/// Plain-text document wrapper for exporting/importing the adventure log.
/// FileDocument/.fileExporter aren't available on tvOS (no user-facing file
/// system) — guarded out there; the export/import menu options themselves
/// are also hidden on tvOS (see showLogExporter's call sites).
#if !os(tvOS)
struct LogFileDocument: FileDocument {
    static var readableContentTypes: [UTType] { [.plainText] }
    var text: String

    init(text: String) {
        self.text = text
    }

    init(configuration: ReadConfiguration) throws {
        guard let data = configuration.file.regularFileContents,
              let string = String(data: data, encoding: .utf8) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        text = string
    }

    func fileWrapper(configuration: WriteConfiguration) throws -> FileWrapper {
        FileWrapper(regularFileWithContents: Data(text.utf8))
    }
}

/// The Atlas's "Save as PDF" export (see GameEngine.showAtlasSaveWarning).
struct PDFFileDocument: FileDocument {
    static var readableContentTypes: [UTType] { [.pdf] }
    var data: Data

    init(data: Data) {
        self.data = data
    }

    init(configuration: ReadConfiguration) throws {
        data = configuration.file.regularFileContents ?? Data()
    }

    func fileWrapper(configuration: WriteConfiguration) throws -> FileWrapper {
        FileWrapper(regularFileWithContents: data)
    }
}
#endif

/// A recently-left screen's full render/interaction state, captured by
/// GameEngine.clearTerminal() and restored by goForwardInHistory() when
/// the player taps the "Fwd >" compact-nav button. Deliberately excludes
/// D-pad corner/direction-pad state (dpad*, directionHandler,
/// chatInputMode) — screens using those are exploration/combat screens,
/// which never qualify for "Fwd >" in the first place since they don't
/// carry a "< Back" (see GameEngine.withForwardOption's gating).
private struct ScreenSnapshot {
    let terminalLines: [TerminalLine]
    let pinnedMapLines: [TerminalLine]
    let menuOptions: [MenuOption]
    let directionExits: [Direction: Bool]
    let securedExits: Set<Direction>
    let menuHandler: ((Int) -> Void)?
    let menuLongPressHandler: ((Int) -> Void)?
    let closeHandler: (() -> Void)?
    let inputHandler: ((String) -> Void)?
    let textLongPressHandler: ((Int) -> Void)?
    let swipeLeftHandler: (() -> Void)?
    let swipeRightHandler: (() -> Void)?
    let swipeRandomHandler: (() -> Void)?
    let rerollHandler: (() -> Void)?
    let undoHandler: (() -> Void)?
    let redoHandler: (() -> Void)?
    let undoLabel: String?
    let redoLabel: String?
    let undoTargetButtonIndex: Int?
    let redoTargetButtonIndex: Int?
    let awaitingTextInput: Bool
    let awaitingContinue: Bool
    let cardPositionLabel: String?
    let dragonGifName: String?
    let menuImageName: String?
    let suppressAutoScroll: Bool
    let scrollLocked: Bool
}

class GameEngine: ObservableObject {
    // MARK: - Published Properties

    /// True if the OS's own screen reader is currently running — VoiceOver,
    /// on both iOS and macOS (same feature, different API). Used both to
    /// pick a sensible first-run default for blinkingCursorEnabled below,
    /// and as a live render-time check in TerminalView — a flashing cursor
    /// actively fights VoiceOver's own focus semantics, so it's suppressed
    /// whenever VoiceOver is actually running right now, regardless of the
    /// toggle (VoiceOver can be turned on well after that toggle was set).
    static var systemVoiceOverRunning: Bool {
        #if os(macOS)
        return NSWorkspace.shared.isVoiceOverEnabled
        #else
        return UIAccessibility.isVoiceOverRunning
        #endif
    }

    /// Screens left via an actual "< Back"/"<<" tap, most recent last — see
    /// ScreenSnapshot. "Fwd >" pops and restores the last entry, undoing
    /// that Back tap. Populated only when justNavigatedBack is true at the
    /// next clearTerminal() (set in handleMenuChoice, only for a tap whose
    /// text is "< Back"/"<<") and wiped by ANY other kind of screen change
    /// (see clearTerminal()) — so "Fwd >" only ever shows up right after
    /// using Back, not as a general "recently visited" cache.
    private var navigationHistory: [ScreenSnapshot] = []
    private static let maxNavigationHistory = 30
    private var justNavigatedBack: Bool = false

    @Published var terminalLines: [TerminalLine] = []
    /// The dungeon map, when one is showing — kept separate from
    /// terminalLines so TerminalView can pin it in its own fixed pane at
    /// the top of the screen instead of it living at the top of the
    /// scrolling text, where enough button rows below could push it (or
    /// scrolling-to-bottom after new text) out of view. See printMap().
    @Published var pinnedMapLines: [TerminalLine] = []
    /// Easter egg: holding the map pane open shows the WHOLE explored floor
    /// (not just the normal radius-limited viewport) in a pannable overlay,
    /// with a Recentre button to snap back to the player's position — like
    /// Google Maps' recentre control.
    @Published var mapOverlayVisible: Bool = false
    @Published var mapOverlayLines: [TerminalLine] = []
    /// The big map drawn as a picture — terrain for each room, names and
    /// little info panels — instead of text (see PictureMapView).
    @Published var pictureMapOn = false
    /// The shared frame that lines the overlay's level up with the others.
    var overlayAtlasFrame: AtlasFrame? {
        let levels = atlasLevels()
        guard levels.indices.contains(atlasLevelIndex) else { return nil }
        return Dungeon.atlasFrames(levels, showAll: atlasShowAllRooms)[atlasLevelIndex]
    }
    var overlayAtlasLevel: AtlasLevel? {
        let levels = atlasLevels()
        return levels.indices.contains(atlasLevelIndex) ? levels[atlasLevelIndex] : nil
    }
    @Published var currentMenuOptions: [MenuOption] = []
    @Published var directionExits: [Direction: Bool] = [:]  // direction -> enabled
    @Published var securedExits: Set<Direction> = []  // directions that are barred
    /// Set to a 1-based menu index to animate a button press (e.g. from voice input)
    @Published var pressedMenuIndex: Int?
    @Published var menuImageName: String? = nil
    /// Name of the dragon GIF to show (nil = hidden)
    @Published var dragonGifName: String? = nil

    /// Display names for the full-screen art/GIF moments (menuImageName/
    /// dragonGifName) — these assets predate this naming pass, so the names
    /// here are simply invented to suit each one; new asset keys should get
    /// an entry added alongside wherever they're first assigned.
    static let poseNames: [String: String] = [
        "DragonGuard": "Warden of the Hall",
        "VictoryScene": "Spoils of Victory",
        "dragon_flapping": "Wings Through the Archive",
    ]

    /// A short flavour blurb per pose caption — tapping the caption (see
    /// TerminalView) shows this instead of the text just sitting there
    /// inert. Every caption gets one so tapping never does nothing.
    private static let poseLore: [String: String] = [
        "Warden of the Hall": "No one remembers who set this dragon to guard the threshold, or what it's meant to keep in — or out. It watches every adventurer who passes, and says nothing.",
        "Spoils of Victory": "Gold, glory, and one very smug dragon. Whatever's still lurking below can wait until the next descent.",
        "Wings Through the Archive": "Somewhere beneath the dungeon's oldest halls, something with wings still keeps its own records.",
    ]

    /// Caption for whichever full-screen art/GIF moment is currently showing.
    var currentPoseCaption: String? {
        if let gif = dragonGifName { return Self.poseNames[gif] }
        if let img = menuImageName { return Self.poseNames[img] }
        return nil
    }

    /// Tapping a pose caption (e.g. "Warden of the Hall" next to the main
    /// menu dragon) shows a short flavour blurb instead of just sitting
    /// there as inert decoration — restores whatever was on screen after.
    func showPoseLore(for caption: String) {
        guard let lore = Self.poseLore[caption] else { return }
        showInlineHelp {
            self.printTitle(caption)
            self.print("")
            self.printWrapped(lore, indent: 2, color: .dimGreen)
            self.print("")
        }
    }
    /// When set, TerminalView prefills the text input field with this value
    @Published var prefillInputText: String? = nil
    @Published var awaitingTextInput: Bool = false
    @Published var awaitingContinue: Bool = false
    /// When true alongside awaitingContinue, the WHOLE screen is tappable to
    /// continue (see TerminalView) — the default for waitForContinue(), since
    /// most "press to continue" screens (NPC results, gym, rest, trap, level
    /// up...) are short, one-shot, and have nothing worth scrolling to
    /// reread; a corner ✕ icon alone made them feel "stuck". Live combat
    /// turns explicitly opt OUT (fullScreenTap: false) and fall back to a
    /// narrow right-edge tap-to-advance strip instead, because full-width
    /// taps there made it impossible to scroll up mid-fight to reread an
    /// earlier round. See waitForContinue(fullScreenTap:).
    @Published var fullScreenTapToContinue: Bool = true
    @Published var chatInputMode: Bool = false
    @Published var isHoldingScreen: Bool = false

    /// Brief dim-then-restore pulse for text content (e.g. re-pressing a help button)
    @Published var textFlashOpacity: CGFloat = 1.0

    /// Indices of title-border lines in terminalLines (for title flash effect)
    var titleLineIndices: Set<Int> = []

    /// When set, TerminalView shows an icon bar (close + optional mic/chat-focus)
    @Published var closeHandler: (() -> Void)?

    /// Accessibility: show mic icon in menu icon bars for voice menu selection
    @Published var voiceMenuEnabled: Bool = (UserDefaults.standard.object(forKey: "voiceMenuEnabled") as? Bool) ?? true

    /// Card navigation style: true = <</>> buttons, false = swipe gesture only
    @Published var useArrowNavigation: Bool = UserDefaults.standard.object(forKey: "useArrowNavigation") == nil ? false : UserDefaults.standard.bool(forKey: "useArrowNavigation")

    /// Suppress auto-scroll-to-bottom (for help/card views where top content matters)
    @Published var suppressAutoScroll: Bool = true
    /// Lock scrolling entirely (for card views with swipe navigation)
    @Published var scrollLocked: Bool = false
    /// Bumped by every clearTerminal() call — i.e. every genuine navigation
    /// to a new screen. TerminalView uses this to tell "brand new screen,
    /// whatever the reader was scrolled to a moment ago is irrelevant" apart
    /// from "same screen, just more content appended" — the latter is the
    /// only case its own recent-manual-scroll guard is meant to protect
    /// (see recentlyScrolledManually there). Without this distinction, an
    /// incidental few points of finger movement during the very tap that
    /// opens a new screen (very easy to trigger on a real touchscreen) could
    /// get read as "the reader just manually scrolled" and suppress that
    /// new screen's scroll-to-top, leaving it showing blank/stale content
    /// until some later, unrelated transition happened to land right.
    @Published private(set) var screenGeneration: Int = 0

    /// Swipe left/right handlers for top-trump card navigation
    var swipeLeftHandler: (() -> Void)?
    var swipeRightHandler: (() -> Void)?
    /// Jump to random card
    var swipeRandomHandler: (() -> Void)?
    /// Card position label e.g. " 3/12"
    @Published var cardPositionLabel: String?

    /// Info screen auto-dismiss delay in seconds (configurable in Gameplay settings)
    @Published var infoTimeout: Double = UserDefaults.standard.object(forKey: "infoTimeout") == nil ? 5.0 : UserDefaults.standard.double(forKey: "infoTimeout")

    /// Whether the DM is currently reading the screen aloud
    @Published var isSpeakingAloud: Bool = false
    /// Persistent speaker mode — stays on until toggled off
    @Published var speakerModeOn: Bool = false
    /// Temporarily paused — stops reading this page but re-engages on next screen change
    @Published var speakerPaused: Bool = false
    /// Tracks whether the current page has already been read aloud (reset on clearTerminal)
    private var speakerHasReadCurrentPage: Bool = false
    private var speakingCheckTimer: Timer?
    private var lastSpeakerTapTime: Date?
    /// Recently spoken text snippets — avoids re-reading repeated NPC greetings etc.
    private var recentlySpokenTexts: [String] = []
    private let maxSpokenMemory = 10

    /// Accessibility: scale multiplier for UI icons (close, mic, return, prompt)
    @Published var iconScaleSetting: Int = UserDefaults.standard.integer(forKey: "iconScaleSetting") // 0=normal, 1=large, 2=extra-large
    /// Adventure log display limit: 0 = all, otherwise show last N entries
    var adventureLogLimit: Int {
        get {
            let val = UserDefaults.standard.object(forKey: "adventureLogLimit")
            return val == nil ? 0 : UserDefaults.standard.integer(forKey: "adventureLogLimit")
        } // 0 = all (default)
        set { UserDefaults.standard.set(newValue, forKey: "adventureLogLimit") }
    }
    var iconScale: CGFloat {
        switch iconScaleSetting {
        case 1: return 1.5
        case 2: return 2.0
        default: return 1.0
        }
    }

    /// Use custom in-app keyboard instead of system keyboard (no globe/mic)
    @Published var useCustomKeyboard: Bool = UserDefaults.standard.object(forKey: "useCustomKeyboard") == nil ? true : UserDefaults.standard.bool(forKey: "useCustomKeyboard")

    /// Idle animation prompts (eye blinks, combat hesitation, save menu
    /// nags, and — see justDMPrompt — idle hints in free-text mode). On
    /// by default as of the version below; see migrateDefaultsForNewVersion.
    @Published var idlePromptsEnabled: Bool = GameEngine.defaultIdlePromptsEnabled()

    /// Auto-Continue — tap-to-continue screens also move on by themselves
    /// once the Info Timeout runs out (see scheduleAutoAdvance). On by
    /// default. autoContinuePaused is session-only: tapping the countdown
    /// bar by the > prompt (or Space on a Mac) holds every countdown.
    @Published var autoContinueEnabled: Bool = UserDefaults.standard.object(forKey: "autoContinueEnabled") == nil ? true : UserDefaults.standard.bool(forKey: "autoContinueEnabled")
    @Published var autoContinuePaused: Bool = false
    /// Accessibility > Animations: Reduced stops flashes, idle blinks, the
    /// pack/hourglass animations, the countdown spin and pulsing buttons.
    /// Until chosen, follows the system's Reduce Motion setting.
    @Published var reduceAnimations: Bool = GameEngine.animationsReduced
    static var animationsReduced: Bool {
        if let chosen = UserDefaults.standard.object(forKey: "reduceAnimations") as? Bool { return chosen }
        #if os(iOS) || os(tvOS)
        return UIAccessibility.isReduceMotionEnabled
        #elseif os(macOS)
        return NSWorkspace.shared.accessibilityDisplayShouldReduceMotion
        #else
        return false
        #endif
    }
    /// Accessibility > Handedness — which side of the text is the free
    /// scrolling edge (the rest is tap-to-continue). Right-handed: scroll
    /// on the right. Left-handed: scroll on the left.
    @Published var leftHanded: Bool = UserDefaults.standard.bool(forKey: "leftHanded")
    /// Accessibility > Auto-Scroll — 0 Off (default), 1 Slow, 2 Medium,
    /// 3 Fast. Pages always open at their top; only with this on does a
    /// long page then glide down by itself.
    @Published var autoScrollSpeed: Int = UserDefaults.standard.integer(forKey: "autoScrollSpeed")
    static let autoScrollSpeedNames = ["Off", "Slow", "Medium", "Fast"]
    var autoScrollLinesPerSecond: Double { [0, 1.5, 3, 6][min(max(autoScrollSpeed, 0), 3)] }
    var autoScrollSpeedName: String { Self.autoScrollSpeedNames[min(max(autoScrollSpeed, 0), 3)] }
    /// Settings > Gameplay > Countdown Icon — the hourglass + ⏸/▶ pause
    /// control by the > prompt. Hiding it doesn't change auto-continue.
    @Published var showCountdownControl: Bool = UserDefaults.standard.object(forKey: "showCountdownControl") == nil ? true : UserDefaults.standard.bool(forKey: "showCountdownControl")

    /// The countdown the input bar's progress line draws: when it ends,
    /// its full length, and — while paused — how much was left.
    @Published var autoCountdownEnd: Date? = nil
    @Published var autoCountdownTotal: Double = 0
    @Published var autoCountdownPausedRemaining: Double? = nil
    private var autoCountdownToken = UUID()

    /// True when screens are actually counting down — i.e. when a pause
    /// control means something.
    var autoContinueCountdownAvailable: Bool { autoContinueEnabled && infoTimeout > 0 && !speakerModeOn }

    /// Long-press on the countdown hourglass: hurry it along — a quarter of
    /// the time left (at least a moment), un-pausing if it was paused.
    func hurryAutoContinue() {
        guard autoCountdownEnd != nil || autoCountdownPausedRemaining != nil else { return }
        let remaining = autoCountdownPausedRemaining ?? autoCountdownEnd.map { max(0, $0.timeIntervalSinceNow) } ?? 0
        autoContinuePaused = false
        pausedForTyping = false
        frozenPendingText = nil
        removeAutoContinuePauseHelp()
        removeFrozenNotice()
        autoCountdownPausedRemaining = nil
        autoCountdownEnd = Date().addingTimeInterval(max(0.6, remaining / 4))
    }

    /// Timeouts page: each kind of timed screen can run quicker or slower
    /// than the Auto-Continue wait — a multiplier, 1 = as it is.
    enum TimeoutKind: String, CaseIterable {
        case reading, fights, loot, search, tales, results
        var label: String {
            switch self {
            case .reading: return "Reading screens"
            case .fights: return "Fights"
            case .loot: return "Loot & pick-ups"
            case .search: return "Search & listen"
            case .tales: return "Tales"
            case .results: return "Victory & defeat"
            }
        }
        var help: String {
            switch self {
            case .reading: return "Most tap-to-continue screens: messages, conversations, results."
            case .fights: return "Each turn in a fight — companions' and monsters' turns, and yours."
            case .loot: return "Who picked up what, after a fight or a find."
            case .search: return "Search, listen and similar quick results."
            case .tales: return "Turning the pages of the Opening and Progress Tales."
            case .results: return "The screens after a battle is won or lost."
            }
        }
    }
    static let timeoutScales: [Double] = [0.5, 0.75, 1.0, 1.5, 2.0, 3.0]
    func timeoutScale(_ kind: TimeoutKind) -> Double {
        let v = UserDefaults.standard.double(forKey: "timeoutScale." + kind.rawValue)
        return v > 0 ? v : 1.0
    }
    static func timeoutScaleLabel(_ v: Double) -> String {
        v == 1 ? "normal" : "×" + String(format: "%g", v) + (v < 1 ? " (quicker)" : " (slower)")
    }
    /// Set just before a timed screen to say what kind it is (used once).
    private var pendingTimeoutKind: TimeoutKind?

    func showTimeoutsSettings(onBack: @escaping () -> Void) {
        clearTerminal()
        printTitle("Timeouts")
        printWrapped("How long timed screens wait before moving on by themselves. Each kind below runs at its own speed on top of the base wait, and every screen still gets time to be read. Tap the hourglass on any screen to pause it.", indent: 2, color: .dimGreen)
        print("")
        print("  Auto-Continue: \(autoContinueEnabled ? "On" : "Off")   Base wait: \(String(format: "%.0fs", infoTimeout))", color: autoContinueEnabled ? .brightGreen : .red)
        print("")
        for k in TimeoutKind.allCases {
            print("  \(k.label): \(Self.timeoutScaleLabel(timeoutScale(k)))", color: .brightGreen)
            printWrapped(k.help, indent: 4, color: .dimGreen)
        }
        print("")
        let kinds = TimeoutKind.allCases
        let options = kinds.map { "\($0.label): \(Self.timeoutScaleLabel(timeoutScale($0)))" } + ["Base Wait", "Reset All"]
        closeHandler = onBack
        showPaginatedMenuOptions(options, pinned: ["< Back"], handler: { [weak self] idx in
            guard let self = self else { return }
            if idx < kinds.count {
                let k = kinds[idx]
                let now = self.timeoutScale(k)
                let next = Self.timeoutScales.first(where: { $0 > now + 0.001 }) ?? Self.timeoutScales[0]
                UserDefaults.standard.set(next, forKey: "timeoutScale." + k.rawValue)
                self.logEvent("\(k.label) timeouts set to \(Self.timeoutScaleLabel(next))", category: "SETTINGS")
                self.showTimeoutsSettings(onBack: onBack)
            } else if idx == kinds.count {
                self.showInfoTimeoutMenu()
            } else {
                for k in kinds { UserDefaults.standard.removeObject(forKey: "timeoutScale." + k.rawValue) }
                self.logEvent("Timeouts reset to normal", category: "SETTINGS")
                self.showTimeoutsSettings(onBack: onBack)
            }
        }, pinnedHandler: { _ in onBack() })
    }

    /// The "Continue?" nudges a waiting screen shows — not story, so Read
    /// Aloud skips them (in a fight it gives a quick cheer instead).
    static let combatContinueTitles = ["Next blow?", "The fight goes on…", "Ready for the next move?", "Steel yourselves…", "What happens next?"]
    static let continueTitles = ["Continue?", "Ready to move on?", "Shall we carry on?", "Onward?", "Seen enough?"]
    static let combatCheers = ["Come on then!", "Jiayou!", "Onward!", "Keep at it!", "Here we go!"]

    /// A countdown never runs out before the screen's text could be read —
    /// about 200 words a minute on top of the Info Timeout (capped, so a
    /// huge page can't park the game for minutes). Busy combat reports and
    /// long DM replies get longer; a short "Nothing found." keeps the base.
    private func countdownDelay(base: Double) -> Double {
        guard base > 0 else { return base }
        let words = terminalLines.reduce(0) { total, line in
            total + line.text.split(separator: " ").filter { $0.contains(where: { $0.isLetter }) }.count
        }
        return max(base, min(25, Double(words) / 3.3))
    }

    /// Text mode: how long after you stop typing it sends — never less than
    /// a few seconds (it used to go after 1.5s, mid-thought).
    var textAutoSubmitDelay: Double { max(4.0, infoTimeout) }

    /// Typing on a counting-down screen pauses it; released again when the
    /// screen moves on (see handleContinue).
    private var pausedForTyping = false
    func pauseAutoContinueForTyping() {
        guard !autoContinuePaused, autoCountdownEnd != nil else { return }
        pausedForTyping = true
        toggleAutoContinuePause()
    }

    // MARK: Continue hints
    //
    // Every tap-to-continue screen says "Continue?" and how, 1.5s in, then
    // again if you're still waiting — up to three times per screen.
    private var continueHintTimer: Timer?
    private var continueHintCount = 0
    private var continueHintGeneration = -1

    private func scheduleContinueHint() {
        continueHintTimer?.invalidate()
        // Part of auto-continue itself (not the Idle Prompts setting): every
        // waiting screen says "Continue?" and how, soon after it appears.
        guard awaitingContinue, !cutsceneActive else { return }
        if continueHintGeneration != screenGeneration {
            continueHintGeneration = screenGeneration
            continueHintCount = 0
        }
        guard continueHintCount < 3 else { return }
        let counting = autoContinueCountdownAvailable && !autoContinuePaused
        let delay: Double = continueHintCount == 0 ? 1.5 : (counting ? max(3, autoCountdownTotal * 0.35) : 5)
        // Only worth saying if there'll still be time to read it before the
        // screen moves on by itself — not on short countdowns.
        if counting, let end = autoCountdownEnd, end.timeIntervalSinceNow - delay < 4 { return }
        continueHintTimer = Timer.scheduledTimer(withTimeInterval: delay, repeats: false) { [weak self] _ in
            guard let self = self, self.awaitingContinue, self.continueHintGeneration == self.screenGeneration else { return }
            if self.timeFrozen {
                // Frozen: no "Continue?" nudges — just how to unfreeze, once.
                if self.frozenNoticeRange == nil || self.frozenNoticeGeneration != self.screenGeneration { self.showFrozenNotice() }
                return
            }
            if self.autoContinueCountdownAvailable && !self.autoContinuePaused,
               let end = self.autoCountdownEnd, end.timeIntervalSinceNow < 4 { return }
            self.continueHintCount += 1
            self.print("")
            if self.currentCombat != nil {
                // In a fight: who's next and how it stands — not just "Continue?".
                let waiting = self.combatWaitingLines()
                self.print("  \(waiting.title)", color: .cyan, bold: true)
                for line in waiting.info { self.printWrapped(line, indent: 4, color: .green) }
                self.printWrapped(self.combatTapLine(), indent: 4, color: .dimGreen)
            } else {
                let title = Self.pickVaried(Self.continueTitles, avoiding: &self.lastContinueTitle)
                self.print("  \(title)", color: .cyan, bold: true)
                self.print("")
                for line in self.continueHintLines() {
                    self.printWrapped(line, indent: 4, color: .dimGreen)
                }
            }
            self.scheduleContinueHint()
        }
    }

    /// While a fight waits: who acts next (and what that means), and how the
    /// fight stands — worded differently each time.
    private func combatWaitingLines() -> (title: String, info: [String]) {
        guard let combat = currentCombat else { return ("", []) }
        var title = Self.combatContinueTitles.randomElement()!
        let order = combat.turnOrder
        if !order.isEmpty {
            var idx = combat.currentTurnIndex
            for _ in 0..<order.count {
                idx = (idx + 1) % order.count
                let entry = order[idx]
                if entry.isPlayer {
                    guard let c = party.first(where: { $0.id == entry.id }), c.isConscious else { continue }
                    let n = shortName(for: c)
                    title = c.isComputerControlled
                        ? ["Next: \(n) takes a turn.", "\(n) is up next.", "Coming up: \(n)'s move.", "\(n) is sizing up the next swing."].randomElement()!
                        : ["Next: your move, \(n).", "\(n), get ready — you're next.", "Your turn is coming, \(n).", "\(n): think about what you'll do next."].randomElement()!
                    break
                } else {
                    guard combat.encounter.monsters.contains(where: { $0.name == entry.name && $0.isAlive }) else { continue }
                    title = ["Next: the \(entry.name) — brace yourselves.", "The \(entry.name) is winding up for its turn.",
                             "Watch out — the \(entry.name) moves next.", "The \(entry.name) is looking for an opening."].randomElement()!
                    break
                }
            }
        }
        var info: [String] = []
        let standing = party.filter { $0.isConscious }.count
        let foes = combat.encounter.monsters.filter { $0.isAlive }
        let foeText = foes.prefix(3).map { "\($0.name) \($0.currentHP)/\($0.maxHP)" }.joined(separator: ", ") + (foes.count > 3 ? "…" : "")
        info.append("Standing: \(standing) of \(party.count) · Foes left: \(foes.count)\(foes.isEmpty ? "" : " (\(foeText))")")
        if let hurt = party.filter({ $0.isConscious && $0.maxHP > 0 && Double($0.currentHP) / Double($0.maxHP) < 0.3 }).first {
            info.append(["\(shortName(for: hurt)) is badly hurt (\(hurt.currentHP)/\(hurt.maxHP) HP).",
                         "Keep an eye on \(shortName(for: hurt)) — only \(hurt.currentHP) HP left."].randomElement()!)
        }
        return (title, info)
    }

    /// "Wait, or tap" — varied; marked as a hint so Read Aloud skips it.
    private func combatTapLine() -> String {
        let counting = autoContinueCountdownAvailable && !autoContinuePaused
        return "• " + (counting
            ? ["Wait a moment, or tap the screen to go on.", "Give it a second — or tap to hurry things along.",
               "It carries on by itself; a tap moves it sooner.", "Hold tight, or tap the screen to press on.",
               "Take a breath — or tap to keep the fight moving."]
            : ["Tap the screen when you're ready.", "Tap to go on — the fight waits for you.",
               "Tap the screen (or type \"go on\") to carry on."]).randomElement()!
    }

    private func continueHintLines() -> [String] {
        if currentCombat != nil && continueHintCount < 2 {
            return [["• Tap the screen to see what happens next", "• Tap the screen — the battle goes on", "• A tap moves the fight along"].randomElement()!,
                    "• or type \"go on\"",
                    autoContinueCountdownAvailable && !autoContinuePaused ? "• or wait — the fight won't wait long" : "• or tap the orange hourglass to let time run again"]
        }
        let tapLine = ["• Tap anywhere on the screen — continue now", "• Tap anywhere on the screen to carry on",
                       "• A tap anywhere on the screen moves things along"].randomElement()!
        // Still waiting after the first hint: "anywhere" deserves the small
        // print — the strip down one edge is kept for scrolling, not taps.
        if continueHintCount >= 2 {
            let side = leftHanded ? "left" : "right"
            return ["When I said anywhere: anywhere on the screen except the buttons, the input line and the narrow strip down the \(side) edge of the text — that's kept for scrolling.",
                    "• or type \"go on\""]
        }
        if autoContinuePaused {
            return [tapLine,
                    "• or type \"go on\"",
                    "• or tap the orange hourglass to let it run again"]
        }
        if autoContinueCountdownAvailable {
            return [tapLine,
                    "• or type \"go on\"",
                    "• or just wait for the hourglass"]
        }
        return ["• Tap anywhere on the screen", "• or type \"go on\""]
    }

    /// Picks a random line, never the same one twice running.
    static func pickVaried(_ options: [String], avoiding last: inout String?) -> String {
        let pool = options.filter { $0 != last }
        let pick = (pool.isEmpty ? options : pool).randomElement()!
        last = pick
        return pick
    }
    private var lastContinueTitle: String?
    private var lastCombatNudge: String?
    private var lastIdleOpener: String?
    private var lastExplorationTip: String?

    private var autoContinueHelpShownGeneration = -1

    /// The "?" beside "paused": a short how-to-carry-on note printed onto
    /// the current screen (once per screen), rather than a help page that
    /// would replace the screen that's waiting.
    private var autoContinueHelpRange: Range<Int>?

    func printAutoContinuePauseHelp() {
        // Tapping ? again takes the note away again.
        if removeAutoContinuePauseHelp() { return }
        autoContinueHelpShownGeneration = screenGeneration
        let start = terminalLines.count
        print("")
        print("  TIME IS FROZEN", color: .yellow, bold: true)
        print("  (orange hourglass = paused)", color: .dimGreen)
        print("")
        printWrapped("While it's orange nothing happens: the DM stays quiet, buttons and taps wait, and anything you type waits until you unfreeze.", indent: 3, color: .green)
        print("")
        print("  To unfreeze:", color: .cyan)
        printWrapped("• Tap the orange hourglass (right of the input line) — time runs on from where it stopped", indent: 3, color: .green)
        printWrapped("• Long-press it — unfreeze and hurry this screen along", indent: 3, color: .green)
        printWrapped("• Type anything, then \"yes\" when asked", indent: 3, color: .green)
        #if os(macOS)
        printWrapped("• Or press Space", indent: 3, color: .green)
        #endif
        print("")
        print("  Why freeze?", color: .cyan)
        printWrapped("To read at your own pace, or step away — nothing moves on, and nobody takes advantage, while you're gone.", indent: 3, color: .green)
        print("")
        print("  Settings now:", color: .cyan)
        printWrapped("Auto-Continue \(autoContinueEnabled ? "On" : "Off") · wait \(Int((infoTimeout * 2).rounded()))s · hourglass \(showCountdownControl ? "On" : "Off")", indent: 3, color: .green)
        printLink("Change Auto-Continue settings", to: "autoContinue", indent: 3)
        autoContinueHelpRange = start..<terminalLines.count
    }

    /// Takes the pause note off this screen if it's showing; true if it did.
    @discardableResult
    private func removeAutoContinuePauseHelp() -> Bool {
        guard let range = autoContinueHelpRange else { return false }
        autoContinueHelpRange = nil
        guard autoContinueHelpShownGeneration == screenGeneration, range.upperBound <= terminalLines.count else { return false }
        terminalLines.removeSubrange(range)
        return true
    }

    // MARK: Time frozen
    //
    // Pausing the hourglass freezes time: nothing happens until it's
    // unfrozen — no "Continue?" nudges from the DM, no combat hesitation,
    // taps and buttons wait, and typing asks to unfreeze first. (A pause
    // that only happened because you started typing isn't a freeze.)
    var timeFrozen: Bool { autoContinuePaused && !pausedForTyping }
    private var frozenNoticeRange: Range<Int>?
    private var frozenNoticeGeneration = -1
    private var frozenPendingText: String?

    /// "Time is frozen" and how to unfreeze — moved to the bottom each
    /// time, so a tap while frozen always shows it in view.
    func showFrozenNotice() {
        removeFrozenNotice()
        let start = terminalLines.count
        print("")
        print("  TIME IS FROZEN", color: .yellow, bold: true)
        #if os(macOS)
        let how = "Click the orange hourglass (right of the input line), or press Space, to unfreeze time."
        #else
        let how = "Tap the orange hourglass (right of the input line) to unfreeze time."
        #endif
        printWrapped("Nothing happens while the hourglass is orange — not even the DM will stir. \(how)", indent: 4, color: .dimGreen)
        frozenNoticeRange = start..<terminalLines.count
        frozenNoticeGeneration = screenGeneration
    }

    @discardableResult
    private func removeFrozenNotice() -> Bool {
        guard let range = frozenNoticeRange else { return false }
        frozenNoticeRange = nil
        guard frozenNoticeGeneration == screenGeneration, range.upperBound <= terminalLines.count else { return false }
        terminalLines.removeSubrange(range)
        return true
    }

    /// Wraps a control's action so it does nothing (but says why) while time is frozen.
    func frozenGuard(_ action: (() -> Void)?) -> (() -> Void)? {
        guard let action = action else { return nil }
        return { [weak self] in
            guard let self = self else { return }
            if self.timeFrozen { self.showFrozenNotice() } else { action() }
        }
    }

    func toggleAutoContinuePause() {
        autoContinuePaused.toggle()
        if !autoContinuePaused { removeAutoContinuePauseHelp() }
        // Freeze / thaw the bar where it is — a pause picks up again from
        // the same point rather than starting the countdown over.
        if autoContinuePaused {
            autoCountdownPausedRemaining = autoCountdownEnd.map { max(0, $0.timeIntervalSinceNow) }
        } else {
            if let remaining = autoCountdownPausedRemaining { autoCountdownEnd = Date().addingTimeInterval(remaining) }
            autoCountdownPausedRemaining = nil
        }
        if autoContinuePaused {
            if !pausedForTyping { showFrozenNotice() }
        } else {
            pausedForTyping = false
            frozenPendingText = nil
            removeFrozenNotice()
            if awaitingContinue { scheduleContinueHint() }
        }
        logEvent(autoContinuePaused ? "Auto-continue paused" : "Auto-continue resumed", category: "SETTINGS")
    }

    /// Runs once per app version bump — applies a NEW default value only
    /// to a setting the user has genuinely never touched (its UserDefaults
    /// key is entirely absent), leaving any explicit choice — including an
    /// explicit "off" — exactly as chosen. Ordinary "add a new setting"
    /// defaults (e.g. useCustomKeyboard above) don't need this: nothing
    /// about their meaning changed, so "unset key = new default" was
    /// always safe. This is specifically for flipping the default of a
    /// setting that ALREADY existed with a different default in an
    /// earlier version — add one line here per future case.
    private static func migrateDefaultsForNewVersion() {
        let currentVersion = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "0"
        // Blinking cursor: off by default for everyone — a one-time switch-off
        // (so installs that had it on from an older default get it off too);
        // after that, the player's own choice in Settings stands.
        if !UserDefaults.standard.bool(forKey: "cursorOffByDefaultApplied") {
            UserDefaults.standard.set(false, forKey: "blinkingCursorEnabled")
            UserDefaults.standard.set(true, forKey: "cursorOffByDefaultApplied")
        }
        let lastMigrated = UserDefaults.standard.string(forKey: "lastMigratedDefaultsVersion")
        guard lastMigrated != currentVersion else { return }

        // v3.1: Idle Prompts (including the new free-text idle hints)
        // default to On going forward — previously Off. Only applies to
        // installs that have never touched this setting at all.
        if UserDefaults.standard.object(forKey: "idlePromptsEnabled") == nil {
            UserDefaults.standard.set(true, forKey: "idlePromptsEnabled")
        }

        UserDefaults.standard.set(currentVersion, forKey: "lastMigratedDefaultsVersion")
    }

    private static func defaultIdlePromptsEnabled() -> Bool {
        migrateDefaultsForNewVersion()
        return UserDefaults.standard.bool(forKey: "idlePromptsEnabled")
    }

    /// Blinking terminal cursor next to the "> " prompt — only while the
    /// game specifically expects the player to act in the text/prompt area
    /// (type something, or tap the text to continue), not for ordinary
    /// menu/D-pad screens where the buttons themselves are the affordance.
    /// On by default.
    // Off by default when VoiceOver is already running the first time this
    // setting is ever read on this device — a blinking cursor is at best
    // useless and at worst distracting for a VoiceOver user, so the
    // friendlier default is off, not on. Purely a first-run default: once
    // UserDefaults has a stored value (the user toggled it, or the app has
    // simply run before), that value always wins, VoiceOver or not.
    @Published var blinkingCursorEnabled: Bool = UserDefaults.standard.object(forKey: "blinkingCursorEnabled") == nil ? false : UserDefaults.standard.bool(forKey: "blinkingCursorEnabled")

    /// True only when the text/prompt area itself is what the player should
    /// act on — typing a response, or tapping to continue. Deliberately
    /// excludes plain menu/D-pad screens (see blinkingCursorEnabled).
    var isWaitingForInput: Bool {
        awaitingTextInput || awaitingContinue
