    // MARK: - Initialization

    init() {
        installGlitchInTheWeaveCrashHandler()
    }

    // MARK: - Glitch in the Weave (crash reporting)

    private static var glitchInTheWeaveCrashURL: URL {
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!
        return docs.appendingPathComponent("GlitchInTheWeave_crash.txt")
    }

    /// Catches uncaught Objective-C-style exceptions and writes what it can
    /// to disk before the process terminates, so the next launch can offer
    /// to export a bug report about it. This deliberately does NOT attempt
    /// to catch every possible crash — a Swift runtime trap (force-unwrap,
    /// array-out-of-bounds, etc.) raises a POSIX signal instead, and a
    /// signal handler has to avoid ordinary Swift/Foundation calls entirely
    /// to be safe, which is its own much larger undertaking. This covers
    /// the Objective-C-exception subset, which is still a real, common
    /// source of crashes (e.g. from UIKit/Foundation APIs).
    private func installGlitchInTheWeaveCrashHandler() {
        NSSetUncaughtExceptionHandler { exception in
            let text = """
            Exception: \(exception.name.rawValue)
            Reason: \(exception.reason ?? "unknown")
            Stack:
            \(exception.callStackSymbols.joined(separator: "\n"))
            """
            try? text.write(to: GameEngine.glitchInTheWeaveCrashURL, atomically: true, encoding: .utf8)
        }
    }

    private static func pendingCrashInfo() -> String? {
        try? String(contentsOf: glitchInTheWeaveCrashURL, encoding: .utf8)
    }

    private func clearPendingCrashReport() {
        try? FileManager.default.removeItem(at: GameEngine.glitchInTheWeaveCrashURL)
    }

    /// Checked once per launch from showMainMenu() — if the app crashed
    /// last time (per the handler above), offer to export a bug report
    /// about it before showing the normal menu. Returns true if it took
    /// over the screen (so showMainMenu shouldn't also render normally).
    private var hasCheckedForCrashThisLaunch = false
    @discardableResult
    private func checkForPendingCrashReport() -> Bool {
        guard !hasCheckedForCrashThisLaunch else { return false }
        hasCheckedForCrashThisLaunch = true
        guard Self.pendingCrashInfo() != nil else { return false }

        clearTerminal()
        printTitle("A Glitch in the Weave")
        print("")
        printWrapped("It looks like the app crashed last time you played. Sorry about that.", indent: 2, color: .yellow)
        print("")
        printWrapped("Exporting a bug report shares what happened (device info, recent log, the crash itself) so it can be fixed — and saves this exact moment so it can be reloaded from Continue Adventure.", indent: 2, color: .dimGreen)
        print("")
        showMenu(["Export Bug Report", "Not Now"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.prepareBugReportExport()
            } else {
                self.clearPendingCrashReport()
            }
            self.showMainMenu()
        }
        return true
    }

    // MARK: - Name Validation

    private let blockedWords: Set<String> = [
        "fuck", "shit", "ass", "damn", "bitch", "bastard", "dick", "cock",
        "pussy", "cunt", "nigger", "nigga", "faggot", "retard", "slut",
        "whore", "piss", "bollocks", "wanker", "twat"
    ]

    /// Reserved words that trigger navigation (go back) and cannot be used as names
    private let reservedWords: Set<String> = ["quit", "back", "exit", "b"]

    private func isReservedWord(_ text: String) -> Bool {
        reservedWords.contains(text.lowercased().trimmingCharacters(in: .whitespaces))
    }

    /// Settings > Gameplay > Auto-Capitalize Names — on by default. Applied
    /// wherever a character's name is finalized (creation, Change Name).
    var autoCapitalizeNames: Bool {
        get {
            if UserDefaults.standard.object(forKey: "auto_capitalize_names") == nil { return true }
            return UserDefaults.standard.bool(forKey: "auto_capitalize_names")
        }
        set { UserDefaults.standard.set(newValue, forKey: "auto_capitalize_names") }
    }

    /// Ensures each word of `name` starts with a capital letter, without
    /// touching anything else about it — so intentional internal caps
    /// (e.g. "McTavish", "O'Brien") survive. No-op when the setting is off.
    private func applyInitialCaps(_ name: String) -> String {
        guard autoCapitalizeNames else { return name }
        return name.split(separator: " ", omittingEmptySubsequences: false).map { word -> String in
            guard let first = word.first else { return String(word) }
            return first.uppercased() + word.dropFirst()
        }.joined(separator: " ")
    }

    private func isNameAppropriate(_ name: String) -> Bool {
        let lower = name.lowercased()
        // Reject reserved navigation words and shortcuts
        if reservedWords.contains(lower) { return false }
        if lower == "a" || lower == "auto" { return false }
        let words = lower.components(separatedBy: .alphanumerics.inverted)
        for word in words {
            if blockedWords.contains(word) { return false }
        }
        // Also check if any blocked word appears as a substring
        for blocked in blockedWords {
            if lower.contains(blocked) { return false }
        }
        return true
    }

    /// Produce short display names for the party that fit on buttons.
    /// Drops " the X" titles, abbreviates to "First L" if needed, keeps full name if short enough.
    func shortNames(maxLen: Int = 12) -> [UUID: String] {
        let chars = party
        var result: [UUID: String] = [:]

        // Phase 1: strip " the ..." suffix
        var candidates: [(Character, String)] = chars.map { char in
            let name = char.name
            if let range = name.range(of: " the ", options: .caseInsensitive) {
                return (char, String(name[name.startIndex..<range.lowerBound]))
            }
            return (char, name)
        }

        // Phase 2: if still too long, abbreviate — keep as much as fits
        candidates = candidates.map { (char, name) in
            if name.count <= maxLen { return (char, name) }
            let words = name.split(separator: " ")
            if words.count >= 2 {
                // Build up "Word1 Word2..." until we exceed maxLen
                var short = String(words[0])
                for w in words.dropFirst() {
                    let candidate = "\(short) \(w)"
                    if candidate.count <= maxLen {
                        short = candidate
                    } else {
                        // Add as much of this word as fits (at least 3 chars)
                        let remaining = maxLen - short.count - 1
                        if remaining >= 3 {
                            short = "\(short) \(w.prefix(remaining))"
                        }
                        break
                    }
                }
                return (char, short)
            }
            return (char, String(name.prefix(maxLen)))
        }

        // Phase 3: ensure uniqueness — append class initial if needed, then
        // fall back to a positional number as an absolute guarantee. Class
        // initial alone can still collide (two same-named party members of
        // the same class would both become e.g. "Bram (Fig)"), and relying
        // solely on the source names already being distinct is fragile —
        // whatever produced them (roster load, manual entry, auto-generate)
        // might not guarantee that in every path. Using `i` (each
        // character's own position) as the last resort makes this function
        // unique by construction no matter what the inputs look like.
        let names = candidates.map { $0.1.lowercased() }
        var usedLower = Set<String>()
        for (i, (char, name)) in candidates.enumerated() {
            let isDuplicate = names.enumerated().contains { $0.offset != i && $0.element == name.lowercased() }
            var candidate = name
            if isDuplicate {
                let classInitial = String(char.characterClass.rawValue.prefix(3))
                candidate = "\(name) (\(classInitial))"
            }
            if usedLower.contains(candidate.lowercased()) {
                candidate = "\(name) #\(i + 1)"
            }
            usedLower.insert(candidate.lowercased())
            result[char.id] = candidate
        }

        return result
    }

    /// Get a short display name for a character in the context of the current party.
    func shortName(for char: Character) -> String {
        let map = shortNames()
        return map[char.id] ?? char.name
    }

    // MARK: - Game Time & Adventure Log

    func formattedGameTime() -> String {
        let day = gameTimeMinutes / 1440 + 1
        let hourOfDay = (gameTimeMinutes % 1440) / 60
        let minute = gameTimeMinutes % 60
        let period = hourOfDay >= 12 ? "PM" : "AM"
        let hour12 = hourOfDay == 0 ? 12 : (hourOfDay > 12 ? hourOfDay - 12 : hourOfDay)
        return "Day \(day), \(hour12):\(String(format: "%02d", minute)) \(period)"
    }

    private func advanceTime(_ minutes: Int) {
        gameTimeMinutes += minutes
        if gameTimeLimit > 0 && gameTimeMinutes >= gameTimeLimit && gameState == .exploring {
            handleTimeLimitExpired()
        }
    }

    func logEvent(_ message: String, category: String? = nil) {
        if !["SYSTEM", "SETTINGS", "DM"].contains(category ?? "") { lastEventThisScreen = message }
        let timestamp = formattedGameTime()
        if let cat = category {
            adventureLog.append("[\(timestamp)] [\(cat)] \(message)")
        } else {
            adventureLog.append("[\(timestamp)] \(message)")
        }
    }

    /// Log a multiplayer action visible to remote players in catch-up
    func logMultiplayerAction(_ description: String) {
        guard isMultiplayer else { return }
        let playerName = GKLocalPlayer.local.displayName
        multiplayerState?.addAction(playerName: playerName, description: description)

        // Debounced background sync — push state to Game Centre so waiting players see live updates
        mpLiveSyncTimer?.invalidate()
        mpLiveSyncTimer = Timer.scheduledTimer(withTimeInterval: 2.0, repeats: false) { [weak self] _ in
            self?.pushLiveMultiplayerSync()
        }
    }

    private var mpLiveSyncTimer: Timer?

    /// Push current state to Game Centre in the background for live spectating
    private func pushLiveMultiplayerSync() {
        guard isMultiplayer, var state = multiplayerState else { return }
        syncMultiplayerState(&state)
        multiplayerState = state
        Task {
            try? await GameCenterManager.shared.saveCurrentTurn(matchState: state)
        }
    }

    // MARK: - Terminal Output

    /// On the Mac the buttons sit to the right of the story, not below it —
    /// so "the buttons below" reads "the buttons to the right" there.
    static func platformWording(_ text: String) -> String {
        #if os(macOS)
        guard text.contains("below") else { return text }
        var t = text.replacingOccurrences(of: #"\b(buttons?|options|choices)\s+below\b"#, with: "$1 to the right", options: .regularExpression)
        t = t.replacingOccurrences(of: "Tap an item below", with: "Tap an item to the right")
        t = t.replacingOccurrences(of: "Load Character below", with: "Load Character to the right")
        return t
        #else
        return text
        #endif
    }

    func print(_ text: String, color: TerminalColor = .green, bold: Bool = false, underlined: Bool = false, size: CGFloat = 14, centered: Bool = false) {
        let text = Self.platformWording(text)
        // runOnMain, not unconditional .async — see its own comment.
        // print() and clearTerminal() used to disagree here: clearTerminal()
        // became synchronous (see runOnMain()) but print() stayed .async, so
        // a synchronous clearTerminal() call could run — and immediately
        // report the array as empty — BEFORE an earlier screen's own
        // still-queued print() appends had landed. A second screen
        // rendered inside the same call chain (e.g. searchRoom() calling
        // forageSupplies(), both of which clearTerminal()+printExplorationMap())
        // would then have its own prints queue up BEHIND the first screen's
        // now-unblocked ones instead of after a real clear, so both screens'
        // content appended together — "the map shows twice."
        runOnMain {
            let line = TerminalLine(text, color: color, bold: bold, underlined: underlined, size: size, centered: centered)
            self.terminalLines.append(line)
            self.queueAnnouncement(line)
        }
    }

    // MARK: VoiceOver announcements
    //
    // New story text is read out as it arrives, even while VoiceOver's focus
    // is down on a button: gathered for a moment, then announced in one go,
    // queued behind whatever VoiceOver is already saying. Not in speaker
    // mode, which reads everything aloud itself.
    private var pendingAnnouncement: [String] = []
    private var announcementTimer: Timer?

    private func queueAnnouncement(_ line: TerminalLine) {
        guard Self.systemVoiceOverRunning, !speakerModeOn, !line.isDecorativeArt else { return }
        let spoken = TerminalLine.spokenText(line.text)
        guard spoken.contains(where: { $0.isLetter || $0.isNumber }) else { return }
        pendingAnnouncement.append(spoken)
        announcementTimer?.invalidate()
        announcementTimer = Timer.scheduledTimer(withTimeInterval: 0.6, repeats: false) { [weak self] _ in
            self?.flushAnnouncement()
        }
    }

    private func flushAnnouncement() {
        guard !pendingAnnouncement.isEmpty else { return }
        var text = pendingAnnouncement.joined(separator: ". ").replacingOccurrences(of: "..", with: ".")
        pendingAnnouncement.removeAll()
        if text.count > 900 { text = String(text.prefix(900)) + "… More on screen." }
        #if os(macOS)
        let element: Any = NSApplication.shared.mainWindow ?? NSApplication.shared
        NSAccessibility.post(element: element, notification: .announcementRequested,
                             userInfo: [.announcement: text, .priority: NSAccessibilityPriorityLevel.high.rawValue])
        #elseif os(iOS)
        UIAccessibility.post(notification: .announcement,
                             argument: NSAttributedString(string: text, attributes: [.accessibilitySpeechQueueAnnouncement: true]))
        #endif
    }

    func printLines(_ lines: [String], color: TerminalColor = .green, size: CGFloat = 14) {
        // Pad all lines to the same width to preserve ASCII art alignment
        let maxLen = lines.map { $0.count }.max() ?? 0
        for line in lines {
            let padded = maxLen > 0 ? line.padding(toLength: maxLen, withPad: " ", startingAt: 0) : line
            print(padded, color: color, size: size)
        }
    }

    /// Like printLines, but for the dungeon map specifically — goes to the
    /// pinned map pane (see pinnedMapLines) instead of the scrolling
    /// terminal text, so it stays on screen regardless of how much text or
    /// how many button rows follow it. Replaces (not appends), since a map
    /// redraw always represents the current room, not a running log.
    func printMap(_ lines: [String], color: TerminalColor = .green, size: CGFloat = 14) {
        // The header (top border, "| MAP" title, separator — always exactly
        // these 3 lines; see getMapDisplay) stays IN the content, same as
        // the legend that follows the grid — both just start scrolled out
        // of view. See TerminalView's initial scroll target (skips past
        // these same 3 lines) and mapOnlyLineCount (panel height, sized to
        // the grid + "@ here: ..." line only, independent of this header).
        let maxLen = lines.map { $0.count }.max() ?? 0
        let mapped = lines.map { line -> TerminalLine in
            let padded = maxLen > 0 ? line.padding(toLength: maxLen, withPad: " ", startingAt: 0) : line
            return TerminalLine(padded, color: color, size: size)
        }
        runOnMain {
            self.pinnedMapLines = mapped
        }
    }

    // MARK: - Atlas (map explorer easter egg)
    //
    // Long-pressing the map pane shows the whole level (the old "big map"
    // easter egg), now with every symbol keyed, you highlighted, and an
    // Explore button into the Atlas proper: stats, every room you've been
    // in (tap one for what you know about it), and every earlier level of
    // the descent. Map Training at a gym unlocks it legitimately from
    // Party Status.

    /// Index into atlasLevels(): earlier (archived) levels first, the level
    /// you're on last.
    @Published var atlasLevelIndex: Int = 0
    /// True while the Atlas's own screen is up — the map overlay's Explore
    /// button is then redundant, and closing the overlay redraws it.
    @Published var atlasScreenActive: Bool = false
    private var atlasOnBack: (() -> Void)?
    @Published var showAtlasPDFExporter: Bool = false
    var pendingAtlasPDF = Data()
    var pendingAtlasPDFName = "atlas"

    /// Settings > Gameplay > World Map — every room, or only those visited.
    var atlasShowAllRooms: Bool {
        get { UserDefaults.standard.bool(forKey: "atlasShowAllRooms") }
        set { UserDefaults.standard.set(newValue, forKey: "atlasShowAllRooms") }
    }

    func atlasLevels() -> [AtlasLevel] {
        guard let dungeon = dungeon else { return [] }
        return dungeon.archivedLevels + [dungeon.atlasLevel(hasTrapSense: partyHasTrapSense)]
    }

    var atlasLevelCount: Int { dungeon.map { $0.archivedLevels.count + 1 } ?? 0 }

    /// Explore only from the exploration screen itself — not mid-combat,
    /// or from a shop/dialogue screen that also shows the map pane.
    var atlasExploreAvailable: Bool {
        atlasScreenActive || (dungeon != nil && currentCombat == nil && !directionExits.isEmpty)
    }

    /// Easter egg triggered by long-pressing the map pane.
    func showExpandedMapOverlay() {
        guard dungeon != nil else { return }
        atlasLevelIndex = max(0, atlasLevelCount - 1)
        presentAtlasMapOverlay()
    }

    private func presentAtlasMapOverlay() {
        let levels = atlasLevels()
        guard levels.indices.contains(atlasLevelIndex) else { return }
        let frame = Dungeon.atlasFrames(levels, showAll: atlasShowAllRooms)[atlasLevelIndex]
        let map = Dungeon.atlasMapLines(levels[atlasLevelIndex], showAll: atlasShowAllRooms, frame: frame)
        // The Whole Deep: rooms you've been to bright, the rest dim.
        let visited = atlasShowAllRooms ? Dungeon.atlasVisitedCells(levels[atlasLevelIndex], frame: frame) : []
        var out: [TerminalLine] = map.lines.enumerated().map { index, text in
            var line = TerminalLine(text, color: atlasShowAllRooms ? .dimGreen : .brightGreen, size: mapFontSize)
            for cell in visited where cell.line == index && cell.column + 3 <= text.count {
                line.extraHighlights.append((cell.column..<(cell.column + 3), .brightGreen))
            }
            if let hl = map.highlight, hl.line == index { line.highlightRange = hl.column..<(hl.column + 3) }
            return line
        }
        out.insert(TerminalLine(atlasShowAllRooms ? "THE WHOLE DEEP — every room on this level" : "THE CHARTED REACHES — where you've been", color: .cyan, size: mapFontSize), at: 0)
        out.append(TerminalLine(" ", size: mapFontSize))
        out += Dungeon.atlasKeyLines().map { TerminalLine($0, color: .dimGreen, size: mapFontSize) }
        mapOverlayLines = out
        mapOverlayVisible = true
    }

    /// The map overlay's Charted/Whole switch — the same setting as
    /// Settings > Gameplay > World Map.
    func setAtlasShowAll(_ all: Bool) {
        atlasShowAllRooms = all
        objectWillChange.send()
        if mapOverlayVisible { presentAtlasMapOverlay() }
    }

    func atlasShowLevel(offset: Int) {
        let count = atlasLevelCount
        guard count > 1 else { return }
        atlasLevelIndex = min(max(0, atlasLevelIndex + offset), count - 1)
        presentAtlasMapOverlay()
    }

    func openAtlasFromOverlay() {
        mapOverlayVisible = false
        if atlasScreenActive, let back = atlasOnBack { showAtlas(onBack: back); return }
        guard atlasExploreAvailable else { return }
        showAtlas(onBack: { [weak self] in self?.showExplorationView() })
    }

    /// Dismiss the full-map overlay (its Close button).
    func recentreMap() {
        mapOverlayVisible = false
        // The overlay may have paged to another level — keep the Atlas
        // screen underneath in step with it.
        if atlasScreenActive, let back = atlasOnBack { showAtlas(onBack: back) }
    }

    func showAtlas(onBack: @escaping () -> Void) {
        let levels = atlasLevels()
        guard !levels.isEmpty else { onBack(); return }
        atlasLevelIndex = min(max(0, atlasLevelIndex), levels.count - 1)
        atlasOnBack = onBack
        atlasScreenActive = true
        let leave: () -> Void = { [weak self] in
            self?.atlasScreenActive = false
            self?.atlasOnBack = nil
            onBack()
        }
        let level = levels[atlasLevelIndex]
        let isCurrent = atlasLevelIndex == levels.count - 1
        let showAll = atlasShowAllRooms

        clearTerminal()
        printTitle("Atlas")
        printWrapped("Level \(level.level): \(level.dungeonName)\(isCurrent ? " — you are here" : "")", indent: 2, color: .cyan, bold: true)
        if levels.count > 1 {
            print("  (\(atlasLevelIndex + 1) of \(levels.count) levels mapped)", color: .dimGreen)
        }
        print("")
        for line in atlasStatsLines(level, showAll: showAll) { printWrapped(line, indent: 2, color: .green) }
        print("")
        printWrapped("Tap a room for what you know about it. View Map shows the whole level.", indent: 2, color: .dimGreen)
        print("")

        let shown = atlasSortedRooms(level, showAll: showAll)
        var entryLineRanges: [Range<Int>] = []
        for room in shown {
            let start = terminalLines.count
            let here = room.id == level.currentRoomId
            let color: TerminalColor = here ? .yellow : (!room.visited ? .dimGreen : (room.danger ? .red : .brightGreen))
            printWrapped(atlasRoomLabel(room, level: level), indent: 2, color: color, bold: here)
            entryLineRanges.append(start..<terminalLines.count)
        }
        if shown.isEmpty { print("  Nothing mapped yet.", color: .dimGreen) }
        print("")

        var options = ["View Map"]
        if atlasLevelIndex > 0 { options.append("< Earlier Level") }
        if atlasLevelIndex < levels.count - 1 { options.append("Later Level >") }
        #if !os(tvOS)
        options.append("Save Map")
        #endif
        showPaginatedMenuOptions(options, pinned: ["?", "< Back"], handler: { [weak self] idx in
            guard let self = self, idx >= 0, idx < options.count else { return }
            switch options[idx] {
            case "View Map": self.presentAtlasMapOverlay()
            case "< Earlier Level": self.atlasLevelIndex -= 1; self.showAtlas(onBack: onBack)
            case "Later Level >": self.atlasLevelIndex += 1; self.showAtlas(onBack: onBack)
            case "Save Map": self.showAtlasSaveWarning(level: level, onBack: onBack)
            default: break
            }
        }, pinnedHandler: { [weak self] choice in
            if choice == 0 { self?.showAtlasHelp() } else { leave() }
        })
        textLongPressHandler = { [weak self] lineIndex in
            guard let idx = entryLineRanges.firstIndex(where: { $0.contains(lineIndex) }), idx < shown.count else { return }
            self?.showAtlasRoom(shown[idx], level: level, onBack: onBack)
        }
        closeHandler = leave
    }

    private func atlasStatsLines(_ level: AtlasLevel, showAll: Bool) -> [String] {
        let visited = level.rooms.filter { $0.visited }
        var lines = ["Rooms explored: \(visited.count)" + (showAll ? " of \(level.rooms.count) known" : "")]
        let slain = visited.reduce(0) { $0 + $1.defeated.count }
        if slain > 0 {
            let rooms = visited.filter { !$0.defeated.isEmpty }.count
            lines.append("Foes defeated: \(slain), in \(rooms) room\(rooms == 1 ? "" : "s")")
        }
        let danger = visited.filter { $0.danger }.count
        lines.append(danger > 0 ? "Still dangerous: \(danger) room\(danger == 1 ? "" : "s") (!)" : "No known dangers left.")
        func tally(_ label: String, _ test: (AtlasRoom) -> Bool) -> String? {
            let n = visited.filter(test).count
            return n > 0 ? "\(n) \(label)\(n == 1 ? "" : "s")" : nil
        }
        let found = [
            tally("merchant") { $0.merchantName != nil },
            tally("gym") { $0.gymName != nil },
            tally("teleport pad") { $0.teleportTo != nil },
            tally("way up or down") { $0.verticalTo != nil },
            tally("room with loot left") { $0.treasureLeft },
        ].compactMap { $0 }
        if !found.isEmpty { lines.append("Found: " + found.joined(separator: ", ")) }
        return lines
    }

    /// Where you are first, then danger, then anything notable, then the rest.
    private func atlasSortedRooms(_ level: AtlasLevel, showAll: Bool) -> [AtlasRoom] {
        func rank(_ r: AtlasRoom) -> Int {
            if r.id == level.currentRoomId || r.id == level.exitRoomId { return 0 }
            if !r.visited { return 5 }
            if r.danger { return 1 }
            if r.merchantName != nil || r.gymName != nil || r.npcName != nil || r.teleportTo != nil || r.verticalTo != nil { return 2 }
            if !r.defeated.isEmpty || r.treasureLeft { return 3 }
            return 4
        }
        return level.rooms.filter { $0.visited || showAll }.sorted { (rank($0), $0.name) < (rank($1), $1.name) }
    }

    private func atlasRoomLabel(_ room: AtlasRoom, level: AtlasLevel) -> String {
        let here = room.id == level.currentRoomId
        let glyph = here ? "@" : (room.visited ? room.symbol : " ")
        var tags: [String] = []
        if here { tags.append("you are here") }
        if room.id == level.exitRoomId { tags.append("you left from here") }
        if !room.visited {
            tags.append("unexplored")
        } else {
            if room.danger { tags.append("danger") }
            if !room.defeated.isEmpty { tags.append("\(room.defeated.count) slain") }
            if room.teleportTo != nil { tags.append("teleport") }
            if let dir = room.verticalDirection { tags.append(dir == "down" ? "way down" : "way up") }
            if room.merchantName != nil { tags.append("merchant") }
            if room.gymName != nil { tags.append("gym") }
            if room.treasureLeft { tags.append("loot") }
        }
        return "[\(glyph)] \(room.name)" + (tags.isEmpty ? "" : " — " + tags.joined(separator: ", "))
    }

    private func showAtlasRoom(_ room: AtlasRoom, level: AtlasLevel, onBack: @escaping () -> Void) {
        let byId = Dictionary(uniqueKeysWithValues: level.rooms.map { ($0.id, $0) })
        let showAll = atlasShowAllRooms
        func place(_ id: Int?) -> String {
            guard let id = id, let other = byId[id] else { return "somewhere unknown" }
            return (other.visited || showAll) ? other.name : "somewhere you haven't been"
        }

        clearTerminal()
        printTitle(String(room.name.prefix(26)))
        print("  Level \(level.level) · \(room.typeName)", color: .dimGreen)
        print("")
        if room.id == level.currentRoomId { print("  You are here.", color: .yellow, bold: true) }
        if room.id == level.exitRoomId { print("  You left this level from here.", color: .yellow) }
        if !room.visited {
            printWrapped("Unexplored. Who knows what waits inside?", indent: 2, color: .dimGreen)
        } else {
            if room.danger {
                printWrapped("Something still lurks here!", indent: 2, color: .red)
            } else if room.cleared {
                print("  Cleared.", color: .green)
            }
            if !room.defeated.isEmpty {
                var counts: [String: Int] = [:]
                for name in room.defeated { counts[name, default: 0] += 1 }
                let text = counts.sorted { $0.key < $1.key }
                    .map { $0.value > 1 ? "\($0.key) ×\($0.value)" : $0.key }
                    .joined(separator: ", ")
                printWrapped("Defeated here: \(text)", indent: 2, color: .green)
            }
            if let merchant = room.merchantName { printWrapped("Merchant: \(merchant)", indent: 2, color: .cyan) }
            if let gym = room.gymName { printWrapped("Gym: \(gym)", indent: 2, color: .cyan) }
            if let npc = room.npcName { printWrapped("Someone here: \(npc)", indent: 2, color: .cyan) }
            if room.teleportTo != nil { printWrapped("Teleport pad → \(place(room.teleportTo))", indent: 2, color: .magenta) }
            if let dir = room.verticalDirection {
                let how = room.verticalMethod == "rope" ? "A rope leads" : "Stairs lead"
                printWrapped("\(how) \(dir) → \(place(room.verticalTo))", indent: 2, color: .magenta)
            }
            if room.treasureLeft { printWrapped("Treasure may still be here.", indent: 2, color: .yellow) }
            if !room.droppedItems.isEmpty {
                printWrapped("You left behind: \(room.droppedItems.joined(separator: ", "))", indent: 2, color: .dimGreen)
            }
            let exits = room.exits.keys.sorted().map { dir -> String in
                room.lockedExits.contains(dir) ? "\(dir) (locked)" : (room.securedExits.contains(dir) ? "\(dir) (barred)" : dir)
            }
            if !exits.isEmpty { printWrapped("Exits: \(exits.joined(separator: ", "))", indent: 2, color: .dimGreen) }
        }
        print("")
        showMenu(["View Map", "< Back"])
        closeHandler = { [weak self] in self?.showAtlas(onBack: onBack) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 { self.presentAtlasMapOverlay() } else { self.showAtlas(onBack: onBack) }
        }
    }

    private func showAtlasHelp() {
        showInlineHelp {
            self.printTitle("Atlas — Help")
            self.print("")
            self.printWrapped("A cartographer's record of everywhere you've set foot, level by level — including the levels above you. Tap a room for what you know about it; View Map (or holding the map pane) shows the whole level, with you in yellow.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  KEY", color: .cyan, bold: true)
            for line in Dungeon.atlasKeyLines().dropFirst() { self.print("  " + line, color: .dimGreen) }
            self.print("")
            self.printWrapped("Only rooms you've visited are shown, unless Settings > Gameplay > World Map is set to All Rooms.", indent: 2, color: .dimGreen)
            self.printLink("Settings > Gameplay", to: "gameplay", indent: 4)
            self.print("")
        }
    }

    /// Saving/printing the map works — but the Guild would rather you didn't.
    /// The big map's printer button: the Atlas's own Save as PDF / Print
    /// screen (with its gentle reminder) for the level on show.
    func saveOrPrintOverlayMap() {
        guard let level = overlayAtlasLevel else { return }
        mapOverlayVisible = false
        showAtlasSaveWarning(level: level, onBack: atlasOnBack ?? { [weak self] in self?.showExplorationView() })
    }

    private func showAtlasSaveWarning(level: AtlasLevel, onBack: @escaping () -> Void) {
        clearTerminal()
        printTitle("Save Map")
        printWrapped("The Cartographers' Guild clears its throat...", indent: 2, color: .yellow)
        print("")
        printWrapped("Saving or printing the map isn't really in the spirit of the game — half the fun is finding your own way (and getting a little lost). But it's your adventure, so you can if you want to.", indent: 2, color: .dimGreen)
        print("")
        var options = ["Save as PDF"]
        #if os(iOS) || os(macOS)
        options.append("Print")
        #endif
        options.append("< Back")
        showMenu(options)
        closeHandler = { [weak self] in self?.showAtlas(onBack: onBack) }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= options.count else { return }
            switch options[choice - 1] {
            case "Save as PDF":
                self.logEvent("Saved the Atlas of Level \(level.level) as a PDF", category: "SYSTEM")
                self.pendingAtlasPDF = self.atlasPDFData(level: level)
                self.pendingAtlasPDFName = "atlas-level\(level.level)-\(Self.saveStamp())"
                self.showAtlas(onBack: onBack)
                self.showAtlasPDFExporter = true
            case "Print":
                self.logEvent("Printed the Atlas of Level \(level.level)", category: "SYSTEM")
                let pdf = self.atlasPDFData(level: level)
                self.showAtlas(onBack: onBack)
                self.printAtlasPDF(pdf)
            default:
                self.showAtlas(onBack: onBack)
            }
        }
    }

    private func atlasPDFData(level: AtlasLevel) -> Data {
        let showAll = atlasShowAllRooms
        var lines = ["\(level.dungeonName) — Level \(level.level)", ""]
        lines += atlasStatsLines(level, showAll: showAll)
        lines.append("")
        lines += Dungeon.atlasMapLines(level, showAll: showAll).lines
        lines.append("")
        lines += Dungeon.atlasKeyLines()
        lines.append("")
        lines.append("ROOMS")
        lines += atlasSortedRooms(level, showAll: showAll).map { String(atlasRoomLabel($0, level: level).prefix(90)) }
        lines.append("")
        lines.append("(Not really in the spirit of the game — but it's your map.)")
        return Self.monospacedPDF(lines: lines)
    }

    /// Plain monospaced text laid out onto US-Letter PDF pages — the font
    /// shrinks (within reason) so the widest line, usually the map, fits.
    static func monospacedPDF(lines: [String]) -> Data {
        let page = CGRect(x: 0, y: 0, width: 612, height: 792)
        let margin: CGFloat = 36
        let data = NSMutableData()
        guard let consumer = CGDataConsumer(data: data as CFMutableData) else { return Data() }
        var mediaBox = page
        guard let context = CGContext(consumer: consumer, mediaBox: &mediaBox, nil) else { return Data() }
        let longest = CGFloat(max(1, lines.map { $0.count }.max() ?? 1))
        let fontSize = min(11, max(5, (page.width - 2 * margin) / (longest * 0.61)))
        let font = CTFontCreateWithName("Menlo" as CFString, fontSize, nil)
        let lineHeight = fontSize * 1.3
        let linesPerPage = max(1, Int((page.height - 2 * margin) / lineHeight))
        var start = 0
        repeat {
            context.beginPDFPage(nil)
            context.textMatrix = .identity
            var y = page.height - margin - fontSize
            for text in lines[start..<min(lines.count, start + linesPerPage)] {
                let attributed = NSAttributedString(string: text, attributes: [NSAttributedString.Key(kCTFontAttributeName as String): font])
                context.textPosition = CGPoint(x: margin, y: y)
                CTLineDraw(CTLineCreateWithAttributedString(attributed), context)
                y -= lineHeight
            }
            context.endPDFPage()
            start += linesPerPage
        } while start < lines.count
        context.closePDF()
        return data as Data
    }

    private func printAtlasPDF(_ data: Data) {
        #if os(iOS)
        let controller = UIPrintInteractionController.shared
        let info = UIPrintInfo(dictionary: nil)
        info.outputType = .grayscale
        info.jobName = "Atlas"
        controller.printInfo = info
        controller.printingItem = data
        controller.present(animated: true)
        #elseif os(macOS)
        if let document = PDFDocument(data: data),
           let operation = document.printOperation(for: NSPrintInfo.shared, scalingMode: .pageScaleToFit, autoRotate: true) {
            operation.run()
        }
        #endif
    }

    /// TerminalView's Atlas .fileExporter completion.
    func handleAtlasExportResult(_ result: Result<URL, Error>) {
        switch result {
        case .success(let url):
            print("  Map saved to \(url.lastPathComponent).", color: .brightGreen)
        case .failure(let error):
            let nsError = error as NSError
            if nsError.domain == NSCocoaErrorDomain && nsError.code == NSUserCancelledError { return }
            print("  Couldn't save the map.", color: .red)
        }
    }

    /// An arcane gym's Incantations lesson: the true words for each of the
    /// character's spells — and what saying them does — learned for good.
    private func teachIncantations(character: Character, trainer: Trainer, room: Room, price: Int) {
        print("")
        guard character.gold >= price else {
            print("  \"The old words aren't cheap, friend. \(price)gp.\"", color: .red)
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
            return
        }
        character.gold -= price
        printWrapped("\(trainer.name) leans close and teaches \(character.name) the true words:", indent: 2, color: .brightGreen)
        for spell in character.knownSpells {
            character.knownIncantations.insert(spell.name)
            printWrapped("• \(spell.name): \"\(Self.trueIncantation(for: spell))!\"", indent: 4, color: .cyan)
        }
        printWrapped("Spoken true, a spell always takes hold — and now and then it surges without spending a slot. The wrong words fizzle, or backfire on the caster. From now on \(character.name) never gets them wrong.", indent: 2, color: .dimGreen)
        logEvent("\(character.name) learned their spell incantations from \(trainer.name)", category: "TRAINING")
        advanceTime(30)
        waitForContinue()
        inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
    }

    /// Map Training (a gym's most expensive lesson) — unlocks the Atlas.
    private func buyMapTraining(character: Character, trainer: Trainer, room: Room, price: Int) {
        print("")
        guard character.gold >= price else {
            print("  \"The cartographer's art isn't cheap, friend. \(price)gp.\"", color: .red)
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
            return
        }
        character.gold -= price
        dungeon?.hasCartography = true
        printWrapped("\(trainer.name) unrolls a sheet of vellum and spends an hour teaching \(character.name) to keep a proper atlas — every room, every passage, level after level.", indent: 2, color: .brightGreen)
        printWrapped("(Party Status now has an Atlas.)", indent: 2, color: .yellow)
        logEvent("\(character.name) paid \(price)gp for Map Training", category: "TRAINING")
        advanceTime(60)
        waitForContinue()
        inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
    }

    /// IDs of characters the local player directly controls
    private var localControlledCharIds: Set<UUID> {
        if isMultiplayer, let state = multiplayerState, let myID = localPlayerID,
           let mySlot = state.players.first(where: { $0.gamePlayerID == myID }) {
            // In multiplayer: only the local player's assigned characters
            var ids = Set(mySlot.controlledCharacterIds)
            if let charId = mySlot.characterId { ids.insert(charId) }
            return ids
        }
        // Single-player: all non-AI characters
        return Set(party.filter { !$0.isComputerControlled }.map { $0.id })
    }

    /// Print combat status with the local player's characters marked with ◀ and underlined
    func printCombatStatus() {
        guard let combat = currentCombat else { return }
        suppressAutoScroll = false

        let localIds = localControlledCharIds
        let lines = combat.displayStatus(localCharacterIds: localIds)
        let maxLen = lines.map { $0.count }.max() ?? 0

        // Party lines start after header (line 0 = "───── COMBAT ─────", line 1 = "")
        let partyLineStart = 2
        for (lineIdx, line) in lines.enumerated() {
            let padded = maxLen > 0 ? line.padding(toLength: maxLen, withPad: " ", startingAt: 0) : line
            let partyIdx = lineIdx - partyLineStart
            let isLocalChar = partyIdx >= 0 && partyIdx < party.count && localIds.contains(party[partyIdx].id)
            print(padded, color: .green, underlined: isLocalChar)
        }
    }

    /// Font size for the map — larger on iPad, a little larger on macOS
    /// too (the window is much roomier than a phone screen — see
    /// bestMapRadius's macOS branch for where most of that extra space
    /// actually goes: a bigger viewport, not a bigger font).
    var mapFontSize: CGFloat {
        #if os(iOS)
        return UIDevice.current.userInterfaceIdiom == .pad ? 20 : 14
        #elseif os(macOS)
        return 16
        #else
        return 14
        #endif
    }

    /// Breadcrumb at the top of each new titled page: the page we came from
    /// and the last notable thing that happened there — e.g.
    /// "↩ from Party Status · Bought a Wedge of Cheddar".
    private var currentScreenTitle: String?
    private var breadcrumbFrom: String?
    private var breadcrumbDid: String?
    private var lastEventThisScreen: String?

    private func printBreadcrumb(for title: String) {
        let from = breadcrumbFrom
        let did = breadcrumbDid
        breadcrumbFrom = nil
        breadcrumbDid = nil
        var parts: [String] = []
        if let from = from, from != title { parts.append("from \(from)") }
        if let did = did { parts.append(did.count > 44 ? String(did.prefix(43)) + "…" : did) }
        guard !parts.isEmpty else { return }
        print("↩ " + parts.joined(separator: " · "), color: .dimGreen)
    }

    func printTitle(_ text: String, color: TerminalColor = .brightGreen) {
        let t = String(text.prefix(30))
        printBreadcrumb(for: t)
        currentScreenTitle = t
        let border = String(repeating: "═", count: t.count + 4)
        titleLineIndices.removeAll()
        let startIdx = terminalLines.count
        print("╔\(border)╗", color: color, bold: true)
        print("║  \(t)  ║", color: color, bold: true)
        print("╚\(border)╝", color: color, bold: true)
        print("")
        for i in startIdx..<terminalLines.count {
            titleLineIndices.insert(i)
        }
        // Help pages open with a word about the quest and what to do next.
        if text.hasSuffix("Help"), let preamble = helpQuestPreamble() {
            printWrapped(preamble, indent: 2, color: .cyan)
            print("")
        }
    }

    /// Flash only the title lines — dim then restore
    func flashTitle() {
        guard !reduceAnimations else { return }
        guard !titleLineIndices.isEmpty else { return }
        let indices = titleLineIndices
        // Save original colors, dim them
        var originals: [(Int, TerminalColor)] = []
        for i in indices where i < terminalLines.count {
            originals.append((i, terminalLines[i].color))
            terminalLines[i].color = .dimGreen
        }
        // Restore after a brief delay
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) { [weak self] in
            guard let self = self else { return }
            for (i, color) in originals where i < self.terminalLines.count {
                self.terminalLines[i].color = color
            }
        }
    }

    func printSubtitle(_ text: String) {
        print("--- \(text) ---", color: .cyan)
        print("")
    }

    /// Shown at the top of every per-character creation screen (race,
    /// class, ability scores, skills, equipment) so a multi-character party
    /// doesn't lose track of which adventurer is currently being built —
    /// chooseCharacterType/the remote-player screen/the name-entry screen
    /// already say this themselves as their own subtitle, so this is only
    /// needed on the screens after that. Silent for a solo party, where
    /// there's nothing to disambiguate.
    private func printCharacterCreationProgress() {
        guard totalCharacters > 1 else { return }
        print("  Character \(creatingCharacterIndex + 1) of \(totalCharacters)", color: .yellow)
        print("")
    }

    /// Word-wrap text to fit within maxWidth characters, with optional indent
    func printWrapped(_ text: String, indent: Int = 0, color: TerminalColor = .green, bold: Bool = false, maxWidth: Int = 38) {
        let text = Self.platformWording(text)
        // Detect any extra leading whitespace in the text and fold it into indent
        let trimmed = text.replacingOccurrences(of: "^\\s+", with: "", options: .regularExpression)
        let effectiveIndent = indent + (text.count - trimmed.count)
        let prefix = String(repeating: " ", count: effectiveIndent)
        let lineWidth = maxWidth - effectiveIndent
        guard lineWidth > 10 else {
            print("\(prefix)\(trimmed)", color: color, bold: bold)
            return
        }

        // Later lines of the paragraph are marked, so Read Aloud reads it as one.
        var printedAny = false
        let emit: (String) -> Void = { line in
            self.print("\(prefix)\(line)", color: color, bold: bold)
            if printedAny {
                self.runOnMain { if !self.terminalLines.isEmpty { self.terminalLines[self.terminalLines.count - 1].continuesPrevious = true } }
            }
            printedAny = true
        }
        let words = trimmed.split(separator: " ", omittingEmptySubsequences: false).map(String.init)
        var currentLine = ""

        for word in words {
            if currentLine.isEmpty {
                currentLine = word
            } else if currentLine.count + 1 + word.count <= lineWidth {
                currentLine += " " + word
            } else {
                emit(currentLine)
                currentLine = word
            }
        }
        if !currentLine.isEmpty {
            emit(currentLine)
        }
    }

    /// Runs a UI-state update immediately if already on the main thread
    /// (true for every call site in this file — all triggered by SwiftUI
    /// button taps), instead of unconditionally deferring via
    /// DispatchQueue.main.async. THE ACTUAL ROOT CAUSE of the
    /// "Accept -> blank screen" saga (finally proven via checkpoint
    /// breadcrumbs inside autoCreateCharacter() itself): menuHandler/
    /// closeHandler are set synchronously and were confirmed correct, but
    /// currentMenuOptions — updated via .async, same as here — read back
    /// as empty (opts:0) at the very moment the function finished, and
    /// still empty a full 3+ seconds later. A .async block queued on a
    /// congested/backed-up main queue can be delayed arbitrarily; a
    /// synchronous update on the thread that's already main can't be.
    private func runOnMain(_ block: @escaping () -> Void) {
        if Thread.isMainThread {
            block()
        } else {
            DispatchQueue.main.async(execute: block)
        }
    }

    /// Runs a D-pad quick action (Search Room, Listen...) whose result is a
    /// timed "read this, then back to exploring" screen. The D-pad is no
    /// longer kept on that screen — a D-pad with no buttons under it read as
    /// broken. The result shows just its text; the full exploration view
    /// (D-pad and buttons) returns when it ends.
    private func runPreservingDirectionExits(_ action: () -> Void) {
        action()
    }

    /// True whenever the compact nav cell's third slot would otherwise be
    /// empty (no `<<`/`>>` pagination in play) and there's a screen to jump
    /// back to — see ScreenSnapshot/navigationHistory.
    private var canShowForwardOption: Bool { !navigationHistory.isEmpty }

    /// Appends a "Fwd >" compact-nav item to `options` when it would
    /// actually land in the otherwise-empty third slot: the screen already
    /// has `< Back`/`<<` (claims slot 0) AND `?` (claims slot 1) — without
    /// both already present, "Fwd >" would get pulled into whichever empty
    /// slot comes first instead of the rightmost one (see TerminalView's
    /// compactNavCell "other" fallback) — and isn't already using `>>`.
    private func withForwardOption(_ options: [MenuOption]) -> [MenuOption] {
        auditCompactNavMiddleSlot(options)
        guard canShowForwardOption else { return options }
        guard !options.contains(where: { $0.text == ">>" }) else { return options }
        guard options.contains(where: { $0.text == "< Back" || $0.text == "<<" }) else { return options }
        guard options.contains(where: { $0.text == "?" || $0.text == "?\u{0338}" }) else { return options }
        return options + [MenuOption("Fwd >", tint: .navigation, compact: true)]
    }

    /// Every 3-bar compact nav cell reserves its middle slot for "?" (help)
    /// first — see compactNavCell(indices:) in TerminalView.swift. That only
    /// holds if "?" is actually one of the compact options whenever there
    /// are 2+ of them; otherwise some other icon (a die, undo/redo, etc.)
    /// silently claims the middle slot. Debug-only tripwire, not a behavior
    /// change — catches a screen missing "?" before it ships.
    #if DEBUG
    private func auditCompactNavMiddleSlot(_ options: [MenuOption]) {
        let compactOptions = options.filter { $0.isCompactNav }
        guard compactOptions.count >= 2 else { return }
        let hasHelp = compactOptions.contains { $0.text == "?" || $0.text == "?\u{0338}" }
        guard !hasHelp else { return }
        let texts = compactOptions.map { $0.text }.joined(separator: ", ")
        assertionFailure("3-bar nav cell has no \"?\" help button — its middle slot will be claimed by another icon instead: [\(texts)]")
    }
    #else
    private func auditCompactNavMiddleSlot(_ options: [MenuOption]) {}
    #endif

    private func captureScreenSnapshot() -> ScreenSnapshot {
        ScreenSnapshot(
            terminalLines: terminalLines,
            pinnedMapLines: pinnedMapLines,
            menuOptions: currentMenuOptions,
            directionExits: directionExits,
            securedExits: securedExits,
            menuHandler: menuHandler,
            menuLongPressHandler: menuLongPressHandler,
            closeHandler: closeHandler,
            inputHandler: inputHandler,
            textLongPressHandler: textLongPressHandler,
            swipeLeftHandler: swipeLeftHandler,
            swipeRightHandler: swipeRightHandler,
            swipeRandomHandler: swipeRandomHandler,
            rerollHandler: rerollHandler,
            undoHandler: undoHandler,
            redoHandler: redoHandler,
            undoLabel: undoLabel,
            redoLabel: redoLabel,
            undoTargetButtonIndex: undoTargetButtonIndex,
            redoTargetButtonIndex: redoTargetButtonIndex,
            awaitingTextInput: awaitingTextInput,
            awaitingContinue: awaitingContinue,
            cardPositionLabel: cardPositionLabel,
            dragonGifName: dragonGifName,
            menuImageName: menuImageName,
            suppressAutoScroll: suppressAutoScroll,
            scrollLocked: scrollLocked
        )
    }

    /// Tapped from "Fwd >" — jumps back to the most recently left screen.
    /// Deliberately does NOT go through clearTerminal()/re-push the screen
    /// being left here, so a return trip via that screen's own native
    /// "< Back" behaves exactly as it always has.
    private func goForwardInHistory() {
        guard let snapshot = navigationHistory.popLast() else { return }
        restoreScreenSnapshot(snapshot)
    }

    private func restoreScreenSnapshot(_ snapshot: ScreenSnapshot) {
        terminalLines = snapshot.terminalLines
        pinnedMapLines = snapshot.pinnedMapLines
        currentMenuOptions = snapshot.menuOptions
        directionExits = snapshot.directionExits
        securedExits = snapshot.securedExits
        menuHandler = snapshot.menuHandler
        menuLongPressHandler = snapshot.menuLongPressHandler
        closeHandler = snapshot.closeHandler
        inputHandler = snapshot.inputHandler
        textLongPressHandler = snapshot.textLongPressHandler
        swipeLeftHandler = snapshot.swipeLeftHandler
        swipeRightHandler = snapshot.swipeRightHandler
        swipeRandomHandler = snapshot.swipeRandomHandler
        rerollHandler = snapshot.rerollHandler
        undoHandler = snapshot.undoHandler
        redoHandler = snapshot.redoHandler
        undoLabel = snapshot.undoLabel
        redoLabel = snapshot.redoLabel
        undoTargetButtonIndex = snapshot.undoTargetButtonIndex
        redoTargetButtonIndex = snapshot.redoTargetButtonIndex
        awaitingTextInput = snapshot.awaitingTextInput
        awaitingContinue = snapshot.awaitingContinue
        cardPositionLabel = snapshot.cardPositionLabel
        dragonGifName = snapshot.dragonGifName
        menuImageName = snapshot.menuImageName
        suppressAutoScroll = snapshot.suppressAutoScroll
        scrollLocked = snapshot.scrollLocked
    }

    // MARK: - In-text links
    //
    // printLink() prints an underlined "→ Settings > Gameplay" line that
    // opens that screen when tapped (TerminalView routes the tap to
    // followLink). The screen it was tapped on is remembered, so that
    // screen's "< Back" / ✕ come straight back to it (returnFromLink)
    // rather than up the linked screen's own menu tree. Followed links are
    // remembered and drawn in the "visited" colour from then on.

    @Published var visitedLinks: Set<String> = Set(UserDefaults.standard.stringArray(forKey: "visitedLinks") ?? [])
    private var linkReturnSnapshot: ScreenSnapshot?
    /// Where the pause note sat on the launching screen, so it can be
    /// redrawn with the current settings on the way back.
    private var pauseHelpRangeAtLink: Range<Int>?

    private func linkTarget(_ key: String) -> (() -> Void)? {
        switch key {
        case "settings": return { [weak self] in self?.showSettings() }
        case "leaveGame": return { [weak self] in self?.leaveExplorationTapped() }
        case "gameplay": return { [weak self] in self?.showGameplaySettings() }
        case "autoContinue": return { [weak self] in self?.showAutoContinueSettingsPage() }
        case "accessibility": return { [weak self] in self?.showAccessibilityMenu() }
        case "infoTimeout": return { [weak self] in self?.showInfoTimeoutMenu() }
        case "timeouts": return { [weak self] in self?.showTimeoutsSettings(onBack: { [weak self] in self?.returnFromLink() }) }
        case "saves": return { [weak self] in self?.showSaveSettings() }
        case "dm": return { [weak self] in self?.showDMSettingsSubMenu() }
        case "ai": return { [weak self] in self?.showAIProviderMenu(onBack: { [weak self] in self?.returnFromLink() }) }
        case "howToPlay": return { [weak self] in self?.showHowToPlay() }
        default: return nil
        }
    }

    /// Opened from the pause note's link. Play is paused, so this is a small
    /// page of just the auto-continue settings — change them, and < Back
    /// (or ✕) returns straight to the paused screen; nowhere else to go.
    private func showAutoContinueSettingsPage() {
        clearTerminal()
        printTitle("Auto-Continue")
        printWrapped("Play is paused while you're here. Change these, then < Back returns you to where you were.", indent: 2, color: .dimGreen)
        print("")
        print("  Auto-Continue: \(autoContinueEnabled ? "On" : "Off")", color: autoContinueEnabled ? .brightGreen : .red)
        printWrapped("Tap-to-continue screens also move on by themselves after the wait below.", indent: 4, color: .dimGreen)
        print("")
        print("  Wait: \(String(format: "%.0fs", infoTimeout)) (about \(Int((infoTimeout * 2).rounded()))s on most screens)", color: .brightGreen)
        printWrapped("Longer screens always get enough time to read them.", indent: 4, color: .dimGreen)
        print("")
        print("  Countdown icon: \(showCountdownControl ? "On" : "Off")", color: showCountdownControl ? .brightGreen : .red)
        printWrapped("The countdown at the right of the input line — tap it to pause, long-press to hurry.", indent: 4, color: .dimGreen)
        print("")
        let waits: [Double] = [2, 3, 5, 8, 10, 15]
        let options = [
            autoContinueEnabled ? "Auto-Continue Off" : "Auto-Continue On",
            "Wait: \(String(format: "%.0fs", infoTimeout))",
            showCountdownControl ? "Countdown Icon Off" : "Countdown Icon On",
            "Timeouts",
        ]
        showPaginatedMenuOptions(options, pinned: ["?", "< Back"], handler: { [weak self] idx in
            guard let self = self else { return }
            switch idx {
            case 0:
                self.recordSettingChange(screen: "s:gameplay", key: "autoContinueEnabled", name: "Auto-Continue")
                self.autoContinueEnabled.toggle()
                UserDefaults.standard.set(self.autoContinueEnabled, forKey: "autoContinueEnabled")
                self.logEvent("Auto-Continue turned \(self.autoContinueEnabled ? "on" : "off")", category: "SETTINGS")
            case 1:
                self.recordSettingChange(screen: "s:gameplay", key: "infoTimeout", name: "Timeout")
                let next = waits.first(where: { $0 > self.infoTimeout + 0.01 }) ?? waits[0]
                self.infoTimeout = next
                UserDefaults.standard.set(next, forKey: "infoTimeout")
                self.logEvent("Auto-Continue wait set to \(Int(next))s", category: "SETTINGS")
            case 2:
                self.recordSettingChange(screen: "s:gameplay", key: "showCountdownControl", name: "Countdown Icon")
                self.showCountdownControl.toggle()
                UserDefaults.standard.set(self.showCountdownControl, forKey: "showCountdownControl")
                self.logEvent("Countdown hourglass turned \(self.showCountdownControl ? "on" : "off")", category: "SETTINGS")
            case 3:
                self.showTimeoutsSettings(onBack: { [weak self] in self?.showAutoContinueSettingsPage() })
                return
            default: break
            }
            self.showAutoContinueSettingsPage()
        }, pinnedHandler: { [weak self] choice in
            guard let self = self else { return }
            if choice == 0 {
                self.showInlineHelp {
                    self.printTitle("Auto-Continue — Help")
                    self.print("")
                    self.printWrapped("Many screens wait for a tap so you can read them. With Auto-Continue on they also move on by themselves after the wait — never before you've had time to read them. The hourglass at the right of the input line shows the time left: tap it to pause (orange = paused), tap again to carry on, long-press to hurry. Typing pauses it too; type 'go on' to continue.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else if !self.returnFromLink() {
                self.showGameplaySettings()
            }
        })
        closeHandler = { [weak self] in
            if self?.returnFromLink() != true { self?.showGameplaySettings() }
        }
    }

    func printLink(_ label: String, to key: String, indent: Int = 2) {
        print(String(repeating: " ", count: indent) + "→ " + label,
              color: visitedLinks.contains(key) ? .magenta : .cyan, underlined: true)
        if !terminalLines.isEmpty { terminalLines[terminalLines.count - 1].link = key }
    }

    func followLink(_ key: String) {
        guard let open = linkTarget(key) else { return }
        visitedLinks.insert(key)
        UserDefaults.standard.set(Array(visitedLinks), forKey: "visitedLinks")
        // A link followed from a linked screen keeps the ORIGINAL return point.
        if linkReturnSnapshot == nil {
            linkReturnSnapshot = captureScreenSnapshot()
            pauseHelpRangeAtLink = autoContinueHelpShownGeneration == screenGeneration ? autoContinueHelpRange : nil
        }
        open()
    }

    /// Back to the screen a link was followed from, if any. True if it did.
    @discardableResult
    func returnFromLink() -> Bool {
        guard let snapshot = linkReturnSnapshot else { return false }
        linkReturnSnapshot = nil
        restoreScreenSnapshot(snapshot)
        terminalLines = terminalLines.map { line in
            var line = line
            if let key = line.link, visitedLinks.contains(key) { line.color = .magenta }
            return line
        }
        if let range = pauseHelpRangeAtLink, range.upperBound <= terminalLines.count {
            // Redraw the pause note so it shows the settings as they are now.
            pauseHelpRangeAtLink = nil
            terminalLines.removeSubrange(range)
            autoContinueHelpRange = nil
            printAutoContinuePauseHelp()
        }
        if snapshot.awaitingContinue { scheduleAutoContinue() }
        return true
    }

    /// The ✕ icon / swipe-back: a linked screen returns to its launch point.
    func invokeClose() {
        if returnFromLink() { return }
        closeHandler?()
    }

    func clearTerminal() {
        taleCountdownOn = false
        speechFromLine = 0
        // Leaving the fight's running account for another screen: keep it, to put back.
        if combatLogShowing {
            combatLogBuffer = terminalLines
            combatLogShowing = false
        }
        pendingAnnouncement.removeAll()   // a new page: only its own text is announced
        breadcrumbFrom = currentScreenTitle
        breadcrumbDid = lastEventThisScreen
        currentScreenTitle = nil
        lastEventThisScreen = nil
        // "Fwd >" is an undo of the "< Back" that's about to happen, not a
        // general "recently visited" cache — only actually useful right
        // after a real Back tap. justNavigatedBack (set in handleMenuChoice,
        // only for a tap on "< Back"/"<<") tells us whether THIS transition
        // is that: if so, cache the screen we're leaving so "Fwd >" can
        // return to it; otherwise this is an ordinary forward move, which
        // invalidates any pending "Fwd >" the same way a browser's forward
        // history clears once you navigate somewhere new after going back.
        if justNavigatedBack {
            if !terminalLines.isEmpty || !currentMenuOptions.isEmpty {
                navigationHistory.append(captureScreenSnapshot())
                if navigationHistory.count > Self.maxNavigationHistory {
                    navigationHistory.removeFirst()
                }
            }
            justNavigatedBack = false
        } else {
            navigationHistory.removeAll()
        }
        // Bumped once per call, captured by each watchdog below as
        // myGeneration. THE REAL BUG (found after extensive investigation
        // into the "Accept -> blank screen" reports): a watchdog only ever
        // checked "is the menu empty right now" — with no way to tell "the
        // specific screen I was watching never recovered" apart from "some
        // completely different, much LATER screen just happens to be
        // mid-transition (its own clearTerminal() ran a moment ago, about
        // to set up its own valid menu) at the exact instant I woke up to
        // check." An old watchdog from an earlier, already-abandoned screen
        // (e.g. a much earlier menu tap, long superseded by many legitimate
        // screen transitions since) could fire during a completely
        // unrelated, perfectly fine later screen and wrongly kill it —
        // exactly what the breadcrumb history showed once armedAt was
        // captured: watchdogs firing minutes after screens that had nothing
        // to do with what was currently on screen. Comparing generations
        // makes a watchdog stand down the instant anything newer has
        // started, instead of judging a screen it was never watching.
        clearTerminalGeneration += 1
        screenGeneration += 1
        stopIdleAnimations()
        stopMenuAnimation()
        SpeechEngine.shared.stop()
        textLongPressHandler = nil
        closeHandler = nil
        rerollHandler = nil
        // Reset menuHandler too — every legitimate screen sets its own right
        // after printing content, so this never matters in normal flow. It
        // matters if some future guard-return happens between clearTerminal()
        // and that setup: the screen would otherwise show blank/stale
        // content with the PREVIOUS screen's menuHandler still wired to
        // whatever buttons happen to be on screen — silently misdirecting
        // taps instead of failing safely. handleMenuChoice's fallback
        // recovers from the nil case instead.
        menuHandler = nil
        lastSafeRebuildAction = nil
        awaitingTextInput = false
        awaitingContinue = false
        fullScreenTapToContinue = false
        suppressAutoScroll = true
        scrollLocked = false
        swipeLeftHandler = nil
        swipeRightHandler = nil
        swipeRandomHandler = nil
        cardPositionLabel = nil
        menuImageName = nil
        dragonGifName = nil
        speakerHasReadCurrentPage = false
        // Clear undo/redo handlers so they don't leak to the next screen
        undoHandler = nil
        redoHandler = nil
        undoLabel = nil
        redoLabel = nil
        undoTargetButtonIndex = nil
        redoTargetButtonIndex = nil
        undoRedoFeedback = nil
        runOnMain {
            self.terminalLines.removeAll()
            self.pinnedMapLines.removeAll()
            // Same reasoning as menuHandler above: if a guard-return ever
            // happens between clearTerminal() and a screen's own showMenu
            // call, this stops the PREVIOUS screen's buttons (now bound to
            // a nil menuHandler) from lingering visibly over blank content
            // — e.g. tapping a stale "Accept"/"Reroll" from the last screen
            // and landing on nothing. Every legitimate screen sets its own
            // options right after printing content, so this never matters
            // in normal flow.
            self.currentMenuOptions = []
        }

        // Watchdog: catches the case the two fixes above don't — a
        // guard-return between clearTerminal() and a screen's own setup now
        // leaves a genuinely blank, buttonless screen (see above) instead of
        // stale buttons, but a buttonless screen means handleMenuChoice's
        // own orphan recovery never gets a tap to react to. If nothing has
        // rendered a real screen shortly after this clear, self-heal instead
        // of leaving the player stuck looking at nothing. Combat is excluded
        // — its animation/timer sequencing legitimately spans longer gaps
        // with no menu on screen.
        //
        // 8s: back up from a 3s stopgap. That was fine while a persistent
        // recurrence still fell through to the visible error screen after
        // 3 retries, but recoverFromOrphanedScreen()'s character-creation
        // path is now uncapped (see its own comment) — a real dead end
        // always recovers eventually no matter the timeout, so there's no
        // downside to widening it, and it gives more breathing room to
        // actually read a screen and tap before a silent rebuild interrupts.
        let armedBreadcrumb = lastCharCreationBreadcrumb
        let myGeneration = clearTerminalGeneration
        DispatchQueue.main.asyncAfter(deadline: .now() + 8.0) { [weak self] in
            guard let self = self else { return }
            // Stand down if any newer clearTerminal() has happened since —
            // the screen this watchdog was armed for has already been
            // superseded by something else; it's not this watchdog's place
            // to judge whatever's on screen now.
            guard self.clearTerminalGeneration == myGeneration else { return }
            // Judge purely on what's actually visible/tappable — currentMenuOptions
            // and directionExits both empty means there is nothing on screen the
            // player could press, full stop. Previously this also required
            // menuHandler/closeHandler == nil, but a stale (non-nil) handler left
            // over from an earlier screen is just as dead as no handler at all if
            // there's no button wired to invoke it — that combination stood the
            // watchdog down and left the control box permanently invisible instead
            // of self-healing, since with zero buttons handleMenuChoice's own
            // orphan-tap recovery never gets a tap to react to either.
            guard self.currentMenuOptions.isEmpty, self.directionExits.isEmpty,
                  !self.awaitingTextInput, !self.awaitingContinue,
                  self.gameState != .combat else { return }
            // Diagnostic: this watchdog's own full state at fire time, plus
            // what the breadcrumb was when THIS PARTICULAR watchdog was
            // armed (as opposed to whatever ran most recently) — with
            // multiple clearTerminal() calls in a chain, multiple watchdogs
            // stack up, and it matters which one actually fired.
            self.setBreadcrumb("WATCHDOG(armedAt:\(armedBreadcrumb)) opts:\(self.currentMenuOptions.count) menuH:\(self.menuHandler != nil) closeH:\(self.closeHandler != nil) awaitText:\(self.awaitingTextInput) awaitCont:\(self.awaitingContinue) state:\(self.gameState)")
            self.recoverFromOrphanedScreen()
        }
    }

    // MARK: - Screen-Scoped Undo/Redo

    /// Push a snapshot onto the undo stack for a given screen
    private func pushScreenUndo(screen: String, data: Data) {
        screenUndoStacks[screen, default: []].append(data)
        screenRedoStacks[screen] = []
    }

    private func popScreenUndo(screen: String) -> Data? {
        screenUndoStacks[screen]?.popLast()
    }

    private func popScreenRedo(screen: String) -> Data? {
        screenRedoStacks[screen]?.popLast()
    }

    private func pushScreenRedo(screen: String, data: Data) {
        screenRedoStacks[screen, default: []].append(data)
    }

    private func clearUndoRedo(for screen: String) {
        screenUndoStacks.removeValue(forKey: screen)
        screenRedoStacks.removeValue(forKey: screen)
    }

    private func clearAllUndoRedo() {
        screenUndoStacks.removeAll()
        screenRedoStacks.removeAll()
        settingUndoStacks.removeAll()
        settingRedoStacks.removeAll()
        currentUndoScreen = nil
        undoHandler = nil
        redoHandler = nil
        undoLabel = nil
        redoLabel = nil
        undoTargetButtonIndex = nil
        redoTargetButtonIndex = nil
        undoRedoFeedback = nil
    }

    private func screenHasUndo(_ screen: String) -> Bool {
        !(screenUndoStacks[screen]?.isEmpty ?? true)
    }

    private func screenHasRedo(_ screen: String) -> Bool {
        !(screenRedoStacks[screen]?.isEmpty ?? true)
    }

    // MARK: - Undo/Redo Feedback

    /// Show undo feedback — persists until next action replaces it
    private func showUndoFeedback(_ message: String) {
        undoRedoFeedback = "↩ \(message)"
    }

    /// Show redo feedback — persists until next action replaces it
    private func showRedoFeedback(_ message: String) {
        undoRedoFeedback = "↪ \(message)"
    }

    // MARK: - Undo/Redo Preview Labels

    /// Peek at the undo stack and describe what undoing would revert
    private func peekUndoLabel() -> String? {
        guard let screen = currentUndoScreen else { return nil }
        guard let data = screenUndoStacks[screen]?.last else { return nil }

        if screen.hasPrefix("editChar:") {
            guard let index = editingCharacterIndex, index < party.count else { return "Undo" }
            if let saved = try? JSONDecoder().decode(Character.self, from: data) {
                let diff = describeCharDiff(before: charSnapshot(party[index]), after: charSnapshot(saved))
                return "Undo:\(diff.name)"
            }
        } else if screen == "partyReview" {
            return "Undo:Party"
        } else if screen == skillsScreenKey {
            if let rawValues = try? JSONDecoder().decode([String].self, from: data) {
                let count = rawValues.count
                let current = selectedSkills.count
                if count < current {
                    let removed = selectedSkills.filter { !rawValues.contains($0.rawValue) }
                    if let skill = removed.first { return "Undo:\(skill.rawValue)" }
                }
                return "Undo:Skill"
            }
        }
        return "Undo"
    }

    /// Peek at the redo stack and describe what redoing would restore
    private func peekRedoLabel() -> String? {
        guard let screen = currentUndoScreen else { return nil }
        guard let data = screenRedoStacks[screen]?.last else { return nil }

        if screen.hasPrefix("editChar:") {
            if let saved = try? JSONDecoder().decode(Character.self, from: data) {
                guard let index = editingCharacterIndex, index < party.count else { return "Redo" }
                let diff = describeCharDiff(before: charSnapshot(party[index]), after: charSnapshot(saved))
                return "Redo:\(diff.name)"
            }
        } else if screen == "partyReview" {
            return "Redo:Party"
        } else if screen == skillsScreenKey {
            return "Redo:Skill"
        }
        return "Redo"
    }

    /// Update the preview labels and target button indices based on current stack state
    private func refreshUndoRedoLabels() {
        undoLabel = undoHandler != nil ? peekUndoLabel() : nil
        redoLabel = redoHandler != nil ? peekRedoLabel() : nil
        undoTargetButtonIndex = undoLabel != nil ? targetButtonIndex(for: undoLabel!) : nil
        redoTargetButtonIndex = redoLabel != nil ? targetButtonIndex(for: redoLabel!) : nil
    }

    /// Map a diff label (e.g. "Undo:Music") to the 1-based menu button index on the current screen
    private func targetButtonIndex(for label: String) -> Int? {
        guard let screen = currentUndoScreen else { return nil }
        let short = label.replacingOccurrences(of: "Undo:", with: "")
                         .replacingOccurrences(of: "Redo:", with: "")

        if screen == "s:main" {
            // Settings buttons: 1=DM Settings, 2=Accessibility, 3=Mood, 4=Gameplay, 5=Saving
            let dmKeys = ["DM Provider", "DM Creativity", "DM Log Context"]
            let accessKeys = ["Display Size", "DM Voice", "Companion Voices", "Voice Menus", "Hit Animations"]
            let moodKeys = ["Music", "Sound FX", "Menu Tune", "Explore Tune", "Combat Tune", "Chat Tune"]
            let gameKeys = ["Button Limit", "Card Navigation", "Map Length", "NPCs", "Multiplayer",
                           "Long Press", "Info Timeout", "Time Limit", "Log Limit", "Undo/Redo",
                           "Idle"]
            let saveKeys = ["Autosave"]

            // Return 0-based index matching the options array
            if dmKeys.contains(short) { return 0 }
            if accessKeys.contains(short) { return 1 }
            if moodKeys.contains(short) { return 2 }
            if gameKeys.contains(short) { return 3 }
            if saveKeys.contains(short) { return 4 }
            return nil
        }

        // Character edit and other screens: no button highlighting for now
        return nil
    }

    /// Structured diff result for undo/redo display
    private struct DiffInfo {
        let name: String   // Short name for button label (e.g. "Hits", "STR")
        let from: String   // Value before (e.g. "On", "14")
        let to: String     // Value after (e.g. "Off", "16")

        /// For feedback text: "Hits: On → Off"
        var feedback: String { "\(name): \(from) → \(to)" }
    }

    /// Describe a character diff for undo/redo feedback
    private func describeCharDiff(before: (name: String, cls: String, race: String, scores: AbilityScores, hp: Int, maxHP: Int),
                                  after: (name: String, cls: String, race: String, scores: AbilityScores, hp: Int, maxHP: Int)) -> DiffInfo {
        if before.name != after.name { return DiffInfo(name: "Name", from: before.name, to: after.name) }
        if before.cls != after.cls { return DiffInfo(name: "Class", from: before.cls, to: after.cls) }
        if before.race != after.race { return DiffInfo(name: "Race", from: before.race, to: after.race) }
        let bs = before.scores; let as_ = after.scores
        if bs.strength != as_.strength { return DiffInfo(name: "STR", from: "\(bs.strength)", to: "\(as_.strength)") }
        if bs.dexterity != as_.dexterity { return DiffInfo(name: "DEX", from: "\(bs.dexterity)", to: "\(as_.dexterity)") }
        if bs.constitution != as_.constitution { return DiffInfo(name: "CON", from: "\(bs.constitution)", to: "\(as_.constitution)") }
        if bs.intelligence != as_.intelligence { return DiffInfo(name: "INT", from: "\(bs.intelligence)", to: "\(as_.intelligence)") }
        if bs.wisdom != as_.wisdom { return DiffInfo(name: "WIS", from: "\(bs.wisdom)", to: "\(as_.wisdom)") }
        if bs.charisma != as_.charisma { return DiffInfo(name: "CHA", from: "\(bs.charisma)", to: "\(as_.charisma)") }
        if before.hp != after.hp || before.maxHP != after.maxHP {
            return DiffInfo(name: "HP", from: "\(before.hp)/\(before.maxHP)", to: "\(after.hp)/\(after.maxHP)")
        }
        return DiffInfo(name: after.name, from: "", to: "")
    }

    private func charSnapshot(_ c: Character) -> (name: String, cls: String, race: String, scores: AbilityScores, hp: Int, maxHP: Int) {
        (c.name, c.characterClass.rawValue, c.race.rawValue, c.abilityScores, c.currentHP, c.maxHP)
    }

    /// Describe a settings diff for undo/redo feedback
    private func describeSettingsDiff(before: [String: Any], after: [String: Any]) -> DiffInfo {
        let labels: [(String, String, ((Any) -> String)?)] = [
            ("musicEnabled", "Music", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("music_enabled", "Music", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("battle_sounds_enabled", "Sound FX", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("hit_animations", "Hits", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("voiceMenuEnabled", "Voice Menus", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("speechEnabled", "DM Voice", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("fontSizeSetting", "Size", { v in
                switch v as? String ?? "" {
                case "small": return "Small"
                case "large": return "Large"
                default: return "Medium"
                }
            }),
            ("maxButtonsPerScreen", "Buttons", { "\($0)" }),
            ("npcs_enabled", "NPCs", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("multiplayer_enabled", "Multi", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("useArrowNavigation", "Cards", { ($0 as? Bool) == true ? "Buttons" : "Swipe" }),
            ("undoRedoEnabled", "Undo/Redo", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("autosave_interval", "Autosave", { "\($0)s" }),
            ("map_radius", "Map", { "\($0)" }),
            ("dmProvider", "Provider", nil),
            ("dmAdLibLevel", "Ad-lib", { "\($0)" }),
            ("dmLogContextSize", "Log", { "\($0)" }),
            ("infoTimeout", "Timeout", { v in
                let d = v as? Double ?? 0
                return d == 0 ? "Off" : String(format: "%.1fs", d)
            }),
            ("autoContinueEnabled", "Auto-Continue", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("showCountdownControl", "Countdown Icon", { ($0 as? Bool) == true ? "On" : "Off" }),
            ("autoScrollSpeed", "Auto-Scroll", { v in GameEngine.autoScrollSpeedNames[min(max((v as? Int) ?? 0, 0), 3)] }),
            ("longPressDuration", "LongPress", { v in
                let d = v as? Double ?? 0.5
                return String(format: "%.1fs", d)
            }),
            ("menu_melody", "Menu Tune", nil),
            ("exploration_melody", "Explore Tune", nil),
            ("combat_melody", "Combat Tune", nil),
            ("chat_melody", "Chat Tune", nil),
            ("gameTimeLimit", "Timer", { v in
                let i = v as? Int ?? 0
                return i == 0 ? "Off" : "\(i) min"
            }),
            ("adventureLogLimit", "Log Limit", { v in
                let i = v as? Int ?? 0
                return i == 0 ? "All" : "\(i)"
            }),
            ("companionVoiceMode", "Voices", nil),
        ]
        for (key, label, formatter) in labels {
            let oldVal = before[key]
            let newVal = after[key]
            if !settingsValuesEqual(oldVal, newVal) {
                let fmt = formatter ?? { "\($0)" }
                let fromStr = oldVal.map { fmt($0) } ?? "—"
                let toStr = newVal.map { fmt($0) } ?? "—"
                return DiffInfo(name: label, from: fromStr, to: toStr)
            }
        }
        return DiffInfo(name: "Settings", from: "", to: "")
    }

    private func settingsValuesEqual(_ a: Any?, _ b: Any?) -> Bool {
        if a == nil && b == nil { return true }
        guard let a = a, let b = b else { return false }
        if let a = a as? Bool, let b = b as? Bool { return a == b }
        if let a = a as? Int, let b = b as? Int { return a == b }
        if let a = a as? Double, let b = b as? Double { return a == b }
        if let a = a as? String, let b = b as? String { return a == b }
        return "\(a)" == "\(b)"
    }

    // MARK: - Edit Undo/Redo

    private func editScreenKey(for index: Int) -> String { "editChar:\(index)" }

    /// Begin tracking edits for a character — fresh stacks each visit
    private func beginEditTracking(index: Int, inGame: Bool = true) {
        editingCharacterIndex = index
        editScreenIsInGame = inGame
        let key = editScreenKey(for: index)
        currentUndoScreen = key
        clearUndoRedo(for: key)
        updateUndoRedoHandlers(index: index)
    }

    /// End edit tracking
    private func endEditTracking() {
        if let index = editingCharacterIndex {
            clearUndoRedo(for: editScreenKey(for: index))
        }
        editingCharacterIndex = nil
        currentUndoScreen = nil
        undoHandler = nil
        redoHandler = nil
        undoLabel = nil
        redoLabel = nil
        undoTargetButtonIndex = nil
        redoTargetButtonIndex = nil
        undoRedoFeedback = nil
    }

    /// Push a snapshot before making changes
    private func pushEditSnapshot(index: Int) {
        guard index < party.count else { return }
        let key = editScreenKey(for: index)
        if let data = try? JSONEncoder().encode(party[index]) {
            pushScreenUndo(screen: key, data: data)
        }
        updateUndoRedoHandlers(index: index)
    }

    private func undoEdit() {
        guard let index = editingCharacterIndex, index < party.count else { return }
        let key = editScreenKey(for: index)
        guard let data = popScreenUndo(screen: key) else { return }
        let before = party[index]
        if let currentData = try? JSONEncoder().encode(before) {
            pushScreenRedo(screen: key, data: currentData)
        }
        if let restored = try? JSONDecoder().decode(Character.self, from: data) {
            party[index] = restored
            showUndoFeedback(describeCharDiff(before: charSnapshot(before), after: charSnapshot(restored)).feedback)
        }
        updateUndoRedoHandlers(index: index)
        if editScreenIsInGame {
            showInGameEditCharacter(index: index)
        } else {
            showEditCharacter(index: index)
        }
    }

    private func redoEdit() {
        guard let index = editingCharacterIndex, index < party.count else { return }
        let key = editScreenKey(for: index)
        guard let data = popScreenRedo(screen: key) else { return }
        let before = party[index]
        if let currentData = try? JSONEncoder().encode(before) {
            pushScreenUndo(screen: key, data: currentData)
        }
        if let restored = try? JSONDecoder().decode(Character.self, from: data) {
            party[index] = restored
            showRedoFeedback(describeCharDiff(before: charSnapshot(before), after: charSnapshot(restored)).feedback)
        }
        updateUndoRedoHandlers(index: index)
        if editScreenIsInGame {
            showInGameEditCharacter(index: index)
        } else {
            showEditCharacter(index: index)
        }
    }

    private func updateUndoRedoHandlers(index: Int) {
        guard undoRedoEnabled else {
            undoHandler = nil
            redoHandler = nil
            undoLabel = nil
            redoLabel = nil
            return
        }
        let key = editScreenKey(for: index)
        undoHandler = screenHasUndo(key) ? { [weak self] in self?.undoEdit() } : nil

        // Only show redo if it would actually change something
        var showRedo = false
        if screenHasRedo(key), index < party.count,
           let redoData = screenRedoStacks[key]?.last,
           let currentData = try? JSONEncoder().encode(party[index]) {
            showRedo = redoData != currentData
        }
        redoHandler = showRedo ? { [weak self] in self?.redoEdit() } : nil
        refreshUndoRedoLabels()
    }

    // MARK: - Per-Setting Undo/Redo

    /// A single setting change for per-screen undo/redo
    private struct SettingUndoEntry {
        let key: String      // UserDefaults key or special identifier
        let name: String     // Short display name (e.g. "Hits")
        let oldValue: Any?   // Value before the change
    }

    /// Per-screen undo/redo stacks for individual setting changes
    private var settingUndoStacks: [String: [SettingUndoEntry]] = [:]
    private var settingRedoStacks: [String: [SettingUndoEntry]] = [:]

    /// Record a setting's current value before changing it
    private func recordSettingChange(screen: String, key: String, name: String) {
        let oldValue = readSettingRaw(key: key)
        settingUndoStacks[screen, default: []].append(
            SettingUndoEntry(key: key, name: name, oldValue: oldValue)
        )
        settingRedoStacks[screen] = []  // New action clears redo
    }

    /// Read the raw value of a setting (handles special keys)
    /// Compare two setting values for equality (both may be nil or different types)
    private func settingValuesEqual(_ a: Any?, _ b: Any?) -> Bool {
        switch (a, b) {
        case (nil, nil): return true
        case (nil, _), (_, nil): return false
        case (let a as Bool, let b as Bool): return a == b
        case (let a as Int, let b as Int): return a == b
        case (let a as Double, let b as Double): return a == b
        case (let a as String, let b as String): return a == b
        default: return String(describing: a) == String(describing: b)
        }
    }

    private func readSettingRaw(key: String) -> Any? {
        switch key {
        case "dmAdLibLevel": return DMEngine.shared.adLibLevel.rawValue
        case "speechEnabled": return SpeechEngine.shared.isEnabled
        default: return UserDefaults.standard.object(forKey: key)
        }
    }

    /// Write a setting value and sync runtime state
    private func writeSettingRaw(key: String, value: Any?) {
        switch key {
        case "dmAdLibLevel":
            if let raw = value as? Int {
                DMEngine.shared.adLibLevel = DMAdLibLevel(rawValue: raw) ?? .full
            }
        case "speechEnabled":
            if let on = value as? Bool { SpeechEngine.shared.isEnabled = on }
        default:
            if let v = value { UserDefaults.standard.set(v, forKey: key) }
            else { UserDefaults.standard.removeObject(forKey: key) }
        }
        syncSingleSetting(key: key)
    }

    /// Sync @Published / runtime state for one setting key
    private func syncSingleSetting(key: String) {
        switch key {
        case "voiceMenuEnabled":
            voiceMenuEnabled = UserDefaults.standard.bool(forKey: key)
        case "useArrowNavigation":
            useArrowNavigation = UserDefaults.standard.bool(forKey: key)
        case "infoTimeout":
            infoTimeout = UserDefaults.standard.double(forKey: key)
        case "autoContinueEnabled":
            autoContinueEnabled = UserDefaults.standard.object(forKey: key) == nil ? true : UserDefaults.standard.bool(forKey: key)
        case "autoScrollSpeed":
            autoScrollSpeed = UserDefaults.standard.integer(forKey: key)
        case "leftHanded":
            leftHanded = UserDefaults.standard.bool(forKey: key)
        case "reduceAnimations":
            reduceAnimations = GameEngine.animationsReduced
        case "showCountdownControl":
            showCountdownControl = UserDefaults.standard.object(forKey: key) == nil ? true : UserDefaults.standard.bool(forKey: key)
        case "iconScaleSetting":
            iconScaleSetting = UserDefaults.standard.integer(forKey: key)
        case "useCustomKeyboard":
            useCustomKeyboard = UserDefaults.standard.bool(forKey: key)
        case "idlePromptsEnabled":
            idlePromptsEnabled = UserDefaults.standard.bool(forKey: key)
            if !idlePromptsEnabled { stopIdleAnimations(); cancelCombatIdleTimer(); cancelSaveMenuIdleTimer() }
        case "blinkingCursorEnabled":
            blinkingCursorEnabled = UserDefaults.standard.bool(forKey: key)
        case "fontSizeSetting":
            fontScale = fontSizeSetting.scale
        case "undoRedoEnabled":
            if !undoRedoEnabled { clearAllUndoRedo() }
        case "music_enabled":
            if musicEnabled { playCurrentMusic() } else { SoundManager.shared.stopMusic() }
        case "battle_sounds_enabled":
            SoundManager.shared.battleSoundsEnabled = battleSoundsEnabled
        default: break
        }
    }

    /// Format the current display value for a setting key
    private func settingDisplayValue(key: String) -> String {
        switch key {
        case "hit_animations": return hitAnimationsEnabled ? "On" : "Off"
        case "voiceMenuEnabled": return voiceMenuEnabled ? "On" : "Off"
        case "speechEnabled": return SpeechEngine.shared.isEnabled ? "On" : "Off"
        case "music_enabled": return musicEnabled ? "On" : "Off"
        case "battle_sounds_enabled": return battleSoundsEnabled ? "On" : "Off"
        case "fontSizeSetting": return fontSizeSetting.displayName
        case "iconScaleSetting":
            return iconScaleSetting == 0 ? "Normal" : (iconScaleSetting == 1 ? "Large" : "XL")
        case "useArrowNavigation": return useArrowNavigation ? "Buttons" : "Swipe"
        case "npcs_enabled": return npcsEnabled ? "On" : "Off"
        case "poison_enabled": return poisonEnabled ? "On" : "Off"
        case "multiplayer_enabled": return multiplayerEnabled ? "On" : "Off"
        case "undoRedoEnabled": return undoRedoEnabled ? "On" : "Off"
        case "useCustomKeyboard": return useCustomKeyboard ? "Custom" : "System"
        case "idlePromptsEnabled": return idlePromptsEnabled ? "On" : "Off"
        case "autoContinueEnabled": return autoContinueEnabled ? "On" : "Off"
        case "showCountdownControl": return showCountdownControl ? "On" : "Off"
        case "autoScrollSpeed": return autoScrollSpeedName
        case "leftHanded": return leftHanded ? "Left" : "Right"
        case "reduceAnimations": return reduceAnimations ? "Reduced" : "Full"
        case "helpGlyph": return MenuOption.helpGlyph
        case "blinkingCursorEnabled": return blinkingCursorEnabled ? "On" : "Off"
        case "map_radius": return "\(mapRadius)"
        case "mac_map_rows": return "\(macMapRows)"
        case "combatArena": return combatArenaEnabled ? "On" : "Off"
        case "maxButtonsPerScreen": return "\(maxButtonsPerScreen)"
        case "autosave_interval": return autosaveInterval.displayName
        case "dmAdLibLevel": return DMEngine.shared.adLibLevel.displayName
        case "dm_log_context_size":
            return dmLogContextSize == Int.max ? "Unlimited" : "\(dmLogContextSize)"
        case "menu_melody": return melodyName(type: "menu", choice: menuMelodyChoice)
        case "exploration_melody": return melodyName(type: "exploration", choice: explorationMelodyChoice)
        case "combat_melody": return melodyName(type: "combat", choice: combatMelodyChoice)
        case "chat_melody": return melodyName(type: "chat", choice: chatMelodyChoice)
        case "longPressDuration": return String(format: "%.1fs", longPressDuration)
        case "infoTimeout":
            return infoTimeout == 0 ? "Off" : String(format: "%.1fs", infoTimeout)
        case "gameTimeLimit":
            return gameTimeLimit == 0 ? "Off" : "\(gameTimeLimit) min"
        case "adventureLogLimit":
            return adventureLogLimit == 0 ? "All" : "\(adventureLogLimit)"
        default: return UserDefaults.standard.object(forKey: key).map { "\($0)" } ?? "—"
        }
    }

    /// Undo the last setting change on a screen
    private func undoSettingOnScreen(screen: String, refreshScreen: @escaping () -> Void) {
        guard var stack = settingUndoStacks[screen], let entry = stack.popLast() else { return }
        settingUndoStacks[screen] = stack

        let currentValue = readSettingRaw(key: entry.key)
        let beforeDisplay = settingDisplayValue(key: entry.key)
        settingRedoStacks[screen, default: []].append(
            SettingUndoEntry(key: entry.key, name: entry.name, oldValue: currentValue)
        )

        writeSettingRaw(key: entry.key, value: entry.oldValue)
        let afterDisplay = settingDisplayValue(key: entry.key)
        showUndoFeedback("\(entry.name): \(beforeDisplay) → \(afterDisplay)")
        refreshScreen()
    }

    /// Redo the last setting change on a screen
    private func redoSettingOnScreen(screen: String, refreshScreen: @escaping () -> Void) {
        guard var stack = settingRedoStacks[screen], let entry = stack.popLast() else { return }
        settingRedoStacks[screen] = stack

        let currentValue = readSettingRaw(key: entry.key)
        let beforeDisplay = settingDisplayValue(key: entry.key)
        settingUndoStacks[screen, default: []].append(
            SettingUndoEntry(key: entry.key, name: entry.name, oldValue: currentValue)
        )

        writeSettingRaw(key: entry.key, value: entry.oldValue)
        let afterDisplay = settingDisplayValue(key: entry.key)
        showRedoFeedback("\(entry.name): \(beforeDisplay) → \(afterDisplay)")
        refreshScreen()
    }

    /// Install undo/redo handlers for a specific settings screen
    private func installSettingUndoRedo(screen: String, refreshScreen: @escaping () -> Void) {
        guard undoRedoEnabled else {
            undoHandler = nil; redoHandler = nil
            undoLabel = nil; redoLabel = nil
            return
        }
        currentUndoScreen = screen
        let hasUndo = !(settingUndoStacks[screen]?.isEmpty ?? true)
        // Only show redo if it would actually change the setting value
        var hasRedo = false
        if let redoEntry = settingRedoStacks[screen]?.last {
            let currentValue = readSettingRaw(key: redoEntry.key)
            hasRedo = !settingValuesEqual(currentValue, redoEntry.oldValue)
        }

        undoHandler = hasUndo ? { [weak self] in
            self?.undoSettingOnScreen(screen: screen, refreshScreen: refreshScreen)
        } : nil
        redoHandler = hasRedo ? { [weak self] in
            self?.redoSettingOnScreen(screen: screen, refreshScreen: refreshScreen)
        } : nil

        undoLabel = settingUndoStacks[screen]?.last.map { "Undo:\($0.name)" }
        redoLabel = hasRedo ? settingRedoStacks[screen]?.last.map { "Redo:\($0.name)" } : nil
    }

    /// Clear all setting change stacks (called when leaving Settings entirely)
    private func clearAllSettingStacks() {
        settingUndoStacks.removeAll()
        settingRedoStacks.removeAll()
    }

    /// Sync runtime state after restoring settings from a snapshot (used by reset)
    private func syncSettingsAfterRestore() {
        SoundManager.shared.battleSoundsEnabled = battleSoundsEnabled
        if musicEnabled {
            playCurrentMusic()
        } else {
            SoundManager.shared.stopMusic()
        }
    }

    // MARK: - Input Handling

    func showMenu(_ options: [String], defaultIndex: Int = 0) {
        menuLongPressHandler = nil
        runOnMain {
            self.directionExits = [:]
            self.securedExits = []
            self.dpadCenterLabel = nil
            self.dpadCenterHandler = nil
            self.dpadCenterLongPressHandler = nil
            self.dpadNPCLabel = nil
            self.dpadNPCHandler = nil
            self.dpadTeleportHandler = nil
            self.dpadTorchLabel = nil
            self.dpadTorchHandler = nil
            self.dpadSearchHandler = nil
            self.dpadListenHandler = nil
            let mapped = options.enumerated().map { index, text -> MenuOption in
                let tint = Self.autoTint(text)
                let compact = text == "?" || text == "?\u{0338}" || text == "<<" || text == ">>" || text == "< Back"
                return MenuOption(text, isDefault: index == defaultIndex, tint: tint, compact: compact)
            }
            self.currentMenuOptions = self.withForwardOption(self.prepareMenu(mapped))
            self.awaitingTextInput = false
            self.awaitingContinue = false
            self.fullScreenTapToContinue = false
            self.autoReadIfSpeakerMode()
        }
    }

    func showMenuOptions(_ options: [MenuOption]) {
        menuLongPressHandler = nil
        runOnMain {
            self.directionExits = [:]
            self.securedExits = []
            self.dpadCenterLabel = nil
            self.dpadCenterHandler = nil
            self.dpadCenterLongPressHandler = nil
            self.dpadNPCLabel = nil
            self.dpadNPCHandler = nil
            self.dpadTeleportHandler = nil
            self.dpadTorchLabel = nil
            self.dpadTorchHandler = nil
            self.dpadSearchHandler = nil
            self.dpadListenHandler = nil
            let mapped = options.map { opt -> MenuOption in
                if !opt.isCompactNav && (opt.text == "?" || opt.text == "?\u{0338}" || opt.text == "<<" || opt.text == ">>" || opt.text == "< Back") {
                    return MenuOption(opt.text, isDefault: opt.isDefault, isDisabled: opt.isDisabled, isAlert: opt.isAlert, tint: opt.tint, compact: true)
                }
                return opt
            }
            self.currentMenuOptions = self.withForwardOption(self.prepareMenu(mapped))
            self.awaitingTextInput = false
            self.awaitingContinue = false
            self.fullScreenTapToContinue = false
            self.autoReadIfSpeakerMode()
        }
    }

    // MARK: - Paginated Menu

    /// Show a paginated menu with ▸/◂ navigation when items exceed maxButtonsPerScreen.
    /// - allOptions: full list of display strings
    /// - page: current page (0-indexed)
    /// - pinned: buttons always shown on every page (e.g. "?") — count against limit
    /// - handler: called with index into allOptions (0-based)
    func showPaginatedMenu(_ allOptions: [String], page: Int = 0,
                            pinned: [String] = [],
                            defaultIndex: Int? = nil,
                            pinnedHandler: ((Int) -> Void)? = nil,
                            handler: @escaping (Int) -> Void) {
        let limit = maxButtonsPerScreen
        let pinnedCount = pinned.count
        let totalItems = allOptions.count

        // If everything fits, just show normally
        if totalItems + pinnedCount <= limit {
            let all = allOptions + pinned
            showMenu(all, defaultIndex: defaultIndex ?? 0)
            menuHandler = { choice in
                let idx = choice - 1
                if idx < allOptions.count {
                    handler(idx)
                } else {
                    pinnedHandler?(idx - allOptions.count)
                }
            }
            return
        }

        let totalPages: Int
        let contentSlots: Int
        let pageStart: Int
        let pageEnd: Int

        // Calculate how many content slots we have on this page
        // Page 0: might need ▸ only. Middle pages: ◂ + ▸. Last page: ◂ only.
        let hasBack = page > 0

        // << / >> / "?" / "< Back" share a single compact button-sized cell
        // visually — that's 1 reserved slot regardless of which of those are
        // active (TerminalView prioritises << / >> / Back over "?" if all 4
        // would ever collide, so Back is never the one silently dropped).
        // Every other pinned button (e.g. "Manage Saves") renders as its own
        // regular, always-visible button instead (see menuOpts below), so
        // each of those needs its own reserved slot on every page.
        let regularPinnedCount = pinned.filter { !GameEngine.isCompactPinnedNavText($0) }.count
        let firstNavItems = 1 + regularPinnedCount   // compact cell: [>> + ?] + regular pinned buttons
        let middleNavItems = 1 + regularPinnedCount  // compact cell: [<< + >> + ?] + regular pinned buttons
        let lastNavItems = 1 + regularPinnedCount    // compact cell: [<< + ?] + regular pinned buttons
        let firstPageSlots = max(1, limit - firstNavItems)
        let middlePageSlots = max(1, limit - middleNavItems)
        let lastPageSlots = max(1, limit - lastNavItems)

        if totalItems <= firstPageSlots {
            // Shouldn't happen (we checked above), but safety
            totalPages = 1
        } else {
            var remaining = totalItems - firstPageSlots
            var pages = 1
            while remaining > lastPageSlots {
                remaining -= middlePageSlots
                pages += 1
            }
            totalPages = pages + 1
        }

        let safePage = min(page, totalPages - 1)
        paginatedPage = safePage
        let hasMore: Bool

        if safePage == 0 {
            contentSlots = firstPageSlots
            pageStart = 0
            pageEnd = min(totalItems, contentSlots)
            hasMore = totalItems > pageEnd
        } else {
            let afterFirstPage = firstPageSlots
            let middleOffset = (safePage - 1) * middlePageSlots
            pageStart = afterFirstPage + middleOffset

            if safePage == totalPages - 1 {
                // Last page
                contentSlots = lastPageSlots
                pageEnd = min(totalItems, pageStart + contentSlots)
                hasMore = false
            } else {
                contentSlots = middlePageSlots
                pageEnd = min(totalItems, pageStart + contentSlots)
                hasMore = totalItems > pageEnd
            }
        }

        // Build visible menu
        var visibleOptions: [String] = []
        var mapping: [Int] = [] // maps visible index to action

        if hasBack {
            visibleOptions.append("<<")
            mapping.append(-1) // sentinel for back
        }

        for i in pageStart..<pageEnd {
            visibleOptions.append(allOptions[i])
            mapping.append(i) // index into allOptions
        }

        // Add pinned (Help) before >> so Help is bottom-left, >> bottom-right
        if hasMore {
            for p in pinned {
                visibleOptions.append(p)
                mapping.append(-3) // sentinel for pinned
            }
            visibleOptions.append(">>")
            mapping.append(-2) // sentinel for more
        } else {
            for p in pinned {
                visibleOptions.append(p)
                mapping.append(-3) // sentinel for pinned
            }
        }

        // Regular (non-compact) pinned buttons — e.g. "Manage Saves" — need
        // their own explicit displayNumber too, not just content items.
        // Without one they'd fall back to a per-page positional count (see
        // regularButton's fallbackDisplayNumber), which can collide with a
        // content item's absolute number on the very same page (both
        // showing "5.", say). Numbering them right after the content list
        // guarantees no collision is possible, and keeps each pinned
        // button's number stable across every page since it doesn't depend
        // on what content happens to share that page.
        var pinnedDisplayNumbers: [String: Int] = [:]
        var nextPinnedNumber = totalItems + 1
        for p in pinned where !GameEngine.isCompactPinnedNavText(p) {
            pinnedDisplayNumbers[p] = nextPinnedNumber
            nextPinnedNumber += 1
        }

        // Build MenuOptions with tints
        let menuOpts = visibleOptions.enumerated().map { idx, text -> MenuOption in
            let m = mapping[idx]
            // The compact nav cell only has 3 physical slots (for <<, ?, >>,
            // and now also "< Back" — see isCompactPinnedNavText). Any other
            // pinned button (e.g. "Manage Saves") is rendered as a normal,
            // always-visible button instead, so it's never silently dropped
            // when the compact cell is already full.
            let isCompactPinnedNav = m == -3 && GameEngine.isCompactPinnedNavText(text)
            if m == -1 || m == -2 || isCompactPinnedNav {
                return MenuOption(text, tint: .navigation, compact: true)
            }
            let isDefault: Bool
            if let di = defaultIndex {
                isDefault = m == di
            } else {
                isDefault = idx == (hasBack ? 1 : 0)
            }
            // Content items (m >= 0) get an explicit displayNumber — m is
            // already this item's true position in the full, unpaginated
            // allOptions array, so this stays correct (and matches a
            // caller's own printed "N. ..." reference list) no matter which
            // page it lands on, unlike a fresh per-page count. Regular
            // pinned buttons (m == -3) get one from pinnedDisplayNumbers
            // (see above) for the same reason.
            let displayNumber: Int?
            if m >= 0 {
                displayNumber = m + 1
            } else if m == -3 {
                displayNumber = pinnedDisplayNumbers[text]
            } else {
                displayNumber = nil
            }
            return MenuOption(text, isDefault: isDefault, tint: Self.autoTint(text), displayNumber: displayNumber)
        }
        showMenuOptions(menuOpts)

        menuHandler = { [weak self] choice in
            let idx = choice - 1
            guard idx >= 0 && idx < mapping.count else { return }
            let m = mapping[idx]
            if m == -1 {
                // << — go to previous page
                self?.showPaginatedMenu(allOptions, page: safePage - 1, pinned: pinned, defaultIndex: defaultIndex, pinnedHandler: pinnedHandler, handler: handler)
            } else if m == -2 {
                // >> — go to next page
                self?.showPaginatedMenu(allOptions, page: safePage + 1, pinned: pinned, defaultIndex: defaultIndex, pinnedHandler: pinnedHandler, handler: handler)
            } else if m == -3 {
                // Pinned item — resolved by text so it's correct regardless
                // of visual position (compact vs. regular). Handled here,
                // inside showPaginatedMenu itself, rather than relying on an
                // external one-time wrap: << / >> re-invoke this same
                // function directly, which would otherwise silently discard
                // any wrapper installed by a caller after the first render —
                // exactly what made pinned buttons (e.g. "< Back") stop
                // working after navigating to a second page.
                let options = self?.currentMenuOptions ?? []
                if idx < options.count, let pinnedIdx = pinned.firstIndex(of: options[idx].text) {
                    pinnedHandler?(pinnedIdx)
                }
            } else if m >= 0 {
                handler(m)
            }
        }

        // Long-press on ◂/▸ jumps 3 pages
        menuLongPressHandler = { [weak self] choice in
            let idx = choice - 1
            guard idx >= 0 && idx < mapping.count else { return }
            let m = mapping[idx]
            if m == -1 {
                self?.showPaginatedMenu(allOptions, page: max(0, safePage - 3), pinned: pinned, defaultIndex: defaultIndex, pinnedHandler: pinnedHandler, handler: handler)
            } else if m == -2 {
                self?.showPaginatedMenu(allOptions, page: min(totalPages - 1, safePage + 3), pinned: pinned, defaultIndex: defaultIndex, pinnedHandler: pinnedHandler, handler: handler)
            }
        }
    }

    /// Show a paginated menu with ▸/◂ navigation for MenuOption arrays.
    /// pinnedHandler is called with the pinned item's index (0-based within pinned array).
    func showPaginatedMenuOptions(_ allOptions: [String], page: Int = 0,
                                   pinned: [String] = [],
                                   defaultIndex: Int? = nil,
                                   handler: @escaping (Int) -> Void,
                                   pinnedHandler: @escaping (Int) -> Void) {
        // Delegates entirely to showPaginatedMenu, which now handles pinned
        // items internally (by text, so it's correct regardless of visual
        // position) on every page — including ones reached via << / >>
        // navigation. This used to be handled here instead, by wrapping
        // menuHandler once after the first render; that wrapper was silently
        // discarded whenever << / >> re-invoked showPaginatedMenu directly,
        // which is exactly what made pinned buttons (e.g. "< Back") stop
        // working after navigating to a second page.
        showPaginatedMenu(allOptions, page: page, pinned: pinned, defaultIndex: defaultIndex, pinnedHandler: pinnedHandler, handler: handler)
    }

    /// Auto-assign button tint based on text content
    /// Whether a pinned button is safe to squeeze into the compact <</>>/?
    /// nav cell (which has only 3 physical slots) instead of rendering as
    /// its own regular (numbered) button. "?", "< Back", and "Manage"
    /// qualify. TerminalView gives << / < Back / ? / >> fixed, consistent
    /// slots (leave/back on the left, ? in the middle, >> on the right);
    /// << and "< Back" share the left slot and are never both shown at
    /// once — << wins when both would apply, since paging back to page 0
    /// already gets you out. "Manage" is the one that can go unreached on a
    /// page where the cell is already full, in favour of the things that
    /// matter more everywhere.
    static func isCompactPinnedNavText(_ text: String) -> Bool {
        text == "?" || text == "?\u{0338}" || text == "< Back" || text == "Manage"
    }

    /// Parses a spoken number phrase ("eighty", "one hundred and eighty",
    /// "eighty gold") into its integer value. Returns nil unless the
    /// ENTIRE string (after dropping a single trailing unit word) is made
    /// of number words — so ordinary free-text/chat input is never
    /// misread as a number. See handleTextInput, which normalizes voice
    /// transcripts before handing them to any numeric prompt.
    static func parseSpokenNumber(_ text: String) -> Int? {
        let ones: [String: Int] = [
            "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7,
            "eight": 8, "nine": 9, "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13,
            "fourteen": 14, "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19,
        ]
        let tens: [String: Int] = [
            "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
        ]
        let scales: [String: Int] = ["hundred": 100, "thousand": 1000]
        let unitWords: Set<String> = ["gold", "gp", "g", "pieces", "piece", "coins", "coin", "dollars", "dollar"]

        var words = text.lowercased()
            .replacingOccurrences(of: "-", with: " ")
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }

        // Drop a single trailing unit word ("eighty gold" -> "eighty").
        if let last = words.last, unitWords.contains(last) {
            words.removeLast()
        }
        guard !words.isEmpty else { return nil }

        var total = 0
        var current = 0
        for word in words {
            if word == "and" { continue }
            if let v = ones[word] {
                current += v
            } else if let v = tens[word] {
                current += v
            } else if let v = scales[word] {
                current = (current == 0 ? 1 : current) * v
                if v == 1000 { total += current; current = 0 }
            } else {
                return nil  // a non-number word — not a spoken number phrase
            }
        }
        return total + current
    }

    static func autoTint(_ text: String) -> MenuTint {
        // Every "< X" button in this app (Back, Done, Cancel, Leave, Not Now...)
        // is a navigation/dismissal action by convention — tint them all the
        // same regardless of the label, so they read consistently everywhere.
        if text.hasPrefix("< ") { return .navigation }
        let lower = text.lowercased()
        // Navigation / back buttons
        if lower == "done" || lower.hasPrefix("done (")
            || lower == "cancel" || lower == "continue" || lower == "next"
            || lower == "back" || lower == "quit" || lower == "save & quit"
            || lower.hasPrefix("delete") || lower.hasPrefix("clear all")
            || lower.hasPrefix("yes, delete") || lower.hasPrefix("quit")
            || text == "?" || text == "?\u{0338}" || text == "<<" || text == ">>" { return .navigation }
        // Chat
        if lower == "chat" { return .cyan }
        // View-only actions — read the same as Roster's own tint, so a
        // non-mutating "look, don't touch" button (View Card) visually
        // stands apart from the Change Type/Race/Class/Voice mutators
        // right next to it, which all otherwise share the same default tint.
        if lower == "view card" { return .cyan }
        return .normal
    }

    func showMenuWithDirections(_ options: [MenuOption], exits: [Direction: Bool]) {
        menuLongPressHandler = nil
        runOnMain {
            self.directionExits = exits
            let mapped = options.map { opt -> MenuOption in
                if !opt.isCompactNav && (opt.text == "?" || opt.text == "?\u{0338}" || opt.text == "<<" || opt.text == ">>" || opt.text == "< Back") {
                    return MenuOption(opt.text, isDefault: opt.isDefault, isDisabled: opt.isDisabled, isAlert: opt.isAlert, tint: opt.tint, compact: true)
                }
                return opt
            }
            self.currentMenuOptions = self.withForwardOption(self.prepareMenu(mapped))
            self.awaitingTextInput = false
            self.awaitingContinue = false
            self.fullScreenTapToContinue = false
            self.autoReadIfSpeakerMode()
        }
    }

    func promptText(_ prompt: String) {
        print(prompt, color: .green)
        // A fresh prompt is a new screen state — a tap/swipe target left
        // over from whatever was on screen before (e.g. "tap the green
        // text to buy" on a shop list) must not still be live here.
        textLongPressHandler = nil
        swipeLeftHandler = nil
        swipeRightHandler = nil
        swipeRandomHandler = nil
        runOnMain {
            self.directionExits = [:]
            self.securedExits = []
            self.currentMenuOptions = []
            self.awaitingTextInput = true
            self.awaitingContinue = false
            self.fullScreenTapToContinue = false
            self.autoReadIfSpeakerMode()
        }
    }

    /// Show both a text input prompt and menu buttons simultaneously
    func promptTextWithMenu(_ prompt: String, options: [String]) {
        print(prompt, color: .green)
        textLongPressHandler = nil
        swipeLeftHandler = nil
        swipeRightHandler = nil
        swipeRandomHandler = nil
        runOnMain {
            self.directionExits = [:]
            self.securedExits = []
            let mapped = options.enumerated().map { index, text -> MenuOption in
                let compact = text == "?" || text == "?\u{0338}" || text == "<<" || text == ">>" || text == "< Back"
                return MenuOption(text, isDefault: index == 0, tint: Self.autoTint(text), compact: compact)
            }
            self.currentMenuOptions = self.withForwardOption(self.prepareMenu(mapped))
            self.awaitingTextInput = true
            self.awaitingContinue = false
            self.fullScreenTapToContinue = false
            self.autoReadIfSpeakerMode()
        }
    }

    func waitForContinue(fullScreenTap: Bool = true, autoContinue: Bool = true) {
        // Same reasoning as promptText — waitForContinue is meant to be a
        // clean "tap anywhere to continue" state (see TerminalView's
        // awaitingContinue branch), which only renders when textTapEnabled
        // is false. Leaving a previous screen's textLongPressHandler set
        // (e.g. buying an item in the shop list, which appends the
        // confirmation onto the same screen rather than clearing it first)
        // kept textTapEnabled on, so tapping to continue silently re-ran
        // the stale handler against the wrong line numbers instead —
        // "broken scrolling," only escapable via the X/close icon.
        textLongPressHandler = nil
        swipeLeftHandler = nil
        swipeRightHandler = nil
        swipeRandomHandler = nil
        // waitForContinue always means "here's what just happened, take a
        // look" — whatever text was just printed (often appended below an
        // existing list, e.g. a shop purchase confirmation, rather than
        // onto a freshly cleared screen) needs to actually be visible.
        // suppressAutoScroll — true while e.g. a long item list is being
        // read from the top — forces the view back to the TOP on every new
        // line instead, which hid that text entirely (and kept fighting
        // any attempt to scroll down to it) until it was turned off here.
        suppressAutoScroll = false
        runOnMain {
            self.directionExits = [:]
            self.securedExits = []
            self.currentMenuOptions = []
            self.awaitingTextInput = false
            self.awaitingContinue = true
            self.fullScreenTapToContinue = fullScreenTap
            self.autoReadIfSpeakerMode()
        }
        resetIdleTimer()
        if autoContinue {
            scheduleAutoContinue()
        } else {
            // The caller runs its own countdown (waitForContinueWithTimeout)
            // — still bump the generation so any older one goes stale.
            Self.continueGeneration += 1
        }
        scheduleContinueHint()
    }

    /// Bumped on every waitForContinue() — lets a pending auto-continue
    /// tell "still the same tap-to-continue screen I was armed for" apart
    /// from a later one (many of these screens append rather than clear,
    /// so clearTerminal's own generation counter can't tell them apart).
    private static var continueGeneration = 0

    /// Every tap-to-continue screen honours the Info Timeout setting (at
    /// 2x, the same default multiplier waitForContinueWithTimeout uses),
    /// not just the handful that used to opt in — otherwise screens like a
    /// "Saved backup" confirmation sat waiting forever. Does exactly what a
    /// tap would (handleContinue), and only if nothing has moved on since.
    /// Off when Info Timeout is Off (0) or Auto-Continue is Off, and in
    /// speaker mode, where the screen is being read aloud and cutting it
    /// short would lose text.
    /// Set by a "defeated!" attack report: its countdown is kept short.
    private var quickNextContinue = false

    /// True while it's a computer-controlled companion's or a monster's turn in a fight.
    private var aiTurnInProgress: Bool {
        guard let turn = currentCombat?.currentCombatant else { return false }
        if !turn.isPlayer { return true }
        return party.first(where: { $0.id == turn.id })?.isComputerControlled ?? false
    }

    private func scheduleAutoContinue() {
        Self.continueGeneration += 1
        let myGeneration = Self.continueGeneration
        // Read Aloud: the voice sets the pace — move on a moment after it has
        // read this screen (a tap still moves on at once, and stops the voice).
        if speakerModeOn {
            quickNextContinue = false
            readingPaceNext = false
            speechReadCompleteHandler = { [weak self] in
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                    guard let self = self, Self.continueGeneration == myGeneration, self.awaitingContinue,
                          self.autoContinueEnabled, !self.autoContinuePaused else { return }
                    self.handleContinue()
                }
            }
            return
        }
        let base = countdownDelay(base: infoTimeout * 2)
        // In a fight things move on a little sooner — by a random amount,
        // never slower than usual.
        // Computer-controlled companions' and monsters' turns move on quickest
        // (a few seconds at most — the reading-time stretch made them drag).
        let delay: Double
        if currentCombat == nil { delay = base * timeoutScale(.reading) }
        else if readingPaceNext { delay = base * timeoutScale(.reading) }
        // A monster's or companion's turn: long enough to read what just happened.
        else if aiTurnInProgress { delay = max(2.5, min(12, newTextReadingTime())) * timeoutScale(.fights) }
        else { delay = base * Double.random(in: 0.55...0.85) * timeoutScale(.fights) }
        readingPaceNext = false
        // A "defeated!" report moves on sooner still.
        let finalDelay = quickNextContinue ? min(delay, 3.0 * timeoutScale(.fights)) : delay
        quickNextContinue = false
        scheduleAutoAdvance(after: finalDelay, isStillValid: { [weak self] in
            guard let self = self else { return false }
            return Self.continueGeneration == myGeneration && self.awaitingContinue && !self.speakerModeOn
        }, fire: { [weak self] in self?.handleContinue() })
    }

    /// Every auto-continue countdown goes through here: after `delay`,
    /// runs `fire` if the screen is still the one it was armed for. With
    /// Auto-Continue Off it never fires (the screen just waits for a tap).
    /// While paused the remaining time is frozen, and resumes from there.
    /// Publishes autoCountdownEnd/Total for the input bar's progress line.
    /// Ticks on the .common run-loop mode so it keeps counting while the
    /// player is scrolling.
    private func scheduleAutoAdvance(after delay: Double, isStillValid: @escaping () -> Bool, fire: @escaping () -> Void) {
        guard delay > 0, autoContinueEnabled else { return }
        let token = UUID()
        autoCountdownToken = token
        var remaining = delay
        var deadline = Date().addingTimeInterval(delay)
        autoCountdownTotal = delay
        autoCountdownEnd = deadline
        autoCountdownPausedRemaining = autoContinuePaused ? delay : nil
        let clear: () -> Void = { [weak self] in
            guard let self = self, self.autoCountdownToken == token else { return }
            self.autoCountdownEnd = nil
            self.autoCountdownPausedRemaining = nil
        }
        let timer = Timer(timeInterval: 0.1, repeats: true) { [weak self] t in
            guard let self = self, isStillValid(), self.autoContinueEnabled else {
                t.invalidate()
                clear()
                return
            }
            if self.autoContinuePaused {
                deadline = Date().addingTimeInterval(remaining)
                return
            }
            // The live countdown follows the shared end time, so a pause,
            // resume or long-press speed-up (hurryAutoContinue) applies to it.
            if self.autoCountdownToken == token, let end = self.autoCountdownEnd { deadline = end }
            remaining = deadline.timeIntervalSinceNow
            if remaining <= 0 {
                t.invalidate()
                clear()
                fire()
            }
        }
        RunLoop.main.add(timer, forMode: .common)
    }

    /// Checks twice a second until the player un-pauses, then runs
    /// `resume` — gives up as soon as the screen has moved on.
    private func afterAutoContinuePause(isStillValid: @escaping () -> Bool, resume: @escaping () -> Void) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self = self, isStillValid() else { return }
            if self.autoContinuePaused {
                self.afterAutoContinuePause(isStillValid: isStillValid, resume: resume)
            } else {
                resume()
            }
        }
    }

    /// Wait for continue with auto-timeout — taps to continue immediately, or auto-continues after delay
    func waitForContinueWithTimeout(multiplier: Double = 2.0, fullScreenTap: Bool = true, action: @escaping () -> Void) {
        waitForContinue(fullScreenTap: fullScreenTap, autoContinue: false)

        // Single-fire guard — without it, a tap landing at (or just before)
        // the exact moment the timer's dispatched block runs can fire
        // `action()` from BOTH paths: `timer.invalidate()` only stops the
        // timer from firing again in the FUTURE, it does nothing for a
        // callback that's already been dispatched to the main queue and is
        // just waiting its turn to run. This is exactly the kind of screen
        // `action` chains into the next step of a sequence (loot pickup,
        // post-purchase options, etc.), so a double-fire here meant the
        // next screen — and whatever it grants — ran twice. Mirrors the
        // same guard autoReturn() already uses for its own timer/tap race.
        var fired = false
        let fire: () -> Void = { [weak self] in
            guard !fired else { return }
            fired = true
            self?.inputHandler = nil
            action()
        }
        // Stale-screen check stays timer-only — a tap always means the
        // player is acting on the CURRENT screen, but a pending countdown
        // could fire well after the player has already moved on some other
        // way (e.g. the corner X), where `action` would no longer make sense.
        let myGeneration = Self.continueGeneration
        var delay = countdownDelay(base: infoTimeout * multiplier)
        // Picking up the spoils after a fight: move along quicker (still
        // time to read who took what).
        if combatLootEligible != nil { delay = max(1.5, min(delay, 4.0) * 0.6) }
        delay *= timeoutScale(pendingTimeoutKind ?? (combatLootEligible != nil ? .loot : .reading))
        pendingTimeoutKind = nil
        scheduleAutoAdvance(after: delay, isStillValid: { [weak self] in
            !fired && self?.awaitingContinue == true && Self.continueGeneration == myGeneration
        }, fire: fire)
        inputHandler = { _ in fire() }
    }

    /// Auto-return to exploration after a delay. Sets closeHandler for manual dismiss too.
    /// Where to return after auto-timeout (nil = exploration view)
    private var autoReturnDestination: (() -> Void)?

    /// One-shot signal fired when speaker mode has genuinely finished
    /// reading the current autoReturn() screen aloud — set by
    /// startReadingScreen() itself, either straight from SpeechEngine's
    /// AVSpeechSynthesizerDelegate "didFinish" callback (see onFinish) when
    /// there was something to say, or immediately when there was nothing
    /// new to read. A real completion signal rather than a guessed delay,
    /// so a longer search/listen result is never cut off mid-sentence.
    private var speechReadCompleteHandler: (() -> Void)?

    /// Bumped on every autoReturn() call; the fallback Timer scheduled by
    /// THIS call captures its own value and checks it still matches before
    /// firing. Without this, tapping through an autoReturn() screen early
    /// left its Timer running in the background with no way to cancel it
    /// (`self.closeHandler != nil` was the only guard, and virtually every
    /// later screen sets ITS OWN closeHandler) — so that stale Timer could
    /// fire minutes later, mid a completely unrelated screen, and silently
    /// invoke this call's old destination() on top of it. Root cause of
    /// reports like a screen (e.g. the victory screen) suddenly becoming
    /// unresponsive with no visible cause.
    private var autoReturnGeneration = 0

    func autoReturn(after seconds: Double? = nil, stretchForReading: Bool = true) {
        let seconds = (seconds ?? infoTimeout) * timeoutScale(pendingTimeoutKind ?? .reading)
        pendingTimeoutKind = nil
        let destination = autoReturnDestination ?? { [weak self] in self?.showExplorationView() }
        autoReturnDestination = nil
        closeHandler = destination
        speechReadCompleteHandler = nil
        autoReturnGeneration += 1
        let myGeneration = autoReturnGeneration

        // Fires destination() exactly once, however it ends up triggered
        // (manual tap, the real speech-finished signal, or the fallback
        // timer below) — clearing closeHandler/speechReadCompleteHandler
        // first so whichever path runs first wins and the rest are no-ops.
        // The generation check additionally guards against THIS call's own
        // fallback Timer firing after some later autoReturn() call has
        // already superseded it (see autoReturnGeneration's doc above).
        let fire: () -> Void = { [weak self] in
            guard let self = self, self.closeHandler != nil, self.autoReturnGeneration == myGeneration else { return }
            self.closeHandler = nil
            self.speechReadCompleteHandler = nil
            destination()
        }

        // Always offer tap-to-continue (tapping the printed result text),
        // not just when the D-pad/menu buttons are also empty — search,
        // listen, and similar results wait out a fixed infoTimeout even
        // when triggered from the main exploration screen (D-pad still
        // showing), and previously had no way to skip that wait early
        // besides the small corner close icon. This is the same
        // tap-anywhere affordance waitForContinue() uses; it layers over
        // whatever controls are already on screen without hiding them.
        awaitingContinue = true
        inputHandler = { _ in fire() }
        scheduleContinueHint()

        // Registered BEFORE autoReadIfSpeakerMode() — its 0.3s startup
        // delay means speech can start and, for short text, even finish
        // well within that window, so the handler must already be in place.
        if speakerModeOn {
            // Paused: finishing the read-aloud doesn't move on — the
            // fallback below picks it up once the player resumes.
            speechReadCompleteHandler = { [weak self] in
                guard let self = self, !self.autoContinuePaused else { return }
                fire()
            }
        }
        // showMenu()/waitForContinue() etc. all trigger speaker mode's
        // auto-read of the screen's text, but this brief "print a result,
        // then return" pattern (search, listen, dark search, and similar
        // flavour-text screens) never went through either — the DM voice
        // simply stayed silent for all of them in speaker mode.
        autoReadIfSpeakerMode()

        if speakerModeOn {
            scheduleAutoReturnFallback(after: seconds, fire: fire, generation: myGeneration)
        } else {
            scheduleAutoAdvance(after: stretchForReading ? countdownDelay(base: seconds) : seconds, isStillValid: { [weak self] in
                guard let self = self else { return false }
                return self.autoReturnGeneration == myGeneration && self.closeHandler != nil
            }, fire: fire)
        }
    }

    /// Fallback timer for autoReturn() — the only path when speaker mode is
    /// off, and a safety net (rescheduling itself as a short poll) in the
    /// unlikely case the real speechReadCompleteHandler signal is ever
    /// missed (e.g. an audio session error swallows the delegate callback).
    private func scheduleAutoReturnFallback(after seconds: Double, fire: @escaping () -> Void, generation: Int) {
        Timer.scheduledTimer(withTimeInterval: seconds, repeats: false) { [weak self] _ in
            DispatchQueue.main.async {
                guard let self = self, self.autoReturnGeneration == generation else { return }
                // Auto-Continue Off (and not reading aloud): the screen
                // stays until tapped or closed with ✕.
                guard self.autoContinueEnabled || self.speakerModeOn else { return }
                if self.autoContinuePaused {
                    self.afterAutoContinuePause(isStillValid: { [weak self] in self?.autoReturnGeneration == generation }) { [weak self] in
                        self?.scheduleAutoReturnFallback(after: max(seconds, 1.0), fire: fire, generation: generation)
                    }
                    return
                }
                let stillSpeaking = self.speakerModeOn && (self.isSpeakingAloud || !self.speakerHasReadCurrentPage)
                if stillSpeaking {
                    self.scheduleAutoReturnFallback(after: 0.5, fire: fire, generation: generation)
                    return
                }
                fire()
            }
        }
    }

    /// Print the dungeon map matching the exploration view style (radius, torch, colour)
    func printExplorationMap() {
        guard let dungeon = dungeon else { return }
        let (radius, verticalRadius, compact) = bestMapRadius()
        lastMapExtent = (radius, verticalRadius)
        #if os(macOS)
        let capWidth = false   // the Mac map fills its pane's width (see bestMapRadius)
        #else
        let capWidth = true
        #endif
        let mapLines = dungeon.getMapDisplay(visibilityRadius: radius, torchLit: torchLit, compact: compact, verticalRadius: verticalRadius, legendMaxSymbols: mapLegendMaxSymbols, hasTrapSense: partyHasTrapSense, capWidth: capWidth)
        printMap(mapLines, color: torchMapColor, size: mapFontSize)
        // The big map, if it's open, follows the party (moves, stairs, a new level).
        if mapOverlayVisible {
            atlasLevelIndex = max(0, atlasLevelCount - 1)
            presentAtlasMapOverlay()
        }
    }

    /// Fixed-width card position label, e.g. " 3/30" always same length as "30/30"
    private func cardLabel(_ current: Int, of total: Int) -> String {
        let totalStr = "\(total)"
        let currentStr = "\(current)".padding(toLength: totalStr.count, withPad: " ", startingAt: 0)
        return "\(currentStr)/\(totalStr)"
    }

    func handleMenuChoice(_ choice: Int) {
        stopIdleAnimations()
        // Frozen: buttons wait (a help/settings page opened from a link still works).
        if timeFrozen && linkReturnSnapshot == nil { showFrozenNotice(); return }
        // Suppress taps briefly after a long-press screen transition
        guard Date() > suppressMenuUntil else { return }

        // Ignore a second tap arriving within a third of a second of the last
        // one handled — a fast double-tap firing the same button action
        // twice before the screen has visibly moved on (see lastMenuChoiceHandledAt).
        guard Date().timeIntervalSince(lastMenuChoiceHandledAt) > 0.35 else { return }
        lastMenuChoiceHandledAt = Date()

        // Ignore stale taps from a previous menu (e.g. finger-up after long-press
        // where the old menu had more options than the new one)
        guard choice >= 1 && choice <= currentMenuOptions.count else { return }
        if speakerModeOn { SpeechEngine.shared.stop() }
        recordAction("pressed \"\(currentMenuOptions[choice - 1].text)\"")

        // "Fwd >" is injected generically (see withForwardOption) rather
        // than wired by each screen's own menuHandler — intercept it here,
        // before dispatching to that handler, so no caller needs to know
        // about it or account for its index in their own options array.
        if currentMenuOptions[choice - 1].text == "Fwd >" {
            flashTitle()
            goForwardInHistory()
            return
        }

        // A screen opened from an in-text link: its "< Back" returns to the
        // screen the link was on, not up this screen's own menu tree.
        if linkReturnSnapshot != nil && currentMenuOptions[choice - 1].text == "< Back" {
            flashTitle()
            returnFromLink()
            return
        }

        // Marks the NEXT clearTerminal() (whichever screen this tap leads
        // to) as a genuine Back navigation — see justNavigatedBack/
        // navigationHistory. Any other tap here means a normal forward
        // move, invalidating "Fwd >" for the same reason a browser's
        // forward history clears once you go somewhere new.
        let tappedText = currentMenuOptions[choice - 1].text
        justNavigatedBack = (tappedText == "< Back" || tappedText == "<<")

        // Flash the title text as visual feedback on every button press
        flashTitle()

        // Diagnostic: record exactly what this tap resolved to before
        // calling into the handler — if the handler turns out to be nil, or
        // a downstream function returns without setting its own breadcrumb,
        // this is what recoverFromOrphanedScreen() will show. Overwritten by
        // any more specific breadcrumb the handler itself sets.
        setBreadcrumb("handleMenuChoice(choice:\(choice), options:\(currentMenuOptions.map { $0.text }), hasHandler:\(menuHandler != nil))")

        if let handler = menuHandler {
            handler(sourceChoice(choice))
        } else {
            // Buttons are visible (we passed the guard above) but nothing is
            // wired to handle them — an orphaned screen. Recover instead of
            // silently doing nothing.
            recoverFromOrphanedScreen()
        }

        // Clear pressed state after handler runs (handler sets new menu)
        DispatchQueue.main.async {
            self.pressedMenuIndex = nil
        }
    }

    /// Last-resort recovery for a screen that ended up with visible menu
    /// buttons but no menuHandler/closeHandler to act on them — e.g. a
    /// future guard-return between clearTerminal() and a screen's own
    /// showMenu setup. Returns to a known-good state rather than leaving
    /// the player stuck.
    /// Persistent, cross-session record of self-healed "Glitch in the Weave"
    /// recoveries — recovery is now silent to the player (see
    /// recoverFromOrphanedScreen()), so this UserDefaults-backed log is the
    /// only remaining trace of it, for later diagnosis/export.
    private func logGlitch(_ history: [String]) {
        let timestamp = ISO8601DateFormatter().string(from: Date())
        let entry = "[\(timestamp)] \(history.joined(separator: " | "))"
        var log = UserDefaults.standard.stringArray(forKey: "glitchLog") ?? []
        log.append(entry)
        if log.count > 50 { log.removeFirst(log.count - 50) }
        UserDefaults.standard.set(log, forKey: "glitchLog")
    }

    private func recoverFromOrphanedScreen() {
        let history = breadcrumbHistory
        logEvent("Orphaned screen recovered — history: \(history.joined(separator: " | "))", category: "SYSTEM")
        logGlitch(history)

        // Mid-character-creation, the underlying progress (which slot,
        // who's already in the party) is untouched — only this one
        // screen's buttons went dead. Silently rebuild the current step
        // instead of dropping the player to an error screen.
        //
        // Prefer lastSafeRebuildAction when the dead screen set one — it
        // re-displays the EXACT same content (e.g. the same auto-generated
        // character) rather than regenerating. Falling back to
        // chooseCharacterType() (a pure "which screen for this slot"
        // dispatcher, safe to re-invoke on its own) would otherwise call
        // autoCreateCharacter() again on every retry, rerolling a brand
        // new random character each time the still-unidentified glitch
        // recurs — which is what made a persistent recurrence look like
        // "Accept never works, it just keeps showing a different random
        // character" instead of a stable screen the player could act on.
        //
        // Uncapped (was 3): diagnostics proved this specific dead end is
        // never a permanently broken screen — autoCreateCharacter()
        // reliably renders correctly first (confirmed live: menuHandler/
        // closeHandler set, currentMenuOptions has its 2 entries) and
        // something still-unidentified clears it again ~3s later. A cap
        // meant a persistent recurrence still eventually dumped the player
        // onto the visible error screen. Since a re-render is safe here no
        // matter how many times it takes, don't give up — keep the player
        // on a working screen instead. silentCharCreationRecoveryCount is
        // still tracked (see its declaration) for the day this needs
        // bounding again.
        if gameState == .characterCreation {
            silentCharCreationRecoveryCount += 1
            if let rebuild = lastSafeRebuildAction {
                rebuild()
            } else {
                chooseCharacterType()
            }
            return
        }
        silentCharCreationRecoveryCount = 0

        // Silent recovery — no visible interruption for the player (the
        // narrative screen and breadcrumb dump this used to show are gone;
        // see logGlitch() above for where the detail still gets recorded).
        // Just continue as if nothing happened, same destination logic as
        // before: back into the game if there's one in progress, else main menu.
        if dungeon != nil && !party.isEmpty {
            gameState = .exploring
            currentCombat = nil
            showExplorationView()
        } else {
            resetGame()
        }
    }

    private var suppressMenuUntil: Date = .distantPast

    /// A fast double-tap on a button (finger bounce, or tapping again before
    /// the screen visibly reacts) can fire this handler twice for what the
    /// player experiences as one tap — in combat that means the same attack
    /// resolves twice and its report/log line appears duplicated. This is a
    /// short re-entrancy guard, separate from suppressMenuUntil (which is
    /// about long-press screen transitions, not rapid double-taps).
    private var lastMenuChoiceHandledAt: Date = .distantPast

    func handleMenuLongPress(_ choice: Int) {
        if timeFrozen && linkReturnSnapshot == nil { showFrozenNotice(); return }
        stopIdleAnimations()

        // Long-press on disabled buttons = dark/forced actions
        if choice >= 1 && choice <= currentMenuOptions.count {
            let option = currentMenuOptions[choice - 1]
            if option.isDisabled && !torchLit {
                switch option.text {
                // Wrapped the same way the D-pad's own Search/Listen corner
                // icons are: darkSearch()/searchRoom() print a result and
                // just set an autoReturn() timer rather than immediately
                // showing a menu again, which left the whole control box
                // (D-pad + buttons) empty until that timer eventually fired
                // — this restores it right away instead.
                case "Search Room": runPreservingDirectionExits { darkSearch() }; return
                case "Scavenge": runPreservingDirectionExits { searchRoom() }; return
                default: break
                }
            }
        }

        // Long-press on "Done" during active gameplay = return directly to game view
        if choice >= 1 && choice <= currentMenuOptions.count {
            let optionText = currentMenuOptions[choice - 1].text
            if optionText == "Done" && (gameState == .exploring || gameState == .combat) && dungeon != nil {
                DispatchQueue.main.async {
                    self.currentMenuOptions = []
                    self.directionExits = [:]
            self.securedExits = []
                }
                suppressMenuUntil = Date().addingTimeInterval(0.5)
                if gameState == .combat, currentCombat != nil {
                    advanceCombat()
                } else {
                    showExplorationView()
                }
                return
            }
        }

        if let handler = menuLongPressHandler {
            handler(sourceChoice(choice))
            suppressMenuUntil = Date().addingTimeInterval(0.8)
        } else if inHelpContext && menuHandler != nil {
            // Help pages: long-press any button → How to Play
            showHowToPlay()
        }
        // No dedicated long-press handler — do nothing. Buttons use
        // .simultaneousGesture for long-press detection (see regularButton
        // in TerminalView.swift), which means a plain tap held just past
        // longPressDuration fires BOTH this and the button's own tap action
        // for the same physical touch. Re-invoking menuHandler(choice) here
        // used to be an intentional fallback ("do something on long-press
        // regardless"), but combined with that dual-firing it meant a
        // slightly slow tap silently ran the tap's own handler TWICE — the
        // second, stale-index invocation landing on whatever screen the
        // first call had already built. That's what produced reports like
        // "Accept -> blank screen": e.g. finishCharacterCreation() adding a
        // character and building a new menu, then immediately being called
        // again by the long-press fallback with the same stale choice
        // number, which the new menu reinterpreted as a different button.
    }

    /// Match a voice transcript against current menu options and select the best match
    /// Levenshtein edit distance for fuzzy matching
    private func levenshteinDistance(_ s: String, _ t: String) -> Int {
        let sArr = Array(s), tArr = Array(t)
        let m = sArr.count, n = tArr.count
        if m == 0 { return n }
        if n == 0 { return m }
        var prev = Array(0...n)
        var curr = [Int](repeating: 0, count: n + 1)
        for i in 1...m {
            curr[0] = i
            for j in 1...n {
                let cost = sArr[i - 1] == tArr[j - 1] ? 0 : 1
                curr[j] = min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost)
            }
            prev = curr
        }
        return prev[n]
    }

    /// Single, authoritative way to leave Just DM (free-text) mode and
    /// return to normal button/D-pad play. Used by every "buttons on"
    /// trigger (typed command, voice command, the universal text-input
    /// check) so they can't drift into subtly different behaviour from
    /// each other — they used to be three separate hand-copied blocks.
    /// Always resolves against the CURRENT authoritative state
    /// (dungeon.currentRoom / currentCombat), never anything narrated —
    /// that authoritative state is exactly what SaveGame serializes, so
    /// it stays correct across a save/reload too. Also logs the exact
    /// room/combat it's returning to, so a mismatch between what the AI
    /// narrated and what's actually true is visible in the Adventure Log
    /// rather than just a silent surprise.
    private func exitJustDMMode() {
        justDMMode = false
        UserDefaults.standard.set(false, forKey: "justDMMode")
        DMEngine.shared.justDMMode = false
        inDMMode = false
        print("")
        print("  Buttons restored.", color: .brightGreen)
        if let combat = currentCombat {
            logEvent("Switched to menu mode (combat)", category: "SYSTEM")
            if let entry = combat.currentCombatant, entry.isPlayer {
                showPlayerCombatMenu(characterId: entry.id)
            } else {
                advanceCombat()
            }
        } else if let dungeon = dungeon, let room = dungeon.currentRoom {
            logEvent("Switched to menu mode in \(room.name)", category: "SYSTEM")
            showExplorationView()
        } else {
            showMainMenu()
        }
    }

    func handleVoiceMenuChoice(_ transcript: String) {
        let lower = transcript.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        guard !lower.isEmpty else { return }

        // Universal mode switch — buttons on/off
        let isButtonsOn = lower == "buttons on" || lower == "buttons" || lower == "button"
            || lower == "button on" || lower == "show buttons" || lower == "normal mode"
            || lower == "menu mode" || lower == "just dm off" || lower == "dm off"
            || lower == "text mode off"
            || lower.hasPrefix("buttons o")
        if isButtonsOn {
            if justDMMode {
                exitJustDMMode()
                return
            }
        }
        let isButtonsOff = lower == "buttons off" || lower == "button off" || lower == "no buttons"
            || lower == "hide buttons" || lower == "dm only" || lower == "dm mode"
            || lower == "just dm" || lower == "just dm on" || lower == "dm on"
            || lower == "text mode" || lower == "text mode on"
            || lower.hasPrefix("buttons of")
        if isButtonsOff {
            if justDMMode {
                print("  Already in text mode.", color: .dimGreen)
                return
            }
            let dm = DMEngine.shared
            if dm.hasAnyAI {
                justDMMode = true
                UserDefaults.standard.set(true, forKey: "justDMMode")
                dm.justDMMode = true
                dm.adLibLevel = .full
                print("  Text mode enabled. Type 'buttons on' to restore.", color: .brightGreen)
                if dungeon != nil {
                    showExplorationView()
                }
                return
            } else {
                print("  Requires an AI provider. Set up an API key in DM Settings.", color: .yellow)
                return
            }
        }

        // "done", "back", "return", "close", "go back", "b", "d" → trigger close handler or emergency exit
        let backWords: Set<String> = ["done", "back", "return", "close", "go back", "exit", "cancel", "b", "d"]
        if backWords.contains(lower) || lower.hasSuffix(" back") || lower.hasSuffix(" return") {
            if let handler = closeHandler {
                print("\"\(transcript)\" -> Back", color: .dimGreen)
                handler()
                return
            }
            // Fallback: on victory/defeat/combat, exit even without closeHandler
            if gameState == .victory || gameState == .gameOver || gameState == .combat {
                print("\"\(transcript)\" -> Back", color: .dimGreen)
                emergencyExit()
                return
            }
        }

        // "continue", "next", "ok", "okay" → tap to continue (inputHandler when waiting)
        let continueWords: Set<String> = ["continue", "next", "ok", "okay", "yes", "carry on"]
        if continueWords.contains(lower) {
            if let handler = inputHandler {
                print("\"\(transcript)\" -> Continue", color: .dimGreen)
                handler("")
                inputHandler = nil
                return
            }
        }

        let options = currentMenuOptions
        guard !options.isEmpty else {
            // No menu options — route to DM if available
            let dm = DMEngine.shared
            if dm.isConfigured || dm.isAppleModelAvailable {
                print("")
                print("  You:", color: .cyan, bold: true)
                printWrapped("  \(transcript)", indent: 2, color: .cyan)
                print("")
                print("  The DM considers...", color: .dimGreen)
                let context = buildDMContext()
                dm.ask(transcript, context: context) { [weak self] response in
                    DispatchQueue.main.async {
                        guard let self = self else { return }
                        self.print("")
                        self.print("  DM:", color: .yellow, bold: true)
                        for paragraph in response.components(separatedBy: "\n") {
                            let trimmed = paragraph.trimmingCharacters(in: .whitespaces)
                            if trimmed.isEmpty { self.print("") }
                            else { self.printWrapped("  \(trimmed)", indent: 2, color: .yellow) }
                        }
                    }
                }
            } else {
                let dmResponse = dmFallbackResponse(for: lower)
                print("")
                print("  The DM says:", color: .yellow, bold: true)
                printWrapped("  \"\(dmResponse)\"", indent: 2, color: .yellow)
            }
            return
        }

        // Helper to show visual press feedback, then trigger button after a short delay
        func selectButton(_ index: Int) {
            let opt = options[index - 1]
            self.print("\"\(transcript)\" -> \(opt.text)", color: .dimGreen)
            // Animate the button press visually
            DispatchQueue.main.async {
                self.pressedMenuIndex = index
            }
            // Delay to let the user see the press, then fire
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
                self?.pressedMenuIndex = nil
                self?.handleMenuChoice(index)
            }
        }

        // Number matching: "one", "button one", "number one", "first", "1" etc.
        let numberWords: [String: Int] = [
            "one": 1, "1": 1, "first": 1, "button one": 1, "number one": 1, "option one": 1,
            "two": 2, "2": 2, "second": 2, "button two": 2, "number two": 2, "option two": 2,
            "three": 3, "3": 3, "third": 3, "button three": 3, "number three": 3, "option three": 3,
            "four": 4, "4": 4, "fourth": 4, "button four": 4, "number four": 4, "option four": 4,
            "five": 5, "5": 5, "fifth": 5, "button five": 5, "number five": 5, "option five": 5,
            "six": 6, "6": 6, "sixth": 6, "button six": 6, "number six": 6, "option six": 6,
            "seven": 7, "7": 7, "seventh": 7, "button seven": 7, "number seven": 7, "option seven": 7,
            "eight": 8, "8": 8, "eighth": 8, "button eight": 8, "number eight": 8, "option eight": 8,
            "nine": 9, "9": 9, "ninth": 9, "button nine": 9, "number nine": 9, "option nine": 9,
            "ten": 10, "10": 10, "tenth": 10, "button ten": 10, "number ten": 10, "option ten": 10,
        ]
        if let num = numberWords[lower], num >= 1 && num <= options.count {
            if !options[num - 1].isDisabled {
                selectButton(num)
                return
            }
        }

        // Symbol aliases: voice "help" → "?", "more"/"next" → ">>", "back"/"previous" → "<<"
        let symbolAliases: [String: String] = ["help": "?", "more": ">>", "next page": ">>", "previous": "<<", "previous page": "<<"]
        if let symbol = symbolAliases[lower] {
            if let idx = options.firstIndex(where: { $0.text == symbol && !$0.isDisabled }) {
                selectButton(idx + 1)
                return
            }
        }

        // Level 1: exact match
        for (i, opt) in options.enumerated() where !opt.isDisabled {
            if opt.text.lowercased() == lower {
                selectButton(i + 1)
                return
            }
        }
        // Level 2: option starts with transcript
        for (i, opt) in options.enumerated() where !opt.isDisabled {
            if opt.text.lowercased().hasPrefix(lower) {
                selectButton(i + 1)
                return
            }
        }
        // Level 3: transcript contains option name
        for (i, opt) in options.enumerated() where !opt.isDisabled {
            if lower.contains(opt.text.lowercased()) {
                selectButton(i + 1)
                return
            }
        }
        // Level 4: option contains transcript
        for (i, opt) in options.enumerated() where !opt.isDisabled {
            if opt.text.lowercased().contains(lower) {
                selectButton(i + 1)
                return
            }
        }
        // Level 5: fuzzy match — tolerate 1 character difference (typos)
        if lower.count >= 3 {
            var bestIdx = -1
            var bestDist = Int.max
            for (i, opt) in options.enumerated() where !opt.isDisabled {
                let optLower = opt.text.lowercased()
                let dist = levenshteinDistance(lower, optLower)
                let threshold = max(1, optLower.count / 4)  // allow ~25% error
                if dist <= threshold && dist < bestDist {
                    bestDist = dist
                    bestIdx = i
                }
            }
            if bestIdx >= 0 {
                selectButton(bestIdx + 1)
                return
            }
        }
        // No button match — if awaiting text input, confirm before submitting
        if awaitingTextInput, let handler = inputHandler {
            print("")
            print("  Heard: \"\(transcript)\"", color: .yellow, bold: true)
            print("")
            showMenu(["Confirm", "Try Again"])
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                if choice == 1 {
                    DispatchQueue.main.async { self.awaitingTextInput = false }
                    handler(transcript)
                } else {
                    // Restore text input mode so user can try again
                    DispatchQueue.main.async { self.awaitingTextInput = true }
                }
            }
            return
        }

        // No match — in combat, redirect to chat with the message
        if gameState == .combat {
            showPartyChat(initialMessage: transcript)
            return
        }

        // If DM engine is available, give a real AI response; otherwise canned fallback
        // Clear screen and hide any image (e.g. dragon castle) for clean DM chat
        DispatchQueue.main.async { self.menuImageName = nil }
        clearTerminal()
        let dm = DMEngine.shared
        if dm.isConfigured || dm.isAppleModelAvailable {
            print("")
            print("You:", color: .cyan, bold: true)
            printWrapped("  \(transcript)", indent: 2, color: .cyan)
            print("")
            print("The DM considers...", color: .dimGreen)
            let context = buildDMContext()
            dm.ask(transcript, context: context) { [weak self] response in
                DispatchQueue.main.async {
                    guard let self = self else { return }
                    self.print("")
                    self.print("  DM:", color: .yellow, bold: true)
                    for paragraph in response.components(separatedBy: "\n") {
                        let trimmed = paragraph.trimmingCharacters(in: .whitespaces)
                        if trimmed.isEmpty { self.print("") }
                        else { self.printWrapped("  \(trimmed)", indent: 2, color: .yellow) }
                    }
                    if self.speakerModeOn {
                        SpeechEngine.shared.speak(response)
                        self.speakerHasReadCurrentPage = true
                    }
                }
            }
        } else {
            print("")
            print("You:", color: .cyan, bold: true)
            printWrapped("  \(transcript)", indent: 2, color: .cyan)
            let dmResponse = dmFallbackResponse(for: lower)
            print("")
            print("The DM says:", color: .yellow, bold: true)
            printWrapped("  \"\(dmResponse)\"", indent: 2, color: .yellow)
        }
    }

    /// Provide a helpful DM-style response for unmatched text input
    private func dmFallbackResponse(for input: String) -> String {
        // Navigation / exit words
        let navWords: Set<String> = ["done", "back", "return", "close", "exit", "cancel", "go back",
                                      "leave", "quit", "stop", "end", "escape", "flee", "run"]
        if navWords.contains(input) || input.hasSuffix(" back") || input.hasSuffix(" return") {
            let responses = [
                "There is nowhere to go right now. Choose from the options before you.",
                "The path behind you has closed. You must press on — use the buttons below.",
                "You cannot leave yet. Your choices lie before you, adventurer.",
            ]
            return responses.randomElement()!
        }

        // Help / confused
        let helpWords: Set<String> = ["help", "what", "huh", "how", "where", "why", "who", "?"]
        if helpWords.contains(input) || input.hasPrefix("what ") || input.hasPrefix("how ") || input.hasPrefix("where ") {
            return "Look to the buttons below — they show your available actions. Tap one to proceed."
        }

        // Greetings
        let greetWords: Set<String> = ["hello", "hi", "hey", "greetings", "yo", "sup"]
        if greetWords.contains(input) {
            let responses = [
                "Well met, adventurer. Now choose your next action from the options below.",
                "Greetings. The dungeon waits for no one — make your choice.",
                "Hail! Your options lie before you. Choose wisely.",
            ]
            return responses.randomElement()!
        }

        // Yes / No / Agree
        if input == "yes" || input == "no" || input == "ok" || input == "okay" || input == "sure" || input == "fine" {
            return "Noted. But I need you to choose one of the options below to continue."
        }

        // Inventory / status queries
        let statusWords: Set<String> = ["inventory", "stats", "status", "health", "hp", "gold", "map", "items", "gear", "equipment"]
        if statusWords.contains(input) {
            return "Use the Party Status button during exploration to check your party's condition, or open your Inventory."
        }

        // Attack / fight
        let fightWords: Set<String> = ["attack", "fight", "hit", "strike", "kill", "slay", "smash", "stab", "slash"]
        if fightWords.contains(input) || input.hasPrefix("attack ") || input.hasPrefix("kill ") {
            if gameState == .exploring {
                return "There is nothing to fight here. Explore the dungeon to find monsters — they will find you soon enough."
            }
            return "Eager for blood? Choose your action from the options below."
        }

        // Rest / heal
        let restWords: Set<String> = ["rest", "sleep", "heal", "camp", "recover"]
        if restWords.contains(input) {
            if gameState == .exploring {
                return "To rest, use the Rest button in the centre of the compass. Short rests heal hit dice; long rests restore the party fully."
            }
            return "Now is not the time for rest. Focus on your current situation."
        }

        // Default — flavourful catchall
        let defaults = [
            "I don't understand '\(input)'. Choose from the options shown below.",
            "The dungeon does not respond to '\(input)'. Your choices are shown below — pick one.",
            "'\(input.capitalized)'? That means nothing here. Use the buttons below, adventurer.",
            "Even the wisest DM cannot parse '\(input)'. Try the buttons instead.",
            "The ancient runes do not recognise '\(input)'. Your path forward lies in the buttons below.",
        ]
        return defaults.randomElement()!
    }

    /// Read all visible terminal text aloud via SpeechEngine
    /// - Single tap while speaking: pause. Single tap while paused: resume.
    /// - Rapid double-tap: restart from beginning.
    /// - Single tap while silent: start reading.
    func readScreenAloud() {
        let speech = SpeechEngine.shared
        guard speech.isAvailable else { return }

        // Toggle persistent speaker mode
        if speakerModeOn {
            // Turn off entirely
            speakerModeOn = false
            speakerPaused = false
            speech.stop()
            isSpeakingAloud = false
            speakingCheckTimer?.invalidate()
            speakingCheckTimer = nil
            recentlySpokenTexts.removeAll()
            return
        }

        // Turn on — read current screen and stay in mode
        speakerModeOn = true
        speakerPaused = false
        startReadingScreen()
    }

    /// Long-press: pause reading on this page, but re-engage on next screen change
    func pauseSpeaker() {
        guard speakerModeOn else { return }
        let speech = SpeechEngine.shared
        speech.stop()
        isSpeakingAloud = false
        speakerPaused = true
        speakingCheckTimer?.invalidate()
        speakingCheckTimer = nil
    }

    /// Auto-read the screen when speaker mode is on (call after screen changes)
    func autoReadIfSpeakerMode() {
        guard speakerModeOn else { return }
        // Only read once per page — skip if already read (in a fight, each
        // new turn's lines are read as they come)
        guard !speakerHasReadCurrentPage || (currentCombat != nil && terminalLines.count > speechFromLine) else { return }
        // Un-pause on screen change (clearTerminal resets both flags)
        speakerPaused = false
        let speech = SpeechEngine.shared
        speech.stop()
        // Small delay so terminal lines are populated
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { [weak self] in
            guard let self = self, !self.speakerPaused,
                  !self.speakerHasReadCurrentPage || (self.currentCombat != nil && self.terminalLines.count > self.speechFromLine) else { return }
            self.startReadingScreen()
        }
    }

    private func startReadingScreen() {
        let speech = SpeechEngine.shared
        let allLines = gatherScreenLines()
        speechFromLine = terminalLines.count
        // Filter out lines recently spoken (NPC greetings, repeated descriptions)
        let newLines = allLines.filter { line in
            !recentlySpokenTexts.contains(line)
        }
        guard !newLines.isEmpty else {
            speakerHasReadCurrentPage = true
            fireSpeechReadComplete()
            return
        }
        // Add new lines to the memory buffer (circular, max 10)
        for line in newLines {
            recentlySpokenTexts.append(line)
        }
        if recentlySpokenTexts.count > maxSpokenMemory {
            recentlySpokenTexts.removeFirst(recentlySpokenTexts.count - maxSpokenMemory)
        }
        let text = newLines.joined(separator: ". ")
        speakerHasReadCurrentPage = true
        // Real completion signal for autoReturn() (see speechReadCompleteHandler)
        // — fires on SpeechEngine's actual AVSpeechSynthesizerDelegate
        // "didFinish" callback, not a guessed delay.
        speech.onFinish = { [weak self] in self?.fireSpeechReadComplete() }
        speech.speakAloud(text)
        isSpeakingAloud = true
        startSpeakingCheck()
    }

    private func fireSpeechReadComplete() {
        if let handler = speechReadCompleteHandler {
            speechReadCompleteHandler = nil
            handler()
        }
    }

    private func startSpeakingCheck() {
        speakingCheckTimer?.invalidate()
        speakingCheckTimer = Timer.scheduledTimer(withTimeInterval: 0.3, repeats: true) { [weak self] _ in
            DispatchQueue.main.async {
                guard let self = self else { return }
                let speech = SpeechEngine.shared
                if !speech.isSpeaking && !speech.isPaused {
                    self.isSpeakingAloud = false
                    self.speakingCheckTimer?.invalidate()
                    self.speakingCheckTimer = nil
                    // Do NOT turn off speakerModeOn — it stays on
                }
            }
        }
    }

    /// Gather readable narrative text from the terminal, filtering out ASCII art, stats, and lists
    private func gatherScreenText() -> String {
        return gatherScreenLines().joined(separator: ". ")
    }

    /// Gather readable narrative lines from the terminal
    private func gatherScreenLines() -> [String] {
        // Extended set of art/decoration characters including block elements
        let artStr = "/\\|_+=#~<>^{}()[].:;*`\"─╔╗╠╣╚╝║✦✧★☆✓·▸☠☢█░▓▄▀▌▐▲▼◆◇●○■□▪▫◈◊♦♠♣♥⚔⚗⚡⚰⛊⛏☽☾⊕⊘⊗┌┐└┘├┤┬┴┼━┃╭╮╯╰"
        // HP/score pattern: digits/digits like "12/20"
        let hpPattern = try? NSRegularExpression(pattern: "\\d+/\\d+")
        // Combat/mechanics essentials — who's fighting, what roll, hit or
        // miss, damage dealt, resulting HP. These are printed in colours
        // (dimGreen, red) and digit-heavy formats ("d20 -> [15] +3 = 18 vs
        // AC 14") that the general narrative filters below exist
        // specifically to treat as decorative "stat noise" and drop — which
        // meant speaker mode silently skipped most of a combat turn (who
        // attacked whom, whether it hit, and the actual damage/HP) even
        // though "Damage:"/"HP" abbreviation-expansion further down was
        // clearly written assuming such lines WOULD reach it. Recognized by
        // keyword/pattern and let straight through, bypassing the colour
        // and letter-ratio checks (not the ASCII-art/table checks below,
        // which these lines pass naturally anyway).
        let combatKeywords = ["damage!", "critical", " attacks ", "defeated!", "unconscious!", "poisoned!", "appears!", "appear!", "looks fearsome", "looks weakened", "dead here"]
        // Map legend/key rows (see Dungeon.mapLegendLines) are bar-separated
        // "X=Label" pairs like "@=You  !=Danger  .=Empty" — a visual
        // reference the player can already see, not narration. Detected
        // structurally (every "  "-separated part matches symbol=Word)
        // rather than by keyword, so it doesn't matter which of the fixed
        // legend entries are showing.
        let legendPartPattern = try? NSRegularExpression(pattern: "^\\S{1,2}=[A-Za-z]+$")
        // A wrapped paragraph is read as one sentence, not a line at a time.
        var merged: [TerminalLine] = []
        for line in terminalLines[min(speechFromLine, terminalLines.count)...] {
            if line.continuesPrevious, var last = merged.popLast() {
                last.text = last.text.trimmingCharacters(in: .whitespaces) + " " + line.text.trimmingCharacters(in: .whitespaces)
                merged.append(last)
            } else {
                merged.append(line)
            }
        }
        let lines = merged.compactMap { line -> String? in
            let trimmed = line.text.trimmingCharacters(in: .whitespaces)
            guard !trimmed.isEmpty else { return nil }
            // "Continue?"-style nudges and tap hints aren't story: skip them —
            // in a fight, a quick cheer instead.
            if Self.continueTitles.contains(trimmed) || Self.combatContinueTitles.contains(trimmed) {
                return currentCombat != nil ? Self.combatCheers.randomElement() : nil
            }
            let lowerHint = trimmed.lowercased()
            if trimmed.hasPrefix("•") && (lowerHint.contains("tap") || lowerHint.contains("click") || lowerHint.contains("press")) {
                return nil
            }

            if let legendPartPattern = legendPartPattern {
                let core = trimmed.trimmingCharacters(in: CharacterSet(charactersIn: "|")).trimmingCharacters(in: .whitespaces)
                let parts = core.components(separatedBy: "  ").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
                if !parts.isEmpty && parts.allSatisfy({ part in
                    let range = NSRange(part.startIndex..., in: part)
                    return legendPartPattern.firstMatch(in: part, range: range) != nil
                }) {
                    return nil
                }
            }

            // Lines containing quoted speech are always readable
            let hasQuote = trimmed.contains("\"") || trimmed.contains("\u{201C}") || trimmed.contains("\u{201D}")

            let lower = trimmed.lowercased()
            let hasDigit = trimmed.contains(where: { $0.isNumber })
            let isCombatEssential = combatKeywords.contains(where: { lower.contains($0) })
                || lower == "hit!" || lower == "miss." || lower.hasPrefix("miss ")
                || (hasDigit && (lower.contains(" hp") || lower.hasSuffix("hp") || lower.contains("hp:") || lower.contains("hp)")))
                || (hasDigit && lower.contains("vs ac"))
                || (hasDigit && lower.contains("d20 ->"))
            // Inventory bag rows ("[W] Longsword — 3.0lb, 15gp") and short
            // labelled stat lines ("Gold: 120", "Carry Weight: 45 / 150 lb")
            // are exactly the kind of digit-heavy content the letter-ratio
            // check below exists to drop — a short item name or a bigger
            // gold value tips the ratio under 50% easily, silently dropping
            // some bag items/stats but not others depending on their exact
            // length. Recognized structurally so the whole inventory reads
            // out consistently rather than partially.
            let isInventoryBagRow = ["[W]", "[A]", "[S]", "[P]", "[?]", "[$]", "[.]"].contains(where: { trimmed.hasPrefix($0) })
            let isLabelledStat = trimmed.range(of: "^[A-Za-z][A-Za-z ]{0,24}:\\s*\\S", options: .regularExpression) != nil
            let isForcedReadable = isCombatEssential || isInventoryBagRow || isLabelledStat

            // Only read narrative/informative colours
            // Skip: dimGreen (nav hints), gray (decorative), red (damage numbers)
            if !hasQuote && !isForcedReadable {
                switch line.color {
                case .yellow, .white, .green, .brightGreen, .cyan, .orange, .magenta:
                    break  // these can contain readable content
                case .dimGreen, .gray, .red:
                    return nil
                }
            }

            // Skip NPC name labels (bold brightGreen short lines like "  Hermit")
            if line.color == .brightGreen && line.isBold && trimmed.count < 25 {
                return nil
            }

            // Skip very short non-word lines (decorative elements)
            if trimmed.count <= 3 && !trimmed.contains(where: { $0.isLetter }) {
                return nil
            }

            // Skip lines that are mostly ASCII art/decoration (>25% special chars)
            let specialCount = trimmed.filter { artStr.contains($0) }.count
            if trimmed.count > 2 && Double(specialCount) / Double(trimmed.count) > 0.25 {
                return nil
            }

            if !isForcedReadable {
                // Skip lines with no readable text
                let letterCount = trimmed.filter { $0.isLetter }.count
                if letterCount == 0 { return nil }
                // Lines need at least 50% letters to be narrative (filters stat lines)
                if trimmed.count > 5 && Double(letterCount) / Double(trimmed.count) < 0.5 {
                    return nil
                }

                // Skip table/stat lines containing HP-style "X/Y" patterns with padded spacing
                if let regex = hpPattern {
                    let range = NSRange(trimmed.startIndex..., in: trimmed)
                    if regex.firstMatch(in: trimmed, range: range) != nil {
                        // Only skip if it looks like a status line (has padding/alignment)
                        if trimmed.contains("  ") { return nil }
                    }
                }
            }

            // Skip table-like lines (mostly dashes/pipes)
            let dashCount = trimmed.filter { $0 == "-" || $0 == "─" || $0 == "|" || $0 == "║" }.count
            if trimmed.count > 5 && Double(dashCount) / Double(trimmed.count) > 0.25 {
                return nil
            }

            // Strip remaining decorative characters but keep readable content
            var cleaned = trimmed.filter { char in
                char.isLetter || char.isNumber || char.isWhitespace ||
                char == "," || char == "." || char == "!" || char == "?" ||
                char == ":" || char == ";" || char == "'" || char == "\"" || char == "-" ||
                char == "(" || char == ")" || char == "/" || char == "%" ||
                char == "+" || char == "&"
            }.trimmingCharacters(in: .whitespaces)

            // Expand common abbreviations for natural speech
            cleaned = cleaned
                .replacingOccurrences(of: "HP ", with: "hit points ")
                .replacingOccurrences(of: "HP:", with: "hit points:")
                .replacingOccurrences(of: "AC ", with: "armour class ")
                .replacingOccurrences(of: "AC:", with: "armour class:")
                .replacingOccurrences(of: "ATK:", with: "attack bonus:")
                .replacingOccurrences(of: "DMG:", with: "damage:")
                .replacingOccurrences(of: "CR:", with: "challenge rating:")
                .replacingOccurrences(of: "XP ", with: "experience ")
                .replacingOccurrences(of: "XP:", with: "experience:")
                .replacingOccurrences(of: "STR", with: "strength")
                .replacingOccurrences(of: "DEX", with: "dexterity")
                .replacingOccurrences(of: "CON", with: "constitution")
                .replacingOccurrences(of: "INT", with: "intelligence")
                .replacingOccurrences(of: "WIS", with: "wisdom")
                .replacingOccurrences(of: "CHA", with: "charisma")
                .replacingOccurrences(of: "DM ", with: "dungeon master ")
                .replacingOccurrences(of: "NPC", with: "non-player character")
                .replacingOccurrences(of: "Prof", with: "proficiency")
                .replacingOccurrences(of: "vs ", with: "versus ")
                .replacingOccurrences(of: "d20", with: "dee twenty")
                .replacingOccurrences(of: "d12", with: "dee twelve")
                .replacingOccurrences(of: "d10", with: "dee ten")
                .replacingOccurrences(of: "d8", with: "dee eight")
                .replacingOccurrences(of: "d6", with: "dee six")
                .replacingOccurrences(of: "d4", with: "dee four")
                .replacingOccurrences(of: "1d", with: "one dee ")
                .replacingOccurrences(of: "2d", with: "two dee ")
                .replacingOccurrences(of: "3d", with: "three dee ")
                .replacingOccurrences(of: "4d", with: "four dee ")
                .replacingOccurrences(of: " ft", with: " feet")
                .replacingOccurrences(of: " GP", with: " gold pieces")
                .replacingOccurrences(of: " gp", with: " gold pieces")
                .replacingOccurrences(of: "gatekeeper", with: "gate keeper")
                .replacingOccurrences(of: "Gatekeeper", with: "Gate Keeper")
                .replacingOccurrences(of: "Choose", with: "Chooze")

            return cleaned.isEmpty ? nil : cleaned
        }
        return lines
    }

    func handleDirectionChoice(_ direction: Direction) {
        if timeFrozen { showFrozenNotice(); return }
        recordAction("went \(direction.rawValue)")
        stopIdleAnimations()
        // Must be synchronous (runOnMain), not DispatchQueue.main.async: the
        // old async wipe was queued to run on a LATER turn of the run loop,
        // but directionHandler below runs synchronously and typically ends
        // by calling showExplorationView() — which itself synchronously
        // repopulates currentMenuOptions/directionExits for the new room.
        // The deferred wipe then ran AFTER that, clobbering the freshly
        // rendered screen back to empty and leaving the whole control box
        // (D-pad + buttons) gone until something else happened to redraw —
        // most noticeable moving in the dark, where nothing else nudges a
        // redraw afterward. Doing this synchronously first, before
        // directionHandler runs, means there's nothing left to race.
        runOnMain {
            self.currentMenuOptions = []
            self.directionExits = [:]
            self.securedExits = []
        }

        if let handler = directionHandler {
            handler(direction)
        }
    }

    func handleTextInput(_ text: String) {
        stopIdleAnimations()
        var trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)

        // Voice input often transcribes a number as words ("eighty", "one
        // hundred and eighty") rather than digits — Apple's speech
        // recognizer doesn't reliably auto-digitize them. Normalize to
        // digits so anything downstream parsing with Int(...) (e.g. the
        // haggle price prompt) still recognizes it as a number. Only
        // touches text that's entirely a spoken number (plus an optional
        // trailing unit word like "gold"), so ordinary typed or free-text
        // input is never altered.
        if Int(trimmed) == nil, let spoken = Self.parseSpokenNumber(trimmed) {
            trimmed = String(spoken)
        }

        // Time frozen: nobody can hear you — ask to unfreeze first, and send
        // what was typed once they say yes.
        if timeFrozen && !trimmed.isEmpty {
            let answer = trimmed.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: ".!"))
            let yes = ["yes", "y", "yes please", "yeah", "yep", "ok", "okay", "sure", "unfreeze", "unpause", "resume", "unfreeze time"]
            let no = ["no", "n", "nope", "not yet", "stay frozen", "keep frozen"]
            if yes.contains(answer) {
                let pending = frozenPendingText
                toggleAutoContinuePause()   // unfreezes (and forgets frozenPendingText)
                print("")
                print("  Time flows again.", color: .cyan, bold: true)
                if let pending = pending { handleTextInput(pending) }
                return
            }
            if no.contains(answer) && frozenPendingText != nil {
                frozenPendingText = nil
                removeFrozenNotice()
                print("")
                printWrapped("Time stays frozen. Tap the orange hourglass whenever you're ready.", indent: 2, color: .dimGreen)
                return
            }
            frozenPendingText = trimmed
            removeFrozenNotice()
            let start = terminalLines.count
            print("")
            print("  TIME IS FROZEN", color: .yellow, bold: true)
            printWrapped("Nobody can hear you while time stands still — not even the DM. Unfreeze time first? Type \"yes\" to unfreeze and carry on with \"\(trimmed)\", or tap the orange hourglass.", indent: 4, color: .dimGreen)
            frozenNoticeRange = start..<terminalLines.count
            frozenNoticeGeneration = screenGeneration
            return
        }

        // Universal mode switch — always works regardless of screen
        let lowerCheck = trimmed.lowercased()
        if lowerCheck == "buttons on" || lowerCheck == "buttons" || lowerCheck == "button"
            || lowerCheck == "button on" || lowerCheck == "show buttons" || lowerCheck == "normal mode"
            || lowerCheck == "menu mode" || lowerCheck == "just dm off" || lowerCheck == "dm off"
            || lowerCheck == "text mode off"
            || lowerCheck.hasPrefix("buttons o") {
            if justDMMode {
                exitJustDMMode()
                return
            }
        }
        if lowerCheck == "buttons off" || lowerCheck == "button off" || lowerCheck == "no buttons"
            || lowerCheck == "hide buttons" || lowerCheck == "dm only" || lowerCheck == "dm mode"
            || lowerCheck == "just dm" || lowerCheck == "just dm on" || lowerCheck == "dm on"
            || lowerCheck == "text mode" || lowerCheck == "text mode on"
            || lowerCheck.hasPrefix("buttons of") {
            let dm = DMEngine.shared
            if dm.hasAnyAI && !justDMMode {
                justDMMode = true
                UserDefaults.standard.set(true, forKey: "justDMMode")
                dm.justDMMode = true
                dm.adLibLevel = .full
                print("  Text mode enabled. Type 'buttons on' to restore.", color: .brightGreen)
                if dungeon != nil {
                    showExplorationView()
                }
                return
            } else if !dm.hasAnyAI {
                print("  Requires an AI provider. Set up an API key in DM Settings.", color: .yellow)
                return
            }
        }

        // Typed on a tap-to-continue screen: 'go on' (and friends) simply
        // continues; anything else is acknowledged, the screen moves on,
        // and then it's acted on as a command there — it used to just
        // continue and silently drop what was typed.
        if awaitingContinue && !trimmed.isEmpty && !chatInputMode {
            let continueWords: Set<String> = ["go on", "continue", "next", "ok", "okay", "go", "on", "more", "c", "carry on", "onward", "onwards"]
            // "g- -n", "g0 0n": the dragon's winks sometimes leave a dash (or
            // a zero) where an o should be — still means go on.
            let unwinked = trimmed.lowercased().replacingOccurrences(of: "-", with: "o").replacingOccurrences(of: "0", with: "o")
            if continueWords.contains(trimmed.lowercased()) || continueWords.contains(unwinked) {
                handleContinue()
                return
            }
            print("> \(trimmed)", color: .dimGreen)
            let command = trimmed
            handleContinue()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { [weak self] in
                guard let self = self, !self.awaitingContinue else { return }
                self.handleTextInput(command)
            }
            return
        }

        // Keep keyboard open in chat mode; dismiss otherwise
        if !chatInputMode {
            DispatchQueue.main.async {
                self.awaitingTextInput = false
            }
        }
        // Don't echo input here when an inputHandler is set — the handler manages its own display
        if inputHandler == nil {
            print("> \(trimmed)", color: .dimGreen)
        }

        // Shortcut commands — intercept before handlers
        let lower = trimmed.lowercased()
        if !chatInputMode && inputHandler == nil {
            // Typing a button's own name (or its first word) presses it —
            // handy with buttons hidden, and for anyone who'd rather type.
            if let idx = currentMenuOptions.firstIndex(where: { option in
                let label = option.text.lowercased()
                return !option.isCompactNav && !option.isDisabled && (label == lower || label.hasPrefix(lower + " "))
            }) {
                handleMenuChoice(idx + 1)
                return
            }
            // Easter egg: about:dndRPG — instant victory with fabricated stats
            if lower == "about:dndrpg" {
                setupEasterEggVictory()
                return
            }

            if lower == "settings" || lower == "options" || lower == "config" {
                showSettings()
                return
            }
            if lower == "about" {
                showAbout()
                return
            }
            if lower == "hall of fame" || lower == "fame" || lower == "hof" {
                showHallOfFame()
                return
            }
            if lower == "how to play" || lower == "how" || lower == "tutorial" {
                showHowToPlay()
                return
            }
            if lower == "bestiary" || lower == "monsters" {
                showBestiary()
                return
            }
            if lower == "gallery" || lower == "lore" || lower == "names" {
                showGalleryAndLore()
                return
            }
            if lower == "chat" || lower == "talk" || lower == "dm" || lower == "dungeon master" {
                if dungeon != nil {
                    showPartyChat()
                } else {
                    print("  Start an adventure first!", color: .yellow)
                }
                return
            }
            if lower == "help" {
                // Find and trigger Help button if present
                if let helpIdx = currentMenuOptions.firstIndex(where: { $0.text == "?" || $0.text == "Help" }) {
                    handleMenuChoice(helpIdx + 1)
                    return
                }
            }
            if lower == "save" || lower == "save game" {
                if dungeon != nil {
                    quickSave()
                    return
                }
            }
            if lower == "load" || lower == "load game" {
                showLoadGameMenu(returnTo: .exploration)
                return
            }
            if lower == "inventory" || lower == "i" || lower == "pack" || lower == "items" {
                if dungeon != nil {
                    showInventory()
                    return
                }
            }
            if lower == "party" || lower == "party status" || lower == "status" {
                if dungeon != nil {
                    showPartyStatus()
                    return
                }
            }
            if lower == "map" {
                if dungeon != nil, gameState == .exploring {
                    printExplorationMap()
                    return
                }
            }
            if lower == "quit" || lower == "exit" || lower == "main menu" || lower == "menu" {
                if let close = closeHandler {
                    close()
                    return
                }
            }
            if lower == "new game" || lower == "new adventure" || lower == "new" {
                if gameState == .mainMenu {
                    startNewGame()
                    return
                }
            }
            // Directional movement shortcuts: N/S/E/W, north, go north, etc.
            if gameState == .exploring, dungeon != nil {
                let dirMap: [String: Direction] = [
                    "n": .north, "s": .south, "e": .east, "w": .west,
                    "north": .north, "south": .south, "east": .east, "west": .west,
                    "go north": .north, "go south": .south, "go east": .east, "go west": .west,
                    "move north": .north, "move south": .south, "move east": .east, "move west": .west,
                ]
                if let dir = dirMap[lower], let dungeon = dungeon, let room = dungeon.currentRoom {
                    if let nextId = room.exits[dir], let _ = dungeon.rooms[nextId] {
                        let _ = dungeon.move(direction: dir)
                        showExplorationView()
                        return
                    } else {
                        print("  There is no exit to the \(dir.rawValue.lowercased()).", color: .yellow)
                        return
                    }
                }
            }
        }

        if let handler = inputHandler {
            handler(trimmed)
        } else if !currentMenuOptions.isEmpty {
            // Route text input to menu matching when on a menu screen
            handleVoiceMenuChoice(trimmed)
        }
    }

    func handleContinue() {
        guard awaitingContinue else { return }
        if timeFrozen { showFrozenNotice(); return }
        awaitingContinue = false
        // Moving on: the voice moves on too.
        if speakerModeOn { SpeechEngine.shared.stop() }
        continueHintTimer?.invalidate()
        if pausedForTyping {
            // A pause that only happened because you were typing ends here.
            pausedForTyping = false
            autoContinuePaused = false
            autoCountdownPausedRemaining = nil
        }
        fullScreenTapToContinue = false
        stopIdleAnimations()
        if let handler = inputHandler {
            inputHandler = nil
            handler("")
        }
    }

    // MARK: - Idle Animations

    private var idleTimer: Timer?
    private var idleAnimTimer: Timer?
    private var idleOriginals: [(index: Int, text: String)] = []

    /// Eye patterns and their wink/blink replacements (tried in order, first match wins)
    private static let eyePatterns: [(find: String, winkL: String, winkR: String, blink: String)] = [
        // Wide-spaced eyes
        ("o   o", "-   o", "o   -", "-   -"),
        ("O   O", "-   O", "O   -", "-   -"),
        ("x   x", "-   x", "x   -", "-   -"),
        (".   .", "-   .", ".   -", "-   -"),
        // Medium-spaced
        ("O  O",  "-  O",  "O  -",  "-  -"),
        ("o  o",  "-  o",  "o  -",  "-  -"),
        ("@  @",  "-  @",  "@  -",  "-  -"),
        // Dotted/underscored
        ("o.o", "-.o", "o.-", "-.-"),
        ("o_o", "-_o", "o_-", "-_-"),
        // Close eyes
        ("o o", "- o", "o -", "- -"),
        ("oo",  "-o",  "o-",  "--"),
        ("OO",  "-O",  "O-",  "--"),
        // Special
        ("><",  ">-",  "-<",  "--"),
        ("( O )", "( - )", "( - )", "( - )"),
        ("(@::@)", "(-::@)", "(@::-)", "(-::-)"),
    ]

    func resetIdleTimer() {
        idleTimer?.invalidate()
        revertIdleLines()
        idleAnimTimer?.invalidate()
        idleAnimTimer = nil

        guard idlePromptsEnabled else { return }
        idleTimer = Timer.scheduledTimer(withTimeInterval: 4.0, repeats: false) { [weak self] _ in
            self?.startIdleAnimations()
        }
        scheduleExplorationTip()
    }

    // MARK: Exploration tips
    //
    // Idle on the exploration screen for a while (Idle Prompts on): one tip
    // per screen — about this room if there's an NPC or a gym here, otherwise
    // a varied general one (quests, gyms, merchants, food, torches).
    private var explorationTipTimer: Timer?
    private var explorationTipGeneration = -1

    private func scheduleExplorationTip() {
        explorationTipTimer?.invalidate()
        explorationTipTimer = Timer.scheduledTimer(withTimeInterval: 25, repeats: false) { [weak self] _ in
            guard let self = self, self.idlePromptsEnabled, !self.timeFrozen, !self.directionExits.isEmpty, !self.awaitingContinue,
                  self.currentCombat == nil, !(self.isJustDMActive && self.inDMMode),
                  self.explorationTipGeneration != self.screenGeneration else { return }
            self.explorationTipGeneration = self.screenGeneration
            self.print("")
            self.printWrapped("Tip: \(self.explorationTip())", indent: 2, color: .dimGreen)
        }
    }

    /// From here to the nearest room matching `want`, through open passages:
    /// the first direction to take and how many rooms away. nil if none.
    func routeToNearest(where want: (Room) -> Bool) -> (direction: Direction, rooms: Int, room: Room)? {
        guard let dungeon = dungeon, let start = dungeon.currentRoom else { return nil }
        var seen: Set<Int> = [start.id]
        var queue: [(id: Int, first: Direction?, dist: Int)] = [(start.id, nil, 0)]
        var head = 0
        while head < queue.count {
            let (id, first, dist) = queue[head]
            head += 1
            guard let room = dungeon.rooms[id] else { continue }
            if dist > 0, let first = first, want(room) { return (first, dist, room) }
            for (dir, next) in room.exits where !seen.contains(next) {
                seen.insert(next)
                queue.append((next, first ?? dir, dist + 1))
            }
        }
        return nil
    }

    func directionWord(_ dir: Direction) -> String {
        let names = ["N": "north", "S": "south", "E": "east", "W": "west", "U": "up", "D": "down"]
        return names[dir.rawValue.uppercased()] ?? dir.rawValue.lowercased()
    }

    /// "head north, 3 rooms away" / "just through the north passage".
    private func wayThere(_ route: (direction: Direction, rooms: Int, room: Room)) -> String {
        let dir = directionWord(route.direction)
        return route.rooms == 1 ? "just through the \(dir) passage" : "head \(dir) — about \(route.rooms) rooms away"
    }

    /// A pointer towards something worth doing: a quest-giver if the party
    /// has room for a quest, else where a quest's target lies.
    private func questPointer() -> String? {
        if canTakeAnotherQuest, npcsEnabled,
           let route = routeToNearest(where: { room in
               guard let npc = room.npc else { return false }
               return npc.type != .gatekeeper && !npc.sideQuestOffered && npc.willOfferSideQuest != false
                   && !self.allQuests.contains { $0.giverName == npc.type.rawValue }
           }), let npc = route.room.npc {
            let opener = allQuests.isEmpty ? "You're not on a quest yet." : "There's room for another quest."
            return "\(opener) \(npc.displayName) might have one — \(wayThere(route))."
        }
        if let quest = allQuests.first(where: { $0.type == .visitRoomType && !isSideQuestComplete($0) }),
           let type = quest.targetRoomType, let route = routeToNearest(where: { $0.roomType == type }) {
            return "For \(quest.giverName)'s quest, a \(type.rawValue.lowercased()) lies that way: \(wayThere(route))."
        }
        if let quest = allQuests.randomElement() {
            return "Quest for \(quest.giverName): \(quest.description). \(sideQuestProgressDescription(quest))."
        }
        return nil
    }

    private func explorationTip() -> String {
        let room = dungeon?.currentRoom
        // Mostly, adventurers should be on a quest — point the way.
        if let pointer = questPointer(), room?.npc == nil || room?.npc?.hasBeenTalkedTo == true, Int.random(in: 1...10) <= 7 {
            return pointer
        }
        if let npc = room?.npc, !npc.hasBeenTalkedTo {
            return "\(npc.displayName) is here. Ask if they have a quest for you — you'll win prizes and progress as a character."
        }
        if room?.trainer != nil {
            return "There's a gym here — train to learn new skills or sharpen the ones you have."
        }
        return Self.pickVaried([
            "Ask anyone you meet if they have a quest for you — quests win prizes and help you progress as a character.",
            "Don't forget to train at any gyms you find: learn new skills, or enhance the ones you have.",
            "Merchants sometimes keep rarer goods under the counter — it never hurts to ask.",
            "Rest when you're hurt — and eat something: hearty food makes you feel strong.",
            "A lit torch lets you see further on the map.",
            "Stuck? Long-press a button to see what shortcut it has.",
        ], avoiding: &lastExplorationTip)
    }

    private func startIdleAnimations() {
        guard !reduceAnimations else { return }
        idleAnimTimer = Timer.scheduledTimer(withTimeInterval: 2.5, repeats: true) { [weak self] _ in
            self?.playIdleAnimation()
        }
        playIdleAnimation()
    }

    private func playIdleAnimation() {
        DispatchQueue.main.async { [weak self] in
            guard let self = self else { return }

            // Revert any previous animation
            self.revertIdleLines()

            // Find lines with eye patterns (skip short patterns inside words)
            var candidates: [Int] = []
            for (i, line) in self.terminalLines.enumerated() {
                // Only the pictures wink — unless Dungeon Quirks lets the
                // winks wander into the words ("g- -n").
                guard self.dungeonQuirksEnabled || line.isDecorativeArt else { continue }
                if Self.eyePatterns.contains(where: {
                    line.text.contains($0.find) && self.isPatternInAsciiArt(line.text, pattern: $0.find)
                }) {
                    candidates.append(i)
                }
            }
            guard let idx = candidates.randomElement() else { return }

            let original = self.terminalLines[idx].text
            if let animated = self.idleTransform(original) {
                self.idleOriginals.append((index: idx, text: original))
                self.terminalLines[idx].text = animated
            }
        }
    }

    /// Check if a pattern match is safe to animate (not inside a normal word)
    private func isPatternInAsciiArt(_ text: String, pattern: String) -> Bool {
        // Short patterns like "oo", "OO" can match inside words — only allow
        // if not surrounded by letters (i.e., the match is in ASCII art context)
        guard pattern.count <= 2 else { return true }  // Longer patterns are fine
        guard let range = text.range(of: pattern) else { return false }

        let before: Swift.Character = range.lowerBound > text.startIndex ? text[text.index(before: range.lowerBound)] : " "
        let after: Swift.Character = range.upperBound < text.endIndex ? text[range.upperBound] : " "
        if before.isLetter || after.isLetter { return false }
        // Skip lines that are mostly text (not ASCII art)
        let letterCount = text.filter { $0.isLetter }.count
        if letterCount > text.count / 2 { return false }
        return true
    }

    private func idleTransform(_ text: String) -> String? {
        for pattern in Self.eyePatterns {
            if text.contains(pattern.find) && isPatternInAsciiArt(text, pattern: pattern.find) {
                let doBlink = Int.random(in: 1...10) <= 3  // 30% blink
                if doBlink {
                    return text.replacingOccurrences(of: pattern.find, with: pattern.blink)
                } else {
                    let wink = Bool.random() ? pattern.winkL : pattern.winkR
                    return text.replacingOccurrences(of: pattern.find, with: wink)
                }
            }
        }
        return nil
    }

    private func revertIdleLines() {
        for saved in idleOriginals {
            if saved.index < terminalLines.count {
                terminalLines[saved.index].text = saved.text
            }
        }
        idleOriginals.removeAll()
    }

    func stopIdleAnimations() {
        idleTimer?.invalidate()
        idleTimer = nil
        idleAnimTimer?.invalidate()
        idleAnimTimer = nil
        revertIdleLines()
    }

    // MARK: - Game Start

    func startGame() {
        GameCenterManager.shared.authenticatePlayer()
        GameCenterManager.shared.turnBasedDelegate = self
        // Roster first — repairOrphanEntries can read the roster (to
        // rebuild legacy parties), and that read creates the roster's
        // folder, which seedCharacterRosterIfEmpty uses to tell a fresh
        // install apart from one that's simply been emptied.
        seedCharacterRosterIfEmpty()
        HallOfFameManager.shared.seedIfEmpty()
        HallOfFameManager.shared.repairOrphanEntries()
        // Sync sound settings from UserDefaults
        SoundManager.shared.battleSoundsEnabled = battleSoundsEnabled
        DMEngine.shared.justDMMode = justDMMode
        clearTerminal()
        showMainMenu()
    }

    /// First-run only: gives the Character Roster (and Character Hall of
    /// Fame) something to load right away — one Level 1 example of each
    /// class — instead of starting completely empty. Mirrors
    /// HallOfFameManager.seedIfEmpty()'s "give new players something to
    /// explore" role, one layer down.
    private func seedCharacterRosterIfEmpty() {
        // Once ever, on a genuinely fresh install — never again just
        // because the roster happens to be empty, or deleting every
        // character would bring the starter six straight back on the next
        // launch. An install whose roster folder already exists has been
        // used before, even if it's empty now. Checked before
        // listCharacters(), whose own directory getter creates that folder.
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: "characterRosterSeedDone") else { return }
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!
        let usedBefore = FileManager.default.fileExists(atPath: docs.appendingPathComponent("SavedCharacters").path)
        defaults.set(true, forKey: "characterRosterSeedDone")
        guard !usedBefore, CharacterLibraryManager.shared.listCharacters().isEmpty else { return }

        let starters: [(name: String, race: Race, cls: CharacterClass)] = [
            ("Bram", .human, .fighter),
            ("Sable", .highElf, .wizard),
            ("Pip", .lightfootHalfling, .rogue),
            ("Wren", .hillDwarf, .cleric),
            ("Kestrel", .woodElf, .ranger),
            ("Ursa", .halfOrc, .barbarian),
        ]

        for starter in starters {
            let sorted = AbilityScores.standardArray.sorted(by: >)
            var scores = AbilityScores(strength: 10, dexterity: 10, constitution: 10, intelligence: 10, wisdom: 10, charisma: 10)
            for (idx, ability) in starter.cls.abilityPriority.enumerated() {
                scores.set(ability, to: sorted[idx])
            }
            for (ability, bonus) in starter.race.abilityBonuses {
                scores.set(ability, to: scores.score(for: ability) + bonus)
            }

            let character = Character(name: starter.name, race: starter.race, characterClass: starter.cls, abilityScores: scores)
            let skills = Array(starter.cls.skillChoices.shuffled().prefix(starter.cls.numSkillChoices))
            for skill in skills { character.skillProficiencies.insert(skill) }
            character.gold = Dice.rollSum(4, d: 4) * 10

            let equipOptions = ItemCatalog.startingEquipmentOptions(for: starter.cls)
            if let (_, items) = equipOptions.first {
                for item in items { _ = character.addItem(item) }
            }
            autoEquip(character)

            let startingSpells = SpellCatalog.startingSpells(for: starter.cls)
            if !startingSpells.isEmpty {
                character.knownSpells = startingSpells
                character.spellSlots = SpellCatalog.startingSlots(for: starter.cls, level: 1)
            }
            if starter.cls == .barbarian {
                character.rageUsesRemaining = character.rageMaxUses
            }

            CharacterLibraryManager.shared.save(character)
            CharacterHallOfFameManager.shared.addEntry(CharacterHallOfFameEntry(
                date: Date(),
                characterName: character.name,
                race: character.race.rawValue,
                characterClass: character.characterClass.rawValue,
                level: 1,
                gold: character.gold,
                dungeonName: "Starter Kit",
                dungeonLevel: 1,
                linkedCharacterId: character.id
            ))
        }
    }

    // MARK: - Main Menu

    func showMainMenu() {
        linkReturnSnapshot = nil
        // Text mode (buttons off) only drives the adventure itself — menus
        // like this one keep their buttons, so the game is usable straight
        // after Tap to Begin.
        inDMMode = false
        gameState = .mainMenu
        if self.musicEnabled { SoundManager.shared.startMusic(.menu, preference: self.menuMelodyChoice) }

        if checkForPendingCrashReport() { return }

        renderMainMenu()

        // Async check for pending multiplayer invites — refresh menu if found
        if multiplayerEnabled && GameCenterManager.shared.isAuthenticated {
            checkForPendingInvites()
            // Re-check periodically while on main menu (Game Center events are unreliable)
            startInvitePollTimer()
        }
    }

    // MARK: - Main Menu Animation

    private var menuAnimTimer: Timer?

    private func stopMenuAnimation() {
        menuAnimTimer?.invalidate()
        menuAnimTimer = nil
    }

    private func renderMainMenu() {
        clearTerminal()
        stopMenuAnimation()
        print("")
        print("")
        print("D&D 5e ASCII Adventure", color: .brightGreen, bold: true, centered: true)
        print("A text-based role-playing game", color: .dimGreen, centered: true)
        print("")

        // Dragon & castle art on the opening screen
        DispatchQueue.main.async {
            self.menuImageName = "DragonCastle"
        }
        print("")

        if justDMMode {
            printWrapped("Text mode is on: menus keep their buttons, and once you're in the dungeon you simply type what you do — the DM will give you clues. You can also type any button's name here. Type \"buttons on\" to switch text mode off.", indent: 2, color: .cyan)
            print("")
        }

        let hasActiveGame = dungeon != nil && !party.isEmpty

        // Build menu dynamically based on settings
        var menuOptions: [MenuOption] = []
        var actions: [() -> Void] = []

        if hasActiveGame {
            menuOptions.append(MenuOption("Continue Quest"))
            actions.append { [weak self] in self?.showExplorationView() }
        }
        menuOptions.append(MenuOption("Play"))
        actions.append { [weak self] in self?.showPlayMenu() }

        // Show flashing Requests button when there's a pending invite
        if pendingInviteMatch != nil {
            menuOptions.append(MenuOption("Requests", isAlert: true, tint: .cyan))
            actions.append { [weak self] in
                guard let self = self, let match = self.pendingInviteMatch else { return }
                self.stopInvitePollTimer()
                GameCenterManager.shared.currentMatch = match
                self.showIncomingTurnPrompt(match: match)
            }
        }

        menuOptions.append(MenuOption("How to Play"))
        actions.append { [weak self] in self?.showHowToPlay() }
        menuOptions.append(MenuOption("Settings"))
        actions.append { [weak self] in self?.showSettings() }

        // Compact nav cell (bottom-right) — just "?" here. Nothing to page
        // through and nothing above this screen to go back to, so the left
        // and right slots of the cell stay empty; this is still the one
        // small addition that keeps the main menu consistent with every
        // other screen's nav cell rather than a special case.
        menuOptions.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showMainMenuHelp() }

        showMenuOptions(menuOptions)

        closeHandler = { [weak self] in self?.quitApp() }
        menuHandler = { choice in
            guard choice >= 1 && choice <= actions.count else { return }
            actions[choice - 1]()
        }
        menuLongPressHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= menuOptions.count else { return }
            guard menuOptions[choice - 1].text == "Play" else { return }
            // Long-press Play → skip the Play menu and the save list
            // entirely, straight into the single most recently saved slot
            // (same shortcut as long-pressing Continue Adventure itself).
            let candidates = SaveGameManager.shared.listSlots().filter { !$0.latest.party.isEmpty }
            if let mostRecent = candidates.max(by: { $0.latest.savedAt < $1.latest.savedAt }) {
                self.loadGame(mostRecent.latest)
            }
        }
    }

    private func showMainMenuHelp() {
        let hasActiveGame = dungeon != nil && !party.isEmpty
        showInlineHelp {
            self.printTitle("Main Menu — Help")
            self.print("")
            if hasActiveGame {
                self.print("  CONTINUE QUEST", color: .cyan, bold: true)
                self.printWrapped("Jumps straight back into your adventure in progress.", indent: 2, color: .dimGreen)
                self.print("")
            }
            self.print("  PLAY", color: .cyan, bold: true)
            self.printWrapped("Start a new adventure, load a save, or continue one from here. Long-press Play to jump straight into your most recently played save.", indent: 2, color: .dimGreen)
            self.print("")
            if self.pendingInviteMatch != nil {
                self.print("  REQUESTS", color: .cyan, bold: true)
                self.printWrapped("A multiplayer turn or invite is waiting for you — tap to jump straight to it.", indent: 2, color: .dimGreen)
                self.print("")
            }
            self.print("  HOW TO PLAY", color: .cyan, bold: true)
            self.printWrapped("Rules, controls, and tips — covers exploration, combat, the DM, and more.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  SETTINGS", color: .cyan, bold: true)
            self.printWrapped("Gameplay, sound, accessibility, AI/DM, and save options.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    private func startInvitePollTimer() {
        stopInvitePollTimer()
        invitePollTimer = Timer.scheduledTimer(withTimeInterval: 5.0, repeats: true) { [weak self] _ in
            guard let self = self else {
                self?.stopInvitePollTimer()
                return
            }
            // Poll on main menu or when idle (not mid-combat or actively exploring)
            if self.gameState == .mainMenu {
                self.checkForPendingInvites()
            }
        }
    }

    private func stopInvitePollTimer() {
        invitePollTimer?.invalidate()
        invitePollTimer = nil
    }

    /// Check Game Center for pending invites and refresh main menu with "Game Invite!" button
    private func checkForPendingInvites() {
        Task {
            guard let matches = try? await GKTurnBasedMatch.loadMatches() else { return }

            // Find matches that need our attention
            let myID = GKLocalPlayer.local.gamePlayerID
            let invites = matches.filter { match in
                // Pending invite we haven't accepted yet
                if match.status == .matching { return true }
                // Any open match where our slot needs confirmation (regardless of whose turn it is)
                guard match.status == .open,
                      let data = match.matchData, !data.isEmpty else { return false }
                if let state = try? MultiplayerMatchState.decoded(from: data) {
                    let mySlot = state.players.first(where: { $0.gamePlayerID == myID })
                    if mySlot?.needsConfirmation == true { return true }
                    // Catch pending_N slots — the host created the match before we joined
                    let hasPendingSlot = state.players.contains(where: { $0.gamePlayerID.hasPrefix("pending_") && $0.needsConfirmation })
                    if hasPendingSlot && state.phase == .characterCreation { return true }
                    // Also catch matches where we need to create a character
                    if mySlot == nil && state.phase == .characterCreation { return true }
                }
                return false
            }

            guard let firstInvite = invites.first else { return }

            await MainActor.run { [weak self] in
                guard let self = self else { return }

                // If not on the main menu, cache the invite for later
                guard self.gameState == .mainMenu else {
                    self.pendingInviteMatch = firstInvite
                    return
                }

                // If this is a brand new invite we haven't shown yet, go straight to the prompt
                if self.pendingInviteMatch?.matchID != firstInvite.matchID {
                    self.pendingInviteMatch = firstInvite
                    self.stopInvitePollTimer()
                    SoundManager.shared.playMultiplayerNotification()
                    GameCenterManager.shared.currentMatch = firstInvite
                    self.showIncomingTurnPrompt(match: firstInvite)
                    return
                }

                // Already seen this invite — just ensure Requests button is showing
                self.pendingInviteMatch = firstInvite
                self.renderMainMenu()
            }
        }
    }

    // MARK: - Unified Play Menu

    private enum PlayEntry {
        case newGame
        case localSave(SaveSlot)
        case multiplayerMatch(GKTurnBasedMatch, info: String, status: String)
    }

    private func showPlayMenu() {
        clearAllUndoRedo()
        // No clearTerminal()/printTitle() here — renderPlayMenu(), called
        // right below, does both itself. Doing it twice used to just be
        // redundant, harmless work; now that clearTerminal()'s state reset
        // runs synchronously (see runOnMain()), calling it twice back to
        // back visibly duplicated the "Play" title for a frame.

        // Load local saves immediately
        let localSlots = SaveGameManager.shared.listSlots()

        // Show local saves while loading multiplayer
        renderPlayMenu(localSlots: localSlots, mpMatches: nil, loading: multiplayerEnabled && GameCenterManager.shared.isAuthenticated)

        // Load multiplayer matches async — also check for pending invites
        if multiplayerEnabled && GameCenterManager.shared.isAuthenticated {
            Task {
                let matches = (try? await GameCenterManager.shared.loadMatches()) ?? []
                let activeMatches = matches.filter { $0.status == .open || $0.status == .matching }

                // Check for invites that need attention (same logic as checkForPendingInvites)
                let myID = GKLocalPlayer.local.gamePlayerID
                let invites = matches.filter { match in
                    if match.status == .matching { return true }
                    guard match.status == .open,
                          let data = match.matchData, !data.isEmpty else { return false }
                    if let state = try? MultiplayerMatchState.decoded(from: data) {
                        let mySlot = state.players.first(where: { $0.gamePlayerID == myID })
                        if mySlot?.needsConfirmation == true { return true }
                        let hasPendingSlot = state.players.contains(where: { $0.gamePlayerID.hasPrefix("pending_") && $0.needsConfirmation })
                        if hasPendingSlot && state.phase == .characterCreation { return true }
                        if mySlot == nil && state.phase == .characterCreation { return true }
                    }
                    return false
                }

                await MainActor.run { [weak self] in
                    guard let self = self else { return }
                    // If there's a pending invite, show the prompt immediately
                    if let invite = invites.first, self.pendingInviteMatch?.matchID != invite.matchID {
                        self.pendingInviteMatch = invite
                        SoundManager.shared.playMultiplayerNotification()
                        GameCenterManager.shared.currentMatch = invite
                        self.showIncomingTurnPrompt(match: invite)
                    } else {
                        self.renderPlayMenu(localSlots: localSlots, mpMatches: activeMatches, loading: false)
                    }
                }
            }
        }
    }

    private func renderPlayMenu(localSlots: [SaveSlot], mpMatches: [GKTurnBasedMatch]?, loading: Bool) {
        clearTerminal()
        printTitle("Play")

        // Summary info — no numbering here, since it doesn't necessarily
        // match the actual button positions below (multiplayer matches can
        // insert between them) and the button labels already self-explain.
        print("  Continue Adventure", color: .brightGreen, bold: true)
        printWrapped("Long-press to jump straight into your latest save", indent: 5, color: .dimGreen)
        print("")
        print("  New Adventure", color: .brightGreen, bold: true)
        printWrapped("Long-press for quick start", indent: 5, color: .dimGreen)
        print("")

        // Show multiplayer matches
        var mpEntries: [(match: GKTurnBasedMatch, info: String, status: String)] = []
        if let matches = mpMatches {
            for match in matches {
                let status: String
                if match.status == .matching {
                    status = "invite"
                } else if match.currentParticipant?.player == GKLocalPlayer.local {
                    status = "your turn"
                } else {
                    // Check if the other player is still connected
                    let otherParticipants = match.participants.filter { $0.player?.gamePlayerID != GKLocalPlayer.local.gamePlayerID }
                    let allOthersQuit = !otherParticipants.isEmpty && otherParticipants.allSatisfy { $0.status == .done || $0.status == .declined }
                    if allOthersQuit {
                        status = "partner left"
                    } else {
                        status = "waiting"
                    }
                }
                var info = ""
                if let data = match.matchData, !data.isEmpty,
                   let state = try? MultiplayerMatchState.decoded(from: data) {
                    info = "\(state.dungeon.name) (Lv\(state.dungeonLevel))"
                }
                mpEntries.append((match: match, info: info, status: status))

                let names = match.participants.compactMap { $0.player?.displayName }
                let playerStr = names.isEmpty ? "Multiplayer" : names.joined(separator: ", ")
                let statusColor: TerminalColor
                let isBold: Bool
                switch status {
                case "your turn":
                    statusColor = .brightGreen; isBold = true
                case "invite":
                    statusColor = .yellow; isBold = true
                case "partner left":
                    statusColor = .red; isBold = false
                default:
                    statusColor = .dimGreen; isBold = false
                }
                printWrapped(playerStr, indent: 2, color: .cyan, bold: isBold)
                if !info.isEmpty {
                    printWrapped(info, indent: 5, color: .dimGreen)
                }
                let statusTag: String
                switch status {
                case "your turn": statusTag = ">> YOUR TURN <<"
                case "invite": statusTag = "New Invite!"
                case "partner left": statusTag = "Partner left — tap to continue solo"
                case "waiting": statusTag = "Waiting for partner..."
                default: statusTag = "[\(status)]"
                }
                printWrapped(statusTag, indent: 5, color: statusColor, bold: status == "your turn")
                print("")
            }
        }

        if loading {
            print("  Loading multiplayer...", color: .dimGreen)
            print("")
        }

        if multiplayerEnabled {
            printWrapped("Remote players: set up in New Adventure, or change Robot→Remote in Party Status.", indent: 2, color: .dimGreen)
            print("")
        }

        // Build menu buttons: New Adventure, multiplayer matches, Load Saves, Manage Saves, Help
        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        // Continue Adventure first — resuming an existing adventure is the
        // more common action than starting a fresh one, so it's button 1
        // (and the default) rather than New Adventure. EXCEPT when there's
        // nothing to continue — an empty save list makes "Continue" a dead
        // end, so New Adventure (the only thing actually possible) becomes
        // the default instead, even though it still displays second.
        let hasSaves = !localSlots.isEmpty
        // Disabled (dimmed) rather than removed when there's nothing to
        // continue — still discoverable as "the button that would resume
        // play," just visibly not the thing to reach for right now. A
        // long-press bypasses isDisabled by design (see MenuButtonsView),
        // so it still fires — redirected to New Adventure below rather
        // than silently doing nothing when there's no save to jump to.
        menuOpts.append(MenuOption("Continue Adventure", isDefault: hasSaves, isDisabled: !hasSaves))
        actions.append { [weak self] in self?.showLoadGameMenu(returnTo: .mainMenu) }

        menuOpts.append(MenuOption("New Adventure", isDefault: !hasSaves))
        actions.append { [weak self] in self?.startNewGame() }

        // No separate "Hall of Fame" button — briefly tried that (as a
        // pinned button inside Continue Adventure, then as its own
        // top-level button here), but Continue Adventure's own list
        // already shows every completed tale's W/L result right alongside
        // adventures still in progress, so a second, score-sorted view of
        // the same tales was just a near-duplicate. Its "Manage" pinned
        // button now lives on Continue Adventure directly instead (see
        // showLoadGameMenu). The dedicated Hall of Fame screen itself is
        // still there for the "hall of fame" chat command.
        // Multiplayer match buttons
        for mp in mpEntries {
            let names = mp.match.participants.compactMap { $0.player?.displayName }
            let baseName = names.isEmpty ? "Multiplayer" : names.prefix(2).joined(separator: ", ")
            let label: String
            let tint: MenuTint
            let isAlert: Bool
            switch mp.status {
            case "your turn":
                label = "\(baseName) [YOUR TURN]"
                tint = .normal
                isAlert = true
            case "invite":
                label = "\(baseName) [INVITE]"
                tint = .amber
                isAlert = true
            case "partner left":
                label = "\(baseName) [SOLO]"
                tint = .cyan
                isAlert = false
            default:
                label = "\(baseName) [waiting]"
                tint = .cyan
                isAlert = false
            }
            menuOpts.append(MenuOption(label, isAlert: isAlert, tint: tint))
            let match = mp.match
            actions.append { [weak self] in
                GameCenterManager.shared.currentMatch = match
                self?.loadMultiplayerMatch(match)
            }
        }

        // Continue Adventure goes straight to the save-game list — tap an
        // entry and it loads immediately, ordered most-recently-saved
        // first (see SaveGameManager.listSlots), with completed tales
        // showing their Hall of Fame result (W/L, score) right in the
        // list — so a separate Hall of Fame list would just duplicate it.
        // Hall of Fame is still reachable via the "hall of fame" chat
        // command. (Continue Adventure itself is added above, ahead of
        // New Adventure.)
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showPlayHelp() }

        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        actions.append { [weak self] in
            self?.clearTerminal()
            self?.showMainMenu()
        }

        showMenuOptions(menuOpts)

        closeHandler = { [weak self] in
            self?.clearTerminal()
            self?.showMainMenu()
        }
        menuHandler = { choice in
            guard choice >= 1 && choice <= actions.count else { return }
            actions[choice - 1]()
        }

        menuLongPressHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= menuOpts.count else { return }
            switch menuOpts[choice - 1].text {
            case "New Adventure":
                // Long-press New Adventure → quick start
                self.createRandomParty(count: 2, allAI: true)
            case "Continue Adventure":
                // Long-press → skip the save list entirely and load the
                // single most recently saved slot directly. Skips any slot
                // whose save has no characters in it — a defunct/corrupted
                // save (performAutosave() now guards against writing one,
                // but an older one could already exist on this device) —
                // rather than silently loading a scenario with nobody in it.
                let candidates = SaveGameManager.shared.listSlots().filter { !$0.latest.party.isEmpty }
                if let mostRecent = candidates.max(by: { $0.latest.savedAt < $1.latest.savedAt }) {
                    self.loadGame(mostRecent.latest)
                } else {
                    // Nothing to continue — the button's dimmed for exactly
                    // this reason, but a long-press still does SOMETHING
                    // useful instead of silently going nowhere.
                    self.startNewGame()
                }
            default:
                break
            }
        }
    }

    private func showPlayHelp() {
        showInlineHelp {
            self.printTitle("Play Menu Help")
            self.print("")
            self.print("  NEW ADVENTURE", color: .cyan, bold: true)
            self.printWrapped("Start a fresh adventure. Pick your party size, then create each character — or load one from the Character Hall of Fame (defaults to your most recent hero, if you have one). Long-press for a quick start with a random party.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  CONTINUE ADVENTURE", color: .cyan, bold: true)
            self.printWrapped("Lists your saved games, most recently saved first — tap one to load it immediately. Completed tales show their Hall of Fame result (W/L, score) right in the list. 'Manage' renames, copies, or deletes saves.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  CHARACTER SAVES", color: .cyan, bold: true)
            self.printWrapped("Found inside New Adventure's character selection (the Character Hall of Fame screen) — 'Manage Saves' there browses and deletes your full Character Roster, not just Hall-of-Famers. Save a character any time from Party Review or Party Status.", indent: 2, color: .dimGreen)
            self.print("")
            if self.multiplayerEnabled {
                self.print("  MULTIPLAYER MATCHES", color: .cyan, bold: true)
                self.printWrapped("Active Game Centre matches appear as cyan buttons. Flashing buttons indicate incoming invites.", indent: 2, color: .dimGreen)
                self.print("")
            }
        }
    }

    private func showMultiplayerHub() {
        clearTerminal()
        printTitle("Multiplayer Games")

        let gcAuth = GameCenterManager.shared.isAuthenticated
        if !gcAuth {
            print("Game Centre is required for", color: .yellow)
            print("multiplayer. Signing in...", color: .yellow)
            print("")
            GameCenterManager.shared.authenticatePlayer()
        }

        showMenu(["New Multiplayer Game", "Active Matches",
                   "How Multiplayer Works"])

        closeHandler = { [weak self] in self?.showMainMenu() }
        menuHandler = { [weak self] choice in
            switch choice {
            case 1:
                self?.startMultiplayerNewGame()
            case 2:
                if GameCenterManager.shared.isAuthenticated {
                    self?.showActiveMatches()
                } else {
                    self?.clearTerminal()
                    self?.printTitle("Active Matches")
                    self?.print("Sign in to Game Centre first.", color: .yellow)
                    self?.print("Check Settings > Game Centre.", color: .dimGreen)
                    self?.print("")
                    self?.waitForContinue()
                    self?.inputHandler = { [weak self] _ in
                        self?.showMultiplayerHub()
                    }
                    self?.closeHandler = { [weak self] in self?.showMultiplayerHub() }
                }
            case 3:
                self?.showMultiplayerHelp()
            default:
                self?.showMainMenu()
            }
        }
    }

    /// Start a new game pre-configured for multiplayer
    private func startMultiplayerNewGame() {
        if !GameCenterManager.shared.isAuthenticated {
            clearTerminal()
            printTitle("New Multiplayer Game")
            print("Sign in to Game Centre first.", color: .yellow)
            print("Check Settings > Game Centre.", color: .dimGreen)
            print("")
            GameCenterManager.shared.authenticatePlayer()
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showPlayMenu() }
            closeHandler = { [weak self] in self?.showPlayMenu() }
            return
        }

        clearTerminal()
        printTitle("New Multiplayer Game")
        print("How many adventurers in your party?", color: .brightGreen)
        print("  (Long-press for auto-setup)", color: .dimGreen)
        print("")

        showMenu(["2 Adventurers", "3 Adventurers", "4 Adventurers"])

        closeHandler = { [weak self] in self?.showMultiplayerHub() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1...3:
                // Manual creation: 1 human + rest to be created manually, last slot preset as remote
                let count = choice + 1
                self.totalCharacters = count
                self.creatingCharacterIndex = 0
                self.party = []
                self.pendingRemoteSlots.removeAll()
                self.explicitlyChosenSlots.removeAll()
                self.pendingRemoteSlots.insert(count - 1) // last slot = remote
                self.isMultiplayer = true
                self.chooseCharacterType()
            default: self.showPlayMenu()
            }
        }

        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: self.createRandomParty(count: 2, allAI: true, presetRemote: true)
            case 2: self.createRandomParty(count: 3, allAI: true, presetRemote: true)
            case 3: self.createRandomParty(count: 4, allAI: true, presetRemote: true)
            default: break
            }
        }
    }

    /// Track which help topic is currently displayed (for re-press flash)
    private var currentHelpTopic: Int = -1
    /// True when inside a help/how-to-play page — long-press any button → How to Play
    var inHelpContext: Bool = false

    /// Dim-then-restore pulse on the text area
    func flashText() {
        guard !reduceAnimations else { return }
        DispatchQueue.main.async {
            self.textFlashOpacity = 0.3
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) {
                self.textFlashOpacity = 1.0
            }
        }
    }

    func showHowToPlay() {
        clearTerminal()
        undoHandler = nil; redoHandler = nil
        inHelpContext = true
        currentHelpTopic = -1
        printTitle("How to Play")
        print("")
        print("  • Explore", color: .brightGreen, bold: true)
        printWrapped("    the dungeon on an adventure with your companions", color: .green)
        print("")
        print("  • Meet", color: .brightGreen, bold: true)
        printWrapped("    interesting creatures in a dark, damp dungeon", color: .green)
        print("")
        print("  • Enjoy", color: .brightGreen, bold: true)
        printWrapped("    yourself fighting and running from scary monsters and super creeps", color: .green)
        print("")
        print("  • Beat", color: .brightGreen, bold: true)
        printWrapped("    the Boss on each level to go deeper", color: .green)
        print("")
        print("  • Level Up", color: .brightGreen, bold: true)
        printWrapped("    your abilities with experience", color: .green)
        print("")
        print("  • Quests", color: .brightGreen, bold: true)
        printWrapped("    ask anyone you meet if they have one for you — you'll win prizes and progress as a character", color: .green)
        print("")
        print("  • Train", color: .brightGreen, bold: true)
        printWrapped("    at any gyms you find: learn new skills, or enhance the ones you have", color: .green)
        print("")
        printWrapped("  Make it into the Hall of Fame — your finished adventures, ranked in Continue Adventure — if you're good enough.", color: .brightGreen, bold: true)
        print("")
        if voiceMenuEnabled {
            printWrapped("Navigate with buttons, type commands at the > prompt, or tap the mic to speak. Swipe left to go back, swipe right to continue.", indent: 2, color: .dimGreen)
        } else {
            printWrapped("Navigate with buttons or type commands at the > prompt. Swipe left to go back, swipe right to continue.", indent: 2, color: .dimGreen)
        }
        print("")
        print("  • Long-press", color: .brightGreen, bold: true)
        printWrapped("    a button for its shortcut — e.g. long-press Quit Without Saving, Delete or Give Up Quest to skip the \"are you sure?\" step, Long Rest to rest fast, or Continue Adventure to jump straight into your latest save.", color: .green)
        print("")
        print("  • Auto-Continue", color: .brightGreen, bold: true)
        printWrapped("    Many screens move on by themselves after a few seconds. Tap anywhere to continue at once, or wait for the little hourglass at the right of the input line to run out. Tap the hourglass to pause it (orange means paused, and a ? explains how to carry on), tap again to let it run, long-press it to hurry. Settings > Gameplay turns Auto-Continue off, changes how long screens wait, or hides the hourglass.", color: .green)
        printLink("Settings > Gameplay", to: "gameplay", indent: 4)
        print("")

        let helpTopics = ["Getting Started", "Exploration", "Combat",
                          "Character & Party", "Recovery",
                          "Dungeon Master", "Multiplayer", "Tips & Tricks",
                          "Bestiary", "Gallery & Lore"]
        let helpActions: [(GameEngine) -> Void] = [
            { $0.showHelpGettingStarted() }, { $0.showHelpExploration() },
            { $0.showHelpCombat() }, { $0.showHelpCharacter() },
            { $0.showHelpRecovery() }, { $0.showHelpDM() },
            { $0.showHelpMultiplayer() }, { $0.showHelpTips() },
            { $0.showBestiary() },
            { $0.showGalleryAndLore() },
        ]

        showPaginatedMenu(helpTopics, pinned: ["?", "< Back"], defaultIndex: currentHelpTopic >= 0 ? currentHelpTopic : nil) { [weak self] idx in
            guard let self = self, idx >= 0 && idx < helpActions.count else { return }
            if idx == self.currentHelpTopic {
                // Same topic re-pressed — flash the text as feedback
                self.flashText()
                return
            }
            self.currentHelpTopic = idx
            helpActions[idx](self)
        }

        // Wrap menuHandler to intercept pinned ?/< Back buttons
        let originalHandler = menuHandler
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let idx = choice - 1
            guard idx >= 0 && idx < self.currentMenuOptions.count else { originalHandler?(choice); return }
            switch self.currentMenuOptions[idx].text {
            case "?": self.showHowToPlayHelp()
            case "< Back": self.closeHandler?()
            default: originalHandler?(choice)
            }
        }

        closeHandler = { [weak self] in
            self?.closeHandler = nil
            self?.currentHelpTopic = -1
            self?.inHelpContext = false
            self?.showMainMenu()
        }
    }

