    // MARK: Combat Arena
    //
    // The fight acted out in ASCII below the buttons. Built for every
    // platform but only offered on the Mac for now — flip
    // combatArenaAvailable to bring it to the app.
    static var combatArenaAvailable: Bool { true }

    /// Fight Club showing this fight — the @ on the input line toggles it
    /// (on by itself on a Mac; on a phone, off until asked for).
    @Published var fightClubOn: Bool = UserDefaults.standard.object(forKey: "fightClubOn") as? Bool ?? GameEngine.fightClubStartsOn {
        didSet { UserDefaults.standard.set(fightClubOn, forKey: "fightClubOn") }
    }
    static var fightClubStartsOn: Bool {
        #if os(macOS)
        return true
        #else
        return false
        #endif
    }
    var fightClubAvailableNow: Bool { combatArenaEnabled && currentCombat != nil && gameState == .combat }

    /// Gameplay > Dungeon Quirks (off by default): little oddities — the
    /// dragon's winks wander out of the pictures into the words.
    var dungeonQuirksEnabled: Bool {
        get { UserDefaults.standard.bool(forKey: "dungeonQuirks") }
        set { UserDefaults.standard.set(newValue, forKey: "dungeonQuirks"); objectWillChange.send() }
    }
    var combatArenaEnabled: Bool {
        get { UserDefaults.standard.object(forKey: "combatArena") == nil ? true : UserDefaults.standard.bool(forKey: "combatArena") }
        set { UserDefaults.standard.set(newValue, forKey: "combatArena"); objectWillChange.send() }
    }
    /// Settings > Gameplay's arena button where it isn't offered yet —
    /// shown greyed out, as a hint of what's coming.
    static let arenaUnavailableLabel = "Arena (Mac only)"
    /// Buttons that always show greyed out (can't be pressed).
    static let alwaysDisabledOptionTexts: Set<String> = combatArenaAvailable ? [] : [arenaUnavailableLabel]
    static func applyAlwaysDisabled(_ options: [MenuOption]) -> [MenuOption] {
        guard !alwaysDisabledOptionTexts.isEmpty else { return options }
        return options.map { o in
            guard alwaysDisabledOptionTexts.contains(o.text) else { return o }
            return MenuOption(o.text, isDefault: false, isDisabled: true, isAlert: o.isAlert, tint: o.tint, compact: o.isCompactNav, displayNumber: o.displayNumber)
        }
    }
    /// Every menu: greyed-out labels applied, a default always chosen (the
    /// first ordinary button when the screen didn't name one), and the
    /// default shown first — each moved button remembering where it was
    /// (sourceIndex), so the screen's handler still gets the choice it expects.
    func prepareMenu(_ options: [MenuOption]) -> [MenuOption] {
        hoveredMenuChoice = nil
        var opts = Self.applyAlwaysDisabled(options)
        func regular(_ o: MenuOption) -> Bool { !o.isCompactNav && o.text != "Fwd >" && o.text != "<<" && o.text != ">>" }
        if !opts.contains(where: { $0.isDefault }), let i = opts.firstIndex(where: { regular($0) && !$0.isDisabled && $0.tint != .danger }) {
            let o = opts[i]
            var d = MenuOption(o.text, isDefault: true, isDisabled: o.isDisabled, isAlert: o.isAlert, tint: o.tint, compact: o.isCompactNav, displayNumber: o.displayNumber)
            d.sourceIndex = o.sourceIndex
            opts[i] = d
        }
        guard let d = opts.firstIndex(where: { $0.isDefault && regular($0) }),
              let f = opts.firstIndex(where: regular), d > f else { return opts }
        var order = Array(opts.indices)
        order.remove(at: d)
        order.insert(d, at: f)
        return order.map { i in var o = opts[i]; o.sourceIndex = i; return o }
    }

    /// The choice number the screen's handler expects for a button pressed
    /// at `choice` on screen.
    func sourceChoice(_ choice: Int) -> Int {
        guard choice >= 1, choice <= currentMenuOptions.count, let s = currentMenuOptions[choice - 1].sourceIndex else { return choice }
        return s + 1
    }

    /// Mac: the button under the mouse — Return presses it (else the default).
    var hoveredMenuChoice: Int?
    func setMenuHover(_ choice: Int, _ inside: Bool) {
        if inside { hoveredMenuChoice = choice } else if hoveredMenuChoice == choice { hoveredMenuChoice = nil }
    }
    var hoveredMenuChoiceIfValid: Int? {
        #if os(macOS)
        guard let h = hoveredMenuChoice, h >= 1, h <= currentMenuOptions.count, !currentMenuOptions[h - 1].isDisabled else { return nil }
        return h
        #else
        return nil
        #endif
    }

    /// The ⚙ menu's music switch: takes effect at once.
    func toggleMusicQuick() {
        musicEnabled.toggle()
        if musicEnabled {
            if currentCombat != nil { SoundManager.shared.startMusic(.combat, preference: combatMelodyChoice) }
            else { SoundManager.shared.startMusic(.exploration, preference: explorationMelodyChoice) }
        }
        objectWillChange.send()
    }

    var showCombatArena: Bool { fightClubAvailableNow && fightClubOn }

    func arenaScene() -> ArenaScene {
        guard let combat = currentCombat else { return ArenaScene(move: arenaMove) }
        // A colour each, so several fighters can be told apart (never the
        // enemy's red for a friend).
        let partyColors: [TerminalColor] = [.brightGreen, .cyan, .yellow, .magenta, .white, .orange]
        let enemyColors: [TerminalColor] = [.red, .orange, .magenta, .yellow, .white]
        let partyF = party.enumerated().map { i, c in ArenaFighter(name: c.name, frames: c.characterClass.asciiArtFrames, hp: c.currentHP, maxHP: c.maxHP, isParty: true, down: !c.isConscious, color: partyColors[i % partyColors.count]) }
        let enemies = combat.encounter.monsters.enumerated().map { i, m in ArenaFighter(name: m.name, frames: m.type.asciiArtFrames, hp: m.currentHP, maxHP: m.maxHP, isParty: false, down: !m.isAlive, color: enemyColors[i % enemyColors.count]) }
        let turn = combat.currentCombatant
        let left = (turn?.isPlayer == true ? partyF.first { $0.name == turn?.name && !$0.down } : nil) ?? partyF.first { !$0.down } ?? partyF.first
        let right = (turn?.isPlayer == false ? enemies.first { $0.name == turn?.name && !$0.down } : nil) ?? enemies.first { !$0.down }
        return ArenaScene(left: left, right: right, party: partyF, enemies: enemies, turnName: turn?.name, move: arenaMove)
    }

    private func arenaFrames(for name: String, fallback: [String]) -> [[String]] {
        if let c = party.first(where: { $0.name == name }) { return c.characterClass.asciiArtFrames }
        if let m = currentCombat?.encounter.monsters.first(where: { $0.name == name }) { return m.type.asciiArtFrames }
        return [fallback]
    }

    /// A weapon attack, as the arena shows it — the style from the weapon
    /// and class (or, for monsters, what sort of creature it is).
    private func arenaPlayAttack(_ r: AttackReport) {
        guard showCombatArena else { return }
        let wn = r.weaponName.lowercased()
        var style: ArenaMove.Style = .melee
        if r.isPlayerAttack {
            let cls = party.first { $0.name == r.attackerName }?.characterClass
            if wn.contains("crossbow") { style = .bolt }
            else if wn.contains("bow") { style = .arrow }
            else if wn.contains("dart") || wn.contains("sling") || wn.contains("javelin") || (wn.contains("dagger") && (cls == .rogue || cls == .thief)) { style = .thrown }
            else if cls == .engineer && !wn.contains("hammer") && !wn.contains("sword") && !wn.contains("axe") { style = .gadget }
        } else {
            let mn = r.attackerName.lowercased()
            if ["dragon", "wyrm", "drake", "hell hound", "salamander"].contains(where: mn.contains) { style = .breath }
            else if ["bat", "stirge", "harpy", "wasp", "hawk", "wyvern", "imp", "ghost", "wraith", "spectre", "specter", "will-o"].contains(where: mn.contains) { style = .swoop }
            else if mn.contains("archer") || wn.contains("bow") { style = .arrow }
        }
        arenaMove = ArenaMove(attackerName: r.attackerName, targetName: r.targetName,
                              attackerFrames: arenaFrames(for: r.attackerName, fallback: r.attackerArt),
                              targetFrames: arenaFrames(for: r.targetName, fallback: r.defenderArt),
                              attackerIsParty: r.isPlayerAttack, style: style, hits: r.hits, critical: r.isCritical,
                              fumble: r.isCriticalMiss, defeated: r.targetDefeated || r.targetUnconscious,
                              amount: r.hits ? (r.totalDamage ?? 0) : 0, glyph: "*", color: .yellow, started: Date())
        arenaCrowdReacts(partyCheers: r.isPlayerAttack == r.hits)
    }

    /// The onlookers react as the blow lands — a cheer when it goes the
    /// party's way (a hit, or a dodge), a jeer when it doesn't.
    private func arenaCrowdReacts(partyCheers: Bool) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.9) { [weak self] in
            guard let self = self, self.showCombatArena else { return }
            if partyCheers { SoundManager.shared.playCrowdCheer() } else { SoundManager.shared.playCrowdJeer() }
        }
    }

    /// A spell, as the arena shows it — coloured by its element.
    private func arenaPlaySpell(_ r: SpellReport) {
        guard showCombatArena else { return }
        let casterIsParty = party.contains { $0.name == r.casterName }
        let key = ((r.damageType ?? "") + " " + r.spellName).lowercased()
        var glyph = "o", color: TerminalColor = .magenta
        if ["fire", "flame", "burn", "scorch"].contains(where: key.contains) { glyph = "*"; color = .orange }
        else if ["cold", "frost", "ice"].contains(where: key.contains) { glyph = "*"; color = .cyan }
        else if ["lightning", "thunder", "shock", "storm"].contains(where: key.contains) { glyph = "z"; color = .yellow }
        else if ["radiant", "sacred", "holy", "guiding"].contains(where: key.contains) { glyph = "+"; color = .yellow }
        else if ["necrotic", "poison", "acid", "chill"].contains(where: key.contains) { glyph = "%"; color = .magenta }
        else if ["psychic", "mockery"].contains(where: key.contains) { glyph = "♪"; color = .magenta }
        else if ["force", "missile"].contains(where: key.contains) { glyph = casterIsParty ? ">" : "<"; color = .cyan }
        let supportive = r.spellType == .healing || r.spellType == .buff || r.spellType == .utility
        let target = supportive ? (r.targetName ?? r.casterName) : (r.targetsHit.first ?? r.targetName ?? r.targetStatuses.first?.name ?? "")
        let hits: Bool
        switch r.spellType {
        case .attack: hits = r.hits ?? false
        case .autoHit: hits = true
        case .savingThrow: hits = !r.targetsHit.isEmpty || r.totalDamage > 0
        default: hits = true
        }
        arenaMove = ArenaMove(attackerName: r.casterName, targetName: target,
                              attackerFrames: arenaFrames(for: r.casterName, fallback: [" o ", "/|\\", "/ \\"]),
                              targetFrames: arenaFrames(for: target, fallback: [" ? "]),
                              attackerIsParty: casterIsParty, style: supportive ? .heal : .spell, hits: hits, critical: r.isCritical,
                              fumble: false, defeated: !r.targetsDefeated.isEmpty,
                              amount: supportive ? r.healAmount : r.totalDamage, glyph: glyph, color: color, started: Date())
        arenaCrowdReacts(partyCheers: casterIsParty == (hits || supportive))
    }

    var gameTimeLimit: Int {  // 0 = off, value in game-minutes
        get { UserDefaults.standard.integer(forKey: "gameTimeLimit") }
        set { UserDefaults.standard.set(newValue, forKey: "gameTimeLimit") }
    }

    /// Max distinct symbol types shown in the map key at once. The key is
    /// filtered to symbols actually present in the viewport, but the block's
    /// HEIGHT is always fixed at this many slots (see mapLegendLines) so the
    /// map never resizes based on how many symbol types happen to be nearby.
    var mapLegendMaxSymbols: Int {
        get {
            #if os(macOS) || os(tvOS)
            // Room to spare on a Mac or TV — always the full key.
            return Dungeon.mapLegendEntries.count
            #else
            let val = UserDefaults.standard.integer(forKey: "map_legend_max_symbols")
            return val > 0 ? min(val, Dungeon.mapLegendEntries.count) : 6
            #endif
        }
        set {
            UserDefaults.standard.set(min(max(newValue, 3), Dungeon.mapLegendEntries.count), forKey: "map_legend_max_symbols")
        }
    }

    var maxButtonsPerScreen: Int {
        get {
            let val = UserDefaults.standard.integer(forKey: "maxButtonsPerScreen")
            return val > 0 ? val : 6
        }
        set {
            UserDefaults.standard.set(newValue, forKey: "maxButtonsPerScreen")
        }
    }

    var longPressDuration: Double {
        get {
            let val = UserDefaults.standard.double(forKey: "longPressDuration")
            return val > 0 ? val : 0.5
        }
        set {
            UserDefaults.standard.set(newValue, forKey: "longPressDuration")
        }
    }

    /// Class-based "reliability" bonus (see CharacterClass.mapReliability):
    /// a party with a Wizard, Ranger, or Scout sees a little further, torch
    /// permitting — reconnaissance/pathfinding/arcane sense of the layout.
    func effectiveMapRadius() -> Int {
        guard torchLit else { return 0 }
        let bonus = party.contains { $0.characterClass.mapReliability > 0 } ? 1 : 0
        return mapRadius + bonus
    }

    func partyHasTorch() -> Bool {
        return party.contains { char in
            char.inventory.contains { $0.isTorch && ($0.torchLife ?? Item.torchFullLife) > 0 }
        }
    }

    /// Whether anyone in the party is skilled enough to sense a trap room
    /// on the map before it's actually gone off — see
    /// Dungeon.getMapDisplay's hasTrapSense parameter.
    var partyHasTrapSense: Bool {
        party.contains { $0.skillProficiencies.contains(.perception) }
    }

    private func autosaveIfNeeded() {
        let interval = autosaveInterval
        guard interval != .off, dungeon != nil else { return }

        roomsSinceLastSave += 1
        if roomsSinceLastSave >= interval.rawValue {
            roomsSinceLastSave = 0
            performAutosave()
        }
    }

    /// Defensive, belt-and-braces check against activeSlotId ever pointing
    /// at a slot that's been deleted (from anywhere — Manage Saves, a bulk
    /// delete, a future code path this doesn't already know about): if the
    /// slot activeSlotId names has no breakpoints left on disk, it was
    /// deleted out from under this session, and blindly reusing that id
    /// for the next save would resurrect the exact adventure the player
    /// just removed. Called at the top of every save path that trusts
    /// activeSlotId, so deletion stays robust regardless of which screen
    /// or code path did it — not just the ones that remember to clear
    /// activeSlotId themselves.
    private func clearActiveSlotIfDeleted() {
        guard let slotId = activeSlotId,
              SaveGameManager.shared.listBreakpoints(slotId: slotId).isEmpty else { return }
        activeSlotId = nil
        activeSlotName = nil
    }

    private func performAutosave() {
        guard let dungeon = dungeon else { return }
        // Never persist a party-less save — if this ever fired at a moment
        // party was transiently empty, it would silently corrupt this slot
        // (and, worse, "load the most recent save across every slot"
        // shortcuts) with an adventure that has no characters in it.
        guard !party.isEmpty else { return }
        clearActiveSlotIfDeleted()

        let partyDesc = party.map { "\($0.name) (\($0.characterClass.rawValue))" }.joined(separator: ", ")

        // Use the active slot if we have one, otherwise create a new slot
        let slotId = activeSlotId ?? UUID()
        let slotName = activeSlotName ?? uniqueSlotName("\(party.first?.name ?? "Unknown") — \(dungeon.name)")

        // Remember this slot for future autosaves
        if activeSlotId == nil {
            activeSlotId = slotId
            activeSlotName = slotName
        }

        let chatEntries = dmChatLog.map { DMChatEntry(isUser: $0.isUser, text: $0.text) }
        let saveGame = SaveGame(
            id: UUID(),
            slotId: slotId,
            savedAt: Date(),
            slotName: slotName,
            partyDescription: partyDesc,
            dungeonName: dungeon.name,
            dungeonLevel: dungeon.level,
            party: party,
            dungeon: dungeon,
            gameState: .exploring,
            gameTimeMinutes: gameTimeMinutes,
            adventureLog: adventureLog,
            dmChatLog: chatEntries,
            torchLit: torchLit,
            torchTurnsRemaining: torchTurnsRemaining,
            partyChatLog: partyChatLog.suffix(20).map { $0 },
            monstersSlain: monstersSlain,
            combatsWon: combatsWon,
            activeQuest: activeQuest, otherQuests: otherQuests, introLines: adventureIntroLines, mainQuest: mainQuest, questHistory: questHistory, noMainQuest: noMainQuest, mainQuestCompleted: mainQuestCompleted, questSummary: questSummaryLine()
        )

        try? SaveGameManager.shared.save(saveGame)
    }

