        print("  Size: \(fontSizeSetting.displayName)  Hits: \(hitAnimationsEnabled ? "On" : "Off")", color: .dimGreen)
        print("  DM Voice: \(speech.isEnabled ? "On" : "Off")  Companions: \(modeLabel)  Menus: \(voiceMenuEnabled ? "On" : "Off")", color: .dimGreen)
        print("")

        print("MOOD:", color: .cyan, bold: true)
        print("  Music: \(musicEnabled ? "On" : "Off")  Sounds: \(battleSoundsEnabled ? "On" : "Off")", color: .dimGreen)
        print("  Melodies: Menu/\(melodyName(type: "menu", choice: menuMelodyChoice))  Explore/\(melodyName(type: "exploration", choice: explorationMelodyChoice))", color: .dimGreen)
        print("")

        print("GAMEPLAY:", color: .cyan, bold: true)
        print("  Map: \(mapRadius)  Buttons: \(maxButtonsPerScreen)  Multi: \(multiplayerEnabled ? "On" : "Off")", color: .dimGreen)
        let timeLimitText = gameTimeLimit == 0 ? "Off" : formatTimeLimitValue(gameTimeLimit)
        print("  NPCs: \(npcsEnabled ? "On" : "Off")  Poison: \(poisonEnabled ? "On" : "Off")  Time: \(timeLimitText)", color: .dimGreen)
        let logText = adventureLogLimit == 0 ? "Off" : "\(adventureLogLimit)"
        print("  Nav: \(useArrowNavigation ? "Buttons" : "Swipe")  Info: \(String(format: "%.1f", infoTimeout))s  Hold: \(String(format: "%.1f", longPressDuration))s", color: .dimGreen)
        print("  Log: \(logText)  Idle: \(idlePromptsEnabled ? "On" : "Off")", color: .dimGreen)
        print("  Undo/Redo: \(undoRedoEnabled ? "On" : "Off")", color: .dimGreen)
        print("")

        print("SAVE:", color: .cyan, bold: true)
        print("  Autosave: \(autosaveInterval.displayName)", color: .dimGreen)
        print("")

        var menuOpts = ["DM Settings", "Change Brain", "Accessibility", "Mood", "Gameplay", "Puzzles", "Game Saves"].map { MenuOption($0) }
        menuOpts.append(MenuOption("Save Settings"))
        menuOpts.append(MenuOption("Reset", tint: .danger))
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)

        installSettingUndoRedo(screen: "s:main") { [weak self] in self?.showSettings() }

        let backToMain: () -> Void = { [weak self] in
            self?.clearAllSettingStacks()
            self?.clearTerminal()
            self?.showMainMenu()
        }
        closeHandler = backToMain
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let text = menuOpts[choice - 1].text
            switch text {
            case "DM Settings": self.showDMSettingsSubMenu()
            case "Change Brain": self.showAIProviderMenu(onBack: { [weak self] in self?.showSettings() })
            case "Puzzles": self.showPuzzleSettings(onBack: { [weak self] in self?.showSettings() })
            case "Accessibility": self.showAccessibilityMenu()
            case "Mood": self.showMusicSettings()
            case "Gameplay": self.showGameplaySettings()
            case "Game Saves": self.showSaveSettings()
            case "Save Settings": self.showSettingsBackupMenu()
            case "Reset": self.confirmResetToDefaults()
            case "?": self.showSettingsHelp()
            case "< Back": backToMain()
            default: break
            }
        }
    }

    /// One-tap settings backup from the main Settings screen — saves over a
    /// fixed "Quick Save" slot so repeated taps don't pile up backups. Rather
    /// than adding a second "Load Settings" button here too (this screen is
    /// crowded enough), lands on Settings Backup afterwards — the existing
    /// View/Load/Delete screen, where "Quick Save" now shows up in the list.
    private func quickSaveSettings() {
        clearTerminal()
        printTitle("Save Settings")
        print("")
        let keysBacked = backupAllAPIKeysToKeychainQuietly()
        saveSettingsBackup(name: "Quick Save") { [weak self] in
            self?.showSettingsBackupMenu()
        }
        if keysBacked > 0 {
            print("  \(keysBacked) API key\(keysBacked == 1 ? "" : "s") backed up to Keychain too.", color: .dimGreen)
        }
    }

