        printWrapped("Speaker and microphone icons for voice control.", indent: 2, color: .dimGreen)
        print("")

        print("BLINKING CURSOR:", color: .cyan, bold: true)
        print("  \(blinkingCursorEnabled ? "On" : "Off")", color: blinkingCursorEnabled ? .brightGreen : .red)
        printWrapped("Off (the default): no blinking block cursor by the > prompt. On: it blinks there until you tap to type. Turn this off if using VoiceOver — off automatically the first time this device has VoiceOver running.", indent: 2, color: .dimGreen)
        print("")

        print("AUTO-SCROLL:", color: .cyan, bold: true)
        print("  \(autoScrollSpeedName)", color: autoScrollSpeed > 0 ? .brightGreen : .red)
        printWrapped("New pages always open at the top, so you see the start of long text. With Auto-Scroll on, a long page then glides down by itself at this speed — touch it to stop. Off (the default): you scroll yourself. Try Auto-Scroll shows each speed.", indent: 2, color: .dimGreen)
        print("")

        print("ANIMATIONS:", color: .cyan, bold: true)
        print("  \(reduceAnimations ? "Reduced" : "Full")", color: .brightGreen)
        printWrapped("Reduced stops the flashing, blinking and spinning — title and text flashes, idle eye-blinks, the pack and hourglass animations, the countdown's spin and pulsing buttons. Starts out matching your device's Reduce Motion setting.", indent: 2, color: .dimGreen)
        print("")

        print("HANDEDNESS:", color: .cyan, bold: true)
        print("  \(leftHanded ? "Left-handed" : "Right-handed")", color: .brightGreen)
        printWrapped("On tap-to-continue screens, tapping the text moves on — except a narrow strip down one edge, kept free for scrolling. Right-handed keeps that strip on the right; left-handed on the left.", indent: 2, color: .dimGreen)
        print("")

        print("HELP BUTTON:", color: .cyan, bold: true)
        print("  \(MenuOption.helpGlyph)", color: .brightGreen)
        printWrapped("What the help button in the 3-bar cell shows: ?, ⓘ, or the word Help.", indent: 2, color: .dimGreen)
        print("")

        let displaySizeLabel = "Size \(displaySizeName)"
        let hitsLabel = hitAnimationsEnabled ? "Hits Off" : "Hits On"
        let dmVoiceLabel = speech.isEnabled ? "DM Voice On" : "DM Voice Off"
        let voiceMenuLabel = voiceMenuEnabled ? "Voice Menus On" : "Voice Menus Off"
        let cursorLabel = blinkingCursorEnabled ? "Cursor Off" : "Cursor On"
        let autoScrollLabel = "Auto-Scroll: \(autoScrollSpeedName)"
        let options = [displaySizeLabel, hitsLabel, dmVoiceLabel, "Companion Voices", voiceMenuLabel, cursorLabel,
                       autoScrollLabel, "Try Auto-Scroll",
                       reduceAnimations ? "Animations: Full" : "Animations: Reduced",
                       leftHanded ? "Right-Handed" : "Left-Handed",
                       "Help Button: \(MenuOption.helpGlyph)"]

        var menuOpts = options.map { MenuOption($0) }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)
        closeHandler = { [weak self] in self?.showSettings() }
        installSettingUndoRedo(screen: "s:access") { [weak self] in self?.showAccessibilityMenu() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let text = menuOpts[choice - 1].text
            if text == "?" {
                self.showAccessibilityHelp()
                return
            }
            if text == "< Back" {
                self.showSettings()
                return
            }
            switch text {
            case displaySizeLabel:
                self.recordSettingChange(screen: "s:access", key: "fontSizeSetting", name: "Size")
                self.recordSettingChange(screen: "s:access", key: "iconScaleSetting", name: "Icons")
                // Cycle through the sizes on offer, smallest to largest, then round again.
                let sizes = FontSizeSetting.choices
                let at = sizes.firstIndex(of: self.fontSizeSetting) ?? 0
                self.fontSizeSetting = sizes[(at + 1) % sizes.count]
                self.iconScaleSetting = self.fontSizeSetting.scale >= 1.6 ? 1 : 0
                UserDefaults.standard.set(self.iconScaleSetting, forKey: "iconScaleSetting")
                self.showAccessibilityMenu()
            case hitsLabel:
                self.recordSettingChange(screen: "s:access", key: "hit_animations", name: "Hits")
                self.hitAnimationsEnabled.toggle()
                self.showAccessibilityMenu()
            case dmVoiceLabel:
                self.recordSettingChange(screen: "s:access", key: "speechEnabled", name: "DM Voice")
                speech.isEnabled.toggle()
                self.showAccessibilityMenu()
            case "Companion Voices":
                self.showAdventurerVoiceSettings()
                self.closeHandler = { [weak self] in self?.showAccessibilityMenu() }
            case voiceMenuLabel:
                self.recordSettingChange(screen: "s:access", key: "voiceMenuEnabled", name: "Voice Menus")
                self.voiceMenuEnabled.toggle()
                UserDefaults.standard.set(self.voiceMenuEnabled, forKey: "voiceMenuEnabled")
                self.showAccessibilityMenu()
            case autoScrollLabel:
                self.recordSettingChange(screen: "s:access", key: "autoScrollSpeed", name: "Auto-Scroll")
                self.autoScrollSpeed = (self.autoScrollSpeed + 1) % 4
                UserDefaults.standard.set(self.autoScrollSpeed, forKey: "autoScrollSpeed")
                self.showAccessibilityMenu()
            case let label where label.hasPrefix("Animations:"):
                self.recordSettingChange(screen: "s:access", key: "reduceAnimations", name: "Animations")
                self.reduceAnimations.toggle()
                UserDefaults.standard.set(self.reduceAnimations, forKey: "reduceAnimations")
                if self.reduceAnimations { self.stopIdleAnimations() }
                self.showAccessibilityMenu()
            case "Right-Handed", "Left-Handed":
                self.recordSettingChange(screen: "s:access", key: "leftHanded", name: "Handedness")
                self.leftHanded.toggle()
                UserDefaults.standard.set(self.leftHanded, forKey: "leftHanded")
                self.showAccessibilityMenu()
            case let label where label.hasPrefix("Help Button:"):
                self.recordSettingChange(screen: "s:access", key: "helpGlyph", name: "Help Button")
                let glyphs = MenuOption.helpGlyphChoices
                let next = glyphs[((glyphs.firstIndex(of: MenuOption.helpGlyph) ?? 0) + 1) % glyphs.count]
                UserDefaults.standard.set(next, forKey: "helpGlyph")
                self.showAccessibilityMenu()
            case "Try Auto-Scroll":
                self.showAutoScrollDemo()
            case cursorLabel:
                self.recordSettingChange(screen: "s:access", key: "blinkingCursorEnabled", name: "Cursor")
                self.blinkingCursorEnabled.toggle()
                UserDefaults.standard.set(self.blinkingCursorEnabled, forKey: "blinkingCursorEnabled")
                self.showAccessibilityMenu()
            default: break
            }
        }
        // Long-press DM Voice opens voice settings
        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            let selected = options[choice - 1]
            if selected == dmVoiceLabel {
                self.showVoiceSettings()
            }
        }
    }

    private func showAccessibilityHelp() {
        showInlineHelp {
            self.printTitle("Accessibility Help")
            self.print("")

            self.print("  PLAYING YOUR WAY", color: .cyan, bold: true)
            self.printWrapped("Vision: Display Size, DM Voice (reads the story aloud), and VoiceOver — buttons, the D-pad and the map all have spoken labels, and decorative ASCII art is skipped. Hearing: every sound has a text equivalent. Motor: Long Press length, Left/Right-Handed, typing or voice instead of tapping, and long-press to skip confirmations. Reading at your own pace: pause the hourglass, turn Auto-Continue off, Auto-Scroll, Reduce Animations, and the ? help on every screen.", indent: 2, color: .dimGreen)
            self.printWrapped("With VoiceOver: set Card Navigation to Use Buttons (swipes clash with VoiceOver gestures), turn Auto-Continue off or lengthen Info Timeout, and turn Idle Prompts off so combat never penalises a slow turn. A long-press is VoiceOver's double-tap-and-hold. The full guide is in ACCESSIBILITY.md alongside the game.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  DISPLAY SIZE", color: .cyan, bold: true)
            self.printWrapped("Cycles through Small, Medium, and Large. This adjusts both text size and icon size together for a consistent look.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  HIT ANIMATIONS", color: .cyan, bold: true)
            self.printWrapped("Small screen flashes when attacks land in combat. Turn off if you find the flashing distracting or if you are sensitive to screen flashes.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  DM VOICE", color: .cyan, bold: true)
            self.printWrapped("Enables text-to-speech narration by the Dungeon Master. Reduces the need to read the screen — helpful for vision difficulties or a hands-free experience. Long-press to open voice configuration. Adjust speed and pitch from the voice preview screen.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  COMPANION VOICES", color: .cyan, bold: true)
            self.printWrapped("Give each party member a unique spoken voice in chat. Choose 'Character' for voices matched to each character or 'Random' for variety.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  VOICE MENUS", color: .cyan, bold: true)
            self.printWrapped("When on, a speaker icon and microphone icon appear on each screen. The speaker reads the screen aloud; the microphone lets you speak menu choices instead of tapping.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  FLASHING CURSOR", color: .cyan, bold: true)
            self.printWrapped("Off (the default): no blinking block cursor by the > prompt. On: it blinks there until you tap to type. Off by default the first time VoiceOver is detected running on this device — turn it off yourself if you use VoiceOver and it's still on.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    private func showGameplaySettings(page: Int = 0) {
        clearTerminal()
        printTitle("Gameplay")

        print("MAP LENGTH:", color: .cyan, bold: true)
        let hasTorch = party.contains { (char: Character) in
            char.inventory.contains { $0.name.lowercased().contains("torch") }
        }
        let effective = effectiveMapRadius()
        print("  Setting: \(mapLengthSetting)  Effective: \(effective)\(hasTorch ? "" : " (no torch!)")", color: hasTorch ? .dimGreen : .yellow)
        printWrapped("How far you can see on the dungeon map. Illuminate your torch to see further!", indent: 2, color: .dimGreen)
        print("")

        print("CARD NAVIGATION:", color: .cyan, bold: true)
        print("  \(useArrowNavigation ? "Use Buttons" : "Use Swipe")", color: .brightGreen)
        printWrapped("Use Buttons shows <</>> buttons and a dice for random on character cards. Use Swipe lets you swipe left/right across the screen to browse cards. Both modes support the random dice.", indent: 2, color: .dimGreen)
        print("")

        print("INFO TIMEOUT:", color: .cyan, bold: true)
        print("  \(String(format: "%.1fs", infoTimeout))", color: .brightGreen)
        printWrapped("How long information screens (search results, listen, examine) stay before moving on — every other tap-to-continue screen waits twice this. Only used while Auto-Continue is on. Tap the ✕ icon to move on sooner.", indent: 2, color: .dimGreen)
        print("")

        print("TIMEOUTS:", color: .cyan, bold: true)
        printWrapped("Make fights, loot, search results, tales and the rest quicker or slower, each on its own — see Timeouts.", indent: 2, color: .dimGreen)
        print("")

        print("AUTO-CONTINUE:", color: .cyan, bold: true)
        print("  \(autoContinueEnabled ? "On" : "Off")\(autoContinuePaused ? " (paused)" : "")", color: autoContinueEnabled ? .brightGreen : .red)
        printWrapped("Many screens wait for a tap so you can read them. With this on, they also move on by themselves after the Info Timeout. Tap the little hourglass at the right of the input line to pause, long-press it to hurry — or press Space on a Mac. See ? for more.", indent: 2, color: .dimGreen)
        print("")

        print("COUNTDOWN ICON:", color: .cyan, bold: true)
        print("  \(showCountdownControl ? "On" : "Off")", color: showCountdownControl ? .brightGreen : .red)
        printWrapped("The turning hourglass at the right of the input line while a screen counts down — tap to pause, long-press to hurry. Off hides it; screens still move on by themselves (Space on a Mac still pauses).", indent: 2, color: .dimGreen)
        print("")

        print("BUTTON LIMIT:", color: .cyan, bold: true)
        print("  \(maxButtonsPerScreen) per screen", color: .brightGreen)
        printWrapped("Maximum buttons shown at once. When a screen has more options, << and >> buttons let you page through them. Long-press to skip 3 pages.", indent: 2, color: .dimGreen)
        print("")

        print("LONG PRESS:", color: .cyan, bold: true)
        print("  \(String(format: "%.1fs", longPressDuration))", color: .brightGreen)
        printWrapped("How long you must hold a button for a long-press action (e.g. long rest, page jump). Lower values make long-press faster to trigger.", indent: 2, color: .dimGreen)
        print("")

        print("NPCs:", color: .cyan, bold: true)
        print("  \(npcsEnabled ? "Enabled" : "Disabled")", color: npcsEnabled ? .brightGreen : .red)
        printWrapped("Non-player characters spawn in dungeons. They can trade, heal, teach, and give information.", indent: 2, color: .dimGreen)
        print("")

        print("POISON:", color: .cyan, bold: true)
        print("  \(poisonEnabled ? "Enabled" : "Disabled")", color: poisonEnabled ? .brightGreen : .red)
        printWrapped("When enabled, venomous creatures can poison your party. Cure with antidotes, potions, or rest.", indent: 2, color: .dimGreen)
        print("")

        print("MULTIPLAYER:", color: .cyan, bold: true)
        print("  \(multiplayerEnabled ? "Enabled" : "Disabled")", color: multiplayerEnabled ? .brightGreen : .red)
        printWrapped("When enabled, you can invite remote players to control party members via Game Centre.", indent: 2, color: .dimGreen)
        print("")

        if multiplayerEnabled {
            print("DEGRADE REMOTE→ROBOT:", color: .cyan, bold: true)
            print("  \(degradeRemoteToRobot ? "Enabled" : "Disabled")", color: degradeRemoteToRobot ? .brightGreen : .red)
            printWrapped("When enabled, a remote player who never joins or leaves mid-game is switched to AI control automatically. When disabled (default), you'll see a \"Continue as Local Game?\" prompt each time instead.", indent: 2, color: .dimGreen)
            print("")
        }

        print("ADVENTURE LOG:", color: .cyan, bold: true)
        let logLimitText = adventureLogLimit == 0 ? "Show All" : "Last \(adventureLogLimit)"
        print("  \(logLimitText)", color: .brightGreen)
        printWrapped("How many log entries to display. 'Show All' can be slow for very long adventures.", indent: 2, color: .dimGreen)
        print("")

        print("TIME LIMIT:", color: .cyan, bold: true)
        let timeLimitText = gameTimeLimit == 0 ? "Off" : formatTimeLimitValue(gameTimeLimit)
        print("  \(timeLimitText)", color: gameTimeLimit == 0 ? .red : .brightGreen)
        printWrapped("Optional time limit for your adventure. When game time runs out, the game ends in defeat.", indent: 2, color: .dimGreen)
        print("")

        print("IDLE PROMPTS:", color: .cyan, bold: true)
        print("  \(idlePromptsEnabled ? "On" : "Off")", color: idlePromptsEnabled ? .brightGreen : .red)
        printWrapped("When on, the DM reacts if you take too long — eye blinks on ASCII art, combat hesitation penalties, and save menu nudges.", indent: 2, color: .dimGreen)
        print("")

        print("BLINKING CURSOR:", color: .cyan, bold: true)
        print("  \(blinkingCursorEnabled ? "On" : "Off")", color: blinkingCursorEnabled ? .brightGreen : .red)
        printWrapped("Off (the default): no blinking block cursor by the > prompt. On: it blinks there until you tap to type.", indent: 2, color: .dimGreen)
        print("")

        print("UNDO/REDO:", color: .cyan, bold: true)
        print("  \(undoRedoEnabled ? "On" : "Off")", color: undoRedoEnabled ? .brightGreen : .red)
        printWrapped("Show labelled Undo/Redo buttons when you change settings or edit adventurers. The label shows what will be reverted.", indent: 2, color: .dimGreen)
        print("")

        print("LIST ORDER:", color: .cyan, bold: true)
        print("  \(listSortMode.label)", color: .brightGreen)
        printWrapped("How Continue Adventure and Hall of Fame sort their lists — by date, points, name, or dungeon level.", indent: 2, color: .dimGreen)
        print("")

        print("WORLD MAP:", color: .cyan, bold: true)
        print("  \(atlasShowAllRooms ? "All Rooms" : "Visited Only")", color: .brightGreen)
        printWrapped("Whether the world map shows only rooms you've set foot in, or every room. Where's the world map? Cartographers keep their secrets — though a patient hand on the map, or a gym's dearest lesson, may tell.", indent: 2, color: .dimGreen)
        print("")

        print("ROBOT PREFIX:", color: .cyan, bold: true)
        print("  \(robotPrefixEnabled ? "On" : "Off")", color: robotPrefixEnabled ? .brightGreen : .red)
        printWrapped("Whether Computer (AI)-controlled party members get an \"R. \" name prefix — a nod to the robot characters in Isaac Asimov's novels.", indent: 2, color: .dimGreen)
        print("")

        print("UNITS:", color: .cyan, bold: true)
        print("  \(useMetricUnits ? "Metric (kg)" : "Imperial (lb)")", color: .brightGreen)
        printWrapped("How item and carry weight are displayed.", indent: 2, color: .dimGreen)
        print("")

        print("TELEPORT PADS:", color: .cyan, bold: true)
        print("  \(teleportPadsEnabled ? "On" : "Off")", color: teleportPadsEnabled ? .brightGreen : .red)
        printWrapped("Whether the D-pad's teleport icon appears in rooms with an active pad.", indent: 2, color: .dimGreen)
        print("")

        print("FIGHT CLUB:", color: .cyan, bold: true)
        print("  \(combatArenaEnabled ? "On" : "Off")", color: combatArenaEnabled ? .brightGreen : .red)
        #if os(macOS)
        printWrapped("During a fight, the space below the buttons acts it out in ASCII — lunges, arrows, spells, sparks, damage rising off the struck, the fallen — while the rest of each side cheers and jeers from the sidelines. Click @ on the input line to hide or show it — your choice stays for the next fight, even after a restart. Turn Fight Club Off here to remove the @ button altogether; best left off with VoiceOver, which can't describe the animation and may trip over it.", indent: 2, color: .dimGreen)
        #else
        printWrapped("In a fight, tap @ on the input line to watch it acted out in ASCII above the buttons — lunges, arrows, spells, sparks, and both sides cheering and jeering. Tap @ again to hide it — your choice stays for the next fight, even after a restart. Turn Fight Club Off here to remove the @ button altogether; best left off with VoiceOver, which can't describe the animation and may trip over it.", indent: 2, color: .dimGreen)
        #endif
        print("")

        print("DUNGEON QUIRKS:", color: .cyan, bold: true)
        print("  \(dungeonQuirksEnabled ? "On" : "Off")", color: dungeonQuirksEnabled ? .brightGreen : .red)
        printWrapped("Little oddities, off by default: the dragon's winks wander out of the pictures and into the words (\"g- -n\" — the DM still understands). Best left off with VoiceOver.", indent: 2, color: .dimGreen)
        print("")

        // Grouped: Interface (5) → Features (6/7) → System (6)
        var options = [
            // Page 1 — Interface
            "Map Length", useArrowNavigation ? "Use Swipe" : "Use Buttons",
            "Info Timeout", "Timeouts", autoContinueEnabled ? "Auto-Continue Off" : "Auto-Continue On",
            showCountdownControl ? "Countdown Icon Off" : "Countdown Icon On",
            "Button Limit", "Long Press",
            // Page 2 — Features
            npcsEnabled ? "NPCs Off" : "NPCs On", poisonEnabled ? "Poison Off" : "Poison On",
            multiplayerEnabled ? "Multi Off" : "Multi On",
        ]
        // Only meaningful (and only shown) while Multiplayer is on — sits
        // right next to the Multi toggle that gates it.
        if multiplayerEnabled {
            options.append(degradeRemoteToRobot ? "Remote→Robot Off" : "Remote→Robot On")
        }
        options.append(contentsOf: [
            "Time Limit",
            idlePromptsEnabled ? "Idle Off" : "Idle On",
            multipleShopsEnabled ? "Multi-Shop Off" : "Multi-Shop On",
            blinkingCursorEnabled ? "Cursor Off" : "Cursor On",
            teleportPadsEnabled ? "Teleport Off" : "Teleport On",
            combatArenaEnabled ? "Fight Club Off" : "Fight Club On",
            dungeonQuirksEnabled ? "Quirks Off" : "Quirks On",
            // Page 3 — System
            "Log Limit", "List Order",
            atlasShowAllRooms ? "World Map: Visited" : "World Map: All Rooms",
            robotPrefixEnabled ? "Robot Prefix Off" : "Robot Prefix On",
            useMetricUnits ? "Units: Imperial" : "Units: Metric",
        ])
        options.append(undoRedoEnabled ? "Undo/Redo Off" : "Undo/Redo On")

        let select: (Int) -> Void = { [weak self] idx in
            guard let self = self else { return }
            guard idx >= 0 && idx < options.count else { return }
            let currentPage = self.paginatedPage
            let selected = options[idx]
            if selected == "Map Length" {
                self.showMapRadiusMenu()
            } else if selected.hasPrefix("Use") {
                self.recordSettingChange(screen: "s:gameplay", key: "useArrowNavigation", name: "Nav")
                self.useArrowNavigation.toggle()
                UserDefaults.standard.set(self.useArrowNavigation, forKey: "useArrowNavigation")
                self.showGameplaySettings(page: currentPage)
            } else if selected == "Timeouts" {
                self.showTimeoutsSettings(onBack: { [weak self] in self?.showGameplaySettings() })
            } else if selected == "Info Timeout" {
                self.showInfoTimeoutMenu()
            } else if selected.hasPrefix("Countdown Icon") {
                self.recordSettingChange(screen: "s:gameplay", key: "showCountdownControl", name: "Countdown Icon")
                self.showCountdownControl.toggle()
                UserDefaults.standard.set(self.showCountdownControl, forKey: "showCountdownControl")
                // Hidden = no way to un-pause from the screen, so never leave it paused.
                if !self.showCountdownControl { self.autoContinuePaused = false }
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Auto-Continue") {
                self.recordSettingChange(screen: "s:gameplay", key: "autoContinueEnabled", name: "Auto-Continue")
                self.autoContinueEnabled.toggle()
                UserDefaults.standard.set(self.autoContinueEnabled, forKey: "autoContinueEnabled")
                if self.autoContinueEnabled { self.autoContinuePaused = false }
                self.showGameplaySettings(page: currentPage)
            } else if selected == "Button Limit" {
                self.showButtonLimitMenu()
            } else if selected == "Long Press" {
                self.showLongPressMenu()
            } else if selected.hasPrefix("Quirks") {
                self.recordSettingChange(screen: "s:gameplay", key: "dungeonQuirks", name: "Quirks")
                self.dungeonQuirksEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Fight Club") {
                self.recordSettingChange(screen: "s:gameplay", key: "combatArena", name: "Arena")
                self.combatArenaEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("NPCs") {
                self.recordSettingChange(screen: "s:gameplay", key: "npcs_enabled", name: "NPCs")
                self.npcsEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Poison") {
                self.recordSettingChange(screen: "s:gameplay", key: "poison_enabled", name: "Poison")
                self.poisonEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Multi-Shop") {
                // Must be checked before the plain "Multi" (multiplayer)
                // branch below — "Multi-Shop On/Off" also starts with
                // "Multi", so it was always matching that branch first and
                // toggling multiplayerEnabled instead of multipleShopsEnabled
                // whenever this button was tapped.
                self.recordSettingChange(screen: "s:gameplay", key: "multiple_shops_enabled", name: "Multi-Shop")
                self.multipleShopsEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Multi") {
                self.recordSettingChange(screen: "s:gameplay", key: "multiplayer_enabled", name: "Multi")
                self.multiplayerEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Remote→Robot") {
                self.recordSettingChange(screen: "s:gameplay", key: "degrade_remote_to_robot", name: "Remote→Robot")
                self.degradeRemoteToRobot.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Teleport") {
                self.recordSettingChange(screen: "s:gameplay", key: "teleport_pads_enabled", name: "Teleport")
                self.teleportPadsEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("World Map") {
                self.recordSettingChange(screen: "s:gameplay", key: "atlasShowAllRooms", name: "World Map")
                self.atlasShowAllRooms.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected == "Log Limit" {
                self.showLogLimitMenu()
            } else if selected == "List Order" {
                self.showListSortMenu()
            } else if selected.hasPrefix("Robot Prefix") {
                self.recordSettingChange(screen: "s:gameplay", key: "robot_prefix_enabled", name: "Robot Prefix")
                self.robotPrefixEnabled.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Units:") {
                self.recordSettingChange(screen: "s:gameplay", key: "use_metric_units", name: "Units")
                self.useMetricUnits.toggle()
                self.showGameplaySettings(page: currentPage)
            } else if selected == "Time Limit" {
                self.showTimeLimitMenu()
            } else if selected.hasPrefix("Idle") {
                self.recordSettingChange(screen: "s:gameplay", key: "idlePromptsEnabled", name: "Idle")
                self.idlePromptsEnabled.toggle()
                UserDefaults.standard.set(self.idlePromptsEnabled, forKey: "idlePromptsEnabled")
                if !self.idlePromptsEnabled {
                    self.stopIdleAnimations()
                    self.cancelCombatIdleTimer()
                    self.cancelSaveMenuIdleTimer()
                }
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Cursor") {
                self.recordSettingChange(screen: "s:gameplay", key: "blinkingCursorEnabled", name: "Cursor")
                self.blinkingCursorEnabled.toggle()
                UserDefaults.standard.set(self.blinkingCursorEnabled, forKey: "blinkingCursorEnabled")
                self.showGameplaySettings(page: currentPage)
            } else if selected.hasPrefix("Undo/Redo") {
                self.recordSettingChange(screen: "s:gameplay", key: "undoRedoEnabled", name: "Undo/Redo")
                self.undoRedoEnabled.toggle()
                if !self.undoRedoEnabled {
                    self.clearAllUndoRedo()
                }
                self.showGameplaySettings(page: currentPage)
            }
        }
        showPaginatedMenuOptions(options, page: page, pinned: ["?", "< Back"], handler: select, pinnedHandler: { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 0: self.showGameplaySettingsHelp()
            default: self.showSettings()
            }
        })

        // Tap a setting's own text (its heading or value line) to do what its
        // button does — toggles flip in place, pickers open. Logged like any
        // other settings change.
        let textTargets: [(heading: String, matches: (String) -> Bool)] = [
            ("MAP LENGTH:", { $0 == "Map Length" }),
            ("CARD NAVIGATION:", { $0.hasPrefix("Use ") }),
            ("INFO TIMEOUT:", { $0 == "Info Timeout" }),
            ("AUTO-CONTINUE:", { $0.hasPrefix("Auto-Continue") }),
            ("COUNTDOWN ICON:", { $0.hasPrefix("Countdown Icon") }),
            ("BUTTON LIMIT:", { $0 == "Button Limit" }),
            ("LONG PRESS:", { $0 == "Long Press" }),
            ("NPCs:", { $0.hasPrefix("NPCs") }),
            ("POISON:", { $0.hasPrefix("Poison") }),
            ("MULTIPLAYER:", { $0 == "Multi On" || $0 == "Multi Off" }),
            ("DEGRADE REMOTE→ROBOT:", { $0.hasPrefix("Remote→Robot") }),
            ("ADVENTURE LOG:", { $0 == "Log Limit" }),
            ("TIME LIMIT:", { $0 == "Time Limit" }),
            ("IDLE PROMPTS:", { $0.hasPrefix("Idle") }),
            ("BLINKING CURSOR:", { $0.hasPrefix("Cursor") }),
            ("UNDO/REDO:", { $0.hasPrefix("Undo/Redo") }),
            ("LIST ORDER:", { $0 == "List Order" }),
            ("ROBOT PREFIX:", { $0.hasPrefix("Robot Prefix") }),
            ("UNITS:", { $0.hasPrefix("Units:") }),
            ("TELEPORT PADS:", { $0.hasPrefix("Teleport") }),
            ("WORLD MAP:", { $0.hasPrefix("World Map") }),
        ]
        var lineTargets: [Int: (heading: String, option: Int)] = [:]
        for (i, line) in terminalLines.enumerated() {
            guard let target = textTargets.first(where: { line.text.hasPrefix($0.heading) }),
                  let optionIndex = options.firstIndex(where: target.matches) else { continue }
            lineTargets[i] = (target.heading, optionIndex)
            if i + 1 < terminalLines.count { lineTargets[i + 1] = (target.heading, optionIndex) }
        }
        textLongPressHandler = { [weak self] lineIndex in
            guard let target = lineTargets[lineIndex] else { return }
            self?.logEvent("Changed \(target.heading.dropLast()) by tapping its text", category: "SETTINGS")
            select(target.option)
        }
        closeHandler = { [weak self] in self?.showSettings() }
        installSettingUndoRedo(screen: "s:gameplay") { [weak self] in self?.showGameplaySettings(page: self?.paginatedPage ?? 0) }
    }

