    // MARK: - Settings Backup/Restore

    /// All UserDefaults keys used by the game
    private static let settingsKeys: [String] = [
        "maxButtonsPerScreen", "longPressDuration", "infoTimeout", "customInfoTimeouts", "autoContinueEnabled", "showCountdownControl", "atlasShowAllRooms", "autoScrollSpeed", "leftHanded", "helpGlyph", "reduceAnimations",
        "map_radius", "useArrowNavigation", "multiplayer_enabled", "npcs_enabled",
        "multiple_shops_enabled",
        "hit_animations", "voiceMenuEnabled", "iconScaleSetting", "adventureLogLimit",
        "fontSizeSetting", "music_enabled", "battle_sounds_enabled",
        "autosave_interval", "dmProvider", "dmAdLibLevel", "dmLogContextSize",
        // Note: deliberately excludes each provider's own API key
        // (AIProvider.userDefaultsKey) — those are backed up/restored via
        // the dedicated, encrypted Keychain flow instead of this plaintext
        // plist, not duplicated into it.
        "speechEnabled", "companionVoiceMode",
        "menu_melody", "exploration_melody", "combat_melody", "chat_melody",
        "gameTimeLimit", "useCustomKeyboard", "undoRedoEnabled",
        "justDMMode", "mac_map_rows", "combatArena", "followSystemTextSize", "dungeonQuirks", "fightClubOn",
    ]

    private func exportSettings() -> [String: Any] {
        var dict: [String: Any] = [:]
        for key in Self.settingsKeys {
            if let val = UserDefaults.standard.object(forKey: key) {
                dict[key] = val
            }
        }
        return dict
    }

    private func importSettings(_ dict: [String: Any]) {
        for (key, value) in dict {
            UserDefaults.standard.set(value, forKey: key)
        }
    }

    /// A handful of settings are cached in @Published vars read once from
    /// UserDefaults at property-init time, so writing UserDefaults directly
    /// (as importSettings does) doesn't move them — call this right after
    /// importSettings so a loaded backup takes effect immediately instead of
    /// requiring the player to force-quit and relaunch the app.
    private func refreshCachedPublishedSettings() {
        let d = UserDefaults.standard
        voiceMenuEnabled = (d.object(forKey: "voiceMenuEnabled") as? Bool) ?? true
        useArrowNavigation = d.object(forKey: "useArrowNavigation") == nil ? false : d.bool(forKey: "useArrowNavigation")
        infoTimeout = d.object(forKey: "infoTimeout") == nil ? 5.0 : d.double(forKey: "infoTimeout")
        autoContinueEnabled = d.object(forKey: "autoContinueEnabled") == nil ? true : d.bool(forKey: "autoContinueEnabled")
        showCountdownControl = d.object(forKey: "showCountdownControl") == nil ? true : d.bool(forKey: "showCountdownControl")
        autoScrollSpeed = d.integer(forKey: "autoScrollSpeed")
        iconScaleSetting = d.integer(forKey: "iconScaleSetting")
        useCustomKeyboard = d.object(forKey: "useCustomKeyboard") == nil ? true : d.bool(forKey: "useCustomKeyboard")
        idlePromptsEnabled = d.object(forKey: "idlePromptsEnabled") == nil ? true : d.bool(forKey: "idlePromptsEnabled")
        blinkingCursorEnabled = d.object(forKey: "blinkingCursorEnabled") == nil ? false : d.bool(forKey: "blinkingCursorEnabled")
        justDMMode = d.bool(forKey: "justDMMode")
    }

    /// Writes a settings snapshot straight to disk with no on-screen feedback —
    /// used internally to capture an automatic "before you loaded a backup"
    /// safety copy, distinct from the user-facing Save As / Quick Save actions.
    private func silentlySaveSettingsSnapshot(name: String) {
        let dict = exportSettings()
        guard let data = try? PropertyListSerialization.data(fromPropertyList: dict, format: .xml, options: 0) else { return }
        try? data.write(to: settingsBackupURL(name: name))
    }

    /// Plain, redacted (API key hidden) listing of a settings dict's raw keys
    /// and values — enough to see what a backup actually contains before
    /// applying it, without needing a full labeled-field editor.
    private func settingsSummaryLines(_ dict: [String: Any]) -> [String] {
        // API keys are never in this dict (see the exclusion note on
        // settingsKeys above), so nothing here needs redacting.
        dict.keys.sorted().map { key in "  \(key): \(dict[key] ?? "")" }
    }

    private func settingsBackupDir() -> URL {
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!
        let dir = docs.appendingPathComponent("SettingsBackups")
        if !FileManager.default.fileExists(atPath: dir.path) {
            try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        }
        return dir
    }

    private func settingsBackupURL(name: String) -> URL {
        settingsBackupDir().appendingPathComponent("\(name).plist")
    }

    private func listSettingsBackups() -> [(name: String, date: Date)] {
        let dir = settingsBackupDir()
        guard let files = try? FileManager.default.contentsOfDirectory(atPath: dir.path) else { return [] }
        var results: [(name: String, date: Date)] = []
        for file in files where file.hasSuffix(".plist") {
            let name = String(file.dropLast(6)) // remove .plist
            let path = dir.appendingPathComponent(file).path
            let date = (try? FileManager.default.attributesOfItem(atPath: path))?[.modificationDate] as? Date ?? .distantPast
            results.append((name, date))
        }
        return results.sorted { $0.date > $1.date }
    }

    // Migrate old single-file backup if it exists
    private func migrateOldBackup() {
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!
        let oldFile = docs.appendingPathComponent("DnDSettings.plist")
        if FileManager.default.fileExists(atPath: oldFile.path) {
            let newFile = settingsBackupURL(name: "Backup")
            try? FileManager.default.moveItem(at: oldFile, to: newFile)
        }
    }

    /// The screen "Save Settings" opens — tapping that button no longer
    /// instantly saves anything; it lands here, where Quick Save, Save As,
    /// Load, Delete, and API key backup/restore all live together.
    private func showSettingsBackupMenu() {
        migrateOldBackup()
        clearTerminal()
        printTitle("Save Settings")
        printWrapped("Save, load, or manage settings and API key backups.", indent: 2, color: .dimGreen)
        print("")

        let backups = listSettingsBackups()
        let fmt = DateFormatter()
        fmt.dateStyle = .medium
        fmt.timeStyle = .short

        if backups.isEmpty {
            print("  No backups yet.", color: .dimGreen)
        } else {
            print("  BACKUPS:", color: .cyan, bold: true)
            for b in backups {
                print("  \(b.name) — \(fmt.string(from: b.date))", color: .brightGreen)
            }
        }
        print("")

        let hasKeychainBackup = loadAPIKeysFromKeychain() != nil
        print("API KEY BACKUP:", color: .cyan, bold: true)
        print("  \(hasKeychainBackup ? "Saved to Keychain" : "Not backed up")", color: hasKeychainBackup ? .brightGreen : .dimGreen)
        print("")

        var options = ["Quick Save", "Save As"]
        if !backups.isEmpty {
            options.append("Load")
            options.append("Delete Backup")
        }
        options.append(hasKeychainBackup ? "Restore API Keys" : "Backup API Keys")

        var menuOpts = options.map { MenuOption($0) }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)
        let backToSettings: () -> Void = { [weak self] in self?.showSettings() }
        closeHandler = backToSettings
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == menuOpts.count {
                backToSettings()
                return
            }
            if choice == menuOpts.count - 1 {
                self.showInlineHelp {
                    self.printTitle("Save Settings — Help")
                    self.print("")
                    self.print("  QUICK SAVE", color: .cyan, bold: true)
                    self.printWrapped("Instantly saves your current settings over a fixed 'Quick Save' slot, and backs up your API keys to the device Keychain — one tap, no naming needed.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  SAVE AS", color: .cyan, bold: true)
                    self.printWrapped("Saves your current settings under a name you choose, alongside any others — use this to keep multiple backups instead of overwriting 'Quick Save'.", indent: 2, color: .dimGreen)
                    self.print("")
                    if !backups.isEmpty {
                        self.print("  LOAD", color: .cyan, bold: true)
                        self.printWrapped("Shows exactly what's in a saved backup before applying it. Applies instantly — no restart needed — and automatically saves your previous settings as 'Before Load' first, with an Undo button right there if you change your mind.", indent: 2, color: .dimGreen)
                        self.print("")
                        self.print("  DELETE BACKUP", color: .cyan, bold: true)
                        self.printWrapped("Removes a saved backup permanently.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                    self.print("  BACKUP / RESTORE API KEYS", color: .cyan, bold: true)
                    self.printWrapped("Saves your AI provider API keys to the device Keychain for safe keeping (this also happens automatically with Quick Save). Restore retrieves them if they're ever cleared. The Keychain is encrypted and persists across app reinstalls.", indent: 2, color: .dimGreen)
                    self.print("")
                }
                return
            }
            let selected = options[choice - 1]
            if selected == "Quick Save" {
                self.quickSaveSettings()
            } else if selected == "Save As" {
                self.promptNewBackupName()
            } else if selected == "Load" {
                self.showLoadBackupMenu()
            } else if selected == "Delete Backup" {
                self.showDeleteBackupMenu()
            } else if selected == "Backup API Keys" {
                self.backupAPIKeysToKeychain()
            } else if selected == "Restore API Keys" {
                self.restoreAPIKeysFromKeychain()
            }
        }
    }

    private func promptNewBackupName() {
        clearTerminal()
        printTitle("New Backup")
        printWrapped("Enter a name for this backup:", indent: 2, color: .dimGreen)
        print("")

        let suggestion = "Settings " + Self.saveStamp()

        promptTextWithMenu("", options: [suggestion])
        closeHandler = { [weak self] in self?.showSettingsBackupMenu() }
        menuHandler = { [weak self] choice in
            // Button 1 = use the suggested name
            self?.saveBackupWithName(suggestion)
        }
        inputHandler = { [weak self] input in
            let name = input.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !name.isEmpty else { return }
            // Sanitise: remove path separators
            let safe = name.replacingOccurrences(of: "/", with: "-").replacingOccurrences(of: ":", with: "-")
            self?.saveBackupWithName(safe)
        }
    }

    private func saveBackupWithName(_ name: String) {
        let dict = exportSettings()
        let data = try? PropertyListSerialization.data(fromPropertyList: dict, format: .xml, options: 0)
        if let data = data {
            try? data.write(to: settingsBackupURL(name: name))
            print("")
            print("  Saved backup: \(name)", color: .brightGreen)
        } else {
            print("")
            print("  Failed to save backup.", color: .red)
        }
        waitForContinue()
        inputHandler = { [weak self] _ in self?.showSettingsBackupMenu() }
    }

    private func showLoadBackupMenu() {
        clearTerminal()
        printTitle("Load Settings")
        print("  Pick a backup to preview before applying.", color: .dimGreen)
        print("")

        let backups = listSettingsBackups()
        let names = backups.map { $0.name }

        showPaginatedMenu(names) { [weak self] idx in
            guard let self = self, idx >= 0 && idx < backups.count else { return }
            self.showBackupPreview(backups[idx])
        }
        closeHandler = { [weak self] in self?.showSettingsBackupMenu() }
    }

    /// Shows exactly what a backup contains (a plain key/value listing, API
    /// key redacted) before committing to anything — answers "what am I
    /// actually about to load" instead of a blind "overwrite?" prompt.
    private func showBackupPreview(_ backup: (name: String, date: Date)) {
        clearTerminal()
        printTitle("Preview: \(backup.name)")
        let url = settingsBackupURL(name: backup.name)
        guard let data = try? Data(contentsOf: url),
              let dict = try? PropertyListSerialization.propertyList(from: data, options: [], format: nil) as? [String: Any] else {
            print("  Failed to read backup.", color: .red)
            print("")
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showLoadBackupMenu() }
            return
        }
        printWrapped("This backup contains \(dict.count) saved setting\(dict.count == 1 ? "" : "s"):", indent: 2, color: .dimGreen)
        print("")
        printLines(settingsSummaryLines(dict), color: .dimGreen)
        print("")
        showMenu(["Apply", "< Cancel"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            guard choice == 1 else {
                self.showLoadBackupMenu()
                return
            }
            // Snapshot current settings first, both to disk (visible as a
            // normal backup, same as "Before Reset") and in memory (so Undo
            // below doesn't need a round-trip through the filesystem).
            let before = self.exportSettings()
            self.silentlySaveSettingsSnapshot(name: "Before Load")
            self.importSettings(dict)
            self.refreshCachedPublishedSettings()
            self.clearTerminal()
            self.printTitle("Settings Applied")
            self.print("")
            self.print("  Settings restored from \(backup.name).", color: .brightGreen)
            self.print("  Applied instantly — no restart needed.", color: .dimGreen)
            self.print("  Your previous settings were saved as", color: .dimGreen)
            self.print("  'Before Load' if you want them back.", color: .dimGreen)
            self.print("")
            self.showMenu(["Undo", "Done"])
            self.menuHandler = { [weak self] choice in
                guard let self = self else { return }
                if choice == 1 {
                    self.importSettings(before)
                    self.refreshCachedPublishedSettings()
                    self.print("")
                    self.print("  Reverted to your previous settings.", color: .yellow)
                    self.print("")
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.showSettingsBackupMenu() }
                } else {
                    self.showSettingsBackupMenu()
                }
            }
        }
        closeHandler = { [weak self] in self?.showLoadBackupMenu() }
    }

    private func showDeleteBackupMenu() {
        clearTerminal()
        printTitle("Delete Backup")
        print("")

        let backups = listSettingsBackups()
        let names = backups.map { $0.name }

        showPaginatedMenu(names) { [weak self] idx in
            guard let self = self, idx >= 0 && idx < backups.count else { return }
            let backup = backups[idx]
            self.clearTerminal()
            self.printTitle("Delete: \(backup.name)")
            self.print("  This cannot be undone.", color: .red)
            self.print("")
            self.showMenu(["Yes, Delete", "< Cancel"], defaultIndex: 1)
            self.menuHandler = { [weak self] choice in
                guard let self = self else { return }
                if choice == 1 {
                    let url = self.settingsBackupURL(name: backup.name)
                    try? FileManager.default.removeItem(at: url)
                    self.print("")
                    self.print("  Deleted \(backup.name).", color: .yellow)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.showSettingsBackupMenu() }
                } else {
                    self.showDeleteBackupMenu()
                }
            }
        }
        closeHandler = { [weak self] in self?.showSettingsBackupMenu() }
    }

    // MARK: - API Key Keychain Backup

    private let keychainServicePrefix = "com.dndtextrpg.apikey."

    private func loadAPIKeyFromKeychain(for provider: AIProvider) -> String? {
        let key = provider.userDefaultsKey
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: keychainServicePrefix + key,
            kSecAttrAccount as String: key,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]
        var item: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &item)
        if status == errSecSuccess, let data = item as? Data, let value = String(data: data, encoding: .utf8) {
            return value
        }
        return nil
    }

    private func deleteSingleAPIKeyFromKeychain(for provider: AIProvider) {
        let key = provider.userDefaultsKey
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: keychainServicePrefix + key,
            kSecAttrAccount as String: key
        ]
        SecItemDelete(query as CFDictionary)
    }

    private func backupSingleAPIKeyToKeychain(for provider: AIProvider) {
        let key = provider.userDefaultsKey
        guard let value = UserDefaults.standard.string(forKey: key), !value.isEmpty,
              let data = value.data(using: .utf8) else { return }
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: keychainServicePrefix + key,
            kSecAttrAccount as String: key
        ]
        SecItemDelete(query as CFDictionary)
        var addQuery = query
        addQuery[kSecValueData as String] = data
        SecItemAdd(addQuery as CFDictionary, nil)
    }

    private func loadAPIKeysFromKeychain() -> [String: String]? {
        var result: [String: String] = [:]
        for provider in AIProvider.allCases {
            let key = provider.userDefaultsKey
            let query: [String: Any] = [
                kSecClass as String: kSecClassGenericPassword,
                kSecAttrService as String: keychainServicePrefix + key,
                kSecAttrAccount as String: key,
                kSecReturnData as String: true,
                kSecMatchLimit as String: kSecMatchLimitOne
            ]
            var item: CFTypeRef?
            let status = SecItemCopyMatching(query as CFDictionary, &item)
            if status == errSecSuccess, let data = item as? Data, let value = String(data: data, encoding: .utf8) {
                result[key] = value
            }
        }
        return result.isEmpty ? nil : result
    }

    private func backupAPIKeysToKeychain() {
        print("")
        print("  Saving API keys to device Keychain...", color: .dimGreen)
        var backed = 0
        for provider in AIProvider.allCases {
            let key = provider.userDefaultsKey
            guard let value = UserDefaults.standard.string(forKey: key), !value.isEmpty else { continue }
            guard let data = value.data(using: .utf8) else { continue }

            let query: [String: Any] = [
                kSecClass as String: kSecClassGenericPassword,
                kSecAttrService as String: keychainServicePrefix + key,
                kSecAttrAccount as String: key
            ]
            // Delete existing item first
            SecItemDelete(query as CFDictionary)
            // Add new item
            var addQuery = query
            addQuery[kSecValueData as String] = data
            let status = SecItemAdd(addQuery as CFDictionary, nil)
            if status == errSecSuccess {
                backed += 1
                print("  ✓ \(provider.displayName) key saved", color: .brightGreen)
            } else {
                print("  ✗ \(provider.displayName) key failed (error \(status))", color: .red)
            }
        }
        print("")
        if backed > 0 {
            print("  \(backed) API key\(backed == 1 ? "" : "s") backed up to Keychain.", color: .brightGreen)
            print("  Keys are encrypted and persist across reinstalls.", color: .dimGreen)
        } else {
            print("  No API keys configured to back up.", color: .yellow)
            print("  Set up a provider key in DM Settings first.", color: .dimGreen)
        }
        print("")
        waitForContinue()
        inputHandler = { [weak self] _ in self?.showSettingsBackupMenu() }
    }

    private func restoreAPIKeysFromKeychain() {
        print("")
        print("  Checking device Keychain for saved API keys...", color: .dimGreen)
        guard let keys = loadAPIKeysFromKeychain() else {
            print("")
            print("  No API keys found in Keychain.", color: .yellow)
            print("  Use 'Backup API Keys' to save them first.", color: .dimGreen)
            print("")
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showSettingsBackupMenu() }
            return
        }
        var restored = 0
        for (key, value) in keys {
            UserDefaults.standard.set(value, forKey: key)
            restored += 1
            // Find provider name for display
            let providerName = AIProvider.allCases.first(where: { $0.userDefaultsKey == key })?.displayName ?? key
            print("  ✓ \(providerName) key restored", color: .brightGreen)
        }
        print("")
        print("  \(restored) API key\(restored == 1 ? "" : "s") restored from Keychain.", color: .brightGreen)
        print("")
        waitForContinue()
        inputHandler = { [weak self] _ in self?.showSettingsBackupMenu() }
    }

    /// The Keychain-writing work behind "Backup API Keys", with no printing
    /// or waiting — so Quick Save can fold it into one action silently.
    @discardableResult
    private func backupAllAPIKeysToKeychainQuietly() -> Int {
        var backed = 0
        for provider in AIProvider.allCases {
            let key = provider.userDefaultsKey
            guard let value = UserDefaults.standard.string(forKey: key), !value.isEmpty,
                  let data = value.data(using: .utf8) else { continue }
            let query: [String: Any] = [
                kSecClass as String: kSecClassGenericPassword,
                kSecAttrService as String: keychainServicePrefix + key,
                kSecAttrAccount as String: key
            ]
            SecItemDelete(query as CFDictionary)
            var addQuery = query
            addQuery[kSecValueData as String] = data
            if SecItemAdd(addQuery as CFDictionary, nil) == errSecSuccess {
                backed += 1
            }
        }
        return backed
    }

    /// This screen is specifically about GAMEPLAY saves (autosave and save
    /// files) — settings/API key backup lives under "Save Settings" instead,
    /// a separate concern reached from the main Settings screen.
    private func showSaveSettings() {
        clearTerminal()
        printTitle("Game Saves")

        print("AUTOSAVE:", color: .cyan, bold: true)
        print("  \(autosaveInterval.displayName)", color: .brightGreen)
        printWrapped("Automatically saves your game at regular intervals. Saves appear in the Play menu.", indent: 2, color: .dimGreen)
        print("")

        let saves = SaveGameManager.shared.listAllSaves()
        let adventuresInUse = SaveGameManager.shared.listSlots().count
        print("GAME SAVES:", color: .cyan, bold: true)
        print("  \(adventuresInUse)/\(SaveGameManager.limitLabel(SaveGameManager.maxSlotsSetting)) adventures (\(saves.count) save file\(saves.count == 1 ? "" : "s"))", color: .dimGreen)
        print("")

        print("KEEPING SAVES:", color: .cyan, bold: true)
        print("  Adventures: \(SaveGameManager.limitLabel(SaveGameManager.maxSlotsSetting))", color: .brightGreen)
        print("  Save points each: \(SaveGameManager.limitLabel(SaveGameManager.savePointsSetting))", color: .brightGreen)
        print("  Keep: \(SaveGameManager.keepStrategy.label)   Protect wins: \(SaveGameManager.protectWins ? "On" : "Off")", color: .brightGreen)
        printWrapped("Max Saves limits how many adventures are kept; Save Points how many save points each keeps. Keep: Newest keeps the most recent ones; Spread Out keeps recent ones plus a few from further back. Protect Wins never trims an adventure you won.", indent: 2, color: .dimGreen)
        print("")

        var options = ["Autosave", "Max Saves", "Save Points",
                       SaveGameManager.keepStrategy == .newest ? "Keep: Spread Out" : "Keep: Newest",
                       SaveGameManager.protectWins ? "Protect Wins Off" : "Protect Wins On"]
        if !saves.isEmpty {
            options.append("Manage Saves")
            options.append("Clear All Saves")
        }

        var menuOpts = options.map { MenuOption($0) }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)
        closeHandler = { [weak self] in self?.showSettings() }
        installSettingUndoRedo(screen: "s:save") { [weak self] in self?.showSaveSettings() }
        // Long-press Clear All Saves skips the confirmation.
        menuLongPressHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= options.count, options[choice - 1] == "Clear All Saves" else { return }
            for save in SaveGameManager.shared.listAllSaves() { SaveGameManager.shared.delete(id: save.id) }
            self.showSaveSettings()
            self.print("All saves deleted.", color: .yellow)
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == menuOpts.count {
                self.showSettings()
                return
            }
            if choice == menuOpts.count - 1 {
                self.showSaveSettingsHelp()
                return
            }
            let selected = options[choice - 1]
            if selected == "Autosave" {
                self.showAutosaveMenu()
            } else if selected == "Max Saves" {
                self.showMaxSavesMenu()
            } else if selected == "Save Points" {
                self.showSavePointsMenu()
            } else if selected.hasPrefix("Keep:") {
                SaveGameManager.keepStrategy = SaveGameManager.keepStrategy == .newest ? .spread : .newest
                self.showSaveSettings()
            } else if selected.hasPrefix("Protect Wins") {
                SaveGameManager.protectWins.toggle()
                self.showSaveSettings()
            } else if selected == "Manage Saves" {
                self.showManageSavesMenu(returnTo: .settings)
            } else if selected == "Clear All Saves" {
                self.confirmClearAllSaves()
            }
        }
    }

    /// Picker for SaveGameManager.maxSlots. Only offers limits at or above
    /// the number of adventures already saved — picking a lower one would
    /// make the very next save's slot trim silently delete the oldest
    /// adventures, which is exactly the kind of quiet loss to avoid.
    private func showMaxSavesMenu() {
        clearTerminal()
        printTitle("Max Saves")
        let current = SaveGameManager.maxSlotsSetting
        let inUse = SaveGameManager.shared.listSlots().count
        printWrapped("How many separate adventures to keep. Currently \(SaveGameManager.limitLabel(current)); \(inUse) in use.", indent: 2, color: .dimGreen)
        printWrapped("Limits below the number you've already saved aren't offered — lowering it would delete your oldest adventures. Delete some first (Manage Saves) if you want a lower limit.", indent: 2, color: .dimGreen)
        print("")

        let allowed = SaveGameManager.maxSlotsChoices.filter { $0 == SaveGameManager.unlimited || $0 >= inUse }
        let choices = allowed
        var opts = choices.map { value -> MenuOption in
            let label = value == SaveGameManager.unlimited ? "Unlimited" : "\(value) adventures"
            return MenuOption(label + (value == current ? " ✓" : ""), isDefault: value == current)
        }
        opts.append(MenuOption("?", tint: .navigation, compact: true))
        opts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(opts)
        closeHandler = { [weak self] in self?.showSaveSettings() }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= opts.count else { return }
            if choice <= choices.count {
                UserDefaults.standard.set(choices[choice - 1], forKey: "maxSaveSlots")
                self.showSaveSettings()
            } else if opts[choice - 1].text == "?" {
                self.showInlineHelp {
                    self.printTitle("Max Saves — Help")
                    self.print("")
                    self.printWrapped("Each adventure keeps up to \(SaveGameManager.limitLabel(SaveGameManager.savePointsSetting)) save points (see Save Points); this limits how many different adventures are kept at once. Once you're at the limit, saving a brand new adventure asks which existing one to replace. Unlimited never asks — just keep an eye on storage. Won adventures don't count towards the limit while Protect Wins is on.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else {
                self.showSaveSettings()
            }
        }
    }

    /// Picker for SaveGameManager.savePointsSetting — save points kept per
    /// adventure. Lowering it trims each adventure the next time it saves.
    private func showSavePointsMenu() {
        clearTerminal()
        printTitle("Save Points")
        let current = SaveGameManager.savePointsSetting
        printWrapped("How many save points each adventure keeps — every save you make is a point you can go back to. Currently \(SaveGameManager.limitLabel(current)).", indent: 2, color: .dimGreen)
        printWrapped("Which ones survive is set by Keep (\(SaveGameManager.keepStrategy.label)). A lower limit trims each adventure the next time it's saved.", indent: 2, color: .dimGreen)
        print("")
        let choices = SaveGameManager.savePointChoices
        var opts = choices.map { value -> MenuOption in
            let label = value == SaveGameManager.unlimited ? "Unlimited" : "\(value) save points"
            return MenuOption(label + (value == current ? " ✓" : ""), isDefault: value == current)
        }
        opts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(opts)
        closeHandler = { [weak self] in self?.showSaveSettings() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= choices.count {
                UserDefaults.standard.set(choices[choice - 1], forKey: "maxSavePointsPerAdventure")
            }
            self.showSaveSettings()
        }
    }

