    /// The unified Reset screen — combines what used to be a separate plain
    /// "Reset" (settings only) and "Factory Reset" (settings + saves + keys)
    /// into one screen with three independent toggles, so any combination
    /// is a normal option rather than two hardcoded presets. Settings backup
    /// files are never touched by any combination of these toggles — restoring
    /// one afterwards (via Save Settings > Load) is always still possible.
    private func confirmResetToDefaults(resetSettings: Bool = true, clearKeys: Bool = false, deleteSaves: Bool = false) {
        clearTerminal()
        printTitle("Reset")
        print("")
        printWrapped("Choose what to reset, then Apply.", indent: 2, color: .dimGreen)
        print("")
        let resetLineStart = terminalLines.count
        print("  [\(resetSettings ? "x" : " ")] Reset Settings to Defaults", color: resetSettings ? .brightGreen : .dimGreen)
        let resetLineRange = resetLineStart..<terminalLines.count

        let clearKeysLineStart = terminalLines.count
        print("  [\(clearKeys ? "x" : " ")] Also Clear API Keys", color: clearKeys ? .yellow : .dimGreen)
        let clearKeysLineRange = clearKeysLineStart..<terminalLines.count

        let deleteSavesLineStart = terminalLines.count
        print("  [\(deleteSaves ? "x" : " ")] Also Delete Saved Games", color: deleteSaves ? .yellow : .dimGreen)
        let deleteSavesLineRange = deleteSavesLineStart..<terminalLines.count
        print("")
        printWrapped("Settings backups are never affected — you can always restore one afterwards from Save Settings.", indent: 2, color: .dimGreen)
        print("")

        var options = ["Reset Settings: \(resetSettings ? "On" : "Off")",
                        "Clear API Keys: \(clearKeys ? "On" : "Off")",
                        "Delete Saves: \(deleteSaves ? "On" : "Off")"]
        if resetSettings {
            options.append("Review Setting Changes")
        }
        options.append("Save Settings First")
        options.append("Load a Backup")
        let anySelected = resetSettings || clearKeys || deleteSaves
        options.append("Apply")

        var menuOpts = options.map { MenuOption($0) }
        if let applyIdx = options.firstIndex(of: "Apply") {
            menuOpts[applyIdx] = MenuOption("Apply", isDisabled: !anySelected, tint: (clearKeys || deleteSaves) ? .danger : .normal)
        }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)
        // Tap the printed checkbox row itself, not just its numbered
        // button below — despite the name, textLongPressHandler drives a
        // plain tap gesture on the terminal text (see textTapEnabled).
        textLongPressHandler = { [weak self] lineIndex in
            guard let self = self else { return }
            if resetLineRange.contains(lineIndex) {
                self.confirmResetToDefaults(resetSettings: !resetSettings, clearKeys: clearKeys, deleteSaves: deleteSaves)
            } else if clearKeysLineRange.contains(lineIndex) {
                self.confirmResetToDefaults(resetSettings: resetSettings, clearKeys: !clearKeys, deleteSaves: deleteSaves)
            } else if deleteSavesLineRange.contains(lineIndex) {
                self.confirmResetToDefaults(resetSettings: resetSettings, clearKeys: clearKeys, deleteSaves: !deleteSaves)
            }
        }
        closeHandler = { [weak self] in self?.showSettings() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let text = menuOpts[choice - 1].text
            switch text {
            case let s where s.hasPrefix("Reset Settings:"):
                self.confirmResetToDefaults(resetSettings: !resetSettings, clearKeys: clearKeys, deleteSaves: deleteSaves)
            case let s where s.hasPrefix("Clear API Keys:"):
                self.confirmResetToDefaults(resetSettings: resetSettings, clearKeys: !clearKeys, deleteSaves: deleteSaves)
            case let s where s.hasPrefix("Delete Saves:"):
                self.confirmResetToDefaults(resetSettings: resetSettings, clearKeys: clearKeys, deleteSaves: !deleteSaves)
            case "Review Setting Changes":
                self.showResetReview()
            case "Save Settings First":
                self.saveSettingsBackup(name: "Before Reset") {
                    self.confirmResetToDefaults(resetSettings: resetSettings, clearKeys: clearKeys, deleteSaves: deleteSaves)
                }
            case "Load a Backup":
                self.showLoadBackupMenu()
            case "Apply":
                guard anySelected else { return }
                self.showUnifiedResetConfirmation(resetSettings: resetSettings, clearKeys: clearKeys, deleteSaves: deleteSaves)
            case "?":
                self.showInlineHelp {
                    self.printTitle("Reset Help")
                    self.print("")
                    self.print("  THE THREE TOGGLES", color: .cyan, bold: true)
                    self.printWrapped("Tap any of the three checkbox rows to switch it on or off. Mix and match — settings-only, keys-only, all three together (the old 'Factory Reset'), or any other combination.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  REVIEW SETTING CHANGES", color: .cyan, bold: true)
                    self.printWrapped("Only shown when 'Reset Settings' is on. Shows every setting that differs from its default, and lets you toggle individual ones off if you don't want everything reset.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  SAVE SETTINGS FIRST", color: .cyan, bold: true)
                    self.printWrapped("Backs up your current settings (as 'Before Reset') before doing anything else — a safety net regardless of which toggles are on.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  LOAD A BACKUP", color: .cyan, bold: true)
                    self.printWrapped("Jumps straight to loading a previously saved settings backup instead, if that's what you actually wanted.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  APPLY", color: .cyan, bold: true)
                    self.printWrapped("Shows exactly what will happen for everything you've switched on, then asks you to confirm before doing it.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default:
                self.showSettings()
            }
        }
    }

    /// Confirmation for the unified Reset screen — lists exactly what will
    /// happen for whichever toggles are on (settings diff, save file names,
    /// affected providers) before anything actually changes.
    private func showUnifiedResetConfirmation(resetSettings: Bool, clearKeys: Bool, deleteSaves: Bool) {
        clearTerminal()
        printTitle("Confirm Reset")
        print("")

        let changes = resetSettings ? changedSettings() : []
        let saves = deleteSaves ? SaveGameManager.shared.listAllSaves() : []
        let keyedProviders = clearKeys ? AIProvider.allCases.filter { DMEngine.shared.apiKey(for: $0) != nil } : []

        if resetSettings {
            if changes.isEmpty {
                printWrapped("Settings: already at defaults, nothing to change.", indent: 2, color: .dimGreen)
            } else {
                print("  SETTINGS (\(changes.count)):", color: .cyan, bold: true)
                for item in changes {
                    print("    \(item.name): \(item.currentDisplay) → \(item.defaultDisplay)", color: .dimGreen)
                }
            }
            print("")
        }
        if clearKeys {
            if keyedProviders.isEmpty {
                printWrapped("API Keys: none currently set, nothing to clear.", indent: 2, color: .dimGreen)
            } else {
                print("  API KEYS TO CLEAR:", color: .yellow, bold: true)
                for provider in keyedProviders {
                    print("    \(provider.displayName)", color: .dimGreen)
                }
            }
            print("")
        }
        if deleteSaves {
            if saves.isEmpty {
                printWrapped("Saved Games: none exist, nothing to delete.", indent: 2, color: .dimGreen)
            } else {
                print("  SAVES TO DELETE (\(saves.count)):", color: .yellow, bold: true)
                for save in saves {
                    print("    \(save.slotName)", color: .dimGreen)
                }
            }
            print("")
        }
        if clearKeys || deleteSaves {
            printWrapped("This cannot be undone.", indent: 2, color: .red)
            print("")
        }

        let nothingToDo = changes.isEmpty && keyedProviders.isEmpty && saves.isEmpty
        let menuOpts = [MenuOption(nothingToDo ? "Nothing To Apply" : "Apply", isDisabled: nothingToDo, tint: (clearKeys || deleteSaves) ? .danger : .normal),
                        MenuOption("< Back")]
        showMenuOptions(menuOpts)
        closeHandler = { [weak self] in self?.confirmResetToDefaults(resetSettings: resetSettings, clearKeys: clearKeys, deleteSaves: deleteSaves) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 && !nothingToDo {
                self.performUnifiedReset(resetSettings: resetSettings, clearKeys: clearKeys, deleteSaves: deleteSaves)
            } else {
                self.confirmResetToDefaults(resetSettings: resetSettings, clearKeys: clearKeys, deleteSaves: deleteSaves)
            }
        }
    }

    /// Executes whichever combination of toggles was confirmed, printing
    /// each step as it happens rather than a single flat "done" message.
    private func performUnifiedReset(resetSettings: Bool, clearKeys: Bool, deleteSaves: Bool) {
        clearTerminal()
        printTitle("Resetting…")
        print("")

        if resetSettings {
            print("  Resetting settings...", color: .dimGreen)
            for key in Self.settingsKeys {
                UserDefaults.standard.removeObject(forKey: key)
            }
            voiceMenuEnabled = true
            useArrowNavigation = false
            infoTimeout = 5.0
            autoContinueEnabled = true
            autoContinuePaused = false
            showCountdownControl = true
            autoScrollSpeed = 0
            iconScaleSetting = 0
            useCustomKeyboard = true
            idlePromptsEnabled = true
            blinkingCursorEnabled = false
            fontScale = FontSizeSetting.defaultSetting.scale
            justDMMode = false
            DMEngine.shared.justDMMode = false
            syncSettingsAfterRestore()
            print("  ✓ Settings reset to defaults.", color: .brightGreen)
            print("")
        }

        if clearKeys {
            print("  Clearing API keys...", color: .dimGreen)
            for provider in AIProvider.allCases {
                UserDefaults.standard.removeObject(forKey: provider.userDefaultsKey)
                deleteSingleAPIKeyFromKeychain(for: provider)
            }
            print("  ✓ API keys cleared (app + Keychain).", color: .brightGreen)
            print("")
        }

        if deleteSaves {
            let saves = SaveGameManager.shared.listAllSaves()
            print("  Deleting \(saves.count) save file\(saves.count == 1 ? "" : "s")...", color: .dimGreen)
            for save in saves {
                SaveGameManager.shared.delete(id: save.id)
            }
            print("  ✓ Saved games deleted.", color: .brightGreen)
            print("")
        }

        printWrapped("Done.", indent: 2, color: .brightGreen)
        print("")
        showMenu(["Done"])
        closeHandler = { [weak self] in self?.showSettings() }
        menuHandler = { [weak self] _ in self?.showSettings() }
    }

    /// Confirmation screen showing exactly what will change before any reset action
    private func showResetConfirmation(action: String, changes: [ResetSettingInfo], onConfirm: @escaping () -> Void) {
        if changes.isEmpty {
            clearTerminal()
            printTitle("Nothing to Reset")
            print("")
            printWrapped("All settings are already at their default values.", indent: 2, color: .brightGreen)
            print("")
            showMenu(["Done"])
            closeHandler = { [weak self] in self?.confirmResetToDefaults() }
            menuHandler = { [weak self] _ in self?.confirmResetToDefaults() }
            return
        }

        clearTerminal()
        printTitle("Confirm: \(action)")
        print("")
        printWrapped("The following \(changes.count) setting\(changes.count == 1 ? "" : "s") will be changed:", indent: 2, color: .yellow)
        print("")

        for item in changes {
            print("  \(item.name)", color: .brightGreen, bold: true)
            print("    \(item.currentDisplay) → \(item.defaultDisplay)", color: .dimGreen)
        }
        print("")
        printWrapped("API keys and saved games will NOT be affected.", indent: 2, color: .dimGreen)
        print("")

        let menuOpts = [MenuOption("Reset", tint: .danger),
                        MenuOption("< Back"),
                        MenuOption("?", tint: .navigation, compact: true)]
        showMenuOptions(menuOpts)
        closeHandler = { [weak self] in self?.confirmResetToDefaults() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let text = menuOpts[choice - 1].text
            switch text {
            case "Reset":
                onConfirm()
            case "?":
                self.showInlineHelp {
                    self.printTitle("Reset Confirmation — Help")
                    self.print("")
                    self.print("  WHAT HAPPENS", color: .cyan, bold: true)
                    self.printWrapped("The settings listed above will be changed from their current values to the defaults shown. No other settings are affected.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  RESET", color: .cyan, bold: true)
                    self.printWrapped("Applies the changes shown. API keys and saved games are never affected by a reset.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  CANCEL", color: .cyan, bold: true)
                    self.printWrapped("Returns to the previous screen without changing anything.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default:
                self.confirmResetToDefaults()
            }
        }
    }

    // MARK: - Selective Reset Review

    /// Describes a single setting for the reset review screen
    private struct ResetSettingInfo {
        let key: String
        let name: String
        let currentDisplay: String
        let defaultDisplay: String
    }

    /// Build a list of all settings that differ from their defaults
    private func changedSettings() -> [ResetSettingInfo] {
        var result: [ResetSettingInfo] = []

        func add(_ key: String, _ name: String, current: String, dflt: String) {
            if current != dflt { result.append(ResetSettingInfo(key: key, name: name, currentDisplay: current, defaultDisplay: dflt)) }
        }

        add("music_enabled", "Music", current: musicEnabled ? "On" : "Off", dflt: "On")
        add("battle_sounds_enabled", "Sound FX", current: battleSoundsEnabled ? "On" : "Off", dflt: "On")
        add("hit_animations", "Hit Animations", current: hitAnimationsEnabled ? "On" : "Off", dflt: "On")
        add("speechEnabled", "DM Voice", current: SpeechEngine.shared.isEnabled ? "On" : "Off", dflt: "Off")
        add("voiceMenuEnabled", "Voice Menus", current: voiceMenuEnabled ? "On" : "Off", dflt: "On")
        add("fontSizeSetting", "Display Size", current: fontSizeSetting.displayName, dflt: FontSizeSetting.defaultSetting.displayName)
        add("maxButtonsPerScreen", "Button Limit", current: "\(maxButtonsPerScreen)", dflt: "6")
        add("useArrowNavigation", "Card Navigation", current: useArrowNavigation ? "Buttons" : "Swipe", dflt: "Swipe")
        #if os(macOS)
        add("mac_map_rows", "Map Length", current: "\(macMapRows)", dflt: "3")
        #else
        add("map_radius", "Map Length", current: "\(mapRadius)", dflt: "1")
        #endif
        if Self.combatArenaAvailable { add("combatArena", "Fight Club", current: combatArenaEnabled ? "On" : "Off", dflt: "On") }
        add("npcs_enabled", "NPCs", current: npcsEnabled ? "On" : "Off", dflt: "Off")
        add("multiple_shops_enabled", "Multi-Shop", current: multipleShopsEnabled ? "On" : "Off", dflt: "On")
        add("multiplayer_enabled", "Multiplayer", current: multiplayerEnabled ? "On" : "Off", dflt: "Off")
        add("undoRedoEnabled", "Undo/Redo", current: undoRedoEnabled ? "On" : "Off", dflt: "On")

        let infoStr = infoTimeout == 0 ? "Off" : String(format: "%.1fs", infoTimeout)
        add("infoTimeout", "Info Timeout", current: infoStr, dflt: "5.0s")
        add("autoContinueEnabled", "Auto-Continue", current: autoContinueEnabled ? "On" : "Off", dflt: "On")
        add("showCountdownControl", "Countdown Icon", current: showCountdownControl ? "On" : "Off", dflt: "On")
        add("autoScrollSpeed", "Auto-Scroll", current: autoScrollSpeedName, dflt: "Off")

        let lpStr = String(format: "%.1fs", longPressDuration)
        add("longPressDuration", "Long Press", current: lpStr, dflt: "0.5s")

        let gtStr = gameTimeLimit == 0 ? "Off" : "\(gameTimeLimit) min"
        add("gameTimeLimit", "Time Limit", current: gtStr, dflt: "Off")

        let logStr = adventureLogLimit == 0 ? "All" : "\(adventureLogLimit)"
        add("adventureLogLimit", "Log Limit", current: logStr, dflt: "All")

        #if os(iOS)
        add("useCustomKeyboard", "Keyboard", current: useCustomKeyboard ? "Custom" : "System", dflt: "Custom")
        #endif
        add("idlePromptsEnabled", "Idle Prompts", current: idlePromptsEnabled ? "On" : "Off", dflt: "On")
        add("blinkingCursorEnabled", "Blinking Cursor", current: blinkingCursorEnabled ? "On" : "Off", dflt: "Off")

        add("autosave_interval", "Autosave", current: autosaveInterval.displayName, dflt: AutosaveInterval.everyRoom.displayName)

        // Tunes
        add("menu_melody", "Menu Tune", current: melodyName(type: "menu", choice: menuMelodyChoice), dflt: melodyName(type: "menu", choice: 0))
        add("exploration_melody", "Explore Tune", current: melodyName(type: "exploration", choice: explorationMelodyChoice), dflt: melodyName(type: "exploration", choice: 0))
        add("combat_melody", "Combat Tune", current: melodyName(type: "combat", choice: combatMelodyChoice), dflt: melodyName(type: "combat", choice: 0))
        add("chat_melody", "Chat Tune", current: melodyName(type: "chat", choice: chatMelodyChoice), dflt: melodyName(type: "chat", choice: 0))

        // DM settings (not API key)
        let dmLevel = DMEngine.shared.adLibLevel
        add("dmAdLibLevel", "DM Ad-lib", current: dmLevel.displayName, dflt: DMAdLibLevel.full.displayName)
        let logCtx = dmLogContextSize == Int.max ? "Unlimited" : "\(dmLogContextSize)"
        add("dmLogContextSize", "DM Log Context", current: logCtx, dflt: "0 (Unlimited)")

        return result
    }

    /// Show the selective reset review — each changed setting with a toggle
    private func showResetReview(selected: Set<String>? = nil, page: Int = 0) {
        let changed = changedSettings()

        if changed.isEmpty {
            clearTerminal()
            printTitle("Review Changes")
            print("")
            printWrapped("All settings are already at their default values. Nothing to reset.", indent: 2, color: .brightGreen)
            print("")
            showMenu(["Done"])
            closeHandler = { [weak self] in self?.confirmResetToDefaults() }
            menuHandler = { [weak self] _ in self?.confirmResetToDefaults() }
            return
        }

        // Default: all selected for reset
        let sel = selected ?? Set(changed.map { $0.key })

        clearTerminal()
        printTitle("Review Changes")
        print("")
        printWrapped("Settings that differ from defaults. Tap to toggle. Selected items (✓) will be reset.", indent: 2, color: .dimGreen)
        print("")

        // Exact printed-line range per setting (so tapping its two-line
        // block in the text window toggles it too, not just its numbered
        // button below — same convention used for selectable lists
        // elsewhere, e.g. Manage Saves).
        var itemLineRanges: [Range<Int>] = []
        for item in changed {
            let lineStart = terminalLines.count
            let isSelected = sel.contains(item.key)
            let check = isSelected ? "✓" : "✗"
            let checkColor: TerminalColor = isSelected ? .brightGreen : .red
            print("  \(check) \(item.name)", color: checkColor, bold: isSelected)
            print("    now: \(item.currentDisplay)  default: \(item.defaultDisplay)", color: .dimGreen)
            itemLineRanges.append(lineStart..<terminalLines.count)
        }
        print("")

        // Build menu: one button per setting to toggle, then Apply + Select All/None + help
        let settingNames = changed.map { item -> String in
            let check = sel.contains(item.key) ? "✓" : "✗"
            return "\(check) \(item.name)"
        }

        var allOptions = settingNames
        let selectedCount = sel.count
        allOptions.append(selectedCount == changed.count ? "Deselect All" : "Select All")
        allOptions.append("Apply Reset")

        let toggleSetting: (Int) -> Void = { [weak self] idx in
            guard let self = self, idx >= 0, idx < changed.count else { return }
            var newSel = sel
            let key = changed[idx].key
            if newSel.contains(key) { newSel.remove(key) } else { newSel.insert(key) }
            self.showResetReview(selected: newSel, page: self.paginatedPage)
        }

        showPaginatedMenuOptions(allOptions, page: page, pinned: ["?", "< Back"], handler: { [weak self] idx in
            guard let self = self else { return }
            guard idx >= 0 && idx < allOptions.count else { return }
            let currentPage = self.paginatedPage

            if idx < changed.count {
                toggleSetting(idx)
            } else if allOptions[idx] == "Select All" || allOptions[idx] == "Deselect All" {
                let newSel: Set<String> = selectedCount == changed.count ? [] : Set(changed.map { $0.key })
                self.showResetReview(selected: newSel, page: currentPage)
            } else if allOptions[idx] == "Apply Reset" {
                let selectedChanges = changed.filter { sel.contains($0.key) }
                self.showResetConfirmation(action: "Reset \(selectedChanges.count) Setting\(selectedChanges.count == 1 ? "" : "s")", changes: selectedChanges) {
                    self.applySelectiveReset(keys: sel)
                }
            }
        }, pinnedHandler: { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 0:
                self.showInlineHelp {
                    self.printTitle("Review Changes Help")
                    self.print("")
                    self.print("  TOGGLE SETTINGS", color: .cyan, bold: true)
                    self.printWrapped("Tap any setting — its text above, or the numbered button below — to toggle it on (✓) or off (✗). Only settings marked ✓ will be reset to their default values.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  SELECT ALL / DESELECT ALL", color: .cyan, bold: true)
                    self.printWrapped("Quickly select or deselect every setting.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  APPLY RESET", color: .cyan, bold: true)
                    self.printWrapped("Resets the selected settings to their defaults. Unselected settings keep their current values. API keys and saved games are never affected.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default:
                self.confirmResetToDefaults()
            }
        })

        // Tap a setting's own printed text (not just its numbered button)
        // to toggle it too — see itemLineRanges above.
        textLongPressHandler = { lineIndex in
            guard let idx = itemLineRanges.firstIndex(where: { $0.contains(lineIndex) }) else { return }
            toggleSetting(idx)
        }
        closeHandler = { [weak self] in self?.confirmResetToDefaults() }
    }

    /// Reset only the specified setting keys
    private func applySelectiveReset(keys: Set<String>) {
        guard !keys.isEmpty else {
            showSettings()
            return
        }

        let preserveKeys: Set<String> = ["dmApiKey"]
        for key in keys where !preserveKeys.contains(key) {
            UserDefaults.standard.removeObject(forKey: key)
        }

        // Re-sync cached properties
        if keys.contains("voiceMenuEnabled") { voiceMenuEnabled = true }
        if keys.contains("useArrowNavigation") { useArrowNavigation = false }
        if keys.contains("infoTimeout") { infoTimeout = 5.0 }
        if keys.contains("autoContinueEnabled") { autoContinueEnabled = true }
        if keys.contains("showCountdownControl") { showCountdownControl = true }
        if keys.contains("autoScrollSpeed") { autoScrollSpeed = 0 }
        if keys.contains("iconScaleSetting") { iconScaleSetting = 0 }
        if keys.contains("useCustomKeyboard") { useCustomKeyboard = true }
        if keys.contains("idlePromptsEnabled") { idlePromptsEnabled = true }
        if keys.contains("blinkingCursorEnabled") { blinkingCursorEnabled = false }
        if keys.contains("fontSizeSetting") { fontScale = FontSizeSetting.defaultSetting.scale }
        if keys.contains("undoRedoEnabled") && !undoRedoEnabled { clearAllUndoRedo() }

        syncSettingsAfterRestore()

        clearTerminal()
        printTitle("Settings Reset")
        print("")
        printWrapped("\(keys.count) setting\(keys.count == 1 ? "" : "s") restored to defaults.", indent: 2, color: .brightGreen)
        print("")
        printWrapped("API keys and saved games are unchanged.", indent: 2, color: .dimGreen)
        print("")

        showMenu(["Done"])
        closeHandler = { [weak self] in self?.showSettings() }
        menuHandler = { [weak self] _ in self?.showSettings() }
    }

    private func saveSettingsBackup(name: String, then completion: @escaping () -> Void) {
        let url = settingsBackupURL(name: name)
        let dict = exportSettings()
        if let data = try? PropertyListSerialization.data(fromPropertyList: dict, format: .xml, options: 0) {
            try? data.write(to: url)
            print("  Settings saved as '\(name)'.", color: .brightGreen)
        } else {
            print("  Could not save settings.", color: .red)
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) { completion() }
    }


    func showMusicSettings() {
        clearTerminal()
        printTitle("Mood")

        print("MUSIC:", color: .cyan, bold: true)
        print("  \(musicEnabled ? "On" : "Off")", color: musicEnabled ? .brightGreen : .red)
        print("")

        if musicEnabled {
            print("MENU TUNE:", color: .cyan, bold: true)
            print("  \(melodyName(type: "menu", choice: menuMelodyChoice))", color: .brightGreen)
            print("")

            print("EXPLORATION TUNE:", color: .cyan, bold: true)
            print("  \(melodyName(type: "exploration", choice: explorationMelodyChoice))", color: .brightGreen)
            print("")

            print("COMBAT TUNE:", color: .cyan, bold: true)
            print("  \(melodyName(type: "combat", choice: combatMelodyChoice))", color: .brightGreen)
            print("")

            print("CHAT TUNE:", color: .cyan, bold: true)
            print("  \(melodyName(type: "chat", choice: chatMelodyChoice))", color: .brightGreen)
            print("")
        }

        print("BATTLE SOUNDS:", color: .cyan, bold: true)
        print("  \(battleSoundsEnabled ? "On" : "Off")", color: battleSoundsEnabled ? .brightGreen : .red)
        print("")

        var options: [String] = ["Switches"]
        if musicEnabled {
            options.append(contentsOf: ["Menu Tune", "Explore Tune", "Combat Tune", "Chat Tune"])
        }
        var menuOpts = options.map { MenuOption($0) }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)

        let backToSettings: () -> Void = { [weak self] in
            guard let self = self else { return }
            SoundManager.shared.stopMusic()
            self.playCurrentMusic()
            self.showSettings()
        }
        closeHandler = backToSettings
        installSettingUndoRedo(screen: "s:mood") { [weak self] in self?.showMusicSettings() }

        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let text = menuOpts[choice - 1].text
            if text == "?" {
                self.showMusicSettingsHelp()
                return
            }
            if text == "< Back" {
                backToSettings()
                return
            }
            switch text {
            case "Switches":
                self.showMoodSwitches()
            case "Menu Tune":
                self.recordSettingChange(screen: "s:mood", key: "menu_melody", name: "Menu Tune")
                self.menuMelodyChoice = (self.menuMelodyChoice + 1) % 4
                SoundManager.shared.stopMusic()
                SoundManager.shared.startMusic(.menu, preference: self.menuMelodyChoice)
                self.showMusicSettings()
            case "Explore Tune":
                self.recordSettingChange(screen: "s:mood", key: "exploration_melody", name: "Explore")
                self.explorationMelodyChoice = (self.explorationMelodyChoice + 1) % 5
                SoundManager.shared.stopMusic()
                SoundManager.shared.startMusic(.exploration, preference: self.explorationMelodyChoice)
                self.showMusicSettings()
            case "Combat Tune":
                self.recordSettingChange(screen: "s:mood", key: "combat_melody", name: "Combat")
                self.combatMelodyChoice = (self.combatMelodyChoice + 1) % 5
                SoundManager.shared.stopMusic()
                SoundManager.shared.startMusic(.combat, preference: self.combatMelodyChoice)
                self.showMusicSettings()
            case "Chat Tune":
                self.recordSettingChange(screen: "s:mood", key: "chat_melody", name: "Chat")
                self.chatMelodyChoice = (self.chatMelodyChoice + 1) % 4
                SoundManager.shared.stopMusic()
                SoundManager.shared.startMusic(.chat, preference: self.chatMelodyChoice)
                self.showMusicSettings()
            default: break
            }
        }
    }

    private func showMoodSwitches() {
        clearTerminal()
        printTitle("Mood — Switches")
        print("")

        print("  MUSIC:", color: .cyan, bold: true)
        print("  \(musicEnabled ? "On" : "Off")", color: musicEnabled ? .brightGreen : .red)
        print("")
        print("  BATTLE SOUNDS:", color: .cyan, bold: true)
        print("  \(battleSoundsEnabled ? "On" : "Off")", color: battleSoundsEnabled ? .brightGreen : .red)
        print("")

        let options = [musicEnabled ? "Music Off" : "Music On",
                       battleSoundsEnabled ? "Sounds Off" : "Sounds On",
                       "?", "< Back"]
        showMenu(options)
        closeHandler = { [weak self] in self?.showMusicSettings() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.recordSettingChange(screen: "s:mood:switches", key: "music_enabled", name: "Music")
                self.musicEnabled.toggle()
                if self.musicEnabled { self.playCurrentMusic() }
                self.showMoodSwitches()
            case 2:
                self.recordSettingChange(screen: "s:mood:switches", key: "battle_sounds_enabled", name: "Sounds")
                self.battleSoundsEnabled.toggle()
                self.showMoodSwitches()
            case 3:
                self.showInlineHelp {
                    self.printTitle("Mood Switches — Help")
                    self.print("")
                    self.printWrapped("Music: turns background music on or off entirely.", indent: 2, color: .dimGreen)
                    self.printWrapped("Battle Sounds: turns combat sound effects on or off.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default:
                self.showMusicSettings()
            }
        }
        installSettingUndoRedo(screen: "s:mood:switches") { [weak self] in self?.showMoodSwitches() }
    }

