    /// Start music appropriate for current game state, respecting preferences
    private func playCurrentMusic() {
        guard musicEnabled else { return }
        switch gameState {
        case .mainMenu, .partySetup, .characterCreation, .gameOver, .victory:
            SoundManager.shared.startMusic(.menu, preference: menuMelodyChoice)
        case .exploring:
            SoundManager.shared.startMusic(.exploration, preference: explorationMelodyChoice)
        case .combat:
            SoundManager.shared.startMusic(.combat, preference: combatMelodyChoice)
        }
    }

    func showAIProviderMenu(onBack: (() -> Void)? = nil) {
        let back = onBack ?? { [weak self] in self?.showDMSettingsSubMenu() }
        clearTerminal()
        printTitle("Brain")

        let dm = DMEngine.shared

        // Show current DM status
        print("CURRENT DM:", color: .cyan, bold: true)
        if dm.isConfigured {
            print("  \(dm.provider.displayName) [key set]", color: .brightGreen)
        } else if dm.isAppleModelAvailable {
            print("  Apple On-Device AI", color: .brightGreen)
            print("  Running locally on this device.", color: .dimGreen)
            print("  Works offline, no account needed.", color: .dimGreen)
            print("  Upgrade to a cloud provider below", color: .dimGreen)
            print("  for a more creative DM.", color: .dimGreen)
        } else {
            print("  Basic DM (no AI)", color: .red)
            print("  This device doesn't support Apple", color: .yellow)
            print("  on-device AI (requires iOS 26+", color: .yellow)
            print("  on iPhone 16 or newer).", color: .yellow)
            print("")
            print("  Without AI, you get a simple DM", color: .yellow)
            print("  with canned responses.", color: .yellow)
            print("")
            print("  OPTIONS:", color: .cyan, bold: true)
            print("  - Set up a cloud AI below", color: .dimGreen)
            print("    (Gemini is FREE for ages 18+)", color: .brightGreen)
            print("  - Use a newer iPhone/iPad", color: .dimGreen)
            print("  - Try the web version (coming soon)", color: .dimGreen)
        }
        print("")

        print("CLOUD PROVIDERS:", color: .cyan, bold: true)
        print("  These give the best DM experience.", color: .dimGreen)
        print("  Each requires its own API key.", color: .dimGreen)
        print("")
        let allProvidersHaveKeys = AIProvider.allCases.allSatisfy { dm.apiKey(for: $0) != nil }
        if !allProvidersHaveKeys {
            print("  Orange buttons below aren't set up", color: .orange)
            print("  yet — no key saved, so they won't", color: .orange)
            print("  work until you tap in and add one.", color: .orange)
            print("")
        }

        let current = dm.provider
        for provider in AIProvider.allCases {
            let isCurrent = provider == current && dm.isConfigured
            let marker = isCurrent ? " <--" : ""
            let hasKey = dm.apiKey(for: provider) != nil
            let keyStatus = hasKey ? " [key set]" : " [not set up]"
            let freeTag = provider == .google && !hasKey ? " (FREE!)" : ""
            let rowColor: TerminalColor = isCurrent ? .brightGreen : (hasKey ? .dimGreen : .orange)
            print("  \(provider.displayName)\(keyStatus)\(freeTag)\(marker)",
                  color: rowColor, bold: isCurrent)
            print("     \(provider.keyURL)", color: .dimGreen)
            print("")
        }

        // Build menu with <-- marker on current provider. Tint amber (this
        // app's closest button colour to orange) for anything not actually
        // usable yet — no key saved for a cloud provider, or Apple's model
        // unavailable on this hardware — so readiness is visible on the
        // button itself, not just in the text above.
        var options: [MenuOption] = []
        let isAppleSelected = !dm.isConfigured && dm.isAppleModelAvailable
        if dm.isAppleModelAvailable {
            let label = isAppleSelected ? "Apple On-Device AI <--" : "Apple On-Device AI"
            options.append(MenuOption(label, isDefault: isAppleSelected))
        }
        for provider in AIProvider.allCases {
            let isSelected = provider == current && dm.isConfigured
            let hasKey = dm.apiKey(for: provider) != nil
            let label = isSelected ? "\(provider.displayName) <--" : provider.displayName
            options.append(MenuOption(label, isDefault: isSelected, tint: hasKey ? .normal : .amber))
        }
        options.append(MenuOption("?", tint: .navigation, compact: true))
        options.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(options)

        let appleOffset = dm.isAppleModelAvailable ? 1 : 0
        let helpIndex = options.count - 1  // 1-based choice for ?
        let backIndex = options.count      // 1-based choice for < Back

        closeHandler = back
        menuHandler = { [weak self] choice in
            if choice == backIndex {
                back()
                return
            }
            if choice == helpIndex {
                self?.showInlineHelp {
                    self?.printTitle("Brain Help")
                    self?.print("")
                    self?.print("  APPLE ON-DEVICE AI", color: .cyan, bold: true)
                    self?.printWrapped("Runs locally on your device. Free, works offline, no account needed. Requires iOS 26+ on iPhone 16 or newer. May refuse some queries.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.print("  GOOGLE GEMINI", color: .cyan, bold: true)
                    self?.printWrapped("Free tier available (ages 18+). Good creative narration. Requires a Google account and API key from AI Studio.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.print("  ANTHROPIC CLAUDE", color: .cyan, bold: true)
                    self?.printWrapped("Excellent narrative quality. Pay-as-you-go — a typical session costs a few pence. Requires an Anthropic account with credit.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.print("  OPENAI CHATGPT", color: .cyan, bold: true)
                    self?.printWrapped("Strong narrative quality. Pay-as-you-go pricing. Requires an OpenAI account with credit.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.printWrapped("After selecting a cloud provider, you'll be prompted to enter your API key. Keys are stored locally on your device.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.print("  TAP A PROVIDER", color: .cyan, bold: true)
                    self?.printWrapped("Tapping any provider (including Apple On-Device AI) opens its own info screen — status, a Test button, and (for cloud providers) buttons to enter, edit, or remove its key.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.print("  BUTTON COLOUR", color: .cyan, bold: true)
                    self?.printWrapped("An orange provider button means it isn't ready to use yet — usually no key saved. Green means a key is saved (this doesn't guarantee it'll pass a test — use Test Key on that provider's screen to check).", indent: 2, color: .dimGreen)
                    self?.print("")
                }
                return
            }
            if dm.isAppleModelAvailable && choice == 1 {
                self?.showAppleAIInfo()
            } else if choice - appleOffset >= 1 && choice - appleOffset <= AIProvider.allCases.count {
                let selected = AIProvider.allCases[choice - appleOffset - 1]
                dm.provider = selected
                dm.clearHistory()
                self?.dmChatLog = []
                self?.promptAPIKey()
            }
        }
    }

    /// The Apple on-device model's own info/test screen — mirrors what
    /// promptAPIKey gives the cloud providers (status + a Test button), even
    /// though there's no key to manage here.
    private func showAppleAIInfo() {
        clearTerminal()
        printTitle("Apple On-Device AI")
        print("")
        let dm = DMEngine.shared
        if dm.isAppleModelAvailable {
            print("  Available on this device.", color: .brightGreen)
        } else {
            print("  Not available on this device.", color: .yellow)
            print("  Requires iOS 26+ on iPhone 16", color: .dimGreen)
            print("  or newer, with Apple Intelligence", color: .dimGreen)
            print("  turned on.", color: .dimGreen)
        }
        print("")
        print("  Runs locally, no account needed.", color: .dimGreen)
        print("  Works offline. May refuse some", color: .dimGreen)
        print("  queries — try rephrasing if it", color: .dimGreen)
        print("  won't answer.", color: .dimGreen)
        print("")

        var options = [MenuOption("Test", isDisabled: !dm.isAppleModelAvailable)]
        if !dm.isConfigured {
            options.append(MenuOption("Use Apple AI <--", isDefault: true))
        } else {
            options.append(MenuOption("Use Apple AI"))
        }
        options.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(options)
        closeHandler = { [weak self] in self?.showAIProviderMenu() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: // Test
                self.print("")
                self.print("  Testing Apple On-Device AI...", color: .dimGreen)
                DMEngine.shared.testAppleModel { success, errorMessage in
                    DispatchQueue.main.async {
                        self.print("")
                        if success {
                            self.print("  Test passed!", color: .brightGreen)
                            self.print("  Apple On-Device AI responded.", color: .brightGreen)
                        } else {
                            self.print("  TEST FAILED", color: .red, bold: true)
                            self.print("  \(errorMessage ?? "Unknown error.")", color: .yellow)
                        }
                        self.print("")
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in
                            self?.showAppleAIInfo()
                        }
                    }
                }
            case 2: // Use Apple AI
                DMEngine.shared.apiKey = nil
                DMEngine.shared.clearHistory()
                self.dmChatLog = []
                self.print("")
                self.print("  Switched to Apple On-Device AI.", color: .brightGreen)
                self.print("")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.showAIProviderMenu()
                }
            default: // Back
                self.showAIProviderMenu()
            }
        }
    }

    func showAdLibLevelMenu() {
        clearTerminal()
        printTitle("DM Ad-lib Level")

        let currentLevel = DMEngine.shared.adLibLevel
        for level in DMAdLibLevel.allCases {
            let marker = level == currentLevel ? "  <--" : ""
            print("  \(level.displayName)\(marker)", color: level == currentLevel ? .brightGreen : .dimGreen, bold: level == currentLevel)
            printWrapped(level.description, indent: 4, color: .dimGreen)
            print("")
        }

        var menuOpts = DMAdLibLevel.allCases.map { level in
            MenuOption(level.displayName, isDefault: level == currentLevel)
        }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)

        closeHandler = { [weak self] in self?.showDMSettingsSubMenu() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == menuOpts.count {
                self.showDMSettingsSubMenu()
                return
            }
            if choice == menuOpts.count - 1 {
                self.showInlineHelp {
                    self.printTitle("Ad-lib Level Help")
                    self.print("")
                    self.print("  OFF", color: .cyan, bold: true)
                    self.printWrapped("The DM stays silent. Good for fast play without narration.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  FLAVOUR ONLY", color: .cyan, bold: true)
                    self.printWrapped("Short atmospheric descriptions. The DM sets the scene but doesn't interfere with gameplay.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  MODERATE", color: .cyan, bold: true)
                    self.printWrapped("Hints, story beats, and hidden details. The DM adds narrative depth and may reveal secrets.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  FULL", color: .cyan, bold: true)
                    self.printWrapped("Full creative freedom. The DM can grant items, modify the story, create quests, and surprise you. The richest experience but uses the most AI tokens.", indent: 2, color: .dimGreen)
                    self.print("")
                }
                return
            }
            if choice <= DMAdLibLevel.allCases.count {
                self.recordSettingChange(screen: "s:dm:adlib", key: "dmAdLibLevel", name: "Ad-lib")
                DMEngine.shared.adLibLevel = DMAdLibLevel(rawValue: choice - 1) ?? .flavorOnly
                self.showAdLibLevelMenu()
            }
        }
        installSettingUndoRedo(screen: "s:dm:adlib") { [weak self] in self?.showAdLibLevelMenu() }
    }

    func showVoiceSettings() {
        clearTerminal()
        printTitle("DM Voice")

        let speech = SpeechEngine.shared

        // Check if TTS is available at all
        guard speech.isAvailable else {
            print("  Text-to-speech is not available", color: .red)
            print("  on this device.", color: .red)
            print("")
            print("  Make sure your device has voices", color: .dimGreen)
            print("  installed in Settings > Accessibility", color: .dimGreen)
            print("  > Spoken Content > Voices.", color: .dimGreen)
            print("")
            showMenu(["?", "< Back"])
            closeHandler = { [weak self] in self?.showSettings() }
            menuHandler = { [weak self] choice in
                if choice == 1 {
                    self?.showDMVoiceHelp()
                } else {
                    self?.showSettings()
                }
            }
            return
        }

        // Check DM is active
        if DMEngine.shared.adLibLevel == .off {
            print("  DM Voice reads DM responses aloud.", color: .dimGreen)
            print("")
            print("  The DM is currently Off.", color: .yellow)
            print("  Enable the DM first in", color: .yellow)
            print("  'DM Ad-lib Level' settings.", color: .yellow)
            print("")
            showMenu(["?", "< Back"])
            closeHandler = { [weak self] in self?.showSettings() }
            menuHandler = { [weak self] choice in
                if choice == 1 {
                    self?.showDMVoiceHelp()
                } else {
                    self?.showSettings()
                }
            }
            return
        }

        print("  The DM can read responses aloud", color: .dimGreen)
        print("  using text-to-speech.", color: .dimGreen)
        print("  (No API key needed — built into iOS)", color: .dimGreen)
        print("")
        print("  Talking DM: \(speech.isEnabled ? "On" : "Off")", color: speech.isEnabled ? .brightGreen : .red)

        if speech.isEnabled {
            let voiceName = speech.voiceIdentifier.flatMap { id in
                AVSpeechSynthesisVoice(identifier: id)?.name
            } ?? "Default (British)"
            let speedLabel: String
            if speech.rate < 0.4 { speedLabel = "Slow" }
            else if speech.rate < 0.5 { speedLabel = "Normal" }
            else { speedLabel = "Fast" }
            let pitchLabel: String
            if speech.pitch < 0.85 { pitchLabel = "Deep" }
            else if speech.pitch < 1.05 { pitchLabel = "Normal" }
            else { pitchLabel = "High" }
            print("  Voice: \(voiceName)", color: .dimGreen)
            print("  Speed: \(speedLabel)  Pitch: \(pitchLabel)", color: .dimGreen)
            print("")
            print("ACCESSIBILITY:", color: .cyan, bold: true)
            print("  Help Narration: \(speech.accessibilityHelpEnabled ? "On" : "Off")", color: speech.accessibilityHelpEnabled ? .brightGreen : .red)
            printWrapped(speech.accessibilityHelpEnabled ? "The DM reads help pages, menus, and tips aloud as you navigate." : "Turn on to have the DM read help pages and menus aloud — useful for vision accessibility.", indent: 4, color: .dimGreen)
        }
        print("")

        var options = [String]()
        options.append(speech.isEnabled ? "Turn Off" : "Turn On")
        if speech.isEnabled {
            options.append("Choose DM Voice")
            options.append(speech.accessibilityHelpEnabled ? "Help Narration Off" : "Help Narration On")
        }
        options.append("Preview")
        // Standard 3-bar nav pair — this screen was missing them entirely.
        options.append("?")
        let helpIndex = options.count
        options.append("< Back")
        let backIndex = options.count

        closeHandler = { [weak self] in self?.showSettings() }
        showMenu(options)

        menuHandler = { [weak self] choice in
            if choice == helpIndex {
                self?.showDMVoiceHelp()
                return
            }
            if choice == backIndex {
                self?.showSettings()
                return
            }
            let selected = options[choice - 1]
            if selected.hasPrefix("Turn O") {
                speech.isEnabled = !speech.isEnabled
                if speech.isEnabled { speech.preview() } else { speech.stop() }
                self?.showVoiceSettings()
            } else if selected == "Choose DM Voice" {
                self?.showVoiceChoiceMenu()
            } else if selected.hasPrefix("Help Narration") {
                speech.accessibilityHelpEnabled.toggle()
                self?.showVoiceSettings()
            } else if selected == "Preview" {
                self?.showVoicePreview()
            }
        }
    }

    private func showDMVoiceHelp() {
        showInlineHelp { [weak self] in
            self?.printTitle("DM Voice Help")
            self?.print("")
            self?.print("  WHAT IT DOES", color: .cyan, bold: true)
            self?.printWrapped("Reads the DM's responses aloud using iOS text-to-speech. No API key or account needed — it's built into iOS.", indent: 2, color: .dimGreen)
            self?.print("")
            self?.print("  TURN ON / OFF", color: .cyan, bold: true)
            self?.printWrapped("Toggles narration. The DM must be enabled first (see 'DM Ad-lib Level' in Settings) — voice has nothing to read if the DM is Off.", indent: 2, color: .dimGreen)
            self?.print("")
            self?.print("  CHOOSE DM VOICE", color: .cyan, bold: true)
            self?.printWrapped("Pick which installed system voice reads the DM's lines, and adjust its speed and pitch.", indent: 2, color: .dimGreen)
            self?.print("")
            self?.print("  HELP NARRATION", color: .cyan, bold: true)
            self?.printWrapped("When on, the DM also reads help pages and menus aloud as you navigate — useful for vision accessibility.", indent: 2, color: .dimGreen)
            self?.print("")
            self?.print("  PREVIEW", color: .cyan, bold: true)
            self?.printWrapped("Plays a short sample line in the current voice, speed, and pitch so you can check it before playing.", indent: 2, color: .dimGreen)
