        }
    }

    private func showAdventurerVoiceSettings() {
        clearTerminal()
        printTitle("Companion Voices")

        let speech = SpeechEngine.shared
        let allVoices = speech.availableVoices()
        let currentPool = speech.adventurerVoicePool

        printWrapped("Your party members speak with their own voices. Voices are automatically matched to each companion's race, class, and name — a dwarf fighter sounds different from an elf wizard.", indent: 2, color: .dimGreen)
        print("")

        // Show current party members and their assigned voices
        if !party.isEmpty {
            print("  YOUR PARTY:", color: .cyan, bold: true)
            for char in party {
                let voiceName = speech.voiceNameForCharacter(name: char.name, race: char.race.rawValue, characterClass: char.characterClass.rawValue) ?? "Default"
                let hasOverride = speech.voiceOverride(forCharacter: char.name) != nil
                print("    \(char.name)", color: .brightGreen, bold: true)
                print("      \(char.race.rawValue) \(char.characterClass.rawValue)", color: .dimGreen)
                print("      Voice: \(voiceName)\(hasOverride ? " (manual)" : "")", color: .cyan)
                print("")
            }
        } else {
            print("  No party yet — start a game to", color: .yellow)
            print("  see your companions here.", color: .yellow)
            print("")
        }

        print("  VOICE POOL (\(currentPool.count)/\(allVoices.count) enabled):", color: .cyan, bold: true)
        printWrapped("Toggle voices on/off. More voices gives the DM a wider range to match characters. Tap a voice to toggle and hear it.", indent: 2, color: .dimGreen)
        print("")

        var menuOpts: [String] = []
        if !party.isEmpty { menuOpts.append("Preview Party") }

        // Add per-character voice change buttons
        var charButtonNames: [String] = []
        for char in party {
            let shortN = String(char.name.prefix(14))
            let label = "♪ \(shortN)"
            menuOpts.append(label)
            charButtonNames.append(label)
        }

        for voice in allVoices {
            let isOn = currentPool.contains(voice.identifier)
            let icon = isOn ? "+" : "-"
            let shortName = String(voice.name.prefix(14))
            menuOpts.append("\(icon) \(shortName)")
        }

        // Toggle: show All Off when all are on, All On otherwise
        let allOn = currentPool.count >= allVoices.count
        menuOpts.append(allOn ? "All Off" : "All On")

        menuOpts.append("?")
        menuOpts.append("< Back")

        closeHandler = { [weak self] in self?.showAccessibilityMenu() }
        showMenu(menuOpts)

        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let selected = menuOpts[choice - 1]
            if selected == "Preview Party" {
                self.previewPartyVoices()
            } else if selected == "?" {
                self.showCompanionVoiceHelp()
            } else if selected == "< Back" {
                self.showAccessibilityMenu()
            } else if selected == "All On" {
                speech.adventurerVoicePool = speech.defaultAdventurerPool()
                self.showAdventurerVoiceSettings()
            } else if selected == "All Off" {
                // Keep just one random voice — pool must have at least one
                if let random = allVoices.randomElement() {
                    speech.adventurerVoicePool = [random.identifier]
                }
                self.showAdventurerVoiceSettings()
            } else if let charIdx = charButtonNames.firstIndex(of: selected) {
                // Per-character voice change
                self.showCompanionVoiceChoice(charIndex: charIdx)
            } else {
                // Voice toggle
                let fixedCount = (self.party.isEmpty ? 0 : 1) + charButtonNames.count
                let voiceIdx = choice - fixedCount - 1
                if voiceIdx >= 0 && voiceIdx < allVoices.count {
                    let voice = allVoices[voiceIdx]
                    var pool = speech.adventurerVoicePool
                    if let idx = pool.firstIndex(of: voice.identifier) {
                        if pool.count > 1 { pool.remove(at: idx) }
                    } else {
                        pool.append(voice.identifier)
                    }
                    speech.adventurerVoicePool = pool
                    speech.previewVoice(voice.identifier)
                }
                self.showAdventurerVoiceSettings()
            }
        }
        // Long-press a voice → preview it with longer sample
        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            let fixedCount = (self.party.isEmpty ? 0 : 1) + charButtonNames.count
            let voiceIdx = choice - fixedCount - 1
            if voiceIdx >= 0 && voiceIdx < allVoices.count {
                speech.previewVoice(allVoices[voiceIdx].identifier)
            }
        }
    }

    /// Pick a specific voice for a party companion
    private func showCompanionVoiceChoice(charIndex: Int) {
        guard charIndex < party.count else { showAdventurerVoiceSettings(); return }
        let char = party[charIndex]
        let speech = SpeechEngine.shared
        let allVoices = speech.availableVoices()

        clearTerminal()
        printTitle("Voice: \(char.name)")
        print("")
        let current = speech.voiceNameForCharacter(name: char.name, race: char.race.rawValue, characterClass: char.characterClass.rawValue) ?? "Auto"
        let hasOverride = speech.voiceOverride(forCharacter: char.name) != nil
        print("  Current: \(current)\(hasOverride ? " (manual)" : " (auto)")", color: .cyan)
        print("")

        var menuOpts = ["Reset to Auto"]
        for voice in allVoices {
            let isCurrent = voice.name == current
            let prefix = isCurrent ? "● " : "  "
            menuOpts.append("\(prefix)\(String(voice.name.prefix(16)))")
        }

        closeHandler = { [weak self] in self?.showAdventurerVoiceSettings() }

        showPaginatedMenu(menuOpts, pinned: []) { [weak self] idx in
            guard let self = self else { return }
            if idx == 0 {
                // Reset to auto
                speech.setVoiceOverride(forCharacter: char.name, voiceId: nil)
                self.showAdventurerVoiceSettings()
            } else {
                let voiceIdx = idx - 1
                if voiceIdx >= 0 && voiceIdx < allVoices.count {
                    let voice = allVoices[voiceIdx]
                    speech.setVoiceOverride(forCharacter: char.name, voiceId: voice.identifier)
                    speech.previewVoice(voice.identifier)
                    self.showCompanionVoiceChoice(charIndex: charIndex)
                }
            }
        }
    }

    private func showCompanionVoiceHelp() {
        showInlineHelp {
            self.printTitle("Companion Voices — Help")
            self.print("")
            self.printWrapped("HOW IT WORKS", indent: 2, color: .cyan, bold: true)
            self.printWrapped("Each party member is assigned a unique voice based on their race, class, and name. The DM picks voices that fit each character — deep voices for dwarves and orcs, lighter voices for elves and halflings.", indent: 2, color: .dimGreen)
            self.print("")
            self.printWrapped("BUTTON SYMBOLS", indent: 2, color: .cyan, bold: true)
            self.printWrapped("♪ — tap to choose a specific voice for that character.", indent: 2, color: .dimGreen)
            self.printWrapped("+ — voice is enabled in the pool (available for matching).", indent: 2, color: .dimGreen)
            self.printWrapped("- — voice is disabled (won't be used for matching).", indent: 2, color: .dimGreen)
            self.printWrapped("All On — enables every voice in the pool (toggles to All Off when all are already on).", indent: 2, color: .dimGreen)
            self.print("")
            self.printWrapped("VOICE POOL", indent: 2, color: .cyan, bold: true)
            self.printWrapped("Tap a voice to toggle it on (+) or off (-) and hear a preview. The more voices available, the better the DM can match characters. Include both male and female voices for variety.", indent: 2, color: .dimGreen)
            self.print("")
            self.printWrapped("MANUAL OVERRIDE", indent: 2, color: .cyan, bold: true)
            self.printWrapped("Tap a character's ♪ button to pick a specific voice for them, or go to Party Status > Change Voice. Use 'Reset to Auto' to let the DM choose again.", indent: 2, color: .dimGreen)
            self.print("")
            self.printWrapped("PREVIEW", indent: 2, color: .cyan, bold: true)
            self.printWrapped("'Preview Party' speaks a line for each party member in their assigned voice so you can hear how they sound.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    private func previewPartyVoices() {
        let speech = SpeechEngine.shared
        clearTerminal()
        printTitle("Party Voice Preview")
        print("")

        let greetings = [
            "Ready for battle!",
            "I've got your back.",
            "Stay alert, something stirs ahead.",
            "Lead on, adventurer!",
        ]

        for (i, char) in party.enumerated() {
            let voiceName = speech.voiceNameForCharacter(name: char.name, race: char.race.rawValue, characterClass: char.characterClass.rawValue) ?? "Default"
            print("  \(char.name) (\(voiceName)):", color: .brightGreen)
            let greeting = greetings[i % greetings.count]
            print("  \"\(greeting)\"", color: .dimGreen)
            print("")
        }

        print("  Speaking...", color: .cyan)
        print("")

        // Speak each character's greeting sequentially
        var charIdx = 0
        func speakNext() {
            guard charIdx < self.party.count else {
                speech.onFinish = nil
                return
            }
            let char = self.party[charIdx]
            let greeting = greetings[charIdx % greetings.count]
            charIdx += 1
            speech.onFinish = { speakNext() }
            speech.speakAsCharacter(greeting, characterName: char.name, race: char.race.rawValue, characterClass: char.characterClass.rawValue)
        }
        speakNext()

        closeHandler = { [weak self] in
            speech.stop()
            self?.showAdventurerVoiceSettings()
        }
    }

    private func showCharacterVoiceEdit(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]
        let speech = SpeechEngine.shared

        clearTerminal()
        printTitle("Voice — \(shortName(for: char))")

        guard speech.isAvailable else {
            print("  Text-to-speech is not available", color: .red)
            print("  on this device.", color: .red)
            print("")
            closeHandler = { [weak self] in self?.returnFromCharacterEditSubscreen(index: index) }
            return
        }

        let voiceName = speech.voiceNameForCharacter(name: char.name, race: char.race.rawValue, characterClass: char.characterClass.rawValue) ?? "Default"
        print("  \(char.race.rawValue) \(char.characterClass.rawValue)", color: .dimGreen)
        print("")
        let hasOverride = speech.voiceOverride(forCharacter: char.name) != nil
        print("  Voice: \(voiceName)\(hasOverride ? " (manual)" : "")", color: speech.isEnabled ? .brightGreen : .dimGreen)
        print("  Companion voices: \(speech.isEnabled ? "On" : "Off")", color: speech.isEnabled ? .brightGreen : .red)
        print("")
        printWrapped("Voice is automatically matched to this character's race, class, and name. Use Change Voice to manually override.", indent: 2, color: .dimGreen)
        print("")

        var options = [String]()
        options.append(speech.isEnabled ? "Turn Off Voices" : "Turn On Voices")
        if speech.isEnabled {
            options.append("Change Voice")
            if hasOverride {
                options.append("Reset to Auto")
            }
            options.append("Preview")
            options.append("Voice Pool")
        }
        options.append("?")
        options.append("< Back")

        showMenu(options)
        let goBack: () -> Void = { [weak self] in self?.returnFromCharacterEditSubscreen(index: index) }
        closeHandler = goBack
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let selected = options[choice - 1]
            if selected.hasPrefix("Turn O") {
                speech.isEnabled = !speech.isEnabled
                self.showCharacterVoiceEdit(index: index)
            } else if selected == "Change Voice" {
                self.showVoicePicker(forCharacter: char, editIndex: index)
            } else if selected == "Reset to Auto" {
                speech.setVoiceOverride(forCharacter: char.name, voiceId: nil)
                self.showCharacterVoiceEdit(index: index)
            } else if selected == "Preview" {
                let greeting = "I am \(char.name). Ready for adventure!"
                speech.speakAsCharacter(greeting, characterName: char.name, race: char.race.rawValue, characterClass: char.characterClass.rawValue)
                self.showCharacterVoiceEdit(index: index)
            } else if selected == "Voice Pool" {
                self.showAdventurerVoiceSettingsFrom(index: index)
            } else if selected == "?" {
                self.showInlineHelp {
                    self.printTitle("Voice — Help")
                    self.print("")
                    self.printWrapped("Turn On/Off Voices: enables or disables companion text-to-speech entirely.", indent: 2, color: .dimGreen)
                    self.printWrapped("Change Voice: manually pick a specific voice instead of the automatic race/class match.", indent: 2, color: .dimGreen)
                    self.printWrapped("Reset to Auto: clears a manual voice pick, back to automatic matching.", indent: 2, color: .dimGreen)
                    self.printWrapped("Preview: hear this character speak a sample line.", indent: 2, color: .dimGreen)
                    self.printWrapped("Voice Pool: manage which voices are available to be auto-assigned.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else {
                goBack()
            }
        }
    }

    private func showVoicePicker(forCharacter char: Character, editIndex: Int) {
        let speech = SpeechEngine.shared
        let pool = speech.adventurerVoicePool
        guard !pool.isEmpty else {
            showCharacterVoiceEdit(index: editIndex)
            return
        }

        clearTerminal()
        printSubtitle("Choose Voice — \(shortName(for: char))")
        print("")

        let currentOverride = speech.voiceOverride(forCharacter: char.name)

        // Collect all eligible voices from the pool
        let allVoiceOptions = speech.availableVoices()
        var allEligible: [(label: String, id: String)] = []
        for vo in allVoiceOptions where pool.contains(vo.identifier) {
            allEligible.append((label: vo.label, id: vo.identifier))
        }

        // Show current voice if set
        if let overrideId = currentOverride,
           let current = allEligible.first(where: { $0.id == overrideId }) {
            print("  Current: \(current.label)", color: .yellow)
        } else {
            print("  Current: Auto (DM assigns)", color: .dimGreen)
        }
        print("")

        // Pick a random sample of 8 voices (always include current override if set)
        var sample: [(label: String, id: String)] = []
        if let overrideId = currentOverride,
           let current = allEligible.first(where: { $0.id == overrideId }) {
            sample.append(current)
        }
        let sampleIds = Set(sample.map { $0.id })
        let remaining = allEligible.filter { !sampleIds.contains($0.id) }
        let needed = min(8 - sample.count, remaining.count)
        sample.append(contentsOf: remaining.shuffled().prefix(needed))

        var options: [String] = []
        var voiceIds: [String] = []
        for vo in sample {
            let marker = (vo.id == currentOverride) ? " ✓" : ""
            options.append("\(vo.label)\(marker)")
            voiceIds.append(vo.id)
        }

        print("  Tap to select & preview. 🎲 for more voices.", color: .dimGreen)
        print("  \(allEligible.count) voices available.", color: .dimGreen)
        print("")

        showMenu(options)
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let idx = choice - 1
            guard idx >= 0 && idx < voiceIds.count else { return }
            let selectedId = voiceIds[idx]
            speech.setVoiceOverride(forCharacter: char.name, voiceId: selectedId)
            speech.previewVoice(selectedId)
            self.showVoicePicker(forCharacter: char, editIndex: editIndex)
        }

        closeHandler = { [weak self] in
            self?.showCharacterVoiceEdit(index: editIndex)
        }

        // Dice icon → shuffle new random voices
        rerollHandler = { [weak self] in
            self?.showVoicePicker(forCharacter: char, editIndex: editIndex)
        }
    }

    /// Companion voice settings with return-to-edit-character support
    private func showAdventurerVoiceSettingsFrom(index: Int) {
        // Reuse the existing companion voices screen but override close to go back to character edit
        showAdventurerVoiceSettings()
        closeHandler = { [weak self] in self?.showCharacterVoiceEdit(index: index) }
    }

    private func showVoicePreview(previousVoice: String? = nil) {
        let speech = SpeechEngine.shared
        clearTerminal()
        printTitle("DM Voice Preview")
        print("")
        print("  Speaking...", color: .cyan)
        print("")
        speech.preview()

        let canRevert = previousVoice != nil && previousVoice != speech.voiceIdentifier
        var opts = ["Sounds Good", "Change Voice", "Change Speed", "Change Pitch"]
        if canRevert {
            opts.append("Revert")
        }
        var menuOpts = opts.map { MenuOption($0) }
        if canRevert {
            menuOpts[menuOpts.count - 1] = MenuOption("Revert", tint: .danger)
        }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)

        closeHandler = { [weak self] in
            speech.stop()
            self?.showVoiceSettings()
        }
        menuHandler = { [weak self] choice in
            if choice == menuOpts.count {
                speech.stop()
                self?.showVoiceSettings()
                return
            }
            if choice == menuOpts.count - 1 {
                self?.showInlineHelp {
                    self?.printTitle("DM Voice Preview — Help")
                    self?.print("")
                    self?.print("  SOUNDS GOOD", color: .cyan, bold: true)
                    self?.printWrapped("Keeps this voice and returns to DM Voice settings.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.print("  CHANGE VOICE / SPEED / PITCH", color: .cyan, bold: true)
                    self?.printWrapped("Adjust and come straight back here to hear the result.", indent: 2, color: .dimGreen)
                    self?.print("")
                    if canRevert {
                        self?.print("  REVERT", color: .cyan, bold: true)
                        self?.printWrapped("Switches back to the voice you had before this preview.", indent: 2, color: .dimGreen)
                        self?.print("")
                    }
                }
                return
            }
            speech.stop()
            let selected = opts[choice - 1]
            switch selected {
            case "Sounds Good":
                self?.showVoiceSettings()
            case "Change Voice":
                self?.showVoiceChoiceMenu()
            case "Change Speed":
                self?.showVoiceSpeedMenu()
            case "Change Pitch":
                self?.showVoicePitchMenu()
            case "Revert":
                speech.voiceIdentifier = previousVoice!
                self?.print("")
                self?.print("  Voice reverted.", color: .yellow)
                self?.print("")
                self?.waitForContinue()
                self?.inputHandler = { [weak self] _ in
                    self?.showVoiceChoiceMenu()
                }
            default: break
            }
        }
    }

    private func showVoiceChoiceMenu(page: Int = 0) {
        clearTerminal()
        printTitle("Choose Voice")

        let speech = SpeechEngine.shared
        let allVoices = speech.availableVoices()
        let currentId = speech.voiceIdentifier

        if allVoices.isEmpty {
            print("  No English voices available.", color: .red)
            print("")
            print("  Install voices in iOS Settings:", color: .dimGreen)
            print("  Settings > Accessibility >", color: .dimGreen)
            print("  Spoken Content > Voices > English", color: .dimGreen)
            print("")
            showMenu(["Done"])
            menuHandler = { [weak self] _ in self?.showVoiceSettings() }
            return
        }

        // Tip if only standard voices
        if !speech.hasHighQualityVoices {
            print("  Tip: Download better voices in", color: .yellow)
            print("  iOS Settings > Accessibility >", color: .yellow)
            print("  Spoken Content > Voices > English", color: .yellow)
            print("  (tap a voice to download Enhanced", color: .yellow)
            print("  or Premium quality)", color: .yellow)
            print("")
        }

        // Paginate — 6 voices per page
        let perPage = 6
        let totalPages = (allVoices.count + perPage - 1) / perPage
        let startIdx = page * perPage
        let endIdx = min(startIdx + perPage, allVoices.count)
        let pageVoices = Array(allVoices[startIdx..<endIdx])

        if totalPages > 1 {
            print("  Page \(page + 1) of \(totalPages)", color: .dimGreen)
            print("")
        }

        for v in pageVoices {
            let isCurrent = v.identifier == currentId
            let marker = isCurrent ? " <--" : ""
            print("  \(v.label)\(marker)",
                  color: isCurrent ? .brightGreen : .dimGreen, bold: isCurrent)
        }
        print("")

        var options: [String] = []
        if page > 0 {
            options.append("<<")
        }
        options.append(contentsOf: pageVoices.map { $0.name })
        if page < totalPages - 1 {
            options.append(">>")
        }
        options.append("?")
        showMenu(options)

        closeHandler = { [weak self] in self?.showVoiceSettings() }
        menuHandler = { [weak self] choice in
            let selected = options[choice - 1]
            if selected == "<<" {
                self?.showVoiceChoiceMenu(page: page - 1)
            } else if selected == ">>" {
                self?.showVoiceChoiceMenu(page: page + 1)
            } else if selected == "?" {
                self?.showVoiceChoiceHelp(page: page)
            } else {
                // Voice selection — find which pageVoice was picked
                let voiceButtonStart = page > 0 ? 1 : 0  // offset for Back button
                let voiceIdx = choice - 1 - voiceButtonStart
                if voiceIdx >= 0 && voiceIdx < pageVoices.count {
                    let v = pageVoices[voiceIdx]
                    let previousVoice = speech.voiceIdentifier
                    speech.voiceIdentifier = v.identifier
                    self?.showVoicePreview(previousVoice: previousVoice)
                }
            }
        }
    }

