    func showDMLogContextMenu() {
        // Roller steps: 0 (unlimited), 20, 40, 60, ... 2020, 2040, 2048 (unlimited)
        let steps: [Int] = {
            var s = [0]
            var v = 20
            while v < 2048 {
                s.append(v)
                v += 20
            }
            s.append(2048)
            return s
        }()

        // Find current index
        let currentVal = dmLogContextSize == Int.max ? 0 : dmLogContextSize
        let selectedIndex: Int
        if currentVal == 0 || currentVal >= 2048 {
            selectedIndex = 0  // unlimited
        } else {
            selectedIndex = steps.enumerated().min(by: { abs($0.element - currentVal) < abs($1.element - currentVal) })?.offset ?? 0
        }

        showDMLogRoller(steps: steps, selectedIndex: selectedIndex)
    }

    private func stopLogRollerTimer() {
        logRollerTimer?.invalidate()
        logRollerTimer = nil
        logRollerTickCount = 0
    }

    private func startLogRollerRepeat(steps: [Int], selectedIndex: Int, direction: Int) {
        stopLogRollerTimer()
        logRollerTickCount = 0

        // Initial jump of 10 on the long-press itself
        let firstTarget: Int
        if direction < 0 {
            firstTarget = max(0, selectedIndex - 10)
        } else {
            firstTarget = min(steps.count - 1, selectedIndex + 10)
        }
        if firstTarget != selectedIndex {
            showDMLogRoller(steps: steps, selectedIndex: firstTarget)
        }

        // Start repeating timer that accelerates
        scheduleLogRollerTick(steps: steps, currentIndex: firstTarget, direction: direction)
    }

    private func scheduleLogRollerTick(steps: [Int], currentIndex: Int, direction: Int) {
        logRollerTickCount += 1

        // Accelerate: interval decreases, step size increases
        let interval: TimeInterval
        let stepSize: Int
        switch logRollerTickCount {
        case 1...3:    interval = 0.25; stepSize = 1
        case 4...8:    interval = 0.15; stepSize = 2
        case 9...15:   interval = 0.10; stepSize = 5
        default:       interval = 0.06; stepSize = 10
        }

        logRollerTimer = Timer.scheduledTimer(withTimeInterval: interval, repeats: false) { [weak self] _ in
            guard let self = self else { return }
            let nextIndex: Int
            if direction < 0 {
                nextIndex = max(0, currentIndex - stepSize)
            } else {
                nextIndex = min(steps.count - 1, currentIndex + stepSize)
            }
            if nextIndex == currentIndex {
                // Hit boundary — stop
                self.stopLogRollerTimer()
                return
            }
            DispatchQueue.main.async {
                self.showDMLogRoller(steps: steps, selectedIndex: nextIndex)
                self.scheduleLogRollerTick(steps: steps, currentIndex: nextIndex, direction: direction)
            }
        }
    }

    private func showDMLogRoller(steps: [Int], selectedIndex: Int) {
        clearTerminal()
        printTitle("DM Log Context")
        print("  How many adventure log entries are", color: .dimGreen)
        print("  sent to the AI DM for context.", color: .dimGreen)
        print("  More = better narrative continuity", color: .dimGreen)
        print("  but uses more AI tokens.", color: .dimGreen)
        print("  Hold ▲/▼ to scroll continuously.", color: .dimGreen)
        print("")

        // Show scroll wheel: 2 above, current, 2 below
        for offset in -2...2 {
            let idx = selectedIndex + offset
            if idx < 0 || idx >= steps.count {
                print("")
                continue
            }
            let val = steps[idx]
            let label = (val == 0 || val >= 2048) ? "Unlimited" : "\(val)"
            if offset == 0 {
                print("    > \(label) <", color: .brightGreen, bold: true)
            } else {
                print("      \(label)", color: .dimGreen)
            }
        }
        print("")

        var options: [MenuOption] = []
        options.append(MenuOption("▲", isDisabled: selectedIndex <= 0))
        options.append(MenuOption("▼", isDisabled: selectedIndex >= steps.count - 1))
        options.append(MenuOption("Set", tint: .navigation))
        options.append(MenuOption("?", tint: .navigation, compact: true))
        options.append(MenuOption("< Back", tint: .navigation, compact: true))

        showMenuOptions(options)
        let backToDMSettings: () -> Void = { [weak self] in
            self?.stopLogRollerTimer()
            self?.showDMSettingsSubMenu()
        }
        closeHandler = backToDMSettings
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            self.stopLogRollerTimer()
            switch choice {
            case 1: // Up
                if selectedIndex > 0 {
                    self.showDMLogRoller(steps: steps, selectedIndex: selectedIndex - 1)
                }
            case 2: // Down
                if selectedIndex < steps.count - 1 {
                    self.showDMLogRoller(steps: steps, selectedIndex: selectedIndex + 1)
                }
            case 3: // Set
                self.recordSettingChange(screen: "s:dm:log", key: "dm_log_context_size", name: "Log Context")
                let val = steps[selectedIndex]
                self.dmLogContextSize = (val == 0 || val >= 2048) ? Int.max : val
                self.showDMSettingsSubMenu()
            case 5: // Back
                backToDMSettings()
            case 4: // Help
                self.showInlineHelp {
                    self.printTitle("Log Context Help")
                    self.print("")
                    self.printWrapped("Controls how many lines of your adventure log the AI DM reads when generating responses.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("More context means the DM remembers more of your story and gives better continuity, but requests are slower and use more tokens (costing more for cloud providers).", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("'Unlimited' sends the entire adventure log. For most sessions, 200-400 lines is a good balance.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("Use ▲/▼ to adjust. Hold ▲/▼ to scroll continuously — it gets faster the longer you hold.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default: break
            }
        }
        // Long-press ▲/▼ — continuous scrolling with acceleration
        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: // Long-press Up — hold to scroll up
                self.startLogRollerRepeat(steps: steps, selectedIndex: selectedIndex, direction: -1)
            case 2: // Long-press Down — hold to scroll down
                self.startLogRollerRepeat(steps: steps, selectedIndex: selectedIndex, direction: 1)
            default: break
            }
        }
        installSettingUndoRedo(screen: "s:dm:log") { [weak self] in self?.showDMLogRoller(steps: steps, selectedIndex: selectedIndex) }
    }

    private var mapPreviewTorchOn: Bool = true

    func showMapRadiusMenu() {
        clearTerminal()
        printTitle("Map Length")
        #if os(macOS)
        printWrapped("How many rooms up and down the map pane shows. This is the same as dragging the handle under the map — change it either way. The width follows the pane: widen the left column to see further sideways. The map always stays centred on you.", indent: 2, color: .dimGreen)
        #else
        print("  How far you can see up/down the minimap.", color: .dimGreen)
        print("  Width isn't part of this — the map already widens on its", color: .dimGreen)
        print("  own to use the available screen width.", color: .dimGreen)
        #endif
        print("  Without a torch, visibility drops to 1.", color: .dimGreen)
        print("  Larger values may cause scrolling.", color: .dimGreen)
        print("")
        let hasTorch = party.contains { char in
            char.inventory.contains { $0.name.lowercased().contains("torch") }
        }
        let effective = effectiveMapRadius()
        print("  Setting: \(mapLengthSetting)  Effective: \(effective)", color: .brightGreen)
        if !hasTorch {
            print("  No torch — visibility reduced!", color: .yellow)
        }
        print("")

        // Show map preview if in a dungeon — matches the actual in-game
        // rendering (bestMapRadius()), so the auto-widened width shows here
        // too rather than a narrower symmetric-radius preview.
        if let dungeon = dungeon {
            let previewLabel = mapPreviewTorchOn ? "TORCH ON" : "TORCH OFF"
            print("  PREVIEW (\(previewLabel)):", color: .cyan, bold: true)
            let (previewRadius, previewVertical, previewCompact) = bestMapRadius()
            let previewMap = dungeon.getMapDisplay(visibilityRadius: previewRadius, torchLit: mapPreviewTorchOn, compact: previewCompact, verticalRadius: previewVertical, legendMaxSymbols: mapLegendMaxSymbols, hasTrapSense: partyHasTrapSense)
            printLines(previewMap, color: mapPreviewTorchOn ? .dimGreen : .red, size: mapFontSize)
            print("")
        }

        #if os(macOS)
        // Mac: step the pane's rows (the drag handle sets the same value).
        var menuOpts: [MenuOption] = [MenuOption("- Shorter"), MenuOption("+ Longer")]
        #else
        let current = mapRadius
        let opts = [("1 Short", 1), ("2 Normal", 2), ("3 Long", 3)]
        var menuOpts: [MenuOption] = opts.map { (label, val) -> MenuOption in
            MenuOption(val == current ? "\(label) <--" : label)
        }
        #endif
        let sizeOptionCount = menuOpts.count
        let torchToggleIndex: Int? = dungeon != nil ? menuOpts.count + 1 : nil
        if dungeon != nil {
            menuOpts.append(MenuOption(mapPreviewTorchOn ? "Torch Off" : "Torch On"))
        }
        // Cycles the fixed number of key slots shown in the map legend —
        // filtered to symbols actually present, but always this many rows
        // regardless (see Dungeon.getMapDisplay), so the box stays the same
        // size no matter what's nearby or whether the torch is lit.
        let legendSteps = [3, 6, 9, Dungeon.mapLegendEntries.count]
        let legendIndex = menuOpts.count + 1
        let legendLabel = mapLegendMaxSymbols >= Dungeon.mapLegendEntries.count ? "Legend: All" : "Legend: \(mapLegendMaxSymbols)"
        menuOpts.append(MenuOption(legendLabel))

        // Standard 3-bar nav pair — this screen was missing them entirely.
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        let helpIndex = menuOpts.count
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        let backIndex = menuOpts.count

        showMenuOptions(menuOpts)

        closeHandler = { [weak self] in self?.showGameplaySettings() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= sizeOptionCount {
                #if os(macOS)
                self.recordSettingChange(screen: "s:gameplay", key: "mac_map_rows", name: "Map")
                self.macSetMapRows(self.macMapRows + (choice == 1 ? -1 : 1))
                #else
                self.recordSettingChange(screen: "s:gameplay", key: "map_radius", name: "Map")
                self.mapRadius = choice
                #endif
                self.showMapRadiusMenu()
            } else if let torchToggleIndex = torchToggleIndex, choice == torchToggleIndex {
                self.mapPreviewTorchOn.toggle()
                self.showMapRadiusMenu()
            } else if choice == legendIndex {
                let currentIdx = legendSteps.firstIndex(where: { $0 >= self.mapLegendMaxSymbols }) ?? 0
                self.mapLegendMaxSymbols = legendSteps[(currentIdx + 1) % legendSteps.count]
                self.recordSettingChange(screen: "s:gameplay", key: "map_legend_max_symbols", name: "Map Legend")
                self.showMapRadiusMenu()
            } else if choice == helpIndex {
                self.showInlineHelp {
                    self.printTitle("Map Length Help")
                    self.print("")
                    self.print("  MAP LENGTH", color: .cyan, bold: true)
                    #if os(macOS)
                    self.printWrapped("How many rooms up and down the map pane shows. Shorter/Longer here, or drag the little handle under the map — both change this same setting (double-click the handle to go back to 3). The map's width follows the left column: drag the handle between the columns to see further sideways. You're always in the middle.", indent: 2, color: .dimGreen)
                    #else
                    self.printWrapped("How far you can see up/down the minimap. Width isn't affected — the map already widens on its own to use the available screen space. Larger values may need scrolling.", indent: 2, color: .dimGreen)
                    #endif
                    self.print("")
                    self.print("  TORCH", color: .cyan, bold: true)
                    self.printWrapped("Without a lit torch, visibility drops to 1 regardless of this setting. The preview above shows both lit and unlit — tap 'Torch On/Off' to compare.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  LEGEND", color: .cyan, bold: true)
                    self.printWrapped("How many symbol/meaning rows the map's key shows at once — cycles through a few fixed sizes up to 'All'. Only symbols actually nearby are shown, but the box stays this many rows regardless. Full symbol key:", indent: 2, color: .dimGreen)
                    self.printFullMapLegend()
                    self.print("")
                }
            } else if choice == backIndex {
                self.showGameplaySettings()
            }
        }
    }

