    /// Trims ordinary whitespace, then strips invisible Unicode characters
    /// (zero-width space/joiners, word joiner, BOM) that `.whitespacesAndNewlines`
    /// doesn't cover — these ride along silently when a key is copied from some
    /// web pages' "click to copy" buttons, and turn an otherwise-correct key into
    /// one that reads fine on screen but fails provider auth with a plain
    /// "incorrect API key" error, since the invisible character is still there.
    private func sanitizedAPIKeyInput(_ raw: String) -> String {
        let invisibleScalars: Set<Unicode.Scalar> = ["\u{200B}", "\u{200C}", "\u{200D}", "\u{2060}", "\u{FEFF}"]
        let filtered = String.UnicodeScalarView(raw.unicodeScalars.filter { !invisibleScalars.contains($0) })
        return String(filtered).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    /// Shows enough of a stored key to visually confirm it's the one you meant
    /// to paste (catches truncation/wrong-key mistakes) without ever printing
    /// the whole thing on screen.
    private func redactedKeyPreview(_ key: String) -> String {
        guard key.count > 10 else { return String(repeating: "•", count: key.count) }
        return "\(key.prefix(6))…\(key.suffix(4))"
    }

    /// Which provider a key's prefix unambiguously identifies, if any. OpenAI's
    /// "sk-" is a PREFIX of Anthropic's "sk-ant-", so this must check the more
    /// specific patterns first — a naive `hasPrefix("sk-")` check for OpenAI
    /// also matches Anthropic keys, silently letting a wrong-provider key
    /// through with no warning at all (the actual bug behind an early version
    /// of this check).
    private func detectedProvider(forKeyFormat key: String) -> AIProvider? {
        if key.hasPrefix("sk-ant-") { return .anthropic }
        // Google's AI Studio now issues "AQ."-prefixed Auth keys by default;
        // older "AIza"-prefixed Standard keys still exist but Google rejects
        // them from September 2026 — recognize both formats as Google.
        if key.hasPrefix("AQ.") || key.hasPrefix("AIza") { return .google }
        if key.hasPrefix("sk-") { return .openAI }
        return nil
    }

    /// Checks a key against the currently selected provider. Returns nil if it
    /// looks right. Returns (message, blocking: true) when the key's prefix
    /// confidently identifies a DIFFERENT provider — e.g. pasting an Anthropic
    /// "sk-ant-..." key while OpenAI is selected — since testing that against
    /// the wrong provider's API would only ever produce a generic, unhelpful
    /// 401. Returns (message, blocking: false) for a merely-unrecognized
    /// format (typo, or a future key style this app doesn't know yet), where
    /// testing anyway is still the right call.
    private func keyFormatWarning(for provider: AIProvider, key: String) -> (message: String, blocking: Bool)? {
        if let detected = detectedProvider(forKeyFormat: key), detected != provider {
            return ("This looks like a \(detected.displayName) key, not \(provider.displayName). Get an \(provider.displayName) key instead, or switch providers in Settings > Change Brain.", true)
        }
        switch provider {
        case .openAI:
            return key.hasPrefix("sk-") ? nil : ("OpenAI keys normally start with 'sk-'.", false)
        case .anthropic:
            return key.hasPrefix("sk-ant-") ? nil : ("Anthropic keys normally start with 'sk-ant-'.", false)
        case .google:
            return (key.hasPrefix("AQ.") || key.hasPrefix("AIza")) ? nil : ("Google (Gemini) keys normally start with 'AQ.' (or the older 'AIza' format).", false)
        }
    }

    /// The account-billing page for a provider that requires a paid account.
    /// nil for Google, which has a free tier and no billing page to visit.
    private func billingURL(for provider: AIProvider) -> String? {
        switch provider {
        case .anthropic: return "https://console.anthropic.com/settings/billing"
        case .openAI: return "https://platform.openai.com/settings/billing"
        case .google: return nil
        }
    }

    /// Shows the full, un-redacted key on screen — the actual "view" a
    /// redacted preview can't give you — with a direct Copy button right
    /// there, since seeing it and wanting to copy it usually go together.
    private func showFullAPIKey(provider: AIProvider) {
        clearTerminal()
        printTitle("\(provider.displayName) Key")
        print("")
        if let key = DMEngine.shared.apiKey, !key.isEmpty {
            print("  \(key)", color: .brightGreen)
            print("")
            print("  (\(key.count) characters)", color: .dimGreen)
        } else {
            print("  No key set.", color: .yellow)
        }
        print("")
        var opts = [MenuOption]()
        #if os(iOS)
        opts.append(MenuOption("Copy Key"))
        #endif
        opts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(opts)
        closeHandler = { [weak self] in self?.promptAPIKey() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            #if os(iOS)
            if choice == 1, let key = DMEngine.shared.apiKey {
                UIPasteboard.general.string = key
                self.print("")
                self.print("  Key copied to clipboard.", color: .brightGreen)
                self.print("")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.showFullAPIKey(provider: provider)
                }
                return
            }
            #endif
            self.promptAPIKey()
        }
    }

    private func promptAPIKey(showClearConfirm: Bool = false) {
        let provider = DMEngine.shared.provider
        clearTerminal()
        printTitle("Set API Key")
        print("")
        print("  Provider: \(provider.displayName)", color: .cyan)
        if provider == .google {
            print("  Free tier — just needs a Google", color: .brightGreen)
            print("  account (you must be 18+).", color: .brightGreen)
        } else {
            print("  Requires a paid account with", color: .dimGreen)
            print("  credit — a typical session costs", color: .dimGreen)
            print("  only a few pence. See '?' below for", color: .dimGreen)
            print("  step-by-step setup + billing info.", color: .dimGreen)
        }
        print("")

        // Show existing key status prominently, whether set or not — this
        // is the actual state of the world, front and centre, instead of
        // buried after a wall of setup instructions.
        if let existingKey = DMEngine.shared.apiKey, !existingKey.isEmpty {
            print("  Current key: \(redactedKeyPreview(existingKey)) (\(existingKey.count) chars)", color: .brightGreen)
            if let warning = keyFormatWarning(for: provider, key: existingKey) {
                print("  Note: \(warning.message)", color: .yellow)
            }
        } else {
            print("  No key set for \(provider.displayName) yet.", color: .yellow)
        }

        // Note about key preservation
        let otherProviders = AIProvider.allCases.filter { $0 != provider && DMEngine.shared.apiKey(for: $0) != nil }
        if !otherProviders.isEmpty {
            let names = otherProviders.map { $0.displayName }.joined(separator: ", ")
            print("")
            print("  Keys saved for: \(names)", color: .dimGreen)
            print("  Switch back any time — keys are kept.", color: .dimGreen)
        }
        print("")

        // Handle clear confirmation overlay
        if showClearConfirm {
            print("  Are you sure you want to remove", color: .red)
            print("  this API key?", color: .red)
            print("")
            print("  Tip: Copy the key first using", color: .dimGreen)
            print("  'Copy Key' to back it up.", color: .dimGreen)
            print("")
            var confirmOpts = [MenuOption("Remove Key", tint: .danger), MenuOption("Copy Key First")]
            confirmOpts.append(MenuOption("Delete Permanently", tint: .danger))
            confirmOpts.append(MenuOption("< Back"))
            showMenuOptions(confirmOpts)
            closeHandler = { [weak self] in self?.promptAPIKey() }
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                switch choice {
                case 1: // Remove
                    self.backupSingleAPIKeyToKeychain(for: provider)
                    DMEngine.shared.apiKey = nil
                    self.print("")
                    self.print("  API key removed.", color: .yellow)
                    self.print("  (Backed up to Keychain — use", color: .dimGreen)
                    self.print("  'Load Key' to restore it.)", color: .dimGreen)
                    self.print("")
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in
                        self?.promptAPIKey()
                    }
                case 2: // Copy key first
                    #if os(iOS)
                    if let key = DMEngine.shared.apiKey {
                        UIPasteboard.general.string = key
                        self.print("")
                        self.print("  Key copied to clipboard.", color: .brightGreen)
                        self.print("  Now you can clear it safely.", color: .dimGreen)
                        self.print("")
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in
                            self?.promptAPIKey(showClearConfirm: true)
                        }
                    }
                    #endif
                case 3: // Delete permanently (also wipes the Keychain backup)
                    self.promptPermanentKeyDelete(provider: provider)
                default: // Cancel
                    self.promptAPIKey()
                }
            }
            return
        }

        var options = ["Provider"]
        if provider == .google {
            options.append("Get Free Key")
        } else {
            options.append("Get Key")
            options.append("Billing Page")
        }
        options.append("Paste Key")
        options.append("Edit Key")
        let hasKey = DMEngine.shared.apiKey != nil && !(DMEngine.shared.apiKey ?? "").isEmpty
        // Auto-backup current key to Keychain whenever we visit this screen
        if hasKey {
            backupSingleAPIKeyToKeychain(for: provider)
        }
        let hasKeychainBackup = loadAPIKeyFromKeychain(for: provider) != nil
        if hasKey {
            options.append("Show Key")
            options.append("Test Key")
            options.append("Copy Key")
            options.append("Save to Keychain")
            options.append("Remove Key")
        }
        options.append("Load Key")

        closeHandler = { [weak self] in
            self?.closeHandler = nil
            self?.showDMSettingsSubMenu()
        }

        // Paginated (<< / >>) rather than one long flat list — this screen
        // has grown too many buttons (Provider, key actions, nav) to fit
        // comfortably on one page under the user's configured button limit.
        showPaginatedMenu(options, pinned: ["?", "< Back"], pinnedHandler: { [weak self] pIdx in
            guard let self = self else { return }
            if pIdx == 0 {
                self.showAPIKeyHelp(provider: provider, hasKey: hasKey)
            } else {
                self.closeHandler = nil
                self.showDMSettingsSubMenu()
            }
        }, handler: { [weak self] idx in
            guard let self = self else { return }
            let selected = options[idx]
            self.handleAPIKeySelection(selected, provider: provider)
        })
    }

    /// The actual per-button behaviour for the Set API Key screen — split out
    /// from promptAPIKey so the paginated-menu handler (which only knows the
    /// selected option's text, not its position) can call straight into it.
    private func handleAPIKeySelection(_ selected: String, provider: AIProvider) {
        if selected == "Provider" {
            self.showAIProviderMenu()
        } else if selected == "Get Free Key" || selected == "Get Key" {
                // Open the provider's key URL in Safari
                let urlString: String
                switch provider {
                case .google: urlString = "https://aistudio.google.com/apikey"
                case .anthropic: urlString = "https://console.anthropic.com/settings/keys"
                case .openAI: urlString = "https://platform.openai.com/api-keys"
                }
                if let url = URL(string: urlString) {
                    DispatchQueue.main.async {
                        #if canImport(UIKit)
                        UIApplication.shared.open(url)
                        #elseif os(macOS)
                        NSWorkspace.shared.open(url)
                        #endif
                    }
                }
                // When they come back, show the same menu again
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                    self.promptAPIKey()
                }
            } else if selected == "Billing Page" {
                if let urlString = self.billingURL(for: provider), let url = URL(string: urlString) {
                    DispatchQueue.main.async {
                        #if canImport(UIKit)
                        UIApplication.shared.open(url)
                        #elseif os(macOS)
                        NSWorkspace.shared.open(url)
                        #endif
                    }
                }
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                    self.promptAPIKey()
                }
            } else if selected == "Paste Key" {
                // Paste from clipboard
                #if os(iOS)
                if let raw = UIPasteboard.general.string, !self.sanitizedAPIKeyInput(raw).isEmpty {
                    let clipText = self.sanitizedAPIKeyInput(raw)
                    self.print("")
                    if let warning = self.keyFormatWarning(for: provider, key: clipText), warning.blocking {
                        DMEngine.shared.apiKey = nil
                        self.print("  \(warning.message)", color: .yellow)
                        self.print("")
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in
                            self?.promptAPIKey()
                        }
                        return
                    }
                    DMEngine.shared.apiKey = clipText
                    if let warning = self.keyFormatWarning(for: provider, key: clipText) {
                        self.print("  Note: \(warning.message)", color: .yellow)
                        self.print("  Testing it anyway...", color: .dimGreen)
                    } else {
                        self.print("  Testing API key...", color: .dimGreen)
                    }
                    self.validateAndConfirmKey(provider: provider)
                } else {
                    self.print("")
                    self.print("Clipboard is empty.", color: .yellow)
                    self.print("Copy your API key first.", color: .dimGreen)
                    self.print("")
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in
                        self?.promptAPIKey()
                    }
                }
                #endif
            } else if selected == "Edit Key" {
                // Pre-fill with the actual current key (if any) so this
                // doubles as "view" — you can see and correct it character
                // by character, not just blindly overwrite it.
                self.print("")
                self.promptText("Edit your API key:")
                if let existing = DMEngine.shared.apiKey, !existing.isEmpty {
                    self.prefillInputText = existing
                }
                self.inputHandler = { [weak self] key in
                    let trimmed = self?.sanitizedAPIKeyInput(key) ?? key.trimmingCharacters(in: .whitespacesAndNewlines)
                    if trimmed.isEmpty {
                        self?.promptAPIKey()
                        return
                    }
                    self?.print("")
                    if let warning = self?.keyFormatWarning(for: provider, key: trimmed), warning.blocking {
                        DMEngine.shared.apiKey = nil
                        self?.print("  \(warning.message)", color: .yellow)
                        self?.print("")
                        self?.waitForContinue()
                        self?.inputHandler = { [weak self] _ in
                            self?.promptAPIKey()
                        }
                        return
                    }
                    DMEngine.shared.apiKey = trimmed
                    if let warning = self?.keyFormatWarning(for: provider, key: trimmed) {
                        self?.print("  Note: \(warning.message)", color: .yellow)
                        self?.print("  Testing it anyway...", color: .dimGreen)
                    } else {
                        self?.print("  Testing API key...", color: .dimGreen)
                    }
                    self?.validateAndConfirmKey(provider: provider)
                }
            } else if selected == "Show Key" {
                self.showFullAPIKey(provider: provider)
            } else if selected == "Test Key" {
                if let key = DMEngine.shared.apiKey, !key.isEmpty {
                    self.print("")
                    self.print("  Key: \(self.redactedKeyPreview(key)) (\(key.count) chars)", color: .dimGreen)
                    if let warning = self.keyFormatWarning(for: provider, key: key) {
                        self.print("  Note: \(warning.message)", color: .yellow)
                    }
                    self.print("  Testing API key...", color: .dimGreen)
                    self.validateAndConfirmKey(provider: provider)
                }
            } else if selected == "Copy Key" {
                #if os(iOS)
                if let key = DMEngine.shared.apiKey {
                    UIPasteboard.general.string = key
                    self.print("")
                    self.print("  Key copied to clipboard.", color: .brightGreen)
                    self.print("")
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in
                        self?.promptAPIKey()
                    }
                }
                #endif
            } else if selected == "Save to Keychain" {
                self.backupSingleAPIKeyToKeychain(for: provider)
                self.print("")
                self.print("  \(provider.displayName) key saved to Keychain.", color: .brightGreen)
                self.print("")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.promptAPIKey()
                }
            } else if selected == "Remove Key" {
                self.promptAPIKey(showClearConfirm: true)
            } else if selected == "Load Key" {
                if let restored = self.loadAPIKeyFromKeychain(for: provider) {
                    DMEngine.shared.apiKey = restored
                    self.print("")
                    self.print("  Key restored from Keychain!", color: .brightGreen)
                    let preview = String(restored.suffix(6))
                    self.print("  Key: ...\(preview)", color: .dimGreen)
                    self.print("")
                    self.print("  Testing API key...", color: .dimGreen)
                    self.validateAndConfirmKey(provider: provider)
                } else {
                    self.print("")
                    self.print("  No backup found in Keychain.", color: .yellow)
                    self.print("")
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in
                        self?.promptAPIKey()
                    }
                }
            }
    }

