    private func promptPermanentKeyDelete(provider: AIProvider) {
        clearTerminal()
        printTitle("Permanently Delete Key")
        print("")
        print("  This will permanently remove your", color: .red)
        print("  \(provider.displayName) API key from this", color: .red)
        print("  device — including the Keychain backup.", color: .red)
        print("")
        print("  You will not be able to recover it.", color: .yellow)
        print("  Make sure you have it saved elsewhere", color: .yellow)
        print("  or can create a new one.", color: .yellow)
        print("")

        if let key = DMEngine.shared.apiKey {
            let preview = String(key.suffix(6))
            print("  Key: ...\(preview)", color: .dimGreen)
            print("")
        }

        let opts = [
            MenuOption("Delete Permanently", tint: .danger),
            MenuOption("< Back")
        ]
        showMenuOptions(opts)
        closeHandler = { [weak self] in self?.promptAPIKey() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                DMEngine.shared.apiKey = nil
                self.deleteSingleAPIKeyFromKeychain(for: provider)
                self.print("")
                self.print("  Key permanently deleted.", color: .yellow)
                self.print("  Removed from Keychain backup too.", color: .dimGreen)
                self.print("")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.promptAPIKey()
                }
            } else {
                self.promptAPIKey()
            }
        }
    }

    private func validateAndConfirmKey(provider: AIProvider) {
        DMEngine.shared.testAPIKey { [weak self] success, errorMessage in
            DispatchQueue.main.async {
                if success {
                    self?.print("")
                    self?.print("  Key verified!", color: .brightGreen)
                    self?.print("  \(provider.displayName) is working.", color: .brightGreen)
                    self?.print("  The AI Dungeon Master is now", color: .cyan)
                    self?.print("  available.", color: .cyan)
                    self?.print("")
                    self?.waitForContinue()
                    self?.inputHandler = { [weak self] _ in
                        self?.promptAPIKey()
                    }
                } else {
                    self?.print("")
                    self?.print("  KEY TEST FAILED", color: .red, bold: true)
                    self?.print("")
                    if let self = self, let key = DMEngine.shared.apiKey, !key.isEmpty {
                        self.print("  Key tested: \(self.redactedKeyPreview(key)) (\(key.count) chars)", color: .dimGreen)
                        self.print("")
                    }
                    if let msg = errorMessage {
                        // Wrap long error messages
                        let maxLen = 30
                        var remaining = msg
                        while !remaining.isEmpty {
                            let line = String(remaining.prefix(maxLen))
                            remaining = String(remaining.dropFirst(line.count))
                            self?.print("  \(line)", color: .yellow)
                        }
                        self?.print("")
                        // Provide helpful guidance based on error
                        let msgLower = msg.lowercased()
                        if msgLower.contains("401") || msgLower.contains("authentication") || msgLower.contains("invalid") || msgLower.contains("incorrect") {
                            self?.print("  LIKELY CAUSE:", color: .cyan, bold: true)
                            self?.print("  The API key is invalid or expired.", color: .dimGreen)
                            self?.print("  Create a new key and try again.", color: .dimGreen)
                            self?.print("  Remember: keys can only be copied", color: .dimGreen)
                            self?.print("  at the moment of creation!", color: .dimGreen)
                        } else if msgLower.contains("402") || msgLower.contains("billing") || msgLower.contains("credit") || msgLower.contains("payment") || msgLower.contains("insufficient") {
                            self?.print("  LIKELY CAUSE:", color: .cyan, bold: true)
                            self?.print("  No credit on your account.", color: .dimGreen)
                            self?.print("  Add credit/payment method at", color: .dimGreen)
                            self?.print("  your provider's billing page.", color: .dimGreen)
                        } else if msgLower.contains("403") || msgLower.contains("permission") || msgLower.contains("forbidden") {
                            self?.print("  LIKELY CAUSE:", color: .cyan, bold: true)
                            self?.print("  Your key doesn't have permission", color: .dimGreen)
                            self?.print("  to use this API. Check your", color: .dimGreen)
                            self?.print("  account settings.", color: .dimGreen)
                        } else if msgLower.contains("429") || msgLower.contains("rate") || msgLower.contains("quota") {
                            self?.print("  LIKELY CAUSE:", color: .cyan, bold: true)
                            self?.print("  Rate limit or quota exceeded.", color: .dimGreen)
                            self?.print("  Wait a minute and try again,", color: .dimGreen)
                            self?.print("  or check your usage limits.", color: .dimGreen)
                        } else if msgLower.contains("connection") || msgLower.contains("network") || msgLower.contains("timeout") {
                            self?.print("  LIKELY CAUSE:", color: .cyan, bold: true)
                            self?.print("  No internet connection.", color: .dimGreen)
                            self?.print("  Check your WiFi/mobile data", color: .dimGreen)
                            self?.print("  and try again.", color: .dimGreen)
                        } else if msgLower.contains("404") || msgLower.contains("not_found") || msgLower.contains("model") {
                            self?.print("  LIKELY CAUSE:", color: .cyan, bold: true)
                            self?.print("  The AI model is unavailable.", color: .dimGreen)
                            self?.print("  This may be a temporary issue.", color: .dimGreen)
                            self?.print("  Try again later.", color: .dimGreen)
                        } else {
                            self?.print("  Check the key and try again.", color: .dimGreen)
                        }
                    } else {
                        self?.print("  Unknown error. Check the key", color: .dimGreen)
                        self?.print("  and try again.", color: .dimGreen)
                    }
                    // Remove the bad key
                    DMEngine.shared.apiKey = nil
                    self?.print("")
                    self?.waitForContinue()
                    self?.inputHandler = { [weak self] _ in
                        self?.promptAPIKey()
                    }
                }
            }
        }
    }

    // MARK: - Hall of Fame

    func showHallOfFame() {
        clearTerminal()
        menuImageName = "DragonGuard"

        printLines(asciiTrophy, color: .yellow)
        print("")
        printTitle("Hall of Fame")

        var entries = HallOfFameManager.shared.listEntries()
        let manager = HallOfFameManager.shared

        // listEntries() already comes back points-desc, which is the
        // .points order, so only re-sort for the other modes (see
        // Settings > List Order).
        switch listSortMode {
        case .points:
            break
        case .date:
            entries.sort { $0.date > $1.date }
        case .name:
            entries.sort { $0.dungeonName.localizedCaseInsensitiveCompare($1.dungeonName) == .orderedAscending }
        case .level:
            entries.sort { $0.dungeonLevel > $1.dungeonLevel }
        }

        // Summary stats
        print("  Victories: \(manager.totalVictories())  Defeats: \(manager.totalDefeats())  Total Runs: \(manager.totalRuns())", color: .cyan)
        if manager.bestGold() > 0 {
            print("  Best Gold: \(manager.bestGold())  Most Slain: \(manager.mostSlain())", color: .cyan)
        }
        print("")

        if entries.isEmpty {
            print("  No adventures recorded yet.", color: .dimGreen)
            print("  Complete a dungeon to earn your place!", color: .dimGreen)
            print("")

            showMenu(["Manage", "< Back"])
            closeHandler = { [weak self] in self?.showMainMenu() }
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                if choice == 1 { self.showHallOfFameManage() } else { self.showMainMenu() }
            }
        } else {
            let dateFormatter = DateFormatter()
            dateFormatter.dateStyle = .medium

            var options: [String] = []
            var entryLineRanges: [Range<Int>] = []
            for (i, entry) in entries.enumerated() {
                let lineStart = terminalLines.count
                let outcomeTag = entry.outcome == .victory ? "W" : "L"
                let outcomeColor: TerminalColor = entry.outcome == .victory ? .yellow : .red

                // This absolute index matches the button's own displayNumber
                // (see showPaginatedMenu) regardless of which page the entry
                // lands on — the two numbering schemes used to diverge past
                // page 1 because the button counted only visible items on
                // its own page; now both use this same stable, global index.
                let name = String(entry.dungeonName.prefix(20))
                let headerText = "\(i + 1). \(name) Lv.\(entry.dungeonLevel) \(outcomeTag) \(entry.score)pts"
                printWrapped(headerText, color: outcomeColor)

                let day = entry.gameTimeMinutes / 1440 + 1
                printWrapped(entry.partyDescription, indent: 3, color: .dimGreen)
                printWrapped("Gold:\(entry.goldCollected) Slain:\(entry.monstersSlain) Lv\(entry.dungeonLevel) rooms:\(entry.roomsExplored)/\(entry.totalRooms) Day \(day)", indent: 3, color: .dimGreen)
                printWrapped(dateFormatter.string(from: entry.date), indent: 3, color: .dimGreen)
                print("")
                entryLineRanges.append(lineStart..<terminalLines.count)

                options.append("\(name) Lv.\(entry.dungeonLevel) \(outcomeTag)")
            }

            printWrapped("Tap an entry (its button or its text) to read its tale — the tale screen has a Relive/Rewrite button if a save is linked. Long-press a numbered button to jump straight into that adventure if it has one.", indent: 2, color: .dimGreen)
            print("")

            let tales = entries.map { AdventureTaleData(hof: $0) }
            let openTale: (Int) -> Void = { [weak self] idx in
                guard let self = self, idx >= 0 && idx < tales.count else { return }
                self.showAdventureTale(tales[idx], tales: tales, index: idx)
            }

            // "Manage Saves" lives behind the non-numbered "Manage" button
            // (see showHallOfFameManage) instead of being pinned with a
            // number past the end of the list regardless of page, or
            // appended to the list itself where a long history would bury
            // it behind however many pages that needs.
            showPaginatedMenuOptions(options, pinned: ["?", "Manage", "< Back"], handler: { idx in
                openTale(idx)
            }, pinnedHandler: { [weak self] choice in
                guard let self = self else { return }
                switch choice {
                case 0: self.showHallOfFameHelp()
                case 1: self.showHallOfFameManage()
                default: self.showMainMenu()
                }
            })
            closeHandler = { [weak self] in self?.showMainMenu() }

            // Tap the printed entry text itself (not just its numbered
            // button) to open the same tale — matches Continue Adventure's
            // equivalent convenience.
            textLongPressHandler = { lineIndex in
                guard let idx = entryLineRanges.firstIndex(where: { $0.contains(lineIndex) }) else { return }
                openTale(idx)
            }

            // Long-press a numbered button → jump straight into that
            // adventure (skip the tale-reading screen) if a save is linked;
            // no-op otherwise — matches Continue Adventure's equivalent.
            menuLongPressHandler = { [weak self] choice in
                guard let self = self, choice >= 1, choice <= tales.count else { return }
                let tale = tales[choice - 1]
                guard tale.saveGameId != nil, SaveGameManager.shared.load(id: tale.saveGameId!) != nil else { return }
                self.showLoadTransition(tale)
            }
        }
    }

    /// Secondary-actions sub-screen for the (game) Hall of Fame, reached via
    /// its non-numbered "Manage" button.
    private func showHallOfFameManage() {
        clearTerminal()
        printTitle("Manage")
        print("")
        showMenu(["Manage Saves", "Select & Delete Saves", "< Back"])
        closeHandler = { [weak self] in self?.showHallOfFame() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: self.showLoadGameMenu(returnTo: .mainMenu)
            case 2:
                self.manageSaveSelectMode = true
                self.showLoadGameMenu(returnTo: .mainMenu)
            default: self.showHallOfFame()
            }
        }
    }

    private func showHallOfFameHelp() {
        showInlineHelp {
            self.printTitle("Hall of Fame — Help")
            self.print("")

            self.print("  HALL OF FAME", color: .cyan, bold: true)
            self.printWrapped("Records the top 10 adventures — victories and defeats. Each entry shows the dungeon name, level, outcome, and a composite score.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  SCORE", color: .cyan, bold: true)
            self.printWrapped("Score is calculated from: victory bonus (+500), gold collected, monsters slain (×20), combats won (×50), exploration percentage, and dungeon level multiplier.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  TAP AN ENTRY", color: .cyan, bold: true)
            self.printWrapped("Tap the numbered button for an entry to read a dramatic tale of that adventure, generated by the Dungeon Master. The tale includes party composition, key battles, and the final outcome.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  STATS", color: .cyan, bold: true)
            self.printWrapped("The summary at the top shows total victories, defeats, best gold haul, and most monsters slain across all recorded runs.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  WITHIN A TALE", color: .cyan, bold: true)
            self.printWrapped("Swipe or use the <</>> buttons to move between tales (cycles round at the end); the dice button picks a random one.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  ⚔ RELIVE AN ADVENTURE", color: .cyan, bold: true)
            self.printWrapped("Some tales have a linked save game. Long-press the title at the top of a tale — or tap the ⚔ button — to step into the adventure yourself. For victories, you'll relive the legend. For defeats, you'll get a second chance, starting one room before the fall.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  MANAGE SAVES", color: .cyan, bold: true)
            self.printWrapped("Browses every saved game, not just Hall of Fame tales — including adventures still in progress. Resume, rename, or delete from there.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    /// Retro ASCII scroll-wheel style tale selector
    private func showTaleSelector(entries: [HallOfFameEntry], selectedIndex: Int = 0) {
        clearTerminal()
        suppressAutoScroll = true
        scrollLocked = true
        printTitle("Choose a Tale")
        print("")

        let count = entries.count

        // ASCII scroll display — show 5 slots with the selected one highlighted
        let scrollArt = [
            "  ╔══════════════════════════╗",
            "  ║  ▲ scroll up             ║",
            "  ╠══════════════════════════╣",
        ]
        printLines(scrollArt, color: .dimGreen)

        // Show entries: 2 above, current, 2 below
        for offset in -2...2 {
            let idx = ((selectedIndex + offset) % count + count) % count
            let entry = entries[idx]
            let outcomeTag = entry.outcome == .victory ? "W" : "L"
            let name = String(entry.dungeonName.prefix(16))
            let line = "\(idx + 1). \(name) \(outcomeTag) \(entry.score)pts"
            let padded = line.padding(toLength: 26, withPad: " ", startingAt: 0)

            if offset == 0 {
                // Selected entry — highlighted
                print("  ║▶ \(padded)◀║", color: .yellow, bold: true)
            } else {
                // Dimmed neighbours
                let dimColor: TerminalColor = abs(offset) == 1 ? .dimGreen : .gray
                print("  ║  \(padded)  ║", color: dimColor)
            }
        }

        let scrollArtBottom = [
            "  ╠══════════════════════════╣",
            "  ║  ▼ scroll down           ║",
            "  ╚══════════════════════════╝",
        ]
        printLines(scrollArtBottom, color: .dimGreen)
        print("")

        // Show selected entry details
        let entry = entries[selectedIndex]
        printWrapped(entry.partyDescription, indent: 4, color: .cyan)
        let day = entry.gameTimeMinutes / 1440 + 1
        printWrapped("Gold:\(entry.goldCollected)  Slain:\(entry.monstersSlain)  Lv\(entry.dungeonLevel) rooms:\(entry.roomsExplored)/\(entry.totalRooms)  Day \(day)", indent: 4, color: .dimGreen)
        print("")

        // "Read Tale" alone meant loading/reliving a specific adventure
        // needed an extra detour through that narrative screen first — this
        // scroll-wheel selector had no way to just pick one directly.
        let canRelive = entry.saveGameId != nil && SaveGameManager.shared.load(id: entry.saveGameId!) != nil
        var options = ["▲ Prev", "▼ Next", "Read Tale"]
        if canRelive {
            options.append("⚔ Relive")
        }
        if count > 3 {
            options.insert("Surprise Me", at: 2)
        }
        var menuOpts = options.map { MenuOption($0) }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))

        showMenuOptions(menuOpts)
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == menuOpts.count {
                self.showHallOfFame()
                return
            }
            if choice == menuOpts.count - 1 {
                self.showInlineHelp {
                    self.printTitle("Choose a Tale — Help")
                    self.print("")
                    self.print("  ▲ PREV / ▼ NEXT", color: .cyan, bold: true)
                    self.printWrapped("Scroll through recorded tales one at a time. You can also swipe left/right.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  READ TALE", color: .cyan, bold: true)
                    self.printWrapped("Shows a dramatic narrative summary of the selected adventure.", indent: 2, color: .dimGreen)
                    self.print("")
                    if canRelive {
                        self.print("  ⚔ RELIVE", color: .cyan, bold: true)
                        self.printWrapped("Jumps straight into this adventure's linked save — a victory lets you relive the legend, a defeat gives you a second chance from one room before the fall. Only shown when a save still exists for this tale.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                    if count > 3 {
                        self.print("  SURPRISE ME", color: .cyan, bold: true)
                        self.printWrapped("Jumps to a random tale.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                }
                return
            }
            let selected = options[choice - 1]
            switch selected {
            case "▲ Prev":
                let prev = (selectedIndex - 1 + count) % count
                self.showTaleSelector(entries: entries, selectedIndex: prev)
            case "▼ Next":
                let next = (selectedIndex + 1) % count
                self.showTaleSelector(entries: entries, selectedIndex: next)
            case "Surprise Me":
                let rand = Int.random(in: 0..<count)
                let tales = entries.map { AdventureTaleData(hof: $0) }
                self.showAdventureTale(tales[rand], tales: tales, index: rand)
            case "Read Tale":
                let tales = entries.map { AdventureTaleData(hof: $0) }
                self.showAdventureTale(tales[selectedIndex], tales: tales, index: selectedIndex)
            case "⚔ Relive":
                self.showLoadTransition(AdventureTaleData(hof: entry))
            default:
                self.showHallOfFame()
            }
        }

        closeHandler = { [weak self] in
            self?.closeHandler = nil
            self?.showHallOfFame()
        }

        // Swipe navigation
        cardPositionLabel = cardLabel(selectedIndex + 1, of: count)
        swipeLeftHandler = { [weak self] in
            let next = (selectedIndex + 1) % count
            self?.showTaleSelector(entries: entries, selectedIndex: next)
        }
        swipeRightHandler = { [weak self] in
            let prev = (selectedIndex - 1 + count) % count
            self?.showTaleSelector(entries: entries, selectedIndex: prev)
        }
        swipeRandomHandler = count > 1 ? { [weak self] in
            let r = Int.random(in: 0..<count)
            self?.showTaleSelector(entries: entries, selectedIndex: r)
        } : nil
    }

    /// Generate an exciting narrative summary of a Hall of Fame entry
    /// When entries/index provided, enables swipe navigation between tales
    /// Everything showAdventureTale() needs to narrate an adventure — built
    /// either from a completed HallOfFameEntry, or directly from an
    /// in-progress SaveGame (outcome nil in that case). This is what makes
    /// the exact same narrative screen, with the exact same style, apply to
    /// every save equally — a still-unfolding adventure and a completed one
    /// differ only in outcome being nil vs set, not in which screen or
    /// wording shows up.
    private struct AdventureTaleData {
        let dungeonName: String
        let dungeonLevel: Int
        let partyNames: [String]
        let partyDescription: String
        let outcome: RunOutcome?  // nil = still in progress
        let goldCollected: Int
        let monstersSlain: Int
        let combatsWon: Int
        let roomsExplored: Int
        let totalRooms: Int
        let gameTimeMinutes: Int
        let date: Date
        let score: Int?  // nil when outcome is nil — no final score yet
        let saveGameId: UUID?

        init(hof entry: HallOfFameEntry) {
            dungeonName = entry.dungeonName
            dungeonLevel = entry.dungeonLevel
            partyNames = entry.partyNames
            partyDescription = entry.partyDescription
            outcome = entry.outcome
            goldCollected = entry.goldCollected
            monstersSlain = entry.monstersSlain
            combatsWon = entry.combatsWon
            roomsExplored = entry.roomsExplored
            totalRooms = entry.totalRooms
            gameTimeMinutes = entry.gameTimeMinutes
            date = entry.date
            score = entry.score
            saveGameId = entry.saveGameId
        }

        init(inProgress save: SaveGame) {
            dungeonName = save.dungeonName
            dungeonLevel = save.dungeonLevel
            partyNames = save.party.map { $0.name }
            partyDescription = save.partyDescription
            outcome = nil
            goldCollected = save.party.reduce(0) { $0 + $1.gold }
            monstersSlain = save.monstersSlain
            combatsWon = save.combatsWon
            roomsExplored = save.dungeon.rooms.values.filter { $0.visited }.count
            totalRooms = save.dungeon.rooms.count
            gameTimeMinutes = save.gameTimeMinutes
            date = save.savedAt
            score = nil
            saveGameId = save.id
        }
    }

    /// - onBack: where "< Back"/closeHandler go — defaults to the standalone
    ///   Hall of Fame screen.
    private func showAdventureTale(_ tale: AdventureTaleData, tales: [AdventureTaleData] = [], index: Int = 0, onBack: (() -> Void)? = nil) {
        let backTarget = onBack ?? { [weak self] in self?.showHallOfFame() }
        clearTerminal()

        // Show appropriate header art — neither trophy nor skull fits an
        // adventure that hasn't ended yet.
        switch tale.outcome {
        case .victory: printLines(asciiTrophy, color: .yellow)
        case .defeat: printLines(asciiSkull, color: .red)
        case nil: break
        }
        print("")

        // Title
        let titleColor: TerminalColor = tale.outcome == .victory ? .yellow : (tale.outcome == .defeat ? .red : .cyan)
        let statusWord = tale.outcome == .victory ? "VICTORY" : (tale.outcome == .defeat ? "DEFEAT" : "IN PROGRESS")
        printTitle(tale.dungeonName)
        print("  Level \(tale.dungeonLevel) — \(statusWord)", color: titleColor, bold: true)
        print("")

        // The party
        print("  THE PARTY", color: .cyan, bold: true)

        // Parse class from partyDescription and show art side-by-side
        let members = tale.partyDescription.components(separatedBy: ", ")
        var partyClasses: [CharacterClass] = []
        for member in members {
            // Format: "Name (Class)"
            if let openParen = member.lastIndex(of: "("),
               let closeParen = member.lastIndex(of: ")") {
                let className = String(member[member.index(after: openParen)..<closeParen])
                if let cls = CharacterClass.allCases.first(where: { $0.rawValue == className }) {
                    partyClasses.append(cls)
                }
            }
        }

        // Show party art side-by-side (split into rows of 2-3 to fit screen)
        if !partyClasses.isEmpty {
            let colWidth = 12
            let rowSize = partyClasses.count >= 4 ? 2 : partyClasses.count
            for chunk in stride(from: 0, to: partyClasses.count, by: rowSize) {
                let end = min(chunk + rowSize, partyClasses.count)
                let chunkClasses = Array(partyClasses[chunk..<end])
                let chunkMembers = Array(members[chunk..<end])
                let arts = chunkClasses.map { $0.asciiArt }
                let maxLines = arts.map { $0.count }.max() ?? 0
                for row in 0..<maxLines {
                    var line = "   "
                    for art in arts {
                        let artLine = row < art.count ? art[row] : ""
                        line += artLine.padding(toLength: colWidth, withPad: " ", startingAt: 0)
                    }
                    print(line, color: .cyan)
                }
                var labelLine = "   "
                for member in chunkMembers {
                    let name = member.components(separatedBy: " (").first ?? member
                    labelLine += String(name.prefix(colWidth - 1)).padding(toLength: colWidth, withPad: " ", startingAt: 0)
                }
                print(labelLine, color: .brightGreen)
                if end < partyClasses.count { print("") }
            }
        }
        print("")

        // Generate exciting narrative
        print("  THE TALE", color: .cyan, bold: true)
        print("")

        let day = tale.gameTimeMinutes / 1440 + 1
        let hours = (tale.gameTimeMinutes % 1440) / 60
        let explorationPct = tale.totalRooms > 0 ? (tale.roomsExplored * 100 / tale.totalRooms) : 0

        // Opening
        let partySize = tale.partyNames.count
        let firstNames = tale.partyNames.map { $0.components(separatedBy: " ").first ?? $0 }
        let heroList = firstNames.count <= 2
            ? firstNames.joined(separator: " and ")
            : firstNames.dropLast().joined(separator: ", ") + ", and " + (firstNames.last ?? "")

        printWrapped("On a \(day > 1 ? "fateful" : "bold") day, \(heroList) \(partySize == 1 ? "descended" : "descended together") into the depths of \(tale.dungeonName).", indent: 4, color: .green)
        print("")

        // Combat narrative
        if tale.monstersSlain > 0 {
            let combatWord: String
            if tale.monstersSlain >= 15 { combatWord = "carved a bloody path through" }
            else if tale.monstersSlain >= 8 { combatWord = "fought valiantly against" }
            else { combatWord = "clashed with" }

            printWrapped("They \(combatWord) \(tale.monstersSlain) creature\(tale.monstersSlain == 1 ? "" : "s"), winning \(tale.combatsWon) battle\(tale.combatsWon == 1 ? "" : "s") in the darkness below.", indent: 4, color: .green)
            print("")
        }

        // Show a random monster they might have faced
        let possibleMonsters = MonsterType.forLevel(tale.dungeonLevel)
        if let monster = possibleMonsters.randomElement() {
            print("", color: .dimGreen)
            let art = monster.asciiArt
            for line in art {
                print("       \(line)", color: .red)
            }
            printWrapped("Among their foes: the dreaded \(monster.rawValue)...", indent: 4, color: .dimGreen)
            print("")
        }

        // Exploration
        if explorationPct == 100 {
            printWrapped("Every chamber was explored, every corridor mapped — \(tale.roomsExplored) rooms laid bare.", indent: 4, color: .green)
        } else if explorationPct >= 75 {
            printWrapped("They explored \(tale.roomsExplored) of \(tale.totalRooms) rooms, leaving few corners unsearched.", indent: 4, color: .green)
        } else {
            printWrapped("They ventured through \(tale.roomsExplored) of \(tale.totalRooms) rooms before fate intervened.", indent: 4, color: .green)
        }
        print("")

        // Treasure
        if tale.goldCollected > 0 {
            let treasureWord: String
            if tale.goldCollected >= 300 { treasureWord = "amassed a king's ransom of" }
            else if tale.goldCollected >= 100 { treasureWord = "gathered a respectable hoard of" }
            else { treasureWord = "scraped together" }
            printWrapped("\(treasureWord) \(tale.goldCollected) gold pieces.", indent: 4, color: .yellow)
            print("")
        }

        // Duration
        printWrapped("The adventure \(tale.outcome == nil ? "has lasted" : "lasted") \(day > 1 ? "\(day) days" : "\(hours) hours") in the depths\(tale.outcome == nil ? " so far" : "").", indent: 4, color: .dimGreen)
        print("")

        // Ending
        switch tale.outcome {
        case .victory:
            printLines(asciiSwords, color: .yellow)
            print("")
            printWrapped("Against all odds, they emerged triumphant! The dungeon boss fell, and \(tale.dungeonName) was conquered. Their names echo in the halls of legend.", indent: 4, color: .yellow)
            print("")
        case .defeat:
            printWrapped("But the darkness proved too strong. One by one, they fell... Their sacrifice is remembered, even if their quest ended in shadow.", indent: 4, color: .red)
            print("")
        case nil:
            printWrapped("Their story is still being written — the ending has yet to unfold.", indent: 4, color: .cyan)
            print("")
        }

        // Score
        if let score = tale.score {
            print("  FINAL SCORE: \(score) points", color: tale.outcome == .victory ? .yellow : .red, bold: true)
            print("")
        }

        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .long
        print("  \(tale.outcome == nil ? "Last saved" : "Recorded"): \(dateFormatter.string(from: tale.date))", color: .dimGreen)
        print("")

        // Hint about continuing/reliving the adventure
        let hasSave = tale.saveGameId != nil && SaveGameManager.shared.load(id: tale.saveGameId!) != nil
        let label: String
        switch tale.outcome {
        case .victory: label = "⚔ Relive"
        case .defeat: label = "⚔ Rewrite"
        case nil: label = "▶ Continue"
        }
        if hasSave {
            switch tale.outcome {
            case .victory: printWrapped("Tap the title, or \(label), to relive this legendary quest...", indent: 4, color: .dimGreen)
            case .defeat: printWrapped("Tap the title, or \(label), to rewrite history — pick up one room before the fall...", indent: 4, color: .dimGreen)
            case nil: printWrapped("Tap the title, or \(label), to continue this adventure...", indent: 4, color: .dimGreen)
            }
            print("")
        }
        print("")

        // Always offer a way back and help, plus Relive/Rewrite/Continue
        // when a save is linked. "?" and "< Back" share the compact nav
        // cell (see isCompactPinnedNavText) so they read consistently with
        // every other screen: nav/back on the left, help in the middle.
        if hasSave {
            showMenuOptions([MenuOption(label), MenuOption("?", tint: .navigation, compact: true), MenuOption("< Back", tint: .navigation, compact: true)])
        } else {
            showMenuOptions([MenuOption("?", tint: .navigation, compact: true), MenuOption("< Back", tint: .navigation, compact: true)])
        }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= self.currentMenuOptions.count else { return }
            switch self.currentMenuOptions[choice - 1].text {
            case let text where text == label:
                self.showLoadTransition(tale)
            case "?":
                self.showInlineHelp {
                    self.printTitle("Adventure Tale — Help")
                    self.print("")
                    self.print("  \(label.uppercased())", color: .cyan, bold: true)
                    switch tale.outcome {
                    case .victory:
                        self.printWrapped("Loads this adventure's most recent save point and lets you play on from there, as if the victory hadn't happened yet.", indent: 2, color: .dimGreen)
                    case .defeat:
                        self.printWrapped("Loads the save point just before the fall, so you can try to avoid the mistake that ended the run.", indent: 2, color: .dimGreen)
                    case nil:
                        self.printWrapped("Loads this adventure's most recent save point and picks up right where you left off.", indent: 2, color: .dimGreen)
                    }
                    self.print("")
                    self.print("  TAP THE TITLE", color: .cyan, bold: true)
                    self.printWrapped("Same shortcut as the \(label) button above — tap the boxed title near the top of the screen.", indent: 2, color: .dimGreen)
                    self.print("")
                    if tales.count > 1 {
                        self.print("  SWIPE", color: .cyan, bold: true)
                        self.printWrapped("Swipe left or right to browse other adventures' tales.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                }
            default:
                SpeechEngine.shared.stop()
                backTarget()
            }
        }

        closeHandler = {
            SpeechEngine.shared.stop()
            backTarget()
        }

        // Tap title (its exact printed lines — see printTitle/titleLineIndices,
        // which precisely tracks them regardless of how much ASCII art or
        // other content precedes it, e.g. the trophy/skull header above)
        // to load the save. Despite the name, this is wired to a plain tap,
        // not an actual long-press — see textTapEnabled in TerminalView.
        if hasSave {
            textLongPressHandler = { [weak self] lineIndex in
                guard let self = self, self.titleLineIndices.contains(lineIndex) else { return }
                self.showLoadTransition(tale)
            }
        }

        // Swipe navigation between tales
        let count = tales.count
        if count > 1 {
            cardPositionLabel = cardLabel(index + 1, of: count)
            swipeLeftHandler = { [weak self] in
                SpeechEngine.shared.stop()
                let next = (index + 1) % count
                self?.showAdventureTale(tales[next], tales: tales, index: next, onBack: onBack)
            }
            swipeRightHandler = { [weak self] in
                SpeechEngine.shared.stop()
                let prev = (index - 1 + count) % count
                self?.showAdventureTale(tales[prev], tales: tales, index: prev, onBack: onBack)
            }
            swipeRandomHandler = { [weak self] in
                SpeechEngine.shared.stop()
                let r = Int.random(in: 0..<count)
                self?.showAdventureTale(tales[r], tales: tales, index: r, onBack: onBack)
            }
        }

        // If DM voice is on, narrate the tale
        if SpeechEngine.shared.isEnabled {
            let heroList = tale.partyNames.map { $0.components(separatedBy: " ").first ?? $0 }.joined(separator: ", ")
            var narration = "\(heroList) entered \(tale.dungeonName). "
            if tale.monstersSlain > 0 {
                narration += "They slew \(tale.monstersSlain) creatures and won \(tale.combatsWon) battles. "
            }
            narration += "They explored \(tale.roomsExplored) of \(tale.totalRooms) rooms. "
            if tale.goldCollected > 0 {
                narration += "They collected \(tale.goldCollected) gold. "
            }
            switch tale.outcome {
            case .victory: narration += "Against all odds, they emerged triumphant!"
            case .defeat: narration += "But the darkness proved too strong, and they fell."
            case nil: narration += "Their story continues..."
            }
            SpeechEngine.shared.speak(narration)
        }

        // Also read the tale's full printed text aloud if the general
        // "read screen aloud" accessibility mode is on (independent of the
        // DM Voice narration above, which is a separate, shorter summary).
        // Ducks music automatically the same way any other spoken screen
        // does — see SpeechEngine's own duck/unduckMusic calls.
        autoReadIfSpeakerMode()
    }

    /// Dramatic transition screen before actually loading the tale's linked
    /// save — the exact wording depends on outcome (Relive a victory,
    /// Rewrite a defeat, or just resume an adventure still in progress).
    private func showLoadTransition(_ tale: AdventureTaleData) {
        guard let saveId = tale.saveGameId,
              let save = SaveGameManager.shared.load(id: saveId) else {
            print("The scroll of this adventure has been lost to time...", color: .red)
            return
        }

        SpeechEngine.shared.stop()
        textLongPressHandler = nil
        clearTerminal()

        let heroNames = tale.partyNames.map { $0.components(separatedBy: " ").first ?? $0 }
        let heroList = heroNames.count <= 2
            ? heroNames.joined(separator: " and ")
            : heroNames.dropLast().joined(separator: ", ") + " and " + (heroNames.last ?? "")

        // Dramatic intro
        printLines(asciiSwords, color: .cyan)
        print("")

        switch tale.outcome {
        case .victory:
            printTitle("Reliving a Legend")
            print("")
            printWrapped("The ancient scrolls speak of \(heroList), who once conquered the depths of \(tale.dungeonName)...", indent: 4, color: .yellow)
            print("")
            printWrapped("Now the dungeon stirs again. The torches are relit. The monsters have returned. Can you match the deeds of these legendary heroes?", indent: 4, color: .green)
        case .defeat:
            printTitle("Rewriting History")
            print("")
            printWrapped("The chronicles record a tragedy — \(heroList) fell in the depths of \(tale.dungeonName), one room from their fate...", indent: 4, color: .red)
            print("")
            printWrapped("But the Fates have granted a second chance. The party stands once more, battered but alive, in the room before the fall. This time, perhaps, the story ends differently.", indent: 4, color: .green)
        case nil:
            printTitle("Returning to the Depths")
            print("")
            printWrapped("\(heroList) pause at the threshold of \(tale.dungeonName), gathering their resolve before pressing onward once more...", indent: 4, color: .cyan)
        }

        print("")
        printWrapped("The torches flicker... the dungeon awaits...", indent: 4, color: .dimGreen)
        print("")

        // Narrate if DM voice is on
        if SpeechEngine.shared.isEnabled {
            switch tale.outcome {
            case .victory:
                SpeechEngine.shared.speak("The legends speak of \(heroList). Can you match their deeds in \(tale.dungeonName)?")
            case .defeat:
                SpeechEngine.shared.speak("\(heroList) fell in \(tale.dungeonName). The Fates grant a second chance. Rewrite history.")
            case nil:
                SpeechEngine.shared.speak("Returning to \(tale.dungeonName). The adventure continues.")
            }
        }

        let backToTale: () -> Void = { [weak self] in self?.showAdventureTale(tale) }
        showMenu(["Enter the Dungeon", "?", "< Back"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.loadGame(save)
            case 2:
                self.showInlineHelp {
                    self.printTitle("Enter the Dungeon — Help")
                    self.print("")
                    self.print("  ENTER THE DUNGEON", color: .cyan, bold: true)
                    self.printWrapped("Loads \(heroList)'s save and drops you back into \(tale.dungeonName) right where this save point left off.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  < BACK", color: .cyan, bold: true)
                    self.printWrapped("Doesn't load anything — returns to this adventure's tale.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default:
                backToTale()
            }
        }
        closeHandler = backToTale
    }

    // MARK: - New Game

    func startNewGame() {
        clearAllUndoRedo()
        hasOfferedHallOfFameReturn = false
        clearTerminal()
        printTitle("New Adventure")
        print("How many adventurers in your party?", color: .brightGreen)
        print("")
        print("  Long-press: auto-create party", color: .dimGreen)
        print("  (all AI teammates)", color: .dimGreen)
        if multiplayerEnabled {
            print("")
            print("  Multiplayer: choose Remote Player", color: .cyan)
            print("  right when creating each teammate,", color: .cyan)
            print("  or swap Robot<->Remote afterward in", color: .cyan)
            print("  Party Review or Party Status.", color: .cyan)
        }
        print("")

        showMenuOptions([
            MenuOption("1 Character"), MenuOption("2 Characters"),
            MenuOption("3 Characters"), MenuOption("4 Characters"),
            MenuOption("Random Party"),
            MenuOption("?", tint: .navigation, compact: true),
            MenuOption("< Back", tint: .navigation, compact: true),
        ])

        closeHandler = { [weak self] in
            self?.clearTerminal()
            self?.showPlayMenu()
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 7 {
                self.clearTerminal()
                self.showPlayMenu()
                return
            }
            if choice == 6 {
                self.showNewGameHelp()
                return
            }
            if choice == 5 {
                self.createRandomParty()
                return
            }
            self.totalCharacters = choice
            self.creatingCharacterIndex = 0
            self.party = []
            self.pendingRemoteSlots.removeAll()
            self.explicitlyChosenSlots.removeAll()
            self.isMultiplayer = false
            self.chooseCharacterType()
        }

        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= 4 {
                self.createRandomParty(count: choice, allAI: true)
            }
        }
    }

    /// Pick a name not already used by party members
    private func pickUniqueName() -> String {
        let existingNames = Set(party.map { $0.name.lowercased() })
        let available = suggestedNames.filter { !existingNames.contains($0.lowercased()) }
        return available.randomElement() ?? "Adventurer \(party.count + 1)"
    }

    /// Create a fully random party and present for confirmation.
    /// - preserveExplicit: when true (Party Review's dice/reroll button),
    ///   any slot the player explicitly chose — built by hand or loaded
    ///   from the Character Roster (see explicitlyChosenSlots) — is kept
    ///   exactly as-is; only the auto-generated slots get rerolled. When
    ///   false (the default — Quick Start, Surprise Me, an initial
    ///   multiplayer party), every slot is freshly generated.
    private func createRandomParty(count: Int? = nil, allAI: Bool = false, presetRemote: Bool = false, preserveExplicit: Bool = false) {
        let count = count ?? Int.random(in: 1...4)
        let preserved: [Int: Character] = preserveExplicit
            ? Dictionary(uniqueKeysWithValues: explicitlyChosenSlots.compactMap { i in i < party.count ? (i, party[i]) : nil })
            : [:]
        party = []
        creatingCharacterIndex = 0
        totalCharacters = count
        pendingRemoteSlots.removeAll()

        for i in 0..<count {
            if let keep = preserved[i] {
                party.append(keep)
                continue
            }
            let name = pickUniqueName()
            let race = Race.allCases.randomElement()!
            let charClass = CharacterClass.allCases.randomElement()!

            // Auto scores
            let sorted = AbilityScores.standardArray.sorted(by: >)
            var scores = AbilityScores(strength: 10, dexterity: 10, constitution: 10, intelligence: 10, wisdom: 10, charisma: 10)
            for (idx, ability) in charClass.abilityPriority.enumerated() {
                scores.set(ability, to: sorted[idx])
            }
            // Racial bonuses
            for (ability, bonus) in race.abilityBonuses {
                scores.set(ability, to: scores.score(for: ability) + bonus)
            }

            // First character is always human-controlled
            let isAI = allAI && i > 0
            let character = Character(name: name, race: race, characterClass: charClass, abilityScores: scores, isComputerControlled: isAI)
            if isAI { character.markAsAI() }

            // Skills
            let skills = Array(charClass.skillChoices.shuffled().prefix(charClass.numSkillChoices))
            for skill in skills { character.skillProficiencies.insert(skill) }

            // Gold & equipment
            character.gold = Dice.rollSum(4, d: 4) * 10
            let equipOptions = ItemCatalog.startingEquipmentOptions(for: charClass)
            if let (_, items) = equipOptions.first {
                for item in items { _ = character.addItem(item) }
            }
            autoEquip(character)

            // Spells
            let startingSpells = SpellCatalog.startingSpells(for: charClass)
            if !startingSpells.isEmpty {
                character.knownSpells = startingSpells
                character.spellSlots = SpellCatalog.startingSlots(for: charClass, level: 1)
            }
            if charClass == .barbarian {
                character.rageUsesRemaining = character.rageMaxUses
            }

            party.append(character)
        }

        // For multiplayer new game, pre-set the last AI slot as Remote
        if presetRemote && count >= 2 {
            pendingRemoteSlots.insert(count - 1)
            isMultiplayer = true
        }

        showPartyReview()
    }

    /// Show party roster with options to swap AI/Remote slots before starting
    private func showPartyReview() {
        setBreadcrumb("showPartyReview(party:\(party.count))")
        clearTerminal()
        printTitle("Party Review")

        // "1." is the Name Dungeon / Start Matchmaker button (top-left,
        // default); the adventurers follow from 2 — same numbers as the buttons.
        let startLabel = pendingRemoteSlots.isEmpty ? "Name Dungeon" : "Start Matchmaker"
        print("  1. \(startLabel)", color: .cyan, bold: true)
        printWrapped("Name your dungeon, pick a difficulty, and begin.", indent: 5, color: .dimGreen)
        print("")

        // Display roster with type tags — aligned past the number
        for (i, char) in party.enumerated() {
            let tag: String
            if pendingRemoteSlots.contains(i) {
                tag = " [Remote]"
            } else if char.isComputerControlled {
                tag = " [Auto]"
            } else {
                tag = " [You]"
            }
            let num = "\(i + 2)"
            // "  2. Name [Tag]"  then indented lines aligned under the name (past "1. ")
            let indentCount = 2 + num.count + 2  // "  " + number + ". "
            print("  \(num). \(char.name)\(tag)", color: .brightGreen)
            printWrapped("\(char.race.rawValue) \(char.characterClass.rawValue)", indent: indentCount, color: .dimGreen)
            printWrapped("HP:\(char.maxHP)  AC:\(char.armorClass)  \(char.characterClass.primaryAbility.abbreviation):\(char.abilityScores.score(for: char.characterClass.primaryAbility))", indent: indentCount, color: .dimGreen)
        }
        print("")

        let hasRemote = !pendingRemoteSlots.isEmpty

        // Build menu options
        var opts: [String] = []
        var actions: [() -> Void] = []

        // Start first — the likeliest next step, so it's button 1 (top-left)
        // and the default. "Name Dungeon" says what actually happens next
        // (name it, choose difficulty, then play).
        opts.append(hasRemote ? "Start Matchmaker" : "Name Dungeon")
        actions.append { [weak self] in
            guard let self = self else { return }
            if hasRemote { self.createMultiplayerMatch() } else { self.startAdventure() }
        }

        // Per-character buttons — just the name, clicking shows card
        if party.count >= 1 {
            for (i, char) in party.enumerated() {
                let shortN = shortName(for: char)
                opts.append(shortN)
                actions.append { [weak self] in
                    self?.showCharacterReviewCard(index: i)
                }
            }
        }

        opts.append("?")
        actions.append { [weak self] in self?.showPartyReviewHelp() }

        opts.append("< Back")
        actions.append { [weak self] in
            guard let self = self else { return }
            let wasMultiplayer = !self.pendingRemoteSlots.isEmpty
            self.party = []
            self.pendingRemoteSlots.removeAll()
            if wasMultiplayer { self.showPlayMenu() } else { self.startNewGame() }
        }

        showMenu(opts, defaultIndex: 0)

        closeHandler = { [weak self] in
            guard let self = self else { return }
            let wasMultiplayer = !self.pendingRemoteSlots.isEmpty
            self.party = []
            self.pendingRemoteSlots.removeAll()
            if wasMultiplayer { self.showPlayMenu() } else { self.startNewGame() }
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
        // Long-press character buttons → show character card
        if party.count >= 1 {
            menuLongPressHandler = { [weak self] choice in
                guard let self = self else { return }
                // Button 1 is Name Dungeon; adventurers are 2...
                guard choice >= 2 && choice <= self.party.count + 1 else { return }
                self.showCardForCharacter(named: self.party[choice - 2].name)
            }
        }

        let partyKey = "partyReview"
        // Clear stacks on fresh entry (not when refreshing after undo/redo/reroll)
        if currentUndoScreen != partyKey {
            clearUndoRedo(for: partyKey)
        }
        currentUndoScreen = partyKey

        // Dice icon on input bar — reroll party
        rerollHandler = { [weak self] in
            guard let self = self else { return }
            if let snapshot = try? JSONEncoder().encode(self.party) {
                self.pushScreenUndo(screen: partyKey, data: snapshot)
            }
            let savedRemote = self.pendingRemoteSlots
            let partyCount = self.party.count
            self.createRandomParty(count: partyCount, allAI: true, presetRemote: !savedRemote.isEmpty, preserveExplicit: true)
        }

        // Undo — restore previous party
        undoHandler = screenHasUndo(partyKey) ? { [weak self] in
            guard let self = self else { return }
            if let snapshot = try? JSONEncoder().encode(self.party) {
                self.pushScreenRedo(screen: partyKey, data: snapshot)
            }
            if let prev = self.popScreenUndo(screen: partyKey),
               let restored = try? JSONDecoder().decode([Character].self, from: prev) {
                let names = restored.map { $0.name }.joined(separator: ", ")
                self.party = restored
                self.showUndoFeedback(names)
                self.showPartyReview()
            }
        } : nil

        // Redo — restore next party
        redoHandler = screenHasRedo(partyKey) ? { [weak self] in
            guard let self = self else { return }
            if let snapshot = try? JSONEncoder().encode(self.party) {
                self.pushScreenUndo(screen: partyKey, data: snapshot)
            }
            if let next = self.popScreenRedo(screen: partyKey),
               let restored = try? JSONDecoder().decode([Character].self, from: next) {
                let names = restored.map { $0.name }.joined(separator: ", ")
                self.party = restored
                self.showRedoFeedback(names)
                self.showPartyReview()
            }
        } : nil

        refreshUndoRedoLabels()
    }

    /// Show character card with edit options — dulled if game in progress
    /// Print a card row: "  ║ Label     Value         ║"
    private func printCardRow(_ label: String, _ value: String, width: Int, color: TerminalColor) {
        let inner = " \(label)  \(value)"
        let padCount = max(0, width - inner.count)
        print("  ║\(inner)\(String(repeating: " ", count: padCount))║", color: color)
    }

    private func showCharacterReviewCard(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]
        let inGame = dungeon != nil

        clearTerminal()

        // ── Card border top ──
        let cardWidth = 33
        let border = String(repeating: "═", count: cardWidth)
        print("  ╔\(border)╗", color: .cyan)

        // Show character card art — centred within card
        let artLines = char.characterClass.asciiArt
        let artMax = artLines.map { $0.count }.max() ?? 0
        for line in artLines {
            let pad = max(0, (cardWidth - line.count) / 2)
            let padded = String(repeating: " ", count: pad) + line
            let trailing = max(0, cardWidth - padded.count)
            print("  ║\(padded)\(String(repeating: " ", count: trailing))║", color: .cyan)
        }

        // ── Name bar ──
        let nameLine = " \(char.name) "
        let nameLeft = max(0, (cardWidth - nameLine.count) / 2)
        let nameRight = max(0, cardWidth - nameLine.count - nameLeft)
        print("  ╠\(String(repeating: "─", count: nameLeft))\(nameLine)\(String(repeating: "─", count: nameRight))╣", color: .brightGreen)

        // ── Key identity (highlighted — editable) ──
        let typeStr: String
        if pendingRemoteSlots.contains(index) {
            typeStr = "Remote"
        } else if char.isComputerControlled {
            typeStr = "Auto (Robot)"
        } else {
            typeStr = "Local (You)"
        }
        printCardRow("Type", typeStr, width: cardWidth, color: .yellow)
        printCardRow("Race", char.race.rawValue, width: cardWidth, color: .yellow)
        printCardRow("Class", "\(char.characterClass.rawValue) Lv\(char.level)", width: cardWidth, color: .yellow)

        // ── Stats ──
        let fm: (Int) -> String = { $0 >= 0 ? "+\($0)" : "\($0)" }
        let s = char.abilityScores
        print("  ╟\(String(repeating: "─", count: cardWidth))╢", color: .cyan)
        printCardRow("HP", "\(char.currentHP)/\(char.maxHP)", width: cardWidth, color: .brightGreen)
        printCardRow("AC", "\(char.armorClass)", width: cardWidth, color: .brightGreen)
        printCardRow("Gold", "\(char.gold)", width: cardWidth, color: .dimGreen)
        printCardRow("XP", "\(char.experiencePoints)", width: cardWidth, color: .dimGreen)

        // ── Ability scores (highlighted — editable) ──
        print("  ╟\(String(repeating: "─", count: cardWidth))╢", color: .cyan)
        printCardRow("STR", "\(s.strength) (\(fm(s.modifier(for: .strength))))", width: cardWidth, color: .yellow)
        printCardRow("DEX", "\(s.dexterity) (\(fm(s.modifier(for: .dexterity))))", width: cardWidth, color: .yellow)
        printCardRow("CON", "\(s.constitution) (\(fm(s.modifier(for: .constitution))))", width: cardWidth, color: .yellow)
        printCardRow("INT", "\(s.intelligence) (\(fm(s.modifier(for: .intelligence))))", width: cardWidth, color: .yellow)
        printCardRow("WIS", "\(s.wisdom) (\(fm(s.modifier(for: .wisdom))))", width: cardWidth, color: .yellow)
        printCardRow("CHA", "\(s.charisma) (\(fm(s.modifier(for: .charisma))))", width: cardWidth, color: .yellow)

        // ── Equipment ──
        print("  ╟\(String(repeating: "─", count: cardWidth))╢", color: .cyan)
        if let w = char.equippedWeapon { printCardRow("Weapon", w.name, width: cardWidth, color: .cyan) }
        else { printCardRow("Weapon", "—", width: cardWidth, color: .gray) }
        if let a = char.equippedArmor { printCardRow("Armour", a.name, width: cardWidth, color: .cyan) }
        else { printCardRow("Armour", "—", width: cardWidth, color: .gray) }
        if let sh = char.equippedShield { printCardRow("Shield", sh.name, width: cardWidth, color: .cyan) }

        // ── Skills (highlighted — editable) ──
        if !char.skillProficiencies.isEmpty {
            print("  ╟\(String(repeating: "─", count: cardWidth))╢", color: .cyan)
            let skills = char.skillProficiencies.map { $0.rawValue }.sorted()
            for skill in skills {
                printCardRow("✓", skill, width: cardWidth, color: .yellow)
            }
        }

        // ── Spells ──
        if !char.knownSpells.isEmpty {
            print("  ╟\(String(repeating: "─", count: cardWidth))╢", color: .cyan)
            let spellNames = char.knownSpells.prefix(4).map { $0.name }
            for spell in spellNames {
                printCardRow("✦", spell, width: cardWidth, color: .magenta)
            }
            if char.knownSpells.count > 4 {
                printCardRow("", "+\(char.knownSpells.count - 4) more", width: cardWidth, color: .gray)
            }
        }

        // ── Pack ──
        if !char.inventory.isEmpty {
            print("  ╟\(String(repeating: "─", count: cardWidth))╢", color: .cyan)
            printCardRow("Pack", formatWeightPair(char.currentWeight, char.carryCapacity), width: cardWidth, color: .dimGreen)
        }

        // ── Reputation (Glyphkeeper) ──
        print("  ╟\(String(repeating: "─", count: cardWidth))╢", color: .cyan)
        let alignmentColor: TerminalColor
        switch char.ethicalAlignment {
        case .heroic: alignmentColor = .brightGreen
        case .kind: alignmentColor = .cyan
        case .neutral: alignmentColor = .dimGreen
        case .selfish: alignmentColor = .yellow
        case .villainous: alignmentColor = .red
        }
        printCardRow("Reputation", "\(char.ethicalAlignment.rawValue) (\(char.ethicalScore))", width: cardWidth, color: alignmentColor)

        // ── Card border bottom ──
        print("  ╚\(border)╝", color: .cyan)
        print("")

        // Mid-adventure warning
        if inGame {
            let warnings = [
                "Best not to change horses midstream...",
                "A wise adventurer plays the hand they're dealt.",
                "Changing now could upset the balance of the party.",
                "The dungeon is no place for second thoughts.",
                "Your companions may not take kindly to sudden changes.",
            ]
            printWrapped(warnings.randomElement()!, indent: 2, color: .yellow)
            printWrapped("The DM advises against changing these mid-adventure, so they're greyed out below — but you can go against that advice: long-press a greyed-out button to change it anyway.", indent: 2, color: .dimGreen)
            print("")
        }

        // Build edit options — disabled if in-game
        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        menuOpts.append(MenuOption("Change Name", isDisabled: inGame))
        actions.append { [weak self] in self?.showChangeName(index: index) }

        // Change Type/Race/Class/Voice are shared with showEditCharacter
        // (Party Status's own edit hub) and hardcode returning there when
        // done — set characterReviewReturnOverride first so "back" from
        // one of them returns HERE instead (see returnFromCharacterEditSubscreen).
        let returnHere: () -> Void = { [weak self] in self?.characterReviewReturnOverride = { [weak self] in self?.showCharacterReviewCard(index: index) } }

        // Only show Change Type when there are multiple party members
        if party.count > 1 {
            menuOpts.append(MenuOption("Change Type", isDisabled: inGame))
            actions.append { [weak self] in returnHere(); self?.showChangePlayerType(index: index) }
        }

        menuOpts.append(MenuOption("Change Race", isDisabled: inGame))
        actions.append { [weak self] in returnHere(); self?.showChangeRace(index: index) }

        menuOpts.append(MenuOption("Change Class", isDisabled: inGame))
        actions.append { [weak self] in returnHere(); self?.showChangeClass(index: index) }

        menuOpts.append(MenuOption("Change Scores", isDisabled: inGame))
        actions.append { [weak self] in self?.showEditAbilityScores(index: index) }

        menuOpts.append(MenuOption("Change Skills", isDisabled: inGame))
        actions.append { [weak self] in self?.showEditSkills(index: index) }

        menuOpts.append(MenuOption("Change Voice", isDisabled: inGame))
        actions.append { [weak self] in returnHere(); self?.showCharacterVoiceEdit(index: index) }

        menuOpts.append(MenuOption("Reputation", tint: .cyan))
        actions.append { [weak self] in self?.showReputationLog(index: index) }

        // Not disabled in-game — saving/loading roster progress mid-adventure
        // is safe and is exactly when you'd want to (e.g. after a level-up).
        menuOpts.append(MenuOption("Roster", tint: .cyan))
        actions.append { [weak self] in self?.showRosterMenu(index: index) }

        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showCharacterReviewCardHelp(index: index, inGame: inGame) }

        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        actions.append { [weak self] in
            guard let self = self else { return }
            if let override = self.characterReviewReturnOverride {
                self.characterReviewReturnOverride = nil
                override()
            } else {
                self.showPartyReview()
            }
        }

        showMenuOptions(menuOpts)

        closeHandler = { [weak self] in
            guard let self = self else { return }
            if let override = self.characterReviewReturnOverride {
                self.characterReviewReturnOverride = nil
                override()
            } else {
                self.showPartyReview()
            }
        }
        menuHandler = { [weak self] choice in
            guard choice > 0 && choice <= actions.count else { return }
            // Block disabled buttons on normal tap
            if menuOpts[choice - 1].isDisabled { return }
            actions[choice - 1]()
        }
        // Long-press bypasses disabled state for in-game edits
        menuLongPressHandler = { choice in
            guard choice > 0 && choice <= actions.count else { return }
            actions[choice - 1]()
        }
    }

    /// Glyphkeeper's visible face — shows a character's current reputation
    /// band/score and the log of what shifted it, most recent first. Read
    /// by the AI DM too (see buildDMContext's partyStatus line) so NPC
    /// reactions and narration stay consistent with this over a long campaign.
    private func showReputationLog(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]
        clearTerminal()
        printTitle("\(char.name)'s Reputation")
        print("")
        let alignmentColor: TerminalColor
        switch char.ethicalAlignment {
        case .heroic: alignmentColor = .brightGreen
        case .kind: alignmentColor = .cyan
        case .neutral: alignmentColor = .dimGreen
        case .selfish: alignmentColor = .yellow
        case .villainous: alignmentColor = .red
        }
        print("  \(char.ethicalAlignment.rawValue) (\(char.ethicalScore))", color: alignmentColor, bold: true)
        printWrapped(char.ethicalAlignment.summary, indent: 2, color: .dimGreen)
        print("")
        printWrapped("This is a look-up, not something you can set directly — it's earned (or lost) through what this character actually does in the story, tracked in the log below.", indent: 2, color: .yellow)
        print("")
        if char.ethicalLog.isEmpty {
            printWrapped("No notable choices tracked yet this campaign.", indent: 2, color: .dimGreen)
        } else {
            print("  RECENT (most recent first):", color: .cyan, bold: true)
            for entry in char.ethicalLog {
                print("  \(entry)", color: .dimGreen)
            }
        }
        print("")
        showMenu(["?", "< Back"])
        closeHandler = { [weak self] in self?.showCharacterReviewCard(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.showInlineHelp {
                    self.printTitle("Reputation — Help")
                    self.print("")
                    self.printWrapped("Glyphkeeper tracks a running ethical score (-100 Villainous to +100 Heroic) for each character, shifted by certain choices during the campaign. You can't set it directly — it's a record of what this character has actually done, not a stat to edit.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  WHY IT MATTERS", color: .cyan, bold: true)
                    self.printWrapped("A better reputation gets you easier haggling and warmer narration/NPC reactions from the DM. A worse one makes both harder — merchants charge more, and the story treats you accordingly. A party with a collective reputation of Kind or better also becomes eligible for Emergency Drop — a rare, one-time-per-adventure chance to survive what would otherwise be a total party wipe.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  WHERE IT'S USED", color: .cyan, bold: true)
                    self.printWrapped("The AI DM sees each character's reputation band and lets it colour narration and NPC reactions. Merchants also react to it directly — a good reputation makes haggling easier, a bad one makes it harder (see the DC note shown when you haggle).", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  THE LOG", color: .cyan, bold: true)
                    self.printWrapped("Keeps the most recent 20 shifts so you can see exactly what's shaped your character's standing.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else {
                self.showCharacterReviewCard(index: index)
            }
        }
    }

    private func showCharacterReviewCardHelp(index: Int, inGame: Bool) {
        showInlineHelp {
            self.printTitle("Character Review Help")
            self.print("")
            self.printWrapped("Tap a character's name to view their card and edit options.", indent: 2, color: .green)
            self.print("")
            if inGame {
                self.printWrapped("Your adventure is underway! Edit buttons are greyed out to prevent accidental changes. If you really need to make a change, long-press the button to override.", indent: 2, color: .yellow)
                self.print("")
            }
            self.printWrapped("Change Name: Rename this character.", indent: 2, color: .dimGreen)
            self.printWrapped("Change Type: Switch between Local (you control), Auto (robot), or Remote (multiplayer) control.", indent: 2, color: .dimGreen)
            self.printWrapped("Change Race: Change the character's race (Elf, Dwarf, etc.).", indent: 2, color: .dimGreen)
            self.printWrapped("Change Class: Change the character's class (Fighter, Wizard, etc.).", indent: 2, color: .dimGreen)
            self.printWrapped("Change Scores: Reassign ability scores (STR, DEX, CON, INT, WIS, CHA) using the standard array.", indent: 2, color: .dimGreen)
            self.printWrapped("Change Skills: Choose new skill proficiencies from your class list.", indent: 2, color: .dimGreen)
            self.printWrapped("Change Voice: Customise the character's speech voice.", indent: 2, color: .dimGreen)
            self.printWrapped("Roster: Save this character's progress to your Character Roster, or load saved details back onto them — the whole character, or just one part (race/class, ability scores, or skills).", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    // MARK: - Character Roster (Save/Load, Party Review)

    private enum RosterLoadCategory: CaseIterable {
        case all, raceClass, abilityScores, skills, name

        var label: String {
            switch self {
            case .all: return "Load All"
            case .raceClass: return "Race & Class only"
            case .abilityScores: return "Ability Scores only"
            case .skills: return "Skills only"
            case .name: return "Name only"
            }
        }

        /// Phrase for the "Loaded ___ from X onto Y" confirmation line.
        var confirmationPhrase: String {
            switch self {
            case .all: return "everything"
            case .raceClass: return "race & class"
            case .abilityScores: return "ability scores"
            case .skills: return "skills"
            case .name: return "the name"
            }
        }
    }

    private func showRosterMenu(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]

        clearTerminal()
        printTitle("Character Roster")
        print("")
        print("  \(char.name) — Level \(char.level) \(char.race.rawValue) \(char.characterClass.rawValue)", color: .cyan)
        print("")
        printWrapped("Save this character's current progress to your roster, or load saved details back onto them from a roster character.", indent: 2, color: .dimGreen)
        print("")

        showPaginatedMenu(["Save to Roster", "Load from Roster"], pinned: ["?", "< Back"], pinnedHandler: { [weak self] pIdx in
            guard let self = self else { return }
            if pIdx == 0 {
                self.showRosterMenuHelp(index: index)
            } else {
                self.showCharacterReviewCard(index: index)
            }
        }, handler: { [weak self] idx in
            guard let self = self else { return }
            if idx == 0 {
                self.saveCharacterToRoster(char)
                self.print("")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showRosterMenu(index: index) }
            } else {
                self.showRosterLoadPicker(index: index)
            }
        })
        closeHandler = { [weak self] in self?.showCharacterReviewCard(index: index) }
    }

    private func showRosterMenuHelp(index: Int) {
        showInlineHelp {
            self.printTitle("Character Roster — Help")
            self.print("")
            self.printWrapped("Save to Roster: store this character's current level, gear, and gold so a future adventure can start with them again.", indent: 2, color: .dimGreen)
            self.print("")
            self.printWrapped("Load from Roster: pick a character you've previously saved, then choose how much of it to copy onto this one — everything, or just race/class, ability scores, skills, or name. \"Load All\" asks separately whether to also take the name — everything else about this character not covered by your choice is left as-is.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    private func showRosterLoadPicker(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        let records = CharacterLibraryManager.shared.listCharacters()

        clearTerminal()
        printTitle("Load from Roster")
        print("")

        guard !records.isEmpty else {
            printWrapped("Your Character Roster is empty — nothing saved yet.", indent: 2, color: .yellow)
            print("")
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showRosterMenu(index: index) }
            closeHandler = { [weak self] in self?.showRosterMenu(index: index) }
            return
        }

        printWrapped("Choose a saved character to load from:", indent: 2, color: .dimGreen)
        print("")

        let opts = records.map { "\($0.character.name) — L\($0.character.level) \($0.character.race.rawValue) \($0.character.characterClass.rawValue)" }
        showPaginatedMenu(opts, pinned: ["?", "< Back"], pinnedHandler: { [weak self] pIdx in
            guard let self = self else { return }
            if pIdx == 0 {
                self.showRosterMenuHelp(index: index)
            } else {
                self.showRosterMenu(index: index)
            }
        }, handler: { [weak self] idx in
            guard let self = self, idx < records.count else { return }
            self.showRosterLoadCategoryPicker(index: index, source: records[idx].character)
        })
        closeHandler = { [weak self] in self?.showRosterMenu(index: index) }
    }

    private func showRosterLoadCategoryPicker(index: Int, source: Character) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]

        clearTerminal()
        printTitle("Load from \(source.name)")
        print("")
        print("  Onto: \(char.name)", color: .cyan)
        print("")
        printWrapped("What should be loaded? \"Load All\" is usually what you want — the others let you take just one part (e.g. only the ability scores) and leave the rest of \(char.name) alone.", indent: 2, color: .dimGreen)
        print("")

        let opts = RosterLoadCategory.allCases.map { $0.label }
        showPaginatedMenu(opts, pinned: ["?", "< Back"], pinnedHandler: { [weak self] pIdx in
            guard let self = self else { return }
            if pIdx == 0 {
                self.showRosterMenuHelp(index: index)
            } else {
                self.showRosterLoadPicker(index: index)
            }
        }, handler: { [weak self] idx in
            guard let self = self, idx < RosterLoadCategory.allCases.count else { return }
            let category = RosterLoadCategory.allCases[idx]
            if category == .all {
                // "Load All" doesn't say what to do about the name up
                // front — ask, rather than silently keeping or overwriting it.
                self.showRosterLoadNamePrompt(index: index, source: source)
            } else {
                self.applyRosterLoad(source: source, into: char, category: category)
                self.showRosterLoadConfirmation(index: index, sourceName: source.name, category: category)
            }
        })
        closeHandler = { [weak self] in self?.showRosterLoadPicker(index: index) }
    }

    private func showRosterLoadNamePrompt(index: Int, source: Character) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]

        clearTerminal()
        printTitle("Load All from \(source.name)")
        print("")
        printWrapped("This copies everything from \(source.name) onto \(char.name) — level, gear, scores, skills, the works.", indent: 2, color: .dimGreen)
        print("")
        printWrapped("Also use \(source.name)'s name, or keep \(char.name)?", indent: 2, color: .cyan)
        print("")

        showMenu(["Use \"\(source.name)\"", "Keep \"\(char.name)\"", "?", "< Back"])
        closeHandler = { [weak self] in self?.showRosterLoadCategoryPicker(index: index, source: source) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.applyRosterLoad(source: source, into: char, category: .all, includeName: true)
                self.showRosterLoadConfirmation(index: index, sourceName: source.name, category: .all, includeName: true)
            case 2:
                self.applyRosterLoad(source: source, into: char, category: .all, includeName: false)
                self.showRosterLoadConfirmation(index: index, sourceName: source.name, category: .all, includeName: false)
            case 3:
                self.showRosterMenuHelp(index: index)
            default:
                self.showRosterLoadCategoryPicker(index: index, source: source)
            }
        }
    }

    private func applyRosterLoad(source: Character, into char: Character, category: RosterLoadCategory, includeName: Bool = false) {
        if includeName {
            char.name = uniqueName(source.name, excluding: char.id)
        }
        switch category {
        case .all:
            char.race = source.race
            char.characterClass = source.characterClass
            char.abilityScores = source.abilityScores
            char.skillProficiencies = source.skillProficiencies
            char.level = source.level
            char.maxHP = source.maxHP
            char.currentHP = source.currentHP
            char.tempHP = source.tempHP
            char.experiencePoints = source.experiencePoints
            char.gold = source.gold
            char.inventory = source.inventory
            char.equippedWeapon = source.equippedWeapon
            char.equippedArmor = source.equippedArmor
            char.equippedShield = source.equippedShield
            char.knownSpells = source.knownSpells
            char.spellSlots = source.spellSlots
        case .raceClass:
            char.race = source.race
            char.characterClass = source.characterClass
        case .abilityScores:
            char.abilityScores = source.abilityScores
        case .skills:
            char.skillProficiencies = source.skillProficiencies
        case .name:
            char.name = uniqueName(source.name, excluding: char.id)
        }
        char.syncRobotPrefix()
    }

    private func showRosterLoadConfirmation(index: Int, sourceName: String, category: RosterLoadCategory, includeName: Bool = false) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]

        clearTerminal()
        printTitle("Roster Load Complete")
        print("")
        let nameNote = (category == .all && includeName) ? " (including the name)" : ""
        print("  Loaded \(category.confirmationPhrase) from \(sourceName) onto \(char.name)\(nameNote).", color: .brightGreen)
        print("")
        printLines(char.displaySheet())
        print("")

        showMenu(["Continue"])
        menuHandler = { [weak self] _ in self?.showCharacterReviewCard(index: index) }
        closeHandler = { [weak self] in self?.showCharacterReviewCard(index: index) }
    }

    // MARK: - Edit Ability Scores (Party Review)

    /// Let the player reassign ability scores using the standard array
    private func showEditAbilityScores(index: Int) {
        guard index < party.count else { showCharacterReviewCard(index: index); return }
        let char = party[index]

        // Start edit tracking if not already
        if editingCharacterIndex != index {
            beginEditTracking(index: index, inGame: false)
        }

        clearTerminal()
        printTitle("Edit Ability Scores — \(shortName(for: char))")

        // Show current scores
        let fm: (Int) -> String = { $0 >= 0 ? "+\($0)" : "\($0)" }
        let s = char.abilityScores
        print("  Current Scores:", color: .cyan, bold: true)
        for ability in Ability.allCases {
            let score = s.score(for: ability)
            let mod = s.modifier(for: ability)
            let isPrimary = ability == char.characterClass.primaryAbility
            let marker = isPrimary ? " (Primary)" : ""
            print("    \(ability.abbreviation): \(score) (\(fm(mod)))\(marker)", color: isPrimary ? .brightGreen : .green)
        }
        print("")

        // Remove racial bonuses to get base scores, then sort for reassignment
        var baseScores: [Int] = []
        for ability in Ability.allCases {
            let racialBonus = char.race.abilityBonuses.first(where: { $0.0 == ability })?.1 ?? 0
            baseScores.append(s.score(for: ability) - racialBonus)
        }
        let sorted = baseScores.sorted(by: >)

        printWrapped("Reassign the standard array (\(sorted.map { String($0) }.joined(separator: ", "))) to abilities. Racial bonuses are applied automatically.", indent: 2, color: .dimGreen)
        print("")

        showMenu(["Auto (Optimal)", "Manual Assign", "< Back"])
        closeHandler = { [weak self] in
            self?.endEditTracking()
            self?.showCharacterReviewCard(index: index)
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.pushEditSnapshot(index: index)
                self.autoReassignScores(index: index)
                self.showCharacterReviewCard(index: index)
            case 2:
                self.pushEditSnapshot(index: index)
                self.manualReassignScores(index: index, remaining: sorted, abilities: Array(Ability.allCases))
            default:
                self.endEditTracking()
                self.showCharacterReviewCard(index: index)
            }
        }
    }

    /// Auto-assign scores optimally for the character's class
    private func autoReassignScores(index: Int) {
        guard index < party.count else { return }
        let char = party[index]
        let sorted = AbilityScores.standardArray.sorted(by: >)
        let priority = char.characterClass.abilityPriority

        for (i, ability) in priority.enumerated() {
            char.abilityScores.set(ability, to: sorted[i])
        }
        // Re-apply racial bonuses
        for (ability, bonus) in char.race.abilityBonuses {
            let current = char.abilityScores.score(for: ability)
            char.abilityScores.set(ability, to: current + bonus)
        }
        char.recalculateMaxHP()
    }

    /// Step through each ability and let the player pick a score
    private func manualReassignScores(index: Int, remaining: [Int], abilities: [Ability]) {
        guard index < party.count else { showCharacterReviewCard(index: index); return }
        let char = party[index]

        if abilities.isEmpty {
            // Done — apply racial bonuses
            for (ability, bonus) in char.race.abilityBonuses {
                let current = char.abilityScores.score(for: ability)
                char.abilityScores.set(ability, to: current + bonus)
            }
            char.recalculateMaxHP()

            clearTerminal()
            printTitle("Scores Updated")
            let fm: (Int) -> String = { $0 >= 0 ? "+\($0)" : "\($0)" }
            for ability in Ability.allCases {
                let score = char.abilityScores.score(for: ability)
                let isPrimary = ability == char.characterClass.primaryAbility
                print("  \(ability.abbreviation): \(score) (\(fm(char.abilityScores.modifier(for: ability))))\(isPrimary ? " *" : "")", color: isPrimary ? .brightGreen : .green)
            }
            print("")

            showMenu(["Confirm"])
            closeHandler = { [weak self] in self?.showCharacterReviewCard(index: index) }
            menuHandler = { [weak self] _ in
                self?.endEditTracking()
                self?.showCharacterReviewCard(index: index)
            }
            return
        }

        let ability = abilities[0]
        let isPrimary = ability == char.characterClass.primaryAbility

        clearTerminal()
        printTitle("Assign Score — \(ability.rawValue)")
        if isPrimary {
            print("  This is \(char.characterClass.rawValue)'s primary ability!", color: .brightGreen)
        }
        print("  Remaining: \(remaining.map { String($0) }.joined(separator: ", "))", color: .cyan)
        print("")

        let opts = remaining.map { String($0) }
        // Default to the highest score
        showMenu(opts)

        closeHandler = { [weak self] in
            self?.endEditTracking()
            self?.showCharacterReviewCard(index: index)
        }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1 && choice <= remaining.count else { return }
            let score = remaining[choice - 1]
            char.abilityScores.set(ability, to: score)
            var newRemaining = remaining
            newRemaining.remove(at: choice - 1)
            self.manualReassignScores(index: index, remaining: newRemaining, abilities: Array(abilities.dropFirst()))
        }
    }

    // MARK: - Edit Skills (Party Review)

    /// Let the player choose new skill proficiencies
    private func showEditSkills(index: Int) {
        guard index < party.count else { showCharacterReviewCard(index: index); return }
        let char = party[index]

        // Start edit tracking if not already
        if editingCharacterIndex != index {
            beginEditTracking(index: index, inGame: false)
        }
        pushEditSnapshot(index: index)

        clearTerminal()
        printTitle("Edit Skills — \(shortName(for: char))")

        let currentSkills = char.skillProficiencies.map { $0.rawValue }.sorted().joined(separator: ", ")
        print("  Current: \(currentSkills)", color: .cyan)
        print("")

        let available = char.characterClass.skillChoices
        let numChoices = char.characterClass.numSkillChoices
        printWrapped("Choose \(numChoices) skills from your class list. Current selections are cleared.", indent: 2, color: .dimGreen)
        print("")

        // Clear current skills and start selection
        char.skillProficiencies.removeAll()
        pickNextSkill(index: index, available: available, remaining: numChoices)
    }

    /// Recursive skill picker for party review edit
    private func pickNextSkill(index: Int, available: [Skill], remaining: Int) {
        guard index < party.count else { showCharacterReviewCard(index: index); return }
        let char = party[index]

        if remaining == 0 {
            // Done — show confirmation
            clearTerminal()
            printTitle("Skills Updated")
            let skillList = char.skillProficiencies.map { $0.rawValue }.sorted().joined(separator: ", ")
            print("  \(skillList)", color: .brightGreen)
            print("")

            showMenu(["Confirm"])
            closeHandler = { [weak self] in self?.showCharacterReviewCard(index: index) }
            menuHandler = { [weak self] _ in
                self?.endEditTracking()
                self?.showCharacterReviewCard(index: index)
            }
            return
        }

        clearTerminal()
        printTitle("Choose Skill (\(char.characterClass.numSkillChoices - remaining + 1)/\(char.characterClass.numSkillChoices))")
        if !char.skillProficiencies.isEmpty {
            let chosen = char.skillProficiencies.map { $0.rawValue }.sorted().joined(separator: ", ")
            print("  Chosen: \(chosen)", color: .brightGreen)
            print("")
        }

        // Filter out already-chosen skills
        let choices = available.filter { !char.skillProficiencies.contains($0) }
        let opts = choices.map { "\($0.rawValue) (\($0.ability.abbreviation))" }

        showMenu(opts)
        closeHandler = { [weak self] in
            self?.endEditTracking()
            self?.showCharacterReviewCard(index: index)
        }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1 && choice <= choices.count else { return }
            char.skillProficiencies.insert(choices[choice - 1])
            self.pickNextSkill(index: index, available: available, remaining: remaining - 1)
        }
    }

    private func showEditCharacter(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]
        clearTerminal()

        // Start edit tracking if not already tracking this character
        if editingCharacterIndex != index {
            beginEditTracking(index: index, inGame: false)
        }

        printTitle("Edit — \(char.name)")

        // Show current details
        printLines(char.characterClass.asciiArt, color: .cyan)
        print("")
        let typeStr: String
        if pendingRemoteSlots.contains(index) {
            typeStr = "Remote"
        } else if char.isComputerControlled {
            typeStr = "Auto (Robot)"
        } else {
            typeStr = "Local (You)"
        }
        print("  Type:  \(typeStr)", color: .yellow)
        print("  Race:  \(char.race.rawValue)", color: .green)
        print("  Class: \(char.characterClass.rawValue)", color: .green)
        print("  HP:\(char.maxHP) AC:\(char.armorClass)", color: .dimGreen)
        print("")

        var opts: [String] = []
        var actions: [() -> Void] = []

        // Player type options
        opts.append("Change Type")
        actions.append { [weak self] in
            self?.showChangePlayerType(index: index)
        }

        // Change race
        opts.append("Change Race")
        actions.append { [weak self] in
            self?.showChangeRace(index: index)
        }

        // Change class
        opts.append("Change Class")
        actions.append { [weak self] in
            self?.showChangeClass(index: index)
        }

        // Change voice
        opts.append("Change Voice")
        actions.append { [weak self] in
            self?.showCharacterVoiceEdit(index: index)
        }

        // View card
        opts.append("View Card")
        actions.append { [weak self] in
            self?.showCharacterCardFromEdit(index: index)
        }

        // Help
        opts.append("?")
        actions.append { [weak self] in
            self?.showEditCharacterHelp(index: index)
        }

        opts.append("< Back")
        actions.append { [weak self] in
            self?.endEditTracking()
            self?.showPartyReview()
        }

        showMenu(opts)

        // Restore undo/redo handlers
        updateUndoRedoHandlers(index: index)

        closeHandler = { [weak self] in
            self?.endEditTracking()
            self?.showPartyReview()
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

