    private func showChangePlayerType(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]
        let hasHumanElsewhere = party.enumerated().contains(where: { $0.offset != index && !$0.element.isComputerControlled && !pendingRemoteSlots.contains($0.offset) })

        clearTerminal()
        printTitle("Player Type — \(shortName(for: char))")
        let currentType: String
        if pendingRemoteSlots.contains(index) { currentType = "Remote" }
        else if char.isComputerControlled { currentType = "Auto (Robot)" }
        else { currentType = "Local (You)" }
        print("  Current: \(currentType)", color: .yellow)

        // The party always needs at least one Local (human-controlled)
        // member. If this IS that member, offering Robot/Remote anyway
        // would silently let the party end up with none — instead of
        // hiding them with no explanation, say why and offer to hand
        // Local to someone else first.
        if currentType == "Local (You)" && !hasHumanElsewhere && party.count > 1 {
            print("")
            printWrapped("\(char.name) is your party's only Local character — at least one must stay Local. Set someone else Local first if you want to change this one.", indent: 2, color: .yellow)
            print("")
            showMenu(["Set Someone Else Local", "?", "< Back"])
            closeHandler = { [weak self] in self?.returnFromCharacterEditSubscreen(index: index) }
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                switch choice {
                case 1: self.showSwapLocalPicker(returnToIndex: index)
                case 2: self.showEditCharacterHelp(index: index)
                default: self.returnFromCharacterEditSubscreen(index: index)
                }
            }
            return
        }

        print("  Who controls this character?", color: .cyan)
        print("")

        var opts: [String] = []
        var typeLabels: [String] = []

        // Local (human) option
        opts.append("Local (You)")
        typeLabels.append("Local (You)")

        // Auto (robot) option — only if another human player exists to maintain control
        if party.count > 1 && hasHumanElsewhere {
            opts.append("Auto (Robot)")
            typeLabels.append("Auto (Robot)")
        }

        // Remote option — only offered while Multiplayer is actually
        // switched on in Settings; without it, Remote isn't a real choice
        // no matter how many other Local members exist.
        let gcAuth = multiplayerEnabled && GameCenterManager.shared.isAuthenticated && party.count >= 2
        if gcAuth && hasHumanElsewhere {
            opts.append("Remote Player")
            typeLabels.append("Remote Player")
        }

        opts.append("?")
        opts.append("< Back")
        showMenu(opts)

        closeHandler = { [weak self] in self?.returnFromCharacterEditSubscreen(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == opts.count {
                self.returnFromCharacterEditSubscreen(index: index)
                return
            }
            if choice == opts.count - 1 {
                self.showEditCharacterHelp(index: index)
                return
            }
            guard choice > 0 && choice <= typeLabels.count else { return }
            let newType = typeLabels[choice - 1]
            // No change? Go back
            if newType == currentType {
                self.returnFromCharacterEditSubscreen(index: index)
                return
            }
            self.confirmChangeType(index: index, newType: newType, currentType: currentType)
        }
    }

    /// Reached only when the character at `returnToIndex` is the party's
    /// sole Local member and the player wants to change it to something
    /// else — hand Local to a different party member first, then return to
    /// finish the original change now that it's actually possible.
    private func showSwapLocalPicker(returnToIndex: Int) {
        guard returnToIndex < party.count else { showPartyReview(); return }
        let others = party.enumerated().filter { $0.offset != returnToIndex }

        clearTerminal()
        printTitle("Set Someone Else Local")
        print("")
        printWrapped("Pick who becomes Local (human-controlled) instead:", indent: 2, color: .dimGreen)
        print("")

        let opts = others.map { offset, c -> String in
            let tag = pendingRemoteSlots.contains(offset) ? "Remote" : (c.isComputerControlled ? "Robot" : "Local")
            return "\(c.name) (\(tag))"
        }
        showMenu(opts + ["?", "< Back"])
        closeHandler = { [weak self] in self?.showChangePlayerType(index: returnToIndex) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= others.count {
                let (offset, chosen) = others[choice - 1]
                self.pushEditSnapshot(index: offset)
                self.pendingRemoteSlots.remove(offset)
                chosen.unmarkAsAI()
                if self.pendingRemoteSlots.isEmpty { self.isMultiplayer = false }
                self.showChangePlayerType(index: returnToIndex)
            } else if choice == others.count + 1 {
                self.showEditCharacterHelp(index: returnToIndex)
            } else {
                self.showChangePlayerType(index: returnToIndex)
            }
        }
    }

    private func confirmChangeType(index: Int, newType: String, currentType: String) {
        let char = party[index]
        clearTerminal()
        printTitle("Confirm Type Change")
        print("")
        print("  \(shortName(for: char)): \(currentType) → \(newType)", color: .yellow, bold: true)
        print("")

        print("  WHAT CHANGES:", color: .cyan, bold: true)
        switch newType {
        case "Local (You)":
            printWrapped("You will control \(char.name) directly — choosing actions in combat and exploration.", indent: 2, color: .dimGreen)
        case "Auto (Robot)":
            printWrapped("\(char.name) will act on their own — the robot makes combat and exploration choices automatically.", indent: 2, color: .dimGreen)
        case "Remote Player":
            printWrapped("Another player will control \(char.name) via Game Centre multiplayer.", indent: 2, color: .dimGreen)
        default: break
        }
        print("")

        showMenu(["Confirm", "< Back"])
        closeHandler = { [weak self] in self?.showChangePlayerType(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.pushEditSnapshot(index: index)
                switch newType {
                case "Local (You)":
                    self.pendingRemoteSlots.remove(index)
                    self.party[index].unmarkAsAI()
                    if self.pendingRemoteSlots.isEmpty { self.isMultiplayer = false }
                case "Auto (Robot)":
                    self.pendingRemoteSlots.remove(index)
                    self.party[index].markAsAI()
                    if self.pendingRemoteSlots.isEmpty { self.isMultiplayer = false }
                case "Remote Player":
                    self.party[index].unmarkAsAI()
                    self.pendingRemoteSlots.insert(index)
                    self.isMultiplayer = true
                default: break
                }
            }
            self.returnFromCharacterEditSubscreen(index: index)
        }
    }

    /// Party members' current names, lowercased, for duplicate checks —
    /// excluding the given character itself (so renaming to the same name
    /// it already has, or reassigning a name during a roster load, doesn't
    /// false-positive against itself).
    private func otherPartyNames(excluding charId: UUID) -> Set<String> {
        Set(party.filter { $0.id != charId }.map { $0.name.lowercased() })
    }

    /// Deduplicates `name` against other party members (excluding the
    /// character keeping id `charId`) by appending " (2)", " (3)", etc. —
    /// same pattern used when loading a roster character into a fresh slot.
    private func uniqueName(_ name: String, excluding charId: UUID) -> String {
        let existing = otherPartyNames(excluding: charId)
        guard existing.contains(name.lowercased()) else { return name }
        var suffix = 2
        var candidate = "\(name) (\(suffix))"
        while existing.contains(candidate.lowercased()) {
            suffix += 1
            candidate = "\(name) (\(suffix))"
        }
        return candidate
    }

    private func showChangeName(index: Int, error: String? = nil) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]

        if editingCharacterIndex != index {
            beginEditTracking(index: index, inGame: false)
        }

        clearTerminal()
        printTitle("Change Name — \(char.name)")
        print("")
        if let error = error {
            print("  \(error)", color: .yellow)
            print("")
        }

        // Show suggestions as buttons — same pattern as the in-game Change
        // Name screen (showInGameChangeName), just wired to this screen's
        // own validation/callbacks.
        let existingNames = Set(party.map { $0.name.lowercased() })
        let available = suggestedNames.filter { !existingNames.contains($0.lowercased()) }
        let suggestionList = Array(available.shuffled().prefix(4))

        print("  Type a name, or pick a suggestion:", color: .dimGreen)
        print("")

        var menuOpts = suggestionList.map { String($0) }
        menuOpts.append("< Back")

        promptTextWithMenu("", options: menuOpts)
        closeHandler = { [weak self] in
            self?.endEditTracking()
            self?.showCharacterReviewCard(index: index)
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= suggestionList.count {
                self.applyChangedName(index: index, newName: suggestionList[choice - 1])
            } else {
                self.endEditTracking()
                self.showCharacterReviewCard(index: index)
            }
        }
        inputHandler = { [weak self] name in
            guard let self = self else { return }
            let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else {
                self.showChangeName(index: index, error: "Name can't be empty. Try again.")
                return
            }
            self.applyChangedName(index: index, newName: trimmed)
        }

        // Dice icon → new random suggestions
        rerollHandler = { [weak self] in
            self?.showChangeName(index: index)
        }
    }

    private func applyChangedName(index: Int, newName: String) {
        guard index < party.count else { showPartyReview(); return }
        let char = party[index]
        if isReservedWord(newName) {
            showChangeName(index: index, error: "That name isn't available. Try something else.")
            return
        }
        if !isNameAppropriate(newName) {
            showChangeName(index: index, error: "That name is not befitting of an adventurer. Try again.")
            return
        }
        if otherPartyNames(excluding: char.id).contains(newName.lowercased()) {
            showChangeName(index: index, error: "Another character in the party already has that name.")
            return
        }
        pushEditSnapshot(index: index)
        char.name = newName
        char.syncRobotPrefix()
        endEditTracking()
        showCharacterReviewCard(index: index)
    }

    private func showChangeRace(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        clearTerminal()
        printTitle("Change Race")
        print("  Current: \(party[index].race.rawValue)", color: .yellow)
        print("")

        let races = Race.allCases
        let backAction: () -> Void = { [weak self] in self?.returnFromCharacterEditSubscreen(index: index) }
        closeHandler = backAction
        showPaginatedMenu(races.map { $0.rawValue }, pinned: ["?", "< Back"], pinnedHandler: { [weak self] p in
            guard let self = self else { return }
            if p == 0 {
                self.showInlineHelp {
                    self.printTitle("Change Race — Help")
                    self.print("")
                    self.printWrapped("Tap a race to see exactly how it would change this character's ability scores and HP, then confirm or back out.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else {
                backAction()
            }
        }, handler: { [weak self] idx in
            guard let self = self, idx >= 0 && idx < races.count else { return }
            let newRace = races[idx]
            let char = self.party[index]
            if newRace == char.race {
                backAction()
                return
            }
            self.confirmChangeRace(index: index, newRace: newRace)
        })
    }

    private func confirmChangeRace(index: Int, newRace: Race) {
        let char = party[index]
        let oldRace = char.race

        clearTerminal()
        printTitle("Confirm Race Change")
        print("")
        print("  \(oldRace.rawValue) → \(newRace.rawValue)", color: .yellow, bold: true)
        print("")

        // Show ability score changes
        print("  ABILITY CHANGES:", color: .cyan, bold: true)
        let oldBonuses = Dictionary(oldRace.abilityBonuses, uniquingKeysWith: { a, _ in a })
        let newBonuses = Dictionary(newRace.abilityBonuses, uniquingKeysWith: { a, _ in a })
        let allAbilities: [Ability] = [.strength, .dexterity, .constitution, .intelligence, .wisdom, .charisma]
        for ability in allAbilities {
            let oldB = oldBonuses[ability] ?? 0
            let newB = newBonuses[ability] ?? 0
            if oldB != newB {
                let diff = newB - oldB
                let sign = diff > 0 ? "+" : ""
                print("    \(ability.abbreviation): \(sign)\(diff)", color: diff > 0 ? .brightGreen : .red)
            }
        }

        // Show HP impact
        let oldCon = char.abilityScores.modifier(for: .constitution)
        let oldConBonus = oldBonuses[.constitution] ?? 0
        let newConBonus = newBonuses[.constitution] ?? 0
        let conDiff = newConBonus - oldConBonus
        if conDiff != 0 {
            print("  HP will change (CON modifier \(conDiff > 0 ? "increases" : "decreases"))", color: conDiff > 0 ? .brightGreen : .yellow)
        }
        print("")

        showMenuOptions([MenuOption("Confirm"), MenuOption("< Back"), MenuOption("?", tint: .navigation, compact: true)])
        closeHandler = { [weak self] in self?.showChangeRace(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 3 {
                self.showInlineHelp {
                    self.printTitle("Confirm Race Change — Help")
                    self.print("")
                    self.printWrapped("Shows exactly which ability scores (and HP) would change. Confirm applies it; < Back returns to picking a race.", indent: 2, color: .dimGreen)
                    self.print("")
                }
                return
            }
            if choice == 1 {
                self.pushEditSnapshot(index: index)
                let char = self.party[index]
                // Remove old racial bonuses
                for (ability, bonus) in oldRace.abilityBonuses {
                    let current = char.abilityScores.score(for: ability)
                    char.abilityScores.set(ability, to: current - bonus)
                }
                // Apply new racial bonuses
                char.race = newRace
                for (ability, bonus) in newRace.abilityBonuses {
                    let current = char.abilityScores.score(for: ability)
                    char.abilityScores.set(ability, to: current + bonus)
                }
                char.recalculateMaxHP()
            }
            self.returnFromCharacterEditSubscreen(index: index)
        }
    }

    private func showChangeClass(index: Int) {
        guard index < party.count else { showPartyReview(); return }
        clearTerminal()
        printTitle("Change Class")
        print("  Current: \(party[index].characterClass.rawValue)", color: .yellow)
        print("")

        let classes = CharacterClass.allCases
        let backAction: () -> Void = { [weak self] in self?.returnFromCharacterEditSubscreen(index: index) }
        closeHandler = backAction
        showPaginatedMenu(classes.map { $0.rawValue }, pinned: ["?", "< Back"], pinnedHandler: { [weak self] p in
            guard let self = self else { return }
            if p == 0 {
                self.showInlineHelp {
                    self.printTitle("Change Class — Help")
                    self.print("")
                    self.printWrapped("Tap a class to see exactly what changing to it would do — ability priorities, hit die, equipment, skills, and spellcasting — then confirm or back out.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else {
                backAction()
            }
        }, handler: { [weak self] idx in
            guard let self = self, idx >= 0 && idx < classes.count else { return }
            let newClass = classes[idx]
