    /// Context-sensitive help for the difficulty selection screen
    private func showDifficultyHelp(dungeonName: String) {
        showInlineHelp {
            self.printTitle("Difficulty Help")

            self.print("DIFFICULTY LEVELS", color: .cyan, bold: true)
            self.printWrapped("Difficulty affects monster strength, encounter frequency, and treasure rarity.", indent: 2)
            self.print("")
            self.print("  0  Trivial — Very weak monsters, great for", color: .dimGreen)
            self.print("     learning the game.", color: .dimGreen)
            self.print("  1  Easy — Suitable for new players or small", color: .dimGreen)
            self.print("     parties. Forgiving combat.", color: .dimGreen)
            self.print("  2  Medium — Balanced challenge. The standard", color: .dimGreen)
            self.print("     D&D experience.", color: .dimGreen)
            self.print("  3  Hard — Tough encounters. Rest often and", color: .dimGreen)
            self.print("     manage resources carefully.", color: .dimGreen)
            self.print(" 4+  Brutal — Scaled-up monster HP and damage.", color: .dimGreen)
            self.print("     For experienced parties only.", color: .dimGreen)
            self.print("")
            self.print("CUSTOM LEVELS", color: .cyan, bold: true)
            self.printWrapped("You can type any number, including decimals (e.g. 1.5, 2.5). Values between whole numbers blend difficulty smoothly.", indent: 2)
            self.print("")
            self.print("TIPS", color: .cyan, bold: true)
            self.printWrapped("• A party of 1-2 adventurers should start on Easy.", indent: 2)
            self.printWrapped("• A full party of 4 can handle Medium comfortably.", indent: 2)
            self.printWrapped("• Long-press a difficulty to skip the confirmation screen.", indent: 2)
            self.print("")
        }
    }

    /// Convert a custom difficulty Double to a display name
    private func difficultyName(for level: Double) -> String {
        switch level {
        case ..<0.5: return "Trivial"
        case 0.5..<1.0: return "Very Easy"
        case 1.0: return "Easy"
        case 1.0..<2.0: return "Easy-Medium"
        case 2.0: return "Medium"
        case 2.0..<3.0: return "Medium-Hard"
        case 3.0: return "Hard"
        case 3.0..<4.0: return "Hard-Brutal"
        default: return "Brutal"
        }
    }

    /// Convert custom difficulty Double to dungeon level (1-3) and difficulty scale
    private func parseDifficulty(_ value: Double) -> (level: Int, scale: Double) {
        let clamped = max(0, value)
        let level = Int(max(1, min(3, round(clamped))))
        // Scale: 1.0 at standard levels, adjusted for custom values
        // e.g. 0 = 0.5x, 0.5 = 0.75x, 1 = 1.0x, 2 = 1.0x, 3 = 1.0x, 4 = 1.5x
        let scale: Double
        if clamped <= 1.0 {
            scale = 0.5 + (clamped * 0.5) // 0→0.5, 1→1.0
        } else if clamped <= 3.0 {
            scale = 1.0 // standard range
        } else {
            scale = 1.0 + ((clamped - 3.0) * 0.25) // 4→1.25, 5→1.5
        }
        return (level, scale)
    }

    /// Stored difficulty scale from custom level input (affects monster HP/damage)
    var difficultyScale: Double = 1.0

    /// How much stronger the party has grown since Level 1, recomputed live
    /// from current party levels every time it's read — so the dungeon keeps
    /// pace with the explorers' actual growing skill over the course of an
    /// adventure, not just the difficulty picked once at the start. Applied
    /// in startCombat() on top of difficultyScale.
    var partySkillMultiplier: Double {
        guard !party.isEmpty else { return 1.0 }
        let avgLevel = Double(party.map { $0.level }.reduce(0, +)) / Double(party.count)
        // Level 1 = baseline (1.0x). Each level above 1 adds ~8% monster
        // toughness, capped so even a full level-5 party isn't overwhelmed.
        return min(1.4, 1.0 + (avgLevel - 1.0) * 0.08)
    }

    func selectDifficulty(dungeonName: String) {
        clearTerminal()
        printTitle("Adventure Awaits!")
        printWrapped("Dungeon: \(dungeonName)", indent: 2, color: .brightGreen)
        let partyNames = party.map { $0.name }.joined(separator: ", ")
        printWrapped("Party: \(partyNames)", indent: 2, color: .dimGreen)
        print("")
        print("Choose difficulty, or type a custom level:")
        print("")
        print("  Level  Difficulty", color: .dimGreen)
        print("  ─────  ──────────", color: .dimGreen)
        print("    0    Trivial", color: .dimGreen)
        print("    1    Easy", color: .dimGreen)
        print("    2    Medium", color: .dimGreen)
        print("    3    Hard", color: .dimGreen)
        print("   4+    Brutal", color: .dimGreen)
        print("")

        promptTextWithMenu("", options: ["Easy (1)", "Medium (2)", "Hard (3)", "?"])

        closeHandler = { [weak self] in
            self?.clearTerminal()
            self?.startAdventure()
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 4 {
                self.showDifficultyHelp(dungeonName: dungeonName)
                return
            }
            self.confirmAdventure(dungeonName: dungeonName, level: Double(choice))
        }
        inputHandler = { [weak self] text in
            guard let self = self else { return }
            guard let value = Double(text.trimmingCharacters(in: .whitespaces)) else {
                self.print("Enter a number (e.g. 1, 2.5, 3).", color: .yellow)
                self.selectDifficulty(dungeonName: dungeonName)
                return
            }
            if value < 0 {
                self.print("Even the bravest adventurers must face some challenge! Enter 0 or above.", color: .yellow)
                self.selectDifficulty(dungeonName: dungeonName)
                return
            }
            self.confirmAdventure(dungeonName: dungeonName, level: value)
        }

        // Long-press bypasses confirmation
        menuLongPressHandler = { [weak self] choice in
            guard let self = self, choice >= 1 && choice <= 3 else {
                self?.clearTerminal()
                self?.startAdventure()
                return
            }
            let diff = self.parseDifficulty(Double(choice))
            self.difficultyScale = diff.scale
            self.dungeon = Dungeon(name: dungeonName, level: diff.level)
            self.beginQuestOffer()
        }
    }

    /// Stack of (name, level) states for undo/redo in adventure confirmation
    private var adventureUndoStack: [(String, Double)] = []
    private var adventureRedoStack: [(String, Double)] = []

    // MARK: Adventure cutscene
    //
    // Before each new adventure: a blank screen and one line at a time —
    // why this party is going down, what they're after, what they might
    // gain, and what their particular skills should count for.
    // MARK: Combat log
    //
    // A fight reads as one long, scrollable account: each turn adds a small
    // divider and carries on below instead of clearing the screen, and
    // after a sub-screen (spells, potions, targets) the account so far is
    // put back before the next turn.
    private var combatLogShowing = false
    private var combatLogBuffer: [TerminalLine] = []

    private func combatPageBreak() {
        guard currentCombat != nil else { clearTerminal(); return }
        if !combatLogShowing {
            let saved = combatLogBuffer
            clearTerminal()
            terminalLines = saved
        }
        if !terminalLines.isEmpty {
            print("")
            print("  · · · · · · · · · · · ·", color: .dimGreen)
            print("")
        }
        if terminalLines.count > 600 { terminalLines.removeFirst(terminalLines.count - 600) }
        combatLogShowing = true
        suppressAutoScroll = false
        speechFromLine = terminalLines.count   // Read Aloud: just this turn's lines
        speakerHasReadCurrentPage = false
    }

    private var cutsceneActive = false
    /// This adventure's opening tale, a line a page (Party Status > Opening Tale).
    var adventureIntroLines: [String] = []
    /// Why the party is on this adventure at all (side quests are the errands).
    @Published var mainQuest: MainQuest?
    /// The story of this adventure's quests — taken up, turned down, changed, done.
    var questHistory: [String] = []
    /// Chose to adventure with no main quest (people will nag, and offer one).
    var noMainQuest = false
    var mainQuestCompleted = false
    /// The plea just turned down (the next asker riffs on it), and who's asking.
    private var questPleaPrevious: MainQuest?
    private var questPleaAsker: String?
    private var npcQuestOffers: [Int: MainQuest] = [:]
    /// Changing quest: the old one (and its tale), kept until the party decides.
    private var questChangeBackup: (quest: MainQuest, intro: [String])?
    /// While a tale, a quest offer or the story so far is on, the map stays hidden.
    @Published var storyScreenActive = false
    /// The opening tale is written by the AI's most capable model when one's set up.
    var storyWriterEnabled: Bool { UserDefaults.standard.object(forKey: "storyWriter") as? Bool ?? true }
    private var typewriterTimer: Timer?

    /// For adventures saved before the tale was kept: the lines, recovered
    /// from the Adventure Log's "The tale begins:" entry.
    private func recoveredIntroLines() -> [String] {
        guard let entry = adventureLog.first(where: { $0.contains("The tale begins: ") }),
              let range = entry.range(of: "The tale begins: ") else { return [] }
        let chars = Array(String(entry[range.upperBound...]))
        var lines: [String] = []
        var current = ""
        for (i, ch) in chars.enumerated() {
            current.append(ch)
            let next: Swift.Character = i + 1 < chars.count ? chars[i + 1] : " "
            if ".!?…".contains(ch) && next == " " {
                lines.append(current.trimmingCharacters(in: .whitespaces))
                current = ""
            }
        }
        let rest = current.trimmingCharacters(in: .whitespaces)
        if !rest.isEmpty { lines.append(rest) }
        return lines
    }

    /// Types `text` out a few letters at a time, with a soft typewriter
    /// tick (Reduce Animations: all at once). A new line (or a tap) finishes
    /// any line still being typed first.
    private var typewriterFinish: (() -> Void)?

    private func finishTypewriter() {
        typewriterTimer?.invalidate()
        typewriterFinish?()
        typewriterFinish = nil
    }

    private func typewrite(_ text: String, color: TerminalColor) {
        finishTypewriter()
        let start = terminalLines.count
        printWrapped(text, indent: 2, color: color)
        let end = terminalLines.count
        guard !reduceAnimations, end > start else { return }
        let full = (start..<end).map { terminalLines[$0].text }
        for i in start..<end { terminalLines[i].text = "" }
        let generation = screenGeneration
        typewriterFinish = { [weak self] in
            guard let self = self, self.screenGeneration == generation else { return }
            for (k, t) in full.enumerated() where start + k < self.terminalLines.count { self.terminalLines[start + k].text = t }
        }
        var lineIndex = 0
        var shown = 0
        typewriterTimer = Timer.scheduledTimer(withTimeInterval: 0.028, repeats: true) { [weak self] timer in
            guard let self = self, self.screenGeneration == generation else { timer.invalidate(); return }
            guard lineIndex < full.count, start + lineIndex < self.terminalLines.count else {
                timer.invalidate()
                self.typewriterFinish = nil
                return
            }
            shown += 1
            self.terminalLines[start + lineIndex].text = String(full[lineIndex].prefix(shown))
            if shown % 3 == 1 { SoundManager.shared.playTypewriterTick() }
            if shown >= full[lineIndex].count { lineIndex += 1; shown = 0 }
        }
    }

    /// A tale shown a page (line) at a time, typed out like a typewriter:
    /// Next/Previous or swipe, with the page counter. At the last page,
    /// `finishLabel` (and a swipe onward) goes to `onFinish` — the Opening
    /// Tale leads straight on to the Progress Tale.
    private func showTalePages(title: String, lines: [String], page: Int, onBack: @escaping () -> Void,
                               emptyMessage: String = "There's no tale to tell yet.",
                               finishLabel: String? = nil, onFinish: (() -> Void)? = nil, appendOnly: Bool = false, pace: Double = 1.0, skipLabel: String? = nil) {
        if !appendOnly || lines.isEmpty {
            clearTerminal()
            printTitle(title)
            print("")
        }
        guard !lines.isEmpty else {
            printWrapped(emptyMessage, indent: 2, color: .dimGreen)
            var opts: [String] = []
            if let label = finishLabel, onFinish != nil { opts.append(label) }
            opts.append("< Back")
            showMenu(opts)
            closeHandler = onBack
            menuHandler = { choice in
                guard choice >= 1, choice <= opts.count else { return }
                if opts[choice - 1] == "< Back" { onBack() } else { onFinish?() }
            }
            return
        }
        let i = min(max(0, page), lines.count - 1)
        let last = i == lines.count - 1
        // Earlier paragraphs stay on the page; the new one types in below.
        if appendOnly {
            finishTypewriter()
            suppressAutoScroll = false
            print("")
        } else {
            for k in 0..<i {
                printWrapped(lines[k], indent: 2, color: .green)
                print("")
            }
        }
        typewrite(lines[i], color: last ? .yellow : .green)
        // The same buttons on every page: Next (End Tale at the very end),
        // Previous (greyed on the first page), Skip (greyed when there's
        // nothing left to skip) and Back.
        let atEnd = last && onFinish == nil
        let opts = [atEnd ? "End Tale" : "Next", "Previous", "Skip", "< Back"]
        showMenuOptions(opts.map { t in
            if t == "< Back" { return MenuOption(t, tint: .navigation, compact: true) }
            return MenuOption(t, isDisabled: (t == "Previous" && i == 0) || (t == "Skip" && atEnd))
        })
        let next: () -> Void = { [weak self] in
            self?.showTalePages(title: title, lines: lines, page: i + 1, onBack: onBack, emptyMessage: emptyMessage, finishLabel: finishLabel, onFinish: onFinish, appendOnly: true, pace: pace, skipLabel: skipLabel)
        }
        let previous: () -> Void = { [weak self] in
            self?.showTalePages(title: title, lines: lines, page: i - 1, onBack: onBack, emptyMessage: emptyMessage, finishLabel: finishLabel, onFinish: onFinish, pace: pace, skipLabel: skipLabel)
        }
        // Stepping out part-way: carry on, start again, or leave the tale.
        let pauseHere: () -> Void = { [weak self] in
            guard let self = self else { return }
            guard !last else { onBack(); return }
            self.talePageToken = UUID()   // stop the page turning itself
            self.pauseTale(resume: { [weak self] in
                self?.showTalePages(title: title, lines: lines, page: i, onBack: onBack, emptyMessage: emptyMessage, finishLabel: finishLabel, onFinish: onFinish, pace: pace, skipLabel: skipLabel)
            }, retell: { [weak self] in
                self?.showTalePages(title: title, lines: lines, page: 0, onBack: onBack, emptyMessage: emptyMessage, finishLabel: finishLabel, onFinish: onFinish, pace: pace, skipLabel: skipLabel)
            }, leave: onBack, leaveLabel: "Leave the Tale")
        }
        cardPositionLabel = "\(i + 1)/\(lines.count)"
        swipeLeftHandler = last ? (onFinish ?? onBack) : next
        swipeRightHandler = i > 0 ? previous : nil
        closeHandler = pauseHere
        menuHandler = { choice in
            guard choice >= 1, choice <= opts.count else { return }
            switch opts[choice - 1] {
            case "Next": if last { onFinish?() } else { next() }
            case "Previous": if i > 0 { previous() }
            case "Skip": if !atEnd { onBack() }
            case "End Tale": onBack()
            case "< Back": pauseHere()
            default: onFinish?()
            }
        }

        // Turns itself, like other timed screens: long enough to type the
        // paragraph out and read it (longer on the last page), with the
        // hourglass to pause it. With Read Aloud, when the voice finishes.
        let token = UUID()
        talePageToken = token
        let generation = screenGeneration
        let stillHere: () -> Bool = { [weak self] in
            guard let self = self else { return false }
            return self.talePageToken == token && self.screenGeneration == generation
        }
        let turn: () -> Void = last ? (onFinish ?? onBack) : next
        paceTaleParagraph(lines[i], last: last, paceScale: pace, isStillValid: stillHere, turn: turn)
    }

    /// The adventure's opening tale again — then on into the Progress Tale.
    func showOpeningTale(page: Int, onBack: @escaping () -> Void) {
        let lines = adventureIntroLines.isEmpty ? recoveredIntroLines() : adventureIntroLines
        showTalePages(title: "The Tale Begins", lines: lines, page: page, onBack: onBack,
                      emptyMessage: "This adventure began before tales were told — there's no opening tale to tell.",
                      finishLabel: "Progress Tale >", onFinish: { [weak self] in self?.showProgressTale(onBack: onBack) })
    }

    // MARK: Progress Tale

    /// Kept until something new happens, so reopening it doesn't ask the AI again.
    private var progressTaleCache: (logCount: Int, lines: [String])?

    /// A tale page is counting down to turn itself (shows the hourglass bar
    /// on a page that has buttons); cleared by the next screen.
    @Published var taleCountdownOn = false
    private var talePageToken = UUID()

    /// The story so far, told like the opening tale — page by page, typed
    /// out; written by the story model when an AI is set up.
    func showProgressTale(onBack: @escaping () -> Void) {
        let open: ([String]) -> Void = { [weak self] lines in
            guard let self = self else { return }
            self.progressTaleCache = (self.adventureLog.count, lines)
            self.showTalePages(title: "The Tale So Far", lines: lines, page: 0, onBack: onBack, pace: 1.8)
        }
        if let cached = progressTaleCache, cached.logCount == adventureLog.count, !cached.lines.isEmpty {
            showTalePages(title: "The Tale So Far", lines: cached.lines, page: 0, onBack: onBack, pace: 1.8)
            return
        }
        guard DMEngine.shared.isConfigured, storyWriterEnabled else { open(progressTaleOffline()); return }
        clearTerminal()
        for _ in 0..<5 { print("") }
        print("The tale is being written…", color: .dimGreen, centered: true)
        startWritingBar(seconds: 15)
        DMEngine.shared.writeStory(system: storySystemPrompt, prompt: progressPrompt()) { [weak self] text in
            guard let self = self else { return }
            self.stopWritingBar(filled: true, succeeded: text != nil)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { open(self.parseStory(text) ?? self.progressTaleOffline()) }
        }
    }

    /// Adventure Log highlights, without their "[time] [CATEGORY]" prefixes.
    private func progressHighlights(limit: Int) -> [String] {
        let wanted = ["QUEST", "LOOT", "COMBAT", "TRAP", "EXPLORE", "NPC", "SHOP"]
        let picked = adventureLog.filter { entry in wanted.contains { entry.contains("[\($0)]") } }
        return picked.suffix(limit).map { entry in
            var text = entry
            while text.hasPrefix("["), let close = text.firstIndex(of: "]") {
                text = String(text[text.index(after: close)...]).trimmingCharacters(in: .whitespaces)
            }
            return text
        }
    }

    private func progressPrompt() -> String {
        let mq = mainQuest
        let partyText = party.map { "\(shortName(for: $0)) (\($0.race.rawValue) \($0.characterClass.rawValue), level \($0.level))" }.joined(separator: ", ")
        let explored = dungeon?.rooms.values.filter { $0.visited }.count ?? 0
        let total = dungeon?.rooms.count ?? 0
        let gold = party.reduce(0) { $0 + $1.gold }
        let events = progressHighlights(limit: 40).map { "- \($0)" }.joined(separator: "\n")
        return """
        Tell the story of this adventure so far, carrying on from its opening tale (below) in exactly the same style, as 6 to 9 short lines — one sentence each, at most 30 words — one per line, with no numbering, headings or blank lines.
        Say what the party has done towards the main quest, their notable fights, finds and side quests, and end with where they stand now and what still lies ahead.
        Keep it plain and concrete: the real events, in order, each following from the last. No prophecies, omens or vague mystical phrases.

        Opening tale: \(adventureIntroLines.joined(separator: " "))
        Main quest: \(mq.map { "\($0.goal) — \($0.stakes); reward: \($0.reward); villain: \($0.villain)" } ?? "unknown")
        What they have found out on the way down: \(mq.map { $0.beatsSoFar(level: dungeon?.level ?? 1).joined(separator: " ") } ?? "nothing yet")
        Their quests so far: \(questHistory.isEmpty ? "(none recorded)" : questHistory.joined(separator: " "))
        The party: \(partyText)
        So far: day \(gameTimeMinutes / 1440 + 1); level \(dungeon?.level ?? 1) of \(dungeon?.name ?? "the dungeon"); \(explored) of \(total) rooms explored on this level; earlier levels: \(levelSummaryLines(includeCurrent: false).joined(separator: " ")); \(monstersSlain) monsters defeated in \(combatsWon) fights; \(gold) gold between them.
        Recent events (oldest first):
        \(events.isEmpty ? "- (nothing much yet)" : events)
        """
    }

    /// The Progress Tale written without an AI, from the same facts.
    private func progressTaleOffline() -> [String] {
        guard let dungeon = dungeon else { return [] }
        let names = party.map { shortName(for: $0) }
        let together = names.count <= 1 ? (names.first ?? "You") : names.dropLast().joined(separator: ", ") + " and " + names.last!
        let explored = dungeon.rooms.values.filter { $0.visited }.count
        let gold = party.reduce(0) { $0 + $1.gold }
        var lines: [String] = []
        if let mq = mainQuest {
            lines.append("It is day \(gameTimeMinutes / 1440 + 1) of the quest to \(mq.goal).")
        } else {
            lines.append("It is day \(gameTimeMinutes / 1440 + 1) of the adventure in \(dungeon.name).")
        }
        lines.append("\(together) \(names.count == 1 ? "has" : "have") explored \(explored) of the \(dungeon.rooms.count) rooms on level \(dungeon.level) of \(dungeon.name).")
        if monstersSlain > 0 {
            lines.append("They have faced down \(monstersSlain) creature\(monstersSlain == 1 ? "" : "s"), winning \(combatsWon) fight\(combatsWon == 1 ? "" : "s") in the dark.")
        } else {
            lines.append("Not a blade has been drawn in anger yet — but the dark is watching, and waiting.")
        }
        for event in progressHighlights(limit: 30).filter({ $0.lowercased().contains("quest") }).suffix(3) {
            lines.append(event.hasSuffix(".") ? event : event + ".")
        }
        lines.append("Their purses hold \(gold) gold between them.")
        if let mq = mainQuest {
            lines.append("Still ahead, somewhere below, waits \(mq.villain) — and it must be done \(mq.stakes).")
        }
        lines.append(["The torches burn lower. The adventure goes on.", "Onward, then — the deep is not done with them yet."].randomElement()!)
        return lines
    }
    private var cutsceneToken = UUID()

    private func playAdventureCutscene(then done: @escaping () -> Void) {
        // Half the time the quest comes from one of the adventure files (so an
        // offline tale can be that file's own), otherwise it's rolled fresh.
        if mainQuest == nil {
            mainQuest = Bool.random() ? (AdventureLibrary.templates().randomElement()?.mainQuest ?? MainQuest.random()) : MainQuest.random()
        }
        let play: ([String]) -> Void = { [weak self] lines in
            guard let self = self else { return }
            self.adventureIntroLines = lines
            self.logEvent("The tale begins: " + lines.joined(separator: " "), category: "STORY")
            if let mq = self.mainQuest { self.logEvent("Main quest: \(mq.summary) (\(mq.villain))", category: "QUEST") }
            self.cutsceneActive = true
            self.showCutsceneLine(0, lines: lines, done: done)
        }
        guard DMEngine.shared.isConfigured, storyWriterEnabled else { play(offlineOpeningTale()); return }
        clearTerminal()
        for _ in 0..<5 { print("") }
        print("The tale is being written…", color: .dimGreen, centered: true)
        startWritingBar(seconds: 15)
        DMEngine.shared.writeStory(system: storySystemPrompt, prompt: storyPrompt()) { [weak self] text in
            guard let self = self else { return }
            self.stopWritingBar(filled: true, succeeded: text != nil)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                if let lines = self.parseStory(text) {
                    self.keepWrittenTale(lines)
                    play(lines)
                } else {
                    play(self.offlineOpeningTale())
                }
            }
        }
    }

    /// A little hourglass and progress bar under "The tale is being
    /// written…" — fills over the story writer's time limit, and stops the
    /// moment the tale arrives.
    private var writingBarTimer: Timer?

    private func startWritingBar(seconds: Double) {
        writingBarTimer?.invalidate()
        print("")
        let index = terminalLines.count
        print("⏳ [" + String(repeating: "·", count: 20) + "]", color: .dimGreen, centered: true)
        let generation = screenGeneration
        let start = Date()
        writingBarStart = start
        writingBarIndex = index
        let expected = max(3, storyWriteEstimate)
        writingBarTimer = Timer.scheduledTimer(withTimeInterval: 0.2, repeats: true) { [weak self] timer in
            guard let self = self, self.screenGeneration == generation, index < self.terminalLines.count else { timer.invalidate(); return }
            let elapsed = Date().timeIntervalSince(start)
            // Calibrated to how long tales have been taking; past that, it
            // creeps on slowly rather than stalling or running out.
            let frac = elapsed < expected ? 0.9 * elapsed / expected : 0.9 + 0.09 * (1 - exp(-(elapsed - expected) / expected))
            let filled = Int(frac * 20)
            let glass = Int(elapsed * 1.5) % 2 == 0 ? "⏳" : "⌛"
            self.terminalLines[index].text = "\(glass) [" + String(repeating: "■", count: filled) + String(repeating: "·", count: 20 - filled) + "]"
        }
    }

    private var writingBarStart: Date?
    private var writingBarIndex: Int?
    /// How long the story writer usually takes (a running average).
    private var storyWriteEstimate: Double {
        get { let v = UserDefaults.standard.double(forKey: "storyWriteEstimate"); return v > 0 ? v : 8 }
        set { UserDefaults.standard.set(newValue, forKey: "storyWriteEstimate") }
    }

    /// Stops the bar; `filled` shows it complete, `succeeded` teaches it the time taken.
    private func stopWritingBar(filled: Bool = false, succeeded: Bool = false) {
        writingBarTimer?.invalidate()
        writingBarTimer = nil
        if succeeded, let start = writingBarStart {
            storyWriteEstimate = storyWriteEstimate * 0.6 + Date().timeIntervalSince(start) * 0.4
        }
        if filled, let i = writingBarIndex, i < terminalLines.count {
            terminalLines[i].text = "⌛ [" + String(repeating: "■", count: 20) + "]"
        }
        writingBarStart = nil
        writingBarIndex = nil
    }

    private func showCutsceneLine(_ i: Int, lines: [String], done: @escaping () -> Void) {
        guard i < lines.count else {
            cutsceneActive = false
            done()
            return
        }
        // One page: each paragraph types in below the last, and the view
        // follows it down.
        if i == 0 {
            clearTerminal()
            print("")
        } else {
            finishTypewriter()
            print("")
        }
        typewrite(lines[i], color: i == lines.count - 1 ? .yellow : .brightGreen)
        waitForContinue(fullScreenTap: true, autoContinue: false)
        let token = UUID()
        cutsceneToken = token
        // Read aloud: speak the paragraph itself (the screen's still typing it,
        // so the usual read-the-screen would find it blank), and move on a
        // moment after the voice finishes.
        inputHandler = { [weak self] _ in self?.showCutsceneLine(i + 1, lines: lines, done: done) }
        // ✕ leaves the tale altogether — straight on into the dungeon.
        closeHandler = { [weak self] in
            guard let self = self else { return }
            self.cutsceneToken = UUID()   // the pending auto-advance no longer applies
            let leave: () -> Void = { [weak self] in
                self?.cutsceneActive = false
                self?.closeHandler = nil
                done()
            }
            guard i < lines.count - 1 else { SpeechEngine.shared.stop(); leave(); return }
            self.pauseTale(resume: { [weak self] in
                guard let self = self else { return }
                self.clearTerminal()
                self.print("")
                for k in 0..<i { self.printWrapped(lines[k], color: .brightGreen); self.print("") }
                self.showCutsceneLine(i, lines: lines, done: done)
            }, retell: { [weak self] in self?.showCutsceneLine(0, lines: lines, done: done) },
               leave: leave, leaveLabel: "Skip the Rest")
        }
        // Each paragraph stays until it's been read (see paceTaleParagraph).
        paceTaleParagraph(lines[i], last: i == lines.count - 1, isStillValid: { [weak self] in
            guard let self = self else { return false }
            return self.cutsceneToken == token && self.awaitingContinue
        }, turn: { [weak self] in self?.handleContinue() })
    }

    /// Stepping out of a tale part-way: carry on, start again, or leave it.
    private func pauseTale(resume: @escaping () -> Void, retell: @escaping () -> Void, leave: @escaping () -> Void, leaveLabel: String) {
        SpeechEngine.shared.stop()
        clearTerminal()
        printTitle("The Tale, Paused")
        print("")
        printWrapped("The storyteller stops mid-sentence and looks up. \"Shall I go on?\"", indent: 2, color: .green)
        print("")
        showMenu(["Continue the Tale", "Tell It From the Start", leaveLabel])
        closeHandler = leave
        menuHandler = { choice in
            switch choice {
            case 1: resume()
            case 2: retell()
            default: leave()
            }
        }
    }

    /// A tale paragraph's pace: with Read Aloud on, the page waits until the
    /// voice has read this paragraph to the end, then a short pause; with it
    /// off, it waits as long as the voice would take (never less than the
    /// typing), then the same pause. The hourglass pauses it, and Timeouts >
    /// Tales stretches or shortens it.
    private func paceTaleParagraph(_ text: String, last: Bool, paceScale: Double = 1.0, isStillValid: @escaping () -> Bool, turn: @escaping () -> Void) {
        let speech = SpeechEngine.shared
        let spoken = speech.estimatedDuration(of: text)
        let typing = reduceAnimations ? 0 : Double(text.count) * 0.028
        let pause = (last ? 6.0 : 2.5) * timeoutScale(.tales) * paceScale
        let go: () -> Void = { [weak self] in
            guard let self = self, isStillValid() else { return }
            if self.autoContinuePaused {
                self.afterAutoContinuePause(isStillValid: isStillValid, resume: turn)
            } else {
                turn()
            }
        }
        if speakerModeOn {
            speakerHasReadCurrentPage = true
            speech.stop()
            var finished = false
            speech.speakAloud(text) {
                finished = true
                DispatchQueue.main.asyncAfter(deadline: .now() + max(0, typing - spoken) + pause) { go() }
            }
            // The hourglass shows about how long the voice will take.
            taleCountdownOn = autoContinueEnabled
            scheduleAutoAdvance(after: max(typing, spoken) + pause, isStillValid: { [weak self] in
                isStillValid() && self?.speakerModeOn == true && !finished
            }, fire: {})
            // If the voice gets cut off rather than finishing, don't stall.
            DispatchQueue.main.asyncAfter(deadline: .now() + max(typing, spoken) * 1.6 + pause + 3) {
                guard !finished, !speech.isSpeaking else { return }
                go()
            }
        } else {
            taleCountdownOn = autoContinueEnabled
            scheduleAutoAdvance(after: max(typing, spoken) * timeoutScale(.tales) * paceScale + pause, isStillValid: isStillValid, fire: turn)
        }
    }

    private var storySystemPrompt: String {
        "You write the opening narration for a family-friendly (age 9+) fantasy text adventure. British English. " +
        "No gore, no swearing, nothing frightening beyond a good fairy tale. Warm, vivid, a little funny where it fits. " +
        "Tell it plainly, the way a good storyteller talks to a child: real people, places and events, each sentence following from the one before. " +
        "Never use prophecies, omens, riddles or vague mystical phrases."
    }

    /// The brief for the story writer: this party, this dungeon, this main quest.
    private func storyPrompt() -> String {
        let mq = mainQuest ?? MainQuest.random()
        let partyText = party.map { "\(shortName(for: $0)) (\($0.race.rawValue) \($0.characterClass.rawValue))" }.joined(separator: ", ")
        return """
        Write the opening tale for this adventure as 7 to 9 short lines — one sentence each, at most 30 words — one per line, with no numbering, headings or blank lines.
        The tale must: tell why this party is going into the dungeon; state the main quest clearly (the goal, what is at stake, and the reward); name the villain; mention every adventurer by name and what their class or people bring; and end on the plea itself — the party hasn't said yes yet, so don't have them accept or set off.
        It must read as one clear story, in this order: what is going wrong in the village; who is behind it and why; who asks the party for help; the quest (goal, deadline, reward); what each adventurer brings; setting off into the dungeon.
        Every sentence must follow from the one before, with concrete, everyday details. Vary the details (who asks, the weather, the mood) so it doesn't feel like every other tale.

        Dungeon: \(dungeon?.name ?? "the dungeon")
        Home village: \(mq.village)
        Villain (the guardian waiting at the very bottom): \(mq.villain)
        What the villain is doing to the village: \(mq.harm ?? "(invent something that fits the goal)")
        Why the villain is doing it: \(mq.motive ?? "(invent a reason that fits)")
        Where it is found: \(mq.place ?? "(somewhere deep — invent a place that fits)")
        What must be done at the end: \(mq.finale ?? "(invent something fitting)")
        Who down there knows things: \(mq.informant ?? "(invent someone)")
        Mention who might know more, as a hint for the journey; keep the ending itself for later.
        \(storyKindNote(mq))
        \(storyRiffNote())
        Main quest: \(mq.goal)
        What is at stake: \(mq.stakes)
        Reward: \(mq.reward)
        The party: \(partyText)
        """ + storyStyleExamples()
    }

    /// Quests whose tale must keep a secret.
    private func storyKindNote(_ mq: MainQuest) -> String {
        switch mq.kind {
        case "mystery": return "This is a mystery: nobody knows who is behind it yet. Do NOT name the villain in the tale — say only that someone is, and that the trail leads into the dungeon."
        case "twist": return "Secret twist: the villain is the very person who asks the party for help. Present them as a worried, generous patron, and don't reveal the truth — just one small odd detail."
        case "rival": return "The villain is a rival band of adventurers racing the party for the same prize."
        default: return ""
        }
    }

    /// A couple of tales from the adventure files, for the story writer to
    /// learn the style from (not to copy).
    private func storyStyleExamples() -> String {
        let examples = AdventureLibrary.styleExamples().map { $0.filledTale(party: "the heroes", dungeon: "the dungeon").joined(separator: "\n") }
        guard !examples.isEmpty else { return "" }
        return "\n\nFor the style only, here are opening tales from other adventures. Match their voice and pace, but don't reuse their plots, names or lines:\n\n"
            + examples.enumerated().map { "Example \($0.offset + 1):\n\($0.element)" }.joined(separator: "\n\n")
    }

    /// A tale the story writer wrote, kept as one more example for next time.
    private func keepWrittenTale(_ lines: [String]) {
        guard let mq = mainQuest else { return }
        AdventureLibrary.saveGenerated(AdventureFile(title: "\(Dungeon.guardianName(mq.villain)) — \(dungeon?.name ?? "the dungeon")",
                                                     village: mq.village, villain: mq.villain, goal: mq.goal, stakes: mq.stakes,
                                                     reward: mq.reward, tale: lines, author: "Story writer", generated: true))
    }

    /// Without the story writer: the adventure file's own tale when the quest
    /// came from one, else the tale built from the quest and the party.
    private func offlineOpeningTale() -> [String] {
        if let mq = mainQuest, let file = AdventureLibrary.templates().first(where: { $0.villain == mq.villain && $0.goal == mq.goal }) {
            let names = party.map { shortName(for: $0) }
            let together = names.count <= 1 ? (names.first ?? "a lone adventurer") : names.dropLast().joined(separator: ", ") + " and " + names.last!
            var tale = file.filledTale(party: together, dungeon: dungeon?.name ?? "the dungeon")
            if tale.count > 3 { tale.removeLast() }   // it ends with them setting off; here, it ends on the plea
            tale.append("\"Will you help?\"")
            return pleaRiffLines() + tale
        }
        return pleaRiffLines() + adventureBackstory()
    }

    /// Just turned a plea down? The next asker answers that very quest.
    private func pleaRiffLines() -> [String] {
        guard let prev = questPleaPrevious else { return [] }
        let short = Dungeon.guardianName(prev.villain)
        let asker = questPleaAsker ?? "someone else from the village"
        let who = asker.prefix(1).uppercased() + asker.dropFirst()
        var lines = [
            "\"So you won't \(prev.goal)?\" \(who) snorts. \"Can't say I blame you — \(short) gives me nightmares. But hear us out first.\"",
            "\"Turned \(prev.village) down, did you? Then you've time for us,\" says \(asker). \"\(short) is bad. Ours is worse.\"",
            "\(who) catches you by the sleeve. \"Forget \(short) and \(prev.village)'s troubles. We've got our own, and nobody else will help.\"",
        ]
        if let harm = prev.harm {
            lines.append("\"Aye, \(harm) — we all heard, and it's awful,\" says \(asker). \"But what's happening to us is worse.\"")
        }
        return [lines.randomElement()!]
    }

    private func storyRiffNote() -> String {
        guard let prev = questPleaPrevious else { return "" }
        let short = Dungeon.guardianName(prev.villain)
        let asker = questPleaAsker ?? "someone else from the village"
        return "The party has just turned down another plea — to \(prev.goal) (villain: \(short)). Open by riffing on that: \(asker) pushes forward and says, in effect, never mind \(short) — their own trouble is far more worrying. Refer to that plea specifically — its villain and what it was about — and draw a clear contrast with the new trouble; no generic remarks. Then tell their tale. The one asking is \(asker), not the village elder."
    }

    static let pleaAskers = ["a knot of worried farmers", "the town rat-catcher, a small man with a very large sack", "the miller's three children",
                             "old Sergeant Budge, the retired town guard", "the goose girl (and her goose)", "the schoolteacher, still clutching her chalk",
                             "a travelling tinker with a wagon full of pans", "the innkeeper, wiping her hands on her apron"]
    static let noQuestNags = ["No quest? What are you lot doing down here — sightseeing?",
                              "Adventurers without a quest are like a boat without an oar. I've got one for you, if you're brave enough.",
                              "You're wandering about with no purpose. I can always tell. Want a real job?",
                              "Still no quest? Tut. Some of us have real troubles."]

    /// The story writer's reply as lines, or nil if it isn't usable.
    private func parseStory(_ text: String?) -> [String]? {
        guard let text = text else { return nil }
        var lines = text.components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty && !$0.hasPrefix("#") }
            .map { line -> String in
                var l = line
                while let first = l.first, first == "-" || first == "*" || first == "•" || first.isNumber || first == "." || first == ")" || first == " " {
                    l.removeFirst()
                }
                return l
            }
            .filter { $0.count >= 8 }
        if lines.count > 10 { lines = Array(lines.prefix(10)) }
        return lines.count >= 4 ? lines.map { String($0.prefix(260)) } : nil
    }

    /// The party's reason for going in, their goal and reward, and a word on
    /// what each kind of adventurer in this team brings.
    private func adventureBackstory() -> [String] {
        let place = dungeon?.name ?? "the dungeon"
        let names = party.map { shortName(for: $0) }
        let solo = names.count <= 1
        let together = solo ? (names.first ?? "You")
            : names.dropLast().joined(separator: ", ") + " and " + names.last!

        // What each kind of adventurer in this team brings — and any gap.
        var team: [String] = []
        var seen = Set<String>()
        for c in party where team.count < 3 && seen.insert(c.characterClass.rawValue).inserted {
            let n = shortName(for: c)
            switch c.characterClass {
            case .fighter: team.append("\(n)'s sword arm will hold the narrow corridors.")
            case .wizard: team.append("\(n)'s spells can light the dark — and burn what lurks in it.")
            case .rogue: team.append("\(n) knows how to slip past a sleeping guard, and open what others lock.")
            case .cleric: team.append("\(n)'s prayers will mend what the dungeon breaks.")
            case .ranger: team.append("\(n) can read a track in the dust and loose an arrow before trouble arrives.")
            case .barbarian: team.append("When all else fails, \(n)'s fury will do the rest.")
            case .engineer: team.append("\(n)'s gadgets have an answer for most locks — and most traps.")
            case .scout: team.append("\(n) will see danger long before it sees them.")
            case .thief: team.append("\(n)'s quick fingers will find the treasure others walk past.")
            case .bard: team.append("\(n)'s songs will lift tired spirits — and a quick tongue can talk the party out of trouble.")
            }
        }
        let classes = Set(party.map { $0.characterClass })
        if !classes.contains(.cleric) {
            team.append("With no healer among them, every potion will count.")
        } else if classes.isDisjoint(with: [.fighter, .barbarian]) {
            team.append("None of them is much of a brawler — cunning will have to win the day.")
        }

        let mq = mainQuest ?? MainQuest.random()

        // Story by Beau Lewis (world creation and storytelling) — the
        // village, the beast (this dungeon's own boss, where there is one),
        // the dungeon and the size of the band are filled in; the words are Beau's.
        if questPleaPrevious == nil && Int.random(in: 1...10) <= 6 {
            let village = mq.village
            let beast = mq.villain
            var lines = [
                "The small, quiet village of \(village), once a place of peace and prosperity, has been recently haunted by the terrifying beast that is known as \(beast).",
                "In their panic and horror, the people desperately tried to find one brave enough to face its lair. But there was none.",
                solo ? "Until, a lone, young and brave warrior came wandering through town, searching for adventure: \(together)."
                     : "Until, a small, young band of brave warriors came wandering through town, searching for adventure: \(together).",
                "One day, whilst \(solo ? "they were" : "they were") staying there, the elder of the village came to the inn that they had been staying at, begging for salvation.",
                solo ? "The adventurer thought briefly, before bravely deciding to take up the task."
                     : "The adventurers consulted briefly, before bravely deciding to take up the task.",
            ]
            lines.append("The task: to \(mq.goal) — \(mq.stakes). The reward: \(mq.reward).")
            lines += team
            lines.append("Now you must venture deep, deeper than any man has ever gone before, into the dank, deep dungeon… of \(place).")
            return lines
        }

        // One plain story, in order: what's wrong, who's behind it and why,
        // who asks, the quest, the team — and in they go.
        let villainName = Dungeon.guardianName(mq.villain)
        var lines: [String] = []
        lines.append("In the village of \(mq.village), \(mq.harm ?? "something has gone badly wrong, and nobody can put it right").")
        switch mq.kind {
        case "mystery":
            lines.append("Nobody knows who is behind it. The only clue is a trail that leads into \(place).")
        case "twist":
            lines.append("\(villainName), who owns the land around \(mq.village), is beside himself with worry, and offers a handsome purse to anyone who can help.")
        default:
            lines.append("Everyone knows who is to blame: \(mq.villain), who \(mq.motive ?? "wants the whole valley for itself").")
            lines.append("\(villainName) has a lair deep in \(place), and the few who went after it came back empty-handed, or not at all.")
        }
        if let asker = questPleaAsker, questPleaPrevious != nil {
            lines.append(asker.prefix(1).uppercased() + asker.dropFirst() + " tells the whole story, twisting their hat in their hands.")
        } else {
        lines.append([
            "That evening \(together) \(solo ? "arrives" : "arrive") at the inn, and the village elder comes straight to their table.",
            "The elder of \(mq.village) has been waiting at the crossroads for anyone with a sword, and \(together) \(solo ? "is" : "are") the first to come along.",
            "A child from \(mq.village) runs up to \(together), out of breath, and begs them to come and see the elder.",
        ].randomElement()!)
        }
        lines.append("The task: to \(mq.goal), \(mq.stakes).")
        if let who = mq.informant { lines.append("Down there, the elder says, \(who) know more than they let on. Ask them.") }
        lines.append("The reward: \(mq.reward).")
        lines += team
        lines.append("\"Will you help us?\"")
        return lines
    }

    private func confirmAdventure(dungeonName: String, level: Double) {
        clearTerminal()
        printTitle("Ready to Begin?")

        // Castle dragon on the entry screen
        DispatchQueue.main.async {
            self.dragonGifName = "dragon_castle"
        }

        let diffName = difficultyName(for: level)
        let levelStr = level.truncatingRemainder(dividingBy: 1) == 0
            ? "\(Int(level))" : String(format: "%.1f", level)
        print("")
        print("  DUNGEON", color: .cyan, bold: true)
        printWrapped("  \(dungeonName)", indent: 2, color: .brightGreen)
        print("")
        print("  DIFFICULTY", color: .cyan, bold: true)
        print("  \(diffName) (Level \(levelStr))", color: .brightGreen)
        print("")
        print("  PARTY", color: .cyan, bold: true)
        for char in party {
            let hp = "HP \(char.currentHP)/\(char.maxHP)"
            print("  \(char.name) — Lv.\(char.level) \(char.characterClass.rawValue) (\(hp))", color: .dimGreen)
        }
        print("")

        var opts = ["Enter the Dungeon", "Difficulty", "Rename Dungeon"]
        if !adventureUndoStack.isEmpty { opts.append("Undo") }
        if !adventureRedoStack.isEmpty { opts.append("Redo") }
        opts.append("?")
        opts.append("< Back")

        showMenu(opts)

        closeHandler = { [weak self] in
            self?.adventureUndoStack.removeAll()
            self?.adventureRedoStack.removeAll()
            self?.clearTerminal()
            self?.startNewGame()
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let selected = opts[choice - 1]
            switch selected {
            case "Enter the Dungeon":
                self.adventureUndoStack.removeAll()
                self.adventureRedoStack.removeAll()
                let diff = self.parseDifficulty(level)
                self.difficultyScale = diff.scale
                self.dungeon = Dungeon(name: dungeonName, level: diff.level)
                self.beginQuestOffer()
            case "Difficulty":
                self.adventureUndoStack.append((dungeonName, level))
                self.adventureRedoStack.removeAll()
                self.changeDifficultyInline(currentName: dungeonName, currentLevel: level)
            case "Rename Dungeon":
                self.adventureUndoStack.append((dungeonName, level))
                self.adventureRedoStack.removeAll()
                self.changeDungeonNameInline(currentName: dungeonName, currentLevel: level)
            case "Undo":
                if let prev = self.adventureUndoStack.popLast() {
                    self.adventureRedoStack.append((dungeonName, level))
                    var changes: [String] = []
                    if prev.0 != dungeonName { changes.append(prev.0) }
                    if prev.1 != level { changes.append("Lv.\(prev.1.truncatingRemainder(dividingBy: 1) == 0 ? "\(Int(prev.1))" : String(format: "%.1f", prev.1))") }
                    self.showUndoFeedback(changes.isEmpty ? "Dungeon" : changes.joined(separator: ", "))
                    self.confirmAdventure(dungeonName: prev.0, level: prev.1)
                }
            case "Redo":
                if let next = self.adventureRedoStack.popLast() {
                    self.adventureUndoStack.append((dungeonName, level))
                    var changes: [String] = []
                    if next.0 != dungeonName { changes.append(next.0) }
                    if next.1 != level { changes.append("Lv.\(next.1.truncatingRemainder(dividingBy: 1) == 0 ? "\(Int(next.1))" : String(format: "%.1f", next.1))") }
                    self.showRedoFeedback(changes.isEmpty ? "Dungeon" : changes.joined(separator: ", "))
                    self.confirmAdventure(dungeonName: next.0, level: next.1)
                }
            case "?":
                self.showReadyToBeginHelp(dungeonName: dungeonName, level: level)
            case "< Back":
                self.adventureUndoStack.removeAll()
                self.adventureRedoStack.removeAll()
                self.clearTerminal()
                self.startNewGame()
            default: break
            }
        }
    }

    private func showReadyToBeginHelp(dungeonName: String, level: Double) {
        showInlineHelp {
            self.printTitle("Ready to Begin — Help")
            self.print("")
            self.print("  ENTER THE DUNGEON", color: .cyan, bold: true)
            self.printWrapped("Begin your adventure with the current dungeon and difficulty. Your party will enter the first room and the quest begins!", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  DIFFICULTY", color: .cyan, bold: true)
            self.printWrapped("Change the difficulty level. Easy (1) suits small parties, Medium (2) is balanced for four, and Hard (3+) is for veterans. You can also enter custom values like 1.5 for fine-tuning.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  RENAME", color: .cyan, bold: true)
            self.printWrapped("Give your dungeon a custom name. Type anything you like, or leave it to get a randomly generated name.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  UNDO / REDO", color: .cyan, bold: true)
            self.printWrapped("Step back or forward through changes you've made to the dungeon name or difficulty on this screen. Undo/Redo must be enabled in Settings > Gameplay.", indent: 2, color: .dimGreen)
            self.printLink("Settings > Gameplay", to: "gameplay", indent: 4)
            self.print("")
        }
    }

    private func changeDifficultyInline(currentName: String, currentLevel: Double) {
        clearTerminal()
        printTitle("Choose Difficulty")
        printWrapped("Dungeon: \(currentName)", indent: 2, color: .brightGreen)
        print("")
        print("Pick a preset or type a custom level:", color: .dimGreen)
        print("  (0 = trivial, 1 = easy, 2 = medium, 3 = hard, 4+ = brutal)", color: .dimGreen)

        promptTextWithMenu("", options: ["Easy (1)", "Medium (2)", "Hard (3)"])

        closeHandler = { [weak self] in
            self?.confirmAdventure(dungeonName: currentName, level: currentLevel)
        }
        menuHandler = { [weak self] choice in
            guard choice >= 1 && choice <= 3 else { return }
            self?.confirmAdventure(dungeonName: currentName, level: Double(choice))
        }
        inputHandler = { [weak self] text in
            guard let self = self else { return }
            guard let value = Double(text.trimmingCharacters(in: .whitespaces)) else {
                self.print("Enter a number (e.g. 1, 2.5, 3).", color: .yellow)
                self.changeDifficultyInline(currentName: currentName, currentLevel: currentLevel)
                return
            }
            if value < 0 {
                self.print("Even the bravest adventurers must face some challenge! Enter 0 or above.", color: .yellow)
                self.changeDifficultyInline(currentName: currentName, currentLevel: currentLevel)
                return
            }
            self.confirmAdventure(dungeonName: currentName, level: value)
        }
    }

    private func changeDungeonNameInline(currentName: String, currentLevel: Double) {
        clearTerminal()
        printTitle("Rename Dungeon")

        var suggestions: [String] = []
        var pool = dungeonNames.shuffled()
        while suggestions.count < 3 && !pool.isEmpty {
            let name = pool.removeFirst()
            if !suggestions.contains(name) && name != currentName { suggestions.append(name) }
        }

        promptTextWithMenu("Enter a name, or choose one:", options: suggestions.map { String($0.prefix(MenuOption.maxButtonLength)) })

        rerollHandler = { [weak self] in
            self?.changeDungeonNameInline(currentName: currentName, currentLevel: currentLevel)
        }
        closeHandler = { [weak self] in
            self?.confirmAdventure(dungeonName: currentName, level: currentLevel)
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= suggestions.count {
                self.confirmAdventure(dungeonName: suggestions[choice - 1], level: currentLevel)
            }
        }
        inputHandler = { [weak self] name in
            guard let self = self else { return }
            let newName = (name.isEmpty ? currentName : name).capitalized
            if !self.isNameAppropriate(newName) {
                self.print("The DM frowns. Choose a more suitable name.", color: .yellow)
                self.changeDungeonNameInline(currentName: currentName, currentLevel: currentLevel)
                return
            }
            self.confirmAdventure(dungeonName: newName, level: currentLevel)
        }
    }

    private func enterDungeon() {
        clearTerminal()
        gameState = .exploring
        gameTimeMinutes = 360  // 6:00 AM
        partyChatLog = []
        roomsSinceLastSave = 0
        storyScreenActive = false
        DMEngine.shared.clearHistory()
        dmChatLog = []
        logEvent("Entered \(dungeon?.name ?? "the dungeon")", category: "EXPLORE")
        explorationStatusMessage = (welcomeLine(returning: false), .cyan)
        if self.musicEnabled { SoundManager.shared.startMusic(.exploration, preference: self.explorationMelodyChoice) }

        // Auto-light torch if the party has one
        if partyHasTorch() {
            torchLit = true
        }

        showExplorationView()
    }

    // MARK: - Exploration

    /// The map radius/compact mode to use — always the same for a given
    /// map_radius setting and torch state, regardless of which screen is
    /// calling. Radius used to shrink dynamically to fit an *estimated*
    /// available-line count, which changed the map's rendered box width
    /// between redraws (e.g. exploration vs. a full-screen map view) —
    /// since @ sits at a column offset from the left edge that depends on
    /// radius, a changing radius made @ appear to jump around even though
    /// it's always centered within its own box. Fixing the radius to the
    /// user's setting keeps the box — and @'s position in it — identical
    /// every time. Compact mode kicks in above the smallest radius to keep
    /// wider maps from needing much scroll.
    #if os(macOS)
    /// The Mac map pane's size, reported by TerminalView — the map's extent
    /// follows it (see bestMapRadius). userHeight is nil while the pane is
    /// at its default "fit the whole map" size.
    private var macMapPaneWidth: CGFloat = 0

    func macMapPaneChanged(width: CGFloat) {
        guard width > 0, abs(width - macMapPaneWidth) >= 1 else { return }
        macMapPaneWidth = width
        // Redraw if the map on screen was drawn for another size — including
        // the very first map, drawn before the pane had reported its width.
        let now = bestMapRadius()
        guard dungeon != nil, !pinnedMapLines.isEmpty,
              lastMapExtent.map({ $0.0 != now.radius || $0.1 != now.verticalRadius }) ?? true else { return }
        DispatchQueue.main.async { [weak self] in self?.printExplorationMap() }
    }

    /// Dragging the map pane's handle: as many rows as fit in `height`
    /// (each map line `lineHeight` tall, as TerminalView lays them out).
    /// Saved as the Map Length setting, so Settings shows the same value.
    func macFitMapRows(toHeight height: CGFloat, lineHeight: CGFloat) {
        guard dungeon != nil else { return }
        // The pane shows the dotted line under MAP, the grid, "@ here" and
        // the dotted line under it (see TerminalView's Mac map frame).
        var best = Self.macMapRowsRange.lowerBound
        for rows in Self.macMapRowsRange {
            let visible = (2 * rows + 1) + (2 * rows) + 5   // + top edge, title, divider, @ here, bottom edge
            if CGFloat(visible) * lineHeight + 6 <= height { best = rows } else { break }
        }
        macSetMapRows(best)
    }

    func macSetMapRows(_ rows: Int) {
        guard rows != macMapRows else { return }
        macMapRows = rows
        if dungeon != nil && !pinnedMapLines.isEmpty { printExplorationMap() }
    }
    #endif

    /// The (radius, rows) the pinned map was last drawn at.
    private var lastMapExtent: (Int, Int)?

    private func bestMapRadius() -> (radius: Int, verticalRadius: Int, compact: Bool) {
        // Always the configured radius, not effectiveMapRadius() — the
        // viewport SIZE shouldn't depend on the torch; getMapDisplay's own
        // torchLit parameter (passed separately by printExplorationMap())
        // already hides room details when dark. Using effectiveMapRadius()
        // here (0 with no torch) used to make the whole map box shrink to a
        // small fixed size whenever the torch went out, instead of just
        // going dark in place at the same size.
        guard mapRadius > 0 else { return (0, 0, false) }
        #if os(macOS)
        // A resizable macOS window is typically far roomier than either
        // phone orientation — "bigger map" there means an actually wider
        // viewport (more of the dungeon visible at once), not a bigger
        // font stretched to fill the extra space (see mapFontSize, which
        // only bumps up a little for macOS).
        // The map fills its pane's width, and its height is the Map Length
        // setting (which dragging the pane also sets). Always centred on the
        // current room, so a bigger pane shows more around you.
        // Rows: the Mac's Map Length (set in Settings or by dragging the pane).
        let verticalRadius = macMapRows
        var horizontalRadius = min(mapRadius + 6, 10)
        if macMapPaneWidth > 0 {
            // The monospaced font's real advance, so the box never outgrows the pane.
            let font = NSFont.monospacedSystemFont(ofSize: mapFontSize * fontScale, weight: .regular)
            let charWidth = max(1, ("M" as NSString).size(withAttributes: [.font: font]).width)
            let columns = Int((macMapPaneWidth - 24) / charWidth) - 4
            horizontalRadius = max(2, (columns / 5 - 1) / 2)
        }
        return (horizontalRadius, verticalRadius, false)
        #else
        // The "Map Length" setting only ever governs vertical rows (how far
        // up/down you can see) — width is handled automatically here instead,
        // widening to use whatever screen space is actually available rather
        // than staying tied 1:1 to the length setting. Portrait gets the map
        // as a full-width band, so widens generously; landscape gives it its
        // own narrower column (map | icons | text), so widens more modestly
        // to avoid overflowing that column.
        // Landscape's screen is short — a portrait-tuned Length (rows) just
        // doesn't fit, forcing heavy scrolling in a panel that has much less
        // height to work with than portrait's. Landscape resets to a small,
        // fixed vertical extent of its own rather than inheriting whatever
        // Length the player picked for portrait.
        let verticalRadius = isLandscapeOrientation ? 1 : mapRadius
        let horizontalRadius = isLandscapeOrientation ? min(verticalRadius + 1, 4) : min(mapRadius + 2, 5)
        #endif
        // Key/legend always hidden on the small pinned map, regardless of
        // Map Length — it used to only hide once Length went above 1, so the
        // The key/legend IS part of this content (compact: false) — it's
        // just not visible by default. The panel's own height (see
        // mapOnlyLineCount / TerminalView) is clipped to just the map's own
        // rows, so the key sits right below the visible area, reachable by
        // scrolling down rather than being left out of the content entirely.
        return (horizontalRadius, verticalRadius, false)
    }

    /// Row count of just the map box itself (border/title/grid), excluding
    /// the key/legend that follows it in the same scrollable content — used
    /// to size the pinned map panel so only the map is visible by default,
    /// with the key reachable by scrolling down instead of eating into the
    /// panel's default height.
    var mapOnlyLineCount: Int {
        let (radius, verticalRadius, _) = bestMapRadius()
        guard radius > 0, dungeon != nil else { return 0 }
        // The panel's default scroll position skips past the 3-line header
        // (see TerminalView's scroll target), so this only needs to cover
        // what's visible from there: room rows + corridor rows between
        // them, the single "@ here: ..." line, and one more line beyond
        // that — the legend's own opening border ("+---+"), so the map
        // reads as a properly closed-off box rather than cutting off
        // mid-content right after "@ here: ...". The header sits above
        // (reachable by scrolling up) and the rest of the legend/closing
        // border below (reachable by scrolling down) — neither counted here.
        let gridLines = (2 * verticalRadius + 1) + (2 * verticalRadius)
        return gridLines + 2
    }

    /// Redraws the full exploration screen: map + room description + party + menu
    /// Quick save from exploration — wraps performQuickSave
    private func quickSave() {
        performQuickSave()
    }

    /// Help screen for exploration — explains the map, buttons, and gameplay
    /// The map's full symbol key, printed as a wrapped list — used in every
    /// help page that references the minimap, so "what does that symbol
    /// mean" always has a real answer to look up, not just the live map's
    /// own on-screen legend (which only shows symbols currently nearby).
    private func printFullMapLegend() {
        let pairs = Dungeon.mapLegendEntries.map { "\($0.symbol) \($0.label)" }
        printWrapped(pairs.joined(separator: "   "), indent: 2, color: .green)
    }

    // MARK: Bard performances
    //
    // A bard in the party can play for whoever's in the room — a merchant,
    // a trainer, a traveller — once per audience: a Performance roll decides
    // between boos and a standing ovation (and the tips that go with them).
    private var performedRoomKeys = Set<String>()

    private func performKey(_ room: Room) -> String { "\(dungeon?.name ?? "")#\(dungeon?.level ?? 0)#\(room.id)" }

    private func bardAudience(_ room: Room) -> String? {
        if let merchant = room.merchant { return merchant.name }
        if let trainer = room.trainer { return trainer.name }
        if let npc = room.npc, npcsEnabled { return npc.displayName }
        return nil
    }

    private func bardPerform(_ bard: Character, audience: String, room: Room, returnTo: (() -> Void)? = nil) {
        performedRoomKeys.insert(performKey(room))
        clearTerminal()
        printExplorationMap()
        print("")
        printTitle("A Tune for \(audience)")
        let mod = bard.skillModifier(for: .performance)
        let roll = Dice.d20()
        let total = roll + mod
        print("  \(bard.name) strikes up a tune. Performance: d20[\(roll)] + \(mod) = \(total)", color: .cyan)
        print("")
        let tips: Int
        let reaction: String
        switch total {
        case ..<8:
            tips = 0
            reaction = ["\(audience) winces and edges away. Perhaps another day.", "A string snaps mid-verse. Nobody claps."].randomElement()!
        case 8..<13:
            tips = Int.random(in: 1...5)
            reaction = ["\(audience) taps along politely and tosses over a coin or two.", "A few polite nods, and a small clink of coins."].randomElement()!
        case 13..<18:
            tips = Int.random(in: 6...12)
            reaction = ["\(audience) laughs, sings the chorus and pays for another.", "Toes tap, spirits lift — the hat fills nicely."].randomElement()!
        default:
            tips = Int.random(in: 13...25)
            reaction = ["\(audience) is moved to tears and presses a purse into \(bard.name)'s hand!", "A standing ovation — even the rats stop to listen."].randomElement()!
        }
        printWrapped(reaction, indent: 2, color: tips > 0 ? .brightGreen : .yellow)
        if tips > 0 {
            bard.gold += tips
            print("  +\(tips) gold for \(bard.name).", color: .yellow)
            SoundManager.shared.playCrowdCheer()
        } else {
            SoundManager.shared.playCrowdJeer()
        }
        advanceTime(20)
        logEvent("\(bard.name) performed for \(audience) (+\(tips) gold)", category: "EXPLORE")
        waitForContinueWithTimeout(multiplier: 1.0) { [weak self] in
            if let back = returnTo { back() } else { self?.showExplorationView() }
        }
    }

