    /// Whether the CURRENT room is visible right now — either because the
    /// party's own torch is lit, or because the room itself is torchlit
    /// (wall-mounted torches). Gates room-local description/exits/NPC/loot
    /// visibility. Broader visibility (map radius) stays keyed on `torchLit`
    /// alone — a lit passage doesn't grant sight into neighbouring rooms.
    var roomIsLit: Bool {
        torchLit || (dungeon?.currentRoom?.isTorchlit ?? false)
    }

    func showExplorationView() {
        linkReturnSnapshot = nil
        guard let dungeon = dungeon, let room = dungeon.currentRoom else { return }
        checkForMonsterRespawn(room: room)
        checkForMonsterWander(room: room)

        // Just DM mode — route to conversational exploration
        if isJustDMActive {
            showJustDMExploration()
            return
        }

        guard !checkAndShowSideQuestCompletion() else { return }

        SpeechEngine.shared.stop()
        clearTerminal()
        suppressAutoScroll = false

        // Dynamically size the map to fill screen without scrolling
        _ = dungeon
        checkQuestDeadline()
        printExplorationMap()   // same map everywhere (fills the Mac pane's width)
        // The date and time, and — once someone's said when — the quest's deadline.
        print("  ☼ \(formattedGameTime())", color: .cyan, bold: true)
        if let line = questDeadlineLine() { print("  \(line)", color: .dimGreen) }
        if !torchLit {
            if partyHasTorch() {
                print("  Torch unlit — illuminate it to see further!", color: .yellow)
            } else {
                print("  No torch — visibility reduced!", color: .yellow)
            }
        } else if torchTurnsRemaining > 0 && torchTurnsRemaining <= 5 {
            print("  Torch flickering... (\(torchTurnsRemaining) rooms left)", color: .yellow)
        }
        print("")

        // Where you are: the place, the level, and the floor where there are several.
        print("\(dungeon.name) · Level \(dungeon.level)\(dungeon.hasVerticalConnections ? " · Floor \(dungeon.currentFloor)" : "")", color: .cyan)

        // Room description — dim when the room itself isn't lit
        if roomIsLit {
            print(room.name, color: .brightGreen, bold: true)
            printWrapped(room.roomDescription)
            if room.isTorchlit && !torchLit {
                print("Wall-mounted torches keep this passage lit.", color: .yellow)
            }
        } else {
            print(room.name, color: .dimGreen, bold: true)
            print("It's too dark to see clearly...", color: .gray)
        }

        if !room.cleared && room.encounter != nil {
            print("You sense danger here...", color: .red)
        } else if roomIsLit, room.cleared, room.encounter == nil, !room.defeatedMonsterNames.isEmpty {
            // A cleared room describes its own aftermath every time it's
            // revisited, not just the moment the fight ended — cleared here
            // (room.encounter == nil) means nothing new has moved in since.
            print("  \(defeatedMonsterSummary(room.defeatedMonsterNames))", color: .dimGreen)
        }
        // NPC presence — harder to notice without light
        if let npc = room.npc, npcsEnabled {
            if roomIsLit {
                print("\(npc.displayName) is here.", color: .cyan)
            } else if Bool.random() {
                // 50% chance to notice NPC in the dark
                print("You hear someone nearby...", color: .cyan)
            }
        }
        if roomIsLit && !room.treasure.isEmpty && room.cleared {
            print("You see treasure on the ground.", color: .yellow)
        }
        if roomIsLit && !room.droppedItems.isEmpty {
            let names = room.droppedItems.map { $0.name }.joined(separator: ", ")
            print("Items on the floor: \(names)", color: .yellow)
        }

        if roomIsLit {
            let exitList = room.exits.keys.map { room.isLockedShut($0) ? "\($0.rawValue) (locked)" : $0.rawValue }.joined(separator: ", ")
            if !exitList.isEmpty {
                print("Exits: \(exitList)", color: .dimGreen)
            }
        } else {
            print("Exits: You can feel openings...", color: .gray)
        }

        print("")

        // Multiplayer indicator
        if isMultiplayer {
            print("MULTIPLAYER", color: .magenta, bold: true)
        }

        // Party status
        let levelStr = dungeon.level > 0 ? "Level \(dungeon.level) | " : ""
        if gameTimeLimit > 0 {
            let remaining = max(0, gameTimeLimit - gameTimeMinutes)
            let remainStr = formatTimeRemaining(remaining)
            let timeColor: TerminalColor = remaining > 180 ? .dimGreen : (remaining > 60 ? .yellow : .red)
            print("\(levelStr)\(formattedGameTime())  ⏱ \(remainStr)", color: timeColor)
        } else {
            print("\(levelStr)\(formattedGameTime())", color: .dimGreen)
        }
        let localIds = localControlledCharIds
        let maxNameLen = party.map { $0.name.count }.max() ?? 10
        for char in party {
            let padded = char.name.padding(toLength: maxNameLen, withPad: " ", startingAt: 0)
            let hp = "L\(char.level) \(char.currentHP)/\(char.maxHP) HP"
            let poisonTag = char.isPoisoned ? " ☠" : ""
            let isYours = localIds.contains(char.id)
            let youTag = isYours ? " ◀" : ""
            let color: TerminalColor = char.isPoisoned ? .magenta : (isYours ? .brightGreen : .cyan)
            print(" \(padded)  \(hp)\(poisonTag)\(youTag)", color: color)
        }
        // Poison warning if any character is poisoned
        if party.contains(where: { $0.isPoisoned }) {
            let poisonedNames = party.filter { $0.isPoisoned }.map { $0.name }.joined(separator: ", ")
            print(" ☠ Poisoned: \(poisonedNames) — use Antidote, potion, or rest", color: .magenta)
        }
        print("")

        // Check for encounter — darkness gives a chance to sneak past
        if !room.cleared, let encounter = room.encounter {
            if !roomIsLit && Int.random(in: 1...100) <= 30 {
                room.cleared = true
                room.encounter = nil
                logEvent("Sneaked past enemies in \(room.name) (darkness)", category: "EXPLORE")
                logMultiplayerAction("The party crept past enemies in the dark")
                explorationStatusMessage = ("You creep past the enemies in darkness...", .dimGreen)
                showExplorationView()
                return
            }
            if !roomIsLit {
                print("You stumble in the dark!", color: .red)
                print("")
            }
            print("Enemies ahead!", color: .red, bold: true)
            startCombat(encounter: encounter)
            return
        }

        // Trigger trap in trap rooms (once per room)
        if !room.trapTriggered && room.roomType == .trap {
            room.trapTriggered = true
            room.cleared = true
            triggerTrap(in: room)
            return
        }

        // Show transient status message if set
        if let msg = explorationStatusMessage {
            print("  \(msg.text)", color: msg.color)
            print("")
            explorationStatusMessage = nil
        }

        // Build direction exits for the D-pad
        var exits: [Direction: Bool] = [:]
        var secured: Set<Direction> = []
        if roomIsLit {
            for direction in Direction.allCases {
                let hasExit = room.exits[direction] != nil
                let isSecured = room.secured.contains(direction)
                let isLocked = room.isLockedShut(direction)
                // Barricaded doors are disabled until long-pressed open; locked
                // doors stay tappable (tapping opens the key/pick/force screen)
                // but show the same "can't just walk through" icon.
                exits[direction] = hasExit && !isSecured
                if hasExit && (isSecured || isLocked) { secured.insert(direction) }
            }
        } else {
            // Torch off: show all directions as available (uncertain) — grey on D-pad
            for direction in Direction.allCases {
                exits[direction] = true
            }
        }
        DispatchQueue.main.async { self.securedExits = secured }

        // Build menu options — contextual actions at top, persistent buttons
        // at bottom in fixed relative order so positions stay stable.
        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        // --- Top row: Actions + contextual ---
        menuOpts.append(MenuOption("Actions"))
        actions.append { [weak self] in self?.showActionsMenu() }

        // Self-heal a stale invalid combination from before Dungeon.generateDungeon()
        // stopped letting an armoury's merchant chance and its room-type encounter
        // roll independently — a room whose text promises a merchant should never
        // stay blocked behind an uncleared fight the description never mentioned.
        // Runs every time this room's menu builds, so it also repairs dungeons
        // already generated (or saved) before that fix existed, not just new ones.
        if room.merchant != nil, room.encounter != nil, !room.cleared {
            room.encounter = nil
        }

        // Every armoury/forge room is a merchant shop, full stop — not
        // conditional on whether it already had a merchant. An earlier
        // version of this self-heal only added the merchant/NPC when
        // room.merchant was ALREADY non-nil, which does nothing for a room
        // that predates the merchant guarantee entirely (merchant still
        // nil) — exactly the case for any armoury generated before this
        // fix existed, including ones whose stored flavour text already
        // happens to mention a merchant (one of the random description
        // variants rolled at creation, before this was made unconditional).
        // Retrofit unconditionally so "a merchant has set up shop here" is
        // never a lie, no matter how old the save.
        dungeon.ensureTeleportPads()   // older maps had one pad or none
        if let villain = mainQuest?.villain { dungeon.crownFinalGuardian(villain: villain) }
        if room.roomType == .armory {
            if room.merchant == nil {
                seedNameRegistry()
                room.merchant = Merchant.random(tier: MerchantTier.forDungeonLevel(dungeon.level))
            }
            if room.roomDescription != Room.armouryMerchantVariant {
                room.roomDescription = Room.armouryMerchantVariant
            }
            // Saves from the last few builds put a Dwarven Smith in every
            // armoury — keep about one in three (settled by the room, so it
            // happens once) and give the rest a merchant of their own.
            if let npc = room.npc, npc.type == .dwarvenSmith, room.id % 3 != 0 {
                room.npc = nil
                seedNameRegistry()
                room.merchant = Merchant.random(tier: MerchantTier.forDungeonLevel(dungeon.level))
            }
            // Where the smith stays, they and the shopkeeper are one person.
            if let npc = room.npc, npc.type == .dwarvenSmith, room.merchant != nil, room.merchant?.name != npc.displayName {
                room.merchant?.name = npc.displayName
            }
        }

        // Merchant present in the room itself (shop room, or an armoury a merchant
        // has set up shop in) — was previously gated on `.shop` only, which left
        // armoury-room merchants mentioned in the room text but unreachable.
        if room.merchant != nil, (room.cleared || room.encounter == nil) {
            // Distinct tint so it reads as an unmistakable "there's a
            // merchant here" signal rather than blending into the regular
            // green action buttons — a merchant genuinely present in the
            // room (guaranteed for .shop, and text-synced for .armory —
            // see Dungeon.generateDungeon) should never be easy to miss.
            menuOpts.append(MenuOption("Visit Merchant", tint: .cyan))
            actions.append { [weak self] in
                guard let self = self else { return }
                if self.roomIsLit { self.visitShop() } else { self.attemptInTheDark("the merchant's wares") { self.visitShop() } }
            }
        }

        if room.trainer != nil, (room.cleared || room.encounter == nil) {
            menuOpts.append(MenuOption("Visit Gym"))
            actions.append { [weak self] in
                guard let self = self else { return }
                if self.roomIsLit { self.visitGym() } else { self.attemptInTheDark("the gym") { self.visitGym() } }
            }
        }

        if let pid = room.puzzleId, !room.riddleResolved, (room.cleared || room.encounter == nil), let puzzle = PuzzleBank.puzzle(id: pid) {
            menuOpts.append(MenuOption("Solve Puzzle"))
            actions.append { [weak self] in
                guard let self = self else { return }
                if self.roomIsLit { self.presentPuzzle(puzzle, room: room) } else { self.attemptInTheDark("the inscription") { self.presentPuzzle(puzzle, room: room) } }
            }
        }

        if let idx = room.riddleIndex, !room.riddleResolved, (room.cleared || room.encounter == nil) {
            menuOpts.append(MenuOption("Solve Riddle"))
            actions.append { [weak self] in
                guard let self = self else { return }
                if self.roomIsLit { self.presentRiddle(index: idx, room: room) } else { self.attemptInTheDark("the inscription") { self.presentRiddle(index: idx, room: room) } }
            }
        }

        if let vMethod = room.verticalMethod, let vDestId = room.verticalDestinationRoomId,
           let vDestRoom = dungeon.rooms[vDestId], (room.cleared || room.encounter == nil) {
            let goingDown = room.verticalDirection == "down"
            let hasRope = party.flatMap { $0.inventory }.contains { $0.name.hasPrefix("Rope") }
            let label: String
            let met: Bool
            switch vMethod {
            case "stairs":
                // Always usable either way — no risk, no gear needed.
                label = goingDown ? "Descend the Stairs" : "Climb the Stairs"
                met = true
            case "rope":
                if goingDown {
                    // Going down never truly needs a rope — you can always
                    // jump, just at the cost of a landing injury without one.
                    label = hasRope ? "Climb Down the Rope" : "Jump Down (risk injury)"
                    met = true
                } else {
                    // Climbing UP a rope-only connection genuinely needs the
                    // rope in hand — no free equivalent going this direction.
                    label = "Climb Up the Rope"
                    met = hasRope
                    if !met, let hintRoom = room.verticalRopeHintRoomName {
                        print("  You'll need rope to climb up here. Try the \(hintRoom).", color: .yellow)
                    } else if !met {
                        print("  You'll need rope to climb up here.", color: .yellow)
                    }
                }
            default: // "levitation" — legacy method from older saves; no longer generated
                label = goingDown ? "Levitate Down" : "Levitate Up"
                met = party.contains { $0.spellSlots.level1Current > 0 || $0.spellSlots.level2Current > 0 }
            }
            menuOpts.append(MenuOption(label, isDisabled: !met))
            actions.append { [weak self] in
                guard let self = self, self.roomIsLit, met else { return }
                self.useVerticalConnection(method: vMethod, from: room, to: vDestRoom, tookInjuryRisk: vMethod == "rope" && goingDown && !hasRope)
            }
        }

        // Talk to NPC — lives on the D-pad (SE corner) only now; it used to
        // ALSO be a plain menu button, duplicating that icon, as a hedge
        // against the D-pad icon "sometimes just doesn't render" (see the
        // still-open investigation into vanished D-pad icons). Removed per
        // explicit request — if that rendering issue resurfaces, restoring
        // this fallback button is the quick fix. Without a torch, NPCs are
        // harder to find (only show if already spoken to).
        // NOTE: these dpad* assignments are deliberately synchronous, matching
        // dpadSearchHandler/dpadListenHandler just below — showExplorationView
        // already mutates other @Published state (terminalLines, menuOpts)
        // synchronously in this same call, so wrapping ONLY these in
        // DispatchQueue.main.async deferred them to the next run-loop tick,
        // one frame behind everything else. That's the root cause of the
        // long-reported "D-pad icons sometimes just don't render" bug: the
        // view could render in the gap between the two, showing a stale or
        // missing icon for a frame. See the still-open investigation task.
        if let npc = room.npc, npcsEnabled, (roomIsLit || npc.hasBeenTalkedTo) {
            let talkLabel = npc.hasBeenTalkedTo ? "Talk" : "Speak to \(npc.type.rawValue.components(separatedBy: " ").last ?? "Stranger")"
            self.dpadNPCLabel = talkLabel
            self.dpadNPCHandler = { [weak self] in self?.talkToNPC() }
        } else {
            self.dpadNPCLabel = nil
            self.dpadNPCHandler = nil
        }

        // Teleport pad — roundel-target icon sharing the D-pad's NW corner
        // slot with the Search Room icon (see DirectionPadView — Search is
        // still reachable as a full menu button, so bumping its shortcut
        // icon here costs nothing). Always set both branches — otherwise a
        // stale teleport icon from a previous room lingers into one with no
        // pad.
        if teleportPadsEnabled, let destId = room.teleportDestinationRoomId, let destRoom = dungeon.rooms[destId],
           (room.cleared || room.encounter == nil) {
            self.dpadTeleportHandler = { [weak self] in
                guard let self = self else { return }
                if self.roomIsLit {
                    self.stepOnPad(from: room, to: destRoom)
                } else {
                    // In the dark it's a fumble, not a silent no-op.
                    self.attemptInTheDark("the teleport pad") { [weak self] in self?.stepOnPad(from: room, to: destRoom) }
                }
            }
        } else {
            self.dpadTeleportHandler = nil
        }

        // Torch toggle — shown on the D-pad (SW corner) as a quick-access
        // icon, alongside the existing "Douse Torch"/"Illuminate" entry in
        // the Actions submenu (not removed — some players prefer the list).
        if torchLit {
            self.dpadTorchLabel = "Douse"
            self.dpadTorchHandler = { [weak self] in self?.douseTorch() }
        } else if partyHasTorch() {
            self.dpadTorchLabel = "Illuminate"
            self.dpadTorchHandler = { [weak self] in self?.lightTorch() }
        } else {
            self.dpadTorchLabel = nil
            self.dpadTorchHandler = nil
        }

        // Search Room / Listen — shown on the D-pad (NW/NE corners) as
        // quick-access icons; always available during exploration.
        // searchRoom()/listenAtDoors() are full "show a result, tap to
        // continue" screens (same as the Actions-menu list items they
        // mirror) — waitForContinue()/showMenu() reset directionExits as
        // part of clearing every other screen's leftover state, which is
        // fine for a deliberate screen change but made the whole D-pad
        // visibly vanish and the button layout jump for what's meant to be
        // a quick, in-place action. runPreservingDirectionExits() re-fills
        // it right after IF the action left it empty, keeping the D-pad in
        // place through the result screen instead.
        dpadSearchHandler = { [weak self] in
            guard let self = self else { return }
            self.runPreservingDirectionExits { self.searchRoom() }
        }
        dpadListenHandler = { [weak self] in
            guard let self = self else { return }
            self.runPreservingDirectionExits { self.listenAtDoors() }
        }

        // --- Middle row: Inventory + Party Status ---
        menuOpts.append(MenuOption("Inventory"))
        actions.append { [weak self] in self?.showInventory() }

        menuOpts.append(MenuOption("Party Status"))
        actions.append { [weak self] in self?.showPartyStatus() }

        // (A bard's "Play a Tune" lives in conversations now — see talkToNPC —
        // not on the main buttons, where it turned up in almost every room.)

        // --- Bottom row: Help ---
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showExplorationHelp() }

        // No always-on "< Leave Game" button (it put people off): leaving
        // takes a deliberate step — the ✕ by the input line (closeHandler
        // below), or the link on this screen's ? help page.

        // --- Multiplayer ---
        if isMultiplayer {
            menuOpts.append(MenuOption("Pass Turn", tint: .cyan))
            actions.append { [weak self] in self?.multiplayerPassTurn() }
        }

        showMenuWithDirections(menuOpts, exits: exits)

        directionHandler = { [weak self] direction in
            self?.move(direction)
        }
        directionLongPressHandler = { [weak self] direction in
            guard let self = self, let room = self.dungeon?.currentRoom else { return }
            guard room.exits[direction] != nil else { return }

            // Locked-but-shut doors are handled by tapping (opens the door
            // interaction screen); a locked-but-open door can be relocked by
            // long-pressing again, if the party still holds the matching key.
            if let lockId = room.doorLockIds[direction] {
                if room.isLockedShut(direction) { return }
                guard self.party.flatMap({ $0.inventory }).contains(where: { $0.keyForDoorId == lockId }) else {
                    self.explorationStatusMessage = ("You'd need the key to lock this again.", .dimGreen)
                    self.showExplorationView()
                    return
                }
                room.openedLocks.remove(direction)
                if let neighborId = room.exits[direction], let neighbor = self.dungeon?.rooms[neighborId] {
                    neighbor.openedLocks.remove(direction.opposite)
                }
                self.advanceTime(5)
                self.logEvent("Locked the \(direction.rawValue) door in \(room.name) again", category: "EXPLORE")
                self.explorationStatusMessage = ("Locked \(direction.rawValue.lowercased()) door again. 🔒", .cyan)
                self.showExplorationView()
                return
            }

            if room.secured.contains(direction) {
                // Unsecure
                room.secured.remove(direction)
                self.advanceTime(3)
                self.logEvent("Unsecured \(direction.rawValue) exit in \(room.name)", category: "EXPLORE")
                self.explorationStatusMessage = ("Opened \(direction.rawValue.lowercased()) door.", .brightGreen)
            } else {
                // Secure
                room.secured.insert(direction)
                self.advanceTime(5)
                self.logEvent("Secured \(direction.rawValue) exit in \(room.name)", category: "EXPLORE")
                self.explorationStatusMessage = ("Barricaded \(direction.rawValue.lowercased()) door. 🔒", .yellow)
            }
            self.showExplorationView()
        }
        dpadCenterLabel = "Rest"
        dpadCenterHandler = { [weak self] in
            self?.rest()
        }
        dpadCenterLongPressHandler = { [weak self] in
            self?.performRest(isLongRest: true, fast: true)
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
        // Long-press handlers for exploration menu — fall through to normal tap for unhandled
        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            // Unhandled long-press → treat as normal tap
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }

        // Close icon → if just saved, go straight to quit confirmation; otherwise Save/Quit menu
        closeHandler = { [weak self] in self?.leaveExplorationTapped() }

        // Text input → enter chat mode (set after async to override showMenuWithDirections)
        inputHandler = { [weak self] input in
            guard let self = self else { return }
            let text = input.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !text.isEmpty else { return }
            // Pre-seed chat with the user's message, then show chat
            self.showPartyChat(initialMessage: text)
        }
        DispatchQueue.main.async { self.awaitingTextInput = true }

        resetIdleTimer()
    }

    // MARK: - Dropped Items Pickup

    private func pickUpDroppedItems() {
        guard let room = dungeon?.currentRoom, !room.droppedItems.isEmpty else {
            showExplorationView()
            return
        }
        let item = room.droppedItems[0]
        room.droppedItems.removeFirst()
        showItemPickupMenu(item: item, source: "Left on the floor") { [weak self] in
            guard let self = self else { return }
            if let room = self.dungeon?.currentRoom, !room.droppedItems.isEmpty {
                self.pickUpDroppedItems()
            } else {
                self.showExplorationView()
            }
        }
    }

    // MARK: - Torch Mechanics

    /// Map colour based on torch state and remaining life.
    /// Flickers on activation (first few turns), steady for most, dims over last 10%.
    var torchMapColor: TerminalColor {
        // Lit is lit — always green, full stop. A flicker-to-gray warning
        // for low torch life used to live here too, but that read as the
        // map randomly going gray/broken even while genuinely illuminated;
        // the "Torch flickering... (N rooms left)" text already covers that
        // warning without messing with the map's own colour.
        guard torchLit else { return .gray }
        return .brightGreen
    }

    /// Find the best torch to light (most life remaining)
    private func findBestTorch() -> (Character, Item)? {
        // If an actor override is set (Actions > Acting As) and they're
        // actually carrying a usable torch, illuminate with THEIRS
        // specifically rather than automatically whoever has the
        // longest-lasting one in the party.
        if let overrideChar = actingOverrideCharacter,
           let torch = overrideChar.inventory.first(where: { $0.isTorch && ($0.torchLife ?? Item.torchFullLife) > 0 }) {
            return (overrideChar, torch)
        }
        var best: (Character, Item)? = nil
        for char in party {
            for item in char.inventory where item.isTorch {
                let life = item.torchLife ?? Item.torchFullLife
                if life > 0, best == nil || life > (best!.1.torchLife ?? Item.torchFullLife) {
                    best = (char, item)
                }
            }
        }
        return best
    }

    /// Save remaining life back to the active torch item
    private func syncTorchLife() {
        guard let torchId = activeTorchId, torchTurnsRemaining > 0 else { return }
        for char in party {
            if let idx = char.inventory.firstIndex(where: { $0.id == torchId }) {
                char.inventory[idx].torchLife = torchTurnsRemaining
                return
            }
        }
    }

    private func lightTorch() {
        guard let (holder, torch) = findBestTorch() else {
            explorationStatusMessage = ("No torch to illuminate!", .red)
            showExplorationView()
            return
        }
        activeTorchId = torch.id
        torchHolderId = holder.id
        torchTurnsRemaining = torch.torchLife ?? Item.torchFullLife
        torchLit = true
        logEvent("Lit a torch (\(torch.torchLifeDescription ?? "12h") left)", category: "EXPLORE")
        explorationStatusMessage = ("You illuminate a torch. The shadows retreat.", .yellow)
        showExplorationView()
    }

    private func douseTorch() {
        syncTorchLife()
        torchLit = false
        logEvent("Doused torch (\(torchTurnsRemaining / 60)h \(torchTurnsRemaining % 60)m left)", category: "EXPLORE")
        torchTurnsRemaining = 0
        activeTorchId = nil
        torchHolderId = nil
        explorationStatusMessage = ("You extinguish the torch. Darkness closes in. Monsters may not notice you as easily, but you might stumble into things.", .gray)
        showExplorationView()
    }

    /// Current game context for hint weighting
    private var currentHintContext: String {
        switch gameState {
        case .combat: return "combat"
        case .exploring: return "exploration"
        case .mainMenu: return "settings"
        default: return "exploration"
        }
    }

    /// Occasionally show a gameplay tip after rest or combat
    private func maybeShowTip() {
        guard tipCooldown <= 0 else {
            tipCooldown -= 1
            return
        }
        guard Int.random(in: 1...100) <= 15 else { return }

        if let result = FAQData.contextWeightedTip(context: currentHintContext, excluding: shownTipIndices) {
            shownTipIndices.insert(result.index)
            tipCooldown = 5
            print("")
            print("  Tip: \(result.tip)", color: .dimGreen)
        } else {
            shownTipIndices.removeAll()
        }
    }

    /// Show a random gameplay hint in an alert-style popup, then return to previous screen via callback
    private func showRandomHint(onBack: @escaping () -> Void, context: String? = nil) {
        let ctx = context ?? currentHintContext
        if let result = FAQData.contextWeightedTip(context: ctx, excluding: shownTipIndices) {
            shownTipIndices.insert(result.index)

            clearTerminal()
            printTitle("Hint")
            print("")
            printWrapped(result.tip, indent: 2, color: .yellow)
            print("")

            showMenu(["Another Hint"])
            menuHandler = { [weak self] choice in
                if choice == 1 { self?.showRandomHint(onBack: onBack, context: context) }
            }
            closeHandler = { [weak self] in
                self?.closeHandler = nil
                onBack()
            }
        } else {
            shownTipIndices.removeAll()
            onBack()
        }
    }

    private func tickTorch() {
        guard torchLit else { return }
        torchTurnsRemaining -= 10  // 10 minutes per exploration move

        // Low torch warning
        if torchTurnsRemaining > 0 && torchTurnsRemaining <= 60 && torchTurnsRemaining % 30 == 0 {
            let mins = torchTurnsRemaining
            print("")
            print("  Your torch is burning low — about \(mins) minutes left.", color: .yellow)
        }

        if torchTurnsRemaining <= 0 {
            torchLit = false
            torchTurnsRemaining = 0
            // Consume the burned-out torch
            if let torchId = activeTorchId {
                for char in party {
                    if let idx = char.inventory.firstIndex(where: { $0.id == torchId }) {
                        char.inventory.remove(at: idx)
                        break
                    }
                }
            }
            activeTorchId = nil
            torchHolderId = nil
            print("")
            print("  Your torch sputters and goes out!", color: .red)
            logEvent("Torch burned out", category: "EXPLORE")
            printTorchHint()
        }
    }

    /// Called at combat start — small chance of torch blowing out
    func checkTorchBlowout() {
        guard torchLit else { return }
        let roll = Int.random(in: 1...20)
        if roll <= 1 {
            syncTorchLife()
            torchLit = false
            // Torch item stays — just needs relighting
            print("")
            print("  A gust of wind blows out your torch!", color: .red)
            logEvent("Torch blown out in combat", category: "COMBAT")
            printTorchHint()
        }
    }

    /// Random torch events during exploration (~3% chance per room)
    private func checkTorchEvent() {
        guard torchLit, torchTurnsRemaining > 60 else { return }
        let roll = Int.random(in: 1...100)
        guard roll <= 3 else { return }

        let event = Int.random(in: 1...100)
        if event <= 25 {
            // Gust of wind — torch goes out
            syncTorchLife()
            torchLit = false
            print("")
            print("  A strange gust of wind sweeps through the corridor!", color: .red)
            print("  Your torch goes out!", color: .red)
            logEvent("Torch blown out by gust", category: "EXPLORE")
            printTorchHint()
        } else if event <= 90 {
            // Flicker warning — cosmetic only
            let messages = [
                "Your torch flickers ominously in a draft...",
                "The flame dips low for a moment, then recovers.",
                "Shadows dance wildly as your torch sputters briefly.",
                "A cold draught makes your torch gutter and hiss.",
            ]
            print("")
            print("  \(messages.randomElement()!)", color: .yellow)
        } else {
            // Trip and drop — torch goes out
            syncTorchLife()
            torchLit = false
            let messages = [
                "You stumble on loose rubble and drop the torch! It goes out.",
                "Something brushes your arm — you fumble the torch and it dies.",
                "A loose flagstone trips you. The torch hits the ground and snuffs out.",
            ]
            print("")
            print("  \(messages.randomElement()!)", color: .red)
            logEvent("Torch dropped", category: "EXPLORE")
            printTorchHint()
        }
    }

    /// Hint to check inventory after torch goes out
    private func printTorchHint() {
        if partyHasTorch() {
            print("  Search your packs — you have another torch!", color: .yellow)
        } else {
            print("  You're out of torches. Find one at a shop.", color: .yellow)
        }
    }

    func move(_ direction: Direction) {
        guard let dungeon = dungeon, let room = dungeon.currentRoom else { return }

        // Locked doors need a key, lockpicking, or force before they'll budge
        if room.isLockedShut(direction) {
            showLockedDoor(direction: direction, room: room)
            return
        }

        // Cannot move through barricaded doors — must unsecure first. Falls
        // through to showExplorationView() below (not an early return) —
        // handleDirectionChoice() already wiped the control box before
        // calling here, and nothing else in this branch was restoring it.
        if room.secured.contains(direction) {
            explorationStatusMessage = ("That door is barricaded! Long-press the direction or use Secure from Actions to unsecure it first.", .yellow)
            showExplorationView()
            return
        }

        let result = dungeon.move(direction: direction)
        if result.success {
            advanceTime(10)
            tickTorch()
            checkTorchEvent()
            if let room = dungeon.currentRoom {
                logEvent("Moved \(direction.rawValue) to \(room.name)", category: "EXPLORE")
                logMultiplayerAction("The party entered \(room.name)")
            }
            autosaveIfNeeded()
        } else {
            if !torchLit {
                let darkMessages = [
                    "You grope in the darkness but find only a cold stone wall.",
                    "Your hands meet solid rock. No passage this way.",
                    "You stumble forward in the dark... nothing. Just a dead end.",
                    "The wall is unyielding. Try another direction.",
                ]
                explorationStatusMessage = (darkMessages.randomElement()!, .yellow)
            } else {
                print(result.message, color: .yellow)
            }
        }
        showExplorationView()
    }

    /// Step through a teleport pad — see Dungeon.generateDungeon()'s
    /// placement (single-way or bidirectional) and Room.teleportDestinationRoomId.
    /// A pad: most just hop across the level; a deep pad (see
    /// Dungeon.deepPadRoomId) asks whether to ride it down a level instead.
    private func stepOnPad(from room: Room, to destination: Room) {
        guard let dungeon = dungeon, dungeon.deepPadRoomId == room.id else {
            useTeleportPad(from: room, to: destination); return
        }
        let next = dungeon.level + 1
        SoundManager.shared.playTeleport()
        clearTerminal()
        printTitle("A Deep Pad")
        print("")
        printLines(Self.deepPadArt("v"), color: .cyan)
        print("")
        printWrapped("This pad glows a deeper, colder blue than the others, and the runes round its rim point down, not across.", indent: 2, color: .cyan)
        print("")
        printWrapped("It could carry you down to Level \(next) of \(dungeon.name) — past this level's guardian, into harder fights and better treasure. Or it will hop you across to \(destination.name) like any other pad.", indent: 2, color: .brightGreen)
        print("")
        printWrapped("Worth saving first: there's no pad back up.", indent: 2, color: .dimGreen)
        let opts = ["Ride It Down to Level \(next)", "Hop Across to \(destination.name)", "Leave It"]
        showMenuOptions([MenuOption(opts[0]), MenuOption(opts[1]), MenuOption(opts[2], isDefault: true)])
        closeHandler = { [weak self] in self?.showExplorationView() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: self.rideDeepPad(from: room)
            case 2: self.useTeleportPad(from: room, to: destination)
            default: self.showExplorationView()
            }
        }
    }

    private static func deepPadArt(_ g: String) -> [String] {
        let top = "      .-\"\"\"-."
        let row1 = "     /  " + g + " " + g + " \\"
        let row2 = "    | " + g + "  " + g + "  " + g + " |"
        let row3 = "     \\  " + g + " " + g + " /"
        return [top, row1, row2, row3, "      '-...-'"]
    }

    private func rideDeepPad(from room: Room) {
        guard let dungeon = dungeon else { return }
        let next = dungeon.level + 1, name = dungeon.name
        SoundManager.shared.playTeleport()
        logEvent("Rode the deep pad in \(room.name) down to Level \(next)", category: "EXPLORE")
        logMultiplayerAction("The party rode a deep pad down to Level \(next)")
        let spinFrames = ["v", "V", "|", "v", "V", "|", "v", "V", "|", "v"]
        for (i, glyph) in spinFrames.enumerated() {
            DispatchQueue.main.asyncAfter(deadline: .now() + Double(i) * 0.1) { [weak self] in
                guard let self = self else { return }
                self.clearTerminal()
                self.printTitle("A Deep Pad")
                self.print("")
                self.printLines(Self.deepPadArt(glyph), color: .cyan)
            }
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + Double(spinFrames.count) * 0.1) { [weak self] in
            self?.continueToNextLevel(next, dungeonName: name, viaDeepPad: true)
        }
    }

    private func useTeleportPad(from room: Room, to destination: Room) {
        guard dungeon != nil else { return }
        SoundManager.shared.playTeleport()
        clearTerminal()
        printTitle("Teleport Pad")
        print("")
        // A brief spinning-glyph "beam" effect — the pad visibly winds up
        // before the jump instead of the room just silently changing.
        let spinFrames = ["/", "-", "\\", "|", "/", "-", "\\", "|"]
        for (i, glyph) in spinFrames.enumerated() {
            DispatchQueue.main.asyncAfter(deadline: .now() + Double(i) * 0.08) { [weak self] in
                guard let self = self else { return }
                self.clearTerminal()
                self.printTitle("Teleport Pad")
                self.print("")
                self.printLines(["      .-\"\"\"-.", "     /  \(glyph) \(glyph) \\", "    | \(glyph)  \(glyph)  \(glyph) |", "     \\  \(glyph) \(glyph) /", "      '-...-'"], color: .cyan)
            }
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + Double(spinFrames.count) * 0.08) { [weak self] in
            guard let self = self, let dungeon = self.dungeon else { return }
            dungeon.currentRoomId = destination.id
            // Normal step-by-step movement (Dungeon.move()) always does this
            // on arrival — a pad jump skipped both, which is exactly why the
            // map came up "No map available" on arrival: the destination had
            // never been marked visited, and nothing around it had ever been
            // revealed.
            destination.visited = true
            dungeon.expandIfNeeded(from: destination)
            self.advanceTime(5)
            self.tickTorch()
            self.checkTorchEvent()
            self.logEvent("Teleported from \(room.name) to \(destination.name)", category: "EXPLORE")
            self.logMultiplayerAction("The party stepped through a teleport pad into \(destination.name)")
            self.explorationStatusMessage = ("The pad hums, and the room shifts around you...", .cyan)
            self.autosaveIfNeeded()
            self.showExplorationView()
        }
    }

    /// Move between floors via stairs, a rope-climbed hole, or levitation
    /// magic. Requirements (rope carried / spell slot available) are
    /// checked by the caller before this is ever invoked — see the
    /// "Take the Stairs"/"Climb the Rope"/"Levitate" menu option above.
    private func useVerticalConnection(method: String, from room: Room, to destination: Room, tookInjuryRisk: Bool = false) {
        guard let dungeon = dungeon else { return }
        dungeon.currentRoomId = destination.id
        // Same fix as useTeleportPad() — normal movement (Dungeon.move())
        // always marks the room visited and expands the map around it;
        // stairs/rope skipped both, which is why arriving on the other
        // floor showed "No map available" instead of a real (if freshly
        // revealed) map. Persisted automatically from here on, since
        // Room.visited/the expanded rooms are part of the normal saved
        // dungeon state — no separate persistence needed.
        destination.visited = true
        dungeon.expandIfNeeded(from: destination)
        let goingDown = room.verticalDirection == "down"
        // Climbing up must increase the floor number, down must decrease it
        // (floor 1 -> up -> floor 2, floor 1 -> down -> floor 0) — this was
        // previously inverted.
        dungeon.currentFloor += goingDown ? -1 : 1
        advanceTime(10)
        tickTorch()
        checkTorchEvent()

        let dirWord = goingDown ? "down" : "up"
        switch method {
        case "rope":
            if tookInjuryRisk {
                // Jumping down without a rope — no roll needed to succeed
                // (you always make it down), just a real chance of a bruising
                // landing, unlike the safe roped climb.
                if Int.random(in: 1...100) <= 40, let unlucky = party.filter({ $0.isConscious }).randomElement() {
                    let injury = Dice.roll(6)
                    unlucky.currentHP = max(1, unlucky.currentHP - injury)
                    explorationStatusMessage = ("You jump down to Floor \(dungeon.currentFloor) — \(unlucky.name) lands wrong! (-\(injury) HP)", .red)
                    logEvent("\(unlucky.name) was hurt jumping down without a rope (-\(injury) HP)", category: "EXPLORE")
                } else {
                    explorationStatusMessage = ("You jump down to Floor \(dungeon.currentFloor), landing hard but unhurt.", .yellow)
                }
                logEvent("Jumped down without a rope from \(room.name) to \(destination.name) (Floor \(dungeon.currentFloor))", category: "EXPLORE")
            } else {
                // A rope actually bears the party's weight here (unlike the
                // no-rope jump-down above) — the heavier the party is loaded,
                // the more likely it snaps under them.
                let totalWeight = party.reduce(0.0) { $0 + $1.currentWeight }
                let totalCapacity = party.reduce(0.0) { $0 + $1.carryCapacity }
                let loadRatio = totalCapacity > 0 ? totalWeight / totalCapacity : 0
                let breakChance = min(50, max(5, Int(loadRatio * 60)))
                if Int.random(in: 1...100) <= breakChance {
                    for member in party {
                        if let idx = member.inventory.firstIndex(where: { $0.name.hasPrefix("Rope") }) {
                            member.inventory.remove(at: idx)
                            break
                        }
                    }
                    let injury = Dice.roll(6)
                    let unlucky = party.filter({ $0.isConscious }).randomElement()
                    unlucky?.currentHP = max(1, (unlucky?.currentHP ?? injury) - injury)
                    let who = unlucky?.name ?? "Someone"
                    explorationStatusMessage = ("The rope snaps under the party's load! \(who) tumbles the last few feet to Floor \(dungeon.currentFloor). (-\(injury) HP) The rope is ruined.", .red)
                    logEvent("Rope broke under the party's weight while climbing \(dirWord) (-\(injury) HP to \(who))", category: "EXPLORE")
                } else {
                    explorationStatusMessage = ("You climb \(dirWord) the rope through the hole to Floor \(dungeon.currentFloor)...", .cyan)
                    logEvent("Climbed via rope \(dirWord) from \(room.name) to \(destination.name) (Floor \(dungeon.currentFloor))", category: "EXPLORE")
                }
            }
        case "levitation":
            // Spend a slot from whichever caster has one — this is what
            // "casts" the levitation, not a specific known spell (the
            // catalog doesn't have one yet).
            if let caster = party.first(where: { $0.spellSlots.level2Current > 0 }) {
                caster.spellSlots.level2Current -= 1
            } else if let caster = party.first(where: { $0.spellSlots.level1Current > 0 }) {
                caster.spellSlots.level1Current -= 1
            }
            // Small risk of a bump on the way — never lethal, just a scare.
            if Int.random(in: 1...100) <= 10, let unlucky = party.filter({ $0.isConscious }).randomElement() {
                let bump = Dice.roll(4)
                unlucky.currentHP = max(1, unlucky.currentHP - bump)
                explorationStatusMessage = ("You levitate \(dirWord) — until \(unlucky.name) bumps the ceiling! (-\(bump) HP) Now on Floor \(dungeon.currentFloor).", .yellow)
                logEvent("\(unlucky.name) bumped the ceiling while levitating (-\(bump) HP)", category: "EXPLORE")
            } else {
                explorationStatusMessage = ("You levitate \(dirWord) to Floor \(dungeon.currentFloor), minding the ceiling...", .cyan)
            }
            logEvent("Levitated \(dirWord) from \(room.name) to \(destination.name) (Floor \(dungeon.currentFloor))", category: "EXPLORE")
        default: // "stairs"
            explorationStatusMessage = ("You take the stairs \(dirWord) to Floor \(dungeon.currentFloor)...", .cyan)
            logEvent("Took the stairs \(dirWord) from \(room.name) to \(destination.name) (Floor \(dungeon.currentFloor))", category: "EXPLORE")
        }
        logMultiplayerAction("The party moved \(dirWord) to Floor \(dungeon.currentFloor) via \(method)")
        autosaveIfNeeded()
        showExplorationView()
    }

    // MARK: - Locked Doors

    private func showLockedDoor(direction: Direction, room: Room) {
        guard let lockId = room.doorLockIds[direction] else { showExplorationView(); return }
        clearTerminal()
        printTitle("Locked Door")
        print("  The door to the \(direction.rawValue.lowercased()) is locked tight.", color: .yellow)
        print("")

        let matchingKey = party.flatMap { $0.inventory }.first(where: { $0.keyForDoorId == lockId })
        let hasThievesTools = party.contains { $0.inventory.contains { $0.name == "Thieves' Tools" } }

        var options: [String] = []
        if let key = matchingKey { options.append("Use \(key.name)") }
        if hasThievesTools { options.append("Pick the Lock") }
        options.append("Force the Door")
        options.append("< Go Back")

        if matchingKey == nil {
            print("  You don't have a key that fits. Somewhere in the dungeon, one probably does.", color: .dimGreen)
            print("")
        }

        showMenu(options)
        closeHandler = { [weak self] in self?.showExplorationView() }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1 && choice <= options.count else { return }
            switch options[choice - 1] {
            case let opt where opt.hasPrefix("Use "):
                self.unlockDoor(direction: direction, room: room, method: "with the key")
            case "Pick the Lock":
                self.attemptLockpick(direction: direction, room: room)
            case "Force the Door":
                self.attemptForceDoor(direction: direction, room: room)
            default:
                self.showExplorationView()
            }
        }
    }

    private func unlockDoor(direction: Direction, room: Room, method: String) {
        room.openedLocks.insert(direction)
        if let neighborId = room.exits[direction], let neighbor = dungeon?.rooms[neighborId] {
            neighbor.openedLocks.insert(direction.opposite)
        }
        advanceTime(5)
        print("")
        print("  The door swings open \(method).", color: .brightGreen)
        print("  Long-press \(direction.rawValue) again to lock it once you're through, if you're holding the key.", color: .dimGreen)
        logEvent("Unlocked a door to the \(direction.rawValue) in \(room.name) (\(method))", category: "EXPLORE")
        waitForContinue()
        inputHandler = { [weak self] _ in self?.move(direction) }
    }

    private func attemptLockpick(direction: Direction, room: Room) {
        let bestTools = party.map { $0.skillModifier(for: .sleightOfHand) }.max() ?? 0
        let roll = Dice.d20()
        let dc = 12 + (dungeon?.level ?? 1)
        print("")
        print("  Sleight of Hand: d20[\(roll)] + \(bestTools) vs DC \(dc)", color: .dimGreen)
        // Picking locks wears Thieves' Tools too — slowly (about every other pick).
        if Bool.random(),
           let owner = party.filter({ $0.inventory.contains { $0.name == "Thieves' Tools" } })
               .max(by: { $0.skillModifier(for: .sleightOfHand) < $1.skillModifier(for: .sleightOfHand) }),
           let note = wearTool("Thieves' Tools", owner: owner, freshUses: 8...15, breakChance: 3) {
            print("  \(note)", color: .dimGreen)
        }
        if roll + bestTools >= dc {
            unlockDoor(direction: direction, room: room, method: "with a click of the lockpicks")
        } else {
            advanceTime(5)
            print("  The pick slips — no luck this time.", color: .yellow)
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showLockedDoor(direction: direction, room: room) }
        }
    }

    private func attemptForceDoor(direction: Direction, room: Room) {
        let bestStr = party.map { $0.abilityScores.modifier(for: .strength) }.max() ?? 0
        let heavyWeaponBonus = party.contains { $0.equippedWeapon?.weaponStats?.isTwoHanded == true } ? 2 : 0
        let roll = Dice.d20()
        let dc = 13 + (dungeon?.level ?? 1)
        print("")
        print("  Strength check: d20[\(roll)] + \(bestStr + heavyWeaponBonus) vs DC \(dc)", color: .dimGreen)
        if roll + bestStr + heavyWeaponBonus >= dc {
            print("  The door splinters open with a crash!", color: .brightGreen)
            SoundManager.shared.playHit()
            unlockDoor(direction: direction, room: room, method: "by force")
        } else {
            advanceTime(5)
            print("  You throw your weight against it, but the door holds.", color: .yellow)
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showLockedDoor(direction: direction, room: room) }
        }
    }

    private func triggerTrap(in room: Room) {
        let traps: [(name: String, desc: String, dice: Int, sides: Int)] = [
            ("Poison Dart Trap", "Darts shoot from hidden holes in the walls!", 1, 6),
            ("Pit Trap", "The floor gives way beneath your feet!", 1, 8),
            ("Swinging Blade", "A blade swings from a concealed slot!", 1, 10),
            ("Flame Jet", "Fire erupts from vents in the floor!", 2, 6),
            ("Falling Net", "A weighted net drops from the ceiling!", 1, 4),
            ("Poison Gas", "A sickly green gas seeps from the walls!", 1, 6),
        ]

        let trap = traps.randomElement()!
        var damage = Dice.rollSum(trap.dice, d: trap.sides)

        print("")
        print("*** TRAP! ***", color: .red, bold: true)
        print(trap.desc, color: .red)
        print("")

        SoundManager.shared.playDeath()

        // Thieves' Tools give the party a chance to disarm the trap entirely
        // — credited to whichever tool-owner actually rolls the check (not
        // just "the party"), so it's clear who to thank (or blame).
        let toolOwners = party.filter { char in char.inventory.contains { $0.name == "Thieves' Tools" } }
        var disarmed = false
        if let user = toolOwners.max(by: { $0.skillModifier(for: .sleightOfHand) < $1.skillModifier(for: .sleightOfHand) }) {
            let modifier = user.skillModifier(for: .sleightOfHand)
            let roll = Dice.d20()
            if roll + modifier >= 14 {
                disarmed = true
                print("  \(user.name)'s Thieves' Tools make quick work of it — \(trap.name) disarmed! No damage taken.", color: .brightGreen)
            } else {
                print("  \(user.name) tries to disarm it with their Thieves' Tools, but fumbles — \(trap.name) triggers anyway!", color: .yellow)
            }
            if let note = wearTool("Thieves' Tools", owner: user, freshUses: 8...15, breakChance: 5) { print("  \(note)", color: .dimGreen) }
        }

        // Rope softens the fall from a Pit Trap specifically.
        let hasRope = party.contains { char in char.inventory.contains { $0.name == "Rope (50 ft)" } }
        if !disarmed && trap.name == "Pit Trap" && hasRope {
            damage = max(1, damage / 2)
            print("  Your rope catches you halfway down — half damage!", color: .brightGreen)
        }

        if disarmed {
            let userName = toolOwners.max(by: { $0.skillModifier(for: .sleightOfHand) < $1.skillModifier(for: .sleightOfHand) })?.name ?? "The party"
            print("")
            logEvent("Trap: \(trap.name) disarmed by \(userName) with Thieves' Tools", category: "TRAP")
            logMultiplayerAction("\(userName) disarmed \(trap.name) with Thieves' Tools — no damage")
            // waitForContinueWithTimeout (not plain waitForContinue): reads
            // the trap out loud when Voice Menus is on (built into
            // waitForContinue already) and auto-advances after a delay
            // instead of waiting indefinitely on a tap — this screen only
            // had the corner ✕ icon as a way off it otherwise. fullScreenTap
            // makes the whole screen tappable too, since there's nothing here
            // worth scrolling back to reread.
            waitForContinueWithTimeout(multiplier: 4.0, fullScreenTap: true) { [weak self] in
                self?.showExplorationView()
            }
            return
        }

        print("  \(trap.name) — \(damage) damage!", color: .red)
        print("")

        // Damage a random party member (or the lead)
        let target = party.randomElement() ?? party[0]
        target.takeDamage(damage)
        print("  \(target.name) takes \(damage) damage! (\(target.currentHP)/\(target.maxHP) HP)", color: .yellow)

        if !target.isConscious {
            print("  \(target.name) is knocked unconscious!", color: .red, bold: true)
        }

        logEvent("Trap: \(trap.name) hit \(target.name) for \(damage) damage", category: "TRAP")
        logMultiplayerAction("\(target.name) triggered \(trap.name) — \(damage) damage! (\(target.currentHP)/\(target.maxHP) HP)")

        print("")
        // waitForContinueWithTimeout (not plain waitForContinue): reads the
        // trap out loud when Voice Menus is on (built into waitForContinue
        // already) and auto-advances after a delay instead of waiting
        // indefinitely on a tap — this screen only had the corner ✕ icon as
        // a way off it otherwise. fullScreenTap makes the whole screen
        // tappable too, since there's nothing here worth scrolling back to
        // reread.
        waitForContinueWithTimeout(multiplier: 4.0, fullScreenTap: true) { [weak self] in
            self?.showExplorationView()
        }
    }

    /// Apply a DM-requested movement, validating against actual dungeon exits
    private func applyTeleportToEntrance() {
        guard let dungeon = dungeon else { return }
        let entranceId = 0  // Entrance is always room 0
        if let entrance = dungeon.rooms[entranceId] {
            dungeon.previousRoomId = dungeon.currentRoomId
            dungeon.currentRoomId = entranceId
            entrance.visited = true
            print("")
            print("  [TELEPORTED to \(entrance.name)!]", color: .cyan, bold: true)
            print("")
            printExplorationMap()
            logEvent("Teleported to dungeon entrance", category: "DM")
        }
    }

    private func applyDMMovement(_ dirName: String) {
        guard let dungeon = dungeon, let room = dungeon.currentRoom else { return }

        let direction: Direction?
        switch dirName.lowercased() {
        case "north": direction = .north
        case "south": direction = .south
        case "east":  direction = .east
        case "west":  direction = .west
        default: direction = nil
        }

        guard let dir = direction else {
            print("  [The DM tried an invalid direction.]", color: .dimGreen)
            return
        }

        // Validate the exit actually exists and isn't barricaded
        if room.exits[dir] != nil && !room.secured.contains(dir) {
            let result = dungeon.move(direction: dir)
            if result.success {
                advanceTime(10)
                if let newRoom = dungeon.currentRoom {
                    logEvent("DM moved party \(dir.rawValue) to \(newRoom.name)", category: "DM")
                    print("")
                    print("  [Moved \(dir.rawValue) to \(newRoom.name)!]", color: .cyan, bold: true)
                    print("")
                    printExplorationMap()
                }
            }
        } else {
            print("  [No exit \(dir.rawValue) — the DM's path is blocked.]", color: .dimGreen)
        }
    }

    private func applyDMDropItem(_ itemName: String) {
        let lower = itemName.lowercased()
        for char in party {
            // Try exact contains first, then word-by-word matching
            if let item = char.inventory.first(where: { $0.name.lowercased().contains(lower) })
                ?? char.inventory.first(where: { lower.contains($0.name.lowercased()) })
                ?? char.inventory.first(where: {
                    let words = lower.split(separator: " ")
                    let itemWords = $0.name.lowercased().split(separator: " ")
                    return words.contains(where: { w in itemWords.contains(where: { $0 == w && w.count > 2 }) })
                }) {
                char.removeItem(item)
                if let room = dungeon?.currentRoom {
                    room.droppedItems.append(item)
                }
                print("  [Dropped: \(item.name)]", color: .yellow, bold: true)
                logEvent("DM: \(char.name) dropped \(item.name)", category: "DM")
                return
            }
            // Check equipped items (bidirectional match)
            if let w = char.equippedWeapon, (w.name.lowercased().contains(lower) || lower.contains(w.name.lowercased())) {
                char.unequipWeapon()
                char.removeItem(w)
                if let room = dungeon?.currentRoom { room.droppedItems.append(w) }
                print("  [Dropped: \(w.name)]", color: .yellow, bold: true)
                logEvent("DM: \(char.name) dropped \(w.name)", category: "DM")
                return
            }
            if let a = char.equippedArmor, (a.name.lowercased().contains(lower) || lower.contains(a.name.lowercased())) {
                char.unequipArmor()
                char.removeItem(a)
                if let room = dungeon?.currentRoom { room.droppedItems.append(a) }
                print("  [Dropped: \(a.name)]", color: .yellow, bold: true)
                logEvent("DM: \(char.name) dropped \(a.name)", category: "DM")
                return
            }
            if let s = char.equippedShield, (s.name.lowercased().contains(lower) || lower.contains(s.name.lowercased())) {
                char.unequipShield()
                char.removeItem(s)
                if let room = dungeon?.currentRoom { room.droppedItems.append(s) }
                print("  [Dropped: \(s.name)]", color: .yellow, bold: true)
                logEvent("DM: \(char.name) dropped \(s.name)", category: "DM")
                return
            }
        }
        print("  [No \(itemName) found to drop.]", color: .dimGreen)
    }

    /// Scan DM narrative for implied item state changes that lack command tags.
    /// Auto-applies drops, uses, and equips mentioned in text but not tagged.
    private func applyNarrativeFallbacks(text: String, alreadyApplied: DMCommandResult) -> Bool {
        let lower = text.lowercased()
        var changed = false

        // Collect all inventory item names for matching
        var allItems: [(char: Character, item: Item, equipped: Bool)] = []
        for char in party {
            for item in char.inventory {
                allItems.append((char, item, false))
            }
            if let w = char.equippedWeapon { allItems.append((char, w, true)) }
            if let a = char.equippedArmor { allItems.append((char, a, true)) }
            if let s = char.equippedShield { allItems.append((char, s, true)) }
        }

        // Drop patterns: "drops the X", "throws away X", "discards X", "sets down X", "tosses X"
        let dropPatterns = ["drops the ", "drop the ", "drops his ", "drops her ",
                            "throws away ", "discards the ", "sets down the ",
                            "tosses the ", "tosses away ", "gets rid of the ",
                            "puts down the ", "removes the ", "takes off the "]

        for item in allItems {
            let iName = item.item.name.lowercased()
            // Skip if already handled by a tag
            if alreadyApplied.droppedItems.contains(where: { $0.lowercased().contains(iName) || iName.contains($0.lowercased()) }) {
                continue
            }
            for pattern in dropPatterns {
                if lower.contains(pattern + iName) || lower.contains(pattern + iName.replacingOccurrences(of: " ", with: "")) {
                    // Narrative implies dropping this item
                    if item.equipped {
                        switch item.item.type {
                        case .weapon: item.char.unequipWeapon()
                        case .armor: item.char.unequipArmor()
                        case .shield: item.char.unequipShield()
                        default: break
                        }
                    }
                    item.char.removeItem(item.item)
                    if let room = dungeon?.currentRoom {
                        room.droppedItems.append(item.item)
                    }
                    print("  [Auto-applied: \(item.char.name) dropped \(item.item.name)]", color: .yellow)
                    logEvent("DM (auto): \(item.char.name) dropped \(item.item.name)", category: "DM")
                    changed = true
                    break
                }
            }
        }

        // Use patterns: "drinks the X", "eats the X", "uses the X", "consumes the X"
        let usePatterns = ["drinks the ", "drinks a ", "eats the ", "eats a ",
                           "uses the ", "uses a ", "consumes the ", "consumes a ",
                           "quaffs the ", "quaffs a "]
        for item in allItems where !item.equipped {
            let iName = item.item.name.lowercased()
            if alreadyApplied.usedItems.contains(where: { $0.lowercased().contains(iName) || iName.contains($0.lowercased()) }) {
                continue
            }
            for pattern in usePatterns {
                if lower.contains(pattern + iName) || lower.contains(pattern + iName.replacingOccurrences(of: " ", with: "")) {
                    if let food = consumeFood(item.item, by: item.char) {
                        item.char.removeItem(item.item)
                        print("  [Auto-applied: \(food.summary)]", color: .brightGreen)
                        logEvent("DM (auto): \(food.summary)", category: "DM")
                    } else if let healStr = item.item.potionStats?.healAmount {
                        item.char.removeItem(item.item)
                        let roll = Dice.rollDamage(healStr)
                        let amount = max(1, roll.total)
                        item.char.heal(amount)
                        print("  [Auto-applied: \(item.char.name) used \(item.item.name) — +\(amount) HP]", color: .brightGreen)
                        logEvent("DM (auto): \(item.char.name) used \(item.item.name), healed \(amount) HP", category: "DM")
                    } else {
                        item.char.removeItem(item.item)
                        print("  [Auto-applied: \(item.char.name) used \(item.item.name)]", color: .cyan)
                        logEvent("DM (auto): \(item.char.name) used \(item.item.name)", category: "DM")
                    }
                    changed = true
                    break
                }
            }
        }

        return changed
    }

    private func applyDMEquipItem(_ itemName: String) {
        let lower = itemName.lowercased()
        for char in party {
            if let item = char.inventory.first(where: { $0.name.lowercased().contains(lower) }) {
                switch item.type {
                case .weapon: char.equipWeapon(item)
                case .armor: char.equipArmor(item)
                case .shield: char.equipShield(item)
                default:
                    print("  [\(item.name) cannot be equipped.]", color: .dimGreen)
                    return
                }
                print("  [Equipped: \(item.name)!]", color: .cyan, bold: true)
                logEvent("DM: \(char.name) equipped \(item.name)", category: "DM")
                return
            }
        }
        print("  [No \(itemName) found to equip.]", color: .dimGreen)
    }

    private func applyDMUseItem(_ itemName: String) {
        let lower = itemName.lowercased()
        for char in party {
            if let item = char.inventory.first(where: { $0.name.lowercased().contains(lower) }) {
                if item.name.lowercased().contains("antidote") {
                    char.removeItem(item)
                    if char.isPoisoned {
                        char.curePoison()
                        print("  [\(char.name) drinks antidote — poison cured!]", color: .brightGreen, bold: true)
                        logEvent("DM: \(char.name) used antidote, cured poison", category: "DM")
                    } else {
                        print("  [\(char.name) drinks antidote (not poisoned).]", color: .dimGreen)
                    }
                } else if let food = consumeFood(item, by: char) {
                    char.removeItem(item)
                    for (line, color) in food.lines { print("  [\(line)]", color: color) }
                    logEvent("DM: \(food.summary)", category: "DM")
                } else if let healStr = item.potionStats?.healAmount {
                    char.removeItem(item)
                    let roll = Dice.rollDamage(healStr)
                    let amount = max(1, roll.total)
                    char.heal(amount)
                    if char.isPoisoned {
                        char.curePoison()
                        print("  [\(char.name) uses \(item.name): +\(amount) HP! Poison cured!]", color: .brightGreen, bold: true)
                    } else {
                        print("  [\(char.name) uses \(item.name): +\(amount) HP!]", color: .brightGreen, bold: true)
                    }
                    logEvent("DM: \(char.name) used \(item.name), healed \(amount) HP", category: "DM")
                } else {
                    char.removeItem(item)
                    print("  [\(char.name) uses \(item.name).]", color: .cyan, bold: true)
                    logEvent("DM: \(char.name) used \(item.name)", category: "DM")
                }
                return
            }
        }
        print("  [No \(itemName) found to use.]", color: .dimGreen)
    }

    private func applyDMLightTorch() {
        if torchLit {
            print("  [The torch is already lit.]", color: .dimGreen)
            return
        }
        if let (holder, torch) = findBestTorch() {
            activeTorchId = torch.id
            torchHolderId = holder.id
            torchTurnsRemaining = torch.torchLife ?? Item.torchFullLife
            torchLit = true
            print("  [Torch lit!]", color: .yellow, bold: true)
            logEvent("DM lit torch", category: "DM")
            refreshMapAfterTorchChange()
        } else {
            print("  [No torch to illuminate.]", color: .dimGreen)
        }
    }

    private func applyDMDouseTorch() {
        if !torchLit {
            print("  [The torch is already out.]", color: .dimGreen)
            return
        }
        syncTorchLife()
        torchLit = false
        torchTurnsRemaining = 0
        activeTorchId = nil
        torchHolderId = nil
        print("  [Torch extinguished!]", color: .yellow, bold: true)
        logEvent("DM doused torch", category: "DM")
        refreshMapAfterTorchChange()
    }

    private func applyDMUnsecure(_ dirName: String) {
        guard let room = dungeon?.currentRoom else { return }
        let dirMap: [String: Direction] = ["north": .north, "south": .south, "east": .east, "west": .west]
        guard let dir = dirMap[dirName] else { return }
        if room.secured.contains(dir) {
            room.secured.remove(dir)
            logEvent("Removed barricade from \(dir.rawValue) door in \(room.name)", category: "EXPLORE")
        }
    }

    private func applyDMSecure(_ dirName: String) {
        guard let room = dungeon?.currentRoom else { return }
        let dirMap: [String: Direction] = ["north": .north, "south": .south, "east": .east, "west": .west]
        guard let dir = dirMap[dirName] else { return }
        if room.exits[dir] != nil && !room.secured.contains(dir) {
            room.secured.insert(dir)
            logEvent("Barricaded \(dir.rawValue) door in \(room.name)", category: "EXPLORE")
        }
    }

    // MARK: - Actions Submenu

    /// Quick-access antidote use from the Actions menu — same cure as the
    /// Inventory > Use Item path, without the detour through it. Auto-picks
    /// the holder and target when unambiguous, otherwise asks who receives it.
    private func useAntidoteQuick() {
        let poisonedMembers = party.filter { $0.isPoisoned }
        guard !poisonedMembers.isEmpty else { showExplorationView(); return }
        guard let holder = party.first(where: { char in char.inventory.contains { $0.name.lowercased().contains("antidote") } }),
              let antidote = holder.inventory.first(where: { $0.name.lowercased().contains("antidote") }) else {
            showExplorationView()
            return
        }

        let applyTo: (Character) -> Void = { [weak self] target in
            guard let self = self else { return }
            holder.removeItem(antidote)
            target.curePoison()
            self.clearTerminal()
            self.printExplorationMap()
            self.print("")
            self.print("  \(holder.name) administers the antidote to \(target.name).", color: .brightGreen)
            self.print("  Poison cured!", color: .brightGreen)
            self.logEvent("\(target.name) cured of poison via Antidote (\(holder.name))", category: "ITEM")
            self.logMultiplayerAction("\(target.name) cured of poison via antidote")
            self.waitForContinueWithTimeout { [weak self] in self?.showExplorationView() }
        }

        if poisonedMembers.count == 1 {
            applyTo(poisonedMembers[0])
        } else {
            clearTerminal()
            printExplorationMap()
            print("")
            printTitle("Use Antidote")
            print("  Who receives it?", color: .cyan)
            showMenu(poisonedMembers.map { "\($0.name) (\($0.currentHP)/\($0.maxHP) HP)" })
            closeHandler = { [weak self] in self?.showExplorationView() }
            menuHandler = { choice in
                guard choice >= 1, choice <= poisonedMembers.count else { return }
                applyTo(poisonedMembers[choice - 1])
            }
        }
    }

    /// "2 Zombies, 1 Goblin lie dead here." — groups Room.defeatedMonsterNames
    /// by name with counts, since a fight is usually more than one monster.
    private func defeatedMonsterSummary(_ names: [String]) -> String {
        var counts: [String: Int] = [:]
        var order: [String] = []
        for name in names {
            if counts[name] == nil { order.append(name) }
            counts[name, default: 0] += 1
        }
        let parts = order.map { name -> String in
            let count = counts[name] ?? 1
            return count > 1 ? "\(count) \(name)s" : "1 \(name)"
        }
        let verb = names.count == 1 ? "lies" : "lie"
        return "\(parts.joined(separator: ", ")) \(verb) dead here."
    }

    /// Zombies left standing after a fight (see Room.respawnEligibleMonsterNames
    /// — a per-zombie coin flip at the kill) have a chance to claw back up on
    /// a later visit to a cleared room. Rolled fresh every entry rather than
    /// once, so a room you keep passing through stays a real, recurring
    /// risk instead of a one-time gotcha. Fresh (undamaged) zombies, since
    /// what's actually still moving is the reanimated husk, not the original.
    private func checkForMonsterRespawn(room: Room) {
        guard room.cleared, room.encounter == nil, !room.respawnEligibleMonsterNames.isEmpty else { return }
        guard Int.random(in: 1...100) <= 12 else { return }

        let names = room.respawnEligibleMonsterNames
        let monsters = names.map { Monster.create(.zombie, customName: $0) }
        room.encounter = Encounter(monsters: monsters, difficulty: .easy)
        room.cleared = false
        room.respawnEligibleMonsterNames = []
        room.defeatedMonsterNames = []
        let summary = defeatedMonsterSummary(names).replacingOccurrences(of: " lie dead here.", with: "")
            .replacingOccurrences(of: " lies dead here.", with: "")
        explorationStatusMessage = ("The \(summary.lowercased()) you left for dead claw their way upright again!", .red)
        logEvent("Zombie respawn in \(room.name): \(names.joined(separator: ", "))", category: "EXPLORE")
    }

    /// Monsters occasionally wander between adjacent rooms — a room you
    /// already cleared isn't guaranteed to stay empty forever if something
    /// is prowling next door. Mirrors checkForMonsterRespawn's shape/cadence
    /// above, but MOVES a real monster (with whatever HP it already had)
    /// out of a live neighboring encounter rather than conjuring a fresh
    /// one — nothing appears from nowhere.
    private func checkForMonsterWander(room: Room) {
        guard let dungeon = dungeon else { return }
        // Only wander into a room that's actually safe right now.
        guard room.cleared, room.encounter == nil else { return }
        guard Int.random(in: 1...100) <= 10 else { return }

        let neighborRooms = room.exits.values.compactMap { dungeon.rooms[$0] }
        let candidates = neighborRooms.filter { ($0.encounter?.aliveMonsters.count ?? 0) > 0 }
        guard let sourceRoom = candidates.randomElement(),
              var sourceEncounter = sourceRoom.encounter,
              let movingIndex = sourceEncounter.monsters.firstIndex(where: { $0.currentHP > 0 }) else { return }

        let monster = sourceEncounter.monsters.remove(at: movingIndex)
        if sourceEncounter.aliveMonsters.isEmpty {
            sourceRoom.encounter = nil
            sourceRoom.cleared = true
        } else {
            sourceRoom.encounter = sourceEncounter
        }

        room.encounter = Encounter(monsters: [monster], difficulty: sourceEncounter.difficulty)
        room.cleared = false
        explorationStatusMessage = ("You hear something moving nearby... a \(monster.name) has wandered in!", .red)
        logEvent("\(monster.name) wandered from \(sourceRoom.name) into \(room.name)", category: "EXPLORE")
    }

    private func showActionsMenu() {
        guard let dungeon = dungeon, let room = dungeon.currentRoom else { showExplorationView(); return }

        clearTerminal()

        // Same layout as exploration view — map, room info, party status
        _ = dungeon
        printExplorationMap()   // same map everywhere (fills the Mac pane's width)
        if !torchLit {
            if partyHasTorch() {
                print("  Torch unlit — illuminate it to see further!", color: .yellow)
            } else {
                print("  No torch — visibility reduced!", color: .yellow)
            }
        } else if torchTurnsRemaining > 0 && torchTurnsRemaining <= 5 {
            print("  Torch flickering... (\(torchTurnsRemaining) rooms left)", color: .yellow)
        }
        print("")

        // Room description
        if torchLit {
            print(room.name, color: .brightGreen, bold: true)
            printWrapped(room.roomDescription)
        } else {
            print(room.name, color: .dimGreen, bold: true)
            print("It's too dark to see clearly...", color: .gray)
        }
        print("")

        // Party status
        let levelStr = dungeon.level > 0 ? "Level \(dungeon.level) | " : ""
        if gameTimeLimit > 0 {
            let remaining = max(0, gameTimeLimit - gameTimeMinutes)
            let remainStr = formatTimeRemaining(remaining)
            let timeColor: TerminalColor = remaining > 180 ? .dimGreen : (remaining > 60 ? .yellow : .red)
            print("\(levelStr)\(formattedGameTime())  ⏱ \(remainStr)", color: timeColor)
        } else {
            print("\(levelStr)\(formattedGameTime())", color: .dimGreen)
        }
        let maxNameLen = party.map { $0.name.count }.max() ?? 10
        for char in party {
            let padded = char.name.padding(toLength: maxNameLen, withPad: " ", startingAt: 0)
            let hp = "L\(char.level) \(char.currentHP)/\(char.maxHP) HP"
            let poisonTag = char.isPoisoned ? " ☠" : ""
            let color: TerminalColor = char.isPoisoned ? .magenta : .cyan
            print(" \(padded)  \(hp)\(poisonTag)", color: color)
        }
        print("")

        // Direction exits (same as exploration)
        var exits: [Direction: Bool] = [:]
        var secured: Set<Direction> = []
        for direction in Direction.allCases {
            let hasExit = room.exits[direction] != nil
            let isSecured = room.secured.contains(direction)
            let isLocked = room.isLockedShut(direction)
            exits[direction] = hasExit && !isSecured
            if hasExit && (isSecured || isLocked) { secured.insert(direction) }
        }
        DispatchQueue.main.async { self.securedExits = secured }

        // Action buttons
        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        // Helper: set return destination to actions menu before each action
        let returnToActions: () -> Void = { [weak self] in
            self?.autoReturnDestination = { self?.showActionsMenu() }
        }

        // Search Room (also scavenges)
        menuOpts.append(MenuOption("Search Room"))
        actions.append { [weak self] in returnToActions(); self?.searchRoom() }

        // Listen
        menuOpts.append(MenuOption("Listen"))
        actions.append { [weak self] in returnToActions(); self?.listenAtDoors() }

        // Pick Up Items (dropped loot)
        if !room.droppedItems.isEmpty {
            menuOpts.append(MenuOption("Pick Up Items"))
            actions.append { [weak self] in returnToActions(); self?.pickUpDroppedItems() }
        }

        // Take Treasure
        var takeTreasureIndex: Int? = nil
        if !room.treasure.isEmpty {
            takeTreasureIndex = menuOpts.count
            menuOpts.append(MenuOption("Take Treasure"))
            actions.append { [weak self] in returnToActions(); self?.collectTreasure() }
        }

        // Use Antidote — direct quick access when poison is actually in
        // play, rather than a trip through Inventory > Use Item every time.
        if party.contains(where: { $0.isPoisoned }),
           party.contains(where: { char in char.inventory.contains { $0.name.lowercased().contains("antidote") } }) {
            menuOpts.append(MenuOption("Use Antidote", tint: .cyan))
            actions.append { [weak self] in returnToActions(); self?.useAntidoteQuick() }
        }

        // Torch toggle
        if torchLit {
            menuOpts.append(MenuOption("Douse Torch"))
            actions.append { [weak self] in
                self?.douseTorch()
                self?.showActionsMenu()
            }
        } else if partyHasTorch() {
            menuOpts.append(MenuOption("Illuminate"))
            actions.append { [weak self] in
                self?.lightTorch()
                self?.showActionsMenu()
            }
        }

        // Open Pack
        let consciousParty = party.filter { $0.isConscious }
        let hasPackItems = consciousParty.contains { !$0.inventory.isEmpty }
        menuOpts.append(MenuOption("Inventory", isDisabled: !hasPackItems))
        actions.append { [weak self] in
            guard let self = self else { return }
            returnToActions()
            if consciousParty.count == 1, let char = consciousParty.first {
                self.showPackMenu(character: char, onBack: { self.showActionsMenu() })
            } else {
                self.showPackCharacterPicker(onBack: { self.showActionsMenu() })
            }
        }

        // Acting As — override which character performs the single-actor
        // actions above (Search Room, Listen, Illuminate). Only worth
        // showing once there's more than one conscious party member to pick
        // from.
        if consciousParty.count > 1 {
            let actingLabel = actingOverrideCharacter.map { "Acting As: \(shortName(for: $0))" } ?? "Acting As: Auto"
            menuOpts.append(MenuOption(actingLabel, tint: actingOverrideCharacter != nil ? .cyan : .navigation))
            actions.append { [weak self] in
                returnToActions()
                self?.showActingAsPicker()
            }
        }

        // Save (quick save)
        menuOpts.append(MenuOption("Save", tint: .navigation))
        actions.append { [weak self] in self?.quickSave() }

        // Help
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showActionsHelp() }

        // Back to exploration
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showExplorationView() }

        showMenuWithDirections(menuOpts, exits: exits)

        directionHandler = { [weak self] direction in
            self?.move(direction)
        }
        dpadCenterLabel = "Rest"
        dpadCenterHandler = { [weak self] in
            self?.rest()
        }
        dpadCenterLongPressHandler = { [weak self] in
            self?.performRest(isLongRest: true, fast: true)
        }

        closeHandler = { [weak self] in self?.showExplorationView() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
        // Long-press actions: Listen → Secure, dark buttons for torch-out actions
        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            guard choice >= 1 && choice <= menuOpts.count else { return }
            let opt = menuOpts[choice - 1]
            if opt.text == "Listen" {
                returnToActions()
                self.secureRoom()
            } else if opt.isDisabled && !self.torchLit {
                if opt.text == "Search Room" { self.darkSearch() }
                else if opt.text == "Take Treasure" { self.collectTreasureInDark() }
            }
        }
    }

    /// Lets the player choose who performs the single-actor exploration
    /// actions (Search Room, Listen, Illuminate) instead of the automatic
    /// "best fit" default — e.g. for roleplay reasons. "Auto" clears the
    /// override.
    func showActingAsPicker() {
        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }
        printSubtitle("Acting As")
        printWrapped("Choose who performs Search Room, Listen, and Illuminate. Auto picks whoever in the party is best suited each time.", indent: 2, color: .dimGreen)
        print("")

        let candidates = party.filter { $0.isConscious }
        var options: [String] = ["Auto (best fit)"]
        for char in candidates {
            options.append(shortName(for: char) + (char.id == actingAsCharacterId ? " (current)" : ""))
        }
        options.append("< Back")

        showMenu(options)
        closeHandler = { [weak self] in self?.showActionsMenu() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.actingAsCharacterId = nil
                self.showActionsMenu()
            } else if choice > 1 && choice <= options.count - 1 {
                self.actingAsCharacterId = candidates[choice - 2].id
                self.showActionsMenu()
            } else {
                self.showActionsMenu()
            }
        }
    }

    func searchRoom() {
        guard let room = dungeon?.currentRoom else { return }

        clearTerminal()
        SoundManager.shared.playSearch()

        // Show map at top
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        // Wall-mounted torches in a torchlit passage are visible, not hidden —
        // taking a spare one is guaranteed, no perception roll needed.
        if room.isTorchlit, let torchIdx = room.hiddenItems.firstIndex(where: { $0.name == "Torch" }) {
            let item = room.hiddenItems.remove(at: torchIdx)
            advanceTime(15)
            let searchNarrative = "You search the torchlit \(room.name.lowercased())...\n  ...and take a spare torch from its wall bracket!"
            showItemPickupMenu(item: item, source: "Wall bracket", narrative: searchNarrative) { [weak self] in
                self?.showExplorationView()
            }
            return
        }

        let hasHiddenLoot = !room.hiddenItems.isEmpty || room.hiddenGold > 0

        // If nothing hidden left, try scavenging instead
        if !hasHiddenLoot {
            forageSupplies()
            return
        }

        advanceTime(15)

        // Perception check
        let roll = Dice.d20()
        // Uses the override actor's own Perception if one is set (Actions >
        // Acting As), else automatically whoever in the party has the best.
        let bestPerception = actingOverrideCharacter?.skillModifier(for: .perception)
            ?? (party.map { $0.skillModifier(for: .perception) }.max() ?? 0)
        // Class "reliability" edge — Rogues/Engineers are that much more
        // likely to spot what's hidden (see CharacterClass.searchReliability).
        let classBonus = actingOverrideCharacter?.characterClass.searchReliability
            ?? (party.map { $0.characterClass.searchReliability }.max() ?? 0)
        let total = roll + bestPerception + classBonus

        if total >= 15 {
            // Success — find something from the room's hidden loot
            // Prefer items first, then gold
            if !room.hiddenItems.isEmpty {
                let item = room.hiddenItems.removeFirst()
                let source = searchSourceDescription(for: room.roomType)
                let searchNarrative = "You search the \(room.name.lowercased()) carefully...\n  ...and find \(item.name)!"
                showItemPickupMenu(item: item, source: source, narrative: searchNarrative) { [weak self] in
                    self?.showExplorationView()
                }
                return
            } else if room.hiddenGold > 0 {
                let gold = room.hiddenGold
                room.hiddenGold = 0
                let source = searchSourceDescription(for: room.roomType)
                let findText = (room.roomType == .corridor || room.roomType == .empty)
                    ? "...and find a dropped purse containing \(gold) gold pieces!"
                    : "...and find \(gold) gold pieces!"
                let searchNarrative = "You search the \(room.name.lowercased()) carefully...\n  \(findText)"
                showGoldPickupMenu(gold: gold, source: source, narrative: searchNarrative) { [weak self] in
                    self?.showExplorationView()
                }
                return
            }
        } else {
            // Failed check — hint if there's still something here
            let hints = searchFailHints(for: room.roomType)
            printWrapped("You search the \(room.name.lowercased()) carefully...", indent: 2, color: .cyan)
            print("")
            printWrapped(hints, indent: 2, color: .dimGreen)
            logEvent("Searched \(room.name) — missed something", category: "EXPLORE")
            logMultiplayerAction("Searched \(room.name) — found nothing")
        }

        // Add an examine-style observation about the room
        print("")
        let observation = examineObservation(for: room)
        if !observation.isEmpty {
            printWrapped(observation, indent: 2, color: .dimGreen)
        }

        pendingTimeoutKind = .search; autoReturn(after: max(2.5, infoTimeout * 0.8), stretchForReading: false)   // search results move on briskly
    }

    /// Room-type flavour text (merged from former Examine action)
    private func examineObservation(for room: Room) -> String {
        switch room.roomType {
        case .library:
            return ["Faded journals hint at the dungeon's history.", "The books are mostly ruined, but one contains a partial map.", "Ancient texts warn of deeper dangers."].randomElement()!
        case .shrine:
            return ["The altar feels warm to the touch.", "Faded offerings surround the shrine.", "The shrine feels cold and unwelcoming."].randomElement()!
        case .armory:
            return ["Scratch marks suggest the contents were taken in haste.", "Dents in the wall suggest training dummies once stood here.", "The metalwork suggests skilled craftsmanship."].randomElement()!
        case .prison:
            return ["Scratches on the walls tell stories of desperate prisoners.", "Names carved into stone — some centuries old.", "One cell door hangs open. The lock was picked from inside."].randomElement()!
        case .trap:
            if room.trapTriggered {
                return "You study the sprung trap carefully. You learn to spot the telltale signs."
            } else {
                return "Something feels off about this room. Best tread carefully."
            }
        case .treasure:
            return "Empty mounting hooks line the walls. This was clearly a vault."
        case .boss:
            return "The air is heavy. Claw marks far larger than any you've seen scar the walls."
        case .shop:
            return "A surprisingly cosy corner of the dungeon."
        default:
            return ["The walls are damp and cold. Faded carvings hint at the room's former purpose.", "Dust lies thick on every surface.", "The stonework here is cruder than elsewhere.", "You spot faint footprints in the dust."].randomElement()!
        }
    }

    /// Easter egg: fumbling search in the dark (long-press disabled Search Room)
    /// Visit Merchant/Gym/Solve Riddle all require roomIsLit — previously a
    /// silent no-op with no torch, which read as the button simply not
    /// working. Now gives feedback either way, with a real (if reduced)
    /// chance of fumbling your way there anyway rather than an outright block.
    /// Tries in the dark at the same thing, for escalating hints — and luck
    /// that improves a little with each attempt.
    private var darkFailStreak: [String: Int] = [:]

    private func attemptInTheDark(_ what: String, action: @escaping () -> Void) {
        clearTerminal()
        printWrapped("It's too dark to make out \(what) clearly...", indent: 2, color: .gray)
        print("")
        advanceTime(5)
        let tries = darkFailStreak[what, default: 0]
        if Int.random(in: 1...100) <= min(60, 35 + tries * 8) {
            darkFailStreak[what] = 0
            print("  You feel your way there anyway.", color: .dimGreen)
            waitForContinueWithTimeout { action() }
        } else {
            darkFailStreak[what] = tries + 1
            print("  You can't quite manage it in the dark.", color: .yellow)
            switch tries {
            case 0: print("  Light a torch and try again.", color: .yellow)
            case 1: printWrapped("Hint: tap the flame on the D-pad (bottom left) to light a torch — then it's easy.", indent: 2, color: .cyan)
            default: printWrapped("Hint: no torch? Merchants sell them, and they sometimes turn up when you search. Or keep trying — now and then luck is on your side.", indent: 2, color: .cyan)
            }
            waitForContinueWithTimeout { [weak self] in self?.showExplorationView() }
        }
    }

    private func darkSearch() {
        guard let room = dungeon?.currentRoom else { return }

        clearTerminal()
        printWrapped("You fumble around in the darkness...", indent: 2, color: .gray)
        print("")
        advanceTime(15)

        let hasHiddenLoot = !room.hiddenItems.isEmpty || room.hiddenGold > 0

        // Harder perception check in the dark (DC 18 instead of 15)
        let roll = Dice.d20()
        // Uses the override actor's own Perception if one is set (Actions >
        // Acting As), else automatically whoever in the party has the best.
        let bestPerception = actingOverrideCharacter?.skillModifier(for: .perception)
            ?? (party.map { $0.skillModifier(for: .perception) }.max() ?? 0)
        let total = roll + bestPerception

        // Fumbling mishaps (30% chance)
        let mishapRoll = Int.random(in: 1...100)
        if mishapRoll <= 30 {
            let mishaps = [
                "Your hand lands in something cold and slimy. You'd rather not know what it was.",
                "You grab something furry. It squeaks and scurries away!",
                "Your fingers find something sticky. It smells terrible.",
                "You put your hand straight into a cobweb. Something skitters up your arm!",
                "You stub your toe painfully on a rock. Ouch!",
                "You kneel in something wet and foul-smelling.",
                "You grab what you think is a handle. It's a dead rat's tail.",
                "Your hand finds something squishy. It pops. You shudder.",
                "You brush against something sharp and nick your finger. (-1 HP)",
                "You trip over something and bang your knee.",
            ]
            let mishap = mishaps.randomElement()!
            printWrapped(mishap, indent: 2, color: .yellow)
            print("")
            if mishap.contains("-1 HP") {
                if let char = party.first(where: { !$0.isComputerControlled }) ?? party.first {
                    char.takeDamage(1)
                    printWrapped("\(char.name) takes 1 damage.", indent: 4, color: .red)
                    print("")
                }
            }
            logEvent("Dark search mishap in \(room.name)", category: "EXPLORE")
        }

        if hasHiddenLoot && total >= 18 {
            // Success despite the darkness!
            printWrapped("...against the odds, your fingers close around something!", indent: 2, color: .brightGreen)
            print("")

            if !room.hiddenItems.isEmpty {
                let item = room.hiddenItems.removeFirst()
                printWrapped("Found in the dark: \(item.name)!", indent: 4, color: .brightGreen)
                logEvent("Dark search found \(item.name) in \(room.name)", category: "EXPLORE")
                showItemPickupMenu(item: item, source: "Found in the dark") { [weak self] in
                    self?.showExplorationView()
                }
                return
            } else if room.hiddenGold > 0 {
                let gold = room.hiddenGold
                room.hiddenGold = 0
                printWrapped("Your hand closes on coins: \(gold) gold!", indent: 4, color: .yellow)
                logEvent("Dark search found \(gold) gold in \(room.name)", category: "EXPLORE")
                showGoldPickupMenu(gold: gold, source: "Found in the dark") { [weak self] in
                    self?.showExplorationView()
                }
                return
            }
        } else if hasHiddenLoot {
            printWrapped("...you feel around but can't find anything useful in this darkness.", indent: 2, color: .dimGreen)
            logEvent("Dark search failed in \(room.name)", category: "EXPLORE")
        } else {
            printWrapped("...you grope around blindly. There's nothing here.", indent: 2, color: .dimGreen)
            logEvent("Dark search — nothing to find in \(room.name)", category: "EXPLORE")
        }

        pendingTimeoutKind = .search; autoReturn(after: max(2.5, infoTimeout * 0.8), stretchForReading: false)   // search results move on briskly
    }

    /// Long-press Examine in the dark — risky fumbling examination
    private func darkExamine() {
        guard let room = dungeon?.currentRoom else { return }

        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        advanceTime(10)

        printWrapped("You grope around in the darkness, trying to make sense of this place...", indent: 2, color: .gray)
        print("")

        // 40% chance of a mishap / encounter
        let mishapRoll = Int.random(in: 1...100)
        if mishapRoll <= 20 {
            let mishaps = [
                "You knock something over. It shatters loudly. Hopefully nothing heard that.",
                "Your hand finds something sharp. You pull back, finger bleeding. (-1 HP)",
                "You trip over debris and land face-first in dust. Coughing echoes down the corridor.",
                "Something cold and wet drips on your neck. You'd rather not know what.",
            ]
            let mishap = mishaps.randomElement()!
            printWrapped(mishap, indent: 2, color: .yellow)
            if mishap.contains("-1 HP") {
                if let char = party.first(where: { !$0.isComputerControlled }) ?? party.first {
                    char.takeDamage(1)
                    printWrapped("\(char.name) takes 1 damage.", indent: 4, color: .red)
                }
            }
            print("")
        }

        // Harder check — 30% chance of learning something vs normal examine
        let roll = Dice.d20()
        // Uses the override actor's own Perception if one is set (Actions >
        // Acting As), else automatically whoever in the party has the best.
        let bestPerception = actingOverrideCharacter?.skillModifier(for: .perception)
            ?? (party.map { $0.skillModifier(for: .perception) }.max() ?? 0)
        let total = roll + bestPerception

        if total >= 16 {
            let hints = [
                "By touch alone, you piece together the room's layout. It was once a \(room.roomType.rawValue.lowercased()).",
                "Your fingers trace carvings on the wall. You can't read them, but you sense their age.",
                "The air here is different — drier, warmer. Something important was kept here.",
                "You feel marks on the floor. Many feet have passed through here. Some recently.",
            ]
            printWrapped(hints.randomElement()!, indent: 2, color: .yellow)
        } else {
            printWrapped("In the darkness, you can barely tell which way is up. You learn nothing useful.", indent: 2, color: .dimGreen)
        }

        logEvent("Dark examine in \(room.name)", category: "EXPLORE")

        autoReturn()
    }

    /// Long-press Supplies in the dark — risky blind foraging
    private func darkForage() {
        guard let room = dungeon?.currentRoom else { return }

        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        advanceTime(15)
        room.searchedFor.insert("foraged")

        printWrapped("You scrabble around in the dark, feeling for anything useful...", indent: 2, color: .gray)
        print("")

        // 25% mishap chance
        let mishapRoll = Int.random(in: 1...100)
        if mishapRoll <= 25 {
            let mishaps = [
                "You grab something that wriggles. You drop it hastily.",
                "A pile of debris collapses on your foot. Ouch!",
                "You put your hand in something slimy. It stinks.",
                "Something skitters over your hand. You freeze, then it's gone.",
            ]
            printWrapped(mishaps.randomElement()!, indent: 2, color: .yellow)
            print("")
        }

        // Much lower chance of finding anything (15% vs normal ~35-45%)
        let roll = Int.random(in: 1...100)
        if roll <= 15 {
            // Found something basic
            let item = ItemCatalog.torch()
            printWrapped("...your hand closes on something familiar. A torch!", indent: 2, color: .brightGreen)
            logEvent("Dark forage found torch in \(room.name)", category: "EXPLORE")
            showItemPickupMenu(item: item, source: "Found in the dark") { [weak self] in
                self?.showExplorationView()
            }
            return
        } else {
            printWrapped("You find nothing but dust and debris. Hard to forage without light.", indent: 2, color: .dimGreen)
            logEvent("Dark forage — nothing found in \(room.name)", category: "EXPLORE")
        }

        autoReturn()
    }

    /// Thematic description of where an item was found, based on room type
    private func searchSourceDescription(for roomType: RoomType) -> String {
        switch roomType {
        case .armory:
            return ["Behind a weapon rack", "Under a fallen shield", "In a rusted locker",
                    "Beneath a pile of broken blades"].randomElement()!
        case .library:
            return ["Hidden behind old tomes", "In a scholar's desk drawer", "Tucked inside a hollowed book",
                    "Under a pile of scrolls"].randomElement()!
        case .shrine:
            return ["At the base of the altar", "In a prayer niche", "Behind a sacred tapestry",
                    "Inside a reliquary"].randomElement()!
        case .prison:
            return ["Hidden in a loose stone", "Under a pile of straw", "Wedged between iron bars",
                    "In a prisoner's hollow boot"].randomElement()!
        case .treasure:
            return ["In a hidden compartment", "Behind a false wall panel", "Under the main hoard",
                    "Inside a locked chest"].randomElement()!
        case .chamber:
            return ["In a crack in the wall", "Behind a fallen pillar", "Under broken furniture",
                    "In a dusty corner"].randomElement()!
        case .corridor:
            return ["In a gap between stones", "Behind a loose brick", "Wedged in a wall crack"].randomElement()!
        case .trap:
            return ["Near the trap mechanism", "Hidden by the trap builder", "In a maintenance alcove"].randomElement()!
        default:
            return "Hidden stash"
        }
    }

    /// Thematic hint when search fails but items remain
    private func searchFailHints(for roomType: RoomType) -> String {
        switch roomType {
        case .armory:
            return ["You don't find anything yet, but some of these weapon racks look like they have false backs...",
                    "Nothing this time, but you notice scratches near one of the armour stands...",
                    "You come up empty, but something glints in the shadows of the armoury..."].randomElement()!
        case .library:
            return ["You don't find anything, but some of these books look like they could be hiding something...",
                    "Nothing yet, but you notice a desk drawer that seems stuck — worth another look...",
                    "You come up empty, but a hollow sound from one of the shelves catches your attention..."].randomElement()!
        case .shrine:
            return ["You don't find anything, but the altar has carvings that might conceal a compartment...",
                    "Nothing yet, but there's a loose flagstone near the shrine...",
                    "You come up empty, but a faint shimmer near the offering bowl draws your eye..."].randomElement()!
        case .prison:
            return ["You don't find anything, but some of these stones look loose...",
                    "Nothing yet, but there are scratch marks near one of the cells — a hiding spot?",
                    "You come up empty, but a pile of straw in the corner looks recently disturbed..."].randomElement()!
        case .treasure:
            return ["You don't find anything more, but this room clearly held great wealth — there may be hidden compartments...",
                    "Nothing yet, but the walls have suspicious seams...",
                    "You come up empty, but you suspect a false panel nearby..."].randomElement()!
        case .chamber:
            return ["You don't find anything, but the room is large — there may be something you missed...",
                    "Nothing this time, but a draught from the walls suggests a hidden space...",
                    "You come up empty, though something in the shadows catches your eye..."].randomElement()!
        default:
            return ["You don't find anything, but you suspect there may still be something here...",
                    "Nothing this time. Still, something about this room nags at you...",
                    "You come up empty, but your instincts say there's more to find..."].randomElement()!
        }
    }

    // MARK: - Listen at Doors

    private func listenAtDoors() {
        guard let room = dungeon?.currentRoom, let dungeon = dungeon else { return }

        clearTerminal()
        printExplorationMap()
        print("")

        advanceTime(5)

        // Perception check — d20 + best perception vs DC 12
        let roll = Dice.d20()
        // Uses the override actor's own Perception if one is set (Actions >
        // Acting As), else automatically whoever in the party has the best.
        let bestPerception = actingOverrideCharacter?.skillModifier(for: .perception)
            ?? (party.map { $0.skillModifier(for: .perception) }.max() ?? 0)
        // Bonus +2 in the dark (ears sharpen)
        let darkBonus = torchLit ? 0 : 2
        let total = roll + bestPerception + darkBonus

        SoundManager.shared.playListenStart()
        printWrapped("You press your ear to the cold stone...", indent: 2, color: .cyan)
        print("")

        if total >= 12 {
            // Success — reveal adjacent room hints with foley sounds
            var heard: [(text: String, sound: () -> Void)] = []
            for (direction, roomId) in room.exits {
                guard let adjRoom = dungeon.rooms[roomId] else { continue }
                let hint: String
                let sfx: () -> Void
                if adjRoom.roomType == .boss {
                    hint = "Something massive stirs to the \(direction.rawValue.lowercased()). Best prepare."
                    sfx = { SoundManager.shared.playListenBoss() }
                } else if adjRoom.encounter != nil && !adjRoom.cleared {
                    let sounds = [
                        ("Growling to the \(direction.rawValue.lowercased()).", { SoundManager.shared.playListenGrowl() }),
                        ("Scraping claws to the \(direction.rawValue.lowercased()).", { SoundManager.shared.playListenScraping() }),
                        ("Heavy breathing from the \(direction.rawValue.lowercased()).", { SoundManager.shared.playListenBreathing() }),
                        ("Movement to the \(direction.rawValue.lowercased()).", { SoundManager.shared.playListenScraping() }),
                    ]
                    let pick = sounds.randomElement()!
                    hint = pick.0; sfx = pick.1
                } else if adjRoom.roomType == .treasure || adjRoom.hiddenGold > 0 {
                    hint = "The clink of coins to the \(direction.rawValue.lowercased())."
                    sfx = { SoundManager.shared.playListenCoins() }
                } else if adjRoom.roomType == .shop {
                    hint = "Someone humming a tune to the \(direction.rawValue.lowercased())."
                    sfx = { SoundManager.shared.playListenHumming() }
                } else if adjRoom.npc != nil {
                    hint = "A voice murmuring to the \(direction.rawValue.lowercased())."
                    sfx = { SoundManager.shared.playListenHumming() }
                } else if adjRoom.roomType == .trap && !adjRoom.trapTriggered {
                    hint = "A faint clicking sound to the \(direction.rawValue.lowercased())."
                    sfx = { SoundManager.shared.playListenClicking() }
                } else {
                    hint = "Silence to the \(direction.rawValue.lowercased())."
                    sfx = { SoundManager.shared.playListenSilence() }
                }
                heard.append((hint, sfx))
            }

            // Play the most interesting sound heard
            if let bestSound = heard.first(where: { !$0.text.hasPrefix("Silence") }) ?? heard.first {
                bestSound.sound()
            }

            for h in heard {
                printWrapped("  \(h.text)", indent: 2, color: .yellow)
            }
            if !torchLit {
                print("")
                printWrapped("(Your hearing is keener in the dark.)", indent: 2, color: .dimGreen)
            }
            logEvent("Listened at doors in \(room.name) — heard \(heard.count) sounds", category: "EXPLORE")
        } else {
            SoundManager.shared.playListenHeartbeat()
            printWrapped("You press your ear to the stone... nothing. Just your own heartbeat.", indent: 2, color: .dimGreen)
            logEvent("Listened at doors in \(room.name) — heard nothing", category: "EXPLORE")
        }
        logMultiplayerAction("Listened at doors in \(room.name)")

        autoReturn()
    }

    // MARK: - Examine Room

    private func examineRoom() {
        guard let room = dungeon?.currentRoom, let dungeon = dungeon else { return }

        clearTerminal()
        printExplorationMap()
        print("")

        advanceTime(10)

        printWrapped("You examine the \(room.name.lowercased()) closely...", indent: 2, color: .cyan)
        print("")

        // Room-type-specific interactions
        switch room.roomType {
        case .library:
            let outcomes = [
                ("You find a faded journal hinting at the dungeon's history. Ancient builders feared what they awoke below.", TerminalColor.yellow, false),
                ("A scroll tucked between the books catches your eye — it describes a warding spell.", TerminalColor.brightGreen, false),
                ("The books are mostly ruined, but one contains a partial map of this level.", TerminalColor.yellow, false),
                ("You decipher an old text. It warns: 'The deeper chambers hold treasures guarded by the restless dead.'", TerminalColor.yellow, false),
            ]
            let (text, color, _) = outcomes.randomElement()!
            printWrapped(text, indent: 2, color: color)

        case .shrine:
            let roll = Dice.d20()
            if roll >= 10 {
                printWrapped("You study the altar and feel a warmth flow through you. A blessing!", indent: 2, color: .brightGreen)
                printWrapped("(+1 to your next roll)", indent: 2, color: .yellow)
                // Apply a minor blessing — store in status message
                explorationStatusMessage = ("Blessed: +1 to next roll", .yellow)
            } else {
                printWrapped("The shrine feels cold and unwelcoming. A sense of unease settles over you.", indent: 2, color: .dimGreen)
            }

        case .armory:
            let outcomes = [
                "You inspect the weapon racks. Most are broken, but the metalwork suggests skilled craftsmanship.",
                "The armour stands are mostly empty. Scratch marks suggest the contents were taken in haste.",
                "You find a whetstone wedged behind a rack. Could be useful for sharpening blades.",
                "Dents in the wall suggest training dummies once stood here. This was a practice hall.",
            ]
            printWrapped(outcomes.randomElement()!, indent: 2, color: .yellow)

        case .prison:
            let outcomes = [
                "The cells are empty now, but scratches on the walls tell stories of desperate prisoners.",
                "You find names carved into the stone. Some are centuries old.",
                "One cell door hangs open. The lock was picked from the inside — someone escaped.",
                "Bones lie in the corner of one cell. Whatever was here did not escape.",
            ]
            printWrapped(outcomes.randomElement()!, indent: 2, color: .yellow)

        case .trap:
            if room.trapTriggered {
                printWrapped("You study the sprung trap mechanism carefully. You learn to spot the telltale signs.", indent: 2, color: .brightGreen)
                printWrapped("(+2 to Perception checks for traps ahead)", indent: 2, color: .yellow)
            } else {
                printWrapped("The room looks ordinary, but something feels off. Best to tread carefully.", indent: 2, color: .dimGreen)
            }

        case .treasure:
            printWrapped("The room was clearly a vault. Empty mounting hooks line the walls, and lock mechanisms are built into the floor.", indent: 2, color: .yellow)

        case .boss:
            printWrapped("The air is heavy here. Something powerful has claimed this space. The walls bear claw marks far larger than any you've seen.", indent: 2, color: .red)

        case .shop:
            printWrapped("A makeshift market stall. Whoever runs this place has carved out a surprisingly cosy corner of the dungeon.", indent: 2, color: .yellow)

        default:
            let generic = [
                "The walls are damp and cold. Faded carvings hint at the room's former purpose.",
                "You notice old torch sconces along the walls. This corridor was once well-lit.",
                "Dust lies thick on every surface. No one has passed through here in some time.",
                "The stonework here is cruder than elsewhere — a later addition to the dungeon.",
                "You spot faint footprints in the dust. Something has been here recently.",
            ]
            printWrapped(generic.randomElement()!, indent: 2, color: .yellow)
        }

        logEvent("Examined \(room.name)", category: "EXPLORE")
        logMultiplayerAction("Examined \(room.name)")

        autoReturn()
    }

    // MARK: - Secure Room

    private func secureRoom() {
        guard let room = dungeon?.currentRoom, let dungeon = dungeon else { return }

        clearTerminal()
        printExplorationMap()
        print("")
        printSubtitle("Secure Exits")

        // Show current secured status
        let allExits = room.exits.sorted(by: { $0.key.rawValue < $1.key.rawValue })
        for (dir, _) in allExits {
            let isSecured = room.secured.contains(dir)
            let icon = isSecured ? "🔒" : "🚪"
            let status = isSecured ? "Secured" : "Open"
            let color: TerminalColor = isSecured ? .brightGreen : .dimGreen
            print("  \(icon) \(dir.rawValue): \(status)", color: color)
        }
        print("")

        // Build options: secure unsecured doors, unsecure secured doors
        var options: [String] = []
        var actions: [() -> Void] = []

        let unsecuredExits = allExits.filter { !room.secured.contains($0.key) }
        let securedExits = allExits.filter { room.secured.contains($0.key) }

        for (dir, _) in unsecuredExits {
            options.append("Secure \(dir.rawValue)")
            actions.append { [weak self] in
                guard let self = self else { return }
                room.secured.insert(dir)
                self.advanceTime(5)
                self.logEvent("Secured \(dir.rawValue) exit in \(room.name)", category: "EXPLORE")
                self.logMultiplayerAction("Secured \(dir.rawValue) door in \(room.name)")
                self.secureRoom()  // Refresh the screen
            }
        }

        for (dir, _) in securedExits {
            options.append("Open \(dir.rawValue)")
            actions.append { [weak self] in
                guard let self = self else { return }
                room.secured.remove(dir)
                self.advanceTime(3)
                self.logEvent("Unsecured \(dir.rawValue) exit in \(room.name)", category: "EXPLORE")
                self.secureRoom()  // Refresh the screen
            }
        }

        options.append("?")
        actions.append { [weak self] in self?.showSecureHelp() }

        options.append("< Back")
        actions.append { [weak self] in self?.showExplorationView() }

        showMenu(options)

        closeHandler = { [weak self] in self?.showExplorationView() }
        menuHandler = { choice in
            if choice >= 1 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

    private func showSecureHelp() {
        showInlineHelp {
            self.printTitle("Secure Help")
            self.print("")
            self.print("  SECURING EXITS", color: .cyan, bold: true)
            self.printWrapped("Barricade a door with debris to prevent monsters from entering through it. Secured exits show XX on the map.", indent: 2, color: .green)
            self.print("")
            self.print("  WHY SECURE?", color: .cyan, bold: true)
            self.printWrapped("Securing a door before resting reduces the chance of a random encounter. It also prevents monsters in adjacent rooms from surprising you.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  REOPENING", color: .cyan, bold: true)
            self.printWrapped("You can reopen a secured door at any time. You'll need to unsecure it before you can travel through it.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    // MARK: - Forage Supplies

    private func forageSupplies() {
        guard let room = dungeon?.currentRoom, let dungeon = dungeon else { return }

        // Already scavenged this room
        if room.searchedFor.contains("foraged") {
            clearTerminal()
            printExplorationMap()
            print("")
            printWrapped("You've already scavenged this room — nothing left to find.", indent: 2, color: .yellow)
            pendingTimeoutKind = .search; autoReturn(after: max(2.5, infoTimeout * 0.8), stretchForReading: false)   // search results move on briskly
            return
        }

        clearTerminal()
        printExplorationMap()
        print("")

        advanceTime(15)
        room.searchedFor.insert("foraged")

        printWrapped("You scavenge the \(room.name.lowercased()) for useful supplies...", indent: 2, color: .cyan)
        print("")

        // Room-type-specific foraging
        var foundItem: Item? = nil
        var foundGold = 0
        var flavourText = ""

        switch room.roomType {
        case .library:
            let roll = Int.random(in: 1...100)
            if roll <= 40 {
                foundItem = Item(id: UUID(), name: "Ink & Parchment", description: "Valuable writing supplies.",
                                 type: .misc, weight: 1.0, value: 15, weaponStats: nil, armorStats: nil, potionStats: nil)
                flavourText = "You salvage some ink and usable parchment from the shelves."
            } else {
                flavourText = "The books are too damaged to salvage, but the knowledge lingers."
            }

        case .shrine:
            let roll = Int.random(in: 1...100)
            if roll <= 35 {
                foundItem = Item(id: UUID(), name: "Holy Water", description: "Blessed water. Bonus damage vs undead.",
                                 type: .misc, weight: 1.0, value: 25, weaponStats: nil, armorStats: nil, potionStats: nil)
                flavourText = "You fill a vial from the blessed font at the altar."
            } else {
                flavourText = "The shrine's offerings have long since been taken."
            }

        case .armory:
            let roll = Int.random(in: 1...100)
            if roll <= 45 {
                let supplies = [
                    Item(id: UUID(), name: "Whetstone", description: "Sharpens blades.",
                         type: .misc, weight: 1.0, value: 5, weaponStats: nil, armorStats: nil, potionStats: nil),
                ]
                foundItem = supplies.randomElement()!
                flavourText = "You find a usable whetstone among the debris."
            } else {
                flavourText = "The armoury has been picked clean. Nothing useful remains."
            }

        case .prison:
            let roll = Int.random(in: 1...100)
            if roll <= 40 {
                foundItem = ItemCatalog.thievesTools()
                flavourText = "You find a set of lockpicks hidden in a cell wall crack."
            } else {
                flavourText = "The cells yield nothing but despair."
            }

        default:
            let roll = Int.random(in: 1...100)
            if roll <= 30 {
                let genericSupplies: [() -> Item] = [ItemCatalog.torch, ItemCatalog.rope]
                foundItem = genericSupplies.randomElement()!()
                flavourText = "You scavenge something useful from the debris."
            } else if roll <= 45 {
                foundGold = Int.random(in: 1...8)
                flavourText = "You find \(foundGold) gold coins lodged in a crack."
            } else {
                flavourText = "You search thoroughly but find nothing worth taking."
            }
        }

        printWrapped(flavourText, indent: 2, color: foundItem != nil || foundGold > 0 ? .brightGreen : .dimGreen)

        if let item = foundItem {
            let source = "Foraged in \(room.name)"
            logEvent("Foraged \(item.name) in \(room.name)", category: "EXPLORE")
            logMultiplayerAction("Foraged supplies in \(room.name)")
            showItemPickupMenu(item: item, source: source) { [weak self] in
                self?.showExplorationView()
            }
            return
        } else if foundGold > 0 {
            let source = "Foraged in \(room.name)"
            logEvent("Foraged \(foundGold) gold in \(room.name)", category: "EXPLORE")
            logMultiplayerAction("Foraged supplies in \(room.name)")
            showGoldPickupMenu(gold: foundGold, source: source) { [weak self] in
                self?.showExplorationView()
            }
            return
        }

        logEvent("Foraged \(room.name) — nothing found", category: "EXPLORE")
        logMultiplayerAction("Foraged supplies in \(room.name)")

        pendingTimeoutKind = .search; autoReturn(after: max(2.5, infoTimeout * 0.8), stretchForReading: false)   // search results move on briskly
    }

    // MARK: - Talk to NPC

    /// Rooms whose NPC has already been asked about the main quest.
    private var questAskedRooms = Set<Int>()

    /// Someone down here may know where the prize is kept, or what to do
    /// with it — or at least who to ask. Each person answers once.
    private func askAboutMainQuest(npc: DungeonNPC, roomId: Int) {
        guard var mq = mainQuest else { return }
        let who = npc.type.rawValue.lowercased()
        print("")
        if questAskedRooms.contains(roomId) {
            printWrapped("\"I've told you all I know,\" says the \(who).", indent: 2, color: .yellow)
        } else if let name = mq.deadlineName, let day = mq.deadlineDay, mq.deadlineKnown != true, mq.deadlinePassed != true {
            questAskedRooms.insert(roomId)
            mq.deadlineKnown = true
            mainQuest = mq
            let left = max(0, day - (gameTimeMinutes / 1440 + 1))
            let cap = name.prefix(1).uppercased() + name.dropFirst()
            printWrapped("The \(who) counts on their fingers. \"\(cap)? That's \(left == 0 ? "today" : "\(left) day\(left == 1 ? "" : "s") off"). After that, it'll be too late to stop what's coming — though you might still put it right, after.\"", indent: 2, color: .yellow)
            print("")
            printWrapped("(The countdown now shows under the date on the play screen.)", indent: 2, color: .dimGreen)
            logEvent("Learned the quest's deadline: \(name), day \(day)", category: "QUEST")
        } else if Int.random(in: 1...10) <= 6, let clue = mq.nextClue {
            questAskedRooms.insert(roomId)
            mq.cluesLearned = (mq.cluesLearned ?? []) + [clue]
            mainQuest = mq
            printWrapped("The \(who) looks around, then lowers their voice. \"\(clue)\"", indent: 2, color: .yellow)
            print("")
            printWrapped("(Noted under your main quest in Party Status.)", indent: 2, color: .dimGreen)
            if Int.random(in: 1...3) == 1 {
                print("")
                printWrapped("\"And if you ever lose your way,\" they add, \"hold your map a little longer than usual. Old maps down here have a magic in them.\"", indent: 2, color: .yellow)
            }
            logEvent("Quest clue from the \(who): \(clue)", category: "QUEST")
        } else {
            questAskedRooms.insert(roomId)
            let pointer = mq.informant.map { "Ask \($0) — they'd know." } ?? "Keep going down. The answers are always further down."
            printWrapped("The \(who) shrugs. \"Not my business. \(pointer)\"", indent: 2, color: .yellow)
        }
        waitForContinue()
        inputHandler = { [weak self] _ in self?.talkToNPC() }
    }

    private func talkToNPC() {
        guard let room = dungeon?.currentRoom, var npc = room.npc, let dungeon = dungeon else { return }

        clearTerminal()
        printExplorationMap()
        print("")

        // Show NPC art and info
        printLines(npc.type.asciiArt, color: .cyan)
        print("")
        print("  \(npc.type.rawValue)", color: .brightGreen, bold: true)
        printWrapped(npc.type.description, indent: 2, color: .dimGreen)
        print("")

        // Assign a voice to this NPC if they don't have one yet
        if npc.voiceIdentifier == nil {
            let charNames = party.map { $0.name }
            npc.voiceIdentifier = SpeechEngine.shared.pickNPCVoice(excludingCharacterNames: charNames)
        }

        // Greeting (first time)
        if !npc.hasBeenTalkedTo {
            let greeting = npc.type == .gatekeeper
                ? npc.type.gatekeeperGreeting(trustworthiness: npc.trustworthiness)
                : npc.type.greeting
            printWrapped("\"\(greeting)\"", indent: 2, color: .yellow)
            print("")
            npc.hasBeenTalkedTo = true
            room.npc = npc
            recordNPCEncounter(npc.type)
            logEvent("Met \(npc.type.rawValue) in \(room.name)", category: "NPC")
            // Speak the intro (name + description, printed above in dimGreen
            // — a colour the normal read-aloud pipeline treats as a
            // decorative nav hint and skips) together with the greeting in
            // the NPC's voice, then mark the page read so the generic
            // pipeline doesn't also read the greeting a second time in the
            // narrator voice.
            if speakerModeOn, let voiceId = npc.voiceIdentifier {
                speakerHasReadCurrentPage = true
                SpeechEngine.shared.speakAsNPC("\(npc.type.rawValue). \(npc.type.description) \(greeting)", voiceId: voiceId)
            }
        } else {
            let returnGreetings = [
                "\"Back again? What do you need?\"",
                "\"Ah, you return. Ask away.\"",
                "\"Yes? I'm still here.\"",
            ]
            let greet = returnGreetings.randomElement()!
            printWrapped(greet, indent: 2, color: .yellow)
            print("")
            if speakerModeOn, let voiceId = npc.voiceIdentifier {
                speakerHasReadCurrentPage = true
                let cleanGreet = greet.replacingOccurrences(of: "\"", with: "")
                SpeechEngine.shared.speakAsNPC("\(npc.type.rawValue). \(npc.type.description) \(cleanGreet)", voiceId: voiceId)
            }
        }

        // No main quest: people notice (and some have one going spare).
        if mainQuest == nil, npc.type != .gatekeeper, Int.random(in: 1...10) <= 5 {
            printWrapped("\"\(Self.noQuestNags.randomElement()!)\"", indent: 2, color: .yellow)
            print("")
        }

        // Build capability menu
        var options: [MenuOption] = []
        var actions: [() -> Void] = []

        // Topic buttons
        for topic in npc.type.knownTopics {
            // "Ask: Quest" leads to an actionable quest-acceptance flow
            // (the Gatekeeper's), not just lore — tinted the same as
            // "Ask to Trade"/"Ask for a Quest" rather than the generic
            // topic amber.
            options.append(MenuOption("Ask: \(topic)", tint: topic == "Quest" ? .cyan : .amber))
            actions.append { [weak self] in
                self?.askNPCAbout(topic: topic)
            }
        }

        // The main quest: anyone down here might know something.
        if mainQuest != nil, npc.type != .gatekeeper {
            let roomId = room.id
            options.append(MenuOption("Ask About Our Quest", tint: .cyan))
            actions.append { [weak self] in self?.askAboutMainQuest(npc: npc, roomId: roomId) }
        }
        if mainQuest == nil, npc.type != .gatekeeper {
            let roomId = room.id
            options.append(MenuOption("Ask for a Quest", tint: .cyan))
            actions.append { [weak self] in self?.hearNPCMainQuest(npc: npc, roomId: roomId) }
        }

        // Capability buttons
        if npc.type.canTrade && !npc.hasTraded {
            options.append(MenuOption("Trade", tint: .cyan))
            actions.append { [weak self] in self?.tradeWithNPC() }
        } else if !npc.hasOfferedOneOffTrade {
            options.append(MenuOption("Ask to Trade", tint: .cyan))
            actions.append { [weak self] in self?.askNPCToTrade() }
        }

        if npc.type.canHeal {
            options.append(MenuOption("Request Healing", tint: .cyan))
            actions.append { [weak self] in self?.requestNPCHealing() }
        }

        if npc.type.canRepair {
            options.append(MenuOption("Repair Gear", tint: .cyan))
            actions.append { [weak self] in self?.requestNPCRepair() }
        }

        if npc.type.canTeach && !npc.hasTaught {
            options.append(MenuOption("Learn", tint: .cyan))
            actions.append { [weak self] in self?.learnFromNPC() }
        }

        if npc.type.canCurePoison {
            let hasPoisoned = party.contains { $0.isPoisoned }
            if hasPoisoned {
                options.append(MenuOption("Cure Poison", tint: .cyan))
                actions.append { [weak self] in self?.requestNPCCurePoison() }
            }
        }

        // Side quest offer — any NPC but the Gatekeeper (who has their own
        // separate "slay the boss" quest), decided once per NPC and only
        // shown while no other quest is active (one at a time).
        if npc.type != .gatekeeper, !npc.sideQuestOffered {
            // Almost anyone will offer a quest (older saves re-roll a "no").
            if npc.willOfferSideQuest != true {
                npc.willOfferSideQuest = Int.random(in: 1...100) <= 90
                room.npc = npc
            }
            if npc.willOfferSideQuest == true, canTakeAnotherQuest, !allQuests.contains(where: { $0.giverName == npc.type.rawValue }) {
                options.append(MenuOption("Side Quest", tint: .cyan))
                actions.append { [weak self] in self?.offerSideQuest() }
            }
        }

        // A bard in the party can play for them — once each.
        if let bard = party.first(where: { $0.characterClass == .bard && $0.isConscious }),
           !performedRoomKeys.contains(performKey(room)) {
            let audience = npc.displayName
            options.append(MenuOption("Play a Tune", tint: .cyan))
            actions.append { [weak self] in
                self?.bardPerform(bard, audience: audience, room: room, returnTo: { [weak self] in self?.talkToNPC() })
            }
        }

        // Help
        options.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showNPCHelp() }

        // Back to exploration
        options.append(MenuOption("< Back", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showExplorationView() }

        showMenuOptions(options)
        closeHandler = { [weak self] in
            self?.showExplorationView()
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

    /// Gold penalty for abandoning the active quest — reneging costs the
    /// party's standing with whoever gave it, represented mechanically as a
    /// flat toll (scaled to dungeon level) taken from whoever in the party
    /// can afford the most of it, never pushing anyone below zero. Returns
    /// the amount actually collected (can be less than the nominal penalty,
    /// or 0, if the party is broke).
    @discardableResult
    private func chargeQuestAbandonPenalty() -> Int {
        let penalty = 20 + (dungeon?.level ?? 1) * 10
        var remaining = penalty
        for char in party.sorted(by: { $0.gold > $1.gold }) {
            guard remaining > 0 else { break }
            let take = min(char.gold, remaining)
            char.gold -= take
            remaining -= take
        }
        return penalty - remaining
    }

    /// Abandoning a quest partway through is a deliberate choice (you lose
    /// whatever progress you'd made, pay a toll for reneging, and clear the
    /// way for a different NPC to offer something new), so it goes through a
    /// confirm step rather than a single tap — same weight as other one-way
    /// actions in the game. `returnTo` is wherever this was reached from
    /// (Party Status, or the quest-giver's own conversation screen).
    /// Gives up the active quest — the confirmed path of confirmAbandonQuest,
    /// and what a long-press on Give Up Quest does directly.
    private func abandonActiveQuest(returnTo: @escaping () -> Void) {
        guard let quest = activeQuest else { returnTo(); return }
        let charged = chargeQuestAbandonPenalty()
        logEvent("Gave up quest: \(quest.description) (paid \(charged) gold in lost goodwill)", category: "QUEST")
        activeQuest = otherQuests.isEmpty ? nil : otherQuests.removeFirst()
        print("  The party's reputation takes a hit — \(charged) gold poorer for it.", color: .yellow)
        waitForContinueWithTimeout { returnTo() }
    }

    private func confirmAbandonQuest(returnTo: @escaping () -> Void) {
        guard let quest = activeQuest else { returnTo(); return }
        let penalty = 20 + (dungeon?.level ?? 1) * 10
        clearTerminal()
        printTitle("Give Up This Quest?")
        print("")
        print("  \(quest.giverName): \(quest.description)", color: .yellow)
        print("")
        printWrapped("Any progress is lost, and \(quest.giverName) won't offer it again. Word gets around — reneging costs the party's standing, about \(penalty) gold's worth of goodwill. You'll be free to accept a different quest from someone else.", indent: 2, color: .dimGreen)
        print("")
        showMenu(["Yes, Give It Up", "No, Keep It"])
        closeHandler = returnTo
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.abandonActiveQuest(returnTo: returnTo)
            } else {
                returnTo()
            }
        }
    }

    private func offerSideQuest() {
        guard let room = dungeon?.currentRoom, var npc = room.npc, let dungeon = dungeon else { return }
        let totalGold = party.reduce(0) { $0 + $1.gold }
        let quest = SideQuest.random(level: dungeon.level, giverName: npc.type.rawValue,
                                     monstersSlain: monstersSlain, partyGold: totalGold, party: party, dungeon: dungeon)

        clearTerminal()
        printExplorationMap()
        print("")
        printTitle("A Quest?")
        print("")
        printWrapped("\"I have a task for you, if you're willing: \(quest.description). Do this and I'll see you rewarded with \(quest.reward.description).\"", indent: 2, color: .yellow)
        print("")

        showMenu(["Accept", "Decline"])
        closeHandler = { [weak self] in self?.talkToNPC() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            npc.sideQuestOffered = true
            room.npc = npc
            if choice == 1 {
                self.addQuest(quest)
                self.print("  Quest accepted: \(quest.description)", color: .brightGreen)
                if self.allQuests.count > 1 {
                    self.print("  The party is now on \(self.allQuests.count) quests at once (room for \(self.questCapacity)).", color: .cyan)
                }
                self.logEvent("Accepted quest from \(quest.giverName): \(quest.description)", category: "QUEST")
                self.waitForContinueWithTimeout { self.talkToNPC() }
            } else {
                self.talkToNPC()
            }
        }
    }

    /// Human-readable progress line for the active quest — shown in Party
    /// Status so a quest accepted a while ago isn't forgotten.
    private func sideQuestProgressDescription(_ quest: SideQuest) -> String {
        switch quest.type {
        case .defeatMonsters:
            let done = min(quest.target, monstersSlain - quest.startMonstersSlain)
            return "Progress: \(done)/\(quest.target) monsters defeated"
        case .collectGold:
            let totalGold = party.reduce(0) { $0 + $1.gold }
            let done = min(quest.target, totalGold - quest.startPartyGold)
            return "Progress: \(done)/\(quest.target) gold gathered"
        case .fullyEquipped:
            let active = party.filter { $0.isConscious }
            let equipped = active.filter { $0.equippedWeapon != nil && $0.equippedArmor != nil && $0.equippedShield != nil }.count
            return "Progress: \(equipped)/\(active.count) fully armed"
        case .reachLevel:
            let best = party.map { $0.level }.max() ?? 0
            return "Progress: highest level is \(best) (need \(quest.target))"
        case .visitRoomType:
            let found = dungeon?.rooms.values.contains { $0.roomType == quest.targetRoomType && $0.visited } ?? false
            return found ? "Progress: found it!" : "Progress: not found yet"
        case .slayBoss:
            return "Progress: the creature still lurks below"
        }
    }

    /// True if the active quest's condition is currently met. Absolute
    /// checks (fullyEquipped/reachLevel) read live state directly;
    /// cumulative checks (defeatMonsters/collectGold) measure the change
    /// since the quest's own start baseline.
    private func isSideQuestComplete(_ quest: SideQuest) -> Bool {
        switch quest.type {
        case .defeatMonsters:
            return monstersSlain - quest.startMonstersSlain >= quest.target
        case .collectGold:
            let totalGold = party.reduce(0) { $0 + $1.gold }
            return totalGold - quest.startPartyGold >= quest.target
        case .fullyEquipped:
            let active = party.filter { $0.isConscious }
            guard !active.isEmpty else { return false }
            return active.allSatisfy { $0.equippedWeapon != nil && $0.equippedArmor != nil && $0.equippedShield != nil }
        case .reachLevel:
            return party.contains { $0.level >= quest.target }
        case .visitRoomType:
            return dungeon?.rooms.values.contains { $0.roomType == quest.targetRoomType && $0.visited } ?? false
        case .slayBoss:
            // Never auto-completes here — the boss fight ends the game
            // entirely, a distinct flow handled directly in
            // handleGameVictory() instead of the generic exploration check.
            return false
        }
    }

    /// Checks the active quest and, if complete, clears it and shows the
    /// completion screen. Returns true when it did — callers (mainly
    /// showExplorationView()) should skip their own render in that case.
    private func checkAndShowSideQuestCompletion() -> Bool {
        if let quest = activeQuest, isSideQuestComplete(quest) {
            activeQuest = otherQuests.isEmpty ? nil : otherQuests.removeFirst()
            showSideQuestComplete(quest)
            return true
        }
        if let i = otherQuests.firstIndex(where: { self.isSideQuestComplete($0) }) {
            let quest = otherQuests.remove(at: i)
            showSideQuestComplete(quest)
            return true
        }
        // Slow going? The quest-giver comes chasing.
        if let i = overdueQuestIndex() {
            showQuestChaser(index: i, quest: allQuests[i])
            return true
        }
        return false
    }

    /// A quest left too long: 8 game hours after taking it, then every 6
    /// hours. (Quests from older saves start their clock now.)
    private func overdueQuestIndex() -> Int? {
        for (i, q) in allQuests.enumerated() where q.acceptedAt == nil {
            updateQuest(at: i) { $0.acceptedAt = gameTimeMinutes }
        }
        for (i, q) in allQuests.enumerated() where q.type != .slayBoss {
            guard let start = q.acceptedAt else { continue }
            if gameTimeMinutes - start >= 8 * 60 + (q.chaseCount ?? 0) * 6 * 60 { return i }
        }
        return nil
    }

    /// The quest-giver's snotty reminder: carry on, ask for more, or give up.
    private func showQuestChaser(index: Int, quest: SideQuest) {
        updateQuest(at: index) { $0.chaseCount = ($0.chaseCount ?? 0) + 1 }
        clearTerminal()
        printExplorationMap()
        print("")
        printTitle("A Message from \(quest.giverName)")
        let nags = [
            "\"Well? I asked you to see to it — \(quest.description.lowercased()) — and here you are, dawdling. Are you doing it or not?\"",
            "\"I don't suppose you've forgotten my little task? No? Then why isn't it done?\"",
            "\"Word travels, you know. Word says you've been wandering about instead of helping me.\"",
            "\"Tick tock, adventurers. My task won't finish itself.\"",
        ]
        printWrapped(nags.randomElement()!, indent: 2, color: .yellow)
        print("")
        printWrapped("Quest: \(quest.description) — \(sideQuestProgressDescription(quest))", indent: 2, color: .dimGreen)
        print("")
        showMenu(["We're On It", "Make It Worthwhile?", "Give It Up"])
        closeHandler = { [weak self] in self?.showExplorationView() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.print("")
                self.printWrapped("\"Hmph. See that you are.\"", indent: 2, color: .yellow)
                self.waitForContinueWithTimeout(multiplier: 1.0) { self.showExplorationView() }
            case 2:
                let talker = self.party.filter { $0.isConscious }.max { $0.skillModifier(for: .persuasion) < $1.skillModifier(for: .persuasion) } ?? self.party.first
                let mod = talker?.skillModifier(for: .persuasion) ?? 0
                let roll = Dice.d20()
                self.print("")
                self.print("  \(talker?.name ?? "You") bargains: Persuasion d20[\(roll)] + \(mod) vs DC 13", color: .dimGreen)
                if roll + mod >= 13 {
                    let bonus = 20 + (self.dungeon?.level ?? 1) * 15
                    self.updateQuest(at: index) { $0.extraGold = ($0.extraGold ?? 0) + bonus }
                    self.printWrapped("\"Fine, FINE. Another \(bonus) gold when it's done. Now get on with it!\"", indent: 2, color: .brightGreen)
                } else {
                    self.printWrapped("\"More? The cheek of it! The reward stands — take it or leave it.\"", indent: 2, color: .yellow)
                }
                self.waitForContinueWithTimeout(multiplier: 1.2) { self.showExplorationView() }
            default:
                self.abandonQuest(at: index)
            }
        }
    }

    /// Drops one particular quest (not necessarily the first).
    private func abandonQuest(at index: Int) {
        let quests = allQuests
        guard quests.indices.contains(index) else { showExplorationView(); return }
        let quest = quests[index]
        if activeQuest != nil && index == 0 {
            activeQuest = otherQuests.isEmpty ? nil : otherQuests.removeFirst()
        } else {
            otherQuests.remove(at: activeQuest != nil ? index - 1 : index)
        }
        let charged = chargeQuestAbandonPenalty()
        logEvent("Gave up quest: \(quest.description) (paid \(charged) gold in lost goodwill)", category: "QUEST")
        print("")
        printWrapped("\"Typical. I'll find someone who can.\" \(quest.giverName)'s task is dropped — the party's standing costs \(charged) gold.", indent: 2, color: .yellow)
        waitForContinueWithTimeout(multiplier: 1.0) { [weak self] in self?.showExplorationView() }
    }

    /// Applies a quest reward immediately and returns a short description —
    /// used for the Gatekeeper's slayBoss reward, which resolves inline as
    /// part of the victory screen (the game is ending) rather than through
    /// showSideQuestComplete()'s own screen/continuation. SideQuest.random()
    /// never offers newSkill/specialSpell/instantLevelUp/familiar for
    /// slayBoss specifically (none of them mean anything once the adventure
    /// is over), but this stays exhaustive in case that ever changes.
    private func applyQuestRewardInline(_ reward: SideQuestReward) -> String {
        switch reward {
        case .bonusGold(let amount):
            let eligible = party.filter { $0.isConscious }
            let recipients = eligible.isEmpty ? party : eligible
            let each = max(1, amount / recipients.count)
            for char in recipients { char.gold += each }
            return "\(amount) gold (\(each) each)"
        case .titleSuffix(let suffix):
            if let honoree = party.filter({ $0.isConscious }).randomElement() ?? party.first {
                if !honoree.name.hasSuffix(suffix) { honoree.name = "\(honoree.name) \(suffix)" }
                return "\(honoree.name) is honored with the title \"\(suffix)\""
            }
            return reward.description
        case .maxHPBoost(let amount):
            for char in party { char.maxHP += amount; char.currentHP += amount }
            return "+\(amount) max HP for the whole party"
        case .certificate(let name):
            if let recipient = party.filter({ $0.isConscious }).randomElement() ?? party.first {
                let item = Item(id: UUID(), name: name, description: "A framed certificate — mostly for bragging rights.",
                                 type: .misc, weight: 0.1, value: 1, weaponStats: nil, armorStats: nil, potionStats: nil)
                _ = recipient.addItem(item)
                return "\(recipient.name) receives a \(name)"
            }
            return reward.description
        case .newSkill, .specialSpell, .instantLevelUp, .familiar:
            return reward.description
        }
    }

    private func showSideQuestComplete(_ quest: SideQuest) {
        clearTerminal()
        SoundManager.shared.playLevelUp()
        DispatchQueue.main.async { [weak self] in self?.dragonGifName = "dragon_flapping" }

        // Big, hard-to-miss fanfare — matches the level-up banner treatment
        // rather than a quiet one-line confirmation, since a whole quest
        // (not just one lucky roll) just paid off.
        printLines([
            "   ✦ · ✦ · ✦ · ✦ · ✦ · ✦   ",
            "   Q U E S T   C O M P L E T E !   ",
            "   ✦ · ✦ · ✦ · ✦ · ✦ · ✦   ",
        ], color: .yellow)
        print("")
        print("  \(quest.giverName)'s task is done: \(quest.description)", color: .brightGreen, bold: true)
        print("")
        if let extra = quest.extraGold, extra > 0 {
            let eligible = party.filter { $0.isConscious }
            let recipients = eligible.isEmpty ? party : eligible
            let each = max(1, extra / max(1, recipients.count))
            for c in recipients { c.gold += each }
            print("  Plus the extra \(extra) gold you talked \(quest.giverName) into (\(each) each).", color: .yellow)
            print("")
        }

        // Instant level-up runs through the normal level-up flow (its own
        // screen, HP roll, spell/feature grants), so it manages its own
        // continuation instead of the generic print-and-wait below.
        if case .instantLevelUp = quest.reward, let recruit = party.filter({ $0.level < 5 }).randomElement() {
            logEvent("Completed quest from \(quest.giverName): \(quest.description)", category: "QUEST")
            logMultiplayerAction("Completed a quest: \(quest.description)")
            showLevelUpScreen(character: recruit) { [weak self] in self?.showExplorationView() }
            return
        }

        switch quest.reward {
        case .bonusGold(let amount):
            let eligible = party.filter { $0.isConscious }
            let recipients = eligible.isEmpty ? party : eligible
            let each = max(1, amount / recipients.count)
            for char in recipients { char.gold += each }
            print("  The party is rewarded with \(amount) gold (\(each) each).", color: .yellow)
        case .titleSuffix(let suffix):
            if let honoree = party.filter({ $0.isConscious }).randomElement() ?? party.first {
                if !honoree.name.hasSuffix(suffix) {
                    honoree.name = "\(honoree.name) \(suffix)"
                }
                print("  \(honoree.name) is honored with \(quest.reward.description)!", color: .yellow)
            }
        case .maxHPBoost(let amount):
            for char in party {
                char.maxHP += amount
                char.currentHP += amount
            }
            print("  The whole party feels hardier: \(quest.reward.description).", color: .yellow)
        case .newSkill:
            let candidates = party.filter { $0.skillProficiencies.count < Skill.allCases.count }
            if let learner = candidates.randomElement(),
               let skill = Skill.allCases.filter({ !learner.skillProficiencies.contains($0) }).randomElement() {
                learner.skillProficiencies.insert(skill)
                print("  \(learner.name) gains proficiency in \(skill.rawValue), free of charge.", color: .yellow)
            } else {
                party.first?.gold += 50
                print("  (Everyone's already well-trained — 50 gold instead.)", color: .yellow)
            }
        case .specialSpell:
            let candidates = party.filter { char in
                guard let spell = SpellCatalog.specialSpellFor(characterClass: char.characterClass) else { return false }
                return !char.knownSpells.contains(where: { $0.name == spell.name })
            }
            if let learner = candidates.randomElement(), let spell = SpellCatalog.specialSpellFor(characterClass: learner.characterClass) {
                learner.knownSpells.append(spell)
                print("  \(learner.name) learns \(spell.name) — \(spell.description)", color: .yellow)
            } else {
                party.first?.gold += 50
                print("  (No one could make use of it — 50 gold instead.)", color: .yellow)
            }
        case .instantLevelUp:
            // No one eligible after all (party changed since offer) — gold instead.
            party.first?.gold += 50
            print("  (No one had room to grow — 50 gold instead.)", color: .yellow)
        case .familiar:
            let candidates = party.filter { $0.familiarName == nil }
            if let owner = candidates.randomElement() {
                let type = SideQuest.familiarTypes.randomElement()!
                let name = SideQuest.familiarNames.randomElement()!
                owner.familiarType = type
                owner.familiarName = name
                print("  \(owner.name) is joined by \(name) the \(type)!", color: .yellow)
            } else {
                party.first?.gold += 50
                print("  (Everyone already has a familiar — 50 gold instead.)", color: .yellow)
            }
        case .certificate(let name):
            if let recipient = party.filter({ $0.isConscious }).randomElement() ?? party.first {
                let item = Item(id: UUID(), name: name, description: "A framed certificate — mostly for bragging rights.",
                                 type: .misc, weight: 0.1, value: 1, weaponStats: nil, armorStats: nil, potionStats: nil)
                _ = recipient.addItem(item)
                print("  \(recipient.name) receives a \(name).", color: .yellow)
            }
        }
        print("")
        logEvent("Completed quest from \(quest.giverName): \(quest.description)", category: "QUEST")
        logMultiplayerAction("Completed a quest: \(quest.description)")

        waitForContinueWithTimeout { [weak self] in self?.showExplorationView() }
    }

    private func askNPCAbout(topic: String) {
        guard let room = dungeon?.currentRoom, var npc = room.npc else { return }

        // Gatekeeper quest flow — handles offering a new (varied) quest,
        // showing progress on one already underway, or explaining that the
        // active quest came from someone else, all in one place.
        if npc.type == .gatekeeper && topic == "Quest" {
            showGatekeeperQuest(npc: npc, room: room)
            return
        }

        // Track how many times this topic has been asked
        let askCount = npc.recordAsk(topic: topic)
        room.npc = npc

        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        printLines(npc.type.asciiArt, color: .cyan)
        print("")
        print("  \(npc.type.rawValue)", color: .brightGreen, bold: true)
        print("")

        let bossType = dungeon?.rooms.values.first(where: { $0.roomType == .boss })?.encounter?.monsters.first?.type

        // Build context from actual dungeon state
        var ctx = NPCType.DungeonContext()
        if let dungeon = dungeon {
            ctx.totalRooms = dungeon.rooms.count
            ctx.clearedRooms = dungeon.rooms.values.filter { $0.cleared || $0.encounter == nil }.count
            for (_, adjId) in room.exits {
                if let adj = dungeon.rooms[adjId] {
                    if let enc = adj.encounter, !adj.cleared {
                        ctx.adjacentMonsterCount += 1
                        for m in enc.monsters {
                            if !ctx.adjacentMonsterNames.contains(m.name) {
                                ctx.adjacentMonsterNames.append(m.name)
                            }
                        }
                    }
                    if adj.roomType == .trap && !adj.trapTriggered { ctx.nearbyTrapCount += 1 }
                    if adj.roomType == .treasure { ctx.nearbyTreasureRooms += 1 }
                    if adj.roomType == .boss { ctx.bossDirection = room.exits.first(where: { $0.value == adjId })?.key.rawValue }
                    if adj.roomType == .shop { ctx.hasShop = true }
                }
            }
        }

        let response: String
        if npc.type == .gatekeeper {
            // "Quest" always returns early above via showGatekeeperQuest().
            response = npc.type.gatekeeperResponse(for: topic, trustworthiness: npc.trustworthiness, dungeonLevel: dungeon?.level ?? 1, bossType: bossType, questGold: npc.questGold, askCount: askCount)
        } else {
            response = npc.type.response(for: topic, dungeonLevel: dungeon?.level ?? 1, bossType: bossType, context: ctx, askCount: askCount)
        }
        printWrapped("\"\(response)\"", indent: 2, color: .yellow)
        print("")

        // Speak response in NPC's voice — mark page as read so auto-read doesn't repeat
        if speakerModeOn, let voiceId = npc.voiceIdentifier {
            speakerHasReadCurrentPage = true
            SpeechEngine.shared.speakAsNPC(response, voiceId: voiceId)
        }

        logEvent("Asked \(npc.type.rawValue) about \(topic)", category: "NPC")

        waitForContinue()
        inputHandler = { [weak self] _ in
            self?.talkToNPC()
        }
    }

    private func showGatekeeperQuest(npc: DungeonNPC, room: Room) {
        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        printLines(npc.type.asciiArt, color: .cyan)
        print("")
        print("  \(npc.type.rawValue)", color: .brightGreen, bold: true)
        print("")

        let bossType = dungeon?.rooms.values.first(where: { $0.roomType == .boss })?.encounter?.monsters.first?.type

        // A quest already underway — from this gatekeeper or someone else —
        // takes priority over offering a new one (only one active at a time).
        if let quest = activeQuest {
            if quest.giverName == npc.type.rawValue {
                printWrapped("\"Your task is still ahead of you.\"", indent: 2, color: .yellow)
                print("")
                print("  Quest: \(quest.description)", color: .cyan)
                print("  Reward: \(quest.reward.description)", color: .brightGreen)
                print("  \(self.sideQuestProgressDescription(quest))", color: .dimGreen)
                print("")
                showMenu(["Abandon Quest", "Keep Going"])
                closeHandler = { [weak self] in self?.talkToNPC() }
                menuHandler = { [weak self] choice in
                    guard let self = self else { return }
                    if choice == 1 {
                        self.confirmAbandonQuest(returnTo: { self.talkToNPC() })
                    } else {
                        self.talkToNPC()
                    }
                }
            } else {
                printWrapped("\"You've already got a task in hand, from \(quest.giverName). See to that first — or give it up, if you'd rather take on something of mine instead.\"", indent: 2, color: .yellow)
                print("")
                showMenu(["Abandon That Quest", "Never Mind"])
                closeHandler = { [weak self] in self?.talkToNPC() }
                menuHandler = { [weak self] choice in
                    guard let self = self else { return }
                    if choice == 1 {
                        self.confirmAbandonQuest(returnTo: { self.talkToNPC() })
                    } else {
                        self.talkToNPC()
                    }
                }
            }
            return
        }

        // No quest active — offer a fresh, varied one (not always "slay the
        // boss for gold"; see SideQuest.random(includeSlayBoss:)).
        guard let dungeon = dungeon else { talkToNPC(); return }
        let totalGold = party.reduce(0) { $0 + $1.gold }
        let quest = SideQuest.random(level: dungeon.level, giverName: npc.type.rawValue,
                                     monstersSlain: monstersSlain, partyGold: totalGold, party: party,
                                     dungeon: dungeon, includeSlayBoss: true)

        let questText = npc.type.gatekeeperResponse(for: "Quest", trustworthiness: npc.trustworthiness, dungeonLevel: dungeon.level, bossType: bossType, questGold: 0)
        printWrapped("\"\(questText)\"", indent: 2, color: .yellow)
        print("")
        print("  Quest: \(quest.description)", color: .cyan)
        print("  Reward: \(quest.reward.description)", color: .brightGreen)
        print("")

        showMenu(["Accept Quest", "Decline"])
        closeHandler = { [weak self] in self?.talkToNPC() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.activeQuest = quest
                self.clearTerminal()
                if let dungeon = self.dungeon {
                    self.printExplorationMap()
                    self.print("")
                }
                self.printLines(npc.type.asciiArt, color: .cyan)
                self.print("")
                self.printWrapped("\"Good. May fortune favour you. Return when the deed is done.\"", indent: 2, color: .yellow)
                self.logEvent("Accepted quest from Gatekeeper: \(quest.description)", category: "QUEST")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.talkToNPC() }
            } else {
                self.talkToNPC()
            }
        }
    }

    private func tradeWithNPC() {
        guard let room = dungeon?.currentRoom, var npc = room.npc, let dungeon = dungeon else { return }
        let merchant: Merchant
        if let existing = npc.merchant {
            merchant = existing
        } else {
            // Generate once and persist immediately — otherwise this
            // Wandering Trader would get a brand new name/stock every
            // single visit instead of being remembered as the same person.
            seedNameRegistry()
            merchant = Merchant.random(tier: .wanderingPeddler)
            npc.merchant = merchant
            room.npc = npc
        }

        // Open the shop with NPC-specific inventory
        // 3-bar ? | < Back instead of a separate "Don't Trade" button —
        // Back returns to the conversation with the trader.
        pickCharacter(title: "Who trades with \(merchant.name)?", onBack: { [weak self] in self?.talkToNPC() }, showGold: true, helpAction: { [weak self] in
            self?.showInlineHelp {
                self?.printTitle("Trading — Help")
                self?.print("")
                self?.printWrapped("Pick who does the trading — it's their gold that pays and their pack the goods go into (the gold shown next to each name). Back returns to the conversation.", indent: 2, color: .dimGreen)
                self?.print("")
            }
        }) { [weak self] character in
            guard let self = self else { return }
            self.shopEngine.openShop(character: character, dungeonLevel: dungeon.level, merchant: merchant) { [weak self] in
                npc.hasTraded = true
                room.npc = npc
                self?.talkToNPC()
            }
        }
    }

    /// Non-merchant NPCs aren't shopkeepers, but the player can still ask if
    /// they'll trade. Most decline in character; a few will sell the one item
    /// they're carrying; a couple might take offence and attack instead.
    private func askNPCToTrade() {
        guard let room = dungeon?.currentRoom, var npc = room.npc else { return }

        clearTerminal()
        printLines(npc.type.asciiArt, color: .cyan)
        print("")
        print("  \(npc.type.rawValue)", color: .brightGreen, bold: true)
        print("")

        npc.hasOfferedOneOffTrade = true
        room.npc = npc

        switch npc.type {
        case .goblinDefector:
            if Int.random(in: 1...100) <= 35 {
                printWrapped("\"Trade?! You think I've got treasure for the likes of you?!\"", indent: 2, color: .red)
                print("")
                printWrapped("The \(npc.type.rawValue) turns on you!", indent: 2, color: .red, bold: true)
                logEvent("\(npc.type.rawValue) turned hostile and attacked", category: "NPC")
                room.npc = nil
                let monster = Monster.create(.goblin, customName: npc.type.rawValue)
                waitForContinue()
                inputHandler = { [weak self] _ in
                    self?.startCombat(encounter: Encounter(monsters: [monster], difficulty: .easy))
                }
                return
            }
            printWrapped("\"Trade? ...Fine. Don't expect charity.\"", indent: 2, color: .yellow)
            offerOneOffNPCSale(item: ItemCatalog.dagger(), price: 15, npc: npc, room: room)
        case .dwarvenSmith:
            if room.merchant != nil {
                // The smith keeps this shop — trading means their counter.
                printWrapped("\"Trade? Step up to the bench and see what I've got.\"", indent: 2, color: .yellow)
                visitShop()
            } else {
                printWrapped("\"Ha! Like my work, do you? I've a spare blade going.\"", indent: 2, color: .yellow)
                offerOneOffNPCSale(item: ItemCatalog.longsword(), price: 20, npc: npc, room: room)
            }
        case .elfScout:
            printWrapped("\"I carry a spare bow. Yours, for the right price.\"", indent: 2, color: .yellow)
            offerOneOffNPCSale(item: ItemCatalog.longbow(), price: 20, npc: npc, room: room)
        case .madAlchemist:
            printWrapped("\"Ooh, a customer! I've a potion here — mostly stable.\"", indent: 2, color: .yellow)
            offerOneOffNPCSale(item: ItemCatalog.greaterHealingPotion(), price: 30, npc: npc, room: room)
        case .woundedKnight:
            printWrapped("\"Take my blade — I've little use for it like this. Name a fair price.\"", indent: 2, color: .yellow)
            offerOneOffNPCSale(item: ItemCatalog.shortsword(), price: 10, npc: npc, room: room)
        case .oldPriestess:
            printWrapped("\"A holy symbol, blessed and spare. Take it, for a small offering.\"", indent: 2, color: .yellow)
            offerOneOffNPCSale(item: ItemCatalog.holySymbol(), price: 5, npc: npc, room: room)
        case .mysteriousStranger:
            if Int.random(in: 1...100) <= 50 {
                printWrapped("\"...Perhaps. I have something. You didn't see where it came from.\"", indent: 2, color: .yellow)
                offerOneOffNPCSale(item: ItemCatalog.thievesTools(), price: 25, npc: npc, room: room)
            } else {
                printWrapped("\"Trade requires trust. I have neither the goods nor the inclination.\"", indent: 2, color: .dimGreen)
                waitForContinue()
                inputHandler = { [weak self] _ in self?.talkToNPC() }
            }
        default:
            let declines = [
                "\"I'm no merchant, just a traveller like you.\"",
                "\"I've nothing worth your coin, I'm afraid.\"",
                "\"Trade? Wrong person to ask, friend.\"",
            ]
            printWrapped(declines.randomElement()!, indent: 2, color: .dimGreen)
            waitForContinue()
            inputHandler = { [weak self] _ in self?.talkToNPC() }
        }
    }

    private func offerOneOffNPCSale(item: Item, price: Int, npc: DungeonNPC, room: Room) {
        print("")
        print("  \(item.name) — \(price)gp", color: .yellow)
        printWrapped("  \(item.description)", indent: 2, color: .dimGreen)
        showMenu(["Buy it", "< No thanks"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            guard choice == 1 else {
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.talkToNPC() }
                return
            }
            self.pickCharacter(title: "Who buys the \(item.name)?", onBack: { [weak self] in self?.talkToNPC() }, showGold: true) { [weak self] character in
                guard let self = self else { return }
                guard character.gold >= price else {
                    self.print("")
                    self.print("  Not enough gold.", color: .red)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.talkToNPC() }
                    return
                }
                guard character.canCarry(item) else {
                    self.print("")
                    self.print("  Too much to carry — lighten your load first.", color: .red)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.talkToNPC() }
                    return
                }
                character.gold -= price
                _ = character.addItem(item.newInstance())
                self.print("")
                self.print("  Purchased \(item.name) for \(price) gold.", color: .brightGreen)
                self.logMultiplayerAction("\(character.name) bought \(item.name) from \(npc.type.rawValue)")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.talkToNPC() }
            }
        }
    }

    private func requestNPCHealing() {
        guard let room = dungeon?.currentRoom, let npc = room.npc else { return }

        let isFree = npc.type == .oldPriestess
        let cost = isFree ? 0 : 15

        pickCharacter(title: "Who receives healing?") { [weak self] character in
            guard let self = self else { return }

            self.clearTerminal()
            if let dungeon = self.dungeon {
                self.printExplorationMap()
                self.print("")
            }

            if character.currentHP >= character.maxHP {
                self.printWrapped("\"\(character.name) is already in full health. Save my aid for when you truly need it.\"", indent: 2, color: .yellow)
            } else if !isFree && character.gold < cost {
                self.printWrapped("\"I need \(cost) gold for my services. Come back when you can afford it.\"", indent: 2, color: .yellow)
            } else {
                if !isFree { character.gold -= cost }
                let healAmount = Dice.rollDamage("2d4+2").total
                character.heal(healAmount)
                self.printWrapped("The \(npc.type.rawValue) tends to \(character.name)'s wounds.", indent: 2, color: .cyan)
                self.print("")
                self.printWrapped("\(character.name) heals \(healAmount) HP!\(isFree ? "" : " (-\(cost) gold)")", indent: 2, color: .brightGreen)
                self.logEvent("\(npc.type.rawValue) healed \(character.name) for \(healAmount) HP", category: "NPC")
            }

            self.waitForContinue()
            self.inputHandler = { [weak self] _ in
                self?.talkToNPC()
            }
        }
    }

    private func requestNPCRepair() {
        guard let room = dungeon?.currentRoom, let npc = room.npc else { return }
        let costPerWeapon = 20
        let brokenCount = party.reduce(0) { $0 + $1.inventory.filter { $0.broken }.count }
        let cost = brokenCount > 0 ? brokenCount * costPerWeapon : costPerWeapon

        pickCharacter(title: "Who pays for repairs?", showGold: true) { [weak self] character in
            guard let self = self else { return }

            self.clearTerminal()
            if let dungeon = self.dungeon {
                self.printExplorationMap()
                self.print("")
            }

            if brokenCount == 0 {
                self.printWrapped("\"Nothing of yours is broken right now — come back if a weapon shatters in battle.\"", indent: 2, color: .yellow)
            } else if character.gold < cost {
                self.printWrapped("\"Fixing \(brokenCount) broken weapon\(brokenCount == 1 ? "" : "s") costs \(cost) gold. \(character.name) hasn't got enough. Come back with coin!\"", indent: 2, color: .yellow)
            } else {
                character.gold -= cost
                var fixedNames: [String] = []
                for member in self.party {
                    for idx in member.inventory.indices where member.inventory[idx].broken {
                        member.inventory[idx].isBroken = false
                        fixedNames.append(member.inventory[idx].name)
                    }
                }
                self.printWrapped("The \(npc.type.rawValue) hammers away at your broken gear.", indent: 2, color: .cyan)
                self.print("")
                self.printWrapped("\"Good as new! Well, almost. That'll be \(cost) gold.\"", indent: 2, color: .yellow)
                self.logEvent("\(npc.type.rawValue) repaired \(fixedNames.joined(separator: ", ")) for \(character.name) (-\(cost) gold)", category: "NPC")
            }

            self.waitForContinue()
            self.inputHandler = { [weak self] _ in
                self?.talkToNPC()
            }
        }
    }

    private func learnFromNPC() {
        guard let room = dungeon?.currentRoom, var npc = room.npc else { return }

        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        npc.hasTaught = true
        room.npc = npc

        let desc = npc.type.teachingDescription
        printWrapped(desc, indent: 2, color: .brightGreen)
        logEvent("Learned from \(npc.type.rawValue): \(desc)", category: "NPC")

        waitForContinue()
        inputHandler = { [weak self] _ in
            self?.talkToNPC()
        }
    }

    private func requestNPCCurePoison() {
        guard let room = dungeon?.currentRoom, let npc = room.npc else { return }

        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        let poisoned = party.filter { $0.isPoisoned }
        if poisoned.isEmpty {
            printWrapped("\"None of your party is poisoned. Lucky you!\"", indent: 2, color: .yellow)
        } else {
            for char in poisoned {
                char.isPoisoned = false
                printWrapped("\(char.name)'s poison is cured!", indent: 2, color: .brightGreen)
            }
            printWrapped("\"The corruption is cleansed. Go carefully — not all venom can be drawn so easily.\"", indent: 2, color: .yellow)
            logEvent("\(npc.type.rawValue) cured poison for \(poisoned.count) party members", category: "NPC")
        }

        waitForContinue()
        inputHandler = { [weak self] _ in
            self?.talkToNPC()
        }
    }

    func collectTreasure() {
        guard let room = dungeon?.currentRoom, !room.treasure.isEmpty else {
            print("No treasure to collect.")
            showExplorationView()
            return
        }

        clearTerminal()

        // Show map at top
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        print("Collected treasure:", color: .brightGreen, bold: true)
        print("")

        // Separate gold from pickable items
        var totalGold = 0
        var pickableItems: [Item] = []
        var itemNames: [String] = []

        for treasureItem in room.treasure {
            itemNames.append(treasureItem.name)
            if treasureItem.type == .gold {
                totalGold += treasureItem.value
                print("  \(treasureItem.name)", color: .yellow)
            } else if treasureItem.type == .gem {
                let gemItem = Item(id: UUID(), name: treasureItem.name,
                                   description: "A precious gem worth \(treasureItem.value)gp.",
                                   type: .gem, weight: 1.0, value: treasureItem.value,
                                   weaponStats: nil, armorStats: nil, potionStats: nil)
                pickableItems.append(gemItem)
                print("  \(treasureItem.name) (\(treasureItem.value)gp)", color: .brightGreen)
            } else if treasureItem.type == .potion || treasureItem.type == .item {
                if let item = resolveItemByName(treasureItem.name) {
                    pickableItems.append(item)
                    print("  \(item.name)", color: .brightGreen)
                } else {
                    totalGold += treasureItem.value
                    print("  \(treasureItem.name) — \(treasureItem.value)gp", color: .yellow)
                }
            }
        }

        room.treasure.removeAll()

        if !itemNames.isEmpty {
            logEvent("Found treasure: \(itemNames.joined(separator: ", "))", category: "LOOT")
            logMultiplayerAction("Found treasure: \(itemNames.joined(separator: ", "))")
        }

        // Show pickup menus for gold and items
        if totalGold > 0 || !pickableItems.isEmpty {
            waitForContinue()
            inputHandler = { [weak self] _ in
                self?.showLootSequence(gold: totalGold, goldSource: "Treasure",
                                       items: pickableItems, itemSource: "Treasure") { [weak self] in
                    self?.showExplorationView()
                }
            }
        } else {
            waitForContinue()
            inputHandler = { [weak self] _ in
                self?.showExplorationView()
            }
        }
    }

    /// Attempt to loot treasure in the dark — reduced success, chance of something unwanted
    func collectTreasureInDark() {
        guard let room = dungeon?.currentRoom, !room.treasure.isEmpty else {
            showExplorationView()
            return
        }

        clearTerminal()
        print("Fumbling in the Dark...", color: .gray, bold: true)
        print("")
        print("  You grope blindly for treasure...", color: .gray)
        print("")

        var totalGold = 0
        var pickableItems: [Item] = []
        var foundAnything = false

        for treasureItem in room.treasure {
            let roll = Int.random(in: 1...100)
            if roll <= 40 {
                // 40% chance: find nothing from this item
                continue
            } else if roll <= 55 {
                // 15% chance: something unwanted
                foundAnything = true
                let mishap = Int.random(in: 1...5)
                switch mishap {
                case 1:
                    print("  You grab something slimy! It wriggles away.", color: .red)
                    logEvent("Grabbed something slimy in the dark", category: "LOOT")
                case 2:
                    let dmg = Dice.rollSum(1, d: 4)
                    let victim = party.randomElement()!
                    victim.takeDamage(dmg)
                    print("  Ouch! You cut your hand on something sharp. (\(victim.name) -\(dmg) HP)", color: .red)
                    logEvent("\(victim.name) cut hand in the dark (-\(dmg) HP)", category: "LOOT")
                case 3:
                    print("  You knock something over — it shatters loudly!", color: .red)
                    print("  Monsters nearby may have heard that...", color: .yellow)
                    logEvent("Made noise fumbling in the dark", category: "LOOT")
                case 4:
                    print("  You grab a fistful of... dust and cobwebs.", color: .gray)
                case 5:
                    print("  Something skitters across your hand. You recoil!", color: .red)
                    logEvent("Something skittered across hand in dark", category: "LOOT")
                default: break
                }
            } else {
                // 45% chance: find it (reduced from 100%)
                foundAnything = true
                if treasureItem.type == .gold {
                    // Only find some of the gold
                    let portion = Int.random(in: 40...80)
                    let found = max(1, treasureItem.value * portion / 100)
                    totalGold += found
                    if found < treasureItem.value {
                        print("  You scoop up some coins — \(found)gp (some spilled!)", color: .yellow)
                    } else {
                        print("  You find \(found)gp!", color: .yellow)
                    }
                } else if treasureItem.type == .gem {
                    let gemItem = Item(id: UUID(), name: treasureItem.name,
                                       description: "A precious gem worth \(treasureItem.value)gp.",
                                       type: .gem, weight: 1.0, value: treasureItem.value,
                                       weaponStats: nil, armorStats: nil, potionStats: nil)
                    pickableItems.append(gemItem)
                    print("  You feel something smooth — a gem!", color: .brightGreen)
                } else if treasureItem.type == .potion || treasureItem.type == .item {
                    if let item = resolveItemByName(treasureItem.name) {
                        pickableItems.append(item)
                        print("  You grab something... a \(item.name)!", color: .brightGreen)
                    }
                }
            }
        }

        room.treasure.removeAll()

        if !foundAnything {
            print("  You fumble around but find nothing useful.", color: .gray)
            logEvent("Fumbled for treasure in the dark — found nothing", category: "LOOT")
        }

        print("")

        if totalGold > 0 || !pickableItems.isEmpty {
            waitForContinue()
            inputHandler = { [weak self] _ in
                self?.showLootSequence(gold: totalGold, goldSource: "Dark loot",
                                       items: pickableItems, itemSource: "Dark loot") { [weak self] in
                    self?.showExplorationView()
                }
            }
        } else {
            waitForContinue()
            inputHandler = { [weak self] _ in
                self?.showExplorationView()
            }
        }
    }

    // MARK: - Item Pickup

    /// Show a menu for a found item — pick up, equip, use, or leave it
    /// Tools wear out: each use counts down (a fresh one's count is rolled
    /// from `freshUses`), and now and then one gives out early. Returns a
    /// line to print when that use was its last.
    @discardableResult
    func wearTool(_ name: String, owner: Character, freshUses: ClosedRange<Int>, breakChance: Int) -> String? {
        guard let i = owner.inventory.firstIndex(where: { $0.name == name }) else { return nil }
        let plural = name.hasSuffix("Tools")
        let left = (owner.inventory[i].usesLeft ?? Int.random(in: freshUses)) - 1
        if left <= 0 {
            owner.inventory.remove(at: i)
            return "\(owner.name)'s \(name) \(plural ? "are" : "is") worn out — that was the last use."
        }
        if Int.random(in: 1...100) <= breakChance {
            owner.inventory.remove(at: i)
            return "\(owner.name)'s \(name) \(plural ? "snap" : "cracks in two") — no more uses, sadly."
        }
        owner.inventory[i].usesLeft = left
        if left <= 3 {
            return "\(owner.name)'s \(name) \(plural ? "are" : "is") getting worn (\(left) use\(left == 1 ? "" : "s") left) — an ironmonger or smith can mend \(plural ? "them" : "it")."
        }
        return nil
    }

    /// Trivial decisions don't hold up play: the first adventurer who can
    /// carry a find simply takes it. If nobody has room, a companion under
    /// the game's control makes room by using up a cheap potion or snack
    /// (players' own adventurers are never made to). Only if that still
    /// fails — or it's a party of one — does the pickup menu ask.
    private func autoAssignLoot(_ item: Item, source: String, narrative: String?, onDone: @escaping () -> Void) -> Bool {
        let eligible = combatLootEligible ?? party
        guard eligible.count > 1 else { return false }
        // Important finds are the player's call: gear to equip, or anything
        // valuable, always gets the "who takes it?" screen.
        let important = item.type == .weapon || item.type == .armor || item.type == .shield || item.value >= 50
        guard !important else { return false }
        // Trivial things go to a companion the game controls if one has room —
        // a player's own adventurer only if none can.
        var taker = eligible.first { $0.isComputerControlled && $0.canCarry(item) } ?? eligible.first { $0.canCarry(item) }
        var madeRoom: String?
        if taker == nil {
            for char in eligible where char.isComputerControlled {
                let usable = char.inventory.filter { $0.type == .potion && ($0.potionStats?.healAmount != nil || ItemCatalog.foodKind(for: $0) != nil) }
                guard let snack = usable.min(by: { $0.value < $1.value }) else { continue }
                char.removeItem(snack)
                if let heal = snack.potionStats?.healAmount { char.heal(max(1, Dice.rollDamage(heal).total)) }
                madeRoom = "\(char.name) \(ItemCatalog.consumeVerb(for: snack)) the \(snack.name) to make room."
                if char.canCarry(item) { taker = char; break }
            }
        }
        guard let who = taker else { return false }
        _ = who.addItem(item)
        clearTerminal()
        if dungeon != nil { printExplorationMap(); print("") }
        if let narrative = narrative {
            for line in narrative.components(separatedBy: "\n") { printWrapped(line, indent: 2, color: .cyan) }
            print("")
        }
        printSubtitle("Found: \(item.name)")
        print("  \(source)", color: .dimGreen)
        if let note = madeRoom { printWrapped(note, indent: 2, color: .dimGreen) }
        print("  \(who.name) picks it up.", color: .brightGreen)
        logEvent("\(who.name) picked up \(item.name)", category: "LOOT")
        pendingTimeoutKind = .loot; waitForContinueWithTimeout(multiplier: 0.8) { onDone() }
        return true
    }

    private func showItemPickupMenu(item: Item, source: String, narrative: String? = nil, onDone: @escaping () -> Void) {
        if autoAssignLoot(item, source: source, narrative: narrative, onDone: onDone) { return }
        clearTerminal()

        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        if let narrative = narrative {
            for line in narrative.components(separatedBy: "\n") {
                printWrapped(line, indent: 2, color: .cyan)
            }
            print("")
        }

        printSubtitle("Found: \(item.name)")
        print("  \(source)", color: .dimGreen)
        print("")
        print("  \(item.description)", color: .cyan)
        if let ws = item.weaponStats {
            print("  Damage: \(ws.damage) \(ws.damageType)", color: .dimGreen)
        }
        if let as_ = item.armorStats {
            print("  AC: \(as_.baseAC)", color: .dimGreen)
        }
        if let ps = item.potionStats {
            print("  Effect: \(ps.effect)", color: .dimGreen)
        }
        print("  Weight: \(formatWeight(item.weight))  Value: \(item.value)gp", color: .dimGreen)
        print("")

        if party.count > 1 {
            print("Who should pick up the \(item.name)?", color: .cyan)
        } else {
            print("What do you want to do with the \(item.name)?", color: .cyan)
        }
        print("")

        // Use combat-eligible characters if set, otherwise full party
        let eligible = combatLootEligible ?? party

        var options: [String] = []
        var actions: [() -> Void] = []

        // Pick up options — one per character for multi-party, or just "Pick Up"
        if eligible.count > 1 {
            for char in eligible {
                let canCarry = char.canCarry(item)
                let tag = canCarry ? "" : (char.isInventoryFull ? " [full]" : " [heavy]")
                options.append("Give to \(shortName(for: char))\(tag)")
                actions.append { [weak self] in
                    guard let self = self else { return }
                    if canCarry {
                        _ = char.addItem(item)
                        self.print("  \(char.name) takes the \(item.name).", color: .brightGreen)
                        self.logEvent("\(char.name) picked up \(item.name)", category: "LOOT")
                        self.waitForContinueWithTimeout { onDone() }
                    } else {
                        if char.isInventoryFull {
                            self.print("  \(char.name)'s bag is full! (\(self.formatWeightPair(char.currentWeight, char.carryCapacity)))", color: .yellow)
                        } else {
                            self.print("  \(char.name) can't carry any more!", color: .yellow)
                        }
                        self.print("  Make room or choose someone else.", color: .dimGreen)
                        self.print("")
                        self.showMenu(["Check Pack", "Choose Again", "Leave It"])
                        self.menuHandler = { [weak self] choice in
                            guard let self = self else { return }
                            if choice == 1 {
                                self.showInventoryFor(char, onBack: { [weak self] in
                                    self?.showItemPickupMenu(item: item, source: source, narrative: nil, onDone: onDone)
                                })
                            } else if choice == 2 {
                                self.showItemPickupMenu(item: item, source: source, narrative: nil, onDone: onDone)
                            } else {
                                // Drop on floor
                                if let room = self.dungeon?.currentRoom {
                                    room.droppedItems.append(item)
                                    self.print("  Left \(item.name) on the ground.", color: .dimGreen)
                                }
                                self.waitForContinueWithTimeout { onDone() }
                            }
                        }
                    }
                }
            }
        } else if let char = eligible.first ?? party.first {
            let canCarry = char.canCarry(item)
            let tag = canCarry ? "" : (char.isInventoryFull ? " [full]" : " [heavy]")
            options.append("Pick Up\(tag)")
            actions.append { [weak self] in
                guard let self = self else { return }
                if canCarry {
                    _ = char.addItem(item)
                    self.print("  \(char.name) takes the \(item.name).", color: .brightGreen)
                    self.logEvent("\(char.name) picked up \(item.name)", category: "LOOT")
                    self.pendingTimeoutKind = .loot; self.waitForContinueWithTimeout(multiplier: 0.8) { onDone() }
                } else {
                    if char.isInventoryFull {
                        self.print("  Bag is full! (\(self.formatWeightPair(char.currentWeight, char.carryCapacity)))", color: .yellow)
                    } else {
                        self.print("  Too heavy to carry!", color: .yellow)
                    }
                    self.print("  Make room or leave it.", color: .dimGreen)
                    self.print("")
                    self.showMenu(["Check Pack", "Try Again", "Leave It"])
                    self.menuHandler = { [weak self] choice in
                        guard let self = self else { return }
                        if choice == 1 {
                            self.showInventoryFor(char, onBack: { [weak self] in
                                self?.showItemPickupMenu(item: item, source: source, narrative: nil, onDone: onDone)
                            })
                        } else if choice == 2 {
                            self.showItemPickupMenu(item: item, source: source, narrative: nil, onDone: onDone)
                        } else {
                            if let room = self.dungeon?.currentRoom {
                                room.droppedItems.append(item)
                                self.print("  Left \(item.name) on the ground.", color: .dimGreen)
                            }
                            self.waitForContinueWithTimeout { onDone() }
                        }
                    }
                }
            }
        }

        // Equip option for weapon/armor/shield
        if item.type == .weapon || item.type == .armor || item.type == .shield {
            let label = item.type == .weapon ? "Equip" : (item.type == .shield ? "Equip Shield" : "Equip Armour")
            options.append(label)
            actions.append { [weak self] in
                guard let self = self else { return }
                let doEquip = { (char: Character) in
                    switch item.type {
                    case .weapon: char.equipWeapon(item)
                    case .armor: char.equipArmor(item)
                    case .shield: char.equipShield(item)
                    default: break
                    }
                    self.print("  \(char.name) equips themselves with the \(item.name)!", color: .brightGreen)
                    self.logEvent("\(char.name) equipped \(item.name)", category: "LOOT")
                    self.waitForContinueWithTimeout { onDone() }
                }
                let equipEligible = self.combatLootEligible ?? self.party
                if equipEligible.count > 1 {
                    self.pickCharacter(title: "Who equips it?", from: equipEligible) { char in doEquip(char) }
                } else if let char = equipEligible.first {
                    doEquip(char)
                }
            }
        }

        // Use option for potions (and food/drink — eat it on the spot)
        let lootIsFood = ItemCatalog.foodKind(for: item) != nil
        if item.type == .potion, lootIsFood || item.potionStats?.healAmount != nil {
            let lootVerb = ItemCatalog.consumeVerb(for: item)
            options.append(lootIsFood ? (lootVerb == "eats" ? "Eat Now" : "Drink Now") : "Use Now")
            actions.append { [weak self] in
                guard let self = self else { return }
                let doUse = { (char: Character) in
                    if let food = self.consumeFood(item, by: char) {
                        for (line, color) in food.lines { self.print("  \(line)", color: color) }
                        self.logEvent(food.summary, category: "LOOT")
                    } else if let healStr = item.potionStats?.healAmount {
                        let roll = Dice.rollDamage(healStr)
                        let amount = max(1, roll.total)
                        char.heal(amount)
                        self.print("  \(char.name) drinks the \(item.name)!", color: .brightGreen)
                        self.print("  Restored \(amount) HP! (\(char.currentHP)/\(char.maxHP))", color: .brightGreen)
                        self.logEvent("\(char.name) used \(item.name) — healed \(amount) HP", category: "LOOT")
                    }
                    self.waitForContinueWithTimeout { onDone() }
                }
                let useEligible = self.combatLootEligible ?? self.party
                if useEligible.count > 1 {
                    self.pickCharacter(title: "Who \(lootVerb) it?", from: useEligible) { char in doUse(char) }
                } else if let char = useEligible.first {
                    doUse(char)
                }
            }
        }

        // "Leave It" is now the 3-bar Back (and the corner ✕) — its old
        // button slot opens a pack instead, to make room before choosing.
        let leaveIt: () -> Void = { [weak self] in
            if let room = self?.dungeon?.currentRoom {
                room.droppedItems.append(item)
            }
            self?.print("  You leave the \(item.name) behind.", color: .dimGreen)
            self?.waitForContinueWithTimeout { onDone() }
        }
        let reshow: () -> Void = { [weak self] in
            self?.showItemPickupMenu(item: item, source: source, narrative: nil, onDone: onDone)
        }
        options.append(eligible.count > 1 ? "Check Packs" : "Check Pack")
        actions.append { [weak self] in
            guard let self = self else { return }
            if eligible.count > 1 {
                self.pickCharacter(title: "Whose pack?", from: eligible, onBack: reshow) { char in
                    self.showInventoryFor(char, onBack: reshow)
                }
            } else if let char = eligible.first ?? self.party.first {
                self.showInventoryFor(char, onBack: reshow)
            }
        }

        var menuOpts = options.map { MenuOption($0) }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Leave", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)
        closeHandler = leaveIt
        menuHandler = { [weak self] choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            } else if choice == actions.count + 1 {
                self?.showInlineHelp {
                    self?.printTitle("Picking Up — Help")
                    self?.print("")
                    self?.printWrapped("Choose who carries the \(item.name). [full] means that adventurer's pack has no free slots; [heavy] means it would take them over their carry weight.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.printWrapped("Check Pack lets you look inside a pack and drop or use things to make room, then brings you straight back here.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.printWrapped("< Leave leaves it where it lies — you can come back for it later.", indent: 2, color: .dimGreen)
                    self?.print("")
                }
            } else if choice == actions.count + 2 {
                leaveIt()
            }
        }
    }

    /// Process multiple items one at a time
    private func showItemPickupSequence(items: [Item], source: String, onDone: @escaping () -> Void) {
        guard !items.isEmpty else {
            onDone()
            return
        }
        var remaining = items
        let current = remaining.removeFirst()
        showItemPickupMenu(item: current, source: source) { [weak self] in
            self?.showItemPickupSequence(items: remaining, source: source, onDone: onDone)
        }
    }

    /// Show a menu for found gold — pick up or leave it
    private func showGoldPickupMenu(gold: Int, source: String, narrative: String? = nil, onDone: @escaping () -> Void) {
        clearTerminal()

        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        if let narrative = narrative {
            for line in narrative.components(separatedBy: "\n") {
                printWrapped(line, indent: 2, color: .cyan)
            }
            print("")
        }

        printSubtitle("Found: \(gold) Gold Pieces")
        print("  \(source)", color: .dimGreen)
        print("")

        // Use combat-eligible characters if set, otherwise full party
        let eligible = combatLootEligible ?? party

        // A quest that just completed gets its own big celebration screen
        // once showExplorationView() runs checkAndShowSideQuestCompletion()
        // — this is only the "getting closer" nudge for a collectGold quest
        // still in progress.
        let announceGoldQuestProgress: () -> Void = { [weak self] in
            guard let self = self, let quest = self.allQuests.first(where: { $0.type == .collectGold }) else { return }
            let totalGold = self.party.reduce(0) { $0 + $1.gold }
            let done = min(quest.target, totalGold - quest.startPartyGold)
            guard done < quest.target else { return }
            self.print("  ✦ Quest progress: \(done)/\(quest.target) gold gathered", color: .cyan, bold: true)
        }

        var options: [String] = []
        var actions: [() -> Void] = []

        if eligible.count > 1 {
            // Split equally
            let goldEach = gold / eligible.count
            let remainder = gold % eligible.count
            // Fewer coins than people (goldEach == 0) still says a real
            // minimum of 1 each for however many actually get one, rather
            // than the misleading "0gp each" that plain integer division
            // gives — 3 gold split 4 ways is "1gp each, for 3 of you", not
            // "0gp each, +3 extra".
            let buttonLabel = goldEach == 0
                ? "Split (1gp each, for \(remainder) of \(eligible.count))"
                : "Split (\(goldEach)gp each)"
            options.append(buttonLabel)
            actions.append { [weak self] in
                guard let self = self else { return }
                // Distribute remainder randomly one coin at a time
                var indices = Array(0..<eligible.count)
                indices.shuffle()
                for (i, char) in eligible.enumerated() {
                    let bonus = indices.firstIndex(of: i)! < remainder ? 1 : 0
                    char.gold += goldEach + bonus
                }
                if goldEach == 0 {
                    self.print("  Gold split — \(remainder) of \(eligible.count) get 1gp each (not quite enough to go around).", color: .yellow)
                } else if remainder > 0 {
                    self.print("  Gold split (\(goldEach)gp each, +\(remainder) extra spread around).", color: .yellow)
                } else {
                    self.print("  Gold split among the party (\(goldEach)gp each).", color: .yellow)
                }
                self.logEvent("Split \(gold) gold equally from \(source.lowercased())", category: "LOOT")
                self.logMultiplayerAction("Found \(gold) gold (\(source.lowercased()))")
                announceGoldQuestProgress()
                self.waitForContinueWithTimeout { onDone() }
            }

            // Give all to one character
            for char in eligible {
                options.append("\(shortName(for: char)) +\(gold)gp")
                actions.append { [weak self] in
                    char.gold += gold
                    self?.print("  \(char.name) takes all \(gold) gold.", color: .yellow)
                    self?.logEvent("\(char.name) took \(gold) gold from \(source.lowercased())", category: "LOOT")
                    announceGoldQuestProgress()
                    self?.waitForContinueWithTimeout { onDone() }
                }
            }
        } else {
            // Solo — just pick up
            let char = eligible.first ?? party.first
            options.append("Take +\(gold)gp")
            actions.append { [weak self] in
                char?.gold += gold
                self?.print("  \(char?.name ?? "You") pocket\(char == nil ? "" : "s") \(gold) gold pieces.", color: .yellow)
                self?.logEvent("Picked up \(gold) gold from \(source.lowercased())", category: "LOOT")
                announceGoldQuestProgress()
                self?.waitForContinueWithTimeout { onDone() }
            }
        }

        // Leave it
        options.append("Leave It")
        actions.append { [weak self] in
            self?.print("  You leave \(gold) gold behind.", color: .dimGreen)
            self?.logEvent("Left \(gold) gold behind", category: "LOOT")
            self?.waitForContinueWithTimeout { onDone() }
        }

        showMenu(options)
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

    /// Process a mixed loot pile — gold first, then items one at a time
    private func showLootSequence(gold: Int, goldSource: String, items: [Item], itemSource: String, onDone: @escaping () -> Void) {
        if gold > 0 {
            showGoldPickupMenu(gold: gold, source: goldSource) { [weak self] in
                if !items.isEmpty {
                    self?.showItemPickupSequence(items: items, source: itemSource, onDone: onDone)
                } else {
                    onDone()
                }
            }
        } else if !items.isEmpty {
            showItemPickupSequence(items: items, source: itemSource, onDone: onDone)
        } else {
            onDone()
        }
    }

    // MARK: - Inventory

    /// - helpAction: when provided, replaces the single `cancelLabel`
    ///   button with the standard compact "?"/"< Back" pair (auto-detected
    ///   as compact nav by showMenu) instead of a custom-worded cancel
    ///   button — for callers that want the ordinary 3-bar nav convention
    ///   rather than a one-off label like "Don't Enter". Existing callers
    ///   that don't pass this keep their current cancelLabel behaviour.
    func pickCharacter(title: String, cancelLabel: String = "Done", from candidates: [Character]? = nil, onBack: (() -> Void)? = nil, showGold: Bool = false, helpAction: (() -> Void)? = nil, action: @escaping (Character) -> Void) {
        let chars = candidates ?? party
        if chars.count == 1 {
            action(chars[0])
            return
        }

        clearTerminal()
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }
        printSubtitle(title)

        var options: [String] = []
        for char in chars {
            // Gold, not HP, is what matters when the question is "who pays"
            // (shop, gym membership...) — HP is the right stat everywhere
            // else (combat targeting, healing...), so this only swaps for
            // callers that explicitly ask for it.
            let stat = showGold ? "\(char.gold)gp" : "\(char.currentHP)/\(char.maxHP)HP"
            options.append("\(shortName(for: char)) \(stat)")
        }
        let usesHelpNav = helpAction != nil
        if usesHelpNav {
            options.append("?")
            options.append("< Back")
        } else {
            options.append(cancelLabel)
        }

        let cancelAction: () -> Void = { [weak self] in
            if let onBack = onBack { onBack() } else { self?.showExplorationView() }
        }
        showMenu(options)
        closeHandler = cancelAction
        menuHandler = { choice in
            if usesHelpNav {
                if choice == chars.count + 1 {
                    helpAction?()
                    return
                }
                if choice == chars.count + 2 {
                    cancelAction()
                    return
                }
            } else if choice == options.count {
                cancelAction()
                return
            }
            guard choice > 0 && choice <= chars.count else { return }
            action(chars[choice - 1])
        }
    }

    func showInventory() {
        // Default to a random human-controlled character
        let humans = party.filter { !$0.isComputerControlled }
        let defaultChar = humans.randomElement() ?? party.first!
        let back: () -> Void = { [weak self] in self?.showExplorationView() }
        showInventoryFor(defaultChar, onBack: back)
    }

    private func showInventoryFor(_ character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        // Pack opening animation — only on first open per room
        let currentRoomId = dungeon?.currentRoom?.id
        if let roomId = currentRoomId, roomId != lastInventoryRoomId && !fromDM {
            lastInventoryRoomId = roomId
            showPackAnimation {
                self.renderInventory(character, onBack: onBack, fromDM: fromDM)
            }
            return
        }
        renderInventory(character, onBack: onBack, fromDM: fromDM)
    }

    private func showPackAnimation(completion: @escaping () -> Void) {
        guard !reduceAnimations else { completion(); return }
        clearTerminal()
        printExplorationMap()
        print("")

        let frames: [([String], TerminalColor)] = [
            (["    ╔════╗", "    ║▓▓▓▓║", "    ║▓▓▓▓║", "    ╚════╝"], .dimGreen),
            (["    ╔╗  ╔╗", "    ║ ╲╱ ║", "    ║    ║", "    ╚════╝"], .yellow),
            (["    ╔    ╗", "    ║ ⚔⚗ ║", "    ║ $$ ║", "    ╚════╝"], .orange),
        ]

        let artStart = terminalLines.count
        let firstFrame = frames[0].0
        printLines(firstFrame, color: frames[0].1)
        print("")

        var frameIndex = 1
        Timer.scheduledTimer(withTimeInterval: 0.3, repeats: true) { [weak self] timer in
            guard let self = self else { timer.invalidate(); return }
            DispatchQueue.main.async {
                if frameIndex < frames.count {
                    let (lines, color) = frames[frameIndex]
                    for (j, line) in lines.enumerated() {
                        let idx = artStart + j
                        if idx < self.terminalLines.count {
                            self.terminalLines[idx] = TerminalLine(line, color: color)
                        }
                    }
                    frameIndex += 1
                } else {
                    timer.invalidate()
                    completion()
                }
            }
        }
    }

    private func renderInventory(_ character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {

        clearTerminal()

        if let _ = dungeon {
            printExplorationMap()
            print("")
        }

        let playerCharId = isMultiplayer ? localCharacterId : party.first(where: { !$0.isComputerControlled })?.id
        let isOwnInventory = character.id == playerCharId
        let charPartyIndex = party.firstIndex(where: { $0.id == character.id })
        let isRemoteChar = charPartyIndex != nil && pendingRemoteSlots.contains(charPartyIndex!)
        let invName = character.isComputerControlled && !isRemoteChar && !character.name.hasPrefix("R.") ? "R. \(character.name)" : character.name
        printTitle("Inventory — \(invName)", color: .orange)

        print("  Carry Weight: \(formatWeightPair(character.currentWeight, character.carryCapacity))", color: character.isEncumbered ? .red : .cyan)
        print("  Gold: \(character.gold)", color: .yellow)
        if let familiarName = character.familiarName, let familiarType = character.familiarType {
            print("  Familiar: \(familiarName) the \(familiarType)", color: .magenta)
        }
        // Torch status — show who holds the lit torch
        if torchLit, let holderId = torchHolderId {
            let holderName = party.first(where: { $0.id == holderId }).map { shortName(for: $0) } ?? "?"
            let activeTorch = activeTorchId.flatMap { tid in party.flatMap { $0.inventory }.first(where: { $0.id == tid }) }
            if character.id == holderId {
                // This character holds the torch
                if let desc = activeTorch?.torchLifeDescription {
                    print("  Torch: holding (lit, \(desc) left)", color: .orange)
                } else {
                    print("  Torch: holding (lit)", color: .orange)
                }
            } else {
                // Someone else has it
                print("  Torch: held by \(holderName)", color: .dimGreen)
            }
        } else {
            let charTorches = character.inventory.filter { $0.isTorch }
            if !charTorches.isEmpty {
                print("  Torch: unlit (\(charTorches.count) in bag)", color: .dimGreen)
            } else {
                let totalTorches = party.flatMap { $0.inventory }.filter { $0.isTorch }.count
                if totalTorches > 0 {
                    print("  Torch: none (party has \(totalTorches))", color: .dimGreen)
                } else {
                    print("  Torch: none", color: .dimGreen)
                }
            }
        }
        print("")

        print("  EQUIPPED:", color: .cyan, bold: true)
        print("    Weapon: \(character.equippedWeapon?.name ?? "(none)")", color: .brightGreen)
        print("    Armour:  \(character.equippedArmor?.name ?? "(none)")", color: .brightGreen)
        print("    Shield: \(character.equippedShield?.name ?? "(none)")", color: .brightGreen)
        print("")

        let slotColor: TerminalColor = character.isInventoryFull ? .red : .cyan
        print("  BAG (\(formatWeightPair(character.currentWeight, character.carryCapacity))):", color: slotColor, bold: true)
        if character.inventory.isEmpty {
            print("    (empty)", color: .dimGreen)
        } else {
            for item in character.inventory {
                let tag: String
                switch item.type {
                case .weapon: tag = "[W]"
                case .armor: tag = "[A]"
                case .shield: tag = "[S]"
                case .potion: tag = "[P]"
                case .scroll: tag = "[?]"
                case .gem: tag = "[$]"
                case .misc: tag = "[.]"
                }
                let torchInfo: String
                if item.isTorch, let desc = item.torchLifeDescription {
                    let isActive = item.id == activeTorchId && torchLit
                    torchInfo = isActive ? " (\(desc) left, lit)" : " (\(desc) left)"
                } else {
                    torchInfo = ""
                }
                print("    \(tag) \(item.name)\(torchInfo) — \(formatWeight(item.weight)), \(item.value)gp", color: .green)
            }
        }
        print("")

        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        // Row 1: Equipment + Open Pack
        menuOpts.append(MenuOption("Equipment"))
        actions.append { [weak self] in self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM) }
        menuOpts.append(MenuOption("Open Pack", isDisabled: character.inventory.isEmpty))
        actions.append { [weak self] in self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM) }

        // Other party member packs (amber)
        if party.count > 1 {
            for (otherIdx, other) in party.enumerated() where other.id != character.id {
                let otherIsRemote = pendingRemoteSlots.contains(otherIdx)
                let prefix = (other.isComputerControlled && !otherIsRemote && !other.name.hasPrefix("R.")) ? "R." : ""
                menuOpts.append(MenuOption("\(prefix)\(shortName(for: other))'s Pack", tint: .amber))
                actions.append { [weak self] in
                    self?.showInventoryFor(other, onBack: onBack, fromDM: fromDM)
                }
            }
        }

        // Help
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showInventoryHelp(character: character, onBack: onBack, fromDM: fromDM) }

        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        let backTarget = onBack
        actions.append { [weak self] in
            guard let self = self else { return }
            self.closeHandler = nil
            if let backTarget = backTarget {
                backTarget()
            } else {
                self.showExplorationView()
            }
        }

        // Cluster buttons by colour: normal first, then amber, then cyan
        let paired = zip(menuOpts, actions).map { ($0, $1) }
        let tintOrder: [MenuTint] = [.normal, .amber, .cyan, .danger, .navigation]
        let sorted = paired.sorted { a, b in
            let ai = tintOrder.firstIndex(of: a.0.tint) ?? 0
            let bi = tintOrder.firstIndex(of: b.0.tint) ?? 0
            return ai < bi
        }
        let sortedOpts = sorted.map { $0.0 }
        let sortedActions = sorted.map { $0.1 }

        showMenuOptions(sortedOpts)
        let backAction = onBack ?? { [weak self] in self?.showExplorationView() }
        closeHandler = { [weak self] in
            self?.closeHandler = nil
            backAction()
        }
        menuHandler = { choice in
            if choice > 0 && choice <= sortedActions.count {
                sortedActions[choice - 1]()
            }
        }
    }

    private func showInventoryHelp(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        showInlineHelp {
            self.printTitle("Inventory — Help")
            self.print("")

            self.print("  OVERVIEW", color: .cyan, bold: true)
            self.printWrapped("Your inventory shows everything you're carrying: equipped gear, items in your pack, and your gold. Each character carries their own equipment.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  EQUIPPED GEAR", color: .cyan, bold: true)
            self.printWrapped("Weapon, Armour, and Shield slots show what you have equipped. Tap Equipment to change what's equipped from your pack. Equipping a new item swaps the old one back into your bag.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  BAG (PACK)", color: .cyan, bold: true)
            self.printWrapped("Your bag holds about 40 lb — roughly ten medium things like axes — a little more for the strong and hardy, a little less for small folk; worn weapon, armour and shield don't count. Item tags show type: [W] weapon, [A] armour, [S] shield, [P] potion, [?] scroll, [$] gem, [.] misc. Weight and gold value are shown for each item.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  OPEN PACK", color: .cyan, bold: true)
            self.printWrapped("Opens your bag to use potions, drop items, give items to party members, or inspect individual items in detail.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  CARRY WEIGHT", color: .cyan, bold: true)
            self.printWrapped("Each character can carry a limited weight based on their Strength score. If encumbered (over limit), movement and combat may be affected. Drop or give away items to lighten your load.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  PARTY PACKS", color: .cyan, bold: true)
            self.printWrapped("Tap a companion's pack to view their inventory. You can give items between party members using the Give option in Open Pack.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  TORCHES", color: .cyan, bold: true)
            self.printWrapped("Torches are vital for exploring. The inventory shows who holds the lit torch and how much burn time remains. Without a torch, searching and scavenging are much harder.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    private func showEquipMenu(character: Character, type: ItemType, label: String, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        let items = character.inventory.filter { $0.type == type && !$0.broken }
        let brokenItems = character.inventory.filter { $0.type == type && $0.broken }

        clearTerminal()
        printSubtitle("Equip \(label)")

        if !brokenItems.isEmpty {
            printWrapped("Broken, can't equip: \(brokenItems.map { $0.name }.joined(separator: ", ")) — find a smith to repair.", indent: 2, color: .red)
            print("")
        }

        var options: [String] = []
        for item in items {
            var desc = "\(item.name)"
            if let ws = item.weaponStats {
                desc += " (\(ws.damage) \(ws.damageType))"
            }
            if let as_ = item.armorStats {
                desc += " (AC \(as_.baseAC))"
            }
            options.append(desc)
        }

        showPaginatedMenuOptions(options, pinned: ["< Done"], handler: { [weak self] idx in
            guard idx >= 0 && idx < items.count else { return }
            let item = items[idx]

            switch type {
            case .weapon: character.equipWeapon(item)
            case .armor: character.equipArmor(item)
            case .shield: character.equipShield(item)
            default: break
            }
            self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM)
        }, pinnedHandler: { [weak self] _ in
            self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM)
        })
    }

    private func showUsePotionMenu(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        let potions = character.inventory.filter { $0.type == .potion || $0.name == "Whetstone" }

        clearTerminal()
        printSubtitle("Use Item")
        print("  \(character.name)'s usable items:", color: .cyan)
        print("")

        // Show party HP so player knows who needs healing
        let hasHealingPotion = potions.contains { $0.potionStats?.healAmount != nil }
        if hasHealingPotion && party.count > 1 {
            for char in party where char.isConscious {
                let hpPct = char.maxHP > 0 ? Double(char.currentHP) / Double(char.maxHP) : 1.0
                let color: TerminalColor = hpPct <= 0.33 ? .red : hpPct <= 0.66 ? .yellow : .dimGreen
                print("  \(shortName(for: char)): \(char.currentHP)/\(char.maxHP) HP", color: color)
            }
            print("")
        }

        var options: [String] = []
        for potion in potions {
            // Short label for button — just the name
            options.append(potion.name)
        }

        // Show item details above buttons
        for potion in potions {
            if let effect = potion.potionStats?.effect {
                print("  \(potion.name): \(effect)", color: .dimGreen)
            } else if potion.name == "Whetstone" {
                print("  Whetstone: sharpen your equipped weapon (+1 to hit/damage for 3 attacks)", color: .dimGreen)
            }
        }
        print("")

        closeHandler = { [weak self] in self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM) }

        showPaginatedMenu(options) { [weak self] idx in
            guard let self = self else { return }
            guard idx >= 0 && idx < potions.count else { return }
            let potion = potions[idx]

            // Whetstone sharpens the user's own equipped weapon — not consumed by
            // another party member, so it skips the potion "who drinks it?" flow.
            if potion.name == "Whetstone" {
                guard character.equippedWeapon != nil else {
                    self.print("")
                    self.print("  You have no weapon equipped to sharpen.", color: .red)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in
                        self?.showUsePotionMenu(character: character, onBack: onBack, fromDM: fromDM)
                    }
                    return
                }
                character.weaponSharpenedUses = 3
                // A whetstone lasts 5-10 sharpenings (and now and then cracks early).
                let wornNote = self.wearTool("Whetstone", owner: character, freshUses: 5...10, breakChance: 5)
                self.print("")
                self.print("  \(character.name) sharpens \(character.equippedWeapon?.name ?? "their weapon") with the whetstone.", color: .brightGreen)
                self.print("  +1 to attack and damage rolls for the next 3 attacks.", color: .yellow)
                if let note = wornNote {
                    self.print("  \(note)", color: .dimGreen)
                } else if let left = character.inventory.first(where: { $0.name == "Whetstone" })?.usesLeft {
                    self.print("  (About \(left) more sharpening\(left == 1 ? "" : "s") left in the stone.)", color: .dimGreen)
                }
                self.logMultiplayerAction("\(character.name) sharpens their weapon")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM)
                }
                return
            }

            let applyPotion = { (target: Character) in
                character.removeItem(potion)
                let isAntidote = potion.name.lowercased().contains("antidote")

                if isAntidote {
                    self.print("")
                    if target.isPoisoned {
                        target.curePoison()
                        self.print("  \(target.name) drinks the antidote!", color: .brightGreen)
                        self.print("  Poison cured!", color: .brightGreen)
                        self.logMultiplayerAction("\(target.name) uses antidote — poison cured!")
                    } else {
                        self.print("  \(target.name) drinks the antidote.", color: .dimGreen)
                        self.print("  (Not poisoned — no effect.)", color: .dimGreen)
                    }
                } else if let food = self.consumeFood(potion, by: target) {
                    self.print("")
                    for (line, color) in food.lines { self.print("  \(line)", color: color) }
                    self.logMultiplayerAction(food.summary)
                } else if let healStr = potion.potionStats?.healAmount {
                    let roll = Dice.rollDamage(healStr)
                    let amount = max(1, roll.total)
                    target.heal(amount)

                    self.print("")
                    self.print("  \(target.name) drinks \(potion.name)!", color: .brightGreen)
                    self.print("  Restored \(amount) HP! (\(target.currentHP)/\(target.maxHP))", color: .brightGreen)
                    if target.isPoisoned {
                        target.curePoison()
                        self.print("  Poison also cured!", color: .brightGreen)
                    }
                    self.logMultiplayerAction("\(target.name) drinks \(potion.name) — restored \(amount) HP (\(target.currentHP)/\(target.maxHP))")
                } else {
                    // Flavour potion — no mechanical effect, just colour.
                    self.print("")
                    self.print("  \(target.name) drinks \(potion.name).", color: .dimGreen)
                    self.print("  \(potion.potionStats?.effect ?? "Nothing obvious happens.")", color: .dimGreen)
                    self.logMultiplayerAction("\(target.name) drinks \(potion.name)")
                }

                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM)
                }
            }

            // Ask who should drink it when there are multiple party members
            if self.party.count > 1 {
                self.pickCharacter(title: "Who \(ItemCatalog.consumeVerb(for: potion)) the \(potion.name)?", onBack: {
                    self.showUsePotionMenu(character: character, onBack: onBack, fromDM: fromDM)
                }) { target in
                    applyPotion(target)
                }
            } else {
                applyPotion(character)
            }
        }
    }

    private func showDropItemMenu(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        clearTerminal()
        printSubtitle("Drop Item")

        let items = character.inventory
        var options: [String] = []
        for item in items {
            options.append("\(item.name) (\(formatWeight(item.weight)))")
        }

        closeHandler = { [weak self] in self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM) }

        showPaginatedMenu(options) { [weak self] idx in
            guard let self = self else { return }
            guard idx >= 0 && idx < items.count else { return }
            let item = items[idx]

            // If multiple party members, offer to give to another character
            let others = self.party.filter { $0.id != character.id }
            if !others.isEmpty {
                self.showItemTransferMenu(item: item, from: character, others: others, onBack: onBack, fromDM: fromDM)
            } else {
                character.removeItem(item)
                if let room = self.dungeon?.currentRoom {
                    room.droppedItems.append(item)
                }
                self.print("")
                self.print("  Dropped \(item.name) in the room.", color: .yellow)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM)
                }
            }
        }
    }

    private func showItemTransferMenu(item: Item, from: Character, others: [Character], onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        clearTerminal()
        printSubtitle("Give or Drop: \(item.name)")
        print("  \(from.name) has selected \(item.name).", color: .dimGreen)
        print("")

        var options: [String] = []
        var actions: [() -> Void] = []

        for other in others {
            let canCarry = other.canCarry(item)
            let tag = canCarry ? "" : (other.isInventoryFull ? " [full]" : " [heavy]")
            options.append("Give to \(shortName(for: other))\(tag)")
            actions.append { [weak self] in
                guard let self = self else { return }
                if canCarry {
                    from.removeItem(item)
                    _ = other.addItem(item)
                    self.print("")
                    self.print("  \(from.name) gives \(item.name) to \(other.name).", color: .brightGreen)
                    self.logEvent("\(from.name) gave \(item.name) to \(other.name)", category: "ITEM")
                } else {
                    self.print("")
                    self.print("  \(other.name) can't carry any more!", color: .yellow)
                }
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.showPackMenu(character: from, onBack: onBack, fromDM: fromDM)
                }
            }
        }

        options.append("Drop on Floor")
        actions.append { [weak self] in
            guard let self = self else { return }
            from.removeItem(item)
            if let room = self.dungeon?.currentRoom {
                room.droppedItems.append(item)
            }
            self.print("")
            self.print("  Dropped \(item.name) in the room.", color: .yellow)
            self.waitForContinue()
            self.inputHandler = { [weak self] _ in
                self?.showPackMenu(character: from, onBack: onBack, fromDM: fromDM)
            }
        }

        showMenu(options)
        closeHandler = { [weak self] in self?.showDropItemMenu(character: from, onBack: onBack, fromDM: fromDM) }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

    private func showPackCharacterPicker(onBack: @escaping () -> Void) {
        let consciousParty = party.filter { $0.isConscious && !$0.inventory.isEmpty }
        guard !consciousParty.isEmpty else { onBack(); return }

        clearTerminal()
        printSubtitle("Whose Pack?")
        print("")

        var options: [String] = []
        for char in consciousParty {
            let count = char.inventory.count
            options.append("\(shortName(for: char))  (\(count) item\(count == 1 ? "" : "s"))")
        }

        showMenu(options)
        closeHandler = onBack
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice > 0 && choice <= consciousParty.count {
                let char = consciousParty[choice - 1]
                self.showPackMenu(character: char, onBack: onBack)
            }
        }
    }

    /// Pack sub-menu: Use Item, Give Item, Drop Item
    func showPackMenu(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        clearTerminal()
        printSubtitle("Pack — \(shortName(for: character))")

        // List pack contents
        if character.inventory.isEmpty {
            print("  (empty)", color: .dimGreen)
        } else {
            for item in character.inventory {
                let tag: String
                switch item.type {
                case .weapon: tag = "[W]"
                case .armor: tag = "[A]"
                case .shield: tag = "[S]"
                case .potion: tag = "[P]"
                case .scroll: tag = "[?]"
                case .gem: tag = "[$]"
                case .misc: tag = "[.]"
                }
                let torchInfo: String
                if item.isTorch, let desc = item.torchLifeDescription {
                    let isActive = item.id == activeTorchId && torchLit
                    torchInfo = isActive ? " (lit, \(desc))" : " (\(desc))"
                } else {
                    torchInfo = ""
                }
                let brokenInfo = item.broken ? " (broken)" : ""
                print("  \(tag) \(item.name)\(torchInfo)\(brokenInfo)", color: item.broken ? .red : .green)
            }
        }
        print("")
        printWrapped("Items are things in your backpack — potions, torches, rope, etc. Equipment (weapons, armour, shields) is what you wear or wield.", indent: 2, color: .dimGreen)
        if character.inventory.contains(where: { $0.broken }) {
            printWrapped("Broken gear can't be equipped — a smith can repair it, or drop it and equip something else.", indent: 2, color: .red)
        }
        print("")

        let usableItems = character.inventory.filter { $0.type == .potion || $0.name == "Whetstone" }
        let hasOthers = party.count > 1

        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        menuOpts.append(MenuOption("Use Item", isDisabled: usableItems.isEmpty))
        actions.append { [weak self] in self?.showUsePotionMenu(character: character, onBack: onBack, fromDM: fromDM) }

        menuOpts.append(MenuOption("Drop Item", isDisabled: character.inventory.isEmpty))
        actions.append { [weak self] in self?.showDropItemMenu(character: character, onBack: onBack, fromDM: fromDM) }

        menuOpts.append(MenuOption("Give Item", isDisabled: character.inventory.isEmpty || !hasOthers))
        actions.append { [weak self] in self?.showGiveItemMenu(character: character, onBack: onBack, fromDM: fromDM) }

        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showPackHelp(character: character, onBack: onBack, fromDM: fromDM) }

        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        actions.append { [weak self] in
            self?.closeHandler = nil
            self?.showInventoryFor(character, onBack: onBack, fromDM: fromDM)
        }

        showMenuOptions(menuOpts)
        closeHandler = { [weak self] in
            self?.closeHandler = nil
            self?.showInventoryFor(character, onBack: onBack, fromDM: fromDM)
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

    private func showPackHelp(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        showInlineHelp {
            self.printTitle("Pack Help")
            self.print("")
            self.printWrapped("Your pack holds items you're carrying but not wearing — potions, torches, scrolls, gems, and spare gear.", indent: 2, color: .green)
            self.print("")
            self.print("  USE ITEM", color: .cyan, bold: true)
            self.printWrapped("Drink a potion to heal or gain temporary effects, or use a tool item like a Whetstone. Only consumable/usable items appear here.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  DROP ITEM", color: .cyan, bold: true)
            self.printWrapped("Drop an item on the ground in the current room. You can pick it up again later if you return.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  GIVE ITEM", color: .cyan, bold: true)
            self.printWrapped("Transfer an item to another party member. They must have room in their pack to accept it.", indent: 2, color: .dimGreen)
            self.print("")

            if !character.inventory.isEmpty {
                self.print("  WHAT'S IN \(self.shortName(for: character).uppercased())'S PACK", color: .cyan, bold: true)
                self.print("")
                for item in character.inventory {
                    self.print("  \(item.name)", color: .brightGreen)
                    self.printWrapped("    \(item.description)", indent: 4, color: .dimGreen)
                    self.printWrapped("    \(self.itemUsageHint(item))", indent: 4, color: .yellow)
                    self.print("")
                }
            }
        }
    }

    /// How/when an item can actually be used — shown in pack help and at merchants,
    /// so nothing sits in the pack as a mystery.
    /// How/when an item can actually be used — shown in pack help and at
    /// merchants, so nothing sits in the pack (or on a shelf) as a mystery.
    func itemUsageHint(_ item: Item) -> String {
        switch item.name {
        case "Whetstone":
            return "Use: sharpens your equipped weapon (+1 to hit/damage, next 3 attacks). Lasts 5–10 sharpenings, and may crack."
        case let name where item.type == .potion:
            if name.lowercased().contains("antidote") {
                return "Use: cures poison. No effect if not poisoned."
            }
            return "Use: drink to heal HP immediately."
        case "Torch":
            return "Light or douse via the room Actions menu — lights your way and reveals more of the map."
        case "Thieves' Tools":
            return "Passive: gives the party a chance to disarm traps instead of triggering them. Wears out after 8–15 uses, and may snap."
        case "Rope (50 ft)":
            return "Passive: halves damage from Pit Trap encounters."
        case "Spell Component Pouch", "Holy Symbol":
            return "Spellcasting focus — narrative/roleplay item, not required to cast spells in this version."
        default:
            if item.type == .weapon || item.type == .armor || item.type == .shield {
                return "Equip via the Equipment menu to wear or wield it."
            }
            return "No direct action — worth selling to a merchant if you don't need it."
        }
    }

    private func showEquipmentMenu(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        clearTerminal()
        printSubtitle("Equipment — \(shortName(for: character))")

        let weapons = character.inventory.filter { $0.type == .weapon }
        let armors = character.inventory.filter { $0.type == .armor }
        let shields = character.inventory.filter { $0.type == .shield }

        // Show current equipment status
        let wName = character.equippedWeapon?.name ?? "(none)"
        let aName = character.equippedArmor?.name ?? "(none)"
        let sName = character.equippedShield?.name ?? "(none)"
        print("  Weapon: \(wName)", color: character.equippedWeapon != nil ? .brightGreen : .dimGreen)
        print("  Armour: \(aName)", color: character.equippedArmor != nil ? .brightGreen : .dimGreen)
        print("  Shield: \(sName)", color: character.equippedShield != nil ? .brightGreen : .dimGreen)
        print("")

        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        // Weapon slot: equip from bag or unequip current
        if character.equippedWeapon != nil {
            menuOpts.append(MenuOption("Remove Weapon"))
            actions.append { [weak self] in
                let w = character.equippedWeapon!
                character.unequipWeapon()
                self?.print("")
                self?.print("  Unequipped \(w.name).", color: .yellow)
                self?.waitForContinue()
                self?.inputHandler = { [weak self] _ in
                    self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM)
                }
            }
        } else {
            menuOpts.append(MenuOption("Equip Weapon", isDisabled: weapons.isEmpty))
            actions.append { [weak self] in
                self?.showEquipMenu(character: character, type: .weapon, label: "Weapon", onBack: onBack, fromDM: fromDM)
            }
        }

        // Armour slot
        if character.equippedArmor != nil {
            menuOpts.append(MenuOption("Remove Armour"))
            actions.append { [weak self] in
                let a = character.equippedArmor!
                character.unequipArmor()
                self?.print("")
                self?.print("  Unequipped \(a.name).", color: .yellow)
                self?.waitForContinue()
                self?.inputHandler = { [weak self] _ in
                    self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM)
                }
            }
        } else {
            menuOpts.append(MenuOption("Equip Armour", isDisabled: armors.isEmpty))
            actions.append { [weak self] in
                self?.showEquipMenu(character: character, type: .armor, label: "Armour", onBack: onBack, fromDM: fromDM)
            }
        }

        // Shield slot
        if character.equippedShield != nil {
            menuOpts.append(MenuOption("Remove Shield"))
            actions.append { [weak self] in
                let s = character.equippedShield!
                character.unequipShield()
                self?.print("")
                self?.print("  Unequipped \(s.name).", color: .yellow)
                self?.waitForContinue()
                self?.inputHandler = { [weak self] _ in
                    self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM)
                }
            }
        } else {
            menuOpts.append(MenuOption("Equip Shield", isDisabled: shields.isEmpty))
            actions.append { [weak self] in
                self?.showEquipMenu(character: character, type: .shield, label: "Shield", onBack: onBack, fromDM: fromDM)
            }
        }

        // Pass Torch option — if this character holds the lit torch and there are others
        if torchLit && torchHolderId == character.id && party.count > 1 {
            let others = party.filter { $0.id != character.id }
            menuOpts.append(MenuOption("Pass Torch", tint: .amber))
            actions.append { [weak self] in
                guard let self = self else { return }
                self.clearTerminal()
                self.printSubtitle("Pass Torch To...")
                let names = others.map { self.shortName(for: $0) }
                self.showMenu(names)
                self.menuHandler = { [weak self] choice in
                    guard let self = self, choice > 0, choice <= others.count else { return }
                    let recipient = others[choice - 1]
                    // Move torch item from current holder to recipient
                    if let torchId = self.activeTorchId,
                       let idx = character.inventory.firstIndex(where: { $0.id == torchId }) {
                        let torch = character.inventory.remove(at: idx)
                        recipient.inventory.append(torch)
                    }
                    self.torchHolderId = recipient.id
                    self.print("")
                    self.print("  \(self.shortName(for: character)) passes the torch to \(self.shortName(for: recipient)).", color: .yellow)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in
                        self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM)
                    }
                }
                self.closeHandler = { [weak self] in
                    self?.showEquipmentMenu(character: character, onBack: onBack, fromDM: fromDM)
                }
            }
        }

        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showEquipmentHelp(character: character, onBack: onBack, fromDM: fromDM) }

        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        actions.append { [weak self] in
            self?.closeHandler = nil
            self?.showInventoryFor(character, onBack: onBack, fromDM: fromDM)
        }

        showMenuOptions(menuOpts)
        closeHandler = { [weak self] in
            self?.closeHandler = nil
            self?.showInventoryFor(character, onBack: onBack, fromDM: fromDM)
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

    private func showEquipmentHelp(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        showInlineHelp {
            self.printTitle("Equipment Help")
            self.print("")
            self.printWrapped("Equipment is what your character wears or wields in combat. You have three slots: Weapon, Armour, and Shield.", indent: 2, color: .green)
            self.print("")
            self.print("  SLOTS", color: .cyan, bold: true)
            self.printWrapped("Equip/Remove Weapon: Swap your wielded weapon. Damage and hit bonuses change with your weapon.", indent: 2, color: .dimGreen)
            self.printWrapped("Equip/Remove Armour: Change your body armour. This affects your Armour Class (AC).", indent: 2, color: .dimGreen)
            self.printWrapped("Equip/Remove Shield: Equip or remove a shield for +2 AC.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  TORCH", color: .cyan, bold: true)
            self.printWrapped("If your character holds the party torch, you can pass it to another party member from this menu.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    private func showGiveItemMenu(character: Character, onBack: (() -> Void)? = nil, fromDM: Bool = false) {
        let others = party.filter { $0.id != character.id }
        guard !others.isEmpty else {
            showPackMenu(character: character, onBack: onBack, fromDM: fromDM)
            return
        }

        clearTerminal()
        printSubtitle("Give Item — \(shortName(for: character))")

        var options: [String] = []
        for item in character.inventory {
            options.append("\(item.name) (\(formatWeight(item.weight)))")
        }

        closeHandler = { [weak self] in self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM) }

        let inventoryItems = character.inventory
        showPaginatedMenu(options) { [weak self] idx in
            guard let self = self else { return }
            guard idx >= 0 && idx < inventoryItems.count else { return }
            let item = inventoryItems[idx]

            // Show recipient selection
            self.clearTerminal()
            self.printSubtitle("Give \(item.name) to...")

            var recipientOpts: [String] = []
            for other in others {
                let canCarry = other.canCarry(item)
                let tag = canCarry ? "" : (other.isInventoryFull ? " [full]" : " [heavy]")
                recipientOpts.append("\(self.shortName(for: other))\(tag)")
            }
            self.showMenu(recipientOpts)
            self.closeHandler = { [weak self] in self?.showGiveItemMenu(character: character, onBack: onBack, fromDM: fromDM) }
            self.menuHandler = { [weak self] rchoice in
                guard let self = self else { return }
                guard rchoice > 0 && rchoice <= others.count else { return }
                let recipient = others[rchoice - 1]
                if recipient.canCarry(item) {
                    character.removeItem(item)
                    _ = recipient.addItem(item)
                    self.print("")
                    self.print("  \(character.name) gives \(item.name) to \(recipient.name).", color: .brightGreen)
                    self.logEvent("\(character.name) gave \(item.name) to \(recipient.name)", category: "ITEM")
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in
                        self?.showPackMenu(character: character, onBack: onBack, fromDM: fromDM)
                    }
                } else {
                    self.print("")
                    if recipient.isInventoryFull {
                        self.print("  \(recipient.name)'s bag is full! (\(self.formatWeightPair(recipient.currentWeight, recipient.carryCapacity)))", color: .yellow)
                    } else {
                        self.print("  \(recipient.name) can't carry any more!", color: .yellow)
                    }
                    self.print("  Open their inventory or choose someone else.", color: .dimGreen)
                    self.print("")
                    self.showMenu(["Inventory", "Choose Again", "< Back"])
                    self.menuHandler = { [weak self] choice in
                        guard let self = self else { return }
                        if choice == 1 {
                            self.showInventoryFor(recipient, onBack: { [weak self] in
                                self?.showGiveItemMenu(character: character, onBack: onBack, fromDM: fromDM)
                            })
                        } else if choice == 2 {
                            self.showGiveItemMenu(character: character, onBack: onBack, fromDM: fromDM)
                        } else {
                            self.showPackMenu(character: character, onBack: onBack, fromDM: fromDM)
                        }
                    }
                }
            }
        }
    }

    // MARK: - Shop

    func visitShop() {
        guard let dungeon = dungeon, let room = dungeon.currentRoom, let merchant = room.merchant else { return }

        pickCharacter(title: "Who visits \(merchant.name)?", showGold: true, helpAction: { [weak self] in
            guard let self = self else { return }
            self.showInlineHelp {
                self.printTitle("Visit Merchant — Help")
                self.print("")
                self.printWrapped("Pick which character enters \(merchant.name)'s shop. The gold shown is that character's own — purchases, sales, and haggling all come out of their purse specifically.", indent: 2, color: .dimGreen)
                self.print("")
            }
        }) { [weak self] character in
            guard let self = self else { return }
            self.shopEngine.openShop(character: character, dungeonLevel: dungeon.level, merchant: merchant) { [weak self] in
                self?.showExplorationView()
            }
        }
    }

    /// Training gym entry: pay a membership fee, or spar (a skill check
    /// against the trainer's specialty) for free entry.
    func visitGym() {
        guard let dungeon = dungeon, let room = dungeon.currentRoom, var trainer = room.trainer else { return }

        clearTerminal()
        printTitle(trainer.gymName)
        print("")
        print("  \(trainer.name) — trains \(trainer.specialty.rawValue)", color: .dimGreen)
        printWrapped("\"\(trainer.greeting)\"", indent: 2, color: .yellow)
        print("")

        // Already a member here — either paid at THIS gym before, or holds
        // a Multi-Gym Pass covering every gym in the dungeon — so entry is
        // free from now on; go straight to training instead of asking to
        // pay or spar again every single visit.
        if trainer.membershipPaid || dungeon.hasMultiGymPass {
            print("  \"Welcome back.\"", color: .brightGreen)
            print("")
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
            return
        }

        let passPrice = trainer.membershipFee * 4
        showMenu(["Pay Membership (\(trainer.membershipFee)gp)", "Spar for Free Entry", "Multi-Gym Pass (\(passPrice)gp)", "< Leave"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.pickCharacter(title: "Who pays the membership?", cancelLabel: "Don't Enter", showGold: true) { [weak self] character in
                    guard let self = self else { return }
                    guard character.gold >= trainer.membershipFee else {
                        self.print("")
                        self.print("  \"Not enough gold, friend.\"", color: .red)
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in self?.showExplorationView() }
                        return
                    }
                    character.gold -= trainer.membershipFee
                    trainer.membershipPaid = true
                    room.trainer = trainer
                    self.print("")
                    self.print("  \"Welcome to \(trainer.gymName). That's good for the rest of the adventure — no need to pay again.\"", color: .brightGreen)
                    self.advanceTime(15)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
                }
            case 2:
                self.pickCharacter(title: "Who spars?", cancelLabel: "Don't Enter") { [weak self] character in
                    guard let self = self else { return }
                    let mod = character.skillModifier(for: trainer.specialty)
                    let roll = Dice.roll(20)
                    let total = roll + mod
                    self.print("")
                    self.print("  \(character.name) spars: d20[\(roll)] + \(mod) = \(total) vs DC \(trainer.sparDC)", color: .dimGreen)
                    self.advanceTime(15)
                    if total >= trainer.sparDC {
                        trainer.membershipPaid = true
                        room.trainer = trainer
                        self.print("  \"Not bad! You've earned your way in — for good.\"", color: .brightGreen)
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
                    } else {
                        self.print("  \"Not good enough. Pay up, or come back stronger.\"", color: .red)
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in self?.showExplorationView() }
                    }
                }
            case 3:
                self.pickCharacter(title: "Who buys the pass?", cancelLabel: "Don't Enter", showGold: true) { [weak self] character in
                    guard let self = self else { return }
                    guard character.gold >= passPrice else {
                        self.print("")
                        self.print("  \"That's the going rate for every gym in these halls. Come back with more coin.\"", color: .red)
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in self?.showExplorationView() }
                        return
                    }
                    character.gold -= passPrice
                    dungeon.hasMultiGymPass = true
                    self.print("")
                    self.print("  \"A Multi-Gym Pass! Every gym in these halls will recognise this — no more membership fees, anywhere.\"", color: .brightGreen)
                    self.advanceTime(15)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
                }
            default:
                self.showExplorationView()
            }
        }
    }

    /// Training grants proficiency in a skill the character doesn't already
    /// have (permanent); training an already-known skill gives a small XP
    /// bonus instead so the option is never a dead end.
    private func showGymTraining(trainer: Trainer, room: Room) {
        pickCharacter(title: "Who trains?") { [weak self] character in
            guard let self = self else { return }

            var offered: [Skill] = [trainer.specialty]
            for skill in Skill.allCases.shuffled() where !offered.contains(skill) {
                offered.append(skill)
                if offered.count >= 4 { break }
            }

            self.clearTerminal()
            self.printTitle(trainer.gymName)
            print("")
            self.print("  Which skill should \(character.name) train?", color: .cyan)
            print("")

            print("  Lessons cost \(trainer.lessonFee)gp each — \(character.name) has \(character.gold)gp.", color: .dimGreen)
            print("")

            let options = offered.map { skill -> String in
                character.skillProficiencies.contains(skill)
                    ? "\(skill.rawValue) (already trained, \(trainer.lessonFee)gp)"
                    : "\(skill.rawValue) (\(trainer.lessonFee)gp)"
            }
            // Map Training — the gym's priciest lesson, once per adventure
            // (it carries to deeper levels): unlocks the Atlas.
            let mapTrainingPrice = trainer.lessonFee * 8
            let offersMapTraining = !(self.dungeon?.hasCartography ?? true)
            if offersMapTraining {
                self.printWrapped("\(trainer.name) also teaches Map Training — the cartographer's art — for \(mapTrainingPrice)gp. Expensive, but you'll never look at a map the same way again.", indent: 2, color: .dimGreen)
                self.print("")
            }
            // Incantations — arcane trainers teach the true words for every
            // spell this character knows (see showIncantationChoice).
            let incantationPrice = trainer.lessonFee * 2
            let unlearned = character.knownSpells.filter { !character.knownIncantations.contains($0.name) }
            let offersIncantations = (trainer.specialty == .arcana || trainer.specialty == .investigation) && !unlearned.isEmpty
            if offersIncantations {
                self.printWrapped("\(trainer.name) can also teach \(character.name) the true incantations for their spells, so they're never spoken wrong — \(incantationPrice)gp.", indent: 2, color: .dimGreen)
                self.print("")
            }
            var extraLabels: [String] = []
            if offersMapTraining { extraLabels.append("Map Training (\(mapTrainingPrice)gp)") }
            if offersIncantations { extraLabels.append("Incantations (\(incantationPrice)gp)") }
            let trainingMenu = options + extraLabels
            self.showMenu(trainingMenu + ["< Done"])
            self.menuHandler = { [weak self] choice in
                guard let self = self else { return }
                if choice > offered.count && choice <= offered.count + extraLabels.count {
                    if extraLabels[choice - offered.count - 1].hasPrefix("Map Training") {
                        self.buyMapTraining(character: character, trainer: trainer, room: room, price: mapTrainingPrice)
                    } else {
                        self.teachIncantations(character: character, trainer: trainer, room: room, price: incantationPrice)
                    }
                    return
                }
                guard choice >= 1 && choice <= offered.count else {
                    self.showExplorationView()
                    return
                }
                let skill = offered[choice - 1]
                self.print("")
                guard character.gold >= trainer.lessonFee else {
                    self.print("  \"Coin first, then the lesson.\" (\(character.name) doesn't have \(trainer.lessonFee)gp.)", color: .red)
                    self.printWrapped("\"...unless you've got something worth trading?\"", indent: 2, color: .yellow)
                    print("")
                    self.showMenu(["Barter", "< Back"])
                    self.menuHandler = { [weak self] choice in
                        guard let self = self else { return }
                        if choice == 1 {
                            self.offerGymBarter(skill: skill, character: character, trainer: trainer, room: room)
                        } else {
                            self.showGymTraining(trainer: trainer, room: room)
                        }
                    }
                    return
                }
                character.gold -= trainer.lessonFee
                if character.skillProficiencies.contains(skill) {
                    let xp = 20
                    character.experiencePoints += xp
                    self.print("  \"You've already got a good handle on that — but keep at it.\" (+\(xp) XP)", color: .yellow)
                    self.advanceTime(30)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
                } else {
                    self.attemptGymTraining(skill: skill, character: character, trainer: trainer, room: room)
                }
            }
        }
    }

    /// Trading an item in (at half value, same rate Sell/shop Barter use)
    /// toward a lesson fee the character can't afford in gold alone.
    private func offerGymBarter(skill: Skill, character: Character, trainer: Trainer, room: Room) {
        let sellables = character.inventory.filter { $0.value > 0 }
        clearTerminal()
        printTitle(trainer.gymName)
        print("  Lesson fee: \(trainer.lessonFee)gp — \(character.name) has \(character.gold)gp.", color: .dimGreen)
        print("")
        guard !sellables.isEmpty else {
            print("  \"Nothing on you worth trading in. Come back when you've got coin.\"", color: .red)
            waitForContinue()
            inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
            return
        }

        let options = sellables.map { "\($0.name) (worth \(max(1, $0.value / 2))gp)" } + ["< Back"]
        showMenu(options)
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            guard choice >= 1 && choice <= sellables.count else {
                self.showGymTraining(trainer: trainer, room: room)
                return
            }
            let offeredItem = sellables[choice - 1]
            let credit = max(1, offeredItem.value / 2)
            self.print("")
            guard character.gold + credit >= trainer.lessonFee else {
                self.print("  \"That, plus your coin, still isn't enough for the lesson.\"", color: .red)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
                return
            }
            let goldSpent = max(0, trainer.lessonFee - credit)
            character.gold -= goldSpent
            character.removeItem(offeredItem)
            self.print("  \"Deal.\" \(trainer.name) takes your \(offeredItem.name)\(goldSpent > 0 ? " and \(goldSpent) gold" : "") for the lesson.", color: .brightGreen)
            if character.skillProficiencies.contains(skill) {
                let xp = 20
                character.experiencePoints += xp
                self.print("  \"You've already got a good handle on that — but keep at it.\" (+\(xp) XP)", color: .yellow)
                self.advanceTime(30)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
            } else {
                self.attemptGymTraining(skill: skill, character: character, trainer: trainer, room: room)
            }
        }
    }

    /// A new skill isn't always an instant hand-out: it's picked up
    /// naturally about as often as it takes a puzzle to prove aptitude, and
    /// sometimes the trainer flatly refuses until the character has used it
    /// for real — that promise is fulfilled by handleCombatVictory().
    private func attemptGymTraining(skill: Skill, character: Character, trainer: Trainer, room: Room) {
        let roll = Int.random(in: 1...100)
        switch roll {
        case 1...40:
            self.print("  It clicks right away — a natural fit.", color: .cyan)
            grantGymSkill(skill, to: character, trainer: trainer, room: room)
        case 41...70:
            let riddle = RiddleData.all[RiddleData.nextIndex()]
            presentGymRiddle(riddle, skill: skill, character: character, trainer: trainer, room: room)
        default:
            pendingBattleTrainedSkills[character.id, default: []].append((skill, trainer.gymName))
            self.print("  \"\(skill.rawValue)? I won't just hand that over — go prove it in a real fight, and it's yours.\"", color: .yellow)
            self.advanceTime(15)
            self.waitForContinue()
            self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
        }
    }

    private func grantGymSkill(_ skill: Skill, to character: Character, trainer: Trainer, room: Room) {
        character.skillProficiencies.insert(skill)
        self.print("  \(character.name) is now proficient in \(skill.rawValue)!", color: .brightGreen, bold: true)
        self.logEvent("\(character.name) trained \(skill.rawValue) at \(trainer.gymName)", category: "LEVEL")
        self.logMultiplayerAction("\(character.name) trained \(skill.rawValue) at \(trainer.gymName)")
        self.advanceTime(30)
        self.waitForContinue()
        self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
    }

    /// One retry on a wrong answer, then the trainer sends them away —
    /// mirrors presentRiddle's leniency (never a hard dead end).
    private func presentGymRiddle(_ riddle: Riddle, skill: Skill, character: Character, trainer: Trainer, room: Room, attemptsUsed: Int = 0) {
        let (options, correctIndex) = riddle.shuffled()

        clearTerminal()
        printTitle(trainer.gymName)
        print("")
        print("  \"Answer me this, and \(skill.rawValue) is yours.\"", color: .cyan)
        printWrapped("\"\(riddle.question)\"", indent: 2, color: .yellow)
        print("")

        showMenu(options + ["< Give Up"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == options.count + 1 {
                self.print("")
                self.print("  You leave the puzzle unanswered — perhaps another time.", color: .dimGreen)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
                return
            }
            guard choice >= 1 && choice <= options.count else { return }
            self.print("")
            if choice - 1 == correctIndex {
                self.print("  Correct! \"\(riddle.correctAnswer)\"", color: .brightGreen, bold: true)
                self.grantGymSkill(skill, to: character, trainer: trainer, room: room)
            } else if attemptsUsed < 1 {
                self.print("  Not quite. Try again.", color: .red)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.presentGymRiddle(riddle, skill: skill, character: character, trainer: trainer, room: room, attemptsUsed: attemptsUsed + 1)
                }
            } else {
                self.print("  \"Not this time. Come back when you've thought it over.\"", color: .red)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showGymTraining(trainer: trainer, room: room) }
            }
        }
    }

    /// Presents a classic riddle (public-domain folklore/mythology, multiple
    /// choice so the answer is never ambiguous) with a bonus reward for a
    /// correct answer. Two wrong attempts and the challenge is spent — no
    /// other penalty, and it never blocks progression, only a bonus prize.
    func presentRiddle(index: Int, room: Room, attemptsUsed: Int = 0) {
        guard index >= 0 && index < RiddleData.all.count else { return }
        let riddle = RiddleData.all[index]
        let (options, correctIndex) = riddle.shuffled()

        clearTerminal()
        printTitle("A Riddle")
        print("")
        printWrapped("\"\(riddle.question)\"", indent: 2, color: .yellow)
        print("")

        showMenu(options + ["< Leave it"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == options.count + 1 {
                self.print("")
                self.print("  You leave the riddle unanswered — perhaps another time.", color: .dimGreen)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showExplorationView() }
                return
            }
            guard choice >= 1 && choice <= options.count else { return }
            if choice - 1 == correctIndex {
                room.riddleResolved = true
                let level = self.dungeon?.level ?? 1
                let gold = Dice.rollSum(2, d: 6) * level
                let reward = level >= 3 ? ItemCatalog.greaterHealingPotion() : ItemCatalog.healingPotion()
                self.print("")
                self.print("  Correct! \"\(riddle.correctAnswer)\"", color: .brightGreen, bold: true)
                self.printWrapped("  (\(riddle.source))", indent: 2, color: .dimGreen)
                self.print("")
                self.print("  You find \(gold) gold and \(reward.name) left as a reward for the wise.", color: .yellow)
                self.logEvent("Solved a riddle for \(gold) gold and \(reward.name)", category: "EXPLORE")
                self.logMultiplayerAction("Solved a riddle — found \(gold) gold and \(reward.name)")
                self.showGoldPickupMenu(gold: gold, source: "Riddle reward", narrative: nil) { [weak self] in
                    guard let self = self else { return }
                    self.showItemPickupMenu(item: reward, source: "Riddle reward", narrative: nil) { [weak self] in
                        self?.showExplorationView()
                    }
                }
            } else {
                let attempts = attemptsUsed + 1
                if attempts >= 2 {
                    room.riddleResolved = true
                    self.print("")
                    self.print("  Wrong. The moment passes — the riddle's answer was \"\(riddle.correctAnswer)\".", color: .red)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.showExplorationView() }
                } else {
                    self.print("")
                    self.print("  Not quite. Try again.", color: .red)
                    self.waitForContinue()
                    self.inputHandler = { [weak self] _ in self?.presentRiddle(index: index, room: room, attemptsUsed: attempts) }
                }
            }
        }
    }

    /// A puzzle from PuzzleBank — deeper levels' answer to the riddles:
    /// logic (pick one), word and cryptic (type it). Hints help, but each
    /// one takes a quarter off the gold. Wrong answers use up tries; it never
    /// blocks the way on, it's only a prize.
    func presentPuzzle(_ puzzle: Puzzle, room: Room, attempts: Int = 0, hintsUsed: Int = 0, shuffled: (options: [String], correctIndex: Int)? = nil) {
        let maxTries = puzzle.isTyped ? 3 : 2
        let order = shuffled ?? puzzle.shuffledOptions()
        clearTerminal()
        printTitle(Puzzle.kindName(puzzle.tier))
        print("")
        printWrapped("\"\(puzzle.question)\"", indent: 2, color: .yellow)
        if puzzle.tier == 4 && hintsUsed == 0 && attempts == 0 {
            print("")
            printWrapped("(A cryptic clue: one part means the answer, the rest is wordplay that builds it. The number is how many letters.)", indent: 2, color: .dimGreen)
        }
        for i in 0..<min(hintsUsed, puzzle.hintList.count) {
            print("")
            printWrapped("Hint \(i + 1): \(puzzle.hintList[i])", indent: 2, color: .cyan)
        }
        if attempts > 0 {
            print("")
            print("  \(maxTries - attempts) \(maxTries - attempts == 1 ? "try" : "tries") left.", color: .dimGreen)
        }
        print("")

        let hintsLeft = puzzle.hintList.count - hintsUsed
        let hintLabel = "Hint (\(hintsLeft) left)"
        let leave = { [weak self] in
            guard let self = self else { return }
            self.print("")
            self.print("  You leave it for now — it'll still be here.", color: .dimGreen)
            self.waitForContinue()
            self.inputHandler = { [weak self] _ in self?.showExplorationView() }
        }
        let takeHint = { [weak self] in
            self?.presentPuzzle(puzzle, room: room, attempts: attempts, hintsUsed: hintsUsed + 1, shuffled: order)
        }
        let answered: (Bool) -> Void = { [weak self] right in
            guard let self = self else { return }
            if right {
                room.riddleResolved = true
                let level = self.dungeon?.level ?? 1
                let base = Dice.rollSum(2, d: 6) * level * (puzzle.tier + 1) / 2
                let gold = max(1, base * max(1, 4 - hintsUsed) / 4)
                let reward = ItemCatalog.greaterHealingPotion()
                self.print("")
                self.print("  Correct! \"\(puzzle.correctAnswer)\"", color: .brightGreen, bold: true)
                if let source = puzzle.source, !source.isEmpty { self.printWrapped("(\(source))", indent: 2, color: .dimGreen) }
                self.print("")
                self.print("  You find \(gold) gold and \(reward.name) left for the clever.", color: .yellow)
                self.logEvent("Solved a puzzle (\(puzzle.id)) for \(gold) gold and \(reward.name)", category: "EXPLORE")
                self.logMultiplayerAction("Solved a puzzle — found \(gold) gold and \(reward.name)")
                self.showGoldPickupMenu(gold: gold, source: "Puzzle reward", narrative: nil) { [weak self] in
                    self?.showItemPickupMenu(item: reward, source: "Puzzle reward", narrative: nil) { [weak self] in
                        self?.showExplorationView()
                    }
                }
            } else if attempts + 1 >= maxTries {
                room.riddleResolved = true
                self.print("")
                self.print("  Wrong. The inscription fades — the answer was \"\(puzzle.correctAnswer)\".", color: .red)
                self.logEvent("Couldn't solve a puzzle (\(puzzle.id))", category: "EXPLORE")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showExplorationView() }
            } else {
                self.print("")
                self.print("  Not quite. Try again.", color: .red)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.presentPuzzle(puzzle, room: room, attempts: attempts + 1, hintsUsed: hintsUsed, shuffled: order)
                }
            }
        }
        closeHandler = { [weak self] in self?.showExplorationView() }

        if puzzle.isTyped {
            var buttons: [String] = []
            if hintsLeft > 0 { buttons.append(hintLabel) }
            buttons.append("< Leave it")
            promptTextWithMenu("  Type your answer:", options: buttons)
            inputHandler = { text in
                let t = text.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !t.isEmpty else { return }
                answered(puzzle.accepts(t))
            }
            menuHandler = { choice in
                guard choice >= 1, choice <= buttons.count else { return }
                if buttons[choice - 1] == hintLabel { takeHint() } else { leave() }
            }
        } else {
            var buttons = order.options
            if hintsLeft > 0 { buttons.append(hintLabel) }
            buttons.append("< Leave it")
            showMenu(buttons)
            menuHandler = { choice in
                guard choice >= 1, choice <= buttons.count else { return }
                if choice - 1 < order.options.count { answered(choice - 1 == order.correctIndex) }
                else if buttons[choice - 1] == hintLabel { takeHint() }
                else { leave() }
            }
        }
    }

    /// Settings > Puzzles: what's installed, fetch new ones, suggest one.
    func showPuzzleSettings(onBack: @escaping () -> Void) {
        clearTerminal()
        printTitle("Puzzles")
        print("")
        printWrapped("Libraries and shrines pose puzzles, harder the deeper you go: riddles on Levels 1-2, logic puzzles on 3-4, word puzzles on 5-6 (type the answer) and cryptic clues on Level 7. Hints help, but each costs a little of the prize.", indent: 2, color: .green)
        print("")
        let pack = PuzzlePackManager.shared
        let counts = (2...4).map { t in PuzzleBank.all.filter { $0.tier == t }.count }
        printWrapped("Puzzles: \(RiddleData.all.count) riddles, \(counts[0]) logic, \(counts[1]) word, \(counts[2]) cryptic.", indent: 2, color: .brightGreen)
        printWrapped(pack.version > 0 ? "Puzzle pack v\(pack.version) installed (checked and signed)." : "Built-in puzzles only — no pack downloaded yet.", indent: 2, color: .dimGreen)
        print("")
        printWrapped("New puzzles arrive now and then as a small signed pack. The game checks for one once a day, and only accepts a pack that carries the author's signature.", indent: 2, color: .dimGreen)
        print("")
        let opts = ["Check for New Puzzles", "Suggest a Puzzle", "< Back"]
        showMenu(opts)
        closeHandler = onBack
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.print("  Checking…", color: .dimGreen)
                PuzzlePackManager.shared.check { [weak self] message in
                    self?.print("  \(message)", color: .cyan)
                }
            case 2:
                self.openPuzzleSuggestion()
                self.print("  Opening a suggestion form on GitHub in your browser…", color: .cyan)
            default:
                onBack()
            }
        }
    }

    /// A pre-filled GitHub issue — the puzzle's author fills in the blanks.
    private func openPuzzleSuggestion() {
        var c = URLComponents(string: "https://github.com/profLewis/gamer/issues/new")
        let body = """
        **Question:**

        **Answer** (plus any other answers that should count):

        **Multiple choice?** If so, list 3 wrong options:

        **Hints** (up to 3, easiest last):

        **Suits levels** (1-2 riddle, 3-4 logic, 5-6 word, 7 cryptic):

        **Source** (your own, or traditional/public domain):
        """
        c?.queryItems = [URLQueryItem(name: "title", value: "Puzzle suggestion: "),
                         URLQueryItem(name: "labels", value: "puzzle-suggestion"),
                         URLQueryItem(name: "body", value: body)]
        guard let url = c?.url else { return }
        DispatchQueue.main.async {
            #if canImport(UIKit)
            UIApplication.shared.open(url)
            #elseif os(macOS)
            NSWorkspace.shared.open(url)
            #endif
        }
    }

    /// A fresh main quest — a new village in trouble, a new villain at the
    /// bottom, a new Opening Tale. The party, their things, the dungeon and
    /// any side quests stay as they are.
    /// The DM's remarks about renamed adventurers, shown on the next story screen.
    private var pendingDMRemarks: [String] = []
    /// Read Aloud reads from here on (a fight reads each new turn's lines).
    private var speechFromLine = 0
    /// The next timed screen gets full reading time (e.g. a fight's opening).
    private var readingPaceNext = false

    /// How long the lines added since the last turn take to read (~200 wpm).
    private func newTextReadingTime() -> Double {
        let from = min(speechFromLine, terminalLines.count)
        let words = terminalLines[from...].reduce(0) { total, line in
            total + line.text.split(separator: " ").filter { $0.contains(where: { $0.isLetter }) }.count
        }
        return Double(words) / 3.3
    }

    /// No two adventurers share a name (fights and quests get muddled): a
    /// second Kevin becomes "Kev" (or another name), and the DM says so.
    @discardableResult
    private func ensureUniqueNames() -> [String] {
        var seen = Set<String>()
        var remarks: [String] = []
        for c in party {
            let key = c.name.lowercased()
            guard seen.contains(key) else { seen.insert(key); continue }
            let old = c.name
            let isRobot = old.hasPrefix("R. ")
            let bare = isRobot ? String(old.dropFirst(3)) : old
            let first = bare.split(separator: " ").first.map(String.init) ?? bare
            var candidates: [String] = []
            if first.count >= 5 { candidates.append(String(first.prefix(3))) }
            candidates += ["Lucy", "Pip", "Bram", "Tilly", "Oswin", "Mags", "Fen", "Rook", "Wren", "Dot"].shuffled()
            let taken = Set(party.map { $0.name.lowercased() }).union(seen)
            let pick = candidates.first { !taken.contains($0.lowercased()) && !taken.contains(("R. " + $0).lowercased()) } ?? bare + " the Second"
            c.name = (isRobot ? "R. " : "") + pick
            seen.insert(c.name.lowercased())
            let plural = first.hasSuffix("s") ? first + "es" : first + "s"
            remarks.append("The DM squints at the party. \"Two \(plural)? That'll never do in a fight. I'm going to call one of you \(pick), then.\"")
            logEvent("Renamed a second \(old) to \(c.name) — no two adventurers share a name", category: "SYSTEM")
        }
        return remarks
    }

    /// A new adventure: the tale comes first (no map yet), then the party is
    /// asked whether they'll take the quest on.
    private func beginQuestOffer() {
        let renames = ensureUniqueNames()
        if !renames.isEmpty {
            storyScreenActive = true
            pinnedMapLines = []
            clearTerminal()
            printTitle("A Word from the DM")
            print("")
            for remark in renames { printWrapped(remark, indent: 2, color: .cyan); print("") }
            waitForContinue()
            inputHandler = { [weak self] _ in self?.beginQuestOffer() }
            return
        }
        storyScreenActive = true
        pinnedMapLines = []
        adventureLog = []
        questHistory = []
        noMainQuest = false
        mainQuestCompleted = false
        mainQuest = nil
        questPleaPrevious = nil
        questPleaAsker = nil
        npcQuestOffers = [:]
        adventureIntroLines = []
        playAdventureCutscene { [weak self] in
            self?.askToTakeQuest(then: { [weak self] in self?.enterDungeon() })
        }
    }

    /// "Will you take it on?" — yes; hear someone else's plea (they riff on
    /// this one); or no quest at all. When changing quest: take up the new
    /// one, hear another, or try to go back to the old one.
    private func askToTakeQuest(then proceed: @escaping () -> Void) {
        guard let mq = mainQuest else { proceed(); return }
        storyScreenActive = true
        clearTerminal()
        printTitle("Will You Take It On?")
        print("")
        printWrapped("To \(mq.goal), \(mq.stakes).", indent: 2, color: .yellow)
        printWrapped("The reward: \(mq.reward).", indent: 2, color: .green)
        if mq.kind != "mystery" && mq.kind != "twist" {
            printWrapped("Waiting at the very bottom: \(mq.villain).", indent: 2, color: .green)
        }
        print("")
        let old = questChangeBackup?.quest
        if let old = old {
            printWrapped("Take it on and the quest to \(old.goal) is left behind. Or hear someone else — or try to go back to \(old.village), if they'll still have you.", indent: 2, color: .dimGreen)
        } else {
            printWrapped("Take it on, hear what someone else wants doing, or set off with no quest at all — just the adventure (there are always errands on the way).", indent: 2, color: .dimGreen)
        }
        print("")
        showMenu(old != nil ? ["Take Up the New Quest", "Hear Another Plea", "Back to Our Old Quest"]
                            : ["Take Up the Quest", "Hear Another Plea", "No Quest"])
        closeHandler = { [weak self] in self?.acceptQuest(then: proceed) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                self.acceptQuest(then: proceed)
            case 2:
                self.questHistory.append("Turned down a plea to \(mq.goal) (\(Dungeon.guardianName(mq.villain))).")
                self.logEvent("Turned down the quest: \(mq.summary)", category: "QUEST")
                self.questPleaPrevious = mq
                self.questPleaAsker = Self.pleaAskers.randomElement()
                let avoid = [mq.villain, self.questChangeBackup?.quest.villain].compactMap { $0 }
                var next = MainQuest.random()
                for _ in 0..<12 where avoid.contains(next.villain) || next.kind == mq.kind { next = MainQuest.random() }
                self.mainQuest = next
                self.playAdventureCutscene { [weak self] in self?.askToTakeQuest(then: proceed) }
            default:
                if let backup = self.questChangeBackup {
                    self.tryReturningToOldQuest(backup, then: proceed)
                    return
                }
                self.questHistory.append("Turned every plea down and set out with no main quest — just for the adventure.")
                self.logEvent("Set out with no main quest", category: "QUEST")
                self.mainQuest = nil
                self.noMainQuest = true
                self.questPleaPrevious = nil
                self.questPleaAsker = nil
                self.adventureIntroLines.append("In the end the party turned the plea down, and set off for the sheer adventure of it.")
                proceed()
            }
        }
    }

    /// Going back to the quest you walked away from — they might have you
    /// back, or they might not (only an older save remembers it then).
    private func tryReturningToOldQuest(_ backup: (quest: MainQuest, intro: [String]), then proceed: @escaping () -> Void) {
        let old = backup.quest
        clearTerminal()
        printTitle("Back to \(old.village)?")
        print("")
        if Bool.random() {
            mainQuest = old
            adventureIntroLines = backup.intro
            questChangeBackup = nil
            questPleaPrevious = nil
            questPleaAsker = nil
            questHistory.append("Thought better of it, and went back to the quest to \(old.goal).")
            logEvent("Went back to the old quest: \(old.summary)", category: "QUEST")
            printWrapped("You send the bird back with an apology. By morning an answer comes from \(old.village): \"Fine. But don't make a habit of it.\" The quest is yours again.", indent: 2, color: .green)
            waitForContinue()
            inputHandler = { _ in proceed() }
        } else {
            questChangeBackup = nil
            questHistory.append("Tried to go back to the quest to \(old.goal), but \(old.village) had already found other heroes.")
            logEvent("Couldn't go back to the old quest", category: "QUEST")
            printWrapped("You send word back to \(old.village). The answer comes quickly, and it isn't kind: they've found other heroes, and they've no use for oath-breakers. There's no going back.", indent: 2, color: .yellow)
            print("")
            printWrapped("(Only an older save remembers that quest now.)", indent: 2, color: .dimGreen)
            applyOathBreakingCost()
            waitForContinue()
            inputHandler = { [weak self] _ in self?.askToTakeQuest(then: proceed) }
        }
    }

    /// The dungeon doesn't like oath-breakers: one time in three it throws
    /// the party back to the entrance, and a thing or two falls out of packs.
    private func applyOathBreakingCost() {
        guard Int.random(in: 1...3) == 1 else { return }
        print("")
        printWrapped("The ground lurches. The fire gutters out, the walls spin — and you're lying in a heap by the entrance.", indent: 2, color: .red)
        applyTeleportToEntrance()
        var dropped: [String] = []
        for _ in 0..<Int.random(in: 1...2) {
            let loose: (Character) -> [Item] = { c in
                c.inventory.filter { i in i.id != c.equippedWeapon?.id && i.id != c.equippedArmor?.id && i.id != c.equippedShield?.id }
            }
            guard let c = party.filter({ !loose($0).isEmpty }).randomElement(), let item = loose(c).randomElement() else { break }
            c.removeItem(item)
            dropped.append("\(item.name) (\(shortName(for: c)))")
        }
        if !dropped.isEmpty { printWrapped("Lost on the way: \(dropped.joined(separator: ", ")).", indent: 2, color: .red) }
        logEvent("Breaking the oath cost the party: back to the entrance\(dropped.isEmpty ? "" : ", lost " + dropped.joined(separator: ", "))", category: "QUEST")
    }

    private func acceptQuest(then proceed: @escaping () -> Void) {
        guard let mq = mainQuest else { proceed(); return }
        questHistory.append("Took up the quest: to \(mq.goal) (\(Dungeon.guardianName(mq.villain))).")
        logEvent("Took up the quest: \(mq.summary)", category: "QUEST")
        noMainQuest = false
        questPleaPrevious = nil
        questPleaAsker = nil
        progressTaleCache = nil
        guard let backup = questChangeBackup else { proceed(); return }
        // A new oath means breaking the old one.
        questChangeBackup = nil
        questHistory.append("Left the quest to \(backup.quest.goal) behind.")
        clearTerminal()
        printTitle("A New Oath")
        print("")
        printWrapped("You take up the quest to \(mq.goal). Somewhere far behind, \(backup.quest.village) will have to find other heroes.", indent: 2, color: .green)
        applyOathBreakingCost()
        waitForContinue()
        inputHandler = { _ in proceed() }
    }

    /// Someone down here with a quest going spare — offered to a party that
    /// has none.
    private func hearNPCMainQuest(npc: DungeonNPC, roomId: Int) {
        let who = npc.type.rawValue.lowercased()
        let q = npcQuestOffers[roomId] ?? MainQuest.random()
        npcQuestOffers[roomId] = q
        clearTerminal()
        printTitle("A Real Quest")
        print("")
        printWrapped("The \(who) leans in. \"Back in \(q.village), \(q.harm ?? "things have gone badly wrong").\"", indent: 2, color: .yellow)
        if q.kind != "mystery", q.kind != "twist", let motive = q.motive {
            printWrapped("\"It's \(q.villain), who \(motive).\"", indent: 2, color: .yellow)
        }
        printWrapped("\"Someone needs to \(q.goal), \(q.stakes). There's \(q.reward) in it — and a proper story to tell.\"", indent: 2, color: .yellow)
        print("")
        showMenu(["Take It On", "Not For Us"])
        closeHandler = { [weak self] in self?.talkToNPC() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            guard choice == 1 else { self.talkToNPC(); return }
            self.mainQuest = q
            self.noMainQuest = false
            self.progressTaleCache = nil
            self.npcQuestOffers[roomId] = nil
            self.questHistory.append("Took up a quest from a \(who) in \(self.dungeon?.name ?? "the dungeon"): to \(q.goal) (\(Dungeon.guardianName(q.villain))).")
            self.logEvent("Took up a quest from the \(who): \(q.summary)", category: "QUEST")
            self.adventureIntroLines.append("Deep in the dungeon, a \(who) told them of \(q.village)'s trouble, and they took the quest on: to \(q.goal).")
            self.print("")
            self.printWrapped("\"Good. About time,\" says the \(who). (It's your main quest now — see Party Status.)", indent: 2, color: .brightGreen)
            self.waitForContinue()
            self.inputHandler = { [weak self] _ in self?.talkToNPC() }
        }
    }

    /// Back to a saved game: the Opening Tale again (Skip jumps past it), then
    /// the story so far — the map only once play starts.
    /// Party Status > Tale: how it began, how it's going, or the short version.
    private func showTaleMenu() {
        storyScreenActive = false
        clearTerminal()
        printTitle("The Tale")
        print("")
        printWrapped("How it began, how it's going — or the short version.", indent: 2, color: .dimGreen)
        print("")
        let back: () -> Void = { [weak self] in self?.showTaleMenu() }
        showMenu(["Opening Tale", "Progress Tale", "The Story So Far", "?", "< Back"])
        closeHandler = { [weak self] in self?.showPartyStatus() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: self.showOpeningTale(page: 0, onBack: back)
            case 2: self.showProgressTale(onBack: back)
            case 3: self.showStorySoFar(onDone: back)
            case 4:
                self.showInlineHelp {
                    self.printTitle("The Tale — Help")
                    self.print("")
                    self.printWrapped("Opening Tale — how this adventure began, page by page (Next, Previous, Skip); its last page leads on into the Progress Tale.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("Progress Tale — the story so far, told the same way (written by the story writer when an AI is set up).", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("The Story So Far — a quick summary: the quest and how it's going, level by level, errands, fights and the latest news.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default:
                self.showPartyStatus()
            }
        }
    }

    private func showResumeStory() {
        storyScreenActive = true
        pinnedMapLines = []
        let lines = adventureIntroLines.isEmpty ? recoveredIntroLines() : adventureIntroLines
        guard !lines.isEmpty else { showStorySoFar(); return }
        showTalePages(title: "The Tale Begins", lines: lines, page: 0, onBack: { [weak self] in self?.showStorySoFar() },
                      finishLabel: "The Story So Far >", onFinish: { [weak self] in self?.showStorySoFar() }, skipLabel: "Skip")
    }

    private func showStorySoFar(onDone: (() -> Void)? = nil) {
        storyScreenActive = true
        clearTerminal()
        printTitle("The Story So Far")
        print("")
        for remark in pendingDMRemarks { printWrapped(remark, indent: 2, color: .cyan); print("") }
        pendingDMRemarks = []
        for (i, line) in adventureRecapLines().enumerated() {
            printWrapped(line, indent: 2, color: i == 1 ? .yellow : .green)
            print("")
        }
        let onward: () -> Void = onDone ?? { [weak self] in self?.resumePlay() }
        showMenu(["Onward!", "Tell the Progress Tale", "< Back"])
        closeHandler = onward
        menuHandler = { [weak self] choice in
            if choice == 2 { self?.showProgressTale(onBack: onward) } else { onward() }
        }
    }

    private func resumePlay() {
        storyScreenActive = false
        explorationStatusMessage = (welcomeLine(returning: true), .cyan)
        showExplorationView()
    }

    /// The whole adventure in a few lines — the quest and how it's going, any
    /// change of quest, errands, fights, and what happened last.
    func adventureRecapLines() -> [String] {
        guard let dungeon = dungeon else { return [] }
        let names = party.map { shortName(for: $0) }
        let together = names.count <= 1 ? (names.first ?? "A lone adventurer") : names.dropLast().joined(separator: ", ") + " and " + names.last!
        let day = gameTimeMinutes / 1440 + 1
        var lines: [String] = []
        lines.append("\(together) \(names.count <= 1 ? "is" : "are") on day \(day) of the adventure, on Level \(dungeon.level) of \(dungeon.name).")
        if mainQuestCompleted, let mq = mainQuest {
            lines.append("★ The quest is done: \(Dungeon.guardianName(mq.villain)) is defeated, and \(mq.village) is saved.")
        } else if let mq = mainQuest {
            let left = max(0, Dungeon.finalLevel - dungeon.level)
            let foe = mq.kind == "mystery" ? "whoever is behind it" : Dungeon.guardianName(mq.villain)
            lines.append("The quest: to \(mq.goal), \(mq.stakes). " + (left == 0 ? "This is the last level — \(foe) is somewhere here." : "\(left) more level\(left == 1 ? "" : "s") to go before the bottom, where \(foe) waits."))
            if let line = questDeadlineLine() { lines.append(line) }
            let found = mq.beatsSoFar(level: dungeon.level) + (mq.cluesLearned ?? [])
            if !found.isEmpty { lines.append("So far they've found out: " + found.joined(separator: " ")) }
            else if let who = mq.informant { lines.append("They haven't learned much yet — \(who) are the ones to ask.") }
        } else if noMainQuest {
            lines.append("They're travelling without a main quest — just for the adventure, and whatever errands turn up.")
        } else {
            lines.append("No main quest yet.")
        }
        if questHistory.count > 1 { lines.append("Along the way: " + questHistory.joined(separator: " ")) }
        let errands = allQuests
        if !errands.isEmpty { lines.append("Errands in hand: " + errands.map { $0.description }.joined(separator: "; ") + ".") }
        lines.append("They've beaten \(monstersSlain) monster\(monstersSlain == 1 ? "" : "s") in \(combatsWon) fight\(combatsWon == 1 ? "" : "s").")
        lines += levelSummaryLines(includeCurrent: true)
        let recent = progressHighlights(limit: 3)
        if !recent.isEmpty { lines.append("Most recently: " + recent.joined(separator: " ")) }
        return lines
    }

    /// Level by level: rooms explored, the guardian, and anything big found —
    /// earlier levels from the Atlas record, then (optionally) this one.
    func levelSummaryLines(includeCurrent: Bool) -> [String] {
        guard let dungeon = dungeon else { return [] }
        func notable(_ types: [String]) -> String {
            var bits: [String] = []
            for (key, one, many) in [("treasure", "a treasure room", "treasure rooms"), ("shrine", "a shrine", "shrines"),
                                     ("library", "a library", "libraries"), ("shop", "a shop", "shops")] {
                let n = types.filter { $0.lowercased().contains(key) }.count
                if n == 1 { bits.append(one) } else if n > 1 { bits.append("\(n) \(many)") }
            }
            return bits.isEmpty ? "" : "; found " + bits.joined(separator: ", ")
        }
        var lines: [String] = []
        for level in dungeon.archivedLevels {
            let visited = level.rooms.filter { $0.visited }
            let boss = level.rooms.first { $0.typeName.lowercased().contains("boss") }
            let guardian = boss.map { $0.cleared ? "; guardian beaten" : "; slipped past its guardian" } ?? ""
            lines.append("Level \(level.level): explored \(visited.count) of \(level.rooms.count) rooms\(guardian)\(notable(visited.map { $0.typeName })).")
        }
        if includeCurrent {
            let visited = dungeon.rooms.values.filter { $0.visited }
            let bossBeaten = dungeon.rooms.values.contains { $0.roomType == .boss && $0.cleared }
            let prefix = lines.isEmpty ? "On this level (Level \(dungeon.level))" : "Now on Level \(dungeon.level)"
            lines.append("\(prefix): explored \(visited.count) of \(dungeon.rooms.count) rooms so far\(bossBeaten ? "; guardian beaten" : "; its guardian still waits")\(notable(visited.map { $0.roomType.rawValue })).")
        }
        return lines
    }

    /// "☾ The new moon in 4 days" — once someone has told you when it is.
    func questDeadlineLine() -> String? {
        guard let mq = mainQuest, !mainQuestCompleted, mq.deadlineKnown == true,
              let name = mq.deadlineName, let day = mq.deadlineDay else { return nil }
        let cap = name.prefix(1).uppercased() + name.dropFirst()
        if mq.deadlinePassed == true { return "☾ \(cap) has passed — late, but not lost" }
        let left = day - (gameTimeMinutes / 1440 + 1)
        return left <= 0 ? "☾ \(cap) is today!" : "☾ \(cap) in \(left) day\(left == 1 ? "" : "s")"
    }

    /// Time-bound quests get their day; and when it passes, it passes.
    private func checkQuestDeadline() {
        guard var mq = mainQuest, !mainQuestCompleted else { return }
        let today = gameTimeMinutes / 1440 + 1
        if mq.deadlineDay == nil {
            let dated = mq.withDeadline(today: today, level: dungeon?.level ?? 1)
            if dated.deadlineDay != nil { mainQuest = dated; mq = dated }
        }
        guard let day = mq.deadlineDay, today > day, mq.deadlinePassed != true, let name = mq.deadlineName else { return }
        mq.deadlinePassed = true
        mainQuest = mq
        questHistory.append("Too late: \(name) came and went before the quest was done.")
        logEvent("The quest's deadline passed: \(name)", category: "QUEST")
        explorationStatusMessage = ("☾ \(name.prefix(1).uppercased() + name.dropFirst()) has come and gone. What \(mq.village) feared has happened — but it isn't too late to put it right (for half the reward).", .red)
    }

    /// What the DM should know about the quest and the calendar.
    private func dmQuestInfo() -> String? {
        var parts: [String] = ["Today is \(formattedGameTime())."]
        if let mq = mainQuest {
            parts.append("Main quest: to \(mq.goal), \(mq.stakes). Villain: \(mq.villain). Reward: \(mq.reward). Home village: \(mq.village).")
            if let name = mq.deadlineName, let day = mq.deadlineDay {
                let left = day - (gameTimeMinutes / 1440 + 1)
                parts.append(left >= 0
                    ? "Deadline: \(name) falls on day \(day) — \(left) day\(left == 1 ? "" : "s") from now. If the quest isn't done by then, what the village feared happens and the reward is halved, but the quest can still be finished."
                    : "Deadline: \(name) was on day \(day) and has passed. What the village feared has happened; the quest can still be finished, for half the reward.")
            }
            if let place = mq.place { parts.append("The prize is kept in \(place).") }
            if let finale = mq.finale { parts.append("At the end they must \(finale).") }
            if let who = mq.informant { parts.append("Who knows things: \(who).") }
            let found = mq.beatsSoFar(level: dungeon?.level ?? 1) + (mq.cluesLearned ?? [])
            if !found.isEmpty { parts.append("Found out so far: " + found.joined(separator: " ")) }
            if mainQuestCompleted { parts.append("The quest is COMPLETE.") }
        } else if noMainQuest {
            parts.append("The party chose to adventure with no main quest.")
        }
        parts += levelSummaryLines(includeCurrent: true)
        if !questHistory.isEmpty { parts.append("Quest history: " + questHistory.joined(separator: " ")) }
        return parts.joined(separator: "\n")
    }

    /// A few words about the quest and what to do next, for the top of help
    /// pages — worded differently each time, sometimes short, sometimes longer.
    func helpQuestPreamble() -> String? {
        guard let dungeon = dungeon, !party.isEmpty, !storyScreenActive else { return nil }
        let level = dungeon.level
        let left = max(0, Dungeon.finalLevel - level)
        var bits: [String] = []
        if mainQuestCompleted, let mq = mainQuest {
            bits.append(["Your quest is done — \(Dungeon.guardianName(mq.villain)) is beaten.",
                         "The quest is won; anything from here is for the fun of it."].randomElement()!)
        } else if let mq = mainQuest {
            let foe = mq.kind == "mystery" ? "whoever is behind it" : Dungeon.guardianName(mq.villain)
            bits.append([
                "Remember why you're here: to \(mq.goal).",
                "The quest, in case it's slipped your mind: to \(mq.goal), \(mq.stakes).",
                "Level \(level) of \(Dungeon.finalLevel) — and \(foe) waits at the very bottom.",
                "\(mq.village) is counting on you to \(mq.goal).",
                "Still on the trail: \(mq.goal).",
            ].randomElement()!)
            var todo = [
                left > 0 ? "Find this level's guardian (the B on the map) and beat it to go deeper." : "This is the last level: find \(foe) and finish it.",
                "Ask the people you meet about the quest — they know more than they let on.",
                "Keep your torch lit and your packs stocked; it's a long way down.",
            ]
            if let who = mq.informant { todo.append(who.prefix(1).uppercased() + who.dropFirst() + " are the ones to ask.") }
            if let d = questDeadlineLine() { todo.append("Mind the calendar — " + d.replacingOccurrences(of: "☾ ", with: "") + ".") }
            if dungeon.deepPadRoomId != nil { todo.append("Somewhere on this level a pad glows deep blue — a quick way down, if you dare.") }
            bits += todo.shuffled().prefix(Int.random(in: 0...2))
        } else if noMainQuest {
            bits.append(["No main quest — just the adventure. Ask anyone you meet for one if you'd like a purpose.",
                         "You're exploring for the fun of it; people down here will happily hand you a quest if you ask."].randomElement()!)
        } else {
            return nil
        }
        let errands = allQuests.count
        if errands > 0 && Int.random(in: 1...3) == 1 { bits.append("You've \(errands) errand\(errands == 1 ? "" : "s") on the go, too.") }
        return bits.joined(separator: " ")
    }

    /// One line for save lists: the quest and how far along, done (★), or none.
    func questSummaryLine() -> String? {
        if mainQuestCompleted, let mq = mainQuest { return "★ QUEST COMPLETE — \(Dungeon.guardianName(mq.villain)) defeated; \(mq.goal): done" }
        if let mq = mainQuest { return "Quest: to \(mq.goal) · Level \(dungeon?.level ?? 1) of \(Dungeon.finalLevel)" }
        if noMainQuest { return "No main quest — adventuring for the fun of it" }
        return nil
    }

    /// "Welcome, adventurers — welcome to Helheim!" and a word about the place.
    private func welcomeLine(returning: Bool) -> String {
        guard let dungeon = dungeon else { return "" }
        var about = nameEntries.first { $0.category == "dungeon" && $0.name == dungeon.name }?.description ?? ""
        if let dot = about.firstIndex(of: ".") { about = String(about[...dot]) }
        if about.isEmpty {
            about = ["Its halls are older than anyone remembers, and few who know them well have come back to say so.",
                     "They say its stones are warm in winter and cold in summer, which is never a good sign.",
                     "Somewhere below, something is waiting — and it has heard you arrive."].randomElement()!
        }
        return returning ? "Welcome back, adventurers — back to \(dungeon.name). \(about)" : "Welcome, adventurers — welcome to \(dungeon.name)! \(about)"
    }

    private func confirmNewMainQuest() {
        clearTerminal()
        printTitle("By the Campfire")
        print("")
        let names = party.map { shortName(for: $0) }
        let together = names.count <= 1 ? (names.first ?? "You") : names.dropLast().joined(separator: ", ") + " and " + names.last!
        if let mq = mainQuest {
            printWrapped("\(together) sit around a small fire in the dark, a long way from \(mq.village). You swore to \(mq.goal), \(mq.stakes).", indent: 2, color: .green)
            print("")
            printWrapped("Someone asks what nobody wants to: is this still the quest worth risking everything for? Other villages need heroes too.", indent: 2, color: .green)
            print("")
            printWrapped("Hear another plea and you can take it up, turn it down, or try to come back to this one — though a village you walked away from may not want you back.", indent: 2, color: .dimGreen)
            print("")
            printWrapped("Be warned: the dungeon doesn't like oath-breakers. Take up a new quest and its magic may fling you back to the entrance — and things fall out of packs on the way.", indent: 2, color: .yellow)
        } else {
            printWrapped("\(together) sit around a small fire in the dark. No quest of your own — yet. Somebody, somewhere, must need you.", indent: 2, color: .green)
        }
        print("")
        showMenu(mainQuest != nil ? ["Hold to Our Oath", "Hear Another Plea"] : ["Stay As We Are", "Hear a Plea"])
        closeHandler = { [weak self] in self?.showPartyStatus() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            guard choice == 2 else { self.showPartyStatus(); return }
            let old = self.mainQuest
            if let old = old { self.questChangeBackup = (old, self.adventureIntroLines) }
            var next = MainQuest.random()
            for _ in 0..<8 where next.villain == old?.villain || next.kind == old?.kind { next = MainQuest.random() }
            self.questPleaPrevious = old
            self.questPleaAsker = Self.pleaAskers.randomElement()
            self.mainQuest = next
            self.print("")
            self.printWrapped("Before the fire burns down, a bedraggled messenger bird drops out of the dark and lands on \(names.first ?? "your")'s pack, a scrap of parchment tied to its leg. It's from \(next.village).", indent: 2, color: .yellow)
            self.waitForContinue()
            self.inputHandler = { [weak self] _ in
                guard let self = self else { return }
                self.storyScreenActive = true
                self.playAdventureCutscene { [weak self] in
                    self?.askToTakeQuest(then: { [weak self] in self?.storyScreenActive = false; self?.showPartyStatus() })
                }
            }
        }
    }

    func showPartyStatus() {
        clearTerminal()

        // Show map at top
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        printTitle("Party Status")

        // Game time & level
        if let level = dungeon?.level {
            print("  Dungeon Level: \(level)", color: .cyan)
        }
        print("  Time: \(formattedGameTime())", color: .cyan)
        let roomsVisited = dungeon?.rooms.values.filter { $0.visited }.count ?? 0
        let totalRooms = dungeon?.rooms.count ?? 0
        print("  Explored: \(roomsVisited)/\(totalRooms) rooms", color: .cyan)
        let dm = DMEngine.shared
        let aiLabel = dm.isConfigured ? dm.provider.displayName : (dm.isAppleModelAvailable ? "Apple On-Device AI" : "Basic DM (no AI)")
        print("  DM's brain: \(aiLabel)", color: .cyan)
        if partySkillMultiplier > 1.0 {
            let pct = Int(((partySkillMultiplier - 1.0) * 100).rounded())
            print("  Monster strength: +\(pct)% (your party has grown stronger)", color: .yellow)
        }

        // Active quest — the only place besides the offer/completion
        // screens where progress is visible, so a player who accepted a
        // quest and moved on has somewhere to check back in.
        if let mq = mainQuest {
            print("")
            printWrapped("MAIN QUEST: \(mq.summary)", indent: 2, color: .yellow, bold: true)
            for found in mq.beatsSoFar(level: dungeon?.level ?? 1) { printWrapped("· \(found)", indent: 4, color: .dimGreen) }
            for clue in mq.cluesLearned ?? [] { printWrapped("· \(clue)", indent: 4, color: .cyan) }
            if let who = mq.informant { printWrapped("Who might know more: \(who).", indent: 4, color: .dimGreen) }
            if let line = questDeadlineLine() { printWrapped(line, indent: 4, color: .cyan) }
            printWrapped("The one behind it all: \(mq.villain), waiting at the very bottom. Reward: \(mq.reward).", indent: 4, color: .dimGreen)
        }
        for quest in allQuests {
            print("")
            printWrapped("SIDE QUEST from \(quest.giverName): \(quest.description)", indent: 2, color: .cyan, bold: true)
            printWrapped(sideQuestProgressDescription(quest), indent: 4, color: .dimGreen)
        }
        if !allQuests.isEmpty && canTakeAnotherQuest {
            printWrapped("Room for another quest (\(allQuests.count) of \(questCapacity)) — ask the folk you meet.", indent: 4, color: .dimGreen)
        }

        // Torch status
        if torchLit, let holderId = torchHolderId {
            let holderName = party.first(where: { $0.id == holderId }).map { shortName(for: $0) } ?? "?"
            let activeTorch = activeTorchId.flatMap { tid in party.flatMap { $0.inventory }.first(where: { $0.id == tid }) }
            let timeLeft = activeTorch?.torchLifeDescription ?? "?"
            print("  Torch: lit (\(timeLeft) left) — \(holderName)", color: .orange)
        } else {
            let totalTorches = party.flatMap { $0.inventory }.filter { $0.isTorch }.count
            if totalTorches > 0 {
                print("  Torch: unlit (\(totalTorches) available)", color: .dimGreen)
            } else {
                print("  Torch: none", color: .dimGreen)
            }
        }

        // Poison status
        let poisoned = party.filter { $0.isPoisoned }
        if !poisoned.isEmpty {
            let names = poisoned.map { shortName(for: $0) }.joined(separator: ", ")
            print("  ☠ Poisoned: \(names)", color: .magenta)
        }
        print("")

        // Character summary — each character's lines are tappable (their card)
        var characterLineRanges: [Range<Int>] = []
        for (partyIdx, char) in party.enumerated() {
            let characterLineStart = terminalLines.count
            let charIsRemote = pendingRemoteSlots.contains(partyIdx)
            let isLocal = localControlledCharIds.contains(char.id)
            let typeTag: String
            if charIsRemote {
                typeTag = "[Remote] "
            } else if isLocal {
                typeTag = "◀ YOU "
            } else if char.isComputerControlled {
                typeTag = "[Robot] "
            } else {
                typeTag = "[Player] "
            }
            let hpFraction = Double(char.currentHP) / Double(char.maxHP)
            let hpColor: TerminalColor = hpFraction > 0.5 ? .brightGreen : (hpFraction > 0.25 ? .yellow : .red)

            // Line 1: Name + Race/Class + type tag
            let shortClass = String(char.characterClass.rawValue.prefix(3))
            let namePrefix = (char.isComputerControlled && !charIsRemote && !char.name.hasPrefix("R.")) ? "R. " : ""
            printWrapped("\(namePrefix)\(shortName(for: char))  \(char.race.rawValue) \(shortClass) L\(char.level)  \(typeTag)", indent: 2, color: .brightGreen, bold: true)
            printWrapped("✦ \(char.characterClass.rankTitle(atLevel: char.level))", indent: 4, color: .cyan)

            // Line 2: HP bar + AC + Gold
            let barLen = 8
            let filled = Int(hpFraction * Double(barLen))
            let hpBar = String(repeating: "█", count: filled) + String(repeating: "░", count: barLen - filled)
            let wpnStr = char.equippedWeapon.map { "  \(String($0.name.prefix(10)))\(char.equippedWeapon?.broken == true ? " (broken)" : "")" } ?? ""
            printWrapped("[\(hpBar)] \(char.currentHP)/\(char.maxHP) AC\(char.armorClass) \(char.gold)gp\(wpnStr)", indent: 4, color: hpColor)

            // Line 3: XP + progress toward next level
            if char.level >= 5 {
                print("    XP: \(char.experiencePoints) (max level)", color: .dimGreen)
            } else {
                let nextXP = Character.xpForLevel(char.level + 1)
                print("    XP: \(char.experiencePoints)/\(nextXP) to Level \(char.level + 1)", color: .dimGreen)
            }
            characterLineRanges.append(characterLineStart..<terminalLines.count)
        }
        print("")

        // Build menu
        // "Change Brain" (was "AI") — which mind runs the Dungeon Master.
        // Party Review first (the default); Brain now lives in Settings.
        var menuOpts = ["Party Review", "Tale", "Save to Roster", "Lore", "Settings", "Adventure Log", "Quests", "Dungeon", "?", "< Back"]
        if dungeon?.hasCartography == true {
            menuOpts.insert("Atlas", at: menuOpts.firstIndex(of: "Lore") ?? 0)
        }
        let hasPoisoned = party.contains(where: { $0.isPoisoned })
        // Occasional actions go at the end — never the default.
        if hasPoisoned {
            menuOpts.insert("Cure Poison", at: menuOpts.firstIndex(of: "Dungeon") ?? menuOpts.count)
        }
        if activeQuest != nil {
            menuOpts.insert("Give Up Quest", at: menuOpts.firstIndex(of: "Dungeon") ?? menuOpts.count)
        }

        showMenu(menuOpts)

        closeHandler = { [weak self] in
            self?.showExplorationView()
        }

        // Tap a character's lines to open their character card.
        textLongPressHandler = { [weak self] lineIndex in
            guard let idx = characterLineRanges.firstIndex(where: { $0.contains(lineIndex) }) else { return }
            self?.showCharacterCard(index: idx)
        }

        // Long-press Give Up Quest skips the "are you sure?" step.
        menuLongPressHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= menuOpts.count, menuOpts[choice - 1] == "Give Up Quest" else { return }
            self.print("")
            self.abandonActiveQuest(returnTo: { [weak self] in self?.showPartyStatus() })
        }

        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let selected = menuOpts[choice - 1]
            switch selected {
            case "Give Up Quest":
                self.confirmAbandonQuest(returnTo: { self.showPartyStatus() })
            case "Cure Poison":
                self.showPoisonInfo(onBack: { self.showPartyStatus() })
            case "Party Review":
                self.showInGamePartyReview()
            case "Save to Roster":
                self.showSavePartyToRosterMenu()
            case "Adventure Log":
                self.showAdventureLog()
            case "Progress Tale":
                self.showProgressTale(onBack: { [weak self] in self?.showPartyStatus() })
            case "Tale":
                self.showTaleMenu()
            case "Opening Tale":
                self.showOpeningTale(page: 0, onBack: { [weak self] in self?.showPartyStatus() })
            case "Quests":
                self.confirmNewMainQuest()
            case "Atlas":
                self.showAtlas(onBack: { [weak self] in self?.showPartyStatus() })
            case "Lore":
                self.showLoreBook()
            case "Change Brain":
                self.showAIProviderMenu(onBack: { [weak self] in self?.showPartyStatus() })
            case "Settings":
                self.showSettings()
            case "Dungeon":
                self.showExplorationView()
            case "?":
                self.showPartyStatusHelp()
            default:
                self.showExplorationView()
            }
        }
    }

    /// Lets the player pick which party member(s) to save/update in the
    /// Character Roster mid-adventure — e.g. after a level-up — so progress
    /// on that character carries into future parties.
    /// The story of this adventure so far — the same tale Continue Adventure
    /// tells, built from the game exactly as it stands right now.
    private func tellTaleSoFar(onBack: @escaping () -> Void) {
        guard let dungeon = dungeon else { onBack(); return }
        let partyDesc = party.map { "\($0.name) (\($0.characterClass.rawValue))" }.joined(separator: ", ")
        let snapshot = SaveGame(
            id: UUID(), slotId: activeSlotId ?? UUID(), savedAt: Date(), slotName: activeSlotName ?? dungeon.name,
            partyDescription: partyDesc, dungeonName: dungeon.name, dungeonLevel: dungeon.level,
            party: party, dungeon: dungeon, gameState: gameState,
            gameTimeMinutes: gameTimeMinutes, adventureLog: adventureLog,
            dmChatLog: dmChatLog.map { DMChatEntry(isUser: $0.isUser, text: $0.text) }, torchLit: torchLit,
            torchTurnsRemaining: torchTurnsRemaining,
            partyChatLog: partyChatLog.suffix(20).map { $0 },
            monstersSlain: monstersSlain,
            combatsWon: combatsWon,
            activeQuest: activeQuest, otherQuests: otherQuests, introLines: adventureIntroLines, mainQuest: mainQuest, questHistory: questHistory, noMainQuest: noMainQuest, mainQuestCompleted: mainQuestCompleted, questSummary: questSummaryLine()
        )
        showAdventureTale(AdventureTaleData(inProgress: snapshot), onBack: onBack)
    }

    private func showSavePartyToRosterMenu() {
        clearTerminal()
        printTitle("Save to Roster")
        print("  Saving a character here updates their Character Roster entry with their current level, gear, and gold.", color: .dimGreen)
        print("")

        var options = party.map { "\($0.name) — Level \($0.level) \($0.characterClass.rawValue)" }
        options.append("Save Whole Party")

        showMenu(options + ["< Back"])
        closeHandler = { [weak self] in self?.showPartyStatus() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == options.count + 1 {
                self.showPartyStatus()
                return
            }
            self.clearTerminal()
            if choice == options.count {
                for char in self.party { self.saveCharacterToRoster(char, silent: true) }
                self.print("  Whole party saved to the Character Roster.", color: .brightGreen)
            } else {
                self.saveCharacterToRoster(self.party[choice - 1])
            }
            self.print("")
            self.waitForContinue()
            self.inputHandler = { [weak self] _ in self?.showPartyStatus() }
        }
    }

    /// Every named individual (merchants, wandering traders) the party has
    /// actually met so far this adventure — visited rooms only, so nothing
    /// spoils what's still undiscovered. This is also fed to the AI DM (see
    /// buildDMContext's partyStatus/lore section) so a named character it
    /// introduced stays consistent instead of being re-invented differently
    /// later in a long campaign.
    /// Loads the current dungeon's names into NameRegistry before anyone new
    /// is created mid-game — after a load, the registry only knows names
    /// from dungeons generated this session.
    private func seedNameRegistry() {
        guard let dungeon = dungeon else { return }
        var names: [String] = []
        for room in dungeon.rooms.values {
            if let merchant = room.merchant { names.append(merchant.name) }
            if let trainer = room.trainer { names.append(trainer.name) }
            if let npc = room.npc {
                if let personal = npc.personalName { names.append(personal) }
                if let merchant = npc.merchant { names.append(merchant.name) }
            }
        }
        NameRegistry.reset(names)
    }

    /// Same answer every run for the same text (Swift's own hash changes per launch).
    private func stableHash(_ text: String) -> Int {
        text.unicodeScalars.reduce(7) { ($0 &* 31 &+ Int($1.value)) & 0x7fffffff }
    }

    private static let loreLooks = ["wears a leather apron patched a dozen times", "has ink-stained fingers and a pencil behind one ear",
        "keeps a tame rat on one shoulder", "hums sea shanties while counting coins", "wears spectacles far too big for their nose",
        "has a laugh you can hear three rooms away", "never quite looks you in the eye", "keeps every coin in a different pocket",
        "smells faintly of cinnamon and lamp oil", "has a scar they say came from a dragon", "speaks in a whisper, as if the walls listen",
        "wears a hat with a very long feather", "has a beard braided with tiny bells", "is never without a mug of something steaming"]
    private static let loreHabits = ["haggles just for the fun of it", "remembers every customer's name", "gives regulars a free biscuit",
        "writes prices in a secret code", "insists everything is 'barely used'", "trades gossip as eagerly as goods",
        "tests every coin with their teeth", "tells a different story about each item", "counts the stock twice, just in case",
        "polishes whatever is nearest when thinking", "hides the best stock behind the worst"]
    private static let loreRumours = ["They say they once sold a sword to a king.", "Rumour has it the best stock is under the counter.",
        "Folk whisper they came down here to escape a debt.", "Someone swears they saw them chatting with a ghost.",
        "They claim to have mapped half this dungeon.", "Nobody knows how the stock gets down here.",
        "Their grandmother ran a shop in these very halls.", "They keep a list of every monster they've outrun."]

    /// Different for each person and place, even when a name comes round again.
    private func merchantLore(_ merchant: Merchant, room: Room) -> String {
        let seed = stableHash(merchant.name + "|" + room.name)
        return "\(merchant.shopName), \(room.name). \(merchant.personaBlurb) This one \(Self.loreLooks[seed % Self.loreLooks.count]) and \(Self.loreHabits[(seed / 7) % Self.loreHabits.count]). \(Self.loreRumours[(seed / 53) % Self.loreRumours.count]) Favourite saying: \"\(merchant.catchphrase)\""
    }

    private func loreEntries() -> [(name: String, description: String)] {
        guard let dungeon = dungeon else { return [] }
        var entries: [(name: String, description: String)] = []
        for room in dungeon.rooms.values where room.visited {
            if let merchant = room.merchant {
                entries.append((merchant.name, merchantLore(merchant, room: room)))
            }
            if let npc = room.npc, npc.hasBeenTalkedTo {
                if let merchant = npc.merchant {
                    entries.append((merchant.name, merchantLore(merchant, room: room)))
                } else {
                    // A non-merchant NPC has no unique name of their own
                    // (npc.name is just their type, e.g. "Hermit") — so the
                    // one thing worth recording about them is what they're
                    // actually like, not just where you found them.
                    var desc = "\(npc.type.description) Met in \(room.name)."
                    let seed = stableHash(npc.displayName + "|" + room.name)
                    let traits = npc.type.personalityTraits
                    if !traits.isEmpty { desc += " (\(traits[seed % traits.count]).)" }
                    desc += " This one \(Self.loreLooks[(seed / 11) % Self.loreLooks.count])."
                    entries.append((npc.displayName, desc))
                }
            }
        }
        // The same person is only listed once, however they were reached.
        var seen = Set<String>()
        let unique = entries.filter { seen.insert($0.name + "|" + $0.description).inserted }
        return unique.sorted { $0.name < $1.name }
    }

    func showLoreBook() {
        clearTerminal()
        printTitle("Lore")
        print("")
        let entries = loreEntries()
        if entries.isEmpty {
            printWrapped("No named individuals encountered yet — merchants and NPCs you've met will show up here.", indent: 2, color: .dimGreen)
        } else {
            for entry in entries {
                print("  \(entry.name)", color: .brightGreen, bold: true)
                printWrapped(entry.description, indent: 4, color: .dimGreen)
                print("")
            }
        }
        showMenu(["?", "< Back"])
        closeHandler = { [weak self] in self?.showPartyStatus() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.showInlineHelp {
                    self.printTitle("Lore — Help")
                    self.print("")
                    self.printWrapped("A running record of every named merchant or NPC your party has actually met — so you can look someone up if you forget who they were or where you found them.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("The AI DM keeps this list in mind too, so a named character it introduced stays consistent instead of being described differently later on.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else {
                self.showPartyStatus()
            }
        }
    }

