        showInlineHelp {
            self.printTitle("Party Status — Help")
            self.print("")
            self.print("  INFORMATION", color: .cyan, bold: true)
            self.printWrapped("Your main quest sits at the top: what you've found out so far, who might know more, and any deadline. Tap an adventurer's lines to open their character card.", indent: 2, color: .dimGreen)
            self.print("")
            self.printWrapped("Map + each adventurer's HP, gold, XP. Green HP = healthy, yellow = wounded, red = critical. The ✦ line under each name is their rank, which rises with their level — a Bard, say, goes Busker, Minstrel, Troubadour, Skald, Master Bard.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  BUTTONS", color: .cyan, bold: true)
            for (name, what) in [
                ("Party Review", "edit adventurers and see their stat cards"),
                ("Tale", "the Opening Tale (how it began), the Progress Tale (the story so far, told the same way), or a quick summary of the story so far"),
                ("Save to Roster", "keep an adventurer's progress for future adventures"),
                ("Lore", "the named merchants and folk you've met"),
                ("Settings", "game settings — Change Brain (which AI runs the DM), Timeouts, Puzzles and more"),
                ("Adventure Log", "a timeline of everything that's happened"),
                ("Quests", "by the campfire: hold to your quest, or hear another plea — take it up, turn it down, or try to go back (careful: breaking an oath can throw you back to the start)"),
                ("Atlas", "the map of everywhere you've been (once you've found cartography)"),
                ("Cure Poison", "shown when someone is poisoned"),
                ("Give Up Quest", "abandon a quest (progress lost, some gold in goodwill) to make room for another"),
                ("Dungeon", "back to exploring, right where you left off"),
                ("? and < Back", "this help, and back to the dungeon (the ✕ does the same)"),
            ] {
                self.printWrapped("\(name) — \(what)", indent: 2, color: .dimGreen)
            }
            self.print("")
            self.print("  MONSTER STRENGTH", color: .cyan, bold: true)
            self.printWrapped("Monsters scale up a little as your party's average level rises, on top of your chosen difficulty — the dungeon keeps pace with your growing skill instead of staying static.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    /// Shared helper — appends voice/text input explanation to any help screen
    private func printInputHelp() {
        print("  INPUT", color: .cyan, bold: true)
        if voiceMenuEnabled {
            printWrapped("You can tap the microphone icon to speak commands, or tap the text prompt (>) to type. The loudspeaker icon reads the screen aloud.", indent: 2, color: .dimGreen)
        } else {
            printWrapped("Tap the text prompt (>) to type commands. Enable Voice Menus in Settings > Accessibility to use voice input and screen reading.", indent: 2, color: .dimGreen)
            printLink("Settings > Accessibility", to: "accessibility", indent: 4)
        }
        print("")

        print("  NAVIGATION BAR", color: .cyan, bold: true)
        printWrapped("When a menu spans multiple pages, a compact bar appears at the bottom right: [<< | ? | >>]. Tap <</>> to page through options, or ? for context help.", indent: 2, color: .dimGreen)
        print("")
        print("  UNDO / REDO", color: .cyan, bold: true)
        printWrapped("When you make changes (settings, character edits), labelled Undo/Redo buttons appear in the input bar showing what they will revert. Tap to step back or forward through changes. Undo/Redo must be enabled in Settings > Gameplay.", indent: 2, color: .dimGreen)
        printLink("Settings > Gameplay", to: "gameplay", indent: 4)
        print("")
    }

    /// Set up tappable text links in help pages.
    /// `links` maps a substring to an action. When the user taps a terminal line
    /// containing that substring, the action is executed.
    /// Toggle inline help: prepends help text above existing content, swaps ? for ?̸.
    /// Pressing ?̸ restores the original screen. Menu buttons are preserved.
    /// - helpBuilder: closure that prints help text (should NOT call clearTerminal)
    func showInlineHelp(_ helpBuilder: () -> Void) {
        // Only "close help" if the help page is still the screen showing.
        // A help page left some other way (navigating elsewhere) used to
        // leave savedHelpState behind, so the NEXT "?" took this branch —
        // restoring a stale screen instead of opening help, i.e. the tap
        // seemed to do nothing, and only the second press worked.
        if savedHelpState != nil && screenGeneration != helpShownGeneration {
            savedHelpState = nil
        }
        if let saved = savedHelpState {
            // Restore previous state — remove help text, restore original lines and menu.
            // Synchronous, not DispatchQueue.main.async: a tap on an underlined
            // help title calls showInlineHelp({}) to dismiss and THEN immediately
            // (same call stack) invokes the real button's own handler, which
            // prints its own fresh output right away. Deferring this restore to
            // the next run-loop tick meant it landed AFTER that fresh output and
            // silently overwrote it with the stale pre-help screen — the tap
            // visibly did nothing, even though the button's action genuinely ran.
            self.terminalLines = saved.lines
            self.currentMenuOptions = saved.menu
            self.pinnedMapLines = saved.pinnedMapLines
            self.menuHandler = saved.menuHandler
            self.closeHandler = saved.closeHandler
            self.menuLongPressHandler = saved.menuLongPressHandler
            self.textLongPressHandler = saved.textLongPressHandler
            self.undoHandler = saved.undoHandler
            self.redoHandler = saved.redoHandler
            self.undoLabel = saved.undoLabel
            self.redoLabel = saved.redoLabel
            self.savedHelpState = nil
        } else {
            // Save current state
            let savedLines = terminalLines
            let savedMenu = currentMenuOptions
            let savedMenuHandler = menuHandler
            let savedCloseHandler = closeHandler
            let savedMenuLongPress = menuLongPressHandler
            let savedTextLongPress = textLongPressHandler
            let savedUndo = undoHandler
            let savedRedo = redoHandler
            let savedUndoLabel = undoLabel
            let savedRedoLabel = redoLabel

            helpShownGeneration = screenGeneration
            savedHelpState = (
                savedLines, savedMenu,
                savedMenuHandler, savedCloseHandler,
                savedMenuLongPress, savedTextLongPress,
                savedUndo, savedRedo,
                savedUndoLabel, savedRedoLabel,
                pinnedMapLines
            )

            // Build help text into a fresh line array
            terminalLines.removeAll()
            // A pinned map above the text would otherwise squeeze a long help
            // page's scrollable area — help never needs the map, so clear it
            // for the duration (restored above on close). Also make sure a
            // stale scrollLocked from whatever screen was showing doesn't
            // carry over and leave a genuinely long help page unscrollable.
            pinnedMapLines = []
            scrollLocked = false
            suppressAutoScroll = true
            // A quest already accepted is easy to forget about mid-adventure
            // — show a reminder of it and its progress before every screen's
            // own help content, rather than only on Party Status.
            for quest in allQuests {
                print("  SIDE QUEST from \(quest.giverName): \(quest.description)", color: .cyan, bold: true)
                print("  \(sideQuestProgressDescription(quest))", color: .dimGreen)
                print("")
            }
            helpBuilder()
            printInputHelp()
            let helpLines = terminalLines

            // Replace screen content with help text only (original saved for restore)
            // Match help section titles to menu buttons — make them tappable
            var helpLineActions: [Int: Int] = [:]  // helpLine index → menu choice (1-based)
            for (lineIdx, line) in helpLines.enumerated() {
                guard line.isBold else { continue }
                let title = line.text.trimmingCharacters(in: .whitespaces).lowercased()
                guard !title.isEmpty else { continue }
                for (optIdx, opt) in savedMenu.enumerated() {
                    let optText = opt.text.lowercased()
                    guard !optText.isEmpty && optText != "?" && optText != "?\u{0338}" else { continue }
                    if title == optText || title.contains(optText) || optText.contains(title) {
                        helpLineActions[lineIdx] = optIdx + 1  // 1-based choice
                        break
                    }
                }
            }

            // Underline tappable help titles
            var linkedHelpLines = helpLines
            for lineIdx in helpLineActions.keys {
                var line = linkedHelpLines[lineIdx]
                line = TerminalLine(line.text, color: line.color, bold: line.isBold, underlined: true, size: line.fontSize, centered: line.isCentered)
                linkedHelpLines[lineIdx] = line
            }
            terminalLines = linkedHelpLines

            // Swap ? for ?̸ in the existing menu, keep all other buttons
            let updatedMenu = savedMenu.map { opt -> MenuOption in
                if opt.text == "?" {
                    var swapped = MenuOption("?\u{0338}", isDefault: opt.isDefault, tint: opt.tint, compact: opt.isCompactNav)
                    swapped.sourceIndex = opt.sourceIndex
                    return swapped
                }
                return opt
            }
            currentMenuOptions = updatedMenu

            // Wire ?̸ to toggle back, pass through all other choices
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                let idx = choice - 1
                if idx >= 0 && idx < updatedMenu.count && updatedMenu[idx].text == "?\u{0338}" {
                    self.showInlineHelp({})
                } else {
                    savedMenuHandler?(choice)
                }
            }
            closeHandler = savedCloseHandler
            menuLongPressHandler = savedMenuLongPress
            // Wire tappable help titles — tap dismisses help and triggers the button
            if !helpLineActions.isEmpty {
                textLongPressHandler = { [weak self] lineIndex in
                    guard let self = self else { return }
                    if let menuChoice = helpLineActions[lineIndex] {
                        // Dismiss help first, then trigger the button
                        self.showInlineHelp({})
                        savedMenuHandler?(menuChoice)
                    }
                }
            } else {
                textLongPressHandler = savedTextLongPress
            }
            undoHandler = savedUndo
            redoHandler = savedRedo
            undoLabel = savedUndoLabel
            redoLabel = savedRedoLabel
        }
    }

    private func setupHelpLinks(_ links: [(text: String, action: () -> Void)]) {
        DispatchQueue.main.async { [weak self] in
            guard let self = self else { return }
            let lines = self.terminalLines
            // Build a map: line index → action (first matching link wins)
            var lineActions: [Int: () -> Void] = [:]
            for (i, line) in lines.enumerated() {
                for link in links {
                    if line.text.contains(link.text) {
                        let action = link.action
                        lineActions[i] = { [weak self] in
                            guard let self = self else { return }
                            if self.linkReturnSnapshot == nil { self.linkReturnSnapshot = self.captureScreenSnapshot() }
                            action()
                        }
                        break
                    }
                }
            }
            guard !lineActions.isEmpty else { return }
            self.textLongPressHandler = { lineIndex in
                lineActions[lineIndex]?()
            }
        }
    }

    /// Show a character card, browseable via swipe L/R
    private func showCharacterCard(index: Int) {
        cancelPartyStatusAnim()
        guard !party.isEmpty else { showPartyStatus(); return }
        let idx = max(0, min(index, party.count - 1))
        let char = party[idx]

        clearTerminal()

        let cardW = 27
        let border = String(repeating: "─", count: cardW)

        // Card position indicator
        if party.count > 1 {
            print("  \(idx + 1) of \(party.count) — swipe to browse", color: .dimGreen)
            print("")
        }

        // Top border
        print("  ╔\(border)╗", color: .cyan)

        // Name
        let nameLines = cardWrapText(char.name, width: cardW)
        for line in nameLines {
            let pad = max(0, cardW - line.count)
            let l = pad / 2; let r = pad - l
            print("  ║\(String(repeating: " ", count: l))\(line)\(String(repeating: " ", count: r))║", color: .brightGreen, bold: true)
        }

        // Class & Race
        let subtitle = "\(char.race.rawValue) \(char.characterClass.rawValue) L\(char.level)"
        let subDisplay = subtitle.count > cardW ? String(subtitle.prefix(cardW)) : subtitle
        let sPad = max(0, cardW - subDisplay.count)
        let sL = sPad / 2; let sR = sPad - sL
        print("  ║\(String(repeating: " ", count: sL))\(subDisplay)\(String(repeating: " ", count: sR))║", color: .yellow)

        print("  ╠\(border)╣", color: .cyan)

        // ASCII art
        for line in char.characterClass.asciiArt {
            let trimmed = line.count > 25 ? String(line.prefix(25)) : line
            let artPad = max(0, cardW - trimmed.count)
            let aL = artPad / 2; let aR = artPad - aL
            print("  ║\(String(repeating: " ", count: aL))\(trimmed)\(String(repeating: " ", count: aR))║", color: .green)
        }

        print("  ╠\(border)╣", color: .cyan)

        // Stats
        func statBar(_ label: String, _ val: Int) -> String {
            let scaled = max(1, min(10, val / 2))
            let bar = String(repeating: "█", count: scaled) + String(repeating: "░", count: 10 - scaled)
            let lbl = " \(label)".padding(toLength: 8, withPad: " ", startingAt: 0)
            let vStr = "\(val)".padding(toLength: 3, withPad: " ", startingAt: 0)
            return String("\(lbl)\(bar) \(vStr)".prefix(cardW))
        }
        let scores = char.abilityScores
        let stats = [("STR", scores.strength), ("DEX", scores.dexterity), ("CON", scores.constitution),
                     ("INT", scores.intelligence), ("WIS", scores.wisdom), ("CHA", scores.charisma)]
        for (label, val) in stats {
            let line = statBar(label, val)
            let lPad = max(0, cardW - line.count)
            print("  ║\(line)\(String(repeating: " ", count: lPad))║", color: .yellow)
        }

        // HP bar
        let hpPct = char.maxHP > 0 ? (char.currentHP * 10 / char.maxHP) : 0
        let hpBar = String(repeating: "█", count: hpPct) + String(repeating: "░", count: 10 - hpPct)
        let hpText = " HP".padding(toLength: 8, withPad: " ", startingAt: 0)
        let hpVal = "\(char.currentHP)/\(char.maxHP)".padding(toLength: 3, withPad: " ", startingAt: 0)
        let hpFull = String("\(hpText)\(hpBar) \(hpVal)".prefix(cardW))
        let hPad = max(0, cardW - hpFull.count)
        let hpColor: TerminalColor = char.currentHP <= char.maxHP / 3 ? .red : .yellow
        print("  ║\(hpFull)\(String(repeating: " ", count: hPad))║", color: hpColor)

        // Bottom border
        print("  ╚\(border)╝", color: .cyan)
        print("")

        // Equipment details
        var details: [String] = []
        if let weapon = char.equippedWeapon { details.append("Weapon: \(weapon.name)") }
        if let armour = char.equippedArmor { details.append("Armour: \(armour.name)") }
        if let shield = char.equippedShield { details.append("Shield: \(shield.name)") }
        details.append("AC: \(char.armorClass)  Gold: \(char.gold)  XP: \(char.experiencePoints)")
        if char.isPoisoned { details.append("☠ POISONED") }
        for detail in details {
            printWrapped(detail, indent: 2, color: .dimGreen)
        }

        // Name Lore match
        let heroes = nameEntries.filter { $0.category == "hero" }
        let cleanName = char.name.lowercased().hasPrefix("r. ") ? String(char.name.lowercased().dropFirst(3)) : char.name.lowercased()
        if heroes.contains(where: { cleanName.contains($0.name.lowercased()) || $0.name.lowercased().contains(cleanName) }) {
            print("")
            printWrapped("This character matches a hero in Name Lore!", indent: 2, color: .cyan)
        }

        // Swipe navigation — circular
        swipeLeftHandler = party.count > 1 ? { [weak self] in
            guard let self = self else { return }
            let next = (idx + 1) % self.party.count
            self.showCharacterCard(index: next)
        } : nil
        swipeRightHandler = party.count > 1 ? { [weak self] in
            guard let self = self else { return }
            let prev = (idx - 1 + self.party.count) % self.party.count
            self.showCharacterCard(index: prev)
        } : nil

        // This card was swipe/close-icon only — no visible "?"/"< Back",
        // so the only ways to navigate it were undiscoverable gestures.
        showMenuOptions([MenuOption("?", tint: .navigation, compact: true), MenuOption("< Back", tint: .navigation, compact: true)])
        closeHandler = { [weak self] in
            self?.swipeLeftHandler = nil
            self?.swipeRightHandler = nil
            self?.showPartyStatus()
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.showInlineHelp {
                    self.printTitle("Character Card — Help")
                    self.print("")
                    self.printWrapped("A quick-glance stat card. Swipe left/right (or use <</>> if shown) to browse the rest of the party.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("For the full detail view — where you can also edit this character — see Party Status > Party Review instead.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            } else {
                self.swipeLeftHandler = nil
                self.swipeRightHandler = nil
                self.showPartyStatus()
            }
        }
    }

    private func showCardForCharacter(named charName: String) {
        guard let idx = party.firstIndex(where: { $0.name == charName }) else { return }
        showCharacterCard(index: idx)
    }

    /// Show character card from edit screen — swipe L/R to browse, close returns to edit
    private func showCharacterCardFromEdit(index: Int, inGame: Bool = false) {
        guard !party.isEmpty else { return }
        let idx = max(0, min(index, party.count - 1))
        let char = party[idx]

        clearTerminal()

        let cardW = 27
        let border = String(repeating: "─", count: cardW)

        if party.count > 1 {
            cardPositionLabel = "\(idx + 1)/\(party.count)"
        }

        // Top border
        print("  ╔\(border)╗", color: .cyan)

        // Name
        let nameLines = cardWrapText(char.name, width: cardW)
        for line in nameLines {
            let pad = max(0, cardW - line.count)
            let l = pad / 2; let r = pad - l
            print("  ║\(String(repeating: " ", count: l))\(line)\(String(repeating: " ", count: r))║", color: .brightGreen, bold: true)
        }

        // Class & Race
        let subtitle = "\(char.race.rawValue) \(char.characterClass.rawValue) L\(char.level)"
        let subDisplay = subtitle.count > cardW ? String(subtitle.prefix(cardW)) : subtitle
        let sPad = max(0, cardW - subDisplay.count)
        let sL = sPad / 2; let sR = sPad - sL
        print("  ║\(String(repeating: " ", count: sL))\(subDisplay)\(String(repeating: " ", count: sR))║", color: .yellow)

        print("  ╠\(border)╣", color: .cyan)

        // ASCII art
        for line in char.characterClass.asciiArt {
            let trimmed = line.count > 25 ? String(line.prefix(25)) : line
            let artPad = max(0, cardW - trimmed.count)
            let aL = artPad / 2; let aR = artPad - aL
            print("  ║\(String(repeating: " ", count: aL))\(trimmed)\(String(repeating: " ", count: aR))║", color: .green)
        }

        print("  ╠\(border)╣", color: .cyan)

        // Stats
        func statBar(_ label: String, _ val: Int) -> String {
            let scaled = max(1, min(10, val / 2))
            let bar = String(repeating: "█", count: scaled) + String(repeating: "░", count: 10 - scaled)
            let lbl = " \(label)".padding(toLength: 8, withPad: " ", startingAt: 0)
            let vStr = "\(val)".padding(toLength: 3, withPad: " ", startingAt: 0)
            return String("\(lbl)\(bar) \(vStr)".prefix(cardW))
        }
        let scores = char.abilityScores
        let stats = [("STR", scores.strength), ("DEX", scores.dexterity), ("CON", scores.constitution),
                     ("INT", scores.intelligence), ("WIS", scores.wisdom), ("CHA", scores.charisma)]
        for (label, val) in stats {
            let line = statBar(label, val)
            let lPad = max(0, cardW - line.count)
            print("  ║\(line)\(String(repeating: " ", count: lPad))║", color: .yellow)
        }

        // HP bar
        let hpPct = char.maxHP > 0 ? (char.currentHP * 10 / char.maxHP) : 0
        let hpBar = String(repeating: "█", count: hpPct) + String(repeating: "░", count: 10 - hpPct)
        let hpText = " HP".padding(toLength: 8, withPad: " ", startingAt: 0)
        let hpVal = "\(char.currentHP)/\(char.maxHP)".padding(toLength: 3, withPad: " ", startingAt: 0)
        let hpFull = String("\(hpText)\(hpBar) \(hpVal)".prefix(cardW))
        let hPad = max(0, cardW - hpFull.count)
        let hpColor: TerminalColor = char.currentHP <= char.maxHP / 3 ? .red : .yellow
        print("  ║\(hpFull)\(String(repeating: " ", count: hPad))║", color: hpColor)

        // Bottom border
        print("  ╚\(border)╝", color: .cyan)
        print("")

        // Equipment details
        var details: [String] = []
        if let weapon = char.equippedWeapon { details.append("Weapon: \(weapon.name)") }
        if let armour = char.equippedArmor { details.append("Armour: \(armour.name)") }
        if let shield = char.equippedShield { details.append("Shield: \(shield.name)") }
        details.append("AC: \(char.armorClass)  Gold: \(char.gold)  XP: \(char.experiencePoints)")
        if char.isPoisoned { details.append("☠ POISONED") }
        for detail in details {
            printWrapped(detail, indent: 2, color: .dimGreen)
        }

        // Swipe navigation — circular
        swipeLeftHandler = party.count > 1 ? { [weak self] in
            guard let self = self else { return }
            let next = (idx + 1) % self.party.count
            self.showCharacterCardFromEdit(index: next, inGame: inGame)
        } : nil
        swipeRightHandler = party.count > 1 ? { [weak self] in
            guard let self = self else { return }
            let prev = (idx - 1 + self.party.count) % self.party.count
            self.showCharacterCardFromEdit(index: prev, inGame: inGame)
        } : nil

        closeHandler = { [weak self] in
            self?.swipeLeftHandler = nil
            self?.swipeRightHandler = nil
            self?.cardPositionLabel = nil
            if inGame {
                self?.showInGameEditCharacter(index: idx)
            } else {
                self?.showEditCharacter(index: idx)
            }
        }
    }

    /// In-game party review — edit names, types, race, class — returns to Party Status
    private func showInGamePartyReview() {
        clearTerminal()
        printTitle("Party Review")

        for (i, char) in party.enumerated() {
            let tag: String
            if char.isComputerControlled {
                tag = " [Auto]"
            } else {
                tag = " [You]"
            }
            printWrapped("\(i + 1). \(char.name)\(tag) — \(char.race.rawValue) \(char.characterClass.rawValue)", indent: 2, color: .brightGreen)
            print("     HP:\(char.currentHP)/\(char.maxHP) AC:\(char.armorClass) \(char.characterClass.primaryAbility.abbreviation):\(char.abilityScores.score(for: char.characterClass.primaryAbility))", color: .dimGreen)
        }
        print("")

        var menuOpts: [MenuOption] = []
        var actions: [() -> Void] = []

        for (i, char) in party.enumerated() {
            let shortN = shortName(for: char)
            menuOpts.append(MenuOption(shortN, isDefault: i == 0))
            actions.append { [weak self] in
                self?.showInGameEditCharacter(index: i)
            }
        }

        // Rest button (long-press = fast long rest) — tinted apart from the
        // character buttons above so it reads as an action, not another
        // party member to tap into.
        let restIdx = menuOpts.count
        menuOpts.append(MenuOption("Rest", tint: .amber))
        actions.append { [weak self] in self?.rest() }

        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        actions.append { [weak self] in self?.showPartyReviewHelp() }

        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        actions.append { [weak self] in
            guard let self = self else { return }
            // Enforce at least one local (human) player
            if !self.party.contains(where: { !$0.isComputerControlled }) {
                self.print("")
                self.print("  At least one character must be Local (You)!", color: .red)
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                    self.showInGamePartyReview()
                }
                return
            }
            self.showPartyStatus()
        }

        showMenuOptions(menuOpts)

        closeHandler = { [weak self] in
            guard let self = self else { return }
            // Enforce at least one local (human) player
            if !self.party.contains(where: { !$0.isComputerControlled }) {
                self.print("")
                self.print("  At least one character must be Local (You)!", color: .red)
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                    self.showInGamePartyReview()
                }
                return
            }
            self.showPartyStatus()
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == restIdx + 1 {
                self.performRest(isLongRest: true, fast: true)
            }
        }
    }

    /// Edit a character mid-game — change name, type, race, class
    private func showInGameEditCharacter(index: Int) {
        guard index < party.count else { showInGamePartyReview(); return }
        let char = party[index]
        clearTerminal()

        // Start edit tracking if not already tracking this character
        if editingCharacterIndex != index {
            beginEditTracking(index: index)
        }

        printTitle("Edit — \(char.name)")

        printLines(char.characterClass.asciiArt, color: .cyan)
        print("")
        let typeStr = char.isComputerControlled ? "Auto (Robot)" : "Local (You)"
        print("  Type:  \(typeStr)", color: .yellow)
        print("  Race:  \(char.race.rawValue)", color: .green)
        print("  Class: \(char.characterClass.rawValue)", color: .green)
        print("  HP:    \(char.currentHP)/\(char.maxHP)  AC:\(char.armorClass)", color: .dimGreen)
        print("")

        var opts: [String] = []
        var actions: [() -> Void] = []

        opts.append("Change Name")
        actions.append { [weak self] in
            self?.showInGameChangeName(index: index)
        }

        opts.append("Change Type")
        actions.append { [weak self] in
            self?.showInGameChangeType(index: index)
        }

        opts.append("Change Class")
        actions.append { [weak self] in
            self?.showRetrainClass(index: index)
        }

        opts.append("Change Voice")
        actions.append { [weak self] in
            self?.showCharacterVoiceEdit(index: index)
        }

        opts.append("View Card")
        actions.append { [weak self] in
            self?.showCharacterCardFromEdit(index: index, inGame: true)
        }

        opts.append("Inventory")
        actions.append { [weak self] in
            self?.showPackMenu(character: char, onBack: { self?.showInGameEditCharacter(index: index) })
        }

        opts.append("?")
        actions.append { [weak self] in
            self?.showInGameEditHelp(index: index)
        }

        opts.append("< Back")
        actions.append { [weak self] in
            self?.endEditTracking()
            self?.showInGamePartyReview()
        }

        showMenu(opts)

        // Restore undo/redo handlers after showMenu (which clears awaitingTextInput)
        updateUndoRedoHandlers(index: index)

        closeHandler = { [weak self] in
            self?.endEditTracking()
            self?.showInGamePartyReview()
        }
        menuHandler = { choice in
            if choice > 0 && choice <= actions.count {
                actions[choice - 1]()
            }
        }
    }

