    // MARK: - Social Mobility (Class Change)

    /// Social tier for each class — lower = humbler origins
    private func socialTier(for cls: CharacterClass) -> Int {
        switch cls {
        case .barbarian: return 1  // tribal outsider
        case .fighter:   return 2  // common soldier
        case .ranger:    return 3  // woodsman
        case .scout:     return 3  // woodsman-adjacent
        case .thief:     return 3  // street-smart, rougher edges than Rogue
        case .rogue:     return 4  // street-smart
        case .cleric:    return 5  // educated clergy
        case .engineer:  return 5  // trained craftsman-scholar
        case .wizard:    return 6  // scholarly elite
        case .bard:      return 4  // travelling performer
        }
    }

    /// Change class mid-game — moving down the social ladder boosts you, moving up stretches you thinner
    private func showRetrainClass(index: Int) {
        guard index < party.count else { showInGameEditCharacter(index: index); return }
        let char = party[index]
        let oldClass = char.characterClass
        let oldLevel = char.level

        clearTerminal()
        printTitle("New Class — \(char.name)")
        print("  Current: \(oldClass.rawValue) Level \(oldLevel)", color: .yellow)
        print("")
        printWrapped("Tap a class to change. Long-press to preview what would happen.", indent: 2, color: .dimGreen)
        print("")

        let classes = CharacterClass.allCases.filter { $0 != oldClass }
        var opts = classes.map { $0.rawValue }
        opts.append("?")
        opts.append("< Back")
        showMenu(opts)

        closeHandler = { [weak self] in self?.showInGameEditCharacter(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == opts.count {
                self.showInGameEditCharacter(index: index)
                return
            }
            if choice == opts.count - 1 {
                self.showRetrainHelp(index: index)
                return
            }
            guard choice >= 1 && choice <= classes.count else { return }
            let newClass = classes[choice - 1]
            self.performRetrain(index: index, newClass: newClass)
        }
        // Long-press to preview retrain outcome
        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            guard choice >= 1 && choice <= classes.count else { return }
            let newClass = classes[choice - 1]
            self.previewRetrain(index: index, newClass: newClass)
        }
    }

    /// Preview what changing class would do, without applying changes
    private func previewRetrain(index: Int, newClass: CharacterClass) {
        guard index < party.count else { return }
        let char = party[index]
        let oldClass = char.characterClass
        let oldLevel = char.level

        // Social mobility calculation
        let oldTier = socialTier(for: oldClass)
        let newTier = socialTier(for: newClass)
        let tierDiff = oldTier - newTier // positive = moving down (boost), negative = moving up (stretch)

        // Calculate skill overlap
        let oldSkills = Set(oldClass.skillChoices)
        let newSkills = Set(newClass.skillChoices)
        let overlap = oldSkills.intersection(newSkills)
        let overlapCount = overlap.count

        // Estimate new level range
        var minLevel = 1
        if overlapCount >= 5 { minLevel += 2 }
        else if overlapCount >= 3 { minLevel += 1 }
        minLevel += (oldLevel - 1) / 2
        // Social mobility adjustment
        minLevel += tierDiff
        minLevel = max(1, minLevel)
        let maxLevel = min(minLevel + 1, oldLevel + max(0, tierDiff)) // +1 from lucky d4

        clearTerminal()
        printTitle("Preview — \(newClass.rawValue)")
        printLines(newClass.asciiArt, color: .cyan)
        print("")

        print("  \(oldClass.rawValue) L\(oldLevel) → \(newClass.rawValue) L\(minLevel)\(maxLevel > minLevel ? "-\(maxLevel)" : "")", color: .yellow, bold: true)
        print("")

        // Social mobility direction
        print("  SOCIAL MOBILITY", color: .cyan, bold: true)
        if tierDiff > 0 {
            printWrapped("Moving down the social ladder — your street smarts give you an edge. Level bonus: +\(tierDiff)", indent: 2, color: .brightGreen)
        } else if tierDiff < 0 {
            printWrapped("Moving up the social ladder — you'll need to learn new ways. Level adjustment: \(tierDiff)", indent: 2, color: .yellow)
        } else {
            printWrapped("Lateral move — similar social standing.", indent: 2, color: .dimGreen)
        }
        print("")

        // Skill overlap detail
        print("  SKILL OVERLAP: \(overlapCount)", color: .cyan, bold: true)
        if overlap.isEmpty {
            printWrapped("No shared skills — level bonus from overlap: +0", indent: 2, color: .dimGreen)
        } else {
            let sharedNames = overlap.map { $0.rawValue }.sorted().joined(separator: ", ")
            printWrapped("Shared: \(sharedNames)", indent: 2, color: .green)
            let bonus = overlapCount >= 5 ? 2 : (overlapCount >= 3 ? 1 : 0)
            printWrapped("Level bonus from overlap: +\(bonus)", indent: 2, color: .dimGreen)
        }
        print("")

        // What changes
        print("  WHAT CHANGES", color: .cyan, bold: true)
        printWrapped("New ability priorities, starting equipment, skills, and spells for \(newClass.rawValue). Old gear is lost.", indent: 2, color: .dimGreen)
        print("")

        // Primary ability
        print("  Primary: \(newClass.primaryAbility.rawValue)  Hit Die: d\(newClass.hitDie)", color: .green)
        print("")

        closeHandler = { [weak self] in self?.showRetrainClass(index: index) }
        waitForContinue()
        inputHandler = { [weak self] _ in self?.showRetrainClass(index: index) }
    }

    private func performRetrain(index: Int, newClass: CharacterClass) {
        guard index < party.count else { return }
        pushEditSnapshot(index: index)
        let char = party[index]
        let oldClass = char.characterClass
        let oldLevel = char.level
        let oldClassName = oldClass.rawValue

        // Calculate skill overlap between old and new class
        let oldSkills = Set(oldClass.skillChoices)
        let newSkills = Set(newClass.skillChoices)
        let overlap = oldSkills.intersection(newSkills).count

        // Social mobility calculation
        let oldTier = socialTier(for: oldClass)
        let newTier = socialTier(for: newClass)
        let tierDiff = oldTier - newTier // positive = moving down (boost), negative = moving up (stretch)

        // Calculate new level
        var newLevel = 1
        // Skill overlap bonus
        if overlap >= 5 { newLevel += 2 }
        else if overlap >= 3 { newLevel += 1 }
        // Current level bonus
        newLevel += (oldLevel - 1) / 2
        // Social mobility adjustment
        newLevel += tierDiff
        // Lucky roll bonus
        if Dice.d4() == 4 { newLevel += 1 }
        // Floor at 1 (can exceed old level when moving down)
        newLevel = max(1, newLevel)

        // Apply the class change
        char.characterClass = newClass
        char.level = newLevel

        // Re-prioritise ability scores
        let sorted = AbilityScores.standardArray.sorted(by: >)
        for (ability, bonus) in char.race.abilityBonuses {
            let current = char.abilityScores.score(for: ability)
            char.abilityScores.set(ability, to: current - bonus)
        }
        for (idx, ability) in newClass.abilityPriority.enumerated() {
            char.abilityScores.set(ability, to: sorted[idx])
        }
        for (ability, bonus) in char.race.abilityBonuses {
            let current = char.abilityScores.score(for: ability)
            char.abilityScores.set(ability, to: current + bonus)
        }

        // Recalculate HP for level 1, then add level-up HP gains
        let conMod = char.abilityScores.modifier(for: .constitution)
        let baseHP = newClass.startingHP + conMod
        var totalHP = max(1, baseHP)
        for _ in 2...max(2, newLevel) {
            if newLevel >= 2 {
                let hpRoll = Dice.rollSum(1, d: newClass.hitDie)
                totalHP += max(1, hpRoll + conMod)
            }
        }
        if newLevel < 2 { totalHP = max(1, baseHP) }
        char.maxHP = totalHP
        char.currentHP = min(char.currentHP, char.maxHP)

        // Update skills
        char.skillProficiencies.removeAll()
        let skills = Array(newClass.skillChoices.shuffled().prefix(newClass.numSkillChoices))
        for skill in skills { char.skillProficiencies.insert(skill) }

        // Update equipment
        char.inventory.removeAll()
        char.equippedWeapon = nil
        char.equippedArmor = nil
        char.equippedShield = nil
        let equipOptions = ItemCatalog.startingEquipmentOptions(for: newClass)
        if let (_, items) = equipOptions.first {
            for item in items { _ = char.addItem(item) }
        }
        autoEquip(char)

        // Update spells
        char.knownSpells = SpellCatalog.startingSpells(for: newClass)
        char.spellSlots = SpellCatalog.startingSlots(for: newClass, level: newLevel)

        // Set XP to match new level
        char.experiencePoints = Character.xpForLevel(newLevel)

        // Barbarian rage
        if newClass == .barbarian {
            char.rageUsesRemaining = char.rageMaxUses
        }

        // Show results
        clearTerminal()
        printTitle("Class Changed!")
        printLines(newClass.asciiArt, color: .cyan)
        print("")
        print("  \(char.name) changed from \(oldClassName) to \(newClass.rawValue)!", color: .brightGreen, bold: true)
        print("")
        if newLevel > oldLevel {
            print("  Level: \(oldLevel) → \(newLevel) (street smarts!)", color: .brightGreen)
        } else if newLevel < oldLevel {
            print("  Level: \(oldLevel) → \(newLevel) (learning the ropes)", color: .yellow)
        } else {
            print("  Level: \(newLevel) (preserved)", color: .brightGreen)
        }
        if tierDiff > 0 {
            print("  Social mobility: moved down — gained experience", color: .dimGreen)
        } else if tierDiff < 0 {
            print("  Social mobility: moved up — stretched thinner", color: .dimGreen)
        }
        if overlap > 0 {
            print("  Skill overlap: \(overlap) shared skills helped", color: .dimGreen)
        }
        print("  HP: \(char.currentHP)/\(char.maxHP)  AC: \(char.armorClass)", color: .green)
        print("")

        logEvent("\(char.name) changed class from \(oldClassName) L\(oldLevel) to \(newClass.rawValue) L\(newLevel)", category: "PARTY")
        logMultiplayerAction("\(char.name) changed class to \(newClass.rawValue) L\(newLevel)")

        waitForContinue()
        inputHandler = { [weak self] _ in
            self?.showInGameEditCharacter(index: index)
        }
    }

    private func showRetrainHelp(index: Int) {
        showInlineHelp {
            self.printTitle("Class Change Help")
            self.print("")
            self.print("  SOCIAL MOBILITY", color: .cyan, bold: true)
            self.printWrapped("Change your class mid-adventure. Social standing affects the transition: dropping down the social ladder (e.g. Wizard to Fighter) means your worldly experience gives you an edge — you may gain levels. Climbing up (e.g. Barbarian to Wizard) means stretching what you know over unfamiliar ground — you may lose levels.", indent: 2, color: .green)
            self.print("")
            self.print("  CLASS HIERARCHY", color: .cyan, bold: true)
            self.printWrapped("From humble to elite: Barbarian → Fighter → Ranger → Rogue → Cleric → Wizard", indent: 2, color: .green)
            self.print("")
            self.print("  LEVEL CALCULATION", color: .cyan, bold: true)
            self.printWrapped("Your new level is based on:", indent: 2, color: .green)
            self.printWrapped("• Social direction (down = bonus, up = penalty)", indent: 4, color: .dimGreen)
            self.printWrapped("• Shared skills between old and new class", indent: 4, color: .dimGreen)
            self.printWrapped("• Your current level (higher = more carries over)", indent: 4, color: .dimGreen)
            self.printWrapped("• A touch of luck (small random bonus)", indent: 4, color: .dimGreen)
            self.printWrapped("Tap a class to change; long-press to preview first.", indent: 2, color: .dimGreen)
            self.print("")
            self.print("  WHAT CHANGES", color: .cyan, bold: true)
            self.printWrapped("Abilities are re-prioritised for your new class. You get new starting equipment, skills, and spells. Your old gear is lost — visit a shop to re-equip.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    /// Change character name mid-game
    private func showInGameChangeName(index: Int) {
        guard index < party.count else { showInGamePartyReview(); return }
        let char = party[index]
        clearTerminal()
        printTitle("Change Name — \(shortName(for: char))")

        print("  Current: \(char.name)", color: .yellow)
        print("")

        // Show suggestions as buttons
        let existingNames = Set(party.map { $0.name.lowercased() })
        let available = suggestedNames.filter { !existingNames.contains($0.lowercased()) }
        let suggestionList = Array(available.shuffled().prefix(4))

        print("  Type a name, or pick a suggestion:", color: .dimGreen)
        print("")

        var menuOpts = suggestionList.map { String($0) }
        menuOpts.append("?")

        promptTextWithMenu("", options: menuOpts)
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= suggestionList.count {
                self.confirmChangeName(index: index, newName: suggestionList[choice - 1])
            } else {
                self.showChangeNameHelp(index: index)
            }
        }

        inputHandler = { [weak self] name in
            guard let self = self else { return }
            let trimmed = name.trimmingCharacters(in: .whitespaces)
            guard !trimmed.isEmpty else {
                self.showInGameEditCharacter(index: index)
                return
            }
            self.confirmChangeName(index: index, newName: self.applyInitialCaps(trimmed))
        }

        // Dice icon → new random suggestions
        rerollHandler = { [weak self] in
            self?.showInGameChangeName(index: index)
        }

        closeHandler = { [weak self] in self?.showInGameEditCharacter(index: index) }
    }

    private func confirmChangeName(index: Int, newName: String) {
        let char = party[index]
        let oldName = char.name

        clearTerminal()
        printTitle("Confirm Name Change")
        print("")
        print("  \(oldName) → \(newName)", color: .yellow, bold: true)
        print("")

        // Check for Name Lore match
        let hasLore = nameEntries.contains(where: { $0.name.lowercased() == newName.lowercased() })
        if hasLore {
            print("  This name has a character card in Name Lore!", color: .brightGreen)
            print("")
        }

        showMenu(["Confirm", "< Back"])
        closeHandler = { [weak self] in self?.showInGameChangeName(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.pushEditSnapshot(index: index)
                self.party[index].name = newName
            }
            self.showInGameEditCharacter(index: index)
        }
    }

    private func showChangeNameHelp(index: Int) {
        showInlineHelp {
            self.printTitle("Change Name — Help")
            self.print("")

            self.print("  INFORMATION", color: .cyan, bold: true)
            self.printWrapped("Shows the current character name and random suggestions from the name pool.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  HOW TO USE", color: .cyan, bold: true)
            self.printWrapped("Type a new name and press return to apply it. Tap the 🎲 icon above the keyboard for fresh suggestions. Names matching heroes from Name Lore will have character cards!", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  UNDO / CANCEL", color: .cyan, bold: true)
            self.printWrapped("Tap close (✕) to cancel without changing the name.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    /// Change player type mid-game (human/AI)
    private func showInGameChangeType(index: Int) {
        guard index < party.count else { showInGamePartyReview(); return }
        let char = party[index]
        let hasHumanElsewhere = party.enumerated().contains(where: { $0.offset != index && !$0.element.isComputerControlled })

        clearTerminal()
        printTitle("Player Type — \(shortName(for: char))")

        let currentType = char.isComputerControlled ? "Auto (Robot)" : "Local (You)"
        print("  Current: \(currentType)", color: .yellow)
        print("")

        var opts: [String] = []
        var typeLabels: [String] = []

        opts.append("Local (You)")
        typeLabels.append("Local (You)")

        // Remote option — only offered while Multiplayer is actually
        // switched on in Settings, matching showChangePlayerType (the
        // pre-adventure equivalent of this screen).
        let gcAuth = multiplayerEnabled && GameCenterManager.shared.isAuthenticated && party.count >= 2
        if gcAuth && (hasHumanElsewhere || !char.isComputerControlled) {
            opts.append("Remote Player")
            typeLabels.append("Remote Player")
        }

        // Auto (robot) option — only if another human player exists to maintain control
        if party.count > 1 && hasHumanElsewhere {
            opts.append("Auto (Robot)")
            typeLabels.append("Auto (Robot)")
        }

        opts.append("?")
        opts.append("< Back")

        showMenu(opts)

        closeHandler = { [weak self] in self?.showInGameEditCharacter(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == opts.count {
                self.showInGameEditCharacter(index: index)
                return
            }
            if choice == opts.count - 1 {
                self.showChangeTypeHelp(index: index)
                return
            }
            guard choice > 0 && choice <= typeLabels.count else { return }
            let newType = typeLabels[choice - 1]
            if newType == currentType {
                self.showInGameEditCharacter(index: index)
                return
            }
            self.confirmInGameChangeType(index: index, newType: newType, currentType: currentType)
        }
    }

    private func confirmInGameChangeType(index: Int, newType: String, currentType: String) {
        let char = party[index]
        clearTerminal()
        printTitle("Confirm Type Change")
        print("")
        print("  \(shortName(for: char)): \(currentType) → \(newType)", color: .yellow, bold: true)
        print("")

        print("  WHAT CHANGES:", color: .cyan, bold: true)
        switch newType {
        case "Local (You)":
            printWrapped("You will control \(char.name) directly in combat and exploration.", indent: 2, color: .dimGreen)
        case "Auto (Robot)":
            printWrapped("\(char.name) will act on their own — the robot chooses actions automatically.", indent: 2, color: .dimGreen)
        case "Remote Player":
            printWrapped("Another player will control \(char.name) via Game Centre multiplayer.", indent: 2, color: .dimGreen)
        default: break
        }
        print("")

        showMenu(["Confirm", "< Back"])
        closeHandler = { [weak self] in self?.showInGameChangeType(index: index) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.pushEditSnapshot(index: index)
                switch newType {
                case "Local (You)":
                    self.party[index].unmarkAsAI()
                case "Auto (Robot)":
                    self.party[index].markAsAI()
                case "Remote Player":
                    self.party[index].unmarkAsAI()
                    self.convertLocalToMultiplayer(remoteCharacter: self.party[index])
                    return // convertLocalToMultiplayer handles navigation
                default: break
                }
            }
            self.showInGameEditCharacter(index: index)
        }
    }

    private func showChangeTypeHelp(index: Int) {
        showInlineHelp {
            self.printTitle("Player Type — Help")
            self.print("")

            self.print("  INFORMATION", color: .cyan, bold: true)
            self.printWrapped("Shows the current controller for this character.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  OPTIONS", color: .cyan, bold: true)
            self.printWrapped("Local (You) — you control this character's actions in combat and exploration.", indent: 2, color: .dimGreen)
            self.printWrapped("Auto (Robot) — the robot controls this character. They act on their own in combat and their name gets an \"R.\" prefix.", indent: 2, color: .dimGreen)
            self.printWrapped("Remote Player — invite a friend via Game Centre to control this character (requires 2+ party members and Game Centre sign-in).", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    private func startPartyStatusAnim(artLineRanges: [(charClass: CharacterClass, startIndex: Int, count: Int)]) {
        cancelPartyStatusAnim()
        partyStatusAnimFrame = 0

        partyStatusAnimTimer = Timer.scheduledTimer(withTimeInterval: 1.5, repeats: true) { [weak self] _ in
            DispatchQueue.main.async {
                guard let self = self else { return }
                self.partyStatusAnimFrame += 1

                for range in artLineRanges {
                    let frames = range.charClass.asciiArtFrames
                    let frameIdx = self.partyStatusAnimFrame % frames.count
                    let frame = frames[frameIdx]

                    for (i, line) in frame.enumerated() {
                        let lineIdx = range.startIndex + i
                        if lineIdx < self.terminalLines.count {
                            self.terminalLines[lineIdx].text = line
                        }
                    }
                }
            }
        }
    }

    private func cancelPartyStatusAnim() {
        partyStatusAnimTimer?.invalidate()
        partyStatusAnimTimer = nil
    }

    /// Invite a remote player to take over an AI character in the current local game
    private func showInviteToCurrentGame() {
        let aiChars = party.filter { $0.isComputerControlled }
        guard !aiChars.isEmpty else {
            showPartyStatus()
            return
        }

        clearTerminal()
        printTitle("Invite Remote Player")
        print("Choose a robot character for the", color: .dimGreen)
        print("remote player to control:", color: .dimGreen)
        print("")

        var opts: [String] = []
        for char in aiChars {
            opts.append("\(char.name) — \(char.race.rawValue) \(char.characterClass.rawValue)")
        }
        opts.append("Done")

        showMenu(opts)
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice >= 1 && choice <= aiChars.count {
                self.convertLocalToMultiplayer(remoteCharacter: aiChars[choice - 1])
            } else {
                self.showPartyStatus()
            }
        }
    }

    /// Convert a local game to multiplayer by assigning an AI character to a remote player
    private func convertLocalToMultiplayer(remoteCharacter: Character) {
        clearTerminal()
        printTitle("Invite Player")
        printWrapped("Inviting a player to control \(remoteCharacter.name)...", indent: 2, color: .dimGreen)
        print("")
        printWrapped("The Game Centre matchmaker will appear. Select a friend to invite.", indent: 2, color: .dimGreen)
        print("")

        // Store which character will be remote
        pendingRemoteCharacterId = remoteCharacter.id
        isMultiplayer = true

        // Close icon → cancel and go back to party review
        closeHandler = { [weak self] in
            self?.pendingRemoteCharacterId = nil
            self?.isMultiplayer = false
            self?.showInGamePartyReview()
        }

        // Show matchmaker for 2 players (us + 1 remote)
        GameCenterManager.shared.showMatchmaker(minPlayers: 2, maxPlayers: 2)
    }

    func showAdventureLog(onBack: (() -> Void)? = nil) {
        clearTerminal()
        printTitle("Adventure Log")
        print("  Time: \(formattedGameTime())", color: .cyan)
        print("  \(adventureLog.count) events", color: .dimGreen)
        print("")

        if adventureLog.isEmpty {
            print("  No events recorded yet.", color: .dimGreen)
        } else {
            // Always the full history across every day — no day filtering.
            // A display limit (if set) only caps how many of the most recent
            // entries are shown, never which days are included.
            let limit = adventureLogLimit
            let entries: [String]
            if limit > 0 && adventureLog.count > limit {
                entries = Array(adventureLog.suffix(limit))
                print("  (Showing last \(limit) of \(adventureLog.count) events — change in Settings > Gameplay)", color: .dimGreen)
                print("")
            } else {
                entries = adventureLog
                if adventureLog.count > 200 {
                    print("  Long log! Set a display limit in Settings > Gameplay if scrolling takes too long.", color: .dimGreen)
                    print("")
                }
            }
            let charColors: [TerminalColor] = [.brightGreen, .cyan, .magenta, .orange]
            for entry in entries {
                let color: TerminalColor
                if entry.contains("[COMBAT]") { color = .red }
                else if entry.contains("[LOOT]") { color = .yellow }
                else if entry.contains("[DM]") { color = .cyan }
                else if entry.contains("[LEVEL]") { color = .brightGreen }
                else if entry.contains("[TRAP]") { color = .red }
                else if entry.contains("[PARTY]") { color = .magenta }
                else if entry.contains("[CHAT]") {
                    if entry.contains("DM:") || entry.contains("Dungeon Master") {
                        color = .yellow
                    } else if let charIdx = party.firstIndex(where: { entry.contains($0.name) }) {
                        color = charColors[charIdx % charColors.count]
                    } else {
                        color = .green
                    }
                }
                else { color = .dimGreen }
                print("  \(entry)", color: color)
            }
        }

        print("")

        let back = onBack ?? { [weak self] in self?.showPartyStatus() }
        showMenu(["Export Log", "Import Log", "Report a Bug", "?", "< Back"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: self.prepareLogExport()
            case 2: self.showLogImporter = true
            case 3: self.prepareBugReportExport()
            case 4:
                self.showInlineHelp {
                    self.printTitle("Adventure Log — Help")
                    self.print("")
                    self.printWrapped("A running record of everything that's happened this adventure — combat, loot, level-ups, traps, chat, and party events, colour-coded by type.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  EXPORT LOG", color: .cyan, bold: true)
                    self.printWrapped("Saves the full log (not just what's shown here) as a text file you can share or keep.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  IMPORT LOG", color: .cyan, bold: true)
                    self.printWrapped("Loads a previously exported log file back in — handy for keeping a record across devices.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  REPORT A BUG", color: .cyan, bold: true)
                    self.printWrapped("Exports a \"Glitch in the Weave\" bug report — device/app info, recent log and DM chat, and (if the app crashed last launch) the crash details — as a text file you can share. Also saves this exact moment under its own name in Continue Adventure, so it can be replayed.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("Settings > Gameplay lets you cap how many recent events are displayed if the log gets long.", indent: 2, color: .dimGreen)
                    self.printLink("Settings > Gameplay", to: "gameplay", indent: 4)
                }
            case 5: back()
            default: break
            }
        }
        closeHandler = back
    }

    /// Builds the exportable text and flips the flag TerminalView watches to
    /// present the system export/save dialog.
    func prepareLogExport() {
        let header = "D&D Text RPG — Adventure Log\nExported: \(Date())\n\(adventureLog.count) events\n\n"
        pendingLogExportText = header + adventureLog.joined(separator: "\n")
        showLogExporter = true
    }

    /// "Glitch in the Weave" bug report — reuses the exact same export
    /// pipeline as the Adventure Log (pendingLogExportText/showLogExporter),
    /// just with different content: device/app info, current game state,
    /// recent adventure log and DM chat, and (if a crash was detected on
    /// last launch — see checkForPendingCrashReport) that crash's details.
    /// Also takes a dedicated, distinctly-named save of the CURRENT exact
    /// moment — including mid-combat, unlike a normal quick save, which
    /// clears an active encounter so reloading doesn't ambush you — so the
    /// state that led to the report is genuinely reloadable ("replay")
    /// from Continue Adventure afterwards, without touching the player's
    /// own ongoing save slot.
    func prepareBugReportExport() {
        var report = "D&D Text RPG — Glitch in the Weave Bug Report\n"
        report += "Generated: \(Date())\n"
        #if os(iOS)
        report += "Device: \(UIDevice.current.model), \(UIDevice.current.systemName) \(UIDevice.current.systemVersion)\n"
        #endif
        if let version = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String,
           let build = Bundle.main.infoDictionary?["CFBundleVersion"] as? String {
            report += "App Version: \(version) (\(build))\n"
        }
        report += "\n"

        if let crashInfo = Self.pendingCrashInfo() {
            report += "LAST LAUNCH ENDED IN A CRASH:\n\(crashInfo)\n\n"
        }

        if let dungeon = dungeon, let room = dungeon.currentRoom {
            report += "CURRENT STATE:\n"
            report += "Dungeon: \(dungeon.name), Level \(dungeon.level)\n"
            report += "Room: \(room.name) (\(room.roomType.rawValue))\n"
            report += "Game phase: \(String(describing: gameState))\n\n"
        } else {
            report += "CURRENT STATE: no adventure in progress.\n\n"
        }

        if !party.isEmpty {
            report += "PARTY:\n"
            for char in party {
                report += "\(char.name): \(char.race.rawValue) \(char.characterClass.rawValue) L\(char.level) HP:\(char.currentHP)/\(char.maxHP)\n"
            }
            report += "\n"
        }

        if !adventureLog.isEmpty {
            report += "RECENT ADVENTURE LOG (last 30):\n"
            report += adventureLog.suffix(30).joined(separator: "\n")
            report += "\n\n"
        }

        if !dmChatLog.isEmpty {
            report += "RECENT DM CHAT (last 20):\n"
            report += dmChatLog.suffix(20).map { ($0.isUser ? "You: " : "DM: ") + $0.text }.joined(separator: "\n")
            report += "\n\n"
        }

        report += bugReportSettingsSnapshot()

        if !actionTrail.isEmpty {
            report += "ACTION TRAIL (last \(actionTrail.count) — what was pressed, typed or walked, and on which screen):\n"
            report += actionTrail.joined(separator: "\n")
            report += "\n\n"
        }

        if dungeon != nil, let savedSlotName = performBugReportSave() {
            report += "A save point named \"\(savedSlotName)\" was created for this report — find it under Continue Adventure to replay from this exact moment.\n\n"
        }

        // The whole game state, so it can be loaded elsewhere: Adventure Log >
        // Import Log spots this block and turns it into a Continue Adventure slot.
        // (Dice are rolled afresh, so a replay follows the trail, not the same luck.)
        if let snapshot = makeSnapshotSave(slotName: "Bug Report"), let json = Self.encodeSaveForReport(snapshot) {
            report += "To replay: Adventure Log > Import Log, and choose this file.\n"
            report += Self.bugSaveBegin + "\n" + json + "\n" + Self.bugSaveEnd + "\n"
        }

        pendingLogExportText = report
        showLogExporter = true
        clearPendingCrashReport()
    }

    /// Saves the CURRENT exact state (mid-combat included) under its own
    /// distinct slot, never overwriting the player's own active save.
    /// Returns the slot name on success.
    @discardableResult
    private func performBugReportSave() -> String? {
        guard let dungeon = dungeon else { return nil }
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd HH:mm:ss"
        let slotName = "Bug Report — \(formatter.string(from: Date()))"
        guard let saveGame = makeSnapshotSave(slotName: slotName) else { return nil }
        guard (try? SaveGameManager.shared.save(saveGame)) != nil else { return nil }
        return slotName
    }

    /// The game exactly as it stands, as a save (not written anywhere).
    private func makeSnapshotSave(slotName: String) -> SaveGame? {
        guard let dungeon = dungeon else { return nil }
        let partyDesc = party.map { "\($0.name) (\($0.characterClass.rawValue))" }.joined(separator: ", ")
        let chatEntries = dmChatLog.map { DMChatEntry(isUser: $0.isUser, text: $0.text) }
        return SaveGame(
            id: UUID(), slotId: UUID(), savedAt: Date(), slotName: slotName,
            partyDescription: partyDesc, dungeonName: dungeon.name, dungeonLevel: dungeon.level,
            party: party, dungeon: dungeon, gameState: gameState,
            gameTimeMinutes: gameTimeMinutes, adventureLog: adventureLog,
            dmChatLog: chatEntries, torchLit: torchLit,
            torchTurnsRemaining: torchTurnsRemaining,
            partyChatLog: partyChatLog.suffix(20).map { $0 },
            monstersSlain: monstersSlain,
            combatsWon: combatsWon,
            activeQuest: activeQuest, otherQuests: otherQuests, introLines: adventureIntroLines, mainQuest: mainQuest, questHistory: questHistory, noMainQuest: noMainQuest, mainQuestCompleted: mainQuestCompleted, questSummary: questSummaryLine()
        )
    }

    static let bugSaveBegin = "=== SAVE DATA (BEGIN) ==="
    static let bugSaveEnd = "=== SAVE DATA (END) ==="

    private static func encodeSaveForReport(_ save: SaveGame) -> String? {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.sortedKeys]
        guard let data = try? encoder.encode(save) else { return nil }
        return String(data: data, encoding: .utf8)
    }

    /// The last 200 things the player did — buttons, moves, typed lines —
    /// each with the screen it happened on, so a bug report shows the steps.
    private(set) var actionTrail: [String] = []
    private static let trailTime: DateFormatter = { let f = DateFormatter(); f.dateFormat = "HH:mm:ss"; return f }()
    func recordAction(_ what: String) {
        actionTrail.append("[\(Self.trailTime.string(from: Date()))] [\(currentScreenTitle ?? "-")] \(what)")
        if actionTrail.count > 200 { actionTrail.removeFirst(actionTrail.count - 200) }
    }

    /// The app's own settings, for a bug report — anything that could be a
    /// key, token or password left out, and long values cut short.
    private func bugReportSettingsSnapshot() -> String {
        guard let bundleId = Bundle.main.bundleIdentifier,
              let domain = UserDefaults.standard.persistentDomain(forName: bundleId) else { return "" }
        let secret = ["key", "token", "secret", "password", "auth", "credential"]
        var lines: [String] = []
        for name in domain.keys.sorted() {
            let lower = name.lowercased()
            guard !secret.contains(where: lower.contains), let value = domain[name] else { continue }
            if value is Data { continue }
            var text = "\(value)".replacingOccurrences(of: "\n", with: " ")
            if text.count > 80 { text = String(text.prefix(77)) + "..." }
            lines.append("\(name) = \(text)")
        }
        return lines.isEmpty ? "" : "SETTINGS:\n" + lines.joined(separator: "\n") + "\n"
    }

    /// Called by TerminalView's .fileExporter completion. On success, just
    /// confirms; if the system picker failed or was denied (not a plain
    /// user cancel), the log is never lost — it's written into the app's
    /// own sandboxed space instead, which needs no filesystem permission at
    /// all, and the player is told exactly where to find it.
    func handleLogExportResult(_ result: Result<URL, Error>) {
        switch result {
        case .success(let url):
            print("  Log exported to \(url.lastPathComponent).", color: .brightGreen)
        case .failure(let error):
            let nsError = error as NSError
            // A plain user cancel isn't a failure worth falling back for.
            if nsError.domain == NSCocoaErrorDomain && nsError.code == NSUserCancelledError { return }
            if let savedURL = saveLogToGameSpace(pendingLogExportText) {
                print("  Couldn't save to that location, so the log was saved inside the app instead:", color: .yellow)
                print("  \(savedURL.lastPathComponent)", color: .dimGreen)
            } else {
                print("  Couldn't export the log.", color: .red)
            }
        }
    }

    /// Writes text into the app's own Documents/ExportedLogs directory — no
    /// filesystem permission needed since it's inside the app's sandbox.
    /// Used as a guaranteed fallback when the user-facing file picker fails.
    @discardableResult
    private func saveLogToGameSpace(_ text: String) -> URL? {
        guard let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first else { return nil }
        let dir = docs.appendingPathComponent("ExportedLogs")
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd-HHmmss"
        let url = dir.appendingPathComponent("adventure-log-\(formatter.string(from: Date())).txt")
        do {
            try text.write(to: url, atomically: true, encoding: .utf8)
            return url
        } catch {
            return nil
        }
    }

    /// Appends an externally-loaded log's lines onto the current session's
    /// log (never replaces it — importing is additive, so you can't lose
    /// the current run's history by mistake).
    func importAdventureLog(from text: String) {
        // An adventure file (see AdventureLibrary): add it to the collection.
        if let data = text.data(using: .utf8), let adventure = try? JSONDecoder().decode(AdventureFile.self, from: data),
           (3...14).contains(adventure.tale.count), let dir = AdventureLibrary.folder {
            var a = adventure
            a.generated = false
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
            if let out = try? encoder.encode(a) {
                try? out.write(to: dir.appendingPathComponent("imported-\(Int(Date().timeIntervalSince1970)).json"), options: .atomic)
                logEvent("Added the adventure \"\(a.title)\" to the collection", category: "SYSTEM")
                print("")
                print("  Adventure \"\(a.title)\" added — a new adventure may now use it.", color: .brightGreen)
            }
            return
        }
        // A bug report carries the whole game: load it as its own slot.
        var text = text
        var importedSlot: String?
        if let begin = text.range(of: Self.bugSaveBegin), let end = text.range(of: Self.bugSaveEnd, range: begin.upperBound..<text.endIndex) {
            let json = String(text[begin.upperBound..<end.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
            importedSlot = importBugReportSave(json)
            text.removeSubrange(begin.lowerBound..<end.upperBound)
        }
        defer {
            if let slot = importedSlot {
                print("")
                print("  This was a bug report with a saved game in it — loaded as", color: .brightGreen)
                print("  \"\(slot)\". Find it under Continue Adventure.", color: .brightGreen)
            }
        }
        let lines = text.split(separator: "\n", omittingEmptySubsequences: true).map(String.init)
        guard !lines.isEmpty else { return }
        adventureLog.append("--- Imported log (\(lines.count) lines) ---")
        adventureLog.append(contentsOf: lines)
        logEvent("Imported an adventure log (\(lines.count) lines)", category: "SYSTEM")
        if gameState == .exploring || dungeon != nil {
            showAdventureLog()
        }
    }

    /// Turns a bug report's saved game into a new Continue Adventure slot
    /// (fresh ids, so it never replaces anything). Returns its name.
    private func importBugReportSave(_ json: String) -> String? {
        guard let data = json.data(using: .utf8),
              var dict = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] else { return nil }
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd HH:mm"
        let name = "Imported Bug Report — \(formatter.string(from: Date()))"
        dict["id"] = UUID().uuidString
        dict["slotId"] = UUID().uuidString
        dict["slotName"] = name
        dict["savedAt"] = ISO8601DateFormatter().string(from: Date())
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        guard let fixed = try? JSONSerialization.data(withJSONObject: dict),
              let save = try? decoder.decode(SaveGame.self, from: fixed),
              (try? SaveGameManager.shared.save(save)) != nil else {
            logEvent("A bug report's saved game couldn't be read", category: "SYSTEM")
            return nil
        }
        logEvent("Loaded a bug report's saved game as \"\(name)\"", category: "SYSTEM")
        return name
    }

    /// Rest screen "Eat & Drink" — any food or drink anyone in the party is
    /// carrying, eaten by whoever you choose (see consumeFood).
    private func showRestMeal() {
        var entries: [(owner: Character, item: Item)] = []
        for char in party {
            for item in char.inventory where ItemCatalog.foodKind(for: item) != nil { entries.append((char, item)) }
        }
        clearTerminal()
        printTitle("Eat & Drink")
        closeHandler = { [weak self] in self?.rest() }
        guard !entries.isEmpty else {
            printWrapped("Nobody has anything to eat or drink. A merchant's counter is the place to fix that.", indent: 2, color: .dimGreen)
            print("")
            showMenu(["< Back"])
            menuHandler = { [weak self] _ in self?.rest() }
            return
        }
        printWrapped("A bite or a drink restores a little HP. Hearty food, sweets and a cup of tea each do a bit more — but too much juice and you'll slosh.", indent: 2, color: .dimGreen)
        print("")
        for entry in entries {
            if let effect = entry.item.potionStats?.effect {
                printWrapped("\(entry.item.name) (\(shortName(for: entry.owner))): \(effect)", indent: 2, color: .green)
            }
        }
        print("")
        let labels = entries.map { "\($0.item.name) · \(shortName(for: $0.owner))" }
        showPaginatedMenuOptions(labels, pinned: ["< Back"], handler: { [weak self] idx in
            guard let self = self, idx >= 0, idx < entries.count else { return }
            let entry = entries[idx]
            let eat: (Character) -> Void = { target in
                guard let food = self.consumeFood(entry.item, by: target) else { return }
                entry.owner.removeItem(entry.item)
                self.print("")
                for (line, color) in food.lines { self.printWrapped(line, indent: 2, color: color) }
                self.logEvent(food.summary, category: "REST")
                self.advanceTime(10)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showRestMeal() }
            }
            if self.party.count > 1 {
                self.pickCharacter(title: "Who \(ItemCatalog.consumeVerb(for: entry.item)) the \(entry.item.name)?", onBack: {
                    self.showRestMeal()
                }) { target in eat(target) }
            } else {
                eat(entry.owner)
            }
        }, pinnedHandler: { [weak self] _ in self?.rest() })
    }

    /// Game time of the party's last wash — a proper scrub only helps so often.
    private var lastWashGameMinutes: Int?

    /// Rest screen "Wash" — a light-hearted freshen-up worth 1 temporary HP each.
    private func restWash() {
        clearTerminal()
        printTitle("Wash")
        if let last = lastWashGameMinutes, gameTimeMinutes - last < 240 {
            printWrapped("You're all still squeaky clean from the last scrub. Any cleaner and the monsters won't recognise you.", indent: 2, color: .dimGreen)
        } else {
            lastWashGameMinutes = gameTimeMinutes
            let flavour = [
                "splashes cold water on their face and yelps.",
                "scrubs behind their ears — somebody had to.",
                "wrings out their socks. The smell improves slightly.",
                "finds a trickle of clean water and makes the most of it.",
                "combs out a surprising amount of cobweb.",
                "tidies up and feels almost civilised again.",
            ].shuffled()
            // Washing in the pitch dark only half works.
            let inDark = !torchLit && !(dungeon?.currentRoom?.isTorchlit ?? false)
            var freshened = 0
            for (i, char) in party.filter({ $0.isConscious }).enumerated() {
                if inDark && Bool.random() {
                    printWrapped("\(shortName(for: char)) gropes about in the dark and mostly just gets their boots wet.", indent: 2, color: .dimGreen)
                    continue
                }
                printWrapped("\(shortName(for: char)) \(flavour[i % flavour.count])", indent: 2, color: .green)
                char.tempHP = max(char.tempHP, 1)
                freshened += 1
            }
            print("")
            if !inDark {
                printWrapped("Feeling fresh: everyone gains 1 temporary HP.", indent: 2, color: .yellow)
            } else if freshened > 0 {
                printWrapped("Washing in the dark only half works: \(freshened) of you feel fresher (1 temporary HP). A lit torch would help.", indent: 2, color: .yellow)
            } else {
                printWrapped("Washing in the pitch dark is hopeless — nobody feels much fresher. Light a torch first.", indent: 2, color: .yellow)
            }
            logEvent("The party washed up during a rest", category: "REST")
            advanceTime(15)
        }
        print("")
        waitForContinue()
        inputHandler = { [weak self] _ in self?.rest() }
    }

    func rest() {
        clearTerminal()

        // Show map at top
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        print("Choose rest type:", color: .cyan, bold: true)
        if torchLit {
            printWrapped("Tip: Douse your torch before resting to save fuel.", indent: 2, color: .dimGreen)
        }
        // Check for unsecured exits and warn
        if let room = dungeon?.currentRoom {
            let openExits = room.exits.keys.filter { !room.secured.contains($0) }
            if !openExits.isEmpty {
                printWrapped("Tip: Barricade doors before resting to reduce attack risk.", indent: 2, color: .dimGreen)
            } else {
                printWrapped("All doors barricaded — safer to rest here.", indent: 2, color: .dimGreen)
            }
        }

        printWrapped("While you rest you can also eat, drink or wash — a little well-being goes a long way.", indent: 2, color: .dimGreen)

        var options: [String] = ["Short Rest", "Long Rest", "Eat & Drink", "Wash"]
        if torchLit {
            options.append("Douse Torch")
        } else if partyHasTorch() {
            options.append("Illuminate")
        }
        options.append("?")
        options.append("< Back")

        showMenu(options)
        closeHandler = { [weak self] in self?.showExplorationView() }

        menuLongPressHandler = { [weak self] choice in
            guard let self = self else { return }
            let selected = options[choice - 1]
            if selected == "Long Rest" {
                self.performRest(isLongRest: true, fast: true)
            } else if selected == "Short Rest" {
                self.performRest(isLongRest: false, fast: true)
            }
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let selected = options[choice - 1]
            switch selected {
            case "Short Rest":
                self.performRest(isLongRest: false)
            case "Long Rest":
                self.performRest(isLongRest: true)
            case "Eat & Drink":
                self.showRestMeal()
            case "Wash":
                self.restWash()
            case "Douse Torch":
                self.torchLit = false
                self.print("")
                self.print("  You carefully douse the torch.", color: .yellow)
                self.print("  Darkness envelops the party...", color: .dimGreen)
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                    self.rest()
                }
            case "Illuminate":
                self.torchLit = true
                self.print("")
                self.print("  The torch flickers to life!", color: .yellow)
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                    self.rest()
                }
            case "?":
                self.showRestHelp()
            default:
                self.showExplorationView()
            }
        }
    }

    /// A light-hearted line about the unglamorous side of adventuring —
    /// eating, washing, the one discreet corner — so a rest reads like the
    /// party actually stopped to live a bit, not just a heal-over-time.
    private func restFlavourLine(isLongRest: Bool) -> String {
        let names = party.map { shortName(for: $0) }.shuffled()
        let a = names.first ?? "Someone"
        let b = names.count > 1 ? names[1] : "the echo"
        let short = [
            "\(a) wolfs down a heel of bread while \(b) pretends not to notice the crumbs.",
            "\(a) slips behind a pillar for a moment of, ahem, privacy. Nobody mentions it.",
            "\(a) splashes water on their face and declares themselves 'practically bathed'.",
            "A flask goes round. \(a) gets the last, suspiciously warm, mouthful.",
            "\(a) shakes a pebble out of a boot that has clearly been there since level one.",
        ]
        let long = [
            "Dinner is \(a)'s famous dungeon stew. Nobody asks what's in it.",
            "\(a) takes a proper wash in a bucket of cold water — loudly, and at length.",
            "\(b) snores. \(a) throws a boot. Balance is restored.",
            "Everyone finally takes their boots off. The torch flickers in protest.",
            "\(a) brushes their teeth with a twig and a great deal of ceremony.",
            "The party queues politely for the one discreet corner of the room.",
            "\(a) darns a sock by torchlight. \(b) offers to 'help' and is firmly declined.",
        ]
        return (isLongRest ? long : short).randomElement()!
    }

    /// On a long rest, if anyone's carrying provisions (honey, bread,
    /// mead... — see ItemCatalog.provisions), the party eats one of them.
    /// Eats or drinks a food/drink item: rolls its HP, then applies its
    /// FoodKind effect (feeling strong, sugary lift, juice slosh...). The
    /// caller removes the item and logs `summary`. Returns nil for anything
    /// that isn't food, so callers fall back to their normal potion path.
    func consumeFood(_ item: Item, by target: Character) -> (lines: [(String, TerminalColor)], summary: String)? {
        guard let kind = ItemCatalog.foodKind(for: item) else { return nil }
        let verb = ItemCatalog.consumeVerb(for: item)
        var lines: [(String, TerminalColor)] = [("\(target.name) \(verb) the \(item.name).", .brightGreen)]
        var notes: [String] = []

        var healAmount = 0
        if let healStr = item.potionStats?.healAmount {
            healAmount = max(1, Dice.rollDamage(healStr).total)
        }
        // In the dark it's hard to see what (or how much) you're eating —
        // only half the good of it.
        let inDark = !torchLit && !(dungeon?.currentRoom?.isTorchlit ?? false)
        if inDark {
            healAmount = healAmount > 0 ? max(1, healAmount / 2) : 0
            lines.append(("It's too dark to see what you're \(verb == "drinks" ? "drinking" : "eating") — half of it ends up down \(target.name)'s front. (Only half the benefit.)", .yellow))
            notes.append("in the dark")
        }
        if case .divisive = kind {
            if Bool.random() {
                lines.append(("\(target.name) loves it, and goes back for another spoonful!", .brightGreen))
                healAmount += 1
            } else {
                lines.append(("\(target.name) hates it and pulls a face. Still — it's food.", .yellow))
                healAmount = min(healAmount, 1)
            }
        }
        if healAmount > 0 {
            let before = target.currentHP
            target.heal(healAmount)
            let gained = target.currentHP - before
            if gained > 0 {
                lines.append(("Restored \(gained) HP! (\(target.currentHP)/\(target.maxHP))", .brightGreen))
                notes.append("+\(gained) HP")
            } else {
                lines.append(("Already at full health — but it was tasty.", .dimGreen))
            }
        }

        func feelStrong(_ attacks: Int) {
            guard attacks > 0 else { return }
            let boosted = inDark ? max(1, attacks / 2) : attacks
            target.wellFedAttacks = max(target.wellFedAttacks, boosted)
            lines.append(("\(target.name) feels strong! +1 to attack and damage for the next \(boosted) attack\(boosted == 1 ? "" : "s").", .yellow))
            notes.append("feeling strong")
        }

        switch kind {
        case .plain, .divisive:
            break
        case .hearty(let attacks):
            feelStrong(attacks)
        case .strange(let line, let attacks):
            lines.append((line, .cyan))
            feelStrong(attacks)
        case .sweet:
            let lift = inDark ? 1 : 2
            target.tempHP = max(target.tempHP, lift)
            lines.append(("A sugary lift: \(lift) temporary HP\(inDark ? " (less, in the dark)" : "").", .yellow))
            notes.append("sugary lift")
        case .juice(let glasses):
            target.juiceCount += glasses
            if target.juiceCount >= 3 {
                target.sluggishAttacks = max(target.sluggishAttacks, 2)
                lines.append(("Too much juice! \(target.name) is full to the brim and sloshing about — sluggish: disadvantage on the next 2 attacks.", .yellow))
                lines.append(("(Water, tea or a rest will settle it.)", .dimGreen))
                notes.append("sluggish from too much juice")
            } else if target.juiceCount == 2 {
                lines.append(("\(target.name)'s belly gurgles. Any more juice and they'll start to slow down.", .dimGreen))
            }
        case .refreshing:
            if target.sluggishAttacks > 0 || target.juiceCount > 0 {
                target.juiceCount = 0
                target.sluggishAttacks = 0
                lines.append(("That settles things — \(target.name) no longer feels sloshy.", .brightGreen))
                notes.append("no longer sluggish")
            } else {
                lines.append(("Refreshing.", .dimGreen))
            }
        }

        let summary = "\(target.name) \(verb) \(item.name)" + (notes.isEmpty ? "" : " — " + notes.joined(separator: ", "))
        return (lines, summary)
    }

    private func eatProvisionDuringRest() -> String? {
        for char in party {
            // A proper meal, not a drink — juice isn't dinner.
            if let item = char.inventory.first(where: { ItemCatalog.foodKind(for: $0) != nil && ItemCatalog.consumeVerb(for: $0) == "eats" }) {
                char.removeItem(item)
                logEvent("\(char.name) shared \(item.name) during a long rest", category: "REST")
                return "\(shortName(for: char)) breaks out the \(item.name) — dinner is served."
            }
        }
        return nil
    }

    func performRest(isLongRest: Bool, fast: Bool = false) {
        let repeats = isLongRest ? 3 : 1
        let restDuration = isLongRest ? "8 hours" : "1 hour"
        let header = isLongRest ? "Taking a long rest (\(restDuration))..." : "Resting (\(restDuration))..."

        clearTerminal()

        // Show map at top
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        SoundManager.shared.stopMusic()
        print(header, color: .cyan, bold: true)
        // Sleeping it off: a rest settles any juice overindulgence.
        for char in party { char.juiceCount = 0; char.sluggishAttacks = 0 }
        if isHoldingScreen && !fast {
            print("(Hold screen to rest faster)", color: .dimGreen)
        }

        // Show clock that ticks during rest
        let startTime = gameTimeMinutes
        let totalMinutes = isLongRest ? 480 : 60
        print("  \(formattedGameTime())", color: .dimGreen)
        let clockLineIndex = terminalLines.count - 1
        print("")

        playHourglassAnimation(repeats: repeats, fast: fast, onFrame: { [weak self] progress in
            guard let self = self else { return }
            // Tick the clock proportionally through the rest
            let elapsed = Int(Double(totalMinutes) * progress)
            let displayTime = startTime + elapsed
            let day = displayTime / 1440 + 1
            let hourOfDay = (displayTime % 1440) / 60
            let minute = displayTime % 60
            let period = hourOfDay >= 12 ? "PM" : "AM"
            let hour12 = hourOfDay == 0 ? 12 : (hourOfDay > 12 ? hourOfDay - 12 : hourOfDay)
            let timeStr = "Day \(day), \(hour12):\(String(format: "%02d", minute)) \(period)"
            if clockLineIndex < self.terminalLines.count {
                self.terminalLines[clockLineIndex].text = "  \(timeStr)"
            }
        }) { [weak self] in
            guard let self = self else { return }

            SoundManager.shared.playHeal()

            if !isLongRest {
                self.advanceTime(60)
                self.print("")
                self.print("Short rest complete!", color: .cyan, bold: true)
                self.printWrapped(self.restFlavourLine(isLongRest: false), indent: 2, color: .dimGreen)
                self.print("")
                var healed: [String] = []
                for char in self.party {
                    let healAmount = Dice.rollSum(1, d: char.characterClass.hitDie)
                    char.heal(healAmount)
                    self.print("\(char.name) recovers \(healAmount) HP")
                    healed.append("\(char.name) +\(healAmount)HP")
                    if char.characterClass == .fighter {
                        char.secondWindUsed = false
                    }
                    // Short rest: CON save to fight off poison (fever breaks)
                    if char.isPoisoned {
                        let conMod = char.abilityScores.modifier(for: .constitution)
                        // Clerics, Rangers, and Druids are better at herbal remedies
                        let classBonus = (char.characterClass == .cleric || char.characterClass == .ranger) ? 3 : 0
                        let saveRoll = Dice.d20() + conMod + classBonus
                        if saveRoll >= 12 {
                            char.curePoison()
                            self.print("  The fever breaks — poison cured!", color: .brightGreen)
                            healed.append("\(char.name) cured")
                        } else {
                            self.print("  \(char.name) is still poisoned. Rest more or use an antidote.", color: .magenta)
                        }
                    }
                }
                self.logEvent("Short rest — \(healed.joined(separator: ", "))", category: "REST")
                self.logMultiplayerAction("Short rest — \(healed.joined(separator: ", "))")
            } else {
                self.advanceTime(480)
                self.print("")
                self.print("Long rest complete!", color: .cyan, bold: true)
                if let meal = self.eatProvisionDuringRest() {
                    self.printWrapped(meal, indent: 2, color: .yellow)
                }
                self.printWrapped(self.restFlavourLine(isLongRest: true), indent: 2, color: .dimGreen)
                self.print("")
                for char in self.party {
                    char.heal(char.maxHP)
                    self.print("\(char.name) fully recovers!")
                    // Long rest always cures poison (body fights it off over 8 hours)
                    if char.isPoisoned {
                        char.curePoison()
                        self.print("  Poison cured after a full rest!", color: .brightGreen)
                    }
                    if !char.spellSlots.isEmpty {
                        char.spellSlots.restoreAll()
                        self.print("  Spell slots restored", color: .cyan)
                    }
                    char.secondWindUsed = false
                    if char.characterClass == .barbarian {
                        char.rageUsesRemaining = char.rageMaxUses
                        char.isRaging = false
                        self.print("  Rage uses restored", color: .cyan)
                    }
                    char.huntersMarkActive = false
                    if char.characterClass.willpowerSurgeMaxUses > 0 {
                        char.willpowerSurgeUsesRemaining = char.characterClass.willpowerSurgeMaxUses
                        self.print("  Willpower Surge restored", color: .cyan)
                    }
                }
                self.logEvent("Long rest — party fully recovered", category: "REST")
                self.logMultiplayerAction("Long rest — party fully recovered")
            }

            // Drain torch during rest
            if self.torchLit {
                let restMinutes = isLongRest ? 480 : 60
                self.torchTurnsRemaining -= restMinutes
                if self.torchTurnsRemaining <= 0 {
                    self.torchTurnsRemaining = 0
                    self.torchLit = false
                    // Consume the burned-out torch
                    if let torchId = self.activeTorchId {
                        for char in self.party {
                            if let idx = char.inventory.firstIndex(where: { $0.id == torchId }) {
                                char.inventory.remove(at: idx)
                                break
                            }
                        }
                    }
                    self.activeTorchId = nil
                    self.torchHolderId = nil
                    self.print("")
                    self.print("  Your torch burned out while resting.", color: .yellow)
                    self.printTorchHint()
                } else {
                    self.syncTorchLife()
                    if isLongRest {
                        let hours = self.torchTurnsRemaining / 60
                        self.print("")
                        self.print("  Your torch burned through the night — \(hours)h left.", color: .yellow)
                        self.print("  Tip: douse your torch before resting to save it.", color: .dimGreen)
                    }
                }
            }

            self.maybeShowTip()

            // Check for rest ambush from adjacent rooms
            if let ambushEncounter = self.checkRestAmbush(isLongRest: isLongRest) {
                self.print("")
                self.print("  *** AMBUSH! ***", color: .red, bold: true)
                self.print("  Monsters burst through an unsecured door!", color: .red)
                SoundManager.shared.playHit()
                // Sleep damage — halved because body is relaxed/untensed
                var ambushLog: [String] = []
                for char in self.party where char.isConscious {
                    let rawDmg = Dice.rollSum(1, d: 6)
                    let dmg = max(1, rawDmg / 2)
                    char.takeDamage(dmg)
                    self.print("  \(char.name) takes \(dmg) damage (caught off guard)", color: .yellow)
                    ambushLog.append("\(char.name) -\(dmg)HP")
                }
                self.logEvent("Ambushed during rest! \(ambushLog.joined(separator: ", "))", category: "COMBAT")
                self.print("")
                self.print("  Find somewhere safe to rest — barricade all doors first!", color: .dimGreen)
                // Full-screen tap (there's nothing here worth scrolling back to
                // reread), but no auto-timeout — an ambush shouldn't force the
                // player into combat unattended.
                self.waitForContinue(fullScreenTap: true)
                self.inputHandler = { [weak self] _ in
                    guard let self = self else { return }
                    if let room = self.dungeon?.currentRoom {
                        room.encounter = ambushEncounter
                        room.cleared = false
                    }
                    self.showExplorationView()
                }
            } else {
                // waitForContinueWithTimeout (not plain waitForContinue): reads
                // the rest summary out loud when Voice Menus is on (built into
                // waitForContinue already) and auto-advances after a delay, with
                // the whole screen tappable too — this screen only had the
                // corner ✕ icon as a way off it otherwise.
                self.waitForContinueWithTimeout(multiplier: 4.0, fullScreenTap: true) { [weak self] in
                    if self?.musicEnabled == true { SoundManager.shared.startMusic(.exploration, preference: self?.explorationMelodyChoice ?? 0) }
                    self?.showExplorationView()
                }
            }
        }
    }

    /// Check if monsters ambush during rest. Unsecured doors to uncleared rooms = danger.
    private func checkRestAmbush(isLongRest: Bool) -> Encounter? {
        guard let dungeon = dungeon, let room = dungeon.currentRoom else { return nil }

        // Count unsecured exits leading to uncleared rooms with encounters
        var dangerousUnsecured = 0
        var dangerousSecured = 0
        for (dir, targetRoomId) in room.exits {
            guard let targetRoom = dungeon.rooms[targetRoomId] else { continue }
            guard !targetRoom.cleared && targetRoom.encounter != nil else { continue }
            if room.secured.contains(dir) {
                dangerousSecured += 1
            } else {
                dangerousUnsecured += 1
            }
        }

        guard dangerousUnsecured > 0 || dangerousSecured > 0 else { return nil }

        // Base chance: 5% per unsecured dangerous exit for short rest, 15% for long rest
        // Secured doors: only 2% chance (monsters batter through)
        let baseChance = isLongRest ? 15 : 5
        let securedChance = 2
        let totalChance = dangerousUnsecured * baseChance + dangerousSecured * securedChance
        let roll = Int.random(in: 1...100)

        guard roll <= totalChance else { return nil }

        // Spawn a small ambush encounter
        let level = dungeon.level
        let monsterTypes = MonsterType.forLevel(level)
        guard let monsterType = monsterTypes.randomElement() else { return nil }
        let count = Int.random(in: 1...2)
        let monsters = (0..<count).map { _ in Monster.create(monsterType) }
        return Encounter(monsters: monsters, difficulty: .easy)
    }

