    // MARK: Just DM — Combat

    private func showJustDMCombatTurn(characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        clearTerminal()
        printCombatStatus()
        print("")
        print("  \(character.name)'s turn", color: .brightGreen, bold: true)
        print("")
        print("  attack · cast spell · dodge · flee", color: .dimGreen)
        print("")

        promptTextWithMenu("What does \(character.name) do?", options: [])

        // Keep d-pad hidden in combat
        DispatchQueue.main.async {
            self.directionExits = [:]
            self.securedExits = []
        }

        inputHandler = { [weak self] input in
            guard let self = self else { return }
            let trimmed = input.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed.isEmpty {
                self.showJustDMCombatTurn(characterId: characterId)
                return
            }
            self.sendToJustDMCombat(trimmed, characterId: characterId)
        }
    }

    private func sendToJustDMCombat(_ input: String, characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        print("")
        print("  > \(input)", color: .cyan)
        print("")
        print("  ...", color: .dimGreen)

        let context = buildDMContext(combatContext: combat, activeCharacter: character)

        DMEngine.shared.ask(input, context: context) { [weak self] response in
            DispatchQueue.main.async {
                guard let self = self else { return }

                let result = DMEngine.parseCommands(from: response)
                let displayText = result.cleanText

                self.print("")
                for paragraph in displayText.components(separatedBy: "\n") {
                    let t = paragraph.trimmingCharacters(in: .whitespaces)
                    if !t.isEmpty { self.printWrapped("  \(t)", indent: 2, color: .yellow) }
                }

                var tookAction = false

                // Apply combat commands
                if let target = result.attackTarget {
                    self.applyJustDMAttack(target, characterId: characterId)
                    tookAction = true
                }
                if let spell = result.castSpell {
                    self.applyJustDMSpell(spell.spell, target: spell.target, characterId: characterId)
                    tookAction = true
                }
                if result.shouldDodge {
                    character.isDodging = true
                    self.print("  [\(character.name) takes the Dodge action!]", color: .cyan)
                    tookAction = true
                }
                if result.shouldFlee {
                    self.print("  [Attempting to flee!]", color: .yellow)
                    self.attemptRunAway()
                    return
                }
                if result.shouldPlayDead {
                    self.print("  [\(character.name) plays dead!]", color: .yellow)
                    tookAction = true
                }

                // Apply existing damage/heal/item commands
                if result.damageAmount > 0 {
                    if let idx = combat.encounter.monsters.firstIndex(where: { $0.isAlive }) {
                        let name = combat.encounter.monsters[idx].name
                        combat.encounter.monsters[idx].takeDamage(result.damageAmount)
                        self.print("  [\(name) takes \(result.damageAmount) damage!]", color: .brightGreen, bold: true)
                    }
                    tookAction = true
                }
                if result.damagePartyAmount > 0 {
                    for char in self.party { char.takeDamage(result.damagePartyAmount) }
                    self.print("  [-\(result.damagePartyAmount) HP!]", color: .red, bold: true)
                    tookAction = true
                }
                if result.healAmount > 0 {
                    for char in self.party { char.heal(result.healAmount) }
                    self.print("  [+\(result.healAmount) HP!]", color: .brightGreen, bold: true)
                    tookAction = true
                }
                for itemName in result.usedItems {
                    self.applyDMUseItem(itemName)
                    tookAction = true
                }

                SpeechEngine.shared.speak(displayText)

                self.print("")
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { [weak self] _ in
                    guard let self = self else { return }
                    if tookAction {
                        // Check for combat end
                        if combat.encounter.aliveMonsters.isEmpty {
                            self.handleCombatVictory()
                        } else if self.party.allSatisfy({ !$0.isConscious }) {
                            self.handleCombatDefeat()
                        } else {
                            self.advanceCombat()
                        }
                    } else {
                        // No action taken — ask again
                        self.showJustDMCombatTurn(characterId: characterId)
                    }
                }
            }
        }
    }

    private func applyJustDMAttack(_ targetName: String, characterId: UUID) {
        guard let combat = currentCombat else { return }
        let lower = targetName.lowercased()

        // Find target monster by fuzzy name match
        let target = combat.encounter.aliveMonsters.first(where: {
            $0.name.lowercased().contains(lower) || lower.contains($0.name.lowercased())
        }) ?? combat.encounter.aliveMonsters.first

        guard let monster = target else {
            print("  [No enemy to attack]", color: .dimGreen)
            return
        }

        if let report = combat.playerAttack(characterId: characterId, targetId: monster.id) {
            if report.hits {
                print("  [\(report.attackerName) hits \(report.targetName) for \(report.totalDamage ?? 0) damage!]",
                      color: .brightGreen, bold: true)
                if report.isCritical {
                    print("  [CRITICAL HIT!]", color: .brightGreen, bold: true)
                }
            } else {
                print("  [\(report.attackerName) misses \(report.targetName)!]", color: .dimGreen)
            }
        }
    }

    private func applyJustDMSpell(_ spellName: String, target: String, characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        let lower = spellName.lowercased()

        // Find the spell
        guard let spell = character.knownSpells.first(where: {
            $0.name.lowercased().contains(lower) || lower.contains($0.name.lowercased())
        }) else {
            print("  [\(character.name) doesn't know '\(spellName)'!]", color: .yellow)
            return
        }

        // Check spell slots for levelled spells
        if spell.level != .cantrip {
            if !character.spellSlots.hasSlot(level: spell.level) {
                print("  [No spell slots remaining for \(spell.name)!]", color: .yellow)
                return
            }
            character.spellSlots.useSlot(level: spell.level)
        }

        // Find target
        let targetLower = target.lowercased()
        let targetMonster = combat.encounter.aliveMonsters.first(where: {
            $0.name.lowercased().contains(targetLower) || targetLower.contains($0.name.lowercased())
        }) ?? combat.encounter.aliveMonsters.first

        // Use the spell's damage/heal dice string to roll
        if spell.spellType == .healing, let healDice = spell.healAmount {
            let healing = Dice.rollDamage(healDice).total
            for char in party { char.heal(healing) }
            print("  [\(character.name) casts \(spell.name) — party heals \(healing) HP!]",
                  color: .brightGreen, bold: true)
        } else if let monster = targetMonster, let damageDice = spell.damage,
                  let idx = combat.encounter.monsters.firstIndex(where: { $0.id == monster.id }) {
            let damage = Dice.rollDamage(damageDice).total
            combat.encounter.monsters[idx].takeDamage(damage)
            print("  [\(character.name) casts \(spell.name) on \(monster.name) for \(damage) damage!]",
                  color: .brightGreen, bold: true)
        } else {
            print("  [\(character.name) casts \(spell.name)!]", color: .cyan)
        }
    }

    // MARK: - AI Dungeon Master

    func askTheDM() {
        inDMMode = true
        // If the current room has an encounter, start combat and return to DM after
        if let room = dungeon?.currentRoom, !room.cleared, let encounter = room.encounter {
            returnToDMAfterCombat = true
            startCombat(encounter: encounter)
            return
        }

        clearTerminal()

        // Snapshot state when entering DM mode
        if StateSnapshotManager.shared.dmEntrySnapshot == nil {
            let snapshot = StateSnapshot.capture(
                label: "dm_entry",
                party: party,
                dungeon: dungeon,
                gameTimeMinutes: gameTimeMinutes
            )
            StateSnapshotManager.shared.write(snapshot)
        }

        // Show map at top
        if let dungeon = dungeon {
            printExplorationMap()
            print("")
        }

        // Replay chat history (compact — newest bright, older dim)
        if !dmChatLog.isEmpty {
            let recentEntries = Array(dmChatLog.suffix(6))
            let lastIdx = recentEntries.count - 1
            for (ei, entry) in recentEntries.enumerated() {
                let isNewest = ei == lastIdx
                if entry.isUser {
                    print("> \(entry.text)", color: isNewest ? .cyan : .dimGreen)
                } else {
                    let color: TerminalColor = isNewest ? .yellow : .dimGreen
                    print("DM:", color: color, bold: isNewest)
                    for paragraph in entry.text.components(separatedBy: "\n") {
                        let trimmed = paragraph.trimmingCharacters(in: .whitespaces)
                        if trimmed.isEmpty { print("") }
                        else { print("  \(trimmed)", color: color) }
                    }
                }
                print("")
            }
        }

        // Inject recent actions into DM context and show as history
        if adventureLogIndexAtLastDM < adventureLog.count {
            let newEntries = Array(adventureLog[adventureLogIndexAtLastDM...])
            if !newEntries.isEmpty {
                let summary = newEntries.joined(separator: "\n")
                DMEngine.shared.injectContext("The party has been busy since we last talked. Here is a summary of recent events:\n\(summary)")
                for entry in newEntries {
                    print("  \(entry)", color: .dimGreen)
                }
                print("")
            }
            adventureLogIndexAtLastDM = adventureLog.count
        }

        dmPromptForQuestion()
    }

    private func leaveDMMode() {
        inDMMode = false
        SpeechEngine.shared.stop()

        let exitSnapshot = StateSnapshot.capture(
            label: "dm_exit",
            party: party,
            dungeon: dungeon,
            gameTimeMinutes: gameTimeMinutes
        )
        StateSnapshotManager.shared.write(exitSnapshot)

        // Show diff if we have an entry snapshot
        if let entrySnapshot = StateSnapshotManager.shared.dmEntrySnapshot {
            let diff = StateDiff.compute(before: entrySnapshot, after: exitSnapshot)
            if diff.hasChanges {
                clearTerminal()
                print("--- DM Session Summary ---", color: .cyan, bold: true)
                print("")
                for change in diff.changes {
                    print("  \(change.description)", color: change.color)
                }
                print("")
                print("--------------------------", color: .cyan)
                print("")

                StateSnapshotManager.shared.clearDMEntry()

                waitForContinue()
                inputHandler = { [weak self] _ in
                    self?.showExplorationView()
                }
                return
            }
        }

        StateSnapshotManager.shared.clearDMEntry()
        showExplorationView()
    }

    private func dmPromptForQuestion() {
        promptTextWithMenu("Ask the DM:", options: [])

        inputHandler = { [weak self] input in
            guard let self = self else { return }

            let trimmed = input.trimmingCharacters(in: .whitespacesAndNewlines)

            // Empty input or explicit exit commands — leave DM mode
            if trimmed.isEmpty || ["back", "b", "quit dm", "quit dm mode", "exit", "quit", "q", "leave"].contains(trimmed.lowercased()) {
                self.leaveDMMode()
                return
            }
            let lower = trimmed.lowercased()

            // Inventory shortcut — opens inventory, Back returns to DM mode
            if lower == "i" || lower == "inventory" || lower == "pack" || lower == "items" {
                let back: () -> Void = { [weak self] in self?.askTheDM() }
                let humans = self.party.filter { !$0.isComputerControlled }
                let defaultChar = humans.randomElement() ?? self.party.first!
                self.showInventoryFor(defaultChar, onBack: back, fromDM: true)
                return
            }

            // Party status shortcut
            if lower == "party" || lower == "party status" || lower == "status" || lower == "hp" || lower == "health" {
                self.print("")
                let partySnapshot = self.party
                for idx in 0..<partySnapshot.count {
                    let hp = "\(partySnapshot[idx].currentHP)/\(partySnapshot[idx].maxHP)"
                    let name = partySnapshot[idx].name
                    let low = partySnapshot[idx].currentHP <= partySnapshot[idx].maxHP / 4
                    self.print("  \(name): \(hp) HP", color: low ? .red : .brightGreen)
                }
                self.print("")
                self.dmPromptForQuestion()
                return
            }

            // Torch shortcuts
            if lower == "douse" || lower == "douse torch" || lower == "dark" || lower == "torch off"
                || lower == "turn off" || lower == "extinguish" || lower == "put out" || lower == "snuff" {
                if self.torchLit {
                    self.torchLit = false
                    self.print("")
                    self.print("  You douse the torch. Darkness.", color: .dimGreen)
                    self.print("")
                } else {
                    self.print("")
                    self.print("  The torch is already out.", color: .yellow)
                    self.print("")
                }
                self.dmPromptForQuestion()
                return
            }
            if lower == "illuminate" || lower == "light" || lower == "light torch" || lower == "torch on"
                || lower == "torch" || lower == "turn on" || lower == "ignite"
                || lower == "light up" || lower == "fire up" || lower == "kindle" || lower == "spark" {
                if !self.torchLit {
                    self.torchLit = true
                    self.print("")
                    self.print("  The torch flickers to life, casting dancing shadows.", color: .yellow)
                    self.print("")
                } else {
                    self.print("")
                    self.print("  The torch is already lit.", color: .yellow)
                    self.print("")
                }
                self.dmPromptForQuestion()
                return
            }

            // Listen shortcut
            if lower == "listen" || lower == "listen at door" || lower == "listen at the door" || lower == "hear" {
                self.print("")
                if let room = self.dungeon?.currentRoom {
                    let exits = room.exits.keys.sorted { $0.rawValue < $1.rawValue }
                    if exits.isEmpty {
                        self.print("  You press your ear to the walls... nothing.", color: .dimGreen)
                    } else {
                        for dir in exits {
                            if let nextId = room.exits[dir], let nextRoom = self.dungeon?.rooms[nextId] {
                                if !nextRoom.cleared, nextRoom.encounter != nil {
                                    self.print("  \(dir.rawValue): You hear something moving...", color: .yellow)
                                } else {
                                    self.print("  \(dir.rawValue): Silence.", color: .dimGreen)
                                }
                            }
                        }
                    }
                }
                self.print("")
                self.dmPromptForQuestion()
                return
            }

            // Search shortcut
            if lower == "search" || lower == "search room" || lower == "look" || lower == "look around" || lower == "examine" {
                self.print("")
                if self.torchLit {
                    if let room = self.dungeon?.currentRoom {
                        self.print("  \(room.name)", color: .brightGreen, bold: true)
                        self.print("  \(room.roomDescription)", color: .dimGreen)
                    }
                } else {
                    self.print("  It's too dark to see much. Light a torch!", color: .yellow)
                }
                self.print("")
                self.dmPromptForQuestion()
                return
            }

            // Rest shortcut
            if lower == "rest" || lower == "short rest" || lower == "heal" {
                self.print("")
                var anyHealed = false
                for idx in 0..<self.party.count {
                    let c = self.party[idx]
                    guard c.currentHP < c.maxHP else { continue }
                    let heal = max(1, c.maxHP / 4)
                    c.currentHP = min(c.maxHP, c.currentHP + heal)
                    self.print("  \(c.name) rests and recovers \(heal) HP.", color: .brightGreen)
                    anyHealed = true
                }
                if !anyHealed {
                    self.print("  Everyone is already at full health.", color: .dimGreen)
                }
                self.advanceTime(30)
                self.print("")
                self.dmPromptForQuestion()
                return
            }

            // Save shortcut
            if lower == "save" || lower == "save game" {
                self.quickSave()
                self.print("")
                self.print("  Game saved.", color: .brightGreen)
                self.print("")
                self.dmPromptForQuestion()
                return
            }

            // About screen shortcut
            if lower == "about" {
                self.showAbout(onBack: { [weak self] in self?.askTheDM() })
                return
            }

            // Actions / help shortcut
            if lower == "help" || lower == "?" || lower == "actions" || lower == "what can i do" || lower == "commands" {
                // Show contextual help page, then return to DM prompt
                self.clearTerminal()
                self.printTitle("Exploration Help")
                self.print("")
                self.print("  THE MAP", color: .cyan, bold: true)
                self.printWrapped("@ is your party. Rooms: $ Loot, ! Danger, M Merchant, + Shrine. XX = secured door.", indent: 2, color: .green)
                self.print("")
                self.print("  DIRECTIONS", color: .cyan, bold: true)
                self.printWrapped("Tap N/S/E/W to move. Long-press a direction to secure/unsecure that door.", indent: 2, color: .dimGreen)
                self.print("")
                self.print("  BUTTONS", color: .cyan, bold: true)
                self.printWrapped("Search looks for hidden items. Listen reveals what's beyond exits. Rest (centre) heals — hold for long rest.", indent: 2, color: .dimGreen)
                self.print("")
                self.print("  DM COMMANDS", color: .cyan, bold: true)
                self.printWrapped("inventory, party, map, listen, search, light/douse, rest, save, N/S/E/W, exit", indent: 2, color: .dimGreen)
                self.print("")
                self.print("  TIPS", color: .cyan, bold: true)
                self.printWrapped("Ask the DM anything — describe actions, ask about lore, or request creative solutions. The DM can grant items, heal, or modify the story depending on the ad-lib level.", indent: 2, color: .dimGreen)
                self.print("")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.askTheDM()
                }
                return
            }

            // Map shortcut — show minimap inline
            if lower == "m" || lower == "map" || lower == "where" || lower == "where am i" {
                self.print("")
                if let dungeon = self.dungeon {
                    self.printExplorationMap()
                }
                self.print("")
                self.dmPromptForQuestion()
                return
            }

            // Exit shortcut — leave DM chat mode
            if lower == "exit" || lower == "quit" || lower == "leave"
                || lower == "close" || lower == "back" || lower == "done"
                || lower == "bye" || lower == "goodbye" || lower == "stop" {
                self.handleChatExit()
                return
            }

            // Teleport shortcut — return to dungeon entrance
            if lower == "t" || lower == "teleport" {
                self.applyTeleportToEntrance()
                self.logEvent("Teleported to entrance", category: "DM")
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in
                    self?.askTheDM()
                }
                return
            }

            // Stop any ongoing DM speech from previous response
            SpeechEngine.shared.stop()

            // Interpret N/S/E/W as movement shortcuts
            let directionMap: [String: Direction] = [
                "n": .north, "north": .north, "go north": .north,
                "s": .south, "south": .south, "go south": .south,
                "e": .east, "east": .east, "go east": .east,
                "w": .west, "west": .west, "go west": .west,
            ]
            if let dir = directionMap[lower] {
                // Move but stay in DM mode
                if let dungeon = self.dungeon, let current = dungeon.currentRoom,
                   let nextId = current.exits[dir], let _ = dungeon.rooms[nextId] {
                    let _ = dungeon.move(direction: dir)
                    self.logEvent("Moved \(dir.rawValue)", category: "MOVE")
                    self.roomsSinceLastSave += 1
                    self.tickTorch()
                    self.checkTorchEvent()
                    // Check for encounter
                    if let newRoom = dungeon.currentRoom, !newRoom.cleared, newRoom.encounter != nil {
                        self.returnToDMAfterCombat = true
                        self.askTheDM()
                        return
                    }
                    // Show map and room name inline
                    self.print("")
                    self.printExplorationMap()
                    if let newRoom = dungeon.currentRoom {
                        self.print("")
                        self.print(newRoom.name, color: .brightGreen, bold: true)
                        self.print(newRoom.roomDescription, color: .dimGreen)
                    }
                    self.print("")
                    self.dmPromptForQuestion()
                } else {
                    self.print("")
                    self.print("Can't go that way.", color: .red)
                    self.dmPromptForQuestion()
                }
                return
            }

            self.dmChatLog.append((isUser: true, text: input))
            self.print("")
            self.print("You:", color: .cyan, bold: true)
            self.printWrapped("  \(input)", indent: 2, color: .cyan)
            self.print("")
            self.print("The DM considers...", color: .dimGreen)

            let context = self.buildDMContext()

            DMEngine.shared.ask(input, context: context) { [weak self] response in
                DispatchQueue.main.async {
                    guard let self = self else { return }

                    let result = DMEngine.parseCommands(from: response)
                    let adLibLevel = DMEngine.shared.adLibLevel
                    let displayText = adLibLevel.rawValue >= DMAdLibLevel.moderate.rawValue ? result.cleanText : response

                    self.dmChatLog.append((isUser: false, text: displayText))

                    self.print("")
                    self.print("DM:", color: .yellow, bold: true)
                    for paragraph in displayText.components(separatedBy: "\n") {
                        let trimmed = paragraph.trimmingCharacters(in: .whitespaces)
                        if trimmed.isEmpty { self.print("") }
                        else { self.print("  \(trimmed)", color: .yellow) }
                    }

                    // Apply DM commands at moderate and full levels
                    var worldChanged = false
                    var pendingPickupItems: [Item] = []
                    var pendingGold = 0
                    if adLibLevel.rawValue >= DMAdLibLevel.moderate.rawValue {
                        if result.bonusGold > 0 {
                            pendingGold = result.bonusGold
                            self.print("")
                            self.print("  [Found \(result.bonusGold) gold!]", color: .yellow, bold: true)
                            self.logEvent("DM awarded \(result.bonusGold) bonus gold", category: "DM")
                            worldChanged = true
                        }
                        if result.healAmount > 0 {
                            for char in self.party { char.heal(result.healAmount) }
                            self.print("  [+\(result.healAmount) HP!]", color: .brightGreen, bold: true)
                            self.logEvent("DM healed party for \(result.healAmount) HP", category: "DM")
                            worldChanged = true
                        }
                        if result.damageAmount > 0 {
                            for char in self.party { char.takeDamage(result.damageAmount) }
                            self.print("  [-\(result.damageAmount) HP!]", color: .red, bold: true)
                            self.logEvent("DM dealt \(result.damageAmount) damage to party", category: "DM")
                            worldChanged = true
                        }
                        if result.damagePartyAmount > 0 {
                            for char in self.party { char.takeDamage(result.damagePartyAmount) }
                            self.print("  [-\(result.damagePartyAmount) HP!]", color: .red, bold: true)
                            self.logEvent("DM dealt \(result.damagePartyAmount) damage to party", category: "DM")
                            worldChanged = true
                        }
                        if let dir = result.moveDirection {
                            self.applyDMMovement(dir)
                            worldChanged = true
                        }
                        if result.teleport {
                            self.applyTeleportToEntrance()
                            worldChanged = true
                        }
                        if result.lightTorch {
                            self.applyDMLightTorch()
                            worldChanged = true
                        }
                        if result.douseTorch {
                            self.applyDMDouseTorch()
                            worldChanged = true
                        }
                        if let dir = result.unsecureDirection {
                            self.applyDMUnsecure(dir)
                            worldChanged = true
                        }
                        if let dir = result.secureDirection {
                            self.applyDMSecure(dir)
                            worldChanged = true
                        }
                        // Item commands
                        for itemName in result.grantedItems {
                            if let item = self.resolveItemByName(itemName) {
                                pendingPickupItems.append(item)
                                self.print("  [Found: \(item.name)!]", color: .brightGreen, bold: true)
                            }
                            worldChanged = true
                        }
                        for itemName in result.droppedItems {
                            self.applyDMDropItem(itemName)
                            worldChanged = true
                        }
                        for itemName in result.equippedItems {
                            self.applyDMEquipItem(itemName)
                            worldChanged = true
                        }
                        for itemName in result.usedItems {
                            self.applyDMUseItem(itemName)
                            worldChanged = true
                        }
                    }

                    // Show updated party status after world changes
                    if worldChanged {
                        self.print("")
                        let maxN = self.party.map { $0.name.count }.max() ?? 8
                        for char in self.party {
                            let n = char.name.padding(toLength: maxN, withPad: " ", startingAt: 0)
                            self.print("  \(n)  \(char.currentHP)/\(char.maxHP) HP  \(char.gold)gp", color: .cyan)
                        }

                        // Snapshot after DM commands applied
                        let postSnapshot = StateSnapshot.capture(
                            label: "dm_command",
                            party: self.party,
                            dungeon: self.dungeon,
                            gameTimeMinutes: self.gameTimeMinutes
                        )
                        StateSnapshotManager.shared.write(postSnapshot)
                    }

                    // Auto-apply narrative-implied item changes that lack tags
                    if adLibLevel.rawValue >= DMAdLibLevel.moderate.rawValue {
                        let fallbackApplied = self.applyNarrativeFallbacks(
                            text: result.cleanText,
                            alreadyApplied: result
                        )
                        if fallbackApplied {
                            worldChanged = true
                        }
                    }

                    // Check for remaining missed commands (healing, damage, gold)
                    let missedHints = DMEngine.detectMissedCommands(
                        narrativeText: result.cleanText,
                        appliedResult: result
                    )
                    if !missedHints.isEmpty {
                        self.print("")
                        for hint in missedHints {
                            self.print("  \(hint)", color: .dimGreen)
                        }
                    }

                    // Speak the DM response (only if still in DM mode)
                    if self.inDMMode {
                        SpeechEngine.shared.speak(displayText)
                    }

                    self.print("")
                    self.logEvent("Asked DM: \(input)", category: "DM")

                    if worldChanged {
                        // World changed — handle loot pickup then stay in DM mode
                        self.waitForContinue()
                        self.inputHandler = { [weak self] _ in
                            self?.showLootSequence(gold: pendingGold, goldSource: "DM reward",
                                                   items: pendingPickupItems, itemSource: "DM gift") { [weak self] in
                                self?.askTheDM()
                            }
                        }
                    } else {
                        self.print("(Type another question, or tap Back)", color: .dimGreen)
                        self.dmPromptForQuestion()
                    }
                }
            }
        }
    }

    func askTheDMInCombat(characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        clearTerminal()
        printCombatStatus()
        print("")
        print("DM — describe your action or ask a question:", color: .cyan, bold: true)
        print("(e.g. throw oil from my pack, look for an exit...)", color: .dimGreen)
        print("")

        promptTextWithMenu(">", options: ["Send", "Done"])

        menuHandler = { [weak self] choice in
            if choice == 2 {
                self?.showPlayerCombatMenu(characterId: characterId)
            }
            // choice 1 (Send) handled by view submitting text
        }

        inputHandler = { [weak self] input in
            guard let self = self else { return }

            if self.isReservedWord(input) || input.isEmpty {
                self.showPlayerCombatMenu(characterId: characterId)
                return
            }

            let lower = input.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if lower == "help" || lower == "?" {
                self.clearTerminal()
                self.printTitle("Combat — Help")
                self.print("")
                self.print("  ATTACK", color: .cyan, bold: true)
                self.printWrapped("d20 + mods vs AC. Damage depends on weapon.", indent: 2, color: .dimGreen)
                self.print("")
                self.print("  SPELL", color: .cyan, bold: true)
                self.printWrapped("Cantrips free; levelled spells use slots (recharge on long rest).", indent: 2, color: .dimGreen)
                self.print("")
                self.print("  DODGE", color: .cyan, bold: true)
                self.printWrapped("Enemies have disadvantage attacking you until your next turn.", indent: 2, color: .dimGreen)
                self.print("")
                self.print("  DM IN COMBAT", color: .cyan, bold: true)
                self.printWrapped("Describe creative actions — throw oil, flip a table, taunt an enemy. The DM will interpret and apply results.", indent: 2, color: .dimGreen)
                self.print("")
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { [weak self] _ in
                    self?.askTheDMInCombat(characterId: characterId)
                }
                return
            }

            self.print("")
            self.print("You:", color: .cyan, bold: true)
            self.printWrapped("  \(input)", indent: 2, color: .cyan)
            self.print("")
            self.print("The DM considers...", color: .dimGreen)

            let context = self.buildDMContext(combatContext: combat, activeCharacter: character)

            DMEngine.shared.ask(input, context: context) { [weak self] response in
                DispatchQueue.main.async {
                    guard let self = self else { return }

                    let adLibLevel = DMEngine.shared.adLibLevel
                    let result = DMEngine.parseCommands(from: response)
                    let displayText = result.cleanText

                    self.print("")
                    self.print("DM:", color: .yellow, bold: true)
                    for paragraph in displayText.components(separatedBy: "\n") {
                        let trimmed = paragraph.trimmingCharacters(in: .whitespaces)
                        if trimmed.isEmpty { self.print("") }
                        else { self.print("  \(trimmed)", color: .yellow) }
                    }

                    // Apply DM commands if at moderate+ level
                    var tookAction = false
                    if adLibLevel.rawValue >= DMAdLibLevel.moderate.rawValue {
                        if result.healAmount > 0 {
                            for char in self.party { char.heal(result.healAmount) }
                            self.print("  [+\(result.healAmount) HP!]", color: .brightGreen, bold: true)
                            self.logEvent("DM healed party for \(result.healAmount) HP in combat", category: "DM")
                            tookAction = true
                        }
                        if result.damageAmount > 0 {
                            // In combat, DAMAGE hits the first alive monster
                            if let idx = combat.encounter.monsters.firstIndex(where: { $0.isAlive }) {
                                let name = combat.encounter.monsters[idx].name
                                combat.encounter.monsters[idx].takeDamage(result.damageAmount)
                                self.print("  [\(name) takes \(result.damageAmount) damage!]", color: .brightGreen, bold: true)
                                self.logEvent("DM: \(name) took \(result.damageAmount) damage", category: "DM")
                            }
                            tookAction = true
                        }
                        if result.damagePartyAmount > 0 {
                            // DAMAGE_PARTY hurts the party in combat
                            for char in self.party { char.takeDamage(result.damagePartyAmount) }
                            self.print("  [-\(result.damagePartyAmount) HP!]", color: .red, bold: true)
                            self.logEvent("DM dealt \(result.damagePartyAmount) damage to party in combat", category: "DM")
                            tookAction = true
                        }
                        if result.bonusGold > 0 {
                            self.party.first?.gold += result.bonusGold
                            self.print("  [+\(result.bonusGold) gold!]", color: .yellow, bold: true)
                            self.logEvent("DM awarded \(result.bonusGold) gold in combat", category: "DM")
                            combat.adLibLootGranted = true
                            tookAction = true
                        }
                        for itemName in result.droppedItems {
                            self.applyDMDropItem(itemName)
                            combat.adLibLootGranted = true
                            tookAction = true
                        }
                        for itemName in result.equippedItems {
                            self.applyDMEquipItem(itemName)
                            tookAction = true
                        }
                        for itemName in result.usedItems {
                            self.applyDMUseItem(itemName)
                            tookAction = true
                        }
                        for itemName in result.grantedItems {
                            if let item = self.resolveItemByName(itemName) {
                                if let c = self.party.first, c.canCarry(item) {
                                    _ = c.addItem(item)
                                    self.print("  [Received: \(item.name)!]", color: .brightGreen, bold: true)
                                    self.logEvent("DM gave \(c.name) \(item.name)", category: "DM")
                                    combat.adLibLootGranted = true
                                } else {
                                    self.print("  [Too heavy to carry: \(item.name)]", color: .yellow)
                                }
                            }
                            tookAction = true
                        }
                    }

                    // Auto-apply narrative-implied item changes in combat too
                    if adLibLevel.rawValue >= DMAdLibLevel.moderate.rawValue {
                        let fallbackApplied = self.applyNarrativeFallbacks(
                            text: result.cleanText,
                            alreadyApplied: result
                        )
                        if fallbackApplied { tookAction = true }
                    }

                    // Speak the DM response
                    SpeechEngine.shared.speak(displayText)

                    self.print("")
                    self.logEvent("Asked DM in combat: \(input)", category: "DM")

                    // Stay in DM conversation — don't leave DM mode after each action
                    self.waitForContinue(fullScreenTap: false)
                    self.inputHandler = { [weak self] _ in
                        if tookAction {
                            combat.checkCombatEnd()
                            if combat.state == .victory {
                                self?.handleCombatVictory()
                            } else if combat.state == .defeat {
                                self?.handleCombatDefeat()
                            } else {
                                self?.askTheDMInCombat(characterId: characterId)
                            }
                        } else {
                            self?.askTheDMInCombat(characterId: characterId)
                        }
                    }
                }
            }
        }
    }

    private func buildDMContext(combatContext: Combat? = nil, activeCharacter: Character? = nil) -> DMContext {
        let room = dungeon?.currentRoom
        let exitList = room?.exits.keys.map { $0.rawValue }.joined(separator: ", ") ?? "None"
        let partyStatus = party.map {
            "\($0.name) (\($0.race.rawValue) \($0.characterClass.rawValue)) HP:\($0.currentHP)/\($0.maxHP) Gold:\($0.gold) Reputation:\($0.ethicalAlignment.rawValue)"
        }.joined(separator: "\n")

        let inventorySummary = party.map { char -> String in
            var items = char.inventory.map { $0.name }
            if let w = char.equippedWeapon { items.insert("Equipped: \(w.name)", at: 0) }
            if let a = char.equippedArmor { items.insert("Wearing: \(a.name)", at: 0) }
            return "\(char.name): \(items.isEmpty ? "(empty)" : items.joined(separator: ", "))"
        }.joined(separator: "\n")

        // Treasure in room
        var treasureInfo: String? = nil
        if let room = room, !room.treasure.isEmpty {
            let items = room.treasure.map { "\($0.name) (worth \($0.value) gold)" }
            treasureInfo = "Uncollected treasure: \(items.joined(separator: ", "))"
        }

        // Encounter info
        var encounterInfo: String? = nil
        if let room = room, let encounter = room.encounter {
            if room.cleared {
                let defeated = encounter.monsters.map { $0.name }
                let grouped = Dictionary(grouping: defeated) { $0 }.map { "\($0.value.count) \($0.key)" }
                encounterInfo = "Defeated enemies here: \(grouped.joined(separator: ", "))"
            } else {
                let alive = encounter.aliveMonsters.map { $0.name }
                let grouped = Dictionary(grouping: alive) { $0 }.map { "\($0.value.count) \($0.key)" }
                encounterInfo = "Enemies present: \(grouped.joined(separator: ", "))"
            }
        }

        // Search history
        var searchHistory: String? = nil
        if let room = room, !room.searchedFor.isEmpty {
            searchHistory = "Already searched for: \(room.searchedFor.joined(separator: ", "))"
        }

        var combatSummary: String? = nil
        if let combat = combatContext {
            let aliveMonsters = combat.encounter.aliveMonsters
            let monsterList = aliveMonsters.map { "\($0.name) HP:\($0.currentHP)/\($0.maxHP)" }.joined(separator: ", ")
            let activeInfo = activeCharacter.map { "Active character: \($0.name) (\($0.characterClass.rawValue))" } ?? ""
            combatSummary = """
            Enemies: \(monsterList)
            \(activeInfo)
            The player is asking during their combat turn. They may describe creative actions \
            (throwing items, using environment, intimidating enemies) or ask questions about \
            the battlefield. Describe the outcome vividly but briefly.
            """
        }

        // Build adventure log summary for DM context (configurable, default 128)
        let relevantLog = adventureLog
            .filter { !$0.contains("[SYSTEM]") }
            .suffix(dmLogContextSize)
            .map { String($0) }
        let logSummary: String? = relevantLog.isEmpty ? nil : relevantLog.joined(separator: "\n")

        // Secured exits — explicit state for DM awareness
        var securedInfo: String? = nil
        if let room = room, !room.secured.isEmpty {
            let dirs = room.secured.sorted(by: { $0.rawValue < $1.rawValue }).map { $0.rawValue }
            securedInfo = dirs.joined(separator: ", ")
        }

        // Dropped items on the floor
        var droppedInfo: String? = nil
        if let room = room, !room.droppedItems.isEmpty {
            let items = room.droppedItems.map { $0.name }
            droppedInfo = "Items on the floor: \(items.joined(separator: ", "))"
        }

        // Time limit
        var timeLimitInfo: String? = nil
        if gameTimeLimit > 0 {
            let remaining = max(0, gameTimeLimit - gameTimeMinutes)
            timeLimitInfo = "Time limit: \(formatTimeLimitValue(gameTimeLimit)), \(formatTimeRemaining(remaining))"
        }

        // NPC info
        var npcInfo: String? = nil
        if let room = room, let npc = room.npc {
            let capabilities = [
                npc.type.canTrade && !npc.hasTraded ? "trade" : nil,
                npc.type.canHeal ? "heal" : nil,
                npc.type.canRepair ? "repair" : nil,
                npc.type.canTeach && !npc.hasTaught ? "teach" : nil,
                npc.type.canCurePoison ? "cure poison" : nil,
            ].compactMap { $0 }
            let capStr = capabilities.isEmpty ? "" : " (can: \(capabilities.joined(separator: ", ")))"
            npcInfo = "NPC present: \(npc.type.rawValue)\(capStr) — \(npc.hasBeenTalkedTo ? "already spoken to" : "not yet spoken to")"
        }
        if let room = room, let merchant = room.merchant {
            let merchantLine = "Merchant present: \(merchant.name) of \(merchant.shopName) (\(merchant.tier.rawValue)) — can buy/sell/haggle here."
            npcInfo = npcInfo.map { "\($0)\n\(merchantLine)" } ?? merchantLine
        }

        return DMContext(
            roomName: room?.name ?? "Unknown",
            roomType: room?.roomType.rawValue ?? "Unknown",
            roomDescription: room?.roomDescription ?? "",
            exits: exitList,
            isCleared: room?.cleared ?? false,
            partyStatus: partyStatus,
            gameTime: formattedGameTime(),
            inventorySummary: inventorySummary,
            adLibLevel: DMEngine.shared.adLibLevel,
            treasureInRoom: treasureInfo,
            encounterInfo: encounterInfo,
            searchHistory: searchHistory,
            combatSummary: combatSummary,
            adventureLogSummary: logSummary,
            torchLit: torchLit,
            torchTurnsRemaining: torchTurnsRemaining,
            securedExits: securedInfo,
            dungeonLevel: dungeon?.level ?? 1,
            timeLimit: timeLimitInfo,
            droppedItems: droppedInfo,
            npcInfo: npcInfo,
            justDMMode: isJustDMActive,
            questInfo: dmQuestInfo(),
            knownLore: {
                let entries = loreEntries()
                guard !entries.isEmpty else { return nil }
                return entries.map { "\($0.name): \($0.description)" }.joined(separator: "\n")
            }()
        )
    }

    /// Ask the DM (whichever tier is active — cloud, Apple on-device, or the
    /// Basic keyword DM) to narrate a merchant interaction in that merchant's
    /// voice. The actual game effect (discount, rare item, etc.) is always
    /// resolved separately as a dice/table mechanic — this only ever produces
    /// flavour text, so it degrades gracefully with no AI at all.
    func merchantNarration(_ situation: String, merchant: Merchant, completion: @escaping (String) -> Void) {
        var context = buildDMContext()
        context.npcInfo = "Merchant present: \(merchant.name), proprietor of \(merchant.shopName) (\(merchant.tier.rawValue)). Persona: \(merchant.personaBlurb) Catchphrase: \(merchant.catchphrase) Stay fully in character as this merchant — do not break the persona, do not narrate outside the shop."
        DMEngine.shared.ask(situation, context: context) { response in
            completion(response)
        }
    }

    private func resolveItemByName(_ name: String) -> Item? {
        let lower = name.lowercased()

        // Potions (check specific before generic)
        if lower.contains("superior") && lower.contains("healing") { return ItemCatalog.superiorHealingPotion() }
        if lower.contains("greater") && lower.contains("healing") { return ItemCatalog.greaterHealingPotion() }
        if lower.contains("fire resistance") { return ItemCatalog.potionOfFireResistance() }
        if lower.contains("giant") && lower.contains("strength") { return ItemCatalog.potionOfGiantStrength() }
        if lower.contains("clarity") { return ItemCatalog.elixirOfClarity() }
        if lower.contains("healing") || lower.contains("potion") { return ItemCatalog.healingPotion() }

        // Weapons
        if lower.contains("greataxe") { return ItemCatalog.greataxe() }
        if lower.contains("battleaxe") { return ItemCatalog.battleaxe() }
        if lower.contains("longsword") || lower.contains("long sword") { return ItemCatalog.longsword() }
        if lower.contains("shortsword") || lower.contains("short sword") { return ItemCatalog.shortsword() }
        if lower.contains("longbow") || lower.contains("long bow") { return ItemCatalog.longbow() }
        if lower.contains("light crossbow") || lower.contains("crossbow") { return ItemCatalog.lightCrossbow() }
        if lower.contains("sling") { return ItemCatalog.sling() }
        if lower.contains("rapier") { return ItemCatalog.rapier() }
        if lower.contains("scimitar") { return ItemCatalog.scimitar() }
        if lower.contains("quarterstaff") || lower.contains("staff") { return ItemCatalog.quarterstaff() }
        if lower.contains("handaxe") || lower.contains("hand axe") { return ItemCatalog.handaxe() }
        if lower.contains("warhammer") || lower.contains("war hammer") { return ItemCatalog.warhammer() }
        if lower.contains("trident") { return ItemCatalog.trident() }
        if lower.contains("whip") { return ItemCatalog.whip() }
        if lower.contains("spear") { return ItemCatalog.spear() }
        if lower.contains("mace") { return ItemCatalog.mace() }
        if lower.contains("dagger") || lower.contains("knife") { return ItemCatalog.dagger() }

        // Armor
        if lower.contains("plate") { return ItemCatalog.plateArmor() }
        if lower.contains("chain mail") || lower.contains("chainmail") { return ItemCatalog.chainMail() }
        if lower.contains("ring mail") { return ItemCatalog.ringMail() }
        if lower.contains("scale mail") || lower.contains("scalemail") { return ItemCatalog.scaleMail() }
        if lower.contains("studded leather") { return ItemCatalog.studdedLeather() }
        if lower.contains("padded") { return ItemCatalog.paddedArmor() }
        if lower.contains("leather armor") || lower.contains("leather armour") { return ItemCatalog.leatherArmor() }
        if lower.contains("buckler") { return ItemCatalog.buckler() }
        if lower.contains("shield") { return ItemCatalog.shield() }

        // Misc gear
        if lower.contains("torch") { return ItemCatalog.torch() }
        if lower.contains("rope") { return ItemCatalog.rope() }
        if lower.contains("holy symbol") { return ItemCatalog.holySymbol() }
        if lower.contains("thieve") || lower.contains("lockpick") { return ItemCatalog.thievesTools() }
        if lower.contains("whetstone") || lower.contains("sharpening stone") { return ItemCatalog.whetstone() }
        if lower.contains("spell component") || lower.contains("component pouch") { return ItemCatalog.spellComponentPouch() }

        // Fallback — create a generic misc item so the DM's gift isn't lost
        let cleanName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanName.isEmpty else { return nil }
        return Item(id: UUID(), name: cleanName, description: "A mysterious item from the DM.",
                    type: .misc, weight: 1.0, value: 5,
                    weaponStats: nil, armorStats: nil, potionStats: nil)
    }

    // MARK: - Combat Display

    private func diceArt(_ value: Int) -> [String] {
        let valStr = String(value)
        let pad: String
        if valStr.count == 1 {
            pad = " \(valStr) "
        } else if valStr.count == 2 {
            pad = " \(valStr)"
        } else {
            pad = valStr
        }
        return [
            "      ┌─────┐",
            "      │ \(pad) │",
            "      └─────┘",
        ]
    }

    /// Render attacker vs defender side-by-side with weapon flourish
    private func renderBattleScene(_ report: AttackReport) {
        let attArt = report.attackerArt
        let defArt = report.defenderArt
        let maxLines = max(attArt.count, defArt.count)

        // Pad each art to a fixed width for alignment
        let attWidth = attArt.map { $0.count }.max() ?? 0
        let defWidth = defArt.map { $0.count }.max() ?? 0
        let padAtt = max(attWidth, 10)

        // Weapon attack animations (center column)
        let weaponLower = report.weaponName.lowercased()
        let attackFrames: [String]
        if weaponLower.contains("bow") || weaponLower.contains("crossbow") {
            attackFrames = ["  ---->  ", "  =====> ", "  --*--> "]
        } else if weaponLower.contains("staff") || weaponLower.contains("quarterstaff") {
            attackFrames = ["  |===|  ", "  |===*  ", "   *==|  "]
        } else if weaponLower.contains("dagger") || weaponLower.contains("rapier") {
            attackFrames = ["   -->   ", "   -=>>  ", "   --*>  "]
        } else if weaponLower.contains("great") || weaponLower.contains("maul") {
            attackFrames = ["  >==>   ", "  >===>  ", "  >=*=>  "]
        } else if weaponLower.contains("axe") || weaponLower.contains("hatchet") {
            attackFrames = ["   )=>   ", "   )==>  ", "   )=*>  "]
        } else {
            // Default sword/melee slash
            attackFrames = ["   \\     ", "    \\    ", "  ---*   "]
        }

        let attackColor: TerminalColor = report.isPlayerAttack ? .brightGreen : .red
        let defendColor: TerminalColor = report.isPlayerAttack ? .red : .brightGreen

        // Print scene header
        let attLabel = report.attackerName
        let defLabel = report.targetName
        let headerGap = String(repeating: " ", count: max(0, padAtt - attLabel.count + 5))
        print("\(attLabel)\(headerGap)\(defLabel)", color: .cyan, bold: true)
        print("")

        // Render side-by-side with animation frames
        for i in 0..<maxLines {
            let leftLine = i < attArt.count ? attArt[i] : ""
            let rightLine = i < defArt.count ? defArt[i] : ""
            let leftPadded = leftLine.padding(toLength: padAtt, withPad: " ", startingAt: 0)

            let midFrame = i < attackFrames.count ? attackFrames[i] : "         "
            // Show attacker in attack color, weapon in yellow, defender in defend color
            print("  \(leftPadded)\(midFrame)\(rightLine)", color: i < attackFrames.count ? .yellow : attackColor)
        }
        print("")
    }

    /// Show an impact frame on the defender when hit
    private func renderHitImpact(_ report: AttackReport) {
        guard hitAnimationsEnabled else { return }
        let defArt = report.defenderArt
        let impactColor: TerminalColor = report.isCritical ? .yellow : .red

        // Impact sparks surrounding the defender
        let sparkPatterns: [[String]] = [
            ["  \\*/  ", "  -*=  ", "  /*/  "],
            ["  */\\  ", "  =*-  ", "  \\*\\  "],
            ["  |*|  ", "  *-*  ", "  |*|  "],
        ]
        let sparks = sparkPatterns[Int.random(in: 0..<sparkPatterns.count)]
        let midPoint = defArt.count / 2

        print("")
        for (i, line) in defArt.enumerated() {
            if i >= midPoint - 1 && i <= midPoint + 1 {
                let sparkIdx = i - (midPoint - 1)
                print(" \(sparks[sparkIdx])\(line)", color: impactColor, bold: true)
            } else {
                print("       \(line)", color: impactColor)
            }
        }
    }

    /// Show the defender collapsing when defeated — eyes replaced with x
    private func renderDefeatFrame(_ report: AttackReport) {
        guard hitAnimationsEnabled else { return }
        let defArt = report.defenderArt.map { deadEyes($0) }
        // "Collapse" the art by shifting each line right progressively and dimming
        print("")
        for (i, line) in defArt.enumerated() {
            let shift = String(repeating: " ", count: i)
            if i == defArt.count - 1 {
                // Last line = fallen
                print("  \(shift)\(line)  x_x", color: .dimGreen)
            } else {
                print("  \(shift)\(line)", color: .dimGreen)
            }
        }
    }

    /// Replace eye characters in ASCII art with "x" for a dead look
    private func deadEyes(_ line: String) -> String {
        var result = line
        for pattern in Self.eyePatterns {
            if result.contains(pattern.find) {
                let dead = pattern.find.unicodeScalars.map { c -> String in
                    let ch = Swift.Character(c)
                    return (ch == "o" || ch == "O" || ch == "@" || ch == ".") ? "x" : String(ch)
                }.joined()
                result = result.replacingOccurrences(of: pattern.find, with: dead)
                break
            }
        }
        return result
    }

    func displayAttackReport(_ report: AttackReport, completion: @escaping () -> Void) {
        arenaPlayAttack(report)
        let attackColor: TerminalColor = report.isPlayerAttack ? .brightGreen : .red

        // Show animated battle scene
        renderBattleScene(report)

        // Play weapon-appropriate sound
        let wn = report.weaponName.lowercased()
        if wn.contains("bow") || wn.contains("crossbow") {
            SoundManager.shared.playArrowShot()
        } else if wn.contains("staff") || wn.contains("quarterstaff") {
            SoundManager.shared.playStaffStrike()
        } else {
            SoundManager.shared.playSwordSwing()
        }

        print("\(report.attackerName) attacks \(report.targetName) with \(report.weaponName)!", color: attackColor, bold: true)
        print("")
        print("  To Hit: d20 + \(report.attackModifier)", color: .cyan)
        print("  (\(report.modifierBreakdown))", color: .dimGreen)
        print("  Target AC: \(report.targetAC)", color: .dimGreen)
        print("")

        // Phase 2: Dice roll (after delay)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) { [weak self] in
            guard let self = self else { return }

            self.printLines(self.diceArt(report.d20Roll), color: .yellow)
            let sign = report.attackModifier >= 0 ? "+" : ""
            self.print("  d20 -> [\(report.d20Roll)] \(sign)\(report.attackModifier) = \(report.totalAttack) vs AC \(report.targetAC)", color: .cyan)
            self.print("")

            if report.isCritical {
                SoundManager.shared.playCrit()
                self.printLines(self.asciiCriticalHit, color: report.isPlayerAttack ? .yellow : .red)
                self.renderHitImpact(report)
                self.print("")
                self.print("  NATURAL 20 -- CRITICAL HIT!", color: .yellow, bold: true)
            } else if report.isCriticalMiss {
                SoundManager.shared.playMiss()
                self.printLines(self.asciiMiss, color: .dimGreen)
                self.print("")
                self.print("  Natural 1 -- Critical Miss!", color: .red)
            } else if report.hits {
                if report.isPlayerAttack {
                    SoundManager.shared.playHit()
                    self.printLines(self.asciiHit(attacker: report.attackerName, target: report.targetName), color: .brightGreen)
                } else {
                    SoundManager.shared.playMonsterAttack()
                    self.printLines(self.asciiMonsterAttack, color: .red)
                }
                self.renderHitImpact(report)
                self.print("")
                self.print("  HIT!", color: .brightGreen, bold: true)
            } else {
                SoundManager.shared.playMiss()
                self.printLines(self.asciiMiss, color: .dimGreen)
                self.print("")
                self.print("  Miss.", color: .dimGreen)
            }
            self.print("")

            // Phase 3: Damage (if hit)
            if report.hits, let rolls = report.damageRolls, let totalDmg = report.totalDamage {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
                    guard let self = self else { return }

                    let diceStr = report.damageDice ?? "?"
                    let modVal = report.damageModifier ?? 0
                    let modSign = modVal >= 0 ? "+" : ""

                    if report.isCritical {
                        self.print("  Damage: \(diceStr) \(modSign)\(modVal) (critical!)", color: .cyan)
                    } else {
                        self.print("  Damage: \(diceStr) \(modSign)\(modVal)", color: .cyan)
                    }

                    let diceTotal = rolls.reduce(0, +)
                    self.printLines(self.diceArt(diceTotal), color: .red)

                    if rolls.count <= 3 {
                        let rollStr = rolls.map { "[\($0)]" }.joined(separator: "+")
                        self.print("  \(rollStr) \(modSign)\(modVal) = \(totalDmg) damage!", color: report.isPlayerAttack ? .brightGreen : .red)
                    } else {
                        self.print("  \(totalDmg) damage!", color: report.isPlayerAttack ? .brightGreen : .red)
                    }
                    self.print("")

                    if report.targetDefeated {
                        SoundManager.shared.playDeath()
                        self.renderDefeatFrame(report)
                        self.print("  \(report.targetName) is defeated!", color: .yellow, bold: true)
                        self.quickNextContinue = true
                    } else if report.targetUnconscious {
                        SoundManager.shared.playDeath()
                        self.renderDefeatFrame(report)
                        self.print("  \(report.targetName) falls unconscious!", color: .red, bold: true)
                    } else {
                        self.print("  \(report.targetName): \(report.targetCurrentHP)/\(report.targetMaxHP) HP", color: .dimGreen)
                    }

                    if report.poisonApplied {
                        if self.poisonEnabled {
                            self.print("")
                            self.print("  POISONED! \(report.targetName) has been poisoned!", color: .magenta, bold: true)
                            self.print("  (takes damage each turn until cured or it wears off)", color: .dimGreen)
                        } else {
                            // Poison disabled — immediately cure
                            if let char = self.party.first(where: { $0.name == report.targetName }), char.isPoisoned {
                                char.curePoison()
                            }
                        }
                    }
                    if let brokenWeapon = report.brokenWeaponName {
                        self.print("")
                        self.print("  \(report.targetName)'s \(brokenWeapon) breaks blocking the blow!", color: .red, bold: true)
                        self.print("  It's been stowed, broken — a smith can repair it.", color: .dimGreen)
                    }
                    self.print("")

                    self.logMultiplayerAttackReport(report)
                    self.waitForContinue(fullScreenTap: false)
                    self.inputHandler = { _ in completion() }
                }
            } else {
                self.logMultiplayerAttackReport(report)
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { _ in completion() }
            }
        }
    }

    /// Log an attack report as a multiplayer action for remote player catch-up
    private func logMultiplayerAttackReport(_ report: AttackReport) {
        guard isMultiplayer else { return }
        var desc: String
        if report.hits, let damage = report.totalDamage {
            if report.isCritical {
                desc = "\(report.attackerName) CRITS \(report.targetName) with \(report.weaponName) — \(damage) damage!"
            } else {
                desc = "\(report.attackerName) hits \(report.targetName) with \(report.weaponName) — \(damage) damage"
            }
            if report.targetDefeated {
                desc += " — \(report.targetName) defeated!"
            } else if report.targetUnconscious {
                desc += " — \(report.targetName) falls unconscious!"
            } else {
                desc += " (\(report.targetCurrentHP)/\(report.targetMaxHP) HP)"
            }
        } else {
            desc = "\(report.attackerName) attacks \(report.targetName) — MISS"
        }
        multiplayerState?.addAction(
            playerName: report.isPlayerAttack ? report.attackerName : "Monster",
            description: desc
        )
    }

    private func logMultiplayerSpellReport(_ report: SpellReport) {
        guard isMultiplayer else { return }
        var desc: String
        switch report.spellType {
        case .healing:
            desc = "\(report.casterName) casts \(report.spellName) — heals \(report.healAmount) HP!"
        case .attack, .savingThrow, .autoHit:
            if report.totalDamage > 0 {
                desc = "\(report.casterName) casts \(report.spellName) — \(report.totalDamage) damage!"
                for defeated in report.targetsDefeated {
                    desc += " \(defeated) defeated!"
                }
            } else {
                desc = "\(report.casterName) casts \(report.spellName) — no effect"
            }
        case .buff:
            desc = "\(report.casterName) casts \(report.spellName)!"
        case .utility:
            desc = "\(report.casterName) casts \(report.spellName) on \(report.targetName ?? "ally")"
        }
        multiplayerState?.addAction(playerName: report.casterName, description: desc)
    }

    // MARK: - Combat

    func startCombat(encounter: Encounter) {
        gameState = .combat
        let renames = ensureUniqueNames()   // two of the same name muddle a fight
        combatHesitating = false
        cancelCombatIdleTimer()

        // Balance monster ACs for ~65% hit rate (medium encounters)
        var balanced = encounter
        let avgAttackBonus: Int = {
            guard !party.isEmpty else { return 4 }
            let total = party.map { char -> Int in
                let strMod = char.abilityScores.modifier(for: .strength)
                let dexMod = char.abilityScores.modifier(for: .dexterity)
                let weaponMod = (char.equippedWeapon?.weaponStats?.isRanged == true ||
                                 (char.equippedWeapon?.weaponStats?.isFinesse == true && dexMod > strMod))
                    ? dexMod : strMod
                return weaponMod + char.proficiencyBonus
            }.reduce(0, +)
            return total / party.count
        }()
        balanced.balanceAC(partyAvgAttackBonus: avgAttackBonus)

        // Apply difficulty scale (custom difficulty levels) and the dynamic
        // party-skill multiplier to monster HP. The skill multiplier also
        // nudges attack bonus up — a growing party should face monsters that
        // hit a bit harder too, not just soak more damage — but only when
        // it's pushing difficulty UP, so the initial Easy/Medium/Hard choice
        // still only affects HP as before.
        let skillMultiplier = partySkillMultiplier
        let hpScale = difficultyScale * skillMultiplier
        if hpScale != 1.0 {
            for i in balanced.monsters.indices {
                let scaledHP = max(1, Int(Double(balanced.monsters[i].maxHP) * hpScale))
                balanced.monsters[i].maxHP = scaledHP
                balanced.monsters[i].currentHP = scaledHP
            }
        }
        if skillMultiplier > 1.0 {
            let attackBonusBoost = Int(((skillMultiplier - 1.0) * 5).rounded())
            for i in balanced.monsters.indices {
                balanced.monsters[i].attackBonus += attackBonusBoost
            }
        }

        currentCombat = Combat(party: party, encounter: balanced)
        arenaMove = nil
        isHandlingCombatVictory = false
        if self.musicEnabled { SoundManager.shared.startMusic(.combat, preference: self.combatMelodyChoice) }
        SoundManager.shared.playBattleStart()
        checkTorchBlowout()

        let monsterNames = encounter.monsters.map { $0.name }.joined(separator: ", ")
        logEvent("Battle! Encountered \(monsterNames)", category: "COMBAT")
        logMultiplayerAction("Encountered \(monsterNames)!")

        clearTerminal()
        combatLogBuffer = []
        combatLogShowing = true   // this fight's running account starts here
        suppressAutoScroll = false
        printLines(asciiSwords, color: .red)
        print("")
        printTitle("COMBAT!")
        for remark in renames { printWrapped(remark, indent: 2, color: .cyan) }
        readingPaceNext = true   // time to read (or hear) what has appeared

        // Group monsters by type for cleaner display
        var monsterCounts: [(type: MonsterType, count: Int)] = []
        for monster in encounter.monsters {
            if let idx = monsterCounts.firstIndex(where: { $0.type == monster.type }) {
                monsterCounts[idx].count += 1
            } else {
                monsterCounts.append((type: monster.type, count: 1))
            }
        }
        for group in monsterCounts {
            printLines(group.type.asciiArt, color: .red)
            if group.count > 1 {
                print("\(group.count) \(group.type.rawValue)s appear!", color: .red)
            } else {
                print("\(group.type.rawValue) appears!", color: .red)
            }
            print("  \(group.type.description)", color: .green)
            print("")
        }

        // Boss difficulty flavor text
        if let bossDiff = encounter.bossDifficulty {
            let bossName = encounter.monsters.first?.name ?? "The boss"
            switch bossDiff {
            case .easy:
                print("\(bossName) looks weakened...", color: .yellow)
            case .medium:
                break
            case .hard:
                print("\(bossName) looks fearsome!", color: .red, bold: true)
            }
            print("")
        }
        print("Rolling initiative...")
        print("")

        if let combat = currentCombat {
            for entry in combat.turnOrder {
                print("  \(entry.name): \(entry.initiative)")
            }
        }

        waitForContinue(fullScreenTap: false)
        inputHandler = { [weak self] _ in
            self?.advanceCombat()
        }
    }

    func runCombatTurn() {
        guard let combat = currentCombat else { return }

        // Check combat end
        if combat.state == .victory {
            handleCombatVictory()
            return
        } else if combat.state == .defeat {
            handleCombatDefeat()
            return
        }

        guard let current = combat.currentCombatant else {
            combat.nextTurn()
            runCombatTurn()
            return
        }

        combatPageBreak()
        printCombatStatus()
        print("")

        if current.isPlayer {
            // Clear dodge at start of turn (dodge only lasts until your next turn)
            if let character = party.first(where: { $0.id == current.id }) {
                character.isDodging = false
                if character.willpowerSurgeImmuneTurns > 0 {
                    character.willpowerSurgeImmuneTurns -= 1
                }
            }

            // Check if character fled or is playing dead
            if let character = party.first(where: { $0.id == current.id }),
               (character.hasFledCombat || character.isPlayingDead) {
                // Skip their turn
                combat.nextTurn()
                runCombatTurn()
                return
            }

            // Tick poison at start of turn
            if let character = party.first(where: { $0.id == current.id }),
               character.isPoisoned {
                let poisonResult = character.tickPoison()
                if poisonResult.cured && poisonResult.damage == 0 {
                    print("  \(character.name) shakes off the poison!", color: .brightGreen, bold: true)
                } else if poisonResult.damage > 0 {
                    print("  \(character.name) takes \(poisonResult.damage) poison damage!", color: .magenta)
                    print("  (\(character.currentHP)/\(character.maxHP) HP)", color: .dimGreen)
                    if poisonResult.cured {
                        print("  The poison wears off.", color: .brightGreen)
                    }
                }
                if !character.isConscious {
                    combat.checkCombatEnd()
                    if combat.state == .defeat {
                        handleCombatDefeat()
                        return
                    }
                }
                print("")
            }

            // Check if unconscious — death saving throw instead of normal turn
            if let character = party.first(where: { $0.id == current.id }),
               !character.isConscious {
                showDeathSavingThrow(character: character)
            } else if let character = party.first(where: { $0.id == current.id }),
                      character.isMindControlled {
                performMindControlledTurn(character: character, combat: combat)
            } else if let character = party.first(where: { $0.id == current.id }),
                      character.isComputerControlled {
                runAICombatTurn(character: character)
            } else {
                showPlayerCombatMenu(characterId: current.id)
            }
        } else {
            switch combat.runMonsterTurn() {
            case .attack(let report):
                displayAttackReport(report) { [weak self] in
                    guard let self = self else { return }
                    combat.checkCombatEnd()
                    combat.nextTurn()
                    self.advanceCombat()
                }
            case .mindControl(let attempt):
                resolveMindControlAttempt(attempt, combat: combat) { [weak self] in
                    guard let self = self else { return }
                    combat.checkCombatEnd()
                    combat.nextTurn()
                    self.advanceCombat()
                }
            case nil:
                combat.nextTurn()
                advanceCombat()
            }
        }
    }

    // MARK: - AI Combat Turn

    /// Average of a dice expression like "2d6+1" (for comparing weapons and potions).
    private func averageDamage(_ dice: String) -> Double {
        var total = 0.0
        for part in dice.lowercased().replacingOccurrences(of: " ", with: "").split(separator: "+") {
            if part.contains("d") {
                let bits = part.split(separator: "d", omittingEmptySubsequences: false)
                let count = Double(bits.first ?? "1") ?? 1
                let sides = Double(bits.last ?? "4") ?? 4
                total += count * (sides + 1) / 2
            } else {
                total += Double(part) ?? 0
            }
        }
        return total
    }

    func runAICombatTurn(character: Character) {
        guard let combat = currentCombat else { return }

        let aliveMonsters = combat.encounter.aliveMonsters
        guard !aliveMonsters.isEmpty else { return }

        print("\(character.name) considers...", color: .cyan, bold: true)
        print("")

        // Decision priority:
        // 0. If poisoned and very hurt, try to use antidote/potion or play dead
        // 1. Barbarian: Rage if not raging and has uses
        // 2. Cleric: Heal if any ally below 30% HP
        // 3. Fighter: Second Wind if below 40% HP
        // 4. Attack the weakest (lowest HP) monster

        // 0. Poisoned — seek antidote or healing potion, or play dead
        if character.isPoisoned {
            // Try antidote first
            let antidoteIdx = character.inventory.firstIndex(where: {
                $0.name.lowercased().contains("antidote")
            })
            if let idx = antidoteIdx {
                let antidote = character.inventory[idx]
                character.inventory.remove(at: idx)
                character.curePoison()
                print("  \(character.name) drinks an \(antidote.name)!", color: .brightGreen)
                print("  Poison cured!", color: .brightGreen)
                logMultiplayerAction("\(character.name) uses antidote — poison cured!")
                combat.nextTurn()
                waitForContinue(fullScreenTap: false)
                inputHandler = { [weak self] _ in self?.advanceCombat() }
                return
            }

            // Try to find and use a healing potion
            let potionIdx = character.inventory.firstIndex(where: {
                $0.name.lowercased().contains("potion") && $0.name.lowercased().contains("heal")
            })
            if let idx = potionIdx {
                let potion = character.inventory[idx]
                let healAmt = Dice.rollSum(2, d: 4) + 2
                character.heal(healAmt)
                character.inventory.remove(at: idx)
                print("  \(character.name) drinks a \(potion.name)! (+\(healAmt) HP)", color: .brightGreen)
                logMultiplayerAction("\(character.name) drinks \(potion.name) (+\(healAmt) HP)")
                character.curePoison()
                print("  The poison is cleansed!", color: .brightGreen)
                combat.nextTurn()
                waitForContinue(fullScreenTap: false)
                inputHandler = { [weak self] _ in self?.advanceCombat() }
                return
            }

            // Very hurt and poisoned — might play dead
            let hpPercent = Double(character.currentHP) / Double(character.maxHP)
            if hpPercent < 0.25 {
                print("  \(character.name) is badly poisoned and collapses, playing dead!", color: .yellow)
                logMultiplayerAction("\(character.name) collapses, playing dead!")
                character.isPlayingDead = true
                combat.nextTurn()
                waitForContinue(fullScreenTap: false)
                inputHandler = { [weak self] _ in self?.advanceCombat() }
                return
            }
        }

        // 1. Barbarian Rage
        if character.characterClass == .barbarian && !character.isRaging && character.rageUsesRemaining > 0 {
            print("  \(character.name) enters a furious RAGE!", color: .red, bold: true)
            logMultiplayerAction("\(character.name) enters a furious RAGE!")
            activateRage(character: character)
            return
        }

        // 1b. Badly hurt: something from their own pack — a potion, an
        //     elixir, a salve, or a bite to eat.
        if character.currentHP < character.maxHP * 35 / 100 {
            let usable = character.inventory.filter { $0.type == .potion && $0.potionStats?.healAmount != nil }
            if let item = usable.max(by: { averageDamage($0.potionStats?.healAmount ?? "0") < averageDamage($1.potionStats?.healAmount ?? "0") }),
               let healStr = item.potionStats?.healAmount {
                character.removeItem(item)
                let amount = max(1, Dice.rollDamage(healStr).total)
                character.heal(amount)
                let lower = item.name.lowercased()
                let verb = lower.contains("salve") || lower.contains("balm") ? "rubs on" : ItemCatalog.consumeVerb(for: item)
                print("  \(character.name) \(verb) the \(item.name)! (+\(amount) HP — \(character.currentHP)/\(character.maxHP))", color: .brightGreen)
                logMultiplayerAction("\(character.name) \(verb) \(item.name) (+\(amount) HP)")
                combat.nextTurn()
                waitForContinue(fullScreenTap: false)
                inputHandler = { [weak self] _ in self?.advanceCombat() }
                return
            }
        }

        // 1c. The party's losing badly and there's nothing left to heal with:
        //     sometimes a companion calls the retreat.
        let standing = party.filter { $0.isConscious }
        let partyHP = standing.reduce(0) { $0 + $1.currentHP }
        let partyMaxHP = max(1, standing.reduce(0) { $0 + $1.maxHP })
        let monsterHP = aliveMonsters.reduce(0) { $0 + $1.currentHP }
        let anyHealing = party.contains { c in
            c.inventory.contains { $0.potionStats?.healAmount != nil } || c.knownSpells.contains { $0.spellType == .healing }
        }
        if Double(partyHP) / Double(partyMaxHP) < 0.25, monsterHP > partyHP, !anyHealing, Int.random(in: 1...100) <= 50 {
            print("  \(character.name) shouts: \"Run for it!\"", color: .yellow, bold: true)
            logMultiplayerAction("\(character.name) calls for a retreat")
            attemptRunAway()
            return
        }

        // 1d. A clearly better weapon in the pack (or nothing in hand): swap to it.
        let currentAvg = character.equippedWeapon.flatMap { $0.weaponStats?.damage }.map { averageDamage($0) } ?? 1
        if let better = character.inventory.filter({ $0.type == .weapon && !$0.broken })
            .max(by: { averageDamage($0.weaponStats?.damage ?? "0") < averageDamage($1.weaponStats?.damage ?? "0") }),
           averageDamage(better.weaponStats?.damage ?? "0") > currentAvg + 1, Int.random(in: 1...100) <= 60 {
            character.removeItem(better)
            if let old = character.equippedWeapon {
                character.equippedWeapon = nil
                _ = character.addItem(old)
            }
            character.equipWeapon(better)
            print("  \(character.name) swaps to the \(better.name).", color: .cyan)
            logMultiplayerAction("\(character.name) swaps to \(better.name)")
            combat.nextTurn()
            waitForContinue(fullScreenTap: false)
            inputHandler = { [weak self] _ in self?.advanceCombat() }
            return
        }

        // 2. Healing — anyone with a healing spell (Cleric, Bard, Ranger) helps
        //    a conscious ally below 30% HP.
        if character.knownSpells.contains(where: { $0.spellType == .healing }) {
            let woundedAlly = party.first(where: {
                $0.isConscious && $0.currentHP < $0.maxHP * 30 / 100
            })
            if let ally = woundedAlly {
                // Try to cast a healing spell
                let spells = character.knownSpells
                let slots = character.spellSlots.level1Current
                let foundHealSpell: Spell? = spells.first(where: { (s: Spell) -> Bool in
                    s.spellType == .healing && (s.level == .cantrip || slots > 0)
                })
                if let healSpell = foundHealSpell {
                    let msg = "  \(character.name) casts \(healSpell.name) on \(ally.name)!"
                    print(msg, color: .brightGreen)
                    let allyId = ally.id
                    if let report = combat.castSpell(casterId: character.id, spell: healSpell, targetIds: [allyId]) {
                        displaySpellReport(report) { [weak self] in
                            combat.checkCombatEnd()
                            combat.nextTurn()
                            self?.advanceCombat()
                        }
                        return
                    }
                }
            }
        }

        // 3. Fighter Second Wind when hurt
        if character.characterClass == .fighter && !character.secondWindUsed
            && character.currentHP < character.maxHP * 40 / 100 {
            print("  \(character.name) uses Second Wind!", color: .brightGreen)
            logMultiplayerAction("\(character.name) uses Second Wind!")
            useSecondWind(character: character)
            return
        }

        // 4. Spellcaster: use an attack cantrip or spell on weakest monster
        if character.characterClass == .wizard || character.characterClass == .ranger || character.characterClass == .bard {
            let weakestMonster = aliveMonsters.min(by: { $0.currentHP < $1.currentHP })!
            let atkSpells = character.knownSpells
            let atkSlots = character.spellSlots.level1Current
            let foundAttackSpell: Spell? = atkSpells.first(where: { (s: Spell) -> Bool in
                // Bards fight with words: a single-target saving-throw cantrip (Vicious Mockery) counts too.
                (s.spellType == .attack || (character.characterClass == .bard && s.spellType == .savingThrow && s.target == .singleEnemy))
                    && (s.level == .cantrip || atkSlots > 0)
            })
            if let attackSpell = foundAttackSpell {
                let atkMsg = "  \(character.name) casts \(attackSpell.name)!"
                print(atkMsg, color: .yellow)
                let targetId = weakestMonster.id
                if let report = combat.castSpell(casterId: character.id, spell: attackSpell, targetIds: [targetId]) {
                    displaySpellReport(report) { [weak self] in
                        combat.checkCombatEnd()
                        combat.nextTurn()
                        self?.advanceCombat()
                    }
                    return
                }
            }
        }

        // 5. Default: attack the weakest monster
        let target = aliveMonsters.min(by: { $0.currentHP < $1.currentHP })!
        if let report = combat.playerAttack(characterId: character.id, targetId: target.id) {
            let weaponName = character.equippedWeapon?.name ?? "fists"
            print("  \(character.name) attacks \(target.name) with \(weaponName)!", color: .brightGreen)
            displayAttackReport(report) { [weak self] in
                combat.checkCombatEnd()
                combat.nextTurn()
                self?.advanceCombat()
            }
        } else {
            // Fallback: skip turn
            combat.nextTurn()
            advanceCombat()
        }
    }

    func showPlayerCombatMenu(characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        // Just DM mode — DM-driven combat
        if isJustDMActive {
            showJustDMCombatTurn(characterId: characterId)
            return
        }

        print(">> \(character.name)'s turn! <<", color: .brightGreen, bold: true)
        print("")

        let aliveMonsters = combat.encounter.aliveMonsters
        var options: [String] = []
        var actions: [() -> Void] = []

        // Build display names that distinguish duplicate monsters
        let monsterDisplayNames = Combat.numberedMonsterNames(aliveMonsters)

        // Attack options
        for (i, monster) in aliveMonsters.enumerated() {
            let monsterRef = monster
            options.append("Attack \(monsterDisplayNames[i])")
            actions.append { [weak self] in
                guard let self = self else { return }
                let hasDisadvantage = self.combatHesitating
                self.combatHesitating = false
                let isSluggish = (self.party.first(where: { $0.id == characterId })?.sluggishAttacks ?? 0) > 0
                if let report = combat.playerAttack(characterId: characterId, targetId: monsterRef.id, disadvantage: hasDisadvantage) {
                    self.combatPageBreak()
                    self.printCombatStatus()
                    self.print("")
                    if hasDisadvantage {
                        self.print("  (Disadvantage — you hesitated!)", color: .yellow)
                        self.print("")
                    } else if isSluggish {
                        self.print("  (Disadvantage — sloshing with juice!)", color: .yellow)
                        self.print("")
                    }
                    self.displayAttackReport(report) { [weak self] in
                        combat.checkCombatEnd()
                        combat.nextTurn()
                        self?.advanceCombat()
                    }
                }
            }
        }

        // Change Weapon — costs the turn, small chance of fumbling it. Only
        // shown when there's an actual alternative carried in the pack.
        if character.inventory.contains(where: { $0.type == .weapon }) {
            options.append("Change Weapon")
            actions.append { [weak self] in
                self?.showCombatChangeWeaponMenu(characterId: characterId)
            }
        }

        // Cast Spell (spellcasters with spells)
        if !character.knownSpells.isEmpty {
            let hasCantrips = character.knownSpells.contains { $0.level == .cantrip }
            let hasSlots = character.spellSlots.level1Current > 0 || character.spellSlots.level2Current > 0
            if hasCantrips || hasSlots {
                let slotInfo = character.spellSlots.isEmpty ? "" : " [\(character.spellSlots.level1Current)]"
                options.append("Spell\(slotInfo)")
                actions.append { [weak self] in
                    self?.showSpellMenu(characterId: characterId)
                }
            }
        }

        // Use Potion — drink or administer a healing potion (or antidote) to
        // yourself or any ally. Takes the whole turn, same as Cast Spell.
        // Only offered when this character is actually carrying something
        // usable — a Whetstone alone doesn't count, that's not a heal.
        if character.inventory.contains(where: { $0.potionStats?.healAmount != nil || $0.name.lowercased().contains("antidote") || ItemCatalog.foodKind(for: $0) != nil }) {
            options.append("Use Potion")
            actions.append { [weak self] in
                self?.showCombatUsePotionMenu(characterId: characterId)
            }
        }

        // Fighter: Second Wind
        if character.characterClass == .fighter && !character.secondWindUsed {
            options.append("Second Wind")
            actions.append { [weak self] in
                self?.useSecondWind(character: character)
            }
        }

        // Barbarian: Rage
        if character.characterClass == .barbarian && character.rageUsesRemaining > 0 && !character.isRaging {
            options.append("Rage!")
            actions.append { [weak self] in
                self?.activateRage(character: character)
            }
        }

        // Dodge
        options.append("Dodge")
        actions.append { [weak self] in
            guard let self = self else { return }
            self.combatPageBreak()
            self.printCombatStatus()
            self.print("")
            self.printLines(self.asciiDodge, color: .cyan)
            self.print("")
            character.isDodging = true
            self.logMultiplayerAction("\(character.name) takes a defensive stance (Dodge)")
            self.print("\(character.name) takes a defensive stance!", color: .cyan, bold: true)
            self.print("  Enemies attacking \(character.name) have DISADVANTAGE", color: .dimGreen)
            self.print("  (they roll twice, take the worse result)", color: .dimGreen)
            combat.checkCombatEnd()
            combat.nextTurn()
            self.waitForContinue(fullScreenTap: false)
            self.inputHandler = { [weak self] _ in self?.advanceCombat() }
        }

        // Play Dead
        options.append("Play Dead")
        actions.append { [weak self] in
            self?.attemptPlayDead(characterId: characterId)
        }

        // Run Away
        options.append("Run Away!")
        actions.append { [weak self] in
            self?.attemptRunAway()
        }

        // Help — pinned (not a regular option) so it always shares the
        // compact nav cell with << / >> on every page, instead of being just
        // another paginated item that could get bumped to a later page once
        // there are enough combat actions to need pagination (leaving a page
        // with ">>" but no "?").
        showPaginatedMenu(options, pinned: ["?"], pinnedHandler: { [weak self] _ in
            self?.cancelCombatIdleTimer()
            self?.showCombatHelp(characterId: characterId)
        }, handler: { [weak self] idx in
            self?.cancelCombatIdleTimer()
            if idx >= 0 && idx < actions.count {
                actions[idx]()
            }
        })
        resetIdleTimer()
        startCombatIdleTimer(characterId: characterId)
    }

    /// "Use Potion" combat action — drink or administer a healing potion
    /// (or antidote) to yourself or any ally, mirroring showUsePotionMenu's
    /// effects but ending the turn afterward instead of returning to the
    /// Pack screen, since this is a full combat action.
    private func showCombatUsePotionMenu(characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }
        let potions = character.inventory.filter { $0.potionStats?.healAmount != nil || $0.name.lowercased().contains("antidote") || ItemCatalog.foodKind(for: $0) != nil }
        guard !potions.isEmpty else { showPlayerCombatMenu(characterId: characterId); return }

        clearTerminal()
        printCombatStatus()
        print("")
        printTitle("Use Potion")
        for char in party where char.isConscious {
            let hpPct = char.maxHP > 0 ? Double(char.currentHP) / Double(char.maxHP) : 1.0
            let color: TerminalColor = hpPct <= 0.33 ? .red : hpPct <= 0.66 ? .yellow : .dimGreen
            print("  \(shortName(for: char)): \(char.currentHP)/\(char.maxHP) HP\(char.isPoisoned ? " (poisoned)" : "")", color: color)
        }
        print("")
        for potion in potions {
            if let effect = potion.potionStats?.effect {
                print("  \(potion.name): \(effect)", color: .dimGreen)
            } else {
                print("  \(potion.name): cures poison", color: .dimGreen)
            }
        }
        print("")

        closeHandler = { [weak self] in self?.showPlayerCombatMenu(characterId: characterId) }
        showPaginatedMenu(potions.map { $0.name }, pinned: ["< Back"], pinnedHandler: { [weak self] _ in
            self?.showPlayerCombatMenu(characterId: characterId)
        }, handler: { [weak self] idx in
            guard let self = self, idx >= 0 && idx < potions.count else { return }
            let potion = potions[idx]

            let applyAndEndTurn: (Character) -> Void = { target in
                character.removeItem(potion)
                let isAntidote = potion.name.lowercased().contains("antidote")
                self.print("")
                if isAntidote {
                    if target.isPoisoned {
                        target.curePoison()
                        self.print("  \(target.name) drinks the antidote! Poison cured!", color: .brightGreen)
                        self.logMultiplayerAction("\(target.name) uses antidote — poison cured!")
                    } else {
                        self.print("  \(target.name) drinks the antidote. (Not poisoned — no effect.)", color: .dimGreen)
                    }
                } else if let food = self.consumeFood(potion, by: target) {
                    for (line, color) in food.lines { self.print("  \(line)", color: color) }
                    self.logMultiplayerAction(food.summary)
                } else if let healStr = potion.potionStats?.healAmount {
                    let roll = Dice.rollDamage(healStr)
                    let amount = max(1, roll.total)
                    target.heal(amount)
                    self.print("  \(target.name) drinks \(potion.name)! Restored \(amount) HP! (\(target.currentHP)/\(target.maxHP))", color: .brightGreen)
                    if target.isPoisoned {
                        target.curePoison()
                        self.print("  Poison also cured!", color: .brightGreen)
                    }
                    self.logMultiplayerAction("\(target.name) drinks \(potion.name) — restored \(amount) HP")
                }
                combat.checkCombatEnd()
                combat.nextTurn()
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { [weak self] _ in self?.advanceCombat() }
            }

            if self.party.filter({ $0.isConscious }).count > 1 {
                self.pickCharacter(title: "Give the \(potion.name) to whom?", onBack: {
                    self.showCombatUsePotionMenu(characterId: characterId)
                }) { target in
                    applyAndEndTurn(target)
                }
            } else {
                applyAndEndTurn(character)
            }
        })
    }

    /// Weapon picker for the "Change Weapon" combat action — see
    /// performCombatWeaponChange() for what actually happens on selection.
    private func showCombatChangeWeaponMenu(characterId: UUID) {
        guard let character = party.first(where: { $0.id == characterId }) else { return }
        // Exclude whatever's already equipped — "swapping" to the same
        // weapon has nothing to show and would still risk the fumble chance
        // in performCombatWeaponChange() for no reason.
        let weapons = character.inventory.filter { $0.type == .weapon && $0.id != character.equippedWeapon?.id }
        guard !weapons.isEmpty else { showPlayerCombatMenu(characterId: characterId); return }

        clearTerminal()
        printCombatStatus()
        print("")
        printTitle("Change Weapon")
        print("  Wielding: \(character.equippedWeapon?.name ?? "bare hands")", color: .dimGreen)
        print("  Switching weapons costs your turn, and there's a small chance you fumble the draw.", color: .yellow)
        print("")

        showMenu(weapons.map { $0.name } + ["< Back"])
        closeHandler = { [weak self] in self?.showPlayerCombatMenu(characterId: characterId) }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == weapons.count + 1 {
                self.showPlayerCombatMenu(characterId: characterId)
                return
            }
            guard choice >= 1 && choice <= weapons.count else { return }
            self.performCombatWeaponChange(characterId: characterId, newWeapon: weapons[choice - 1])
        }
    }

    /// Actually swaps the weapon (or fumbles it — ~15% chance the new
    /// weapon is dropped instead of equipped) and ends the character's
    /// turn. Mutates character.equippedWeapon directly on the live
    /// Character instance shared by both `party` and `combat.party` (same
    /// object references — playerAttack() reads equippedWeapon fresh on
    /// every attack, not a snapshot taken at combat start), so the new
    /// weapon is what subsequent attacks in THIS combat immediately use —
    /// no separate "reload" step needed. logEvent/logMultiplayerAction
    /// make sure it's visible in the adventure log and multiplayer feed
    /// like any other combat action, rather than only being reflected in
    /// state silently.
    private func performCombatWeaponChange(characterId: UUID, newWeapon: Item) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        clearTerminal()
        printCombatStatus()
        print("")

        let fumbled = Int.random(in: 1...100) <= 15
        if fumbled {
            character.removeItem(newWeapon)
            dungeon?.currentRoom?.droppedItems.append(newWeapon)
            print("  \(character.name) fumbles drawing \(newWeapon.name) — it slips free and clatters to the floor!", color: .yellow, bold: true)
            print("  (\(newWeapon.name) can be found with a search once the fight is over.)", color: .dimGreen)
            logEvent("\(character.name) fumbled changing to \(newWeapon.name) — dropped it", category: "COMBAT")
            logMultiplayerAction("\(character.name) fumbled switching weapons and dropped \(newWeapon.name)!")
        } else {
            let oldWeaponName = character.equippedWeapon?.name ?? "bare hands"
            character.equipWeapon(newWeapon)
            print("  \(character.name) swaps \(oldWeaponName) for \(newWeapon.name)!", color: .brightGreen, bold: true)
            logEvent("\(character.name) switched weapon to \(newWeapon.name)", category: "COMBAT")
            logMultiplayerAction("\(character.name) switched weapons — now wielding \(newWeapon.name)")
        }
        print("")

        combat.checkCombatEnd()
        combat.nextTurn()
        waitForContinue(fullScreenTap: false)
        inputHandler = { [weak self] _ in self?.advanceCombat() }
    }

    // MARK: - Combat Idle Timer

    /// Your turn in combat and nothing's happening: a gentle nudge — twice
    /// at most, worded differently each time — on what you can do.
    private var combatNudgeTimer: Timer?

    private func scheduleCombatNudge(characterId: UUID, count: Int) {
        guard count < 2 else { return }
        combatNudgeTimer = Timer.scheduledTimer(withTimeInterval: count == 0 ? 20 : 45, repeats: false) { [weak self] _ in
            guard let self = self, self.currentCombat != nil, !self.awaitingContinue, !self.currentMenuOptions.isEmpty,
                  let character = self.party.first(where: { $0.id == characterId }) else { return }
            // Frozen: the enemy waits too — try again later.
            if self.timeFrozen { self.scheduleCombatNudge(characterId: characterId, count: count); return }
            let name = self.shortName(for: character)
            let opener = Self.pickVaried([
                "Your move, \(name)!",
                "\(name), the enemy is waiting...",
                "What will \(name) do?",
                "\(name) — act now, or the moment passes!",
                "Steady, \(name). What's the plan?",
            ], avoiding: &self.lastCombatNudge)
            let how = [
                "Tap one of the buttons below — or type its name at the > prompt (e.g. \"attack\").",
                "Pick an action from the buttons below, or type it at the > prompt.",
                "Choose from the buttons below, or type what you want to do at the > prompt.",
            ].randomElement()!
            let talk = [
                "Type \"chat\" to talk tactics with your party or ask the DM — you'll come straight back to the fight.",
                "Want advice? Type \"chat\" to ask your companions or the DM, then carry on fighting.",
                "Type \"chat\" to confer with the party and the DM; the fight will wait for you.",
            ].randomElement()!
            self.print("")
            self.print("  \(opener)", color: .cyan, bold: true)
            self.printWrapped(how, indent: 4, color: .dimGreen)
            self.printWrapped(talk, indent: 4, color: .dimGreen)
            self.scheduleCombatNudge(characterId: characterId, count: count + 1)
        }
    }

    private func startCombatIdleTimer(characterId: UUID) {
        cancelCombatIdleTimer()
        scheduleCombatNudge(characterId: characterId, count: 0)
        guard idlePromptsEnabled else { return }
        combatIdleTimer = Timer.scheduledTimer(withTimeInterval: 300.0, repeats: false) { [weak self] _ in
            guard let self = self, let combat = self.currentCombat else { return }
            // No hesitation penalty while time is frozen.
            if self.timeFrozen { self.startCombatIdleTimer(characterId: characterId); return }
            // First warning at 2 min — disadvantage on next attack
            if !self.combatHesitating {
                self.combatHesitating = true
                self.print("")
                self.print("  You hesitate... the enemy senses your indecision!", color: .red)
                self.print("  (Disadvantage on your next attack)", color: .yellow)
                self.logEvent("Combat hesitation — disadvantage applied", category: "COMBAT")

                // Second timer at 60s more — monster gets a free attack
                self.combatIdleTimer = Timer.scheduledTimer(withTimeInterval: 120.0, repeats: false) { [weak self] _ in
                    guard let self = self, let combat = self.currentCombat else { return }
                    let aliveMonsters = combat.encounter.aliveMonsters
                    guard let attacker = aliveMonsters.randomElement(),
                          let character = self.party.first(where: { $0.id == characterId && $0.isConscious }) else { return }

                    self.print("")
                    self.print("  \(attacker.name) seizes the opening and strikes!", color: .red, bold: true)
                    self.logEvent("\(attacker.name) free attack — player too slow", category: "COMBAT")

                    if let report = combat.monsterAttack(monsterId: attacker.id, targetId: character.id) {
                        self.displayAttackReport(report) { [weak self] in
                            guard let self = self else { return }
                            combat.checkCombatEnd()
                            if combat.state == .defeat {
                                self.handleCombatDefeat()
                            } else {
                                // Re-show the player's combat menu — still their turn
                                self.showPlayerCombatMenu(characterId: characterId)
                            }
                        }
                    } else {
                        self.showPlayerCombatMenu(characterId: characterId)
                    }
                }
            }
        }
    }

    private func cancelCombatIdleTimer() {
        combatIdleTimer?.invalidate()
        combatIdleTimer = nil
        combatNudgeTimer?.invalidate()
        combatNudgeTimer = nil
    }

    // MARK: - Run Away

    func attemptRunAway() {
        guard let combat = currentCombat else { return }

        clearTerminal()
        printCombatStatus()
        print("")
        print("The party attempts to flee!", color: .yellow, bold: true)
        print("")

        // Each conscious party member rolls DEX check
        // DC = 10 + highest monster DEX-like bonus (simplified: attackBonus / 2)
        let monsterDC = 10 + (combat.encounter.aliveMonsters.map { $0.attackBonus / 2 }.max() ?? 0)
        print("  Escape DC: \(monsterDC)", color: .cyan)
        print("")

        var successes = 0
        var total = 0
        for char in party where char.isConscious {
            total += 1
            let roll = Dice.d20()
            let dexMod = char.abilityScores.modifier(for: .dexterity)
            let result = roll + dexMod
            let passed = result >= monsterDC
            if passed { successes += 1 }
            print("  \(char.name): [\(roll)]+\(dexMod) = \(result) \(passed ? "OK" : "FAIL")",
                  color: passed ? .brightGreen : .red)
        }

        print("")

        // Need majority to escape
        let escaped = successes > total / 2

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self = self else { return }

            if escaped {
                self.print("You escape!", color: .brightGreen, bold: true)
                self.logMultiplayerAction("The party fled from combat!")
                self.print("")

                // Take opportunity attacks — each monster gets one free hit on a random party member
                let opportunityHits = min(combat.encounter.aliveMonsters.count, 1)
                if opportunityHits > 0, let monster = combat.encounter.aliveMonsters.first,
                   let target = self.party.filter({ $0.isConscious }).randomElement() {
                    let dmg = max(1, Dice.rollDamage(monster.damage).total)
                    target.takeDamage(dmg)
                    self.print("  \(monster.name) strikes as you flee!", color: .red)
                    self.print("  \(target.name) takes \(dmg) damage!", color: .red)
                    self.print("")
                }

                // Fleeing exhaustion — everyone loses some HP from the desperate sprint
                self.print("  The desperate sprint takes its toll...", color: .yellow)
                for char in self.party where char.isConscious {
                    let exhaustion = max(1, Dice.d4())
                    char.takeDamage(exhaustion)
                    self.print("  \(char.name) loses \(exhaustion) HP from exhaustion", color: .yellow)
                }
                self.print("")

                // Combat cleanup
                for char in self.party {
                    char.isRaging = false
                    char.huntersMarkActive = false
                    char.hasFledCombat = false
                    char.isPlayingDead = false
                    char.curePoison()
                }
                self.currentCombat = nil
                self.gameState = .exploring

                if self.musicEnabled { SoundManager.shared.startMusic(.exploration, preference: self.explorationMelodyChoice) }

                // Let the player choose which direction to flee
                guard let dungeon = self.dungeon, let room = dungeon.currentRoom else {
                    self.showExplorationView()
                    return
                }

                self.print("Which way do you run?", color: .cyan, bold: true)
                self.print("")

                var fleeOptions: [String] = []
                var fleeDirections: [Direction] = []
                for dir in Direction.allCases {
                    if room.exits[dir] != nil && !room.secured.contains(dir) {
                        fleeOptions.append(dir.rawValue)
                        fleeDirections.append(dir)
                    }
                }
                // Add "keep running" option — run in a straight line as far as possible
                fleeOptions.append("Keep Running!")

                self.showMenu(fleeOptions)
                self.menuHandler = { [weak self] choice in
                    guard let self = self else { return }
                    let idx = choice - 1
                    if idx < fleeDirections.count {
                        // Move one room in chosen direction
                        let dir = fleeDirections[idx]
                        self.move(dir)
                    } else {
                        // Keep running — pick a random valid direction and run as far as possible
                        self.keepRunning()
                    }
                }
            } else {
                self.print("You can't escape!", color: .red, bold: true)
                self.print("The monsters block your path!")
                self.print("")

                // Monsters get a free round of attacks
                combat.nextTurn()

                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { [weak self] _ in
                    self?.advanceCombat()
                }
            }
        }
    }

    /// Keep running — flee in a straight line as far as possible
    private func keepRunning() {
        guard let dungeon = dungeon, let startRoom = dungeon.currentRoom else {
            showExplorationView()
            return
        }

        // Pick a random valid direction to start running
        let validDirs = Direction.allCases.filter { dir in
            startRoom.exits[dir] != nil && !startRoom.secured.contains(dir)
        }
        guard let runDir = validDirs.randomElement() else {
            showExplorationView()
            return
        }

        clearTerminal()
        print("You keep running \(runDir.rawValue.lowercased())!", color: .yellow, bold: true)
        print("")

        var roomsTraversed = 0
        var currentRoom = startRoom

        // Run in a straight line until no more exits in that direction (max 5 rooms)
        while roomsTraversed < 5 {
            guard let nextRoomId = currentRoom.exits[runDir],
                  let nextRoom = dungeon.rooms[nextRoomId],
                  !currentRoom.secured.contains(runDir) else {
                break
            }

            // Stop if there's a monster in the next room (unless it's cleared)
            if nextRoom.encounter != nil && !nextRoom.cleared {
                print("  Danger ahead — you skid to a halt!", color: .red)
                break
            }

            dungeon.currentRoom = nextRoom
            nextRoom.visited = true
            currentRoom = nextRoom
            roomsTraversed += 1
            advanceTime(2)
            print("  ...through the \(nextRoom.name.lowercased())...", color: .dimGreen)
        }

        print("")
        if roomsTraversed > 0 {
            print("You ran through \(roomsTraversed) room\(roomsTraversed == 1 ? "" : "s") \(runDir.rawValue.lowercased()).", color: .brightGreen)
            logEvent("Fled \(runDir.rawValue.lowercased()) through \(roomsTraversed) rooms", category: "COMBAT")
        } else {
            print("Nowhere to run \(runDir.rawValue.lowercased()) — you stop here.", color: .yellow)
        }

        autoReturn()
    }

    // MARK: - Play Dead

    func attemptPlayDead(characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        clearTerminal()
        printCombatStatus()
        print("")
        print("\(character.name) collapses dramatically, playing dead!", color: .yellow, bold: true)
        print("")

        // Performance check: CHA or Deception-based
        // Higher success chance than Run Away (DC 8 instead of DC 10)
        let chaMod = character.abilityScores.modifier(for: .charisma)
        let profBonus = character.skillProficiencies.contains(.deception) ? character.proficiencyBonus : 0
        let roll = Dice.d20()
        let total = roll + chaMod + profBonus
        let dc = 8 + (combat.encounter.aliveMonsters.map { $0.attackBonus / 3 }.max() ?? 0)

        let profStr = profBonus > 0 ? " + Deception +\(profBonus)" : ""
        print("  Performance: d20 + CHA \(chaMod >= 0 ? "+" : "")\(chaMod)\(profStr)", color: .cyan)
        print("  [\(roll)] + \(chaMod + profBonus) = \(total) vs DC \(dc)", color: .cyan)
        print("")

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self = self else { return }

            if total >= dc {
                // Success — monster reaction
                let reactions = [
                    "The monsters glance at the fallen body and lose interest.",
                    "A creature sniffs at \(character.name) suspiciously... then wanders off.",
                    "The enemies step over what they think is a corpse.",
                    "\(character.name) lies perfectly still. The monsters look elsewhere.",
                ]
                self.print(reactions.randomElement()!, color: .brightGreen)
                self.print("")
                self.print("  \(character.name) is out of the fight (playing dead).", color: .dimGreen)

                character.isPlayingDead = true

                // Check if all party members are out of the fight
                let activeFighters = self.party.filter {
                    $0.isConscious && !$0.isPlayingDead && !$0.hasFledCombat
                }
                if activeFighters.isEmpty {
                    // Everyone is out — end combat, retreat to previous room
                    self.print("")
                    self.print("With no one left fighting, the monsters lose interest.", color: .yellow)

                    for char in self.party {
                        char.isPlayingDead = false
                        char.hasFledCombat = false
                        char.isRaging = false
                        char.huntersMarkActive = false
                    }
                    self.currentCombat = nil
                    self.gameState = .exploring

                    if let dungeon = self.dungeon, let prevRoom = dungeon.previousRoom {
                        dungeon.currentRoom = prevRoom
                        self.print("  You quietly retreat to the \(prevRoom.name).", color: .dimGreen)
                    }

                    if self.musicEnabled { SoundManager.shared.startMusic(.exploration, preference: self.explorationMelodyChoice) }
                    let shouldReturnToDM = self.returnToDMAfterCombat
                    self.returnToDMAfterCombat = false
                    self.print("")
                    self.waitForContinue(fullScreenTap: false)
                    self.inputHandler = { [weak self] _ in
                        if shouldReturnToDM {
                            self?.askTheDM()
                        } else {
                            self?.showExplorationView()
                        }
                    }
                } else {
                    combat.nextTurn()
                    self.waitForContinue(fullScreenTap: false)
                    self.inputHandler = { [weak self] _ in self?.advanceCombat() }
                }
            } else {
                // Failed — monster sees through the ruse
                let reactions = [
                    "The creature isn't fooled! It kicks \(character.name) roughly.",
                    "A monster prods \(character.name) with a weapon. \"Not dead yet!\"",
                    "The ruse fails! The enemies aren't buying it.",
                ]
                self.print(reactions.randomElement()!, color: .red)

                // Take a hit as punishment
                if let monster = combat.encounter.aliveMonsters.randomElement() {
                    let dmg = max(1, Dice.rollDamage(monster.damage).total / 2)
                    character.takeDamage(dmg)
                    self.print("  \(character.name) takes \(dmg) damage!", color: .red)
                    self.print("  (\(character.currentHP)/\(character.maxHP) HP)", color: .dimGreen)
                }
                self.print("")

                combat.checkCombatEnd()
                combat.nextTurn()
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { [weak self] _ in self?.advanceCombat() }
            }
        }
    }

    // MARK: - Spell Casting UI

    func showSpellMenu(characterId: UUID) {
        guard let combat = currentCombat,
              let character = party.first(where: { $0.id == characterId }) else { return }

        clearTerminal()
        printCombatStatus()
        print("")
        print("Choose a spell:", color: .brightGreen, bold: true)
        print("")

        let cantrips = character.knownSpells.filter { $0.level == .cantrip }
        let level1Spells = character.knownSpells.filter { $0.level == .level1 && character.canCastSpell($0) }
        let level2Spells = character.knownSpells.filter { $0.level == .level2 && character.canCastSpell($0) }

        var spellOptions: [Spell] = []

        if !cantrips.isEmpty {
            print("  CANTRIPS (unlimited):", color: .cyan, bold: true)
            for c in cantrips {
                print("    \(c.name) — \(c.description)", color: .dimGreen)
            }
            spellOptions.append(contentsOf: cantrips)
            print("")
        }

        if !level1Spells.isEmpty {
            let l1 = character.spellSlots.level1Current
            let l1m = character.spellSlots.level1Max
            print("  LEVEL 1 (slots: \(l1)/\(l1m)):", color: .cyan, bold: true)
            for s in level1Spells {
                print("    \(s.name) — \(s.description)", color: .dimGreen)
            }
            spellOptions.append(contentsOf: level1Spells)
            print("")
        }

        if !level2Spells.isEmpty {
            let l2 = character.spellSlots.level2Current
            let l2m = character.spellSlots.level2Max
            print("  LEVEL 2 (slots: \(l2)/\(l2m)):", color: .cyan, bold: true)
            for s in level2Spells {
                print("    \(s.name) — \(s.description)", color: .dimGreen)
            }
            spellOptions.append(contentsOf: level2Spells)
            print("")
        }

        let menuOpts = spellOptions.map { $0.name }

        showPaginatedMenuOptions(menuOpts, pinned: ["< Done"], handler: { [weak self] idx in
            guard idx >= 0 && idx < spellOptions.count else { return }
            let spell = spellOptions[idx]
            self?.selectSpellTarget(characterId: characterId, spell: spell)
        }, pinnedHandler: { [weak self] _ in
            self?.clearTerminal()
            self?.printCombatStatus()
            self?.print("")
            self?.showPlayerCombatMenu(characterId: characterId)
        })
    }

    func selectSpellTarget(characterId: UUID, spell: Spell) {
        guard let combat = currentCombat else { return }

        // AoE spells target all enemies automatically
        if spell.target == .allEnemies {
            let targetIds = combat.encounter.aliveMonsters.map { $0.id }
            executeSpell(characterId: characterId, spell: spell, targetIds: targetIds)
            return
        }

        // Self/buff spells
        if spell.target == .self_ {
            executeSpell(characterId: characterId, spell: spell, targetIds: [characterId])
            return
        }

        // Healing/utility — target allies
        if spell.target == .singleAlly {
            clearTerminal()
            printCombatStatus()
            print("")
            print("Choose target for \(spell.name):", color: .cyan)
            print("")

            var options: [String] = []
            for char in party {
                let status = char.isConscious ? "\(char.currentHP)/\(char.maxHP) HP" : "Unconscious"
                options.append("\(shortName(for: char)) (\(status))")
            }
            options.append("Done")

            showMenu(options)
            menuHandler = { [weak self] choice in
                if choice == options.count {
                    self?.showSpellMenu(characterId: characterId)
                    return
                }
                guard choice > 0 && choice <= self?.party.count ?? 0 else { return }
                let targetId = self?.party[choice - 1].id ?? UUID()
                self?.executeSpell(characterId: characterId, spell: spell, targetIds: [targetId])
            }
            return
        }

        // Single enemy target
        let aliveMonsters = combat.encounter.aliveMonsters
        if aliveMonsters.count == 1 {
            executeSpell(characterId: characterId, spell: spell, targetIds: [aliveMonsters[0].id])
            return
        }

        clearTerminal()
        printCombatStatus()
        print("")
        print("Choose target for \(spell.name):", color: .cyan)
        print("")

        let monsterNames = Combat.numberedMonsterNames(aliveMonsters)
        var options = aliveMonsters.enumerated().map { "\(monsterNames[$0.offset]) (\($0.element.currentHP)/\($0.element.maxHP) HP)" }
        options.append("Done")

        showMenu(options)
        menuHandler = { [weak self] choice in
            if choice == options.count {
                self?.showSpellMenu(characterId: characterId)
                return
            }
            guard choice > 0 && choice <= aliveMonsters.count else { return }
            self?.executeSpell(characterId: characterId, spell: spell, targetIds: [aliveMonsters[choice - 1].id])
        }
    }

    // MARK: Incantations
    //
    // Now and then the words matter: the caster picks the incantation. The
    // true words (always the same for a spell, so they can be learned) cast
    // it — sometimes with a surge that spends no slot; the wrong ones fizzle
    // or backfire. Arcane gyms teach the true words for good.

    private static let incantationFirst = ["Ignis", "Lux", "Vox", "Aqua", "Terra", "Ventus", "Umbra", "Arcanum", "Fulmen", "Vita", "Glacies", "Sanctus"]
    private static let incantationSecond = ["Magna", "Venite", "Ardeo", "Fiat", "Protego", "Surgo", "Revelo", "Tueor", "Frango", "Sano", "Ligo", "Volo"]

    /// The true words for a spell — fixed per spell (a stable hash of its
    /// name, not Swift's per-launch hashValue).
    static func trueIncantation(for spell: Spell) -> String {
        let seed = spell.name.unicodeScalars.reduce(0) { ($0 &* 31 &+ Int($1.value)) & 0x7fffffff }
        return "\(incantationFirst[seed % incantationFirst.count]) \(incantationSecond[(seed / 13) % incantationSecond.count])"
    }

    func executeSpell(characterId: UUID, spell: Spell, targetIds: [UUID]) {
        guard let caster = party.first(where: { $0.id == characterId }) else { return }
        let chance = spell.level == .cantrip ? 15 : 35
        if !caster.knownIncantations.contains(spell.name), Int.random(in: 1...100) <= chance {
            showIncantationChoice(caster: caster, spell: spell, targetIds: targetIds)
            return
        }
        performSpell(characterId: characterId, spell: spell, targetIds: targetIds, surge: false)
    }

    private func showIncantationChoice(caster: Character, spell: Spell, targetIds: [UUID]) {
        guard let combat = currentCombat else { return }
        let truth = Self.trueIncantation(for: spell)
        var decoys = Set<String>()
        while decoys.count < 2 {
            let decoy = "\(Self.incantationFirst.randomElement()!) \(Self.incantationSecond.randomElement()!)"
            if decoy != truth { decoys.insert(decoy) }
        }
        let choices = ([truth] + Array(decoys)).shuffled()
        clearTerminal()
        printCombatStatus()
        print("")
        print("\(caster.name) raises a hand to cast \(spell.name)...", color: .brightGreen, bold: true)
        printWrapped("The words matter. Which incantation?", indent: 2, color: .cyan)
        print("")
        showMenu(choices.map { "\"\($0)!\"" })
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= choices.count else { return }
            let said = choices[choice - 1]
            self.print("")
            if said == truth {
                let surge = Int.random(in: 1...100) <= 25
                self.print("  \"\(said)!\" — the words ring true.", color: .brightGreen)
                if surge { self.print("  ✦ The magic surges! (No spell slot spent.)", color: .magenta, bold: true) }
                self.logEvent("\(caster.name) spoke the true words for \(spell.name)\(surge ? " — and it surged" : "")", category: "COMBAT")
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { [weak self] _ in
                    self?.performSpell(characterId: caster.id, spell: spell, targetIds: targetIds, surge: surge)
                }
            } else {
                // Wrong words: the slot's spent either way.
                if spell.level != .cantrip { caster.spellSlots.useSlot(level: spell.level) }
                if Bool.random() {
                    self.print("  \"\(said)!\" — nothing. The spell fizzles.", color: .yellow)
                    self.logEvent("\(caster.name)'s \(spell.name) fizzled (wrong words)", category: "COMBAT")
                } else {
                    let hurt = max(1, Dice.rollDamage("1d4").total)
                    caster.takeDamage(hurt)
                    self.print("  \"\(said)!\" — the magic backfires! \(caster.name) takes \(hurt) damage. (\(caster.currentHP)/\(caster.maxHP) HP)", color: .red)
                    self.logEvent("\(caster.name)'s \(spell.name) backfired (wrong words)", category: "COMBAT")
                }
                self.printWrapped("(The true words were \"\(truth)\" — an arcane gym can teach them for good.)", indent: 2, color: .dimGreen)
                combat.checkCombatEnd()
                combat.nextTurn()
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { [weak self] _ in self?.advanceCombat() }
            }
        }
    }

    private func performSpell(characterId: UUID, spell: Spell, targetIds: [UUID], surge: Bool) {
        guard let combat = currentCombat else { return }

        guard let report = combat.castSpell(casterId: characterId, spell: spell, targetIds: targetIds) else { return }
        if surge, let caster = party.first(where: { $0.id == characterId }) {
            // The magic surged: give back the slot the cast just used.
            switch spell.level {
            case .level1: caster.spellSlots.level1Current = min(caster.spellSlots.level1Max, caster.spellSlots.level1Current + 1)
            case .level2: caster.spellSlots.level2Current = min(caster.spellSlots.level2Max, caster.spellSlots.level2Current + 1)
            default: break
            }
        }

        clearTerminal()
        printCombatStatus()
        print("")

        displaySpellReport(report) { [weak self] in
            combat.checkCombatEnd()
            combat.nextTurn()
            self?.advanceCombat()
        }
    }

    /// ASCII art frames for spell casting animation
    private func spellCastArt(spellType: SpellType) -> [[String]] {
        switch spellType {
        case .attack:
            return [
                ["       *        ",
                 "      ***       ",
                 "     *****      ",
                 "      ***       ",
                 "       *        "],
                ["      .*.       ",
                 "     .***.      ",
                 "    .*****.     ",
                 "     .***.      ",
                 "      .*.       "],
                ["     ~ * ~      ",
                 "    ~ *** ~     ",
                 "   ~ ***** ~    ",
                 "    ~ *** ~     ",
                 "     ~ * ~      "],
            ]
        case .healing:
            return [
                ["       +        ",
                 "      +++       ",
                 "     +++++      ",
                 "      +++       ",
                 "       +        "],
                ["      .+.       ",
                 "     .+++.      ",
                 "    .+++++.     ",
                 "     .+++.      ",
                 "      .+.       "],
            ]
        default:
            return [
                ["      ~ ~       ",
                 "     ~   ~      ",
                 "    ~  o  ~     ",
                 "     ~   ~      ",
                 "      ~ ~       "],
                ["     . ~ .      ",
                 "    .     .     ",
                 "   .   O   .    ",
                 "    .     .     ",
                 "     . ~ .      "],
            ]
        }
    }

    func displaySpellReport(_ report: SpellReport, completion: @escaping () -> Void) {
        arenaPlaySpell(report)
        // Every spell cast — the player's own and companions' — gets its whoosh here.
        SoundManager.shared.playSpellCast()
        logMultiplayerSpellReport(report)

        // Show spell casting animation if hit animations are on
        if hitAnimationsEnabled {
            let artFrames = spellCastArt(spellType: report.spellType)
            let artColor: TerminalColor = report.spellType == .healing ? .brightGreen : (report.spellType == .attack ? .red : .cyan)
            let firstFrame = artFrames[0]
            printLines(firstFrame, color: artColor)
            let artStart = terminalLines.count - firstFrame.count

            // Animate through frames
            var frameIdx = 0
            Timer.scheduledTimer(withTimeInterval: 0.25, repeats: true) { [weak self] timer in
                DispatchQueue.main.async {
                    guard let self = self else { timer.invalidate(); return }
                    frameIdx += 1
                    if frameIdx >= artFrames.count * 2 {
                        timer.invalidate()
                        return
                    }
                    let frame = artFrames[frameIdx % artFrames.count]
                    for (i, line) in frame.enumerated() {
                        let lineIdx = artStart + i
                        if lineIdx < self.terminalLines.count {
                            self.terminalLines[lineIdx].text = line
                        }
                    }
                }
            }
        }

        print("\(report.casterName) casts \(report.spellName)!", color: .cyan, bold: true)
        print("")

        DispatchQueue.main.asyncAfter(deadline: .now() + (hitAnimationsEnabled ? 1.0 : 0.5)) { [weak self] in
            guard let self = self else { return }

            switch report.spellType {
            case .attack:
                if let d20 = report.d20Roll {
                    self.printLines(self.diceArt(d20), color: .yellow)
                    let bonus = report.attackBonus ?? 0
                    self.print("  d20 -> [\(d20)] +\(bonus) = \(report.totalAttack ?? 0) vs AC \(report.targetAC ?? 0)", color: .cyan)
                    self.print("")
                    if report.isCritical {
                        self.print("  CRITICAL HIT!", color: .yellow, bold: true)
                    } else if report.hits == true {
                        self.print("  HIT!", color: .brightGreen, bold: true)
                    } else {
                        self.print("  Miss.", color: .dimGreen)
                    }
                }

            case .savingThrow:
                self.print("  Save DC: \(report.saveDC ?? 0)", color: .cyan)
                for save in report.saveResults {
                    self.print("  \(save.targetName): [\(save.roll)] +mod = \(save.total) — \(save.saved ? "SAVED" : "FAILED")",
                               color: save.saved ? .dimGreen : .red)
                }

            case .autoHit:
                if report.damageType == "sleep" {
                    self.print("  Sleep power: \(report.totalDamage) HP", color: .cyan)
                } else {
                    self.print("  The missiles strike unerringly!", color: .brightGreen)
                }

            case .healing:
                self.print("  Healed \(report.healAmount) HP!", color: .brightGreen, bold: true)
                for status in report.targetStatuses {
                    self.print("  \(status.name): \(status.currentHP)/\(status.maxHP) HP", color: .dimGreen)
                }

            case .buff:
                self.print("  \(report.casterName) is empowered!", color: .brightGreen)

            case .utility:
                self.print("  \(report.targetName ?? "Ally") is stabilized!", color: .brightGreen)
            }

            self.print("")

            // Show damage results
            if report.totalDamage > 0 && report.spellType != .healing {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { [weak self] in
                    guard let self = self else { return }

                    if !report.damageRolls.isEmpty {
                        let total = report.damageRolls.reduce(0, +)
                        self.printLines(self.diceArt(total), color: .red)
                    }
                    if let dt = report.damageType {
                        self.print("  \(report.totalDamage) \(dt) damage!", color: .red, bold: true)
                    } else {
                        self.print("  \(report.totalDamage) damage!", color: .red, bold: true)
                    }

                    for defeated in report.targetsDefeated {
                        self.print("  \(defeated) is defeated!", color: .yellow, bold: true)
                    }
                    for status in report.targetStatuses where !report.targetsDefeated.contains(status.name) {
                        self.print("  \(status.name): \(status.currentHP)/\(status.maxHP) HP", color: .dimGreen)
                    }
                    self.print("")

                    self.waitForContinue(fullScreenTap: false)
                    self.inputHandler = { _ in completion() }
                }
            } else {
                self.waitForContinue(fullScreenTap: false)
                self.inputHandler = { _ in completion() }
            }
        }
    }

    // MARK: - Class Feature Actions

    func useSecondWind(character: Character) {
        guard let combat = currentCombat else { return }

        clearTerminal()
        printCombatStatus()
        print("")
        print("\(character.name) uses Second Wind!", color: .brightGreen, bold: true)
        print("")

        let healRoll = Dice.rollSum(1, d: 10)
        let healAmount = healRoll + character.level
        character.heal(healAmount)
        character.secondWindUsed = true
        logMultiplayerAction("\(character.name) uses Second Wind — healed \(healAmount) HP (\(character.currentHP)/\(character.maxHP))")

        SoundManager.shared.playHeal()
        printLines(diceArt(healRoll), color: .brightGreen)
        print("  Healed \(healAmount) HP! (\(character.currentHP)/\(character.maxHP))", color: .brightGreen)
        print("")

        combat.checkCombatEnd()
        combat.nextTurn()

        waitForContinue(fullScreenTap: false)
        inputHandler = { [weak self] _ in self?.advanceCombat() }
    }

    func activateRage(character: Character) {
        guard let combat = currentCombat else { return }

        clearTerminal()
        printCombatStatus()
        print("")
        print("\(character.name) enters a RAGE!", color: .red, bold: true)
        print("")
        print("  +\(character.rageDamageBonus) bonus melee damage", color: .yellow)
        print("  Resistance to physical damage", color: .yellow)
        print("")

        character.isRaging = true
        character.rageUsesRemaining -= 1
        logMultiplayerAction("\(character.name) enters a RAGE!")

        combat.checkCombatEnd()
        combat.nextTurn()

        waitForContinue(fullScreenTap: false)
        inputHandler = { [weak self] _ in self?.advanceCombat() }
    }

    // MARK: - Willpower Surge (mind control)

    /// Entry point for a MindControlAttempt (see runMonsterTurn) — routes
    /// to the timed Willpower Surge prompt for an eligible, still-charged
    /// Cleric/Wizard, or straight to an automatic saving throw otherwise.
    private func resolveMindControlAttempt(_ attempt: MindControlAttempt, combat: Combat, completion: @escaping () -> Void) {
        guard let target = party.first(where: { $0.id == attempt.targetId }) else {
            completion()
            return
        }
        if attempt.offersWillpowerSurge {
            showWillpowerSurgePrompt(attempt: attempt, target: target, completion: completion)
        } else {
            autoResolveMindControlSave(attempt: attempt, target: target, completion: completion)
        }
    }

    /// The QTE itself — a single "RESIST!" button with a short fuse. Tap it
    /// in time and the surge shatters the attempt outright, no save needed;
    /// let the timer run out and it's treated as a miss (falls through to
    /// the same consequence as a failed saving throw).
    private func showWillpowerSurgePrompt(attempt: MindControlAttempt, target: Character, completion: @escaping () -> Void) {
        clearTerminal()
        printCombatStatus()
        print("")
        print("  \(attempt.monsterName) reaches for \(target.name)'s mind with \(attempt.attackDescription)!", color: .magenta, bold: true)
        print("")
        print("  ⚡ WILLPOWER SURGE! ⚡", color: .brightGreen, bold: true)
        printWrapped("Tap RESIST before the surge fades!", indent: 2, color: .yellow)
        print("")

        target.willpowerSurgeUsesRemaining -= 1
        showMenu(["RESIST!"])

        var resolved = false
        let surgeTimer = Timer.scheduledTimer(withTimeInterval: 2.2, repeats: false) { [weak self] _ in
            guard let self = self, !resolved else { return }
            resolved = true
            self.finishWillpowerSurge(succeeded: false, attempt: attempt, target: target, completion: completion)
        }
        menuHandler = { [weak self] _ in
            guard let self = self, !resolved else { return }
            resolved = true
            surgeTimer.invalidate()
            self.finishWillpowerSurge(succeeded: true, attempt: attempt, target: target, completion: completion)
        }
    }

    private func finishWillpowerSurge(succeeded: Bool, attempt: MindControlAttempt, target: Character, completion: @escaping () -> Void) {
        clearTerminal()
        printCombatStatus()
        print("")
        if succeeded {
            // Grace window — stops the very next monster turn from just
            // throwing the same prompt straight back at them.
            target.willpowerSurgeImmuneTurns = 1
            print("  \(target.name)'s will blazes bright — the surge shatters \(attempt.monsterName)'s hold before it can take root!", color: .brightGreen, bold: true)
            logEvent("\(target.name) resisted mind control with a Willpower Surge", category: "COMBAT")
            logMultiplayerAction("\(target.name) resisted \(attempt.monsterName)'s mind control with a Willpower Surge!")
        } else {
            let turns = Int.random(in: 1...2)
            target.applyMindControl(turns: turns)
            print("  \(target.name) wasn't fast enough — \(attempt.monsterName)'s will crashes over their own!", color: .red, bold: true)
            printWrapped("\(target.name) will lose \(turns) turn\(turns == 1 ? "" : "s") to it.", indent: 2, color: .dimGreen)
            logEvent("\(target.name) succumbed to mind control", category: "COMBAT")
            logMultiplayerAction("\(attempt.monsterName) seized control of \(target.name)'s mind!")
        }
        print("")
        waitForContinue(fullScreenTap: false)
        inputHandler = { _ in completion() }
    }

    /// Plain WIS saving throw — used when the target isn't a Cleric/Wizard,
    /// or has no Willpower Surge uses left this rest.
    private func autoResolveMindControlSave(attempt: MindControlAttempt, target: Character, completion: @escaping () -> Void) {
        clearTerminal()
        printCombatStatus()
        print("")
        print("  \(attempt.monsterName) reaches for \(target.name)'s mind with \(attempt.attackDescription)!", color: .magenta, bold: true)
        let mod = target.abilityScores.modifier(for: .wisdom)
        let roll = Dice.roll(20)
        let total = roll + mod
        print("  Willpower save: d20[\(roll)] + \(mod) = \(total) vs DC \(attempt.saveDC)", color: .dimGreen)
        print("")
        if total >= attempt.saveDC {
            print("  \(target.name) resists!", color: .brightGreen, bold: true)
            logEvent("\(target.name) resisted mind control (WIS save)", category: "COMBAT")
            logMultiplayerAction("\(target.name) resisted \(attempt.monsterName)'s mind control!")
        } else {
            let turns = Int.random(in: 1...2)
            target.applyMindControl(turns: turns)
            print("  \(target.name)'s mind is overwhelmed!", color: .red, bold: true)
            printWrapped("\(target.name) will lose \(turns) turn\(turns == 1 ? "" : "s") to it.", indent: 2, color: .dimGreen)
            logEvent("\(target.name) succumbed to mind control", category: "COMBAT")
            logMultiplayerAction("\(attempt.monsterName) seized control of \(target.name)'s mind!")
        }
        print("")
        waitForContinue(fullScreenTap: false)
        inputHandler = { _ in completion() }
    }

    /// A mind-controlled character's turn — frozen, unable to act, rather
    /// than making a choice of their own. advanceCombat() (not a passed-in
    /// completion) is safe to call from both the single-player and
    /// multiplayer combat loops — it already branches on isMultiplayer.
    private func performMindControlledTurn(character: Character, combat: Combat) {
        character.mindControlTurnsRemaining -= 1
        if character.mindControlTurnsRemaining <= 0 {
            character.isMindControlled = false
        }
        clearTerminal()
        printCombatStatus()
        print("")
        print("  \(character.name)'s mind is not their own — they stand frozen, unable to act!", color: .magenta, bold: true)
        print("")
        logEvent("\(character.name) lost their turn to mind control", category: "COMBAT")
        waitForContinue(fullScreenTap: false)
        inputHandler = { [weak self] _ in
            guard let self = self else { return }
            combat.checkCombatEnd()
            combat.nextTurn()
            self.advanceCombat()
        }
    }

    // MARK: - Death Saving Throws

    func showDeathSavingThrow(character: Character) {
        guard let combat = currentCombat else { return }

        print("\(character.name) is unconscious! Death Saving Throw...", color: .red, bold: true)
        print("")
        print("  Successes: \(String(repeating: "●", count: character.deathSaveSuccesses))\(String(repeating: "○", count: 3 - character.deathSaveSuccesses))", color: .brightGreen)
        print("  Failures:  \(String(repeating: "●", count: character.deathSaveFailures))\(String(repeating: "○", count: 3 - character.deathSaveFailures))", color: .red)
        print("")

        waitForContinue(fullScreenTap: false)
        inputHandler = { [weak self] _ in
            guard let self = self else { return }

            let result = Dice.deathSave()
            self.printLines(self.diceArt(result.roll), color: result.isSuccess ? .brightGreen : .red)
            self.print("  Death Save: [\(result.roll)]", color: .cyan)
            self.print("")

            if result.isCriticalSuccess {
                // Natural 20: revive with 1 HP
                character.heal(1)
                self.print("  NATURAL 20! \(character.name) revives with 1 HP!", color: .yellow, bold: true)
                SoundManager.shared.playHeal()
            } else if result.isCriticalFailure {
                // Natural 1: 2 failures
                character.deathSaveFailures += 2
                self.print("  NATURAL 1! Two failures!", color: .red, bold: true)
            } else if result.isSuccess {
                character.deathSaveSuccesses += 1
                self.print("  Success! (\(character.deathSaveSuccesses)/3)", color: .brightGreen)
            } else {
                character.deathSaveFailures += 1
                self.print("  Failure! (\(character.deathSaveFailures)/3)", color: .red)
            }

            // Check outcomes
            if character.deathSaveFailures >= 3 {
                self.print("")
                self.print("  \(character.name) has died!", color: .red, bold: true)
            } else if character.deathSaveSuccesses >= 3 {
                self.print("")
                self.print("  \(character.name) is stabilized!", color: .brightGreen, bold: true)
                character.deathSaveSuccesses = 0
                character.deathSaveFailures = 0
            }

            self.print("")
            combat.checkCombatEnd()
            combat.nextTurn()

            self.waitForContinue(fullScreenTap: false)
            self.inputHandler = { [weak self] _ in self?.advanceCombat() }
        }
    }

    // MARK: - Level Up

    func checkAndShowLevelUp(completion: @escaping () -> Void) {
        // Find first party member who can level up
        guard let character = party.first(where: { $0.canLevelUp }) else {
            completion()
            return
        }
        showLevelUpScreen(character: character) { [weak self] in
            // Check if more characters need leveling
            self?.checkAndShowLevelUp(completion: completion)
        }
    }

    func showLevelUpScreen(character: Character, completion: @escaping () -> Void) {
        let oldLevel = character.level
        let newLevel = oldLevel + 1
        let oldTitle = character.characterClass.rankTitle(atLevel: oldLevel)
        let newTitle = character.characterClass.rankTitle(atLevel: newLevel)

        character.level = newLevel

        clearTerminal()
        SoundManager.shared.playLevelUp()

        // Big, hard-to-miss fanfare — this is the one moment the game makes a
        // point of showing growth, since there's no portrait to hang a new
        // hat on in a text UI.
        printLines([
            "   ✦ · ✦ · ✦ · ✦ · ✦ · ✦   ",
            "      L E V E L   U P !     ",
            "   ✦ · ✦ · ✦ · ✦ · ✦ · ✦   ",
        ], color: .yellow)
        print("")
        print("\(character.name) reaches Level \(newLevel)!", color: .yellow, bold: true)
        if newTitle != oldTitle {
            print("\(character.name) is now a \(newTitle)!", color: .brightGreen, bold: true)
        }
        print("  \(Self.levelUpFlourish(for: character.characterClass))", color: .cyan)
        logMultiplayerAction("\(character.name) reached Level \(newLevel) — \(newTitle)!")
        print("")

        // Roll hit die for HP
        let hitDie = character.characterClass.hitDie
        let conMod = character.abilityScores.modifier(for: .constitution)
        let hpRoll = Dice.rollSum(1, d: hitDie)
        let hpGain = max(1, hpRoll + conMod)
        character.maxHP += hpGain
        character.currentHP += hpGain

        // Update spell slots
        let newSlots = SpellCatalog.startingSlots(for: character.characterClass, level: newLevel)
        var slotLine: String? = nil
        if !newSlots.isEmpty {
            character.spellSlots.level1Max = newSlots.level1Max
            character.spellSlots.level1Current = newSlots.level1Max
            character.spellSlots.level2Max = newSlots.level2Max
            character.spellSlots.level2Current = newSlots.level2Max
            if newSlots.level1Max > 0 {
                slotLine = "Spell Slots: \(newSlots.level1Max) L1\(newSlots.level2Max > 0 ? ", \(newSlots.level2Max) L2" : "")"
            }
        }

        // Learn new spells
        let newSpells = SpellCatalog.spellsForLevelUp(characterClass: character.characterClass, newLevel: newLevel)
        for spell in newSpells {
            character.knownSpells.append(spell)
        }

        // Class feature announcement for this level, if any
        var newFeature: String? = nil
        switch character.characterClass {
        case .fighter:
            if newLevel == 2 {
                newFeature = "Second Wind — heal 1d10+level once per short rest"
            }
        case .rogue:
            let dice = (newLevel + 1) / 2
            if dice > (oldLevel + 1) / 2 {
                newFeature = "Sneak Attack — now \(dice)d6 bonus damage"
            }
        case .barbarian:
            character.rageUsesRemaining = character.rageMaxUses
            if newLevel == 3 {
                newFeature = "Rage — now 3 uses per long rest"
            }
        default:
            break
        }

        // --- New things first, always ---
        print("  ✦ NEW THIS LEVEL", color: .brightGreen, bold: true)
        printLines(diceArt(hpRoll), color: .brightGreen)
        print("  +\(hpGain) HP (d\(hitDie)[\(hpRoll)] + \(conMod) CON) → \(character.maxHP) max HP", color: .brightGreen)
        if let slotLine = slotLine {
            print("  \(slotLine)", color: .cyan)
        }
        for spell in newSpells {
            print("  New Spell: \(spell.name) — \(spell.description)", color: .cyan)
        }
        if let newFeature = newFeature {
            print("  New Ability: \(newFeature)", color: .cyan)
        }
        print("")

        // --- Reminder of what they already had, so nothing gets forgotten ---
        let existingSpells = character.knownSpells.filter { spell in !newSpells.contains(where: { $0.name == spell.name }) }
        if !existingSpells.isEmpty {
            let names = existingSpells.prefix(4).map { $0.name }.joined(separator: ", ")
            let more = existingSpells.count > 4 ? " +\(existingSpells.count - 4) more" : ""
            print("  Still have: \(names)\(more)", color: .dimGreen)
        }
        print("")

        logEvent("\(character.name) reached Level \(newLevel) (\(newTitle))! (+\(hpGain) HP)", category: "LEVEL")

        if Self.abilityScoreImprovementLevels.contains(newLevel) {
            offerAbilityScoreImprovement(character: character, completion: completion)
            return
        }

        waitForContinue()
        inputHandler = { _ in completion() }
    }

    /// D&D 5e Ability Score Improvement levels. Only level 4 is currently reachable
    /// (characters cap at level 5 — see Character.canLevelUp), but the rest are kept
    /// so this keeps working automatically if the level cap is ever raised.
    /// A characteristic beat of celebration per class, printed on level-up —
    /// since a text UI has no portrait or sprite to animate, this is the
    /// closest thing to "the character does a little dance."
    private static func levelUpFlourish(for characterClass: CharacterClass) -> String {
        let lines: [String]
        switch characterClass {
        case .fighter:
            lines = ["💪 flexes and lets out a battle roar!", "💪 slams a fist against their breastplate, grinning."]
        case .wizard:
            lines = ["✨ traces a shimmering rune in the air, cackling with delight!", "✨ conjures a burst of harmless sparks and takes a little bow."]
        case .rogue:
            lines = ["🗡️ flips a dagger, grins, and gives a mock bow.", "🗡️ vanishes into shadow for a beat, then reappears with a flourish."]
        case .cleric:
            lines = ["🙏 raises a hand skyward as warm light glimmers around them.", "🙏 murmurs a quiet thanks, eyes shining with renewed conviction."]
        case .ranger:
            lines = ["🏹 lets out a sharp whistle and does a little victory jig.", "🏹 nocks an arrow skyward and lets it fly in celebration."]
        case .barbarian:
            lines = ["🪓 pounds their chest and stomps the ground, whooping with joy!", "🪓 hoists their weapon overhead with a triumphant roar!"]
        case .engineer:
            lines = ["⚙️ tightens a bolt on a contraption and it whirs to life triumphantly!", "⚙️ sketches a quick diagram in the air, muttering excitedly."]
        case .scout:
            lines = ["🧭 spins a compass, grins, and points confidently ahead.", "🧭 crouches low, scans the horizon, then flashes a thumbs up."]
        case .thief:
            lines = ["🗝️ palms an invisible coin, winks, and it's gone.", "🗝️ flashes a sly grin and pockets something that wasn't there before."]
        case .bard:
            lines = ["🎵 strikes up a jaunty victory tune!", "🎵 makes up a verse about the fight on the spot, to groans and cheers."]
        }
        return lines.randomElement()!
    }

    private static let abilityScoreImprovementLevels: Set<Int> = [4, 8, 12, 16, 19]

    private static func primaryAbility(for characterClass: CharacterClass) -> Ability {
        switch characterClass {
        case .fighter, .barbarian: return .strength
        case .wizard, .engineer: return .intelligence
        case .rogue, .ranger, .scout, .thief: return .dexterity
        case .cleric: return .wisdom
        case .bard: return .charisma
        }
    }

    /// Grants +2 to one ability score (player's choice; capped at 20 per 5e rules).
    /// AI-controlled party members auto-pick their class's primary ability.
    private func offerAbilityScoreImprovement(character: Character, completion: @escaping () -> Void) {
        print("Ability Score Improvement!", color: .yellow, bold: true)

        func apply(_ ability: Ability) {
            let newScore = min(20, character.abilityScores.score(for: ability) + 2)
            character.abilityScores.set(ability, to: newScore)
            print("  \(character.name)'s \(ability.rawValue) increases to \(newScore)!", color: .brightGreen)
            logEvent("\(character.name) improved \(ability.rawValue) to \(newScore) (Level \(character.level) ASI)", category: "LEVEL")
            waitForContinue()
            inputHandler = { _ in completion() }
        }

        if character.isComputerControlled {
            apply(Self.primaryAbility(for: character.characterClass))
            return
        }

        print("Choose one ability to increase by 2 (max 20):", color: .cyan)
        print("")
        let abilities = Ability.allCases
        let options = abilities.map { ability -> String in
            let score = character.abilityScores.score(for: ability)
            return score >= 20 ? "\(ability.rawValue) (\(score) — MAX)" : "\(ability.rawValue) (\(score))"
        }
        showMenu(options)
        menuHandler = { choice in
            guard abilities.indices.contains(choice) else { return }
            apply(abilities[choice])
        }
    }

    /// Characters eligible for combat loot (those who actually fought); nil = whole party
    private var combatLootEligible: [Character]?

    /// Guards against handleCombatVictory() running twice for the same
    /// fight — several independent paths call it (the per-turn check in
    /// runCombatTurn(), and separate "ask the DM in combat" flows that hold
    /// their own local reference to the same Combat and can each decide
    /// independently that it's over), and currentCombat alone wasn't a
    /// reliable guard: it's only nilled out partway through this function,
    /// so a second call arriving before that point would still see it
    /// non-nil and re-roll/re-show the loot a second time. Reset whenever a
    /// new combat actually starts (startCombat(), and multiplayer combat
    /// catch-up), never inside this function itself.
    private var isHandlingCombatVictory = false

    func handleCombatVictory() {
        guard !isHandlingCombatVictory else { return }
        // currentCombat checked BEFORE setting the guard flag — this flag is
        // only ever reset when a new combat starts (never inside this
        // function), so if it were set true here and currentCombat then
        // turned out nil, this function would permanently short-circuit
        // every future real combat victory for the rest of the session.
        guard let combat = currentCombat else { return }
        isHandlingCombatVictory = true
        cancelCombatIdleTimer()
        combatHesitating = false
        // combat.lootAwarded (unlike isHandlingCombatVictory) survives a
        // multiplayer catch-up resync, which resets isHandlingCombatVictory
        // to false and re-enters this function for a fight that was already
        // resolved and looted on another device.
        guard !combat.lootAwarded else { return }
        combat.lootAwarded = true
        SoundManager.shared.playVictory()
        advanceTime(30)

        // Track stats
        monstersSlain += combat.encounter.monsters.count
        combatsWon += 1

        // Identify who actually fought — exclude those who fled or played dead
        let fighters = party.filter { !$0.hasFledCombat && !$0.isPlayingDead }
        let shirkers = party.filter { $0.hasFledCombat || $0.isPlayingDead }
        combatLootEligible = fighters.isEmpty ? nil : fighters

        // Combat cleanup — end rage, hunter's mark, reset death saves, clear status
        for char in party {
            char.isRaging = false
            char.huntersMarkActive = false
            char.isPlayingDead = false
            char.hasFledCombat = false
            char.isDodging = false
            if !char.isConscious && char.deathSaveFailures < 3 {
                // Stabilize unconscious survivors
                char.deathSaveSuccesses = 0
                char.deathSaveFailures = 0
            }
        }

        clearTerminal()
        printTitle("VICTORY!")

        // Celebratory dragon animation
        DispatchQueue.main.async {
            self.dragonGifName = "dragon_castle"
        }

        let xp = combat.encounter.totalXP
        let rewardParty = fighters.isEmpty ? party : fighters

        // Split XP by contribution rather than flat — half the pool is a
        // guaranteed equal base share (so nobody who fought walks away with
        // nothing), the other half is weighted by an effort score: damage
        // dealt plus a flat per-turn credit so a healer/support character
        // taking real turns (buffs, heals) still earns a fair cut even with
        // little or no damage of their own.
        let baseShare = xp / 2
        let bonusPool = xp - baseShare
        let baseEach = baseShare / rewardParty.count
        let effortScores: [UUID: Int] = Dictionary(uniqueKeysWithValues: rewardParty.map { char in
            let dmg = combat.damageDealtByCharacter[char.id] ?? 0
            let turns = combat.turnsTakenByCharacter[char.id] ?? 0
            return (char.id, dmg + turns * 8)
        })
        let totalEffort = effortScores.values.reduce(0, +)
        var xpByCharacter: [UUID: Int] = [:]
        for char in rewardParty {
            let effort = effortScores[char.id] ?? 0
            let bonus = totalEffort > 0
                ? Int((Double(bonusPool) * Double(effort) / Double(totalEffort)).rounded())
                : bonusPool / rewardParty.count
            xpByCharacter[char.id] = baseEach + bonus
        }

        let defeated = combat.encounter.monsters.map { $0.name }.joined(separator: ", ")
        logEvent("Victory! Defeated \(defeated) (+\(xp) XP)", category: "COMBAT")
        logMultiplayerAction("Combat victory! \(combat.encounter.monsters.count) enemies slain (+\(xp) XP)")

        // Log party HP status after battle
        for char in party where char.isConscious {
            logMultiplayerAction("\(char.name): \(char.currentHP)/\(char.maxHP) HP after battle")
        }
        for char in party where !char.isConscious {
            logMultiplayerAction("\(char.name) is unconscious!")
        }

        print("All enemies defeated!", color: .brightGreen)
        print("")

        // A quest that just completed gets its own big celebration screen
        // once showExplorationView() runs checkAndShowSideQuestCompletion()
        // — this is only the "getting closer" nudge for one still in progress.
        if let quest = allQuests.first(where: { $0.type == .defeatMonsters }) {
            let done = min(quest.target, monstersSlain - quest.startMonstersSlain)
            if done < quest.target {
                print("  ✦ Quest progress: \(done)/\(quest.target) monsters defeated", color: .cyan, bold: true)
                print("")
            }
        }

        maybeShowTip()

        if !shirkers.isEmpty {
            let names = shirkers.map { $0.name }.joined(separator: ", ")
            print("\(names) did not fight and receive no spoils.", color: .dimGreen)
            print("")
        }

        print("Experience gained: \(xp) XP")

        for char in rewardParty {
            let gained = xpByCharacter[char.id] ?? 0
            char.experiencePoints += gained
            print("  \(char.name): +\(gained) XP", color: .dimGreen)
            let nextLevel = char.level + 1
            if char.canLevelUp {
                print("  \(char.name) has enough XP for Level \(nextLevel)!", color: .yellow)
            }
        }

        // Fulfil any "prove it in a real fight" gym-training promises
        for char in rewardParty {
            guard let pending = pendingBattleTrainedSkills[char.id], !pending.isEmpty else { continue }
            pendingBattleTrainedSkills[char.id] = nil
            for (skill, gymName) in pending where !char.skillProficiencies.contains(skill) {
                char.skillProficiencies.insert(skill)
                print("")
                print("  \(char.name) has proven themself — \(gymName) now counts them proficient in \(skill.rawValue)!", color: .brightGreen, bold: true)
                logEvent("\(char.name) earned \(skill.rawValue) proficiency in combat (promised by \(gymName))", category: "LEVEL")
                logMultiplayerAction("\(char.name) earned \(skill.rawValue) proficiency in combat, as promised by \(gymName)")
            }
        }

        // Generate loot from defeated monsters — skipped if "Ask the DM"
        // already ad-libbed a reward for this fight (see
        // Combat.adLibLootGranted), so the same combat's spoils aren't
        // granted twice from two independent sources.
        var lootGold = 0
        var lootItems: [Item] = []
        if !combat.adLibLootGranted {
            for monster in combat.encounter.monsters {
                if let loot = monster.type.rollLoot() {
                    if loot.type == .gold {
                        lootGold += loot.value
                        print("  \(monster.name) dropped \(loot.value) gold", color: .yellow)
                        logMultiplayerAction("\(monster.name) dropped \(loot.value) gold")
                    } else if loot.type == .potion || loot.type == .item {
                        if let item = resolveItemByName(loot.name) {
                            lootItems.append(item)
                            print("  \(monster.name) dropped \(loot.name)!", color: .brightGreen)
                            logMultiplayerAction("\(monster.name) dropped \(loot.name)!")
                        }
                    }
                }
            }
        }
        // Mark room cleared — capture who was defeated before the encounter
        // is wiped, so a revisit can describe the aftermath (see
        // Room.defeatedMonsterNames and showExplorationView()).
        dungeon?.currentRoom?.cleared = true
        dungeon?.currentRoom?.defeatedMonsterNames = combat.encounter.monsters.map { $0.name }
        // Zombies don't reliably stay down — unless the killing blow happens
        // to finish one for good (a coin-flip per zombie here), it's left
        // eligible to claw back up on a later visit (see
        // checkForMonsterRespawn, called from showExplorationView).
        dungeon?.currentRoom?.respawnEligibleMonsterNames = combat.encounter.monsters
            .filter { $0.name.localizedCaseInsensitiveContains("zombie") && Int.random(in: 1...100) > 50 }
            .map { $0.name }
        dungeon?.currentRoom?.encounter = nil

        // Chance for NPC to appear in cleared room (15%)
        if npcsEnabled, let room = dungeon?.currentRoom, room.npc == nil, room.roomType != .boss {
            if Int.random(in: 1...100) <= 15 {
                if let npcType = NPCType.randomFor(roomType: room.roomType) ?? NPCType.allCases.randomElement() {
                    seedNameRegistry()
                    room.npc = DungeonNPC(type: npcType)
                    print("")
                    print("A \(npcType.rawValue) emerges from the shadows...", color: .cyan)
                    logEvent("\(npcType.rawValue) appeared in \(room.name) after combat", category: "NPC")
                }
            }
        }

        // Check for boss room
        if dungeon?.currentRoom?.roomType == .boss {
            handleGameVictory()
            return
        }

        currentCombat = nil
        gameState = .exploring
        if self.musicEnabled { SoundManager.shared.startMusic(.exploration, preference: self.explorationMelodyChoice) }

        // If this was a trap room, trigger the trap after combat
        let pendingTrap = dungeon?.currentRoom?.roomType == .trap && dungeon?.currentRoom?.trapTriggered == false
        let shouldReturnToDM = returnToDMAfterCombat
        returnToDMAfterCombat = false

        let continueAction: () -> Void = { [weak self] in
            guard let self = self else { return }
            // Show loot pickup first, then level-ups, then back to DM or exploration
            let afterLoot = { [weak self] in
                guard let self = self else { return }
                self.combatLootEligible = nil
                self.checkAndShowLevelUp {
                    if pendingTrap, let room = self.dungeon?.currentRoom {
                        room.trapTriggered = true
                        self.triggerTrap(in: room)
                    } else if shouldReturnToDM {
                        self.askTheDM()
                    } else {
                        self.showExplorationView()
                    }
                }
            }
            self.showLootSequence(gold: lootGold, goldSource: "Combat loot",
                                  items: lootItems, itemSource: "Combat loot", onDone: afterLoot)
        }
        // Was a hand-rolled Timer + inputHandler pair, guarded only by
        // "is inputHandler currently non-nil" — true of almost any active
        // screen, not specifically this one. If that Timer ever fired after
        // the player had already tapped through to a LATER, unrelated
        // screen (its own inputHandler in active use for something else),
        // it would fire continueAction() a second time regardless, wiping
        // that screen via clearTerminal() and calling showLootSequence()
        // again with already-granted loot — which, having nothing left to
        // show, could render as little more than a blank screen instead of
        // "text appropriate to the victory and what's next". autoReturn()
        // already solves exactly this: it guards on closeHandler, set and
        // cleared specifically for THIS destination, not shared with
        // whatever screen comes after.
        autoReturnDestination = continueAction
        // Victory moves on reasonably briskly — no reading-time stretch.
        pendingTimeoutKind = .results; autoReturn(after: max(3.0, infoTimeout * 1.5), stretchForReading: false)
    }

    /// "Emergency Drop" — a rare, automatic anti-total-party-wipe save.
    /// EXPLICIT about how it works (see the on-screen message below and the
    /// Reputation help screen) rather than a hidden mechanic: only a party
    /// with a strong collective reputation (Glyphkeeper) is even eligible,
    /// and even then it's a chance, not a guarantee, scaled by how good
    /// they are. One use per adventure (Dungeon.emergencyDropUsed) — a
    /// genuine safety net, not a repeatable free pass. Returns true if it
    /// triggered (handleCombatDefeat should stop, not proceed to game over).
    private func tryEmergencyDrop() -> Bool {
        guard let dungeon = dungeon, !dungeon.emergencyDropUsed, !party.isEmpty else { return false }
        let avgScore = party.map { $0.ethicalScore }.reduce(0, +) / party.count
        // Threshold matches solidly Kind or better (see EthicalAlignment.forScore).
        let goodnessThreshold = 40
        guard avgScore >= goodnessThreshold else { return false }
        // Chance scales with how good the party is — capped, never certain.
        let chance = min(60, avgScore)
        guard Int.random(in: 1...100) <= chance else { return false }

        dungeon.emergencyDropUsed = true
        for char in party {
            char.currentHP = max(1, char.maxHP / 10)
            char.isRaging = false
            char.huntersMarkActive = false
            char.isPlayingDead = false
            char.hasFledCombat = false
            char.isDodging = false
        }
        ensureSafeRoom()
        clearAllUndoRedo()
        cancelCombatIdleTimer()
        combatHesitating = false
        SoundManager.shared.stopMusic()
        clearTerminal()
        gameState = .exploring
        logEvent("Emergency Drop triggered — the party's reputation (avg \(avgScore)) spared them from a total wipe.", category: "COMBAT")

        printTitle("Emergency Drop")
        print("")
        printWrapped("The party should have fallen here — but word of your reputation reached further than the blade. Someone, or something, pulled you back from the brink.", indent: 2, color: .brightGreen)
        print("")
        printWrapped("This is Emergency Drop: a rare, one-time-per-adventure save, only possible because your party's collective reputation is Kind or better. It won't happen again this adventure.", indent: 2, color: .dimGreen)
        print("")
        printWrapped("Your party is alive, but shaken — everyone is down to a sliver of HP.", indent: 2, color: .yellow)
        print("")
        showMenu(["Continue"])
        menuHandler = { [weak self] _ in self?.showExplorationView() }
        closeHandler = { [weak self] in self?.showExplorationView() }
        return true
    }

    func handleCombatDefeat() {
        if tryEmergencyDrop() { return }
        clearAllUndoRedo()
        suppressMenuUntil = .distantPast // same fix as handleGameVictory: don't let a pre-defeat long-press swallow the first menu tap
        cancelCombatIdleTimer()
        combatHesitating = false
        // Combat cleanup
        for char in party {
            char.isRaging = false
            char.huntersMarkActive = false
            char.isPlayingDead = false
            char.hasFledCombat = false
            char.isDodging = false
        }

        SoundManager.shared.stopMusic()
        SoundManager.shared.playDefeat()
        clearTerminal()
        suppressAutoScroll = false
        gameState = .gameOver
        logEvent("The party has fallen...", category: "COMBAT")

        // Record in Hall of Fame
        recordHallOfFame(outcome: .defeat)

        // Set closeHandler so the X icon is always available
        closeHandler = { [weak self] in
            self?.resetGame()
        }

        printLines(asciiSkull, color: .red)
        print("")
        printTitle("DEFEAT")
        print("Your party has fallen...", color: .red)
        print("")
        print("The dungeon claims another group of adventurers.")
        print("")

        showMenu(["View Adventure Log", "Return to Main Menu"])
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.showAdventureLog(onBack: { [weak self] in self?.resetGame() })
            } else {
                self.resetGame()
            }
        }
    }

    private func handleTimeLimitExpired() {
        SoundManager.shared.stopMusic()
        SoundManager.shared.playDefeat()
        clearTerminal()
        suppressAutoScroll = false
        gameState = .gameOver

        let limitText = formatTimeLimitValue(gameTimeLimit)
        logEvent("Time's up! The party ran out of time (\(limitText)).", category: "DEFEAT")

        recordHallOfFame(outcome: .defeat)

        // Set closeHandler so the X icon is always available
        closeHandler = { [weak self] in
            self?.resetGame()
        }

        printLines(asciiSkull, color: .red)
        print("")
        printTitle("TIME'S UP!")
        print("Your time has run out...", color: .red, bold: true)
        print("")
        print("The dungeon seals shut as the hourglass empties.")
        print("Your party is lost to the depths forever.")
        print("")
        print("Time limit: \(limitText)", color: .dimGreen)
        print("Game time: \(formattedGameTime())", color: .dimGreen)

        waitForContinue()
        inputHandler = { [weak self] _ in
            self?.resetGame()
        }
    }

    private func formatTimeLimitValue(_ minutes: Int) -> String {
        if minutes >= 1440 {
            let days = minutes / 1440
            return days == 1 ? "1 Day" : "\(days) Days"
        } else {
            let hours = minutes / 60
            return "\(hours) Hours"
        }
    }

    private func formatTimeRemaining(_ minutes: Int) -> String {
        if minutes <= 0 { return "0m left" }
        let h = minutes / 60
        let m = minutes % 60
        if h > 0 {
            return m > 0 ? "\(h)h\(m)m left" : "\(h)h left"
        }
        return "\(m)m left"
    }

    /// Easter egg victory — creates fake party/dungeon and triggers victory screen
    private func setupEasterEggVictory() {
        if party.isEmpty {
            let scores = AbilityScores(strength: 20, dexterity: 20, constitution: 20, intelligence: 20, wisdom: 20, charisma: 20)
            createEasterEggParty(scores: scores)
        }
        if dungeon == nil {
            dungeon = Dungeon(name: "The Hidden Debug Chamber", level: 42)
        }
        monstersSlain = 99
        combatsWon = 42
        handleGameVictory()
    }

    /// Creates a fake party of four legendary heroes for the easter egg victory
    private func createEasterEggParty(scores: AbilityScores) {
        let hero1 = Character(name: "Sir Debugalot", race: .human, characterClass: .fighter, abilityScores: scores)
        hero1.currentHP = hero1.maxHP
        let hero2 = Character(name: "Gandcode the Grey", race: .highElf, characterClass: .wizard, abilityScores: scores)
        hero2.currentHP = hero2.maxHP
        let hero3 = Character(name: "Stealthy McPatchfix", race: .lightfootHalfling, characterClass: .rogue, abilityScores: scores)
        hero3.currentHP = hero3.maxHP
        let hero4 = Character(name: "Brother Breakpoint", race: .hillDwarf, characterClass: .cleric, abilityScores: scores)
        hero4.currentHP = hero4.maxHP
        self.party = [hero1, hero2, hero3, hero4]
    }

    func handleGameVictory() {
        clearAllUndoRedo()
        suppressMenuUntil = .distantPast // a long-press right before the killing blow can otherwise swallow the first tap on this menu
        SoundManager.shared.stopMusic()
        SoundManager.shared.playVictory()
        clearTerminal()
        suppressAutoScroll = false
        menuImageName = "VictoryScene"
        gameState = .victory

        let currentLevel = dungeon?.level ?? 1
        let dungeonName = dungeon?.name ?? "The dungeon"
        logEvent("DUNGEON CONQUERED! \(dungeonName) has been cleared!", category: "EXPLORE")

        // Record in Hall of Fame + Game Center
        recordHallOfFame(outcome: .victory)

        // Every survivor is saved to the Character Roster and inducted into
        // the Character Hall of Fame — the character-level parallel to the
        // game Hall of Fame entry above, with its own linked save.
        inductPartyIntoCharacterHallOfFame(dungeonName: dungeonName, dungeonLevel: currentLevel)

        // Set closeHandler early so the X icon is always visible
        closeHandler = { [weak self] in
            self?.resetGame()
        }

        // Check for gatekeeper quest reward (before stats) — the quest's
        // type/reward vary (see SideQuest.random(includeSlayBoss:)), not
        // always "slay the boss for flat gold" as it once was.
        var gatekeeperRewardLine: String? = nil
        if let quest = activeQuest, quest.type == .slayBoss {
            gatekeeperRewardLine = applyQuestRewardInline(quest.reward)
            logEvent("Gatekeeper quest complete! Reward: \(quest.reward.description)", category: "QUEST")
            activeQuest = nil
        }

        // Gather stats
        var totalGold = 0
        var totalXP = 0
        for char in party { totalGold += char.gold; totalXP += char.experiencePoints }
        let roomsExplored = dungeon?.rooms.values.filter { $0.visited }.count ?? 0
        let totalRooms = dungeon?.rooms.count ?? 0
        let explorationPct = totalRooms > 0 ? (roomsExplored * 100 / totalRooms) : 0
        let day = gameTimeMinutes / 1440 + 1
        let bossMonster = dungeon?.rooms.values.first(where: { $0.roomType == .boss })?.encounter?.monsters.first
        let isFinal = dungeon?.isFinalLevel ?? false
        let bossName = isFinal ? bossMonster?.name : bossMonster?.type.rawValue
        let guardian = mainQuest.map { Dungeon.guardianName($0.villain) }

        // --- ASCII Trophy ---
        printLines(asciiTrophy, color: .yellow)
        print("")

        // --- Title ---
        printTitle("VICTORY!")
        print("")

        // --- Narrative opening ---
        let firstNames = party.map { $0.name.components(separatedBy: " ").first ?? $0.name }
        let heroList = firstNames.count <= 2
            ? firstNames.joined(separator: " and ")
            : firstNames.dropLast().joined(separator: ", ") + ", and " + (firstNames.last ?? "")

        printWrapped("The echoes of battle fade as \(heroList) \(party.count == 1 ? "stands" : "stand") triumphant in the heart of \(dungeonName).", indent: 2, color: .brightGreen)
        print("")

        // Boss defeat narrative
        if let boss = bossName {
            printWrapped("The dreaded \(boss) lies defeated, its reign of terror ended by steel, spell, and courage.", indent: 2, color: .green)
        } else {
            printWrapped("The dungeon boss lies vanquished. Its dark power is broken.", indent: 2, color: .green)
        }
        // Every guardian before the last serves the villain — and says so.
        if !isFinal, let g = guardian {
            printWrapped("With its last breath it gasps a name — \(g) — as if that should frighten you. It does, a little.", indent: 2, color: .yellow)
        }
        print("")

        // Party accomplishments
        if monstersSlain >= 15 {
            printWrapped("Your party carved a bloody path through the darkness — \(monstersSlain) creatures fell before your blades across \(combatsWon) brutal encounters.", indent: 2, color: .green)
        } else if monstersSlain >= 5 {
            printWrapped("Through \(combatsWon) hard-fought battles, your party vanquished \(monstersSlain) foul creatures lurking in the depths.", indent: 2, color: .green)
        } else if monstersSlain > 0 {
            printWrapped("Your party fought wisely, besting \(monstersSlain) creature\(monstersSlain == 1 ? "" : "s") in \(combatsWon) encounter\(combatsWon == 1 ? "" : "s").", indent: 2, color: .green)
        }

        // Exploration
        if explorationPct == 100 {
            printWrapped("Every chamber was explored, every corridor mapped — \(roomsExplored) rooms laid bare.", indent: 2, color: .green)
        } else if explorationPct >= 75 {
            printWrapped("You explored \(roomsExplored) of \(totalRooms) rooms, leaving few corners unsearched.", indent: 2, color: .green)
        } else {
            printWrapped("You ventured through \(roomsExplored) of \(totalRooms) rooms — secrets still remain hidden in the depths.", indent: 2, color: .green)
        }
        print("")

        // Gatekeeper quest reward display — variable-length now that the
        // reward varies, so a plain callout instead of the old fixed-width
        // box (which only ever fit a short gold amount).
        if let rewardLine = gatekeeperRewardLine {
            print("  ✦ QUEST COMPLETE — the Gatekeeper's task is done", color: .cyan, bold: true)
            printWrapped("  \(rewardLine)", indent: 2, color: .brightGreen)
            print("")
        }

        // --- Stats box ---
        print("  ┌─ Spoils of Victory ────────────┐", color: .yellow, bold: true)
        print("  │  Gold collected:  \(String(totalGold).padding(toLength: 14, withPad: " ", startingAt: 0)) │", color: .yellow)
        print("  │  Monsters slain:  \(String(monstersSlain).padding(toLength: 14, withPad: " ", startingAt: 0)) │", color: .yellow)
        print("  │  Combats won:     \(String(combatsWon).padding(toLength: 14, withPad: " ", startingAt: 0)) │", color: .yellow)
        print("  │  Experience:      \(String(totalXP).padding(toLength: 14, withPad: " ", startingAt: 0)) │", color: .yellow)
        print("  │  Level rooms:     \(String("\(roomsExplored)/\(totalRooms)").padding(toLength: 14, withPad: " ", startingAt: 0)) │", color: .yellow)
        if day > 1 {
            print("  │  Days survived:   \(String(day).padding(toLength: 14, withPad: " ", startingAt: 0)) │", color: .yellow)
        }
        print("  └───────────────────────────────┘", color: .yellow)
        print("")

        // Party status
        print("  YOUR HEROES", color: .cyan, bold: true)
        for char in party {
            let hp = "\(char.currentHP)/\(char.maxHP) HP"
            let lvl = "Lv\(char.level)"
            print("  \(char.name) — \(char.characterClass.rawValue) \(lvl), \(hp)", color: .brightGreen)
        }
        print("")

        // Hall of Fame
        print("  Recorded in the Hall of Fame!", color: .yellow)
        print("")

        // --- The end of the tale: the villain is beaten, nothing lies deeper ---
        if isFinal {
            print("  ┌─ The Tale Is Told ─────────────┐", color: .yellow, bold: true)
            if let q = mainQuest {
                printWrapped("\(Dungeon.guardianName(q.villain)) is no more. You came down here to \(q.goal) — and it is done.", indent: 2, color: .yellow)
                if let finale = q.finale {
                    print("")
                    printWrapped("Then, just as you were told, you \(finale).", indent: 2, color: .yellow)
                }
                if q.deadlinePassed == true {
                    printWrapped("It was later than it should have been — \(q.deadlineName ?? "the deadline") had come and gone — but it's done now, and that's what they'll sing about.", indent: 2, color: .dimGreen)
                }
                print("")
                printWrapped("Word runs ahead of you all the way to \(q.village). They promised you \(q.reward). It's yours, and so is every song they'll sing about this.", indent: 2, color: .brightGreen)
            } else {
                printWrapped("The last guardian of \(dungeonName) has fallen. There is nothing deeper — this was the bottom of the world, and you conquered it.", indent: 2, color: .yellow)
            }
            print("  └───────────────────────────────┘", color: .yellow)
            print("")
            printWrapped("THE END — of this adventure. Your heroes are in the Hall of Fame; a new tale starts whenever you like.", indent: 2, color: .dimGreen)
            print("")
            mainQuestCompleted = mainQuest != nil
            if let q = mainQuest { questHistory.append("Completed the quest: \(Dungeon.guardianName(q.villain)) defeated, and \(q.goal) done.") }
            logEvent("THE END: the final guardian of \(dungeonName) is defeated", category: "EXPLORE")
            showMenu(["Save & End Adventure", "End Adventure"])
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                if choice == 1 { self.performQuickSave() }
                self.resetGame()
            }
            return
        }

        // --- What lies ahead ---
        let nextLevel = currentLevel + 1
        print("  ┌─ The Depths Beckon ────────────┐", color: .cyan, bold: true)
        printWrapped("Level \(nextLevel) of \(dungeonName) awaits. Darker corridors, deadlier foes, and greater treasures lie below. Your party is stronger now — but so are the monsters.", indent: 2, color: .cyan)
        if let g = guardian {
            let left = Dungeon.finalLevel - currentLevel
            printWrapped(left <= 1 ? "Level \(nextLevel) is the last. \(g) waits at the bottom."
                                   : "\(g) waits at the bottom, \(left) levels down. Every guardian between here and there is stronger than the last.", indent: 2, color: .yellow)
        }
        print("  └───────────────────────────────┘", color: .cyan)
        print("")
        printWrapped("Save your progress before descending — the deeper levels show no mercy to the unprepared.", indent: 2, color: .dimGreen)
        print("")

        showMenu(["Save & Continue to Level \(nextLevel)", "Continue to Level \(nextLevel)", "Save & End Adventure", "End Adventure"])

        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1:
                // Save then continue
                self.performQuickSave()
                self.continueToNextLevel(nextLevel, dungeonName: dungeonName)
            case 2:
                // Continue without saving
                self.continueToNextLevel(nextLevel, dungeonName: dungeonName)
            case 3:
                // Save then end
                self.performQuickSave()
                self.resetGame()
            case 4:
                // End without saving
                self.resetGame()
            default: break
            }
        }

        // No auto-dismiss — victory is a major milestone, let the player read it
    }

    private func continueToNextLevel(_ nextLevel: Int, dungeonName: String, viaDeepPad: Bool = false) {
        clearTerminal()

        // Level up any eligible characters before proceeding
        checkAndShowLevelUp { [weak self] in
            guard let self = self else { return }

            // Generate new dungeon at next level, keeping the party — and
            // the Atlas: the level being left is archived onto the new one.
            let previousDungeon = self.dungeon
            self.dungeon = Dungeon(name: dungeonName, level: nextLevel)
            if let previous = previousDungeon, let next = self.dungeon {
                next.archivedLevels = previous.archivedLevels + [previous.atlasLevel(hasTrapSense: self.partyHasTrapSense, archived: true)]
                next.hasCartography = previous.hasCartography
            }
            self.currentCombat = nil
            self.roomsSinceLastSave = 0
            DMEngine.shared.clearHistory()
            self.dmChatLog = []

            self.gameState = .exploring
            self.logEvent("Descended to Level \(nextLevel) of \(dungeonName)", category: "EXPLORE")

            self.clearTerminal()
            if viaDeepPad {
                self.print("The floor drops away — and you land, hard, somewhere deeper in \(dungeonName).", color: .cyan)
                self.print("")
                self.print("Level \(nextLevel). You slipped past a guardian; the ones down here won't be so easy.", color: .dimGreen)
            } else {
                self.print("Your party descends deeper into \(dungeonName)...", color: .cyan)
                self.print("")
                self.print("The air grows heavier. Stronger foes await.", color: .dimGreen)
            }
            self.print("")

            if let beat = self.mainQuest?.beat(forLevel: nextLevel) {
                self.print("")
                self.printWrapped(beat, indent: 0, color: .yellow)
                self.logEvent("Quest: \(beat)", category: "QUEST")
            }
            if nextLevel >= Dungeon.finalLevel {
                self.print("")
                let g = self.mainQuest.map { Dungeon.guardianName($0.villain) } ?? "its last guardian"
                self.printWrapped("This is the last level — the bottom of the world. Somewhere down here, \(g) is waiting.", indent: 0, color: .yellow)
            }

            if self.musicEnabled { SoundManager.shared.startMusic(.exploration, preference: self.explorationMelodyChoice) }

            self.waitForContinue()
            self.inputHandler = { [weak self] _ in
                self?.clearTerminal()
                self?.showExplorationView()
            }
        }
    }

    /// Saves each surviving party member to the Character Roster and adds a
    /// Character Hall of Fame entry linking to that save — called on victory.
    private func inductPartyIntoCharacterHallOfFame(dungeonName: String, dungeonLevel: Int) {
        for char in party {
            saveCharacterToRoster(char, silent: true)
            let entry = CharacterHallOfFameEntry(
                date: Date(),
                characterName: char.name,
                race: char.race.rawValue,
                characterClass: char.characterClass.rawValue,
                level: char.level,
                gold: char.gold,
                dungeonName: dungeonName,
                dungeonLevel: dungeonLevel,
                linkedCharacterId: char.id
            )
            CharacterHallOfFameManager.shared.addEntry(entry)
        }
    }

    /// - loadHandler: when set, this is being browsed to pick a character to
    ///   join the party being created — tapping an entry loads it directly.
    ///   When nil, tapping an entry opens its roster detail/delete screen.
    /// - createNewHandler: when set, adds a "Create New" pinned option (used
    ///   when this screen doubles as the entry point for a fresh party slot).
    /// - defaultCharacterId: pre-selects the numbered button for the entry
    ///   linked to this character id (e.g. the most recently inducted hero),
    ///   so it's the one-tap default without changing display order.
    /// "Manage Saves" is always offered — the full Character Roster (not
    /// just Hall-of-Famers) is reachable from here.
    func showCharacterHallOfFame(loadHandler: ((Character) -> Void)? = nil, onBack: (() -> Void)? = nil,
                                  createNewHandler: (() -> Void)? = nil, defaultCharacterId: UUID? = nil) {
        clearTerminal()
        printLines(asciiCrown, color: .yellow)
        print("")
        printTitle("Character Hall of Fame")

        // Garbage-collect entries whose character was deleted from the
        // roster since before CharacterLibraryManager.delete cascaded this
        // cleanup itself — quietly, on every visit, so a deleted character
        // never resurfaces here as a ghost of the "same" hero.
        let rosterIds = Set(CharacterLibraryManager.shared.listCharacters().map { $0.character.id })
        for entry in CharacterHallOfFameManager.shared.listEntries() {
            if entry.linkedCharacterId == nil || !rosterIds.contains(entry.linkedCharacterId!) {
                CharacterHallOfFameManager.shared.deleteEntry(id: entry.id)
            }
        }

        let entries = CharacterHallOfFameManager.shared.listEntries()
        let backTarget = onBack ?? { [weak self] in self?.showPlayMenu() }
        let manageAction: () -> Void = { [weak self] in
            self?.showCharacterHallOfFameManage(loadHandler: loadHandler, onBack: onBack, createNewHandler: createNewHandler, defaultCharacterId: defaultCharacterId)
        }

        if entries.isEmpty {
            print("  No legends yet.", color: .yellow)
            print("")
            print("  Every survivor of a victorious adventure is inducted here, with their level, gear, and gold saved to your Character Roster.", color: .dimGreen)
            print("")
            showMenu(["Manage", "?", "< Back"])
            menuHandler = { [weak self] choice in
                switch choice {
                case 1: manageAction()
                case 2:
                    self?.showInlineHelp {
                        self?.printTitle("Character Hall of Fame — Help")
                        self?.print("")
                        self?.printWrapped("Every character who survives a victorious adventure is inducted here. Tap Manage to create a new roster character or manage existing ones.", indent: 2, color: .dimGreen)
                        self?.print("")
                    }
                default: backTarget()
                }
            }
            closeHandler = backTarget
            return
        }

        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .medium

        var options: [String] = []
        var defaultIdx: Int? = nil
        for (i, entry) in entries.enumerated() {
            // This absolute index matches the button's own displayNumber
            // (see showPaginatedMenu) regardless of which page the entry
            // lands on.
            print("  \(i + 1). \(entry.characterName) — \(entry.race) \(entry.characterClass) L\(entry.level)", color: .brightGreen, bold: true)
            print("     Score: \(entry.score)  ·  \(entry.gold)gp  ·  \(entry.dungeonName) (Lv\(entry.dungeonLevel))  ·  \(dateFormatter.string(from: entry.date))", color: .dimGreen)
            options.append(entry.characterName)
            if let defaultCharacterId = defaultCharacterId, entry.linkedCharacterId == defaultCharacterId {
                defaultIdx = i
            }
        }
        print("")

        // "Create New"/"Manage Saves" live behind the non-numbered "Manage"
        // button (see showCharacterHallOfFameManage) rather than either
        // (a) pinned buttons numbered past the end of the list regardless
        // of page, which used to collide/renumber confusingly, or (b)
        // appended to the list itself, which would bury them at the end of
        // however many pages a long roster needs. "Manage" is always one
        // tap away on every page instead.
        showPaginatedMenuOptions(options, pinned: ["Manage", "?", "< Back"], defaultIndex: defaultIdx, handler: { [weak self] idx in
            guard let self = self, idx >= 0 && idx < entries.count else { return }
            guard let linkedId = entries[idx].linkedCharacterId,
                  let record = CharacterLibraryManager.shared.listCharacters().first(where: { $0.character.id == linkedId }) else {
                self.print("  That character's roster save is no longer available.", color: .yellow)
                self.waitForContinue()
                self.inputHandler = { [weak self] _ in self?.showCharacterHallOfFame(loadHandler: loadHandler, onBack: onBack, createNewHandler: createNewHandler, defaultCharacterId: defaultCharacterId) }
                return
            }
            if let loadHandler = loadHandler {
                loadHandler(record.character)
            } else {
                self.showCharacterRosterActions(record: record, loadHandler: nil, onBack: { self.showCharacterHallOfFame(onBack: onBack) })
            }
        }, pinnedHandler: { [weak self] choice in
            switch choice {
            case 0: manageAction()
            case 1:
                self?.showInlineHelp {
                    self?.printTitle("Character Hall of Fame — Help")
                    self?.print("")
                    self?.printWrapped("Tap a character to \(loadHandler != nil ? "add them to your party" : "view their card and manage options"). Every survivor of a victorious adventure is inducted here automatically.", indent: 2, color: .dimGreen)
                    self?.print("")
                    self?.print("  MANAGE", color: .cyan, bold: true)
                    self?.printWrapped("Create a new roster character, or manage saved ones.", indent: 2, color: .dimGreen)
                    self?.print("")
                }
            default: backTarget()
            }
        })
        closeHandler = backTarget
    }

    /// Secondary-actions sub-screen for the Character Hall of Fame, reached
    /// via its non-numbered "Manage" button — keeps "Create New"/"Manage
    /// Saves" off the roster's own numbering entirely, and always one tap
    /// away regardless of how many pages the roster itself needs.
    private func showCharacterHallOfFameManage(loadHandler: ((Character) -> Void)?, onBack: (() -> Void)?,
                                                createNewHandler: (() -> Void)?, defaultCharacterId: UUID?) {
        let backToList: () -> Void = { [weak self] in
            self?.showCharacterHallOfFame(loadHandler: loadHandler, onBack: onBack, createNewHandler: createNewHandler, defaultCharacterId: defaultCharacterId)
        }

        clearTerminal()
        printTitle("Manage")
        print("")

        var opts: [String] = []
        if createNewHandler != nil { opts.append("Create New") }
        opts.append("Manage Saves")
        opts.append("< Back")

        showMenu(opts)
        closeHandler = backToList
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= opts.count else { return }
            switch opts[choice - 1] {
            case "Create New":
                createNewHandler?()
            case "Manage Saves":
                self.showCharacterRoster(loadHandler: loadHandler, onBack: backToList)
            default:
                backToList()
            }
        }
    }

    private func recordHallOfFame(outcome: RunOutcome) {
        var totalGold = 0
        for char in party { totalGold += char.gold }

        let roomsExplored = dungeon?.rooms.values.filter { $0.visited }.count ?? 0
        let totalRooms = dungeon?.rooms.count ?? 0

        // Create a linked save so the player can replay from Hall of Fame
        var linkedSaveId: UUID? = nil
        if let dungeon = dungeon {
            clearActiveSlotIfDeleted()
            let saveId = UUID()
            let slotId = activeSlotId ?? UUID()
            let slotName = activeSlotName ?? uniqueSlotName("\(party.first?.name ?? "Hero") — \(dungeon.name)")
            let partyDesc = party.map { "\($0.name) (\($0.characterClass.rawValue))" }.joined(separator: ", ")
            let chatEntries = dmChatLog.map { DMChatEntry(isUser: $0.isUser, text: $0.text) }
            let hofSave = SaveGame(
                id: saveId, slotId: slotId, savedAt: Date(), slotName: slotName,
                partyDescription: partyDesc, dungeonName: dungeon.name, dungeonLevel: dungeon.level,
                party: party, dungeon: dungeon, gameState: .exploring,
                gameTimeMinutes: gameTimeMinutes, adventureLog: adventureLog,
                dmChatLog: chatEntries, torchLit: torchLit,
                torchTurnsRemaining: torchTurnsRemaining,
                partyChatLog: partyChatLog.suffix(20).map { $0 },
                monstersSlain: monstersSlain, combatsWon: combatsWon,
                activeQuest: activeQuest, otherQuests: otherQuests, introLines: adventureIntroLines, mainQuest: mainQuest, questHistory: questHistory, noMainQuest: noMainQuest, mainQuestCompleted: mainQuestCompleted, questSummary: questSummaryLine()
            )
            try? SaveGameManager.shared.save(hofSave)
            linkedSaveId = saveId
        }

        let entry = HallOfFameEntry(
            id: UUID(),
            date: Date(),
            partyNames: party.map { $0.name },
            partyDescription: party.map { "\($0.name) (\($0.characterClass.rawValue))" }.joined(separator: ", "),
            dungeonName: dungeon?.name ?? "Unknown",
            dungeonLevel: dungeon?.level ?? 1,
            outcome: outcome,
            goldCollected: totalGold,
            monstersSlain: monstersSlain,
            combatsWon: combatsWon,
            roomsExplored: roomsExplored,
            totalRooms: totalRooms,
            gameTimeMinutes: gameTimeMinutes,
            saveGameId: linkedSaveId
        )

        HallOfFameManager.shared.addEntry(entry)

        // Game Center submissions
        let gc = GameCenterManager.shared
        gc.submitScore(totalGold, leaderboardID: GameCenterManager.leaderboardGold)
        gc.submitScore(monstersSlain, leaderboardID: GameCenterManager.leaderboardSlain)

        let totalVictories = HallOfFameManager.shared.totalVictories()
        gc.submitScore(totalVictories, leaderboardID: GameCenterManager.leaderboardVictories)

        // Check achievements
        gc.checkAchievements(
            combatsWon: combatsWon,
            monstersSlain: monstersSlain,
            goldCollected: totalGold,
            dungeonLevel: dungeon?.level ?? 1,
            isVictory: outcome == .victory
        )
    }

    // MARK: - Character Roster
    //
    // Saves/loads individual characters independent of game saves, so a
    // character's level, gear, and gold can carry over into a new adventure.
    // Deliberately kept visually and terminologically distinct from
    // "Saved Adventures" — different title, different verbs ("Roster" /
    // "Load into Party" vs "Continue Quest" / "Load") — so it's always
    // obvious which system is in play.

    /// - loadHandler: when set, this is being browsed to pick a character to
    ///   join the party being created — each row offers "Load into Party".
    ///   When nil, this is a standalone browse/manage screen.
    func showCharacterRoster(loadHandler: ((Character) -> Void)? = nil, onBack: (() -> Void)? = nil) {
        clearTerminal()
        printTitle("Character Roster")

        let records = CharacterLibraryManager.shared.listCharacters()

        let helpAction: () -> Void = { [weak self] in
            self?.showInlineHelp {
                self?.printTitle("Character Roster — Help")
                self?.print("")
                self?.printWrapped("Characters you save (after creating them, or from Party Status during an adventure) appear here, ready to bring into a future party.", indent: 2, color: .dimGreen)
                self?.print("")
                self?.printWrapped("Tap one to \(loadHandler != nil ? "add it to your party" : "view its card and manage it (load into party, or delete from the roster)"). ", indent: 2, color: .dimGreen)
                self?.print("")
            }
        }

        if records.isEmpty {
            print("  No saved adventurers yet.", color: .yellow)
            print("")
            print("  Characters you save after creating them (or from Party Status during an adventure) will appear here, ready to bring into a future party.", color: .dimGreen)
            print("")
            // With nothing to load, the only way to get a character at all
            // is through New Adventure's own creation flow — so offer it
            // directly rather than just a dead-end back button (when
            // loadHandler is set, the player is already mid-creation
            // picking a character to load, so there's nothing extra to
            // point them at).
            var opts = ["?", "< Back"]
            if loadHandler == nil { opts.insert("New Adventure", at: 0) }
            showMenu(opts)
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                switch opts[choice - 1] {
                case "New Adventure": self.startNewGame()
                case "?": helpAction()
                default: (onBack ?? { self.showPlayMenu() })()
                }
            }
            closeHandler = onBack ?? { [weak self] in self?.showPlayMenu() }
            return
        }

        print("  \(records.count) saved character\(records.count == 1 ? "" : "s")\(loadHandler != nil ? " — tap one to add it to your party" : "")", color: .dimGreen)
        print("")

        var options: [String] = []
        for record in records {
            let c = record.character
            options.append("\(c.name) — \(c.race.rawValue) \(c.characterClass.rawValue) L\(c.level)")
        }

        showPaginatedMenuOptions(options, pinned: ["?", "< Back"], handler: { [weak self] idx in
            guard let self = self, idx >= 0 && idx < records.count else { return }
            self.showCharacterRosterActions(record: records[idx], loadHandler: loadHandler, onBack: onBack)
        }, pinnedHandler: { [weak self] choice in
            if choice == 0 { helpAction() } else { (onBack ?? { self?.showPlayMenu() })() }
        })
        closeHandler = onBack ?? { [weak self] in self?.showPlayMenu() }
    }

    private func showCharacterRosterActions(record: SavedCharacterRecord, loadHandler: ((Character) -> Void)?, onBack: (() -> Void)?) {
        clearTerminal()
        let c = record.character
        printSubtitle("\(c.name)")
        printLines(c.displaySheet())
        print("")
        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .medium
        dateFormatter.timeStyle = .short
        print("  Saved: \(dateFormatter.string(from: record.savedAt))", color: .dimGreen)
        print("")

        var options: [String] = []
        if loadHandler != nil { options.append("Load into Party") }
        options.append("Delete from Roster")
        options.append(contentsOf: ["?", "< Back"])

        showMenu(options)
        let backToList: () -> Void = { [weak self] in
            self?.showCharacterRoster(loadHandler: loadHandler, onBack: onBack)
        }
        closeHandler = backToList
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1 && choice <= options.count else { return }
            switch options[choice - 1] {
            case "Load into Party":
                let loaded = c
                loaded.prepareForNewAdventure()
                loadHandler?(loaded)
            case "Delete from Roster":
                CharacterLibraryManager.shared.delete(id: c.id)
                self.print("")
                self.print("  \(c.name) removed from the roster.", color: .yellow)
                self.waitForContinue()
                self.inputHandler = { _ in backToList() }
            case "?":
                self.showInlineHelp {
                    self.printTitle("\(c.name) — Help")
                    self.print("")
                    if loadHandler != nil {
                        self.print("  LOAD INTO PARTY", color: .cyan, bold: true)
                        self.printWrapped("Adds \(c.name), with their saved level and gear, to the party you're building.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                    self.print("  DELETE FROM ROSTER", color: .cyan, bold: true)
                    self.printWrapped("Permanently removes \(c.name) from your Character Roster. Cannot be undone.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default: backToList()
            }
        }
    }

    /// Saves (or updates) a character to the roster and confirms to the player.
    @discardableResult
    func saveCharacterToRoster(_ character: Character, silent: Bool = false) -> Bool {
        let ok = CharacterLibraryManager.shared.save(character)
        if !silent {
            print(ok ? "  \(character.name) saved to your Character Roster." : "  Couldn't save \(character.name) to the roster.",
                  color: ok ? .brightGreen : .red)
        }
        return ok
    }

    // MARK: - Save / Load

    private enum LoadGameOrigin {
        case mainMenu
        case exploration
        case settings
    }

    /// Shared destination for the exploration screen's corner X icon and
    /// its "< Leave" nav button — if just saved, go straight to quit
    /// confirmation; otherwise the Save/Quit menu.
    private func leaveExplorationTapped() {
        if let saved = lastSaveTime, Date().timeIntervalSince(saved) < 60,
           let slotId = activeSlotId {
            let slotName = activeSlotName ?? "Current Game"
            confirmQuitAfterRecentSave(slotId: slotId, slotName: slotName)
        } else {
            showSaveMenu()
        }
    }

    /// The one place that should ever call SaveGameManager.deleteSlot —
    /// clears activeSlotId/activeSlotName too, if the deleted slot was the
    /// currently active adventure. Without this, deleting your own active
    /// adventure (directly, or as part of a multi-select bulk delete)
    /// left activeSlotId still pointing at that now-gone slotId, and the
    /// very next autosave (every few rooms, mid-play) silently wrote a
    /// fresh save right back under the same id — the deletion looked like
    /// it "didn't stick" the moment you kept playing (or, on a bulk
    /// delete that happened to include the active slot, even before you
    /// noticed). Single-slot delete already had this check inline; the
    /// bulk multi-select delete paths and the "replace an old slot to
    /// free up room" path did not.
    private func deleteSlotClearingActiveIfNeeded(_ slotId: UUID) {
        SaveGameManager.shared.deleteSlot(slotId: slotId)
        if activeSlotId == slotId {
            activeSlotId = nil
            activeSlotName = nil
        }
    }

    func showSaveMenu() {
        clearTerminal()
        printTitle("Save/Quit")
        startSaveMenuIdleTimer()

        guard let _ = dungeon else {
            print("Error: No dungeon to save.", color: .red)
            showExplorationView()
            return
        }
        clearActiveSlotIfDeleted()

        let slots = SaveGameManager.shared.listSlots()

        if activeSlotId != nil {
            // We already have an active slot — offer to save to it
            let slotName = activeSlotName ?? "Current Game"
            print("Save to: \(slotName)", color: .cyan)
            print("")

            // Help text
            print("  Save: save and keep playing", color: .dimGreen)
            print("  Save & Quit App: save, then close the app", color: .dimGreen)
            if slots.count < SaveGameManager.maxSlots {
                print("  Save+NewName: save as a new adventure", color: .dimGreen)
            }
            print("  Quit App: close the app without saving", color: .dimGreen)
            print("  Main Menu: leave this adventure, stay in the app", color: .dimGreen)
            print("  (Long-press either Quit button to skip the check.)", color: .dimGreen)
            print("")

            var options: [String] = []
            options.append("Save")              // 1
            options.append("Save & Quit App")         // 2
            if slots.count < SaveGameManager.maxSlots {
                options.append("Save+NewName")   // 3
                options.append("Quit App")     // 4
                options.append("Main Menu")     // 5
            } else {
                options.append("Quit App")     // 3
                options.append("Main Menu")     // 4
            }
            options.append("?")
            options.append("< Back")

            // ? and < Back live in the 3-bar nav cell, like every other screen.
            showMenuOptions(options.map {
                ($0 == "?" || $0 == "< Back") ? MenuOption($0, tint: .navigation, compact: true) : MenuOption($0)
            })
            closeHandler = { [weak self] in
                self?.closeHandler = nil
                self?.cancelSaveMenuIdleTimer()
                self?.showExplorationView()
            }
            // Long-press skips the "are you sure?" step.
            menuLongPressHandler = { [weak self] choice in
                guard let self = self, choice >= 1 && choice <= options.count, let slotId = self.activeSlotId else { return }
                switch options[choice - 1] {
                case "Quit App":
                    self.performQuit()
                case "Save & Quit App":
                    self.performSave(slotId: slotId, slotName: slotName)
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { self.performQuit() }
                default: break
                }
            }
            menuHandler = { [weak self] choice in
                guard let self = self, choice >= 1 && choice <= options.count else { return }
                self.cancelSaveMenuIdleTimer()
                let selected = options[choice - 1]
                switch selected {
                case "Save":
                    self.performSave(slotId: self.activeSlotId!, slotName: slotName)
                case "Save & Quit App":
                    self.confirmQuitAndSave(slotId: self.activeSlotId!, slotName: slotName)
                case "Save+NewName":
                    self.askForNewSlotName()
                case "Quit App":
                    self.confirmQuitWithoutSaving()
                case "Main Menu":
                    self.confirmExitToMainMenu()
                case "Info":
                    self.showSaveInfo()
                case "?":
                    self.showSaveHelp()
                default:
                    self.showExplorationView()
                }
            }
        } else if slots.count >= SaveGameManager.maxSlots {
            // No active slot and at limit — must pick a slot to overwrite
            showOverwriteSlotMenu(slots: slots)
        } else {
            // No active slot, room for new one
            askForNewSlotName()
        }
    }

    // MARK: Save Menu Idle Timer

    private func startSaveMenuIdleTimer() {
        saveMenuIdleTimer?.invalidate()
        saveMenuNagCount = 0
        guard idlePromptsEnabled else { return }
        saveMenuIdleTimer = Timer.scheduledTimer(withTimeInterval: 90.0, repeats: true) { [weak self] _ in
            DispatchQueue.main.async {
                guard self?.timeFrozen != true else { return }
                self?.saveMenuIdleNag()
            }
        }
    }

    private func cancelSaveMenuIdleTimer() {
        saveMenuIdleTimer?.invalidate()
        saveMenuIdleTimer = nil
    }

    private func saveMenuIdleNag() {
        saveMenuNagCount += 1

        let nags: [(String, [String])] = [
            ("The DM taps the table impatiently...",
             ["    ╭─────╮",
              "    │ -_- │",
              "    │  >  │",
              "    ╰──┬──╯",
              "     ╱│╲",
              "      │",
              "     ╱ ╲"]),
            ("\"Whilst you deliberate, the dungeon grows restless...\"",
             ["    ╭─────╮",
              "    │ o_o │",
              "    │  ~  │",
              "    ╰──┬──╯",
              "    ╱╱│╲╲",
              "      │",
              "     ╱ ╲"]),
            ("The DM glances at a pocket watch.",
             ["    ╭─────╮",
              "    │ ¬_¬ │",
              "    │  .  │",
              "    ╰──┬──╯",
              "     ╲│  ◔",
              "      │",
              "     ╱ ╲"]),
            ("\"The monsters aren't going to slay themselves, you know.\"",
             ["    ╭─────╮",
              "    │ >_< │",
              "    │  o  │",
              "    ╰──┬──╯",
              "     ╱│╲",
              "      │",
              "     ╱ ╲"]),
            ("The DM starts rolling dice menacingly...",
             ["    ╭─────╮",
              "    │ ●_● │",
              "    │  ▽  │",
              "    ╰──┬──╯",
              "     ╱│╲ 🎲",
              "      │",
              "     ╱ ╲"]),
            ("\"I haven't got all day. Well, actually I have. But still.\"",
             ["    ╭─────╮",
              "    │ -_- │",
              "    │  ω  │",
              "    ╰──┬──╯",
              "    ╱╱ │ ╲╲",
              "       │",
              "      ╱ ╲"]),
        ]

        let index = (saveMenuNagCount - 1) % nags.count
        let (text, art) = nags[index]

        print("")
        for line in art {
            print(line, color: .dimGreen)
        }
        print("")
        print("  \(text)", color: .yellow)
        print("  [\(formattedGameTime())]", color: .dimGreen)
    }

    private func showSaveInfo() {
        clearTerminal()
        printTitle("Save Info")
        print("")

        // --- Last saved ---
        print("  LAST SAVED", color: .cyan, bold: true)
        if let slotId = activeSlotId {
            let breakpoints = SaveGameManager.shared.listBreakpoints(slotId: slotId)
            if let latest = breakpoints.first {
                let elapsed = Date().timeIntervalSince(latest.savedAt)
                let mins = Int(elapsed) / 60
                let timeAgo: String
                let timeColor: TerminalColor
                if mins < 1 {
                    timeAgo = "Just now"
                    timeColor = .brightGreen
                } else if mins < 60 {
                    timeAgo = "\(mins) min ago"
                    timeColor = mins > 15 ? .yellow : .brightGreen
                } else {
                    let hrs = mins / 60
                    timeAgo = "\(hrs)h \(mins % 60)m ago"
                    timeColor = .red
                }
                printWrapped(timeAgo, indent: 4, color: timeColor)
            } else {
                printWrapped("No saves yet.", indent: 4, color: .yellow)
            }
        } else {
            printWrapped("No saves yet for this adventure.", indent: 4, color: .yellow)
            printWrapped("You should save soon!", indent: 4, color: .yellow)
        }
        print("")

        // --- Recent saves ---
        if let slotId = activeSlotId {
            let breakpoints = SaveGameManager.shared.listBreakpoints(slotId: slotId)
            if !breakpoints.isEmpty {
                print("  RECENT SAVES", color: .cyan, bold: true)
                let dateFormatter = DateFormatter()
                dateFormatter.dateStyle = .short
                dateFormatter.timeStyle = .short
                for (i, bp) in breakpoints.prefix(3).enumerated() {
                    let dateStr = dateFormatter.string(from: bp.savedAt)
                    let day = bp.gameTimeMinutes / 1440 + 1
                    let label = i == 0 ? " (latest)" : ""
                    printWrapped("Day \(day) — \(bp.dungeonName) Lv\(bp.dungeonLevel)\(label)", indent: 4, color: .dimGreen)
                    printWrapped(dateStr, indent: 6, color: .gray)
                }
                print("")
            }
        }

        // --- Run stats ---
        print("  RUN STATS", color: .cyan, bold: true)
        let day = gameTimeMinutes / 1440 + 1
        let hourOfDay = (gameTimeMinutes % 1440) / 60
        let period = hourOfDay >= 12 ? "PM" : "AM"
        let hour12 = hourOfDay == 0 ? 12 : (hourOfDay > 12 ? hourOfDay - 12 : hourOfDay)
        printWrapped("Game time: Day \(day), \(hour12) \(period)", indent: 4, color: .dimGreen)
        printWrapped("Monsters slain: \(monstersSlain)", indent: 4, color: .dimGreen)
        printWrapped("Combats won: \(combatsWon)", indent: 4, color: .dimGreen)
        let totalGold = party.reduce(0) { $0 + $1.gold }
        printWrapped("Party gold: \(totalGold)", indent: 4, color: .dimGreen)
        if let dungeon = dungeon {
            let explored = dungeon.rooms.values.filter { $0.visited }.count
            printWrapped("Rooms explored on Level \(dungeon.level): \(explored)/\(dungeon.rooms.count)", indent: 4, color: .dimGreen)
            printWrapped("Dungeon level: \(dungeon.level)", indent: 4, color: .dimGreen)
        }
        print("")

        // --- Torch ---
        print("  TORCH", color: .cyan, bold: true)
        let torches = party.flatMap { $0.inventory }.filter { $0.isTorch }
        if torchLit {
            let h = torchTurnsRemaining / 60
            let m = torchTurnsRemaining % 60
            printWrapped("Lit (\(h)h \(m)m remaining)", indent: 4, color: .yellow)
        } else if torches.isEmpty {
            printWrapped("None! Buy from Merchant.", indent: 4, color: .red)
        } else {
            printWrapped("\(torches.count) in packs (unlit)", indent: 4, color: .dimGreen)
        }
        print("")

        // --- Party summary ---
        print("  PARTY", color: .cyan, bold: true)
        for char in party {
            let hpPct = char.maxHP > 0 ? (char.currentHP * 100 / char.maxHP) : 0
            let hpColor: TerminalColor = hpPct > 50 ? .brightGreen : (hpPct > 25 ? .yellow : .red)
            printWrapped("\(char.name) (\(char.characterClass.rawValue) Lv\(char.level))", indent: 4, color: hpColor)
            printWrapped("HP \(char.currentHP)/\(char.maxHP)  Gold \(char.gold)  Pack \(formatWeightPair(char.currentWeight, char.carryCapacity))", indent: 6, color: .dimGreen)
        }
        print("")

        closeHandler = { [weak self] in
            self?.showSaveMenu()
        }
    }

    private func showSaveHelp() {
        showInlineHelp {
            self.printTitle("Save/Quit — Help")
            self.print("")

            self.print("  SAVE", color: .cyan, bold: true)
            self.printWrapped("Save and continue playing. Your progress is saved to the current slot. You can also quick-save from the Actions menu.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  QUIT+SAVE", color: .cyan, bold: true)
            self.printWrapped("Save your game and exit to the main menu. Your adventure is preserved — pick it up later from Load Game.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  SAVE+NEWNAME", color: .cyan, bold: true)
            self.printWrapped("Save to a new slot with a different name. Useful for keeping multiple save points of the same adventure.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  QUIT-SAVE", color: .cyan, bold: true)
            self.printWrapped("Exit without saving. Any progress since your last save is lost! Be careful.", indent: 2, color: .red)
            self.print("")

            self.print("  AUTOSAVE", color: .cyan, bold: true)
            self.printWrapped("The game autosaves periodically. Change the frequency in Settings > Saving. Autosaves create breakpoints you can reload from.", indent: 2, color: .dimGreen)
            self.printLink("Settings > Game Saves", to: "saves", indent: 4)
            self.print("")

            self.print("  BREAKPOINTS", color: .cyan, bold: true)
            self.printWrapped("Each save slot can hold multiple breakpoints (snapshots). Long-press Load to quick-load the latest breakpoint.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    static let maxSlotNameLength = 20

    private func askForNewSlotName() {
        let rawDefault = "\(party.first?.name ?? "Unknown") — \(dungeon?.name ?? "Dungeon")"
        let defaultName = String(rawDefault.prefix(Self.maxSlotNameLength))
        // Explicit "Quit Without Saving" alongside the default-name button
        // — without it, a player who's never saved before had no way to
        // reach that option at all (X here only cancels back to the game,
        // it doesn't quit, and there's no active slot yet to route them
        // through the main Save/Quit screen's own Quit-Save button).
        promptTextWithMenu("Enter a name, or use default:", options: [defaultName, "Quit Without Saving"])
        // Long-press Quit Without Saving skips the confirmation.
        menuLongPressHandler = { [weak self] choice in
            if choice == 2 { self?.performQuit() }
        }

        closeHandler = { [weak self] in
            self?.showExplorationView()
        }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                let slotName = self.uniqueSlotName(defaultName)
                let slotId = UUID()
                self.performSave(slotId: slotId, slotName: slotName)
            } else if choice == 2 {
                self.confirmQuitWithoutSaving()
            }
        }

        inputHandler = { [weak self] name in
            guard let self = self else { return }
            if self.isReservedWord(name) {
                self.showExplorationView()
                return
            }
            if !name.isEmpty && !self.isNameAppropriate(name) {
                self.print("Not appropriate. Try again.", color: .yellow)
                self.print("")
                self.askForNewSlotName()
                return
            }

            let baseName: String
            if name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                baseName = defaultName
            } else {
                baseName = String(name.trimmingCharacters(in: .whitespacesAndNewlines).prefix(Self.maxSlotNameLength))
            }

            let slotName = self.uniqueSlotName(baseName)
            let newSlotId = UUID()
            self.activeSlotId = newSlotId
            self.activeSlotName = slotName
            self.performSave(slotId: newSlotId, slotName: slotName)
        }
    }

    /// Returns a unique slot name, truncated to fit buttons. Appends " 002" etc. if a duplicate exists.
    /// yyMMddHHmm date-time code, e.g. 2609132308 for 13 Sep 2026, 23:08.
    static func saveStamp(_ date: Date = Date()) -> String {
        let f = DateFormatter()
        f.locale = Locale(identifier: "en_US_POSIX")
        f.dateFormat = "yyMMddHHmm"
        return f.string(from: date)
    }

    /// Every new save name gets a date-time code (see saveStamp) appended
    /// to the end of whatever name was chosen. The name itself is trimmed
    /// to fit — never the code.
    private func uniqueSlotName(_ baseName: String) -> String {
        let stamp = " " + Self.saveStamp()
        let maxLen = Self.maxSlotNameLength + stamp.count
        let truncated = String(baseName.prefix(Self.maxSlotNameLength)) + stamp
        let existingNames = Set(SaveGameManager.shared.listSlots().map { $0.slotName })
        if !existingNames.contains(truncated) { return truncated }

        for n in 2...999 {
            let suffix = String(format: " %03d", n)
            let base = String(truncated.prefix(maxLen - suffix.count))
            let candidate = base + suffix
            if !existingNames.contains(candidate) { return candidate }
        }
        return String((truncated + " \(UUID().uuidString.prefix(4))").prefix(maxLen))
    }

    private func showOverwriteSlotMenu(slots: [SaveSlot]) {
        print("All \(SaveGameManager.limitLabel(SaveGameManager.maxSlotsSetting)) adventure slots are full.", color: .yellow)
        print("Choose an adventure to replace, or quit without saving:", color: .cyan)
        print("")

        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .short
        dateFormatter.timeStyle = .short

        for (i, slot) in slots.enumerated() {
            let dateStr = dateFormatter.string(from: slot.latest.savedAt)
            print(" \(i + 1). \(slot.slotName)", color: .brightGreen)
            print("    \(slot.latest.partyDescription)", color: .dimGreen)
            if let q = slot.latest.questSummary { print("    \(q)", color: q.hasPrefix("★") ? .yellow : .cyan) }
            print("    Lv\(slot.latest.dungeonLevel) — \(dateStr) (\(slot.breakpointCount) saves)", color: .dimGreen)
        }
        print("")

        // A full slot list must never leave "quit without saving" as the
        // only unreachable option — replacing a save is a much bigger
        // commitment than just walking away from this run unsaved.
        var options = slots.map { "Replace: \($0.slotName)" }
        let quitIndex = options.count
        options.append("Quit Without Saving")
        options.append("?")
        options.append("< Back")

        showMenu(options)
        closeHandler = { [weak self] in self?.showExplorationView() }

        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let idx = choice - 1
            guard idx >= 0 && idx < options.count else { return }
            if idx < slots.count {
                let selected = slots[idx]

                self.clearTerminal()
                self.print("Replace slot:", color: .yellow, bold: true)
                self.print("  \(selected.slotName) (\(selected.breakpointCount) saves)", color: .yellow)
                self.print("  \(selected.latest.partyDescription)", color: .dimGreen)
                self.print("")

                self.showMenu(["Yes, Replace", "Different Slot", "Quit Without Saving"])
                self.menuLongPressHandler = { [weak self] confirm in
                    if confirm == 3 { self?.performQuit() }
                }
                self.closeHandler = { [weak self] in self?.showExplorationView() }
                self.menuHandler = { [weak self] confirm in
                    guard let self = self else { return }
                    switch confirm {
                    case 1:
                        self.deleteSlotClearingActiveIfNeeded(selected.slotId)
                        self.askForNewSlotName()
                    case 2:
                        self.clearTerminal()
                        self.printTitle("Save/Quit")
                        self.showOverwriteSlotMenu(slots: slots)
                    case 3:
                        self.confirmQuitWithoutSaving()
                    default:
                        self.showExplorationView()
                    }
                }
            } else if idx == quitIndex {
                self.confirmQuitWithoutSaving()
            } else if idx == quitIndex + 1 {
                self.showSaveHelp()
            } else {
                self.showExplorationView()
            }
        }
    }

    /// Quick save to active slot (or auto-create) and return to exploration
    private func performQuickSave() {
        guard let dungeon = dungeon else {
            explorationStatusMessage = ("Nothing to save.", .red)
            showExplorationView()
            return
        }
        clearActiveSlotIfDeleted()

        let slotId: UUID
        let slotName: String
        if let existingId = activeSlotId {
            slotId = existingId
            slotName = activeSlotName ?? uniqueSlotName("\(party.first?.name ?? "Hero") — \(dungeon.name)")
        } else {
            slotId = UUID()
            slotName = uniqueSlotName("\(party.first?.name ?? "Hero") — \(dungeon.name)")
            activeSlotId = slotId
            activeSlotName = slotName
        }

        let partyDesc = party.map { "\($0.name) (\($0.characterClass.rawValue))" }.joined(separator: ", ")
        let chatEntries = dmChatLog.map { DMChatEntry(isUser: $0.isUser, text: $0.text) }
        let saveGame = SaveGame(
            id: UUID(), slotId: slotId, savedAt: Date(), slotName: slotName,
            partyDescription: partyDesc, dungeonName: dungeon.name, dungeonLevel: dungeon.level,
            party: party, dungeon: dungeon, gameState: .exploring,
            gameTimeMinutes: gameTimeMinutes, adventureLog: adventureLog,
            dmChatLog: chatEntries, torchLit: torchLit,
            torchTurnsRemaining: torchTurnsRemaining,
            partyChatLog: partyChatLog.suffix(20).map { $0 },
            monstersSlain: monstersSlain,
            combatsWon: combatsWon,
            activeQuest: activeQuest, otherQuests: otherQuests, introLines: adventureIntroLines, mainQuest: mainQuest, questHistory: questHistory, noMainQuest: noMainQuest, mainQuestCompleted: mainQuestCompleted, questSummary: questSummaryLine()
        )

        do {
            try SaveGameManager.shared.save(saveGame)
            SoundManager.shared.playSave()
            logEvent("Quick save: \(slotName)", category: "SYSTEM")
            explorationStatusMessage = ("Game saved! (\"\(slotName)\" — find it under Continue Adventure.)", .brightGreen)
        } catch {
            explorationStatusMessage = ("Save failed: \(error.localizedDescription)", .red)
        }
        showExplorationView()
    }

    private func performSave(slotId: UUID, slotName: String) {
        guard let dungeon = dungeon else { return }

        // If saving during combat, clear the current room's encounter so
        // loading won't immediately throw the player back into battle.
        if gameState == .combat, let room = dungeon.currentRoom, !room.cleared {
            room.cleared = true
            room.encounter = nil
        }

        let partyDesc = party.map { "\($0.name) (\($0.characterClass.rawValue))" }.joined(separator: ", ")

        logEvent("Game saved: \(slotName)", category: "SYSTEM")

        let chatEntries = dmChatLog.map { DMChatEntry(isUser: $0.isUser, text: $0.text) }
        let saveGame = SaveGame(
            id: UUID(),
            slotId: slotId,
            savedAt: Date(),
            slotName: slotName,
            partyDescription: partyDesc,
            dungeonName: dungeon.name,
            dungeonLevel: dungeon.level,
            party: party,
            dungeon: dungeon,
            gameState: .exploring,
            gameTimeMinutes: gameTimeMinutes,
            adventureLog: adventureLog,
            dmChatLog: chatEntries,
            torchLit: torchLit,
            torchTurnsRemaining: torchTurnsRemaining,
            partyChatLog: partyChatLog.suffix(20).map { $0 },
            monstersSlain: monstersSlain,
            combatsWon: combatsWon,
            activeQuest: activeQuest, otherQuests: otherQuests, introLines: adventureIntroLines, mainQuest: mainQuest, questHistory: questHistory, noMainQuest: noMainQuest, mainQuestCompleted: mainQuestCompleted, questSummary: questSummaryLine()
        )

        do {
            try SaveGameManager.shared.save(saveGame)
            lastSaveTime = Date()
            SoundManager.shared.playSave()
            printLines(asciiScroll, color: .brightGreen)
            print("")
            print("Game saved!", color: .brightGreen, bold: true)
            print("")
            print("  \(slotName)", color: .cyan)
            print("  \(partyDesc)", color: .dimGreen)
            print("  \(dungeon.name) (Level \(dungeon.level))", color: .dimGreen)

            let breakpoints = SaveGameManager.shared.listBreakpoints(slotId: slotId)
            let slotCount = SaveGameManager.shared.listSlots().count
            print("")
            let bpWord = breakpoints.count == 1 ? "save" : "saves"
            print("  \(breakpoints.count) \(bpWord) in this adventure", color: .dimGreen)
            print("  \(slotCount)/\(SaveGameManager.limitLabel(SaveGameManager.maxSlotsSetting)) adventures saved", color: .dimGreen)
        } catch {
            print("Failed to save: \(error.localizedDescription)", color: .red)
        }

        print("")

        showMenu(["Continue", "Load Game", "Main Menu"])

        menuHandler = { [weak self] choice in
            switch choice {
            case 1: self?.showExplorationView()
            case 2: self?.showLoadGameMenu(returnTo: .exploration)
            case 3: self?.resetGame()
            default: self?.showExplorationView()
            }
        }
    }

    /// A single row in the unified Continue Adventure list. Most rows are a
    /// real, loadable save slot — but a Hall of Fame entry recorded before
    /// adventures got linked saves (or whose linked save has since been
    /// trimmed/deleted) has no slot to attach to. It still gets a row here,
    /// styled and reached exactly the same way as everything else — it just
    /// has no save to relive/continue from, so tapping it skips straight to
    /// the tale instead of a save-detail screen. This is what actually
    /// fixes "old Hall of Fame entries behave differently": previously they
    /// were entirely absent from this list whenever they had no (surviving)
    /// linked save, and only reachable via the separate Hall of Fame screen.
    private enum AdventureRow {
        case slot(SaveSlot)
        case orphanHof(HallOfFameEntry)
    }

    /// Approximate monospace column width of a string, for budgeting how
    /// much text fits in a button label. Plain `.count` (grapheme clusters)
    /// undercounts emoji — most (e.g. the "⭐" some seed save names start
    /// with) render about twice as wide as a regular character in a
    /// monospaced font, so a budget based on `.count` alone let text that
    /// technically "fit" actually overflow its button's box.
    private func displayWidth(_ s: String) -> Int {
        s.reduce(0) { total, char in
            total + (char.unicodeScalars.contains(where: { $0.properties.isEmojiPresentation }) ? 2 : 1)
        }
    }

    private func showLoadGameMenu(returnTo origin: LoadGameOrigin, page: Int = 0) {
        clearTerminal()
        printTitle("Continue Adventure")

        let backAction: () -> Void = { [weak self] in
            switch origin {
            case .mainMenu:
                self?.clearTerminal()
                self?.showMainMenu()
            case .exploration:
                self?.showExplorationView()
            case .settings:
                self?.showSaveSettings()
            }
        }
        closeHandler = backAction

        let slots = SaveGameManager.shared.listSlots()
        let allHofEntries = HallOfFameManager.shared.listEntries()

        // Every entry here is backed by an actual save — no separate
        // "Hall of Fame entry with no surviving save" row anymore (that
        // used to linger even after the player deleted every save, which
        // read as two disconnected lists of the same adventures instead of
        // one). A slot whose latest save happens to be linked from a
        // completed Hall of Fame entry is simply shown in that entry's own
        // style (outcome tag + score) instead of PLAYING.
        let hofBySaveId: [UUID: HallOfFameEntry] = Dictionary(
            allHofEntries.compactMap { entry in entry.saveGameId.map { ($0, entry) } },
            uniquingKeysWith: { first, _ in first }
        )
        // Garbage-collect anything left over from before this was fixed,
        // or from a deletion path that predates SaveGameManager.delete's
        // own cascade — quietly, on every visit, so a deleted adventure
        // never resurfaces here again.
        for entry in allHofEntries where entry.saveGameId == nil || SaveGameManager.shared.load(id: entry.saveGameId!) == nil {
            HallOfFameManager.shared.deleteEntry(id: entry.id)
        }

        var rows: [AdventureRow] = slots.map { .slot($0) }

        if rows.isEmpty {
            print("  No saved games or adventures recorded yet.", color: .yellow)
            print("")
            // Same button set as the Play menu itself (Continue Adventure/
            // New Adventure/?/Back), rather than a bespoke minimal screen —
            // Continue Adventure just sits disabled here since there's
            // nothing to continue (long-press still redirects to New
            // Adventure, matching the Play menu's own dimmed button).
            let opts = [MenuOption("Continue Adventure", isDisabled: true), MenuOption("New Adventure"),
                        MenuOption("?", tint: .navigation, compact: true), MenuOption("< Back", tint: .navigation, compact: true)]
            showMenuOptions(opts)
            menuHandler = { [weak self] choice in
                guard let self = self, choice >= 1, choice <= opts.count else { return }
                switch opts[choice - 1].text {
                case "New Adventure": self.startNewGame()
                case "?":
                    self.showInlineHelp {
                        self.printTitle("Continue Adventure — Help")
                        self.print("")
                        self.printWrapped("Once you've saved (or completed) an adventure, it'll show up here — tap it to continue, or see how it ended.", indent: 2, color: .dimGreen)
                        self.print("")
                        self.printWrapped("Start one from New Adventure on the Play menu.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                default: backAction()
                }
            }
            menuLongPressHandler = { [weak self] choice in
                guard choice == 1 else { return }
                self?.startNewGame()
            }
            closeHandler = backAction
            return
        }

        func rowDate(_ row: AdventureRow) -> Date {
            switch row {
            case .slot(let s): return s.latest.savedAt
            case .orphanHof(let e): return e.date
            }
        }
        func rowScore(_ row: AdventureRow) -> Int? {
            switch row {
            case .slot(let s): return hofBySaveId[s.latest.id]?.score
            case .orphanHof(let e): return e.score
            }
        }
        func rowName(_ row: AdventureRow) -> String {
            switch row {
            case .slot(let s): return s.slotName
            case .orphanHof(let e): return e.partyNames.first ?? e.dungeonName
            }
        }
        func rowLevel(_ row: AdventureRow) -> Int {
            switch row {
            case .slot(let s): return s.latest.dungeonLevel
            case .orphanHof(let e): return e.dungeonLevel
            }
        }

        switch listSortMode {
        case .date:
            rows.sort { rowDate($0) > rowDate($1) }
        case .points:
            // Rows with no score yet (in-progress saves) sort after every
            // completed (scored) adventure, most recent first among themselves.
            rows.sort { a, b in
                switch (rowScore(a), rowScore(b)) {
                case let (sa?, sb?): return sa > sb
                case (nil, nil): return rowDate(a) > rowDate(b)
                case (_?, nil): return true
                case (nil, _?): return false
                }
            }
        case .name:
            rows.sort { rowName($0).localizedCaseInsensitiveCompare(rowName($1)) == .orderedAscending }
        case .level:
            rows.sort { rowLevel($0) > rowLevel($1) }
        }

        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .medium
        dateFormatter.timeStyle = .short

        // Quick flip between newest-first and most-points-first right here
        // (every order, incl. name and level, is in Settings > Gameplay >
        // List Order). Tap the line itself.
        let sortLineIndex = terminalLines.count
        let nextSort: ListSortMode = listSortMode == .date ? .points : .date
        let currentSortName = listSortMode == .date ? "newest" : (listSortMode == .points ? "most points" : listSortMode.label.lowercased())
        print("  Sorted by \(currentSortName) — tap here for \(nextSort == .date ? "newest" : "most points") first", color: .cyan, underlined: true)
        print("")

        var options: [String] = []
        // Exact printed-line range per entry (not a guessed fixed count —
        // printWrapped can span more than one terminal line depending on
        // text length) so tapping the printed text, not just the button,
        // can open the right entry.
        var entryLineRanges: [Range<Int>] = []
        for (i, row) in rows.enumerated() {
            let lineStart = terminalLines.count

            switch row {
            case .slot(let slot):
                let save = slot.latest
                let day = save.gameTimeMinutes / 1440 + 1
                let bpInfo = slot.breakpointCount > 1 ? " (\(slot.breakpointCount) saves)" : ""

                if let entry = hofBySaveId[save.id] {
                    let outcomeTag = entry.outcome == .victory ? "W" : "L"
                    let outcomeColor: TerminalColor = entry.outcome == .victory ? .yellow : .red
                    let name = String(entry.dungeonName.prefix(20))
                    printWrapped("\(i + 1). \(name) Lv.\(entry.dungeonLevel) \(outcomeTag) \(entry.score)pts\(bpInfo)", color: outcomeColor, bold: true)
                    printWrapped(entry.partyDescription, indent: 3, color: .dimGreen)
                    if let q = save.questSummary { printWrapped(q, indent: 3, color: q.hasPrefix("★") ? .yellow : .cyan) }
                    printWrapped("Gold:\(entry.goldCollected) Slain:\(entry.monstersSlain) Lv\(entry.dungeonLevel) rooms:\(entry.roomsExplored)/\(entry.totalRooms) Day \(day)", indent: 3, color: .dimGreen)
                } else {
                    let gold = save.party.reduce(0) { $0 + $1.gold }
                    let roomsExplored = save.dungeon.rooms.values.filter { $0.visited }.count
                    let totalRooms = save.dungeon.rooms.count
                    printWrapped("\(i + 1). \(save.dungeonName) Lv.\(save.dungeonLevel) PLAYING\(bpInfo)", color: .cyan, bold: true)
                    printWrapped(save.partyDescription, indent: 3, color: .dimGreen)
                    if let q = save.questSummary { printWrapped(q, indent: 3, color: .cyan) }
                    printWrapped("Gold:\(gold) Slain:\(save.monstersSlain) Lv\(save.dungeonLevel) rooms:\(roomsExplored)/\(totalRooms) Day \(day)", indent: 3, color: .dimGreen)
                }
                printWrapped(dateFormatter.string(from: save.savedAt), indent: 3, color: .dimGreen)
                print("")

                let parts = slot.slotName.components(separatedBy: " — ")
                let charName = parts.first ?? slot.slotName
                let location = save.dungeonName
                let maxLen = 20
                if displayWidth(charName) + displayWidth(location) + 3 <= maxLen {
                    options.append("\(charName) · \(location)")
                } else {
                    let locBudget = max(4, maxLen - displayWidth(charName) - 3)
                    options.append("\(charName) · \(location.prefix(locBudget))")
                }

            case .orphanHof(let entry):
                // Same Hall-of-Fame row style as a linked slot above — this
                // entry just predates (or outlived) per-adventure saves, so
                // there's nothing to load. "Read Tale" still works, styled
                // and accessed identically.
                let day = entry.gameTimeMinutes / 1440 + 1
                let outcomeTag = entry.outcome == .victory ? "W" : "L"
                let outcomeColor: TerminalColor = entry.outcome == .victory ? .yellow : .red
                let name = String(entry.dungeonName.prefix(20))
                printWrapped("\(i + 1). \(name) Lv.\(entry.dungeonLevel) \(outcomeTag) \(entry.score)pts (no save)", color: outcomeColor, bold: true)
                printWrapped(entry.partyDescription, indent: 3, color: .dimGreen)
                printWrapped("Gold:\(entry.goldCollected) Slain:\(entry.monstersSlain) Lv\(entry.dungeonLevel) rooms:\(entry.roomsExplored)/\(entry.totalRooms) Day \(day)", indent: 3, color: .dimGreen)
                printWrapped(dateFormatter.string(from: entry.date), indent: 3, color: .dimGreen)
                print("")

                let charName = entry.partyNames.first ?? "Hero"
                let location = entry.dungeonName
                let maxLen = 20
                if displayWidth(charName) + displayWidth(location) + 3 <= maxLen {
                    options.append("\(charName) · \(location)")
                } else {
                    let locBudget = max(4, maxLen - displayWidth(charName) - 3)
                    options.append("\(charName) · \(location.prefix(locBudget))")
                }
            }

            entryLineRanges.append(lineStart..<terminalLines.count)
        }

        // Was a plain showMenu() with every slot as its own button plus
        // "Manage Saves"/"Hall of Fame" tacked on — ignored maxButtonsPerScreen
        // entirely, so a long save history just kept growing the button list
        // past the configured limit instead of paging. "Manage Saves" (a
        // separate screen re-listing the exact same slots) is gone too —
        // tapping an entry now goes to showSaveSlotDetail(), which shows its
        // save points, a "Read Tale" narrative, AND a "Manage" (rename/copy/
        // delete) button, so there's one place to find any entry. A row with
        // no save (see AdventureRow.orphanHof) skips straight to the tale,
        // since there's no save-detail to show.
        let openRow: (AdventureRow) -> Void = { [weak self] row in
            guard let self = self else { return }
            switch row {
            case .slot(let slot):
                self.showSaveSlotDetail(slot: slot, returnTo: origin)
            case .orphanHof(let entry):
                let backToList: () -> Void = { [weak self] in self?.showLoadGameMenu(returnTo: origin) }
                self.showAdventureTale(AdventureTaleData(hof: entry), onBack: backToList)
            }
        }

        // Multi-select ("Select" pinned button): checkbox-prefix each row,
        // tapping toggles instead of opening it, "Select All"/"Delete
        // Selected" appear once at least one is checked. Only .slot rows
        // are selectable/deletable this way — an orphan Hall of Fame entry
        // has no save behind it to delete.
        if manageSaveSelectMode {
            let selectableSlotIds = rows.compactMap { row -> UUID? in
                if case .slot(let s) = row { return s.slotId }
                return nil
            }
            let displayOptions = zip(options, rows).map { label, row -> String in
                if case .slot(let s) = row {
                    return (manageSaveSelectedSlotIds.contains(s.slotId) ? "[x] " : "[ ] ") + label
                }
                return label
            }
            var pinned = ["Select All", "Deselect All", "?", "< Back"]
            if !manageSaveSelectedSlotIds.isEmpty {
                pinned.insert("Delete Selected (\(manageSaveSelectedSlotIds.count))", at: 2)
            }
            showPaginatedMenuOptions(displayOptions, page: page, pinned: pinned, handler: { [weak self] idx in
                guard let self = self, idx >= 0 && idx < rows.count else { return }
                guard case .slot(let slot) = rows[idx] else { return }
                if self.manageSaveSelectedSlotIds.contains(slot.slotId) {
                    self.manageSaveSelectedSlotIds.remove(slot.slotId)
                } else {
                    self.manageSaveSelectedSlotIds.insert(slot.slotId)
                }
                self.showLoadGameMenu(returnTo: origin, page: self.paginatedPage)
            }, pinnedHandler: { [weak self] choice in
                guard let self = self else { return }
                let chosen = pinned[choice]
                switch chosen {
                case "Select All":
                    self.manageSaveSelectedSlotIds = Set(selectableSlotIds)
                    self.showLoadGameMenu(returnTo: origin, page: self.paginatedPage)
                case "Deselect All":
                    self.manageSaveSelectedSlotIds.removeAll()
                    self.showLoadGameMenu(returnTo: origin, page: self.paginatedPage)
                case "?":
                    self.showInlineHelp {
                        self.printTitle("Select Saves — Help")
                        self.print("")
                        self.printWrapped("Tap a row to check/uncheck it. \"Select All\" toggles every selectable row at once. Once at least one is checked, \"Delete Selected\" removes all of them permanently.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                default:
                    if chosen.hasPrefix("Delete Selected") {
                        let count = self.manageSaveSelectedSlotIds.count
                        self.clearTerminal()
                        self.printTitle("Delete \(count) Save\(count == 1 ? "" : "s")?")
                        self.print("")
                        self.print("  This cannot be undone.", color: .red)
                        self.print("")
                        self.showMenu(["Delete Permanently", "< Cancel"])
                        self.menuHandler = { [weak self] c in
                            guard let self = self else { return }
                            if c == 1 {
                                for id in self.manageSaveSelectedSlotIds {
                                    self.deleteSlotClearingActiveIfNeeded(id)
                                }
                                self.manageSaveSelectedSlotIds.removeAll()
                                self.manageSaveSelectMode = false
                            }
                            self.showLoadGameMenu(returnTo: origin)
                        }
                    } else {
                        self.manageSaveSelectMode = false
                        self.manageSaveSelectedSlotIds.removeAll()
                        self.showLoadGameMenu(returnTo: origin)
                    }
                }
            })
            closeHandler = { [weak self] in
                guard let self = self else { return }
                self.manageSaveSelectMode = false
                self.manageSaveSelectedSlotIds.removeAll()
                backAction()
            }
            return
        }

        // This list already covers what a separate "Hall of Fame" button
        // used to (every completed tale shows its W/L result right here,
        // alongside adventures still in progress) — so rather than a
        // second, near-duplicate list elsewhere, "Manage" is pinned right
        // here for renaming/deleting saves, which is the one thing this
        // screen's own list doesn't do inline.
        let pinnedButtons = ["Manage", "?", "< Back"]
        showPaginatedMenuOptions(options, page: page, pinned: pinnedButtons, handler: { idx in
            guard idx >= 0 && idx < rows.count else { return }
            openRow(rows[idx])
        }, pinnedHandler: { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case pinnedButtons.firstIndex(of: "Manage") ?? -1:
                self.showManageSavesMenu(returnTo: origin)
            case pinnedButtons.firstIndex(of: "?") ?? -1:
                self.showInlineHelp {
                    self.printTitle("Continue Adventure — Help")
                    self.print("")
                    self.printWrapped("Tap an entry's button, or its description text, to see its save points and read its tale. Long-press a numbered button to load that adventure's latest save directly.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.printWrapped("A completed adventure shows its Hall of Fame result (W/L, score); one still in progress shows PLAYING. Either way it's read and continued the same way.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  COLOUR", color: .cyan, bold: true)
                    self.printWrapped("Cyan = still in progress (PLAYING). Yellow = you won (W). Red = your party fell (L) — you can still revisit or relive it.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  MANAGE", color: .cyan, bold: true)
                    self.printWrapped("Rename, copy, or delete saves — including bulk multi-select delete.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            default:
                backAction()
            }
        })

        // Long-press → load latest save directly (skip the slot detail
        // screen); no-op for a row with no save.
        menuLongPressHandler = { [weak self] choice in
            guard choice >= 1, choice <= rows.count else { return }
            if case .slot(let slot) = rows[choice - 1] {
                self?.loadGame(slot.latest)
            }
        }

        // Tap the printed entry text itself (not just its numbered button)
        // to open the same detail screen — despite the name,
        // textLongPressHandler drives a plain tap gesture on the terminal
        // text (see textTapEnabled), so the descriptive block above each
        // button is a live target too, not just inert decoration.
        textLongPressHandler = { [weak self] lineIndex in
            if lineIndex == sortLineIndex {
                self?.listSortMode = nextSort
                self?.showLoadGameMenu(returnTo: origin)
                return
            }
            guard let idx = entryLineRanges.firstIndex(where: { $0.contains(lineIndex) }) else { return }
            openRow(rows[idx])
        }
    }

    /// Shows a save slot's available save points, a "Read Tale" narrative
    /// (see showTaleForSlot — generated the same way whether or not this
    /// adventure is actually finished), and a "Manage" button (rename/copy/
    /// delete — see showSaveSlotManage). Always shown on tapping a slot, not
    /// just when it has more than one save point, so there's a single
    /// consistent path in from the load list.
    private func showSaveSlotDetail(slot: SaveSlot, returnTo origin: LoadGameOrigin) {
        clearTerminal()
        printTitle(slot.slotName)
        print("  \(slot.latest.partyDescription)", color: .dimGreen)
        print("  \(slot.latest.dungeonName) (Level \(slot.latest.dungeonLevel))", color: .dimGreen)
        print("")

        let breakpoints = SaveGameManager.shared.listBreakpoints(slotId: slot.slotId)
        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .short
        dateFormatter.timeStyle = .short

        // Each save point's printed lines, so tapping its text loads it —
        // same as the Continue Adventure list one screen back.
        var entryLineRanges: [Range<Int>] = []
        for (index, bp) in breakpoints.enumerated() {
            let lineStart = terminalLines.count
            defer { entryLineRanges.append(lineStart..<terminalLines.count) }
            let dateStr = dateFormatter.string(from: bp.savedAt)
            let day = bp.gameTimeMinutes / 1440 + 1
            let hourOfDay = (bp.gameTimeMinutes % 1440) / 60
            let period = hourOfDay >= 12 ? "PM" : "AM"
            let hour12 = hourOfDay == 0 ? 12 : (hourOfDay > 12 ? hourOfDay - 12 : hourOfDay)
            let marker = index == 0 ? " (latest)" : ""
            print("\(index + 1). Day \(day), \(hour12) \(period)\(marker)", color: index == 0 ? .brightGreen : .green)
            print("   \(dateStr) — \(bp.dungeonName) Lv\(bp.dungeonLevel)", color: .dimGreen)
        }
        print("")

        let options = breakpoints.enumerated().map { i, _ in
            i == 0 ? "Load Latest" : "Load #\(i + 1)"
        }

        // "Read Tale" is a regular (numbered) pinned button, not squeezed
        // into the compact ?/Manage/Back cell — it's a primary action here,
        // not a secondary one.
        showPaginatedMenuOptions(options, pinned: ["Read Tale", "?", "Manage", "< Back"], handler: { [weak self] idx in
            guard let self = self, idx >= 0 && idx < breakpoints.count else { return }
            self.loadGame(breakpoints[idx])
        }, pinnedHandler: { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 0: self.showTaleForSlot(slot: slot, returnTo: origin)
            case 1:
                self.showInlineHelp {
                    self.printTitle("\(slot.slotName) — Help")
                    self.print("")
                    self.print("  LOAD LATEST / LOAD #N", color: .cyan, bold: true)
                    self.printWrapped("Continue this adventure from that save point — tap its button or its text. Long-press any of these to load the latest one directly.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  READ TALE", color: .cyan, bold: true)
                    self.printWrapped("A narrative of this adventure so far — same style whether it's finished or still in progress.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  MANAGE", color: .cyan, bold: true)
                    self.printWrapped("Rename, copy, or delete this adventure — or delete a single save point.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            case 2: self.showSaveSlotManage(slot: slot, returnTo: origin)
            default: self.showLoadGameMenu(returnTo: origin)
            }
        })

        menuLongPressHandler = { [weak self] choice in
            guard choice > 0 && choice <= breakpoints.count else { return }
            self?.loadGame(breakpoints[choice - 1])
        }

        textLongPressHandler = { [weak self] lineIndex in
            guard let idx = entryLineRanges.firstIndex(where: { $0.contains(lineIndex) }),
                  idx < breakpoints.count else { return }
            self?.loadGame(breakpoints[idx])
        }

        closeHandler = { [weak self] in self?.showLoadGameMenu(returnTo: origin) }
    }

    /// Builds and shows the narrative for a save slot — from its linked
    /// Hall of Fame entry if the adventure's been completed, or generated
    /// directly from the save's own stats if it's still in progress. Same
    /// screen, same style, either way (see AdventureTaleData/showAdventureTale).
    private func showTaleForSlot(slot: SaveSlot, returnTo origin: LoadGameOrigin) {
        let backToDetail: () -> Void = { [weak self] in self?.showSaveSlotDetail(slot: slot, returnTo: origin) }
        if let entry = HallOfFameManager.shared.listEntries().first(where: { $0.saveGameId == slot.latest.id }) {
            showAdventureTale(AdventureTaleData(hof: entry), onBack: backToDetail)
        } else {
            showAdventureTale(AdventureTaleData(inProgress: slot.latest), onBack: backToDetail)
        }
    }

    /// Rename / Copy / Delete for one save slot — reached via the "Manage"
    /// button on showSaveSlotDetail, rather than a separate top-level
    /// "Manage Saves" screen that re-listed every slot a second time.
    private func showSaveSlotManage(slot: SaveSlot, returnTo origin: LoadGameOrigin) {
        clearTerminal()
        printTitle("Manage")
        print("  \(slot.slotName)", color: .brightGreen, bold: true)
        print("  \(slot.latest.partyDescription)", color: .dimGreen)
        let saveWord = slot.breakpointCount == 1 ? "save" : "saves"
        print("  \(slot.breakpointCount) \(saveWord)", color: .dimGreen)
        print("")

        let backToDetail: () -> Void = { [weak self] in self?.showSaveSlotDetail(slot: slot, returnTo: origin) }
        // "Delete One Save" only makes sense when there's more than one save
        // point — with just one, "Delete Adventure" already covers it.
        let hasMultipleSaves = slot.breakpointCount > 1
        var options = ["Rename", "Copy"]
        if hasMultipleSaves { options.append("Delete One Save") }
        options.append(contentsOf: ["Delete Adventure", "?", "< Back"])
        showMenu(options)
        closeHandler = backToDetail
        // Long-press Delete Adventure deletes straight away — no confirmation.
        menuLongPressHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= options.count, options[choice - 1] == "Delete Adventure" else { return }
            self.deleteSlotClearingActiveIfNeeded(slot.slotId)
            self.showLoadGameMenu(returnTo: origin)
        }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= options.count else { return }
            let backToManage: () -> Void = { [weak self] in self?.showSaveSlotManage(slot: slot, returnTo: origin) }
            let backToList: () -> Void = { [weak self] in self?.showLoadGameMenu(returnTo: origin) }
            switch options[choice - 1] {
            case "Rename": self.renameSlot(slot: slot, returnTo: origin, onCancel: backToManage, onDone: backToList)
            case "Copy": self.duplicateSlot(slot: slot, returnTo: origin)
            case "Delete One Save": self.showBreakpointList(slot: slot, returnTo: origin, onBack: backToManage, onAllDeleted: backToList)
            case "Delete Adventure": self.confirmDeleteSlot(slot: slot, returnTo: origin, onCancel: backToManage, onDone: backToList)
            case "?":
                self.showInlineHelp {
                    self.printTitle("Manage — Help")
                    self.print("")
                    self.print("  RENAME", color: .cyan, bold: true)
                    self.printWrapped("Change this adventure's display name. Renames every save point in this slot.", indent: 2, color: .dimGreen)
                    self.print("")
                    self.print("  COPY", color: .cyan, bold: true)
                    self.printWrapped("Duplicates every save point in this slot into a brand new, independent adventure you can play separately.", indent: 2, color: .dimGreen)
                    self.print("")
                    if hasMultipleSaves {
                        self.print("  DELETE ONE SAVE", color: .cyan, bold: true)
                        self.printWrapped("Removes a single save point from this slot, keeping the rest.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                    self.print("  DELETE ADVENTURE", color: .cyan, bold: true)
                    self.printWrapped("Permanently deletes every save point in this slot. Cannot be undone.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            case "< Back": backToDetail()
            default: break
            }
        }
    }

    /// Copies every save point in `slot` into a brand new, independent slot
    /// named "<original> (Copy)" (numbered further if that's already taken).
    private func duplicateSlot(slot: SaveSlot, returnTo origin: LoadGameOrigin) {
        let breakpoints = SaveGameManager.shared.listBreakpoints(slotId: slot.slotId)
        guard !breakpoints.isEmpty else {
            showSaveSlotManage(slot: slot, returnTo: origin)
            return
        }

        let existingNames = Set(SaveGameManager.shared.listSlots().map { $0.slotName.lowercased() })
        var copyName = "\(slot.slotName) (Copy)"
        var suffix = 2
        while existingNames.contains(copyName.lowercased()) {
            copyName = "\(slot.slotName) (Copy \(suffix))"
            suffix += 1
        }

        let newSlotId = UUID()
        for bp in breakpoints {
            let copy = SaveGame(
                id: UUID(),
                slotId: newSlotId,
                savedAt: bp.savedAt,
                slotName: copyName,
                partyDescription: bp.partyDescription,
                dungeonName: bp.dungeonName,
                dungeonLevel: bp.dungeonLevel,
                party: bp.party,
                dungeon: bp.dungeon,
                gameState: bp.gameState,
                gameTimeMinutes: bp.gameTimeMinutes,
                adventureLog: bp.adventureLog,
                dmChatLog: bp.dmChatLog,
                torchLit: bp.torchLit,
                torchTurnsRemaining: bp.torchTurnsRemaining,
                partyChatLog: bp.partyChatLog,
                monstersSlain: bp.monstersSlain,
                combatsWon: bp.combatsWon,
                activeQuest: bp.activeQuest, otherQuests: bp.otherQuests, introLines: bp.introLines, mainQuest: bp.mainQuest, questHistory: bp.questHistory, noMainQuest: bp.noMainQuest, mainQuestCompleted: bp.mainQuestCompleted, questSummary: bp.questSummary
            )
            try? SaveGameManager.shared.save(copy)
        }

        print("")
        print("  Copied to '\(copyName)'.", color: .brightGreen)
        waitForContinue()
        inputHandler = { [weak self] _ in self?.showLoadGameMenu(returnTo: origin) }
    }

    private func showManageSavesMenu(returnTo origin: LoadGameOrigin) {
        clearTerminal()
        printTitle("Manage Saves")

        let slots = SaveGameManager.shared.listSlots()

        // Load remote matches asynchronously, then render the full menu
        if multiplayerEnabled && GameCenterManager.shared.isAuthenticated {
            print("Loading remote games...", color: .dimGreen)
            Task {
                let matches = (try? await GKTurnBasedMatch.loadMatches()) ?? []
                let activeMatches = matches.filter { $0.status == .open || $0.status == .matching }
                await MainActor.run {
                    self.renderManageSavesMenu(slots: slots, remoteMatches: activeMatches, returnTo: origin)
                }
            }
        } else {
            renderManageSavesMenu(slots: slots, remoteMatches: [], returnTo: origin)
        }
    }

    private func renderManageSavesMenu(slots: [SaveSlot], remoteMatches: [GKTurnBasedMatch], returnTo origin: LoadGameOrigin, page: Int = 0) {
        clearTerminal()
        printTitle("Manage Saves")

        let hasLocalSlots = !slots.isEmpty
        let hasRemoteMatches = !remoteMatches.isEmpty

        if !hasLocalSlots && !hasRemoteMatches {
            print("No saved games to manage.", color: .yellow)
            print("")
            print("Start an adventure first!", color: .dimGreen)
            print("")
            let goBack: () -> Void = { [weak self] in
                switch origin {
                case .mainMenu: self?.showPlayMenu()
                case .exploration: self?.showExplorationView()
                case .settings: self?.showSettings()
                }
            }
            showMenu(["New Adventure", "?", "< Back"])
            closeHandler = goBack
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                switch choice {
                case 1:
                    self.startNewGame()
                case 2:
                    self.showInlineHelp {
                        self.printTitle("Manage Saves — Help")
                        self.print("")
                        self.printWrapped("Rename, copy, or delete saved games and remote multiplayer matches — once you've got one to manage.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                default:
                    goBack()
                }
            }
            return
        }

        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .medium
        dateFormatter.timeStyle = .short

        // Exact printed-line range per entry, in the same order actions[]
        // is built below (local slots, then remote matches) — so tapping
        // an entry's description text, not just its numbered button, can
        // open it too, matching Continue Adventure's own list.
        var entryLineRanges: [Range<Int>] = []

        // List local save slots
        if hasLocalSlots {
            print("Local Saves", color: .cyan, bold: true)
            print("")
            for (index, slot) in slots.enumerated() {
                let lineStart = terminalLines.count
                let dateStr = dateFormatter.string(from: slot.latest.savedAt)
                let bpInfo = slot.breakpointCount > 1 ? " (\(slot.breakpointCount) saves)" : ""
                print("\(index + 1). \(slot.slotName)\(bpInfo)", color: .brightGreen)
                print("   \(slot.latest.partyDescription)", color: .dimGreen)
                print("   \(dateStr)", color: .dimGreen)
                print("")
                entryLineRanges.append(lineStart..<terminalLines.count)
            }
        }

        // List remote multiplayer matches
        if hasRemoteMatches {
            print("Remote Games", color: .cyan, bold: true)
            print("")
            for (index, match) in remoteMatches.enumerated() {
                let lineStart = terminalLines.count
                let opponentName = remoteMatchOpponentName(match)
                let phaseStr = remoteMatchPhaseString(match)
                let num = slots.count + index + 1
                print("\(num). vs. \(opponentName)", color: .brightGreen)
                print("   \(phaseStr)", color: .dimGreen)
                print("")
                entryLineRanges.append(lineStart..<terminalLines.count)
            }
        }

        let backToLoadGame: () -> Void = { [weak self] in self?.showLoadGameMenu(returnTo: origin) }

        // Bulk multi-select (local slots only — remote matches already have
        // their own "Delete All Remote Games" bulk shortcut below). Mirrors
        // Continue Adventure's own select mode.
        if manageSaveSelectMode {
            let displayOptions = slots.map { slot -> String in
                (manageSaveSelectedSlotIds.contains(slot.slotId) ? "[x] " : "[ ] ") + slot.slotName
            }
            var pinned = ["Select All", "Deselect All", "?", "< Back"]
            if !manageSaveSelectedSlotIds.isEmpty {
                pinned.insert("Delete Selected (\(manageSaveSelectedSlotIds.count))", at: 2)
            }
            print("Tap slots to select, then Delete Selected:", color: .cyan)
            showPaginatedMenuOptions(displayOptions, page: page, pinned: pinned, handler: { [weak self] idx in
                guard let self = self, idx >= 0 && idx < slots.count else { return }
                let slotId = slots[idx].slotId
                if self.manageSaveSelectedSlotIds.contains(slotId) {
                    self.manageSaveSelectedSlotIds.remove(slotId)
                } else {
                    self.manageSaveSelectedSlotIds.insert(slotId)
                }
                self.renderManageSavesMenu(slots: slots, remoteMatches: remoteMatches, returnTo: origin, page: self.paginatedPage)
            }, pinnedHandler: { [weak self] choice in
                guard let self = self else { return }
                let chosen = pinned[choice]
                if chosen == "Select All" {
                    self.manageSaveSelectedSlotIds = Set(slots.map { $0.slotId })
                    self.renderManageSavesMenu(slots: slots, remoteMatches: remoteMatches, returnTo: origin, page: self.paginatedPage)
                } else if chosen == "Deselect All" {
                    self.manageSaveSelectedSlotIds.removeAll()
                    self.renderManageSavesMenu(slots: slots, remoteMatches: remoteMatches, returnTo: origin, page: self.paginatedPage)
                } else if chosen.hasPrefix("Delete Selected") {
                    let count = self.manageSaveSelectedSlotIds.count
                    self.clearTerminal()
                    self.printTitle("Delete \(count) Save\(count == 1 ? "" : "s")?")
                    self.print("")
                    self.print("  This cannot be undone.", color: .red)
                    self.print("")
                    self.showMenu(["Delete Permanently", "< Cancel"])
                    self.menuHandler = { [weak self] c in
                        guard let self = self else { return }
                        if c == 1 {
                            for id in self.manageSaveSelectedSlotIds {
                                self.deleteSlotClearingActiveIfNeeded(id)
                            }
                            self.manageSaveSelectedSlotIds.removeAll()
                            self.manageSaveSelectMode = false
                        }
                        self.showManageSavesMenu(returnTo: origin)
                    }
                } else if chosen == "?" {
                    self.showInlineHelp {
                        self.printTitle("Manage Saves — Help")
                        self.print("")
                        self.printWrapped("Tap a slot to check/uncheck it, Select All to grab every local save, then Delete Selected to remove them all at once.", indent: 2, color: .dimGreen)
                        self.print("")
                    }
                } else {
                    self.manageSaveSelectMode = false
                    self.manageSaveSelectedSlotIds.removeAll()
                    self.showManageSavesMenu(returnTo: origin)
                }
            })
            closeHandler = { [weak self] in
                guard let self = self else { return }
                self.manageSaveSelectMode = false
                self.manageSaveSelectedSlotIds.removeAll()
                backToLoadGame()
            }
            return
        }

        // Build menu options
        var options: [String] = []
        var actions: [() -> Void] = []

        for slot in slots {
            options.append(slot.slotName)
            actions.append { [weak self] in
                self?.showSlotActions(slot: slot, returnTo: origin)
            }
        }

        for match in remoteMatches {
            let opponentName = remoteMatchOpponentName(match)
            options.append("vs. \(opponentName)")
            actions.append { [weak self] in
                self?.showRemoteMatchActions(match: match, returnTo: origin)
            }
        }

        if remoteMatches.count >= 2 {
            options.append("Delete All Remote Games")
            actions.append { [weak self] in
                self?.confirmDeleteAllRemoteMatches(matches: remoteMatches, returnTo: origin)
            }
        }

        print("Select a slot to manage:", color: .cyan)
        var pinnedButtons = ["?", "< Back"]
        if hasLocalSlots {
            pinnedButtons.insert("Select", at: 0)
        }

        closeHandler = backToLoadGame
        showPaginatedMenuOptions(options, pinned: pinnedButtons, handler: { idx in
            guard idx >= 0 && idx < actions.count else { return }
            actions[idx]()
        }, pinnedHandler: { [weak self] choice in
            guard let self = self else { return }
            let chosen = pinnedButtons[choice]
            if chosen == "Select" {
                self.manageSaveSelectMode = true
                self.renderManageSavesMenu(slots: slots, remoteMatches: remoteMatches, returnTo: origin)
            } else if chosen == "?" {
                self.showInlineHelp {
                    self.printTitle("Manage Saves — Help")
                    self.print("")
                    self.printWrapped("Tap a local save slot or remote game to rename, delete, or otherwise manage it.", indent: 2, color: .dimGreen)
                    if hasLocalSlots {
                        self.print("")
                        self.printWrapped("Select lets you check off several local saves at once and delete them together.", indent: 2, color: .dimGreen)
                    }
                    self.print("")
                }
            } else {
                backToLoadGame()
            }
        })

        // Tap an entry's description text, not just its numbered button —
        // matches Continue Adventure's own list.
        textLongPressHandler = { lineIndex in
            guard let idx = entryLineRanges.firstIndex(where: { $0.contains(lineIndex) }) else { return }
            guard idx < actions.count else { return }
            actions[idx]()
        }
    }

    // MARK: - Remote Match Helpers

    private func remoteMatchOpponentName(_ match: GKTurnBasedMatch) -> String {
        let localID = GKLocalPlayer.local.gamePlayerID
        let opponent = match.participants.first(where: { $0.player?.gamePlayerID != localID })
        return opponent?.player?.displayName ?? "Unknown Player"
    }

    private func remoteMatchPhaseString(_ match: GKTurnBasedMatch) -> String {
        if match.status == .matching { return "Pending Invite" }
        guard let data = match.matchData, !data.isEmpty,
              let state = try? MultiplayerMatchState.decoded(from: data) else {
            return "Remote Game"
        }
        switch state.phase {
        case .characterCreation: return "Character Creation"
        case .exploring: return "Exploring — Level \(state.dungeonLevel)"
        case .combat: return "In Combat — Level \(state.dungeonLevel)"
        case .victory: return "Victory!"
        case .gameOver: return "Game Over"
        case .abandoned: return "Abandoned"
        }
    }

    // MARK: - Remote Match Actions

    private func showRemoteMatchActions(match: GKTurnBasedMatch, returnTo origin: LoadGameOrigin) {
        clearTerminal()
        let opponentName = remoteMatchOpponentName(match)
        printSubtitle("vs. \(opponentName)")
        print("  \(remoteMatchPhaseString(match))", color: .dimGreen)
        print("")

        showMenu(["Delete Match"])

        closeHandler = { [weak self] in self?.showManageSavesMenu(returnTo: origin) }
        menuHandler = { [weak self] choice in
            if choice == 1 { self?.confirmDeleteRemoteMatch(match: match, returnTo: origin) }
        }
    }

    private func confirmDeleteRemoteMatch(match: GKTurnBasedMatch, returnTo origin: LoadGameOrigin) {
        let opponentName = remoteMatchOpponentName(match)
        print("")
        print("Delete this remote game with \(opponentName)?", color: .red, bold: true)
        print("The other player will be notified.", color: .yellow)
        print("")

        showMenu(["Yes, Delete", "No, Keep It"])

        menuHandler = { [weak self] choice in
            if choice == 1 {
                self?.executeDeleteRemoteMatch(match) {
                    self?.print("")
                    self?.print("Match deleted.", color: .red)
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
                        self?.showManageSavesMenu(returnTo: origin)
                    }
                }
            } else {
                self?.showRemoteMatchActions(match: match, returnTo: origin)
            }
        }
    }

    private func confirmDeleteAllRemoteMatches(matches: [GKTurnBasedMatch], returnTo origin: LoadGameOrigin) {
        clearTerminal()
        printTitle("Delete All Remote Games")
        print("")
        print("Delete all \(matches.count) remote games?", color: .red, bold: true)
        print("All other players will be notified.", color: .yellow)
        print("")

        showMenu(["Yes, Delete All", "No, Keep Them"])

        menuHandler = { [weak self] choice in
            if choice == 1 {
                self?.executeDeleteAllRemoteMatches(matches) {
                    self?.print("")
                    self?.print("All remote games deleted.", color: .red)
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
                        self?.showManageSavesMenu(returnTo: origin)
                    }
                }
            } else {
                self?.showManageSavesMenu(returnTo: origin)
            }
        }
    }

    private func executeDeleteRemoteMatch(_ match: GKTurnBasedMatch, completion: @escaping () -> Void) {
        Task {
            do {
                // Pending invites — decline and remove
                if match.status == .matching {
                    try? await match.declineInvite()
                    try? await match.remove()
                    await MainActor.run { completion() }
                    return
                }

                let hasOtherPlayers = match.participants.contains {
                    $0.player?.gamePlayerID != GKLocalPlayer.local.gamePlayerID && $0.status != .done
                }

                if hasOtherPlayers {
                    // Decode state, mark our character as AI, set phase to abandoned
                    if let data = match.matchData, !data.isEmpty,
                       var state = try? MultiplayerMatchState.decoded(from: data) {
                        state.relinkCombat()

                        if let slotIdx = state.players.firstIndex(where: { $0.gamePlayerID == self.localPlayerID }),
                           let charId = state.players[slotIdx].characterId,
                           let char = state.party.first(where: { $0.id == charId }) {
                            char.markAsAI()
                            state.addAction(
                                playerName: GKLocalPlayer.local.displayName,
                                description: "\(char.name) is now AI-controlled (player left)")
                        }
                        state.phase = .abandoned

                        if match.currentParticipant?.player == GKLocalPlayer.local {
                            let others = match.participants.filter {
                                $0.player?.gamePlayerID != GKLocalPlayer.local.gamePlayerID && $0.status != .done
                            }
                            if !others.isEmpty {
                                if let nextPlayer = others.first?.player?.gamePlayerID {
                                    state.activePlayerID = nextPlayer
                                }
                                var trimmed = state
                                trimmed.trimForTransfer()
                                let stateData = try trimmed.encoded()
                                try await match.participantQuitInTurn(
                                    with: .quit,
                                    nextParticipants: others,
                                    turnTimeout: GKTurnTimeoutDefault,
                                    match: stateData
                                )
                            } else {
                                for p in match.participants { p.matchOutcome = .quit }
                                try await match.endMatchInTurn(withMatch: match.matchData ?? Data())
                            }
                        } else {
                            // Not our turn — save the abandoned state, then quit out of turn
                            var trimmed = state
                            trimmed.trimForTransfer()
                            let stateData = try trimmed.encoded()
                            try await match.saveCurrentTurn(withMatch: stateData)
                            try await match.participantQuitOutOfTurn(with: .quit)
                        }
                    } else {
                        // No decodable state — just quit
                        if match.currentParticipant?.player == GKLocalPlayer.local {
                            let others = match.participants.filter { $0.player?.gamePlayerID != GKLocalPlayer.local.gamePlayerID }
                            try await match.participantQuitInTurn(
                                with: .quit,
                                nextParticipants: others,
                                turnTimeout: GKTurnTimeoutDefault,
                                match: match.matchData ?? Data()
                            )
                        } else {
                            try await match.participantQuitOutOfTurn(with: .quit)
                        }
                    }
                } else {
                    // Solo or no other active players — end and remove
                    for p in match.participants { p.matchOutcome = .quit }
                    if match.currentParticipant?.player == GKLocalPlayer.local {
                        try await match.endMatchInTurn(withMatch: match.matchData ?? Data())
                    }
                    try? await match.remove()
                }

                // Clear local multiplayer state if this was the active match
                await MainActor.run {
                    if GameCenterManager.shared.currentMatch?.matchID == match.matchID {
                        self.isMultiplayer = false
                        self.multiplayerState = nil
                        GameCenterManager.shared.currentMatch = nil
                    }
                    completion()
                }
            } catch {
                // Force remove on any error
                try? await match.remove()
                await MainActor.run {
                    if GameCenterManager.shared.currentMatch?.matchID == match.matchID {
                        self.isMultiplayer = false
                        self.multiplayerState = nil
                        GameCenterManager.shared.currentMatch = nil
                    }
                    completion()
                }
            }
        }
    }

    private func executeDeleteAllRemoteMatches(_ matches: [GKTurnBasedMatch], completion: @escaping () -> Void) {
        Task {
            for match in matches {
                await withCheckedContinuation { cont in
                    executeDeleteRemoteMatch(match) {
                        cont.resume()
                    }
                }
            }
            await MainActor.run { completion() }
        }
    }

    private func showSlotActions(slot: SaveSlot, returnTo origin: LoadGameOrigin) {
        clearTerminal()
        printSubtitle(slot.slotName)
        print("  \(slot.latest.partyDescription)", color: .dimGreen)
        print("  \(slot.latest.dungeonName) (Level \(slot.latest.dungeonLevel))", color: .dimGreen)
        let saveWord = slot.breakpointCount == 1 ? "save" : "saves"
        print("  \(slot.breakpointCount) \(saveWord)", color: .dimGreen)
        print("")

        var options = ["Delete Adventure"]
        options.append("Rename")
        if slot.breakpointCount > 1 {
            options.append("View Saves (\(slot.breakpointCount))")
        }

        showMenu(options)

        closeHandler = { [weak self] in
            self?.showManageSavesMenu(returnTo: origin)
        }
        menuHandler = { [weak self] choice in
            guard choice >= 1 && choice <= options.count else { return }
            let picked = options[choice - 1]
            if picked == "Rename" {
                self?.renameSlot(slot: slot, returnTo: origin)
            } else if picked.hasPrefix("View Saves") {
                self?.showBreakpointList(slot: slot, returnTo: origin)
            } else if picked == "Delete Adventure" {
                self?.confirmDeleteSlot(slot: slot, returnTo: origin)
            }
        }
    }

    /// Rename a save slot: tap a suggested name, roll the dice for new
    /// ones, or type your own at the > prompt. Renames every save point in
    /// place — it used to delete each one and then re-save it, and since a
    /// deleted save's id is remembered for good (SaveGameManager's deletion
    /// record), that silently threw the whole adventure away.
    private func renameSlot(slot: SaveSlot, returnTo origin: LoadGameOrigin, onCancel: (() -> Void)? = nil, onDone: (() -> Void)? = nil) {
        let cancelAction: () -> Void = onCancel ?? { [weak self] in self?.showSlotActions(slot: slot, returnTo: origin) }
        let doneAction: () -> Void = onDone ?? { [weak self] in self?.showManageSavesMenu(returnTo: origin) }
        let suggestions = renameSuggestions(for: slot)

        clearTerminal()
        printTitle("Rename Adventure")
        print("  Now: \(slot.slotName)", color: .brightGreen)
        print("")
        printWrapped("Tap a suggestion, tap 🎲 for new ideas, or type your own name at the > prompt.", indent: 2, color: .dimGreen)
        print("")
        for (i, name) in suggestions.enumerated() {
            print("  \(i + 1). \(name)", color: .green)
        }
        print("")
        let options = suggestions + ["🎲 New Ideas", "?", "< Back"]
        promptTextWithMenu("New name:", options: options)
        closeHandler = cancelAction

        let apply: (String) -> Void = { [weak self] raw in
            guard let self = self else { return }
            let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty, !self.isReservedWord(trimmed) else {
                cancelAction()
                return
            }
            self.applySlotRename(slot: slot, to: trimmed)
            self.logEvent("Renamed adventure '\(slot.slotName)' to '\(trimmed)'", category: "SAVE")
            self.print("")
            self.print("Renamed to '\(trimmed)'", color: .brightGreen)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) { doneAction() }
        }
        menuHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= options.count else { return }
            switch options[choice - 1] {
            case "🎲 New Ideas":
                self.renameSlot(slot: slot, returnTo: origin, onCancel: onCancel, onDone: onDone)
            case "?":
                self.showInlineHelp {
                    self.printTitle("Rename — Help")
                    self.print("")
                    self.printWrapped("Tap one of the suggested names, tap 🎲 New Ideas for another batch, or type any name at the > prompt and press Return. Only the name changes — every save point in the adventure is kept.", indent: 2, color: .dimGreen)
                    self.print("")
                }
            case "< Back":
                cancelAction()
            default:
                apply(options[choice - 1])
            }
        }
        inputHandler = { newName in apply(newName) }
    }

    /// Three name ideas for a renamed adventure.
    private func renameSuggestions(for slot: SaveSlot) -> [String] {
        let leader = slot.latest.party.first.map { shortName(for: $0) } ?? "The Party"
        let adjectives = ["Brave", "Lost", "Last", "Golden", "Shadowed", "Merry", "Reckless", "Silent", "Crimson", "Wandering", "Doomed", "Lucky"]
        let nouns = ["Expedition", "Descent", "Delve", "Crusade", "Quest", "Venture", "Saga", "Gambit", "Pilgrimage", "Escapade", "Foray", "Odyssey"]
        return [
            "\(leader)'s \(nouns.randomElement()!)",
            "The \(adjectives.randomElement()!) \(nouns.randomElement()!)",
            "\(slot.latest.dungeonName) \(["Run", "Attempt", "Venture"].randomElement()!) \(Int.random(in: 2...9))",
        ].map { String($0.prefix(30)) }
    }

    /// Writes every save point of a slot back under its new name — same
    /// ids, so each file is simply overwritten in place.
    private func applySlotRename(slot: SaveSlot, to newName: String) {
        for bp in SaveGameManager.shared.listBreakpoints(slotId: slot.slotId) {
            let renamed = SaveGame(
                id: bp.id, slotId: bp.slotId, savedAt: bp.savedAt, slotName: newName,
                partyDescription: bp.partyDescription, dungeonName: bp.dungeonName, dungeonLevel: bp.dungeonLevel,
                party: bp.party, dungeon: bp.dungeon, gameState: bp.gameState,
                gameTimeMinutes: bp.gameTimeMinutes, adventureLog: bp.adventureLog,
                dmChatLog: bp.dmChatLog, torchLit: bp.torchLit, torchTurnsRemaining: bp.torchTurnsRemaining,
                partyChatLog: bp.partyChatLog, monstersSlain: bp.monstersSlain, combatsWon: bp.combatsWon,
                activeQuest: bp.activeQuest, otherQuests: bp.otherQuests, introLines: bp.introLines, mainQuest: bp.mainQuest, questHistory: bp.questHistory, noMainQuest: bp.noMainQuest, mainQuestCompleted: bp.mainQuestCompleted, questSummary: bp.questSummary
            )
            try? SaveGameManager.shared.save(renamed)
        }
        if activeSlotId == slot.slotId { activeSlotName = newName }
    }

    /// - onBack: where closeHandler/"No, Keep It" go — defaults to the
    ///   Settings-reached flow (showSlotActions); showSaveSlotManage (reached
    ///   from Continue Adventure) passes its own.
    /// - onAllDeleted: where to go if the very last save point in the slot
    ///   gets deleted (nothing left to list) — defaults to the
    ///   Settings-reached Manage Saves screen.
    private func showBreakpointList(slot: SaveSlot, returnTo origin: LoadGameOrigin, onBack: (() -> Void)? = nil, onAllDeleted: (() -> Void)? = nil) {
        let backTarget = onBack ?? { [weak self] in self?.showSlotActions(slot: slot, returnTo: origin) }
        clearTerminal()
        printSubtitle(slot.slotName)

        let breakpoints = SaveGameManager.shared.listBreakpoints(slotId: slot.slotId)
        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .medium
        dateFormatter.timeStyle = .short

        var entryLineRanges: [Range<Int>] = []
        for (i, bp) in breakpoints.enumerated() {
            let lineStart = terminalLines.count
            defer { entryLineRanges.append(lineStart..<terminalLines.count) }
            let dateStr = dateFormatter.string(from: bp.savedAt)
            let label = i == 0 ? " (latest)" : ""
            print("\(i + 1). \(dateStr)\(label)", color: .brightGreen)
            print("   \(bp.partyDescription)", color: .dimGreen)
            print("   \(bp.dungeonName) (Level \(bp.dungeonLevel))", color: .dimGreen)
            print("")
        }

        print("Select a save to delete:", color: .cyan)

        let options = breakpoints.enumerated().map { (i, bp) in
            let dateStr = dateFormatter.string(from: bp.savedAt)
            return "Delete \(i + 1). \(dateStr)"
        }

        var menuOpts = options.map { MenuOption($0) }
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        menuOpts.append(MenuOption("< Back", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)

        // Long-press a save to delete it straight away (no confirmation).
        menuLongPressHandler = { [weak self] choice in
            guard let self = self, choice >= 1, choice <= breakpoints.count else { return }
            if breakpoints.count == 1 {
                self.deleteSlotClearingActiveIfNeeded(slot.slotId)
                (onAllDeleted ?? { [weak self] in self?.showManageSavesMenu(returnTo: origin) })()
            } else {
                SaveGameManager.shared.delete(id: breakpoints[choice - 1].id)
                self.showBreakpointList(slot: slot, returnTo: origin, onBack: onBack, onAllDeleted: onAllDeleted)
            }
        }
        closeHandler = backTarget
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == menuOpts.count {
                backTarget()
                return
            }
            if choice == menuOpts.count - 1 {
                self.showInlineHelp {
                    self.printTitle("Delete a Save — Help")
                    self.print("")
                    self.printWrapped("Tap a save point to permanently delete just that one, keeping the rest of this adventure's saves.", indent: 2, color: .dimGreen)
                    self.print("")
                }
                return
            }
            guard choice >= 1 && choice <= breakpoints.count else { return }
            let bp = breakpoints[choice - 1]
            self.confirmDeleteBreakpoint(bp, slot: slot, isLast: breakpoints.count == 1, returnTo: origin, onBack: onBack, onAllDeleted: onAllDeleted)
        }

        // Tapping a save's text works like its button — still asks to confirm.
        textLongPressHandler = { [weak self] lineIndex in
            guard let idx = entryLineRanges.firstIndex(where: { $0.contains(lineIndex) }),
                  idx < breakpoints.count else { return }
            self?.confirmDeleteBreakpoint(breakpoints[idx], slot: slot, isLast: breakpoints.count == 1, returnTo: origin, onBack: onBack, onAllDeleted: onAllDeleted)
        }
    }

    private func confirmDeleteBreakpoint(_ bp: SaveGame, slot: SaveSlot, isLast: Bool, returnTo origin: LoadGameOrigin, onBack: (() -> Void)? = nil, onAllDeleted: (() -> Void)? = nil) {
        let allDeletedTarget = onAllDeleted ?? { [weak self] in self?.showManageSavesMenu(returnTo: origin) }
        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .medium
        dateFormatter.timeStyle = .short
        let dateStr = dateFormatter.string(from: bp.savedAt)

        print("")
        print("Delete save from \(dateStr)?", color: .red, bold: true)
        if isLast {
            print("This is the only save — deleting it removes the adventure.", color: .yellow)
        }
        print("")

        let opts = [MenuOption("Yes, Delete", tint: .danger), MenuOption("No, Keep It"),
                    MenuOption("?", tint: .navigation, compact: true)]
        showMenuOptions(opts)

        menuHandler = { [weak self] choice in
            if choice == 3 {
                self?.showInlineHelp {
                    self?.printTitle("Delete Save — Help")
                    self?.print("")
                    self?.printWrapped("Permanently deletes this one save point. This cannot be undone — 'No, Keep It' cancels safely.", indent: 2, color: .dimGreen)
                    self?.print("")
                }
                return
            }
            if choice == 1 {
                SaveGameManager.shared.delete(id: bp.id)
                if self?.activeSlotId == slot.slotId && isLast {
                    self?.activeSlotId = nil
                    self?.activeSlotName = nil
                }
                self?.print("")
                self?.print("Save deleted.", color: .red)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
                    let remaining = SaveGameManager.shared.listBreakpoints(slotId: slot.slotId)
                    if remaining.isEmpty {
                        allDeletedTarget()
                    } else {
                        let updated = SaveSlot(
                            slotId: slot.slotId,
                            slotName: slot.slotName,
                            latest: remaining.first!,
                            breakpointCount: remaining.count
                        )
                        self?.showBreakpointList(slot: updated, returnTo: origin, onBack: onBack, onAllDeleted: onAllDeleted)
                    }
                }
            } else {
                // Refresh slot in case something changed
                let remaining = SaveGameManager.shared.listBreakpoints(slotId: slot.slotId)
                let updated = SaveSlot(
                    slotId: slot.slotId,
                    slotName: slot.slotName,
                    latest: remaining.first ?? slot.latest,
                    breakpointCount: remaining.count
                )
                self?.showBreakpointList(slot: updated, returnTo: origin, onBack: onBack, onAllDeleted: onAllDeleted)
            }
        }
    }

    /// - onCancel/onDone: see renameSlot's doc — same defaulting pattern so
    ///   the Continue Adventure-reached flow returns there instead of to
    ///   the unrelated Settings-based Manage Saves screen.
    private func confirmDeleteSlot(slot: SaveSlot, returnTo origin: LoadGameOrigin, onCancel: (() -> Void)? = nil, onDone: (() -> Void)? = nil) {
        let cancelAction: () -> Void = onCancel ?? { [weak self] in self?.showSlotActions(slot: slot, returnTo: origin) }
        let doneAction: () -> Void = onDone ?? { [weak self] in self?.showManageSavesMenu(returnTo: origin) }

        print("")
        let saveWord = slot.breakpointCount == 1 ? "save" : "saves"
        print("Delete '\(slot.slotName)'?", color: .red, bold: true)
        print("This will delete all \(slot.breakpointCount) \(saveWord) for this adventure.", color: .yellow)
        print("This cannot be undone.", color: .yellow)
        print("")

        let opts = [MenuOption("Yes, Delete All", tint: .danger), MenuOption("No, Keep It"),
                    MenuOption("Tell Me About It"),
                    MenuOption("?", tint: .navigation, compact: true)]
        showMenuOptions(opts)
        closeHandler = cancelAction

        menuHandler = { [weak self] choice in
            if choice == 1 {
                self?.deleteSlotClearingActiveIfNeeded(slot.slotId)
                self?.print("")
                self?.print("Adventure deleted.", color: .red)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                    doneAction()
                }
            } else if choice == 3 {
                // A last look at what's about to go — then back here.
                if let entry = HallOfFameManager.shared.listEntries().first(where: { $0.saveGameId == slot.latest.id }) {
                    self?.showAdventureTale(AdventureTaleData(hof: entry), onBack: cancelAction)
                } else {
                    self?.showAdventureTale(AdventureTaleData(inProgress: slot.latest), onBack: cancelAction)
                }
            } else if choice == 4 {
                self?.showInlineHelp {
                    self?.printTitle("Delete Adventure — Help")
                    self?.print("")
                    self?.printWrapped("Permanently deletes every save point for this adventure. This cannot be undone — 'No, Keep It' cancels safely. (In a hurry? Long-press Delete Adventure to skip this step.)", indent: 2, color: .dimGreen)
                    self?.print("")
                }
            } else {
                cancelAction()
            }
        }
    }

    /// If the current room has an active encounter, retreat to the nearest safe room
    private func ensureSafeRoom() {
        guard let dungeon = dungeon else { return }
        var visited = Set<Int>()
        var queue = [dungeon.currentRoomId]
        visited.insert(dungeon.currentRoomId)

        while let roomId = queue.first {
            queue.removeFirst()
            guard let room = dungeon.rooms[roomId] else { continue }
            if room.encounter == nil || room.cleared {
                // This room is safe — move here
                if roomId != dungeon.currentRoomId {
                    dungeon.previousRoomId = dungeon.currentRoomId
                    dungeon.currentRoomId = roomId
                }
                return
            }
            // Try adjacent rooms
            for (_, nextId) in room.exits where !visited.contains(nextId) {
                visited.insert(nextId)
                queue.append(nextId)
            }
        }
        // If no safe room found, just clear the current room's encounter
        dungeon.rooms[dungeon.currentRoomId]?.encounter = nil
        dungeon.rooms[dungeon.currentRoomId]?.cleared = true
    }

    private func loadGame(_ save: SaveGame) {
        party = save.party
        // A save can predate the Robot Prefix setting, or the setting can
        // have changed since it was made — re-sync every loaded character's
        // "R. " prefix against isComputerControlled and the current setting.
        for char in party { char.syncRobotPrefix() }
        dungeon = save.dungeon
        currentCombat = nil
        gameState = .exploring
        gameTimeMinutes = save.gameTimeMinutes
        adventureLog = save.adventureLog
        monstersSlain = save.monstersSlain
        combatsWon = save.combatsWon
        activeQuest = save.activeQuest
        otherQuests = save.otherQuests ?? []
        adventureIntroLines = save.introLines ?? []
        mainQuest = save.mainQuest
        questHistory = save.questHistory ?? []
        noMainQuest = save.noMainQuest ?? false
        mainQuestCompleted = save.mainQuestCompleted ?? false
        // Restore torch state — if not saved, auto-light if anyone has a torch
        if let savedTorchLit = save.torchLit {
            torchLit = savedTorchLit
        } else {
            torchLit = partyHasTorch()
        }
        if let savedTurns = save.torchTurnsRemaining, savedTurns > 0 {
            torchTurnsRemaining = savedTurns
        } else if torchLit {
            torchTurnsRemaining = Item.torchFullLife
        } else {
            torchTurnsRemaining = 0
        }
        partyChatLog = save.partyChatLog ?? []

        // Reconnect active torch — find a torch with matching or closest life
        if torchLit, let (holder, torch) = findBestTorch() {
            activeTorchId = torch.id
            torchHolderId = holder.id
        } else {
            activeTorchId = nil
            torchHolderId = nil
        }

        // Restore DM chat log and seed AI conversation history
        if let savedChat = save.dmChatLog {
            dmChatLog = savedChat.map { (isUser: $0.isUser, text: $0.text) }
            DMEngine.shared.restoreHistory(from: savedChat)
        } else {
            dmChatLog = []
            DMEngine.shared.clearHistory()
        }

        // Track the loaded slot for future saves/autosaves
        activeSlotId = save.slotId
        activeSlotName = save.slotName

        // Reroll encounters so monsters are different each load
        dungeon?.rerollEncounters()

        // Safety: if loading into a room with combat, retreat to a safe room
        ensureSafeRoom()

        logEvent("Game loaded: \(save.slotName)", category: "SYSTEM")
        if self.musicEnabled { SoundManager.shared.startMusic(.exploration, preference: self.explorationMelodyChoice) }

        // The Opening Tale again (skippable), then the story so far — and
        // only then the play screen.
        pendingDMRemarks = ensureUniqueNames()
        showResumeStory()
    }

    // These three screens (reached from the Save menu's "Quit+Save"/
    // "Quit-Save", and the X-icon's just-saved shortcut) all say, in their
    // own on-screen text, that they take you to the main menu — but used
    // to call performQuit() (exit(0), closing the app entirely), directly
    // contradicting that promise. Fixed to actually do what they say:
    // "quit" here means leave this adventure for the app's main menu, same
    // as confirmExitToMainMenu's "Quit Without Saving" — never closes the
    // app. The only action that still does that is the main menu's own
    // Quit (see quitApp()/performQuit()).
    private func confirmQuitAndSave(slotId: UUID, slotName: String) {
        clearTerminal()
        printTitle("Save & Quit")
        print("")
        print("Your adventure will be saved and", color: .yellow)
        print("the app will close.", color: .yellow)
        print("")
        print("Save: \(slotName)", color: .dimGreen)
        print("")

        showMenu(["Yes, Save & Quit", "No, Keep Playing"], defaultIndex: 1)
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            if choice == 1 {
                self.performSave(slotId: slotId, slotName: slotName)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                    self.performQuit()
                }
            } else {
                self.showExplorationView()
            }
        }
    }

    private func confirmQuitAfterRecentSave(slotId: UUID, slotName: String) {
        clearTerminal()
        printTitle("Leave or Quit?")
        print("")
        print("Game was saved moments ago.", color: .green)
        print("  \(slotName)", color: .dimGreen)
        print("")
        printWrapped("Main Menu stays in the app. Quit App closes it entirely.", indent: 2, color: .dimGreen)
        print("")

        // "Main Menu" (stay in the app) is the default here — you just
        // tapped the Leave/close-icon action, so heading to the Main Menu
        // is the most likely intent, not quitting the app or continuing.
        showMenu(["Quit App", "Main Menu", "Keep Playing", "Save Again"], defaultIndex: 1)
        closeHandler = { [weak self] in self?.showExplorationView() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            switch choice {
            case 1: self.performQuit()
            case 2: self.resetGame()
            case 4: self.showSaveMenu()
            default: self.showExplorationView()
            }
        }
    }

    private func confirmQuitWithoutSaving() {
        clearTerminal()
        printTitle("Quit Without Saving?")
        printWrapped("Unsaved progress will be lost, and the app will close.", indent: 2, color: .red)
        print("")

        showMenu(["Yes, Quit", "No, Stay"])
        menuHandler = { [weak self] choice in
            if choice == 1 {
                self?.performQuit()
            } else {
                self?.showExplorationView()
            }
        }
    }

    func confirmExitToMainMenu() {
        clearTerminal()
        printTitle("Leave Adventure")
        printWrapped("Leave returns to the Main Menu — the app stays open. Quit closes the app.", indent: 2, color: .cyan)
        print("")
        // One short block per button, in the same order as the buttons.
        let choices: [(String, String)] = [
            ("SAVE & LEAVE", "Save this adventure, then go to the Main Menu."),
            ("LEAVE WITHOUT SAVING", "Go to the Main Menu. Anything since your last save is lost."),
            ("SAVE & QUIT", "Save this adventure, then close the app."),
            ("QUIT WITHOUT SAVING", "Close the app. Anything since your last save is lost."),
        ]
        for (label, detail) in choices {
            print("  \(label)", color: .brightGreen, bold: true)
            printWrapped(detail, indent: 4, color: .dimGreen)
            print("")
        }

        // "Leave" is the one option here that does NOT call performQuit() —
        // it stays in the app (resetGame() → showMainMenu()). Both "Quit"
        // options close the app via performQuit() — see the note on
        // performQuit() for where the actual app-exit action lives.
        var menuOpts = [
            MenuOption("Save & Leave", isDefault: true),
            MenuOption("Leave Without Saving", tint: .danger),
            MenuOption("Save & Quit"),
            MenuOption("Quit Without Saving", tint: .danger),
            MenuOption("< Back"),
        ]
        menuOpts.append(MenuOption("?", tint: .navigation, compact: true))
        showMenuOptions(menuOpts)
        closeHandler = { [weak self] in self?.showExplorationView() }
        menuHandler = { [weak self] choice in
            guard let self = self else { return }
            let text = menuOpts[choice - 1].text
            switch text {
            case "Save & Leave":
                self.performQuickSave()
                self.resetGame()
            case "Leave Without Saving":
                self.resetGame()
            case "Save & Quit":
                self.performQuickSave()
                self.performQuit()
            case "Quit Without Saving":
                self.performQuit()
            case "< Back":
                self.showExplorationView()
            case "?":
                self.showReturnToMenuHelp()
            default: break
            }
        }
    }

    private func showReturnToMenuHelp() {
        showInlineHelp {
            self.printTitle("Leave Adventure — Help")
            self.print("")

            self.print("  LEAVE vs QUIT", color: .cyan, bold: true)
            self.printWrapped("Leave stays in the app — you land back on the Main Menu and can start or continue any adventure. Quit closes the app completely.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  SAVE & LEAVE", color: .cyan, bold: true)
            self.printWrapped("Saves your game to the current slot, then returns to the Main Menu with the app still open.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  LEAVE WITHOUT SAVING", color: .cyan, bold: true)
            self.printWrapped("Returns to the Main Menu, app stays open, but discards anything since your last save.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  SAVE & QUIT", color: .cyan, bold: true)
            self.printWrapped("Saves your game to the current slot, then closes the app. You can continue this adventure later from the main menu.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  QUIT WITHOUT SAVING", color: .cyan, bold: true)
            self.printWrapped("Also closes the app, but discards anything since your last save.", indent: 2, color: .dimGreen)
            self.print("")

            self.print("  < BACK", color: .cyan, bold: true)
            self.printWrapped("Go back to exploring the dungeon.", indent: 2, color: .dimGreen)
            self.print("")
        }
    }

    /// Fallback exit for victory/defeat/combat when closeHandler has been lost
    func emergencyExit() {
        if gameState == .victory || gameState == .gameOver {
            resetGame()
        } else if gameState == .combat {
            // Return to exploration if possible, otherwise reset
            if dungeon != nil && !party.isEmpty {
                currentCombat = nil
                gameState = .exploring
                showExplorationView()
            } else {
                resetGame()
            }
        } else {
            resetGame()
        }
    }

    func resetGame() {
        party = []
        dungeon = nil
        currentCombat = nil
        gameTimeMinutes = 360
        adventureLog = []
        monstersSlain = 0
        combatsWon = 0
        activeQuest = nil
        otherQuests = []
        adventureIntroLines = []
        mainQuest = nil
        questHistory = []
        noMainQuest = false
        mainQuestCompleted = false
        storyScreenActive = false
        activeSlotId = nil
        activeSlotName = nil
        torchLit = false
        torchTurnsRemaining = 0
        activeTorchId = nil
        torchHolderId = nil
        difficultyScale = 1.0
        showMainMenu()
    }

    func quitApp() {
        // If there's an active game that could be saved, offer to save first
        let hasUnsavedGame = dungeon != nil && !party.isEmpty && !isMultiplayer
        if hasUnsavedGame {
            clearTerminal()
            printTitle("Quit")
            print("You have an active adventure.", color: .yellow)
            print("Would you like to save before", color: .yellow)
            print("leaving?", color: .yellow)
            print("")

            showMenu(["Save, Then Quit", "Quit Without Saving", "?", "< Back"])
            menuHandler = { [weak self] choice in
                guard let self = self else { return }
                switch choice {
                case 1:
                    self.showSaveMenu()
                case 2:
                    self.performQuit()
                case 3:
                    self.showInlineHelp {
                        self.printTitle("Quit — Help")
                        self.print("")
                        self.print("  SAVE, THEN QUIT", color: .cyan, bold: true)
                        self.printWrapped("Takes you to the Save menu first — pick a slot, then the app closes once it's saved.", indent: 2, color: .dimGreen)
                        self.print("")
                        self.print("  QUIT WITHOUT SAVING", color: .cyan, bold: true)
                        self.printWrapped("Closes the app immediately WITHOUT saving. Today's progress on this adventure is lost.", indent: 2, color: .yellow)
                        self.print("")
                        self.print("  < BACK", color: .cyan, bold: true)
                        self.printWrapped("Cancels — returns to the Main Menu, app stays open.", indent: 2, color: .dimGreen)
                    }
                default:
                    self.showMainMenu()
                }
            }
            return
        }

        performQuit()
    }

    /// Timer for twinkling farewell stars
    private var starTwinkleTimer: Timer?
    /// Indices into terminalLines that hold star rows
    private var starLineIndices: [Int] = []

    private func randomStarLine(width: Int) -> String {
        let stars: [String] = ["·", "✦", "✧", "★", "☆", "*", "°", "∙"]
        var chars = Array(repeating: " ", count: width)
        let numStars = Int.random(in: 3...6)
        for _ in 0..<numStars {
            let pos = Int.random(in: 0..<width)
            chars[pos] = stars.randomElement()!
        }
        return chars.joined()
    }

    private func performQuit() {
        SoundManager.shared.stopMusic()
        SoundManager.shared.playQuit()
        clearTerminal()

        let w = 34

        // Star field (top)
        var starIndices: [Int] = []
        for _ in 0..<4 {
            starIndices.append(terminalLines.count)
            print(randomStarLine(width: w), color: .dimGreen)
        }
        print("")

        let farewells = [
            "May your dice roll true, adventurer.",
            "The dungeon will remember your name.",
            "Until we meet again at the tavern...",
            "Your legend grows with each adventure.",
            "The road goes ever on. Farewell.",
        ]

        // Witty follow-up teases (shown ~40% of the time)
        let teases: [String] = [
            "... probably.",
            "... or was it all a dream?",
            "... the monsters hope so, anyway.",
            "... the goblins are still talking about you.",
            "... though the mimics won't miss you.",
            "... the tavern keeper kept your tab open.",
            "... your torch just went out.",
            "... that chest was definitely not a mimic. Definitely.",
        ]

        // Character-specific teases (if we have a party)
        var personalTeases: [String] = []
        if !party.isEmpty {
            if let hero = party.first {
                personalTeases.append("... \(hero.name) waves goodbye.")
                if hero.currentHP < hero.maxHP {
                    personalTeases.append("... \(hero.name) could really use a long rest.")
                }
            }
            if party.count > 1 {
                let random = party.randomElement()!
                personalTeases.append("... \(random.name) mutters something about loot shares.")
            }
        }

        let farewell = farewells.randomElement()!
        print("  Thanks for playing!", color: .brightGreen, bold: true)
        print("")
        print("  \(farewell)", color: .dimGreen)

        // ~40% chance of a witty follow-up
        let allTeases = teases + personalTeases
        if Int.random(in: 0..<5) < 2, let tease = allTeases.randomElement() {
            print("  \(tease)", color: .gray)
        }
        print("")

        // Star field (bottom)
        for _ in 0..<3 {
            starIndices.append(terminalLines.count)
            print(randomStarLine(width: w), color: .dimGreen)
        }
        print("")
        print("  Goodbye.", color: .dimGreen)
        print("")

        // Twinkle animation — update star lines every 400ms
        self.starLineIndices = starIndices
        starTwinkleTimer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in
            guard let self = self else { return }
            DispatchQueue.main.async {
                for idx in self.starLineIndices {
                    if idx < self.terminalLines.count {
                        self.terminalLines[idx].text = self.randomStarLine(width: w)
                    }
                }
            }
        }

        // Exit the app after the farewell tune finishes
        DispatchQueue.main.asyncAfter(deadline: .now() + 5.0) { [weak self] in
            self?.starTwinkleTimer?.invalidate()
            exit(0)
        }
    }

